bool FilterAndFind(const std::vector<std::vector<Point>>& contours) {
    int validContours = 0;
    for (const auto& contour : contours) {
        double area = contourArea(contour);
        if (area > MIN_AREA_THRESHOLD && area < MAX_AREA_THRESHOLD) {
            // Calculate the bounding box of the contour
            cv::Rect boundingBox = cv::boundingRect(contour);
            double aspectRatio = static_cast<double>(boundingBox.width) / boundingBox.height;
            // Check if the aspect ratio of the bounding box meets the criteria for a valid object
            if (aspectRatio >= MIN_ASPECT_RATIO && aspectRatio <= MAX_ASPECT_RATIO) {
                // Increment the count of valid contours
                validContours++;
            }
        }
    }
    // If there are more than MIN_VALID_CONTOURS valid contours, consider the objects as valid
    return validContours > MIN_VALID_CONTOURS;
}

