class Position {
private:
    double xpos;
    double ypos;
    double theta;
public:
    // Constructor to initialize the position
    Position() : xpos(0), ypos(0), theta(0) {}
    // Method to set x-coordinate
    void setX(double x) {
        xpos = x;
    }
    // Method to get x-coordinate
    double getX() const {
        return xpos;
    }
    // Method to set y-coordinate
    void setY(double y) {
        ypos = y;
    }
    // Method to get y-coordinate
    double getY() const {
        return ypos;
    }
    // Method to set angle
    void setTheta(double angle) {
        theta = angle;
    }
    // Method to get angle
    double getTheta() const {
        return theta;
    }
    // Method to move the position by a given distance in a given direction
    void move(double distance, double direction) {
        xpos += distance * cos(direction);
        ypos += distance * sin(direction);
    }
};
int main() {
    Position p;
    std::cout << "Initial position: (" << p.getX() << ", " << p.getY() << ")" << std::endl;
    p.move(5, M_PI / 4); // Move 5 units at 45 degrees
    std::cout << "New position: (" << p.getX() << ", " << p.getY() << ")" << std::endl;
    return 0;
}

