// Define the ordered logistic lpmf function
template <typename T_y, typename T_loc, typename T_cut>
auto ordered_logistic_lpmf(const T_y& y, const T_loc& lam_d, const T_cut& c_fv) {
  // Calculate the log probability mass function value
  auto out = ordered_logistic_lpmf(y, lam_d, c_fv);
  out.d_.grad();
  // Validate the log probability mass function value and its gradient
  EXPECT_FLOAT_EQ(out.val_.val(), -8.21855481819114);
  EXPECT_FLOAT_EQ(out.d_.val(), 2.32912026425027);
  // Calculate the gradients for the cutpoints
  EXPECT_FLOAT_EQ(c_fv[0].d_.adj(), -0.209379786457621);
  EXPECT_FLOAT_EQ(c_fv[1].d_.adj(), 1.33112093047159);
  EXPECT_FLOAT_EQ(c_fv[2].d_.adj(), 1.20737912023631);
  // Calculate the gradients using the fvar type
  fvar<fvar<var>> out_ffv = ordered_logistic_lpmf(y, lam_ffv, c_d);
  out_ffv.d_.val_.grad();
}

