#include <eosiolib/asset.hpp>
#include <eosiolib/eosio.hpp>
#include <eosiolib/time.hpp>
using namespace eosio;
class [[eosio::contract]] MyToken : public contract {
public:
  using contract::contract;
  [[eosio::action]]
  void create(name issuer, asset maximum_supply) {
    require_auth(_self);
    auto sym = maximum_supply.symbol;
    check(sym.is_valid(), "invalid symbol name");
    check(maximum_supply.is_valid(), "invalid supply");
    check(maximum_supply.amount > 0, "max-supply must be positive");
    stats statstable(_self, sym.code().raw());
    auto existing = statstable.find(sym.code().raw());
    check(existing == statstable.end(), "token with symbol already exists");
    statstable.emplace(_self, [&](auto& s) {
      s.supply.symbol = maximum_supply.symbol;
      s.max_supply = maximum_supply;
      s.issuer = issuer;
    });
  }
  [[eosio::action]]
  void issue(name to, asset quantity, std::string memo) {
    auto sym = quantity.symbol;
    check(sym.is_valid(), "invalid symbol name");
    check(memo.size() <= 256, "memo has more than 256 bytes");
    stats statstable(_self, sym.code().raw());
    auto existing = statstable.find(sym.code().raw());
    check(existing != statstable.end(), "token with symbol does not exist");
    const auto& st = *existing;
    require_auth(st.issuer);
    check(quantity.is_valid(), "invalid quantity");
    check(quantity.amount > 0, "must issue positive quantity");
    check(quantity.symbol == st.supply.symbol, "symbol precision mismatch");
    check(quantity.amount <= st.max_supply.amount - st.supply.amount, "quantity exceeds available supply");
    statstable.modify(st, same_payer, [&](auto& s) {
      s.supply += quantity;
    });
    add_balance(st.issuer, quantity, st.issuer);
    if (to != st.issuer) {
      SEND_INLINE_ACTION(*this, transfer, {st.issuer, "active"_n}, {st.issuer, to, quantity, memo});
    }
  }
  [[eosio::action]]
  void transfer(name from, name to, asset quantity, std::string memo) {
    check(from != to, "cannot transfer to self");
    require_auth(from);
    check(is_account(to), "to account does not exist");
    auto sym = quantity.symbol.code();
    stats statstable(_self, sym.raw());
    const auto& st = statstable.get(sym.raw());
    require_recipient(from);
    require_recipient(to);
    check(quantity.is_valid(), "invalid quantity");
    check(quantity.amount > 0, "must transfer positive quantity");
    check(memo.size() <= 256, "memo has more than 256 bytes");
    sub_balance(from, quantity);
    add_balance(to, quantity, from);
  }
  [[eosio::action]]
  void balance(name account) {
    require_auth(account);
    accounts accountstable(_self, account.value);
    const auto& ac = accountstable.get(account.value);
    print("Balance: ", ac.balance);
  }
private:
  struct [[eosio::table]] account {
    asset balance;
    uint64_t primary_key() const { return balance.symbol.code().raw(); }
  };
  struct [[eosio::table]] currency_stats {
    asset supply;
    asset max_supply;
    name issuer;
    uint64_t primary_key() const { return supply.symbol.code().raw(); }
  };
  typedef multi_index<"accounts"_n, account> accounts;
  typedef multi_index<"stat"_n, currency_stats> stats;
  void sub_balance(name owner, asset value) {
    accounts from_acnts(_self, owner.value);
    const auto& from = from_acnts.get(value.symbol.code().raw(), "no balance object found");
    check(from.balance.amount >= value.amount, "overdrawn balance");
    if (from.balance.amount == value.amount) {
      from_acnts.erase(from);
    } else {
      from_acnts.modify(from, owner, [&](auto& a) {
        a.balance -= value;
      });
    }
  }
  void add_balance(name owner, asset value, name ram_payer) {
    accounts to_acnts(_self, owner.value);
    auto to = to_acnts.find(value.symbol.code().raw());
    if (to == to_acnts.end()) {
      to_acnts.emplace(ram_payer, [&](auto& a) {
        a.balance = value;
      });
    } else {
      to_acnts.modify(to, same_payer, [&](auto& a) {
        a.balance += value;
      });
    }
  }
};
EOSIO_DISPATCH(MyToken, (create)(issue)(transfer)(balance))

