#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <bitset>
std::vector<std::string> read2BitFile(const std::string& fileName) {
    std::ifstream file(fileName, std::ios::binary);
    if (!file.is_open()) {
        throw std::runtime_error("Failed to open file: " + fileName);
    }
    // Read header
    int sequenceCount;
    file.read(reinterpret_cast<char*>(&sequenceCount), sizeof(sequenceCount));
    std::vector<std::string> sequenceNames(sequenceCount);
    for (int i = 0; i < sequenceCount; ++i) {
        int nameLength;
        file.read(reinterpret_cast<char*>(&nameLength), sizeof(nameLength));
        sequenceNames[i].resize(nameLength);
        file.read(&sequenceNames[i][0], nameLength);
    }
    // Read encoded sequences
    std::vector<std::string> decodedSequences;
    for (const auto & seqName : sequenceNames) {
        int sequenceLength;
        file.read(reinterpret_cast<char*>(&sequenceLength), sizeof(sequenceLength));
        std::string encodedSequence;
        encodedSequence.resize(sequenceLength);
        file.read(&encodedSequence[0], sequenceLength);
        // Decode the 2-bit encoded sequence
        std::string decodedSequence;
        for (char c : encodedSequence) {
            std::bitset<2> bits(c);
            decodedSequence += "ACGT"[bits.to_ulong()];
        }
        decodedSequences.push_back(decodedSequence);
    }
    file.close();
    return decodedSequences;
}

#include <iostream>
bool isPowerOfTwo(int number) {
    if (number <= 0) {
        return false;  // 0 and negative numbers are not powers of two
    }
    return (number & (number - 1)) == 0;  // A power of two has only one bit set in its binary representation
}
int main() {
    int input;
    std::cout << "Enter a positive integer: ";
    std::cin >> input;
    if (isPowerOfTwo(input)) {
        std::cout << "The given number is a power of two" << std::endl;
    } else {
        std::cout << "The given number is not a power of two" << std::endl;
    }
    return 0;
}

#include <iostream>
#include <fstream>
#include <filesystem>
class CustomLog {
private:
    std::ostream& output;
    std::string before;
public:
    CustomLog(std::ostream& out, const std::string& filePath, const std::string& messageType) : output(out) {
        before = '[' + std::filesystem::path(filePath).filename().string() + "] " + messageType + '\t';
    }
    template <typename T>
    std::ostream& operator<<(T other) {
        return output << before << other;
    }
};
int main() {
    // Example usage
    std::ofstream fileStream("log.txt");
    CustomLog fileLog(fileStream, "example.cpp", "INFO");
    fileLog << "This is an informational message." << std::endl;
    CustomLog consoleLog(std::cout, "example.cpp", "ERROR");
    consoleLog << "An error occurred!" << std::endl;
    return 0;
}

#include <SFML/Graphics.hpp>
class Camera2D {
private:
    sf::RenderTargetPtr m_pRenderTarget;
    sf::View m_view;
public:
    Camera2D(sf::RenderTargetPtr renderTarget, float frustrumWidth, float frustrumHeight)
        : m_pRenderTarget(renderTarget) {
        m_view = m_pRenderTarget->getView();
        m_view.setViewport(sf::FloatRect(0, 0, frustrumWidth, frustrumHeight));
        resize(m_pRenderTarget->getSize());
        updateTarget();
    }
    void updateTarget() {
        m_pRenderTarget->setView(m_view);
    }
    void resize(sf::Vector2u size) {
        m_view.setSize(static_cast<float>(size.x), static_cast<float>(size.y));
    }
};

fs::path DirectoryUtils::searchResourceDirectory(const fs::path& workingDirectory) {
    // Start the search from the working directory
    fs::path currentDirectory = workingDirectory;
    // Traverse up the directory structure until the resource directory is found
    while (!currentDirectory.empty()) {
        fs::path resourceDirectory = currentDirectory / "resources";
        if (fs::exists(resourceDirectory) && fs::is_directory(resourceDirectory)) {
            return resourceDirectory;
        }
        currentDirectory = currentDirectory.parent_path();
    }
    // If the resource directory is not found, return an empty path
    return fs::path();
}

