        for(int j=1; j<=n; j++)
            cin >> a[i][j];

    int x = 0;
    int v[n*n+1];
    for(int i=1; i<=n/2; i++) {
        x++;
        v[x] = a[i][n/2-i+1];
    }
    for(int i=1; i<=n/2; i++) {
        x++;
        v[x] = a[n/2+i][i];
    }
    for(int i=1; i<=n/2; i++) {
        x++;
        v[x] = a[n-i+1][n/2+i];
    }
    for(int i=1; i<=n/2; i++) {
        x++;
        v[x] = a[n/2-i+1][n-i+1];
    }

    cin >> k;
    for(int i=k+1; i<=x; i++)
        cout << v[i] << " ";
    for(int i=1; i<=k; i++)
        cout << v[i] << " ";

