#include <iostream>
// Define the maximum number of threads
#define LZ5MT_THREAD_MAX 8
class CEncoder {
private:
    UInt32 _numThreads;
public:
    // Constructor
    CEncoder() : _numThreads(1) {}
    // Method to set the number of threads
    STDMETHODIMP SetNumberOfThreads(UInt32 numThreads) {
        const UInt32 kNumThreadsMax = LZ5MT_THREAD_MAX;
        if (numThreads < 1) {
            numThreads = 1;
        }
        if (numThreads > kNumThreadsMax) {
            numThreads = kNumThreadsMax;
        }
        _numThreads = numThreads;
        return S_OK;
    }
    // Getter method for number of threads
    UInt32 GetNumberOfThreads() {
        return _numThreads;
    }
};
int main() {
    CEncoder encoder;
    encoder.SetNumberOfThreads(5);
    std::cout << "Number of threads set: " << encoder.GetNumberOfThreads() << std::endl;  // Output: Number of threads set: 5
    encoder.SetNumberOfThreads(10);
    std::cout << "Number of threads set: " << encoder.GetNumberOfThreads() << std::endl;  // Output: Number of threads set: 8 (maximum allowed)
    encoder.SetNumberOfThreads(0);
    std::cout << "Number of threads set: " << encoder.GetNumberOfThreads() << std::endl;  // Output: Number of threads set: 1 (minimum allowed)
    return 0;
}

