class opp_runtime_error : public std::runtime_error {
public:
    opp_runtime_error(const char *messagefmt, ...) : std::runtime_error("") {
        va_list args;
        va_start(args, messagefmt);
        char buffer[256];  // Assuming a maximum message length of 255 characters
        vsnprintf(buffer, sizeof(buffer), messagefmt, args);
        va_end(args);
        formatted_message = buffer;
    }
    const char* what() const noexcept override {
        return formatted_message.c_str();
    }
private:
    std::string formatted_message;
};
int main() {
    try {
        throw opp_runtime_error("An error occurred: %d %s", 404, "Not Found");
    }
    catch (const std::exception& e) {
        printf("Exception: %s\n", e.what());
    }
    return 0;
}

