    if (userIt != users.end()) {
        auto& user = userIt->second;
        auto dirPermIt = user.directoryPermissions.find(request.fid);
        if (dirPermIt != user.directoryPermissions.end() && dirPermIt->second == OpenMode::Write) {
            // User has write permission, create the file
