#include <string>
std::string reverseFoldString(const std::string& input, int n) {
    std::string reversed = input;
    std::reverse(reversed.begin(), reversed.end());  // Reverse the input string
    std::string folded;
    for (size_t i = 0; i < reversed.length(); i += n) {
        folded += reversed.substr(i, n);  // Append the substring of length n
        if (i + n < reversed.length()) {
            folded += ",";  // Insert the delimiter after every n characters
        }
    }
    return folded;
}

