        ids[at] = low[at] = id++;
        for (int to : graph[at]) {
            if (ids[to] == -1) {
                dfs(to);
                low[at] = std::min(low[at], low[to]);
            } else if (onStack[to]) {
                low[at] = std::min(low[at], ids[to]);
            }
        }
        if (ids[at] == low[at]) {
            std::vector<int> scc;
