constexpr Color BLACK{0, 0, 0, 255}; // Represents the color black
constexpr Color RED{255, 0, 0, 255};  // Represents the color red
Color blendColors(const Color& color1, const Color& color2, float t) {
    // Blending operation for each color component
    unsigned int blended_red = static_cast<unsigned int>((1 - t) * color1.red + t * color2.red);
    unsigned int blended_green = static_cast<unsigned int>((1 - t) * color1.green + t * color2.green);
    unsigned int blended_blue = static_cast<unsigned int>((1 - t) * color1.blue + t * color2.blue);

    // Return the blended color with alpha component from color1
    return Color(blended_red, blended_green, blended_blue, color1.alpha);
}
