std::vector<std::string> extractNestedElements(const std::string& namespaceStr) {
    std::vector<std::string> nestedElements;
    // Regular expression to match nested namespaces and classes
    std::regex nestedRegex("\\b" + namespaceStr + "::(\\w+)");
    // Sample code snippet representing the namespace and its nested elements
    std::string codeSnippet = R"(
        namespace osquery {
            namespace detail {
                class Logger {
                    // Class implementation
                };
            }
            class Table {
                // Class implementation
            };
            namespace util {
                class Converter {
                    // Class implementation
                };
            }
        }
    )";
    // Search for nested namespaces and classes using regex
    std::smatch match;
    std::string::const_iterator searchStart(codeSnippet.cbegin());
    while (std::regex_search(searchStart, codeSnippet.cend(), match, nestedRegex)) {
        nestedElements.push_back(match[1]);
        searchStart = match.suffix().first;
    }
    return nestedElements;
}
