void ParticleEmitter::updateParticles(float dt)
{
    for (auto it = particles.begin(); it != particles.end();)
    {
        it->x += it->vx * dt;  // Update position based on velocity
        it->y += it->vy * dt;
        it->lifetime -= dt;  // Reduce remaining lifetime
        if (it->lifetime <= 0.0f)
        {
            it = particles.erase(it);  // Remove particle if lifetime has expired
        }
        else
        {
            ++it;
        }
    }
}

void waterfill(const Grid& grid, int source_x, int source_y, Grid& water_grid) {
    // Initialize a queue for BFS traversal
    std::queue<std::pair<int, int>> q;
    q.push({source_x, source_y});
    // Mark the source tile as filled with water
    water_grid[source_x][source_y] = Filled;
    // Define the possible directions for spreading water
    const std::vector<std::pair<int, int>> directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    // Perform BFS traversal to spread water to neighboring tiles
    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop();
        // Check and spread water to neighboring tiles
        for (const auto& dir : directions) {
            int new_x = x + dir.first;
            int new_y = y + dir.second;
            // Check if the neighboring tile is within bounds and not already filled with water
            if (new_x >= 0 && new_x < grid.size() && new_y >= 0 && new_y < grid[0].size() &&
                water_grid[new_x][new_y] != Filled) {
                // Check if the neighboring tile satisfies the specific condition for waterfill
                if (TileRoutines::waterfill_touch_right(grid[x][y], grid[new_x][new_y], tile)) {
                    // Mark the neighboring tile as filled with water and add it to the queue for further spreading
                    water_grid[new_x][new_y] = Filled;
                    q.push({new_x, new_y});
                }
            }
        }
    }
}

