#include "Components/Lights/LightInterface.hpp"
#include <vector>
#include <algorithm>
namespace Components::Lights {
    class PointLight : public LightInterface {
    public:
        PointLight(const glm::vec3& position, const glm::vec3& color)
            : position_(position), color_(color) {}
        virtual glm::vec3 CalculateIllumination(const glm::vec3& point) const override {
            glm::vec3 direction = position_ - point;
            float distance = glm::length(direction);
            direction = glm::normalize(direction);
            float attenuation = 1.0f / (distance * distance);
            return color_ * attenuation * std::max(glm::dot(glm::vec3(0, 0, 1), direction), 0.0f);
        }
    private:
        glm::vec3 position_;
        glm::vec3 color_;
    };
    class DirectionalLight : public LightInterface {
    public:
        DirectionalLight(const glm::vec3& direction, const glm::vec3& color)
            : direction_(direction), color_(color) {}
        virtual glm::vec3 CalculateIllumination(const glm::vec3& point) const override {
            return color_ * std::max(glm::dot(glm::vec3(0, 0, 1), -direction_), 0.0f);
        }
    private:
        glm::vec3 direction_;
        glm::vec3 color_;
    };
    glm::vec3 CalculateIllumination(const glm::vec3& point, const std::vector<std::shared_ptr<LightInterface>>& lights) {
        glm::vec3 totalIllumination(0.0f);
        for (const auto& light : lights) {
            totalIllumination += light->CalculateIllumination(point);
        }
        return totalIllumination;
    }
}

