template <typename T>
struct codec_map {
    static bool decode(pb_istream_t *stream, const pb_field_t *field, void **arg) {
        auto *mapping = static_cast<std::map<typename T::KeyType, typename T::ValueType> *>(*arg);
        T map_entry;
        // Read the protocol buffer message from the input stream
        if (!pb_decode(stream, field, &map_entry)) {
            return false; // Return false if decoding failed
        }
        // Populate the map with the decoded key-value pairs
        mapping->insert(std::make_pair(map_entry.key, map_entry.value));
        return true; // Return true if decoding and populating the map was successful
    }
};

