BoundingBox adjustMotionExtrema(BoundingBox tb) {
    // Add a little slop to allow for floating-point round-off error in computing the motion extrema times.
    tb.pMin.x += (Float)1e-4 * tb.Diagonal();
    tb.pMin.y += (Float)1e-4 * tb.Diagonal();
    tb.pMin.z += (Float)1e-4 * tb.Diagonal();
    return tb;
}

