namespace boost {
    // Define SinglePassRangeConcept and range_detail::for_each_impl here
    // ...
    template<class SinglePassRange1, class SinglePassRange2, class Fn2>
    inline Fn2 for_each(SinglePassRange1& rng1, const SinglePassRange2& rng2, Fn2 fn)
    {
        // Range concept assertions
        BOOST_RANGE_CONCEPT_ASSERT(( SinglePassRangeConcept<SinglePassRange1> ));
        BOOST_RANGE_CONCEPT_ASSERT(( SinglePassRangeConcept<const SinglePassRange2> ));
        // Iterate over the ranges and apply the function
        auto it1 = ::boost::begin(rng1);
        auto it2 = ::boost::begin(rng2);
        while (it1 != ::boost::end(rng1) && it2 != ::boost::end(rng2)) {
            fn(*it1, *it2);  // Apply the function to the current pair of elements
            ++it1;
            ++it2;
        }
        return fn;
    }
}
// Example usage
int main() {
    std::vector<int> range1 = {1, 2, 3, 4};
    std::vector<int> range2 = {5, 6, 7, 8};
    auto print_sum = [](int a, int b) { std::cout << a + b << " "; };
    boost::for_each(range1, range2, print_sum);  // Output: 6 8 10 12
    return 0;
}

