class Uncopyable {
protected:
    Uncopyable() {}
    ~Uncopyable() {}
private:
    Uncopyable(const Uncopyable&);
    Uncopyable& operator=(const Uncopyable&);
};
class CriticalSection {
public:
    void Lock() {
        mutex.lock();
    }
    void Unlock() {
        mutex.unlock();
    }
private:
    std::mutex mutex;
};
class ScopedLock : private Uncopyable {
public:
    ScopedLock(CriticalSection& criticalSection)
        : cs(criticalSection) {
        REF_CHECK(criticalSection);
        cs.Lock();
    }
    ~ScopedLock() {
        cs.Unlock();
    }
private:
    CriticalSection& cs;
};
template <typename T>
class ThreadSafeStack {
public:
    void Push(const T& value) {
        ScopedLock lock(cs);
        data.push(value);
    }
    bool Pop(T& value) {
        ScopedLock lock(cs);
        if (data.empty()) {
            return false;
        }
        value = data.top();
        data.pop();
        return true;
    }
    bool IsEmpty() {
        ScopedLock lock(cs);
        return data.empty();
    }
private:
    std::stack<T> data;
    CriticalSection cs;
};

#include <functional>
double trapezoidalIntegral(std::function<double(double)> f, double a, double b, int N) {
    double h = (b - a) / N;  // Width of each subinterval
    double sum = 0.5 * (f(a) + f(b));  // Initialize sum with the first and last function evaluations
    for (int i = 1; i < N; i++) {
        double x = a + i * h;  // Calculate the x value for the current subinterval
        sum += f(x);  // Add the function value at x to the sum
    }
    return h * sum;  // Return the approximate integral value
}

