#include <iostream>
// Define the CPU feature detection class
class CPUFeatureDetection {
public:
    bool HW_SSE2;
    bool HW_AVX;
    bool HW_AVX2;
    // Function to retrieve CPU feature information using CPUID instruction
    void cpuid(int info[4], int function_id) {
        __asm__ __volatile__(
            "cpuid"
            : "=a" (info[0]), "=b" (info[1]), "=c" (info[2]), "=d" (info[3])
            : "a" (function_id)
        );
    }
    // Function to detect CPU features and set the flags accordingly
    void detectFeatures() {
        int info[4];
        cpuid(info, 0);
        int nIds = info[0];
        if (nIds >= 1) {
            cpuid(info, 1);
            // Check for SSE2 support (bit 26 of edx)
            HW_SSE2 = (info[3] & (1 << 26)) != 0;
            // Check for AVX support (bit 28 of ecx)
            HW_AVX = (info[2] & (1 << 28)) != 0;
        }
        if (nIds >= 7) {
            cpuid(info, 7);
            // Check for AVX2 support (bit 5 of ebx)
            HW_AVX2 = (info[1] & (1 << 5)) != 0;
        }
    }
};
int main() {
    CPUFeatureDetection cpuFeatures;
    cpuFeatures.detectFeatures();
    std::cout << "SSE2 support: " << (cpuFeatures.HW_SSE2 ? "Yes" : "No") << std::endl;
    std::cout << "AVX support: " << (cpuFeatures.HW_AVX ? "Yes" : "No") << std::endl;
    std::cout << "AVX2 support: " << (cpuFeatures.HW_AVX2 ? "Yes" : "No") << std::endl;
    return 0;
}

