void SMExtractRGBI(IplImage* inputImage, CvMat* &R, CvMat* &G, CvMat* &B, CvMat* &I)
{
    // Convert input image to OpenCV Mat
    Mat inputMat(inputImage);
    // Split the input image into its RGB components
    vector<Mat> rgbChannels;
    split(inputMat, rgbChannels);
    // Convert RGB channels to floating point format
    Mat R_float, G_float, B_float;
    rgbChannels[2].convertTo(R_float, CV_32F);
    rgbChannels[1].convertTo(G_float, CV_32F);
    rgbChannels[0].convertTo(B_float, CV_32F);
    // Calculate intensity (I) as the average of RGB channels
    Mat I_float = (R_float + G_float + B_float) / 3.0;
    // Allocate memory for output matrices
    R = cvCreateMat(inputImage->height, inputImage->width, CV_32FC1);
    G = cvCreateMat(inputImage->height, inputImage->width, CV_32FC1);
    B = cvCreateMat(inputImage->height, inputImage->width, CV_32FC1);
    I = cvCreateMat(inputImage->height, inputImage->width, CV_32FC1);
    // Copy data from OpenCV Mat to CvMat
    memcpy(R->data.fl, R_float.data, R_float.total() * sizeof(float));
    memcpy(G->data.fl, G_float.data, G_float.total() * sizeof(float));
    memcpy(B->data.fl, B_float.data, B_float.total() * sizeof(float));
