#include <png.h>
#include <fstream>
#include <iostream>
void PNGImageReader::ReadImage(const std::string &filename, GrayscaleFloatImage &image) {
    // Open the PNG file for reading
    std::ifstream file(filename, std::ios::binary);
    if (!file) {
        std::cerr << "Error: Unable to open file " << filename << std::endl;
        return;
    }
    // Create a PNG read struct
    png_structp png = png_create_read_struct(PNG_LIBPNG_VER_STRING, nullptr, nullptr, nullptr);
    if (!png) {
        std::cerr << "Error: Failed to create PNG read struct" << std::endl;
        file.close();
        return;
    }
    // Create a PNG info struct
    png_infop info = png_create_info_struct(png);
    if (!info) {
        std::cerr << "Error: Failed to create PNG info struct" << std::endl;
        png_destroy_read_struct(&png, nullptr, nullptr);
        file.close();
        return;
    }
    // Set up error handling
    if (setjmp(png_jmpbuf(png))) {
        std::cerr << "Error: An error occurred while reading the PNG file" << std::endl;
        png_destroy_read_struct(&png, &info, nullptr);
        file.close();
        return;
    }
    // Initialize PNG IO
    png_init_io(png, file);
    // Read the PNG header info
    png_read_info(png, info);
    int width = png_get_image_width(png, info);
    int height = png_get_image_height(png, info);
    int bit_depth = png_get_bit_depth(png, info);
    int color_type = png_get_color_type(png, info);
    // Ensure the PNG image is grayscale with 8-bit depth
    if (color_type != PNG_COLOR_TYPE_GRAY || bit_depth != 8) {
        std::cerr << "Error: Unsupported PNG format. Only 8-bit grayscale images are supported." << std::endl;
        png_destroy_read_struct(&png, &info, nullptr);
        file.close();
        return;
    }
    // Allocate memory for the image data
    png_bytep row_pointers[height];
    for (int y = 0; y < height; ++y) {
        row_pointers[y] = (png_bytep)malloc(png_get_rowbytes(png, info));
    }
    // Read the PNG image data
    png_read_image(png, row_pointers);
    // Populate the GrayscaleFloatImage object with the pixel values
    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            // Convert the 8-bit grayscale value to a floating-point value
            float value = static_cast<float>(row_pointers[y][x]) / 255.0f;
            image.SetPixelValue(x, y, value);
        }
    }
    // Clean up and release resources
    for (int y = 0; y < height; ++y) {
        free(row_pointers[y]);
    }
    png_destroy_read_struct(&png, &info, nullptr);
    file.close();
}

#include <memory>
class CustomMemoryManager {
    std::shared_ptr<void> storage;
    template<typename T>
    static void funcDeleter(void* mPtr) {
        static_cast<T*>(mPtr)->~T();
        operator delete(mPtr);
    }
public:
    template<typename T>
    T* allocate() {
        storage.reset(new T, funcDeleter<T>);
        return static_cast<T*>(storage.get());
    }
    template<typename T>
    void deallocate(T* ptr) {
        if (ptr == storage.get()) {
            storage.reset();
        }
    }
};

