// Test basic boolean constants
void test_boolean_constants(SMTParser::ParserPtr& parser) {
    std::cout << "=== Testing Boolean Constants ===" << std::endl;
    auto t = parser->mkExpr("true");
    assert(t && t->isTrue() && !t->isFalse());
    std::cout << "Expression: true" << std::endl;
    std::cout << "  Result: " << parser->toString(t) << std::endl;
    std::cout << "  isTrue: yes" << std::endl;
    std::cout << "  isFalse: no" << std::endl << std::endl;
    auto f = parser->mkExpr("false");
    assert(f && f->isFalse() && !f->isTrue());
    std::cout << "Expression: false" << std::endl;
    std::cout << "  Result: " << parser->toString(f) << std::endl;
    std::cout << "  isTrue: no" << std::endl;
    std::cout << "  isFalse: yes" << std::endl << std::endl;
}
// Test logical operations (expected: true/false)
void test_logical_operations(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, bool>> cases = {
        {"(not true)", false},
        {"(not false)", true},
        {"(and true true)", true},
        {"(and true false)", false},
        {"(and false false)", false},
        {"(or true true)", true},
        {"(or true false)", true},
        {"(or false false)", false},
        {"(=> true true)", true},
        {"(=> true false)", false},
        {"(=> false true)", true},
        {"(=> false false)", true},
        {"(xor true true)", false},
        {"(xor true false)", true},
        {"(xor false false)", false}
    };

    std::cout << "=== Testing Logical Operations ===" << std::endl;
    for (const auto& p : cases) {
        std::cout << "Expression: " << p.first << std::endl;
        std::shared_ptr<SMTParser::DAGNode> result = parser->mkExpr(p.first);
        assert(result);
        assert(result->isTrue() == p.second || result->isFalse() == !p.second);
        std::cout << "  Result: " << parser->toString(result) << std::endl;
        std::cout << std::endl;
    }
}
// Test complex boolean expressions
void test_complex_expressions(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, bool>> cases = {
        {"(and (or true false) (not false))", true},
        {"(or (and true false) (not true))", false},
        {"(=> (or true false) (and true true))", true},
        {"(xor (not false) (and true false))", true},
        {"(and (=> true false) (or false true))", false},
        {"(not (and (or true false) (=> false true)))", false}
    };

    std::cout << "=== Testing Complex Boolean Expressions ===" << std::endl;
    for (const auto& p : cases) {
        std::cout << "Expression: " << p.first << std::endl;
        std::shared_ptr<SMTParser::DAGNode> result = parser->mkExpr(p.first);
        assert(result);
        assert(result->isTrue() == p.second || result->isFalse() == !p.second);
        std::cout << "  Result: " << parser->toString(result) << std::endl;
        std::cout << std::endl;
    }
}
int main() {
    std::cout << "======= Boolean Logic Operations Test =======" << std::endl;

    SMTParser::ParserPtr parser = SMTParser::newParser();

    test_boolean_constants(parser);
    test_logical_operations(parser);
    test_complex_expressions(parser);

    return 0;
}

#include <iostream>
#include <vector>
#include <numeric>
#include <random>
#include <algorithm>
// Function to perform a query
int ask(int x) {
    std::cout << "? " << x << std::endl;
    int r;
    std::cin >> r;
    if (r == -1) exit(0); // Judge may terminate on error
    return r;
}
// Function to report a pair
void answer(int a, int b) {
    std::cout << "! " << a << " " << b << std::endl;
}
void solve(std::vector<int>& slices) {
    if (slices.empty()) {
        return;
    }
    if (slices.size() == 2) {
        answer(slices[0], slices[1]);
        return;
    }
    // Pick a pivot element. Slices are pre-shuffled, so this is a random pivot.
    int pivot = slices.back();
    slices.pop_back();
    // Put pivot in the device.
    ask(pivot);
    std::vector<int> group_with_pivot;
    group_with_pivot.push_back(pivot);
    std::vector<int> other_group;
    // The number of distinct kinds in the device.
    // Initially, only the pivot is in, so there's 1 kind.
    int kinds_in_device = 1;
    // Partition the remaining slices based on the pivot.
    for (int slice : slices) {
        int kinds_after_toggle = ask(slice);
        // If the number of kinds does not increase, the new slice's mate is
        // already in the device. The device currently contains group_with_pivot.
        if (kinds_after_toggle == kinds_in_device) {
            group_with_pivot.push_back(slice);
        } else {
            // Number of kinds increased, so slice's mate is not in group_with_pivot.
            // This slice belongs to a different self-contained group.
            other_group.push_back(slice);
            // The slice was added and increased kinds, so we update the count for the
            // growing set in the device.
            kinds_in_device = kinds_after_toggle;
        }
    }
    // At this point, group_with_pivot is in the device.
    // Its elements form a self-contained set.
    // The elements of other_group are not in the device and also form a self-contained set.
    // Clear the device by removing all elements of group_with_pivot.
    for (int slice : group_with_pivot) {
        ask(slice);
    }

    // Recurse on both groups.
    solve(group_with_pivot);
    solve(other_group);
}
int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int n;
    std::cin >> n;
    if (n == 0) {
        return 0;
    }
    std::vector<int> all_slices(2 * n);
    std::iota(all_slices.begin(), all_slices.end(), 1);
    // Randomize to make worst-case pivot selection highly unlikely.
    std::random_device rd;
    std::mt19937 g(rd());
    std::shuffle(all_slices.begin(), all_slices.end(), g);
    solve(all_slices);
    return 0;
}

#include <asio/ts/executor.hpp>
#include <asio/thread_pool.hpp>
#include <iostream>
#include <string>
using asio::bind_executor;
using asio::dispatch;
using asio::make_work_guard;
using asio::post;
using asio::thread_pool;
// A function to asynchronously read a single line from an input stream.
template <class Handler>
void async_getline(std::istream& is, Handler handler)
{
  // Create executor_work for the handler's associated executor.
  auto work = make_work_guard(handler);
  // Post a function object to do the work asynchronously.
  post([&is, work, handler=std::move(handler)]() mutable
      {
        std::string line;
        std::getline(is, line);
        // Pass the result to the handler, via the associated executor.
        dispatch(work.get_executor(),
            [line=std::move(line), handler=std::move(handler)]() mutable
            {
              handler(std::move(line));
            });
      });
}
int main()
{
  thread_pool pool;
  std::cout << "Enter a line: ";
  async_getline(std::cin,
      bind_executor(pool, [](std::string line)
        {
          std::cout << "Line: " << line << "\n";
        }));
  pool.join();
}

