#include <asio/ts/executor.hpp>
#include <asio/thread_pool.hpp>
#include <iostream>
using asio::post;
using asio::thread_pool;
// Traditional active object pattern.
// Member functions do not block.
class bank_account
{
  int balance_ = 0;
  mutable thread_pool pool_{1};
public:
  void deposit(int amount)
  {
    post(pool_, [=]
      {
        balance_ += amount;
      });
  }
  void withdraw(int amount)
  {
    post(pool_, [=]
      {
        if (balance_ >= amount)
          balance_ -= amount;
      });
  }
  void print_balance() const
  {
    post(pool_, [=]
      {
        std::cout << "balance = " << balance_ << "\n";
      });
  }
  ~bank_account()
  {
    pool_.join();
  }
};
int main()
{
  bank_account acct;
  acct.deposit(20);
  acct.withdraw(10);
  acct.print_balance();
}

#include "Alias/TPA/Context/Context.h"
#include "Alias/TPA/Context/ProgramPoint.h"
using namespace llvm;
namespace context {
// Pushes a new context frame onto the current context stack.
// This version takes a ProgramPoint, extracting the context and instruction from it.
const Context *Context::pushContext(const ProgramPoint &pp) {
  return pushContext(pp.getContext(), pp.getInstruction());
}
// Pushes a new context frame.
// Parameters:
//   ctx - The current (caller's) context.
//   inst - The call instruction (call site) invoking the function.
// Returns: A pointer to the unique interned Context object representing the new state.
const Context *Context::pushContext(const Context *ctx,
                                    const Instruction *inst) {
  // Create a temporary context object
  auto newCtx = Context(inst, ctx);
  // Insert into the set. If it exists, 'itr' points to the existing one.
  // If not, it points to the newly inserted one.
  auto itr = ctxSet.insert(newCtx).first;
  return &(*itr);
}
// Pops the most recent context frame.
// Returns the predecessor context (the caller's context).
const Context *Context::popContext(const Context *ctx) {
  assert(ctx->sz != 0 && "Trying to pop an empty context");
  return ctx->predContext;
}
// Retrieves the singleton Global Context.
// Used for global variables and the entry point of the analysis.
const Context *Context::getGlobalContext() {
  auto itr = ctxSet.insert(Context()).first;
  return &(*itr);
}
// Helper to retrieve all created contexts.
// Useful for debugging or statistics.
std::vector<const Context *> Context::getAllContexts() {
  std::vector<const Context *> ret;
  ret.reserve(ctxSet.size());
  for (auto const &ctx : ctxSet)
    ret.push_back(&ctx);
  return ret;
}
} // namespace context

#include "BufferedOutputStream.h"
#include "util/console/ArrayWithLength.h"
#include "win/extraX64.h"
// Creates a new buffered output stream to write data to the specified
// underlying output stream with the specified buffer size. Parameters: out -
// the underlying output stream. size - the buffer size.
BufferedOutputStream::BufferedOutputStream(OutputStream* out, int size) {
    stream = out;
    buf    = byteArray(size);
    count  = 0;
}
BufferedOutputStream::~BufferedOutputStream() { delete buf.data; }
// Flushes this buffered output stream. This forces any buffered output bytes to
// be written out to the underlying output stream.
void BufferedOutputStream::flush() {
    stream->write(buf, 0, count);
    count = 0;
}
// Closes this output stream and releases any system resources associated with
// the stream. The close method of FilterOutputStream calls its flush method,
// and then calls the close method of its underlying output stream.
void BufferedOutputStream::close() {
    flush();
    stream->close();
}
// Writes len bytes from the specified byte array starting at offset off to this
// buffered output stream. Ordinarily this method stores bytes from the given
// array into this stream's buffer, flushing the buffer to the underlying output
// stream as needed. If the requested length is at least as large as this
// stream's buffer, however, then this method will flush the buffer and write
// the bytes directly to the underlying output stream. Thus redundant
// BufferedOutputStreams will not copy data unnecessarily.
//
// Overrides:
// write in class FilterOutputStream
// Parameters:
// b - the data.
// off - the start offset in the data.
// len - the number of bytes to write.
void BufferedOutputStream::write(
    byteArray    b,
    unsigned int offset,
    unsigned int length
) {
    // Over the length of what we can store in our buffer - just flush the
    // buffer and output directly
    if (length >= buf.length) {
        flush();
        stream->write(b, offset, length);
    } else {
        for (unsigned int i = 0; i < length; i++) {
            write(b[offset + i]);
        }
    }
}
// Writes b.length bytes to this output stream.
// The write method of FilterOutputStream calls its write method of three
// arguments with the arguments b, 0, and b.length.
//
// Note that this method does not call the one-argument write method of its
// underlying stream with the single argument b.
void BufferedOutputStream::write(byteArray b) { write(b, 0, b.length); }
// Writes the specified byte to this buffered output stream.
// Overrides:
// write in class FilterOutputStream
// Parameters:
// b - the byte to be written.
void BufferedOutputStream::write(unsigned int b) {
    buf[count++] = (byte)b;
    if (count == buf.length) {
        flush();
    }
}

