#include <sm/vvec>
#include <mplot/Visual.h>
#include <mplot/GraphVisual.h>
#include <mplot/unicode.h>
// Make an equation string for the legend
std::string make_legend_str (double k, double x0)
{
    // We'll use mathplot's awesome unicode chars for the subscript 0 on x0
    namespace uc = mplot::unicode;
    std::stringstream ktxt;
    if (k != 1.0) { ktxt << k; }
    std::stringstream brtxt;
    std::stringstream ostxt;
    if (x0 != 0.0) {
        brtxt << "(";
        if (x0 > 0.0) {
            ostxt << " - " << x0 <<")";
        } else {
            ostxt << " + " << -x0 <<")";
        }
    }
    std::stringstream eqn;
    eqn << "k="<<k<<", x" << uc::toUtf8(uc::subs0) << "=" << x0;
    eqn << ": f(x) = 1 / [1 + exp (-"<< ktxt.str() << brtxt.str() << "x" << ostxt.str() << ")]";
    return eqn.str();
}
int main()
{
    // Set up a mplot::Visual 'scene environment'.
    mplot::Visual v(1024, 768, "Logistic functions");
    // Create a GraphVisual object (obtaining a unique_ptr to the object) with a spatial offset within the scene of 0,0,0
    auto gv = std::make_unique<mplot::GraphVisual<double>> (sm::vec<float>({-0.5f,-0.5f,0.0f}));
    v.bindmodel (gv);
    // Data for the x axis. A vvec is like std::vector, but with built-in maths methods
    sm::vvec<double> x;
    // This works like numpy's linspace() (the 3 args are "start", "end" and "num"):
    x.linspace (-100, 30, 200);
    // Logistic functions. Args are parameters to the function: (k, x0)
    // vvec::logistic() returns a new vvec with the logistic function-transformed values:
    gv->setdata (x, x.logistic(0.1, -10), make_legend_str (0.1, -10));
    // For this one, demonstrate use of logistic_inplace():
    sm::vvec<double> xlogistic = x;
    xlogistic.logistic_inplace(0.25, -5);
    gv->setdata (x, xlogistic, make_legend_str (0.25, -5));
    gv->setdata (x, x.logistic(0.5, 0), make_legend_str (0.5, 0));
    gv->setdata (x, x.logistic(1, 5), make_legend_str (1, 5));
    gv->setdata (x, x.logistic(2, 10), make_legend_str (2, 10));
    // finalize() makes the GraphVisual compute the vertices of the OpenGL model
    gv->finalize();
    // Add the GraphVisual OpenGL model to the Visual scene, transferring ownership of the unique_ptr
    v.addVisualModel (gv);
    // Render the scene on the screen until user quits with 'Ctrl-q'
    v.keepOpen();
    return 0;
}

#include <iostream>
// Function to ask a query and get the result
int ask(int l, int r) {
    std::cout << "? " << l << " " << r << std::endl;
    int result;
    std::cin >> result;
    return result;
}
void solve() {
    int n;
    std::cin >> n;
    // Phase 1: Find reference point s (position of n-1)
    // and determine if n is to its left or right.
    int s = ask(1, n);
    int L, R;
    bool s_is_left;
    if (s < n && ask(s, n) == s) {
        // n is in [s+1, n], so s is to the left of the search range.
        L = s + 1;
        R = n;
        s_is_left = true;
    } else {
        // n is in [1, s-1], so s is to the right of the search range.
        L = 1;
        R = s - 1;
        s_is_left = false;
    }
    // Phase 2: Binary search for the position of n.
    while (L < R) {
        int M = L + (R - L) / 2;
        if (s_is_left) {
            // s is to the left of [L, R]. Test if n is in [L, M].
            // Query range [s, M] contains n iff pos_n is in [L, M].
            if (ask(s, M) == s) {
                // n is in [L, M]
                R = M;
            } else {
                // n is in [M+1, R]
                L = M + 1;
            }
        } else {
            // s is to the right of [L, R]. Test if n is in [M+1, R].
            // Query range [M+1, s] contains n iff pos_n is in [M+1, R].
            if (ask(M + 1, s) == s) {
                // n is in [M+1, R]
                L = M + 1;
            } else {
                // n is in [L, M]
                R = M;
            }
        }
    }
    std::cout << "! " << L << std::endl;
}
int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int T;
    std::cin >> T;
    while (T--) {
        solve();
    }
    return 0;
}

#include "ta.h"
// Tile Accelerator (TA) state machine for PowerVR2 (Dreamcast) emulation
// Handles DMA and Store Queue writes, dispatches polygon/vertex/control params
namespace TASplitter
{
    // Current active command handler (state machine pointer)
    TaListFP* TaCmd = nullptr;
}
using namespace TASplitter;
// Store Queue path: single 32-byte write (e.g. via SQ registers)
void libPvr_TaSQ(u32* data)
{
    verify(TaCmd != nullptr);
    Ta_Dma* t = (Ta_Dma*)data;
    TaCmd(t, t);
}
// DMA path: process a contiguous block of 32-byte TA entries
// 'size' is in units of Ta_Dma (32 bytes), not bytes
void libPvr_TaDMA(u32* data, u32 size)
{
    verify(TaCmd != nullptr);
    verify(size > 0);
    Ta_Dma* ta_data     = (Ta_Dma*)data;
    Ta_Dma* ta_data_end = ta_data + size - 1;
    do
    {
        ta_data = TaCmd(ta_data, ta_data_end);
    }
    while (ta_data <= ta_data_end);
}
