- Returns the current seleted locale
## return: string?
### Game.Resources.getLocale
*/
static int l_Resources_getLocale(lua_State* L) {
    if (Minecraft::Lang::current)
        lua_pushstring(L, Minecraft::Lang::current->name);
    else
        lua_pushnil(L);
    return 1;
