void Change2FNumberingOrder(idx_t nvtxs, idx_t *xadj, idx_t *adjncy, 
         idx_t *v1, idx_t *v2)
{
  idx_t i, nedges;
  for (i=0; i<nvtxs; i++) {
    v1[i]++;
    v2[i]++;
  }
  nedges = xadj[nvtxs];
  for (i=0; i<nedges; i++)
    adjncy[i]++;
