#include <iostream>
#include <vector>
using namespace std;
// LeetCode 136: Single Number
// Given a non-empty array of integers nums, every element appears twice except for one. Find that single one.
// You must implement a solution with a linear runtime complexity and use only constant extra space.
class Solution {
public:
    int singleNumber(vector<int> & nums) {
        int n = 0;
        for(int i : nums){
            n^= i;
        }

      return n;

    }
};
// Logic Explanation:
// We can use the XOR bitwise operation to solve this problem efficiently.
// The XOR operation has the following properties:
// 1. a ^ a = 0 (any number XORed with itself is 0)
// 2. a ^ 0 = a (any number XORed with 0 is the number itself)
// 3. XOR is commutative and associative, meaning the order of operations does not matter.
// By XORing all the numbers in the array together, the numbers that appear twice will cancel each other out
// (resulting in 0), and we will be left with the single number that appears only once.
// Time Complexity: O(n) where n is the number of elements in the array.
// Space Complexity: O(1) since we are using only a constant amount of extra space.

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
// Function to map characters 'A'-'Z', '0'-'9' to an integer index [0, 35]
inline int char_to_int(char c) {
    if (c >= 'A' && c <= 'Z') {
        return c - 'A';
    }
    // Assumes c is a digit '0'-'9' based on problem constraints
    return c - '0' + 26;
}
// The core greedy algorithm
// Iterates through s_iterate and finds the earliest possible match for each character
// based on precomputed character positions `pos_search`.
// This is an O(|s_iterate| + |s_search|) implementation where |s_search| is the
// length of the string from which pos_search was built.
std::string solve_greedy(const std::string& s_iterate, const std::vector<std::vector<int>>& pos_search) {
    std::string res;
    if (s_iterate.empty()) {
        return res;
    }
    res.reserve(s_iterate.length());

    int last_search_idx = -1;
    std::vector<int> ptrs(36, 0);
    for (char c_iterate : s_iterate) {
        int char_idx = char_to_int(c_iterate);

        const std::vector<int>& positions = pos_search[char_idx];
        int& p = ptrs[char_idx];

        // Advance pointer to the first available position
        while (static_cast<size_t>(p) < positions.size() && positions[p] <= last_search_idx) {
            p++;
        }

        if (static_cast<size_t>(p) < positions.size()) {
            res.push_back(c_iterate);
            last_search_idx = positions[p];
            p++;
        }
    }
    return res;
}
int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    std::string s1, s2;
    std::cin >> s1 >> s2;
    // Precompute character positions for both strings
    std::vector<std::vector<int>> pos1(36);
    std::vector<std::vector<int>> pos2(36);
    for (size_t i = 0; i < s1.length(); ++i) {
        pos1[char_to_int(s1[i])].push_back(i);
    }
    for (size_t i = 0; i < s2.length(); ++i) {
        pos2[char_to_int(s2[i])].push_back(i);
    }
    // Run greedy algorithm in both directions:
    // 1. Iterate through s1, search in s2
    // 2. Iterate through s2, search in s1
    std::string res1 = solve_greedy(s1, pos2);
    std::string res2 = solve_greedy(s2, pos1);
    // Output the longer result
    if (res1.length() >= res2.length()) {
        std::cout << res1 << '\n';
    } else {
        std::cout << res2 << '\n';
    }
    return 0;
}

#include <pybind11/eigen.h>
#include <pybind11/numpy.h>
#include <pybind11/pybind11.h>
#include <pybind11/stl.h>
#include <Eigen/Dense>
#include <lapack.hh>
#include <vector>
namespace py = pybind11;
/**
 * @brief Solve dense matrix eigenvalue problems using LAPACK's syev.
 *
 * @param matrix Input dense matrix (NumPy array).
 * @return A tuple containing the eigenvalues and eigenvectors of the matrix.
 */
py::tuple dense_matrix_solver(const py::array_t<double>& matrix) {
  // Validate input matrix
  if (matrix.ndim() != 2) {
    throw std::invalid_argument("Input matrix must be 2-dimensional.");
  }
  auto shape = matrix.shape();
  if (shape[0] != shape[1]) {
    throw std::invalid_argument("Input matrix must be square.");
  }
  int n = shape[0];
  // Use Eigen types for NumPy conversion
  Eigen::MatrixXd a = Eigen::Map<const Eigen::MatrixXd>(matrix.data(), n, n);
  Eigen::VectorXd w(n);
  int info = lapack::syev(lapack::Job::Vec, lapack::Uplo::Lower, n, a.data(), n,
                          w.data());
  if (info != 0) {
    throw std::runtime_error("LAPACK syev failed to compute eigenvalues.");
  }
  return py::make_tuple(w, a);
}
/**
 * @brief Bind syev solver to Python module.
 *
 */
void bind_syev_solver(py::module& m) {
  m.def("syev_solver", &dense_matrix_solver,
        R"(
            Solve a dense matrix eigenvalue problem using LAPACK's syev.
            This function computes all eigenvalues and eigenvectors of a dense matrix.
            Parameters
            ----------
            matrix : numpy.ndarray
                Dense matrix.
            Returns
            -------
            tuple of (numpy.ndarray, numpy.ndarray)
                - ``eigenvalues``: numpy.ndarray, the eigenvalues of the matrix in ascending order
                - ``eigenvectors``: numpy.ndarray, the eigenvectors of the matrix, where each column corresponds to an eigenvector
            Raises
            ------
            ValueError
                If the input matrix is not square or symmetric.
            RuntimeError
                If LAPACK fails to compute the eigenvalues.
        )",
        py::arg("matrix"));
}

class Solution {
public:
    int maximumWealth(vector<vector<int>>& accounts) {
        int m=accounts.size();
        int n=accounts[0].size();
        int maxSum=0;
        for(int i=0;i<m;i++){
            int sum=0;
            for(int j=0;j<n;j++){
                sum+=accounts[i][j];
            }
            maxSum=max(sum,maxSum);
        }
        return maxSum;

    }
};

