#include <sol/sol.hpp>
#include <iostream>
void test_environment(std::string key,
     const sol::environment& env, const sol::state_view& lua) {
	sol::optional<int> maybe_env_a = env[key];
	sol::optional<int> maybe_global_a = lua[key];
	if (maybe_global_a) {
		std::cout << "\t'" << key << "' is "
		          << maybe_global_a.value()
		          << " in the global environment" << std::endl;
	}
	else {
		std::cout
		     << "\t'" << key
		     << "' does not exist in the global environment"
		     << std::endl;
	}
	if (maybe_env_a) {
		std::cout << "\t'" << key << "' is "
		          << maybe_env_a.value()
		          << " in target environment" << std::endl;
	}
	else {
		std::cout << "\t'" << key
		          << "' does not exist in target environment"
		          << std::endl;
	}
}
int main(int, char**) {
	std::cout << "=== environments ===" << std::endl;
	sol::state lua;
	// A global variable to see if we can "fallback" into it
	lua["b"] = 2142;
	// Create a new environment
	sol::environment plain_env(lua, sol::create);
	// Use it
	lua.script("a = 24", plain_env);
	std::cout << "-- target: plain_env" << std::endl;
	test_environment("a", plain_env, lua);
	test_environment("b", plain_env, lua);
	std::cout << std::endl;
	// Create an environment with a fallback
	sol::environment env_with_fallback(
	     lua, sol::create, lua.globals());
	// Use it
	lua.script("a = 56", env_with_fallback);
	std::cout << "-- target: env_with_fallback (fallback is "
	             "global table)"
	          << std::endl;
	test_environment("a", env_with_fallback, lua);
	test_environment("b", env_with_fallback, lua);
	std::cout << std::endl;
	return 0;
}

#include <assert.h>
#include <math.h>
#include <mpi.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
// Creates an array of random numbers. Each number has a value from 0 - 1
float*
create_rand_nums(int num_elements)
{
    float* rand_nums = (float*) malloc(sizeof(float) * num_elements);
    assert(rand_nums != NULL);
    int i;
    for(i = 0; i < num_elements; i++)
    {
        rand_nums[i] = (rand() / (float) RAND_MAX);
    }
    return rand_nums;
}
int
main(int argc, char** argv)
{
    if(argc != 2)
    {
        fprintf(stderr, "Usage: avg num_elements_per_proc\n");
        exit(1);
    }
    int num_elements_per_proc = atoi(argv[1]);
    MPI_Init(NULL, NULL);
    int world_rank;
    MPI_Comm_rank(MPI_COMM_WORLD, &world_rank);
    int world_size;
    MPI_Comm_size(MPI_COMM_WORLD, &world_size);
    // Create a random array of elements on all processes.
    srand(time(NULL) *
          world_rank);  // Seed the random number generator of processes uniquely
    float* rand_nums = NULL;
    rand_nums        = create_rand_nums(num_elements_per_proc);
    // Sum the numbers locally
    float local_sum = 0;
    int   i;
    for(i = 0; i < num_elements_per_proc; i++)
    {
        local_sum += rand_nums[i];
    }
    // Reduce all of the local sums into the global sum in order to
    // calculate the mean
    float global_sum;
    MPI_Allreduce(&local_sum, &global_sum, 1, MPI_FLOAT, MPI_SUM, MPI_COMM_WORLD);
    float mean = global_sum / (num_elements_per_proc * world_size);
    // Compute the local sum of the squared differences from the mean
    float local_sq_diff = 0;
    for(i = 0; i < num_elements_per_proc; i++)
    {
        local_sq_diff += (rand_nums[i] - mean) * (rand_nums[i] - mean);
    }
    // Reduce the global sum of the squared differences to the root process
    // and print off the answer
    float global_sq_diff;
    MPI_Reduce(&local_sq_diff, &global_sq_diff, 1, MPI_FLOAT, MPI_SUM, 0, MPI_COMM_WORLD);
    // The standard deviation is the square root of the mean of the squared
    // differences.
    if(world_rank == 0)
    {
        float stddev = sqrt(global_sq_diff / (num_elements_per_proc * world_size));
        printf("Mean - %f, Standard deviation = %f\n", mean, stddev);
    }
    // Clean up
    free(rand_nums);
    MPI_Barrier(MPI_COMM_WORLD);
    MPI_Finalize();
}

