using asio::thread_pool;
using asio::yield_context;
void print_match(std::string input_file, std::string line)
{
  std::cout << input_file << ':' << line << std::endl;
}
void search_file(std::string search_string, std::string input_file,
    strand<thread_pool::executor_type> output_strand, yield_context yield)
{
  std::ifstream is(input_file.c_str());
  std::string line;
  std::size_t line_num = 0;
  while (std::getline(is, line))
  {
    // If we find a match, send a message to the output.
    if (line.find(search_string) != std::string::npos)
    {
      dispatch(output_strand, boost::bind(&print_match, input_file, line));
    }
    // Every so often we yield control to another coroutine.
    if (++line_num % 10 == 0)
      post(yield);
  }
}
int main(int argc, char* argv[])
{
  try
  {
    if (argc < 2)
    {
      std::cerr << "Usage: parallel_grep <string> <files...>\n";
      return 1;
    }
    // We use a fixed size pool of threads for reading the input files. The
    // number of threads is automatically determined based on the number of
    // CPUs available in the system.
    thread_pool pool;
    // To prevent the output from being garbled, we use a strand to synchronise
    // printing.
    strand<thread_pool::executor_type> output_strand(pool.get_executor());
    // Spawn a new coroutine for each file specified on the command line.
    std::string search_string = argv[1];
    for (int argn = 2; argn < argc; ++argn)
    {
      std::string input_file = argv[argn];
      spawn(pool, boost::bind(&search_file,
            search_string, input_file, output_strand, _1));
    }
    // Join the thread pool to wait for all the spawned tasks to complete.
    pool.join();
  }
  catch (std::exception& e)
  {
    std::cerr << "Exception: " << e.what() << "\n";
  }
  return 0;
}

#include <iostream>
#include <functional>
#include <string>

// Free function
void free_function(int x) {
    std::cout << "free_function: " << x << std::endl;
}

// Functor
struct Functor {
    void operator()(int x) const {
        std::cout << "Functor: " << x << std::endl;
    }
};

// Class with member functions
struct Widget {
    void member_function(int x) {
        std::cout << "Widget::member_function: " << x << std::endl;
    }

    void const_member_function(int x) const {
        std::cout << "Widget::const_member_function: " << x << std::endl;
    }

    int data = 42;
};

void demo_invoke_basics() {
    std::cout << "=== std::invoke Basics ===" << std::endl;

    Functor f;
    Widget w;

    // Invoke free function
    std::invoke(free_function, 42);

    // Invoke functor
    std::invoke(f, 21);

    // Invoke lambda
    std::invoke([](int x) { std::cout << "Lambda: " << x << std::endl; }, 10);

    // Invoke member function with object reference
    std::invoke(&Widget::member_function, w, 5);

    // Invoke member function with object pointer
    std::invoke(&Widget::member_function, &w, 15);

    // Invoke const member function
    std::invoke(&Widget::const_member_function, w, 25);

    // Access member variable
    int value = std::invoke(&Widget::data, w);
    std::cout << "Widget::data = " << value << std::endl;
}

void demo_vs_traditional() {
    std::cout << "\n=== Traditional vs std::invoke ===" << std::endl;

    Widget w;

    // Traditional calling
    std::cout << "Traditional:" << std::endl;
    w.member_function(1);                  // Direct call
    (w.*&Widget::member_function)(2);      // Member pointer with ref
    (&w->*&Widget::member_function)(3);    // Member pointer with ptr

    // std::invoke - uniform syntax
    std::cout << "\nWith std::invoke:" << std::endl;
    std::invoke(&Widget::member_function, w, 1);
    std::invoke(&Widget::member_function, &w, 2);
}

void demo_with_std_function() {
    std::cout << "\n=== std::invoke with std::function ===" << std::endl;

    std::function<void(int)> func = [](int x) {
        std::cout << "std::function: " << x << std::endl;
    };

    std::invoke(func, 100);
}

void demo_reference_wrapper() {
    std::cout << "\n=== std::invoke with reference_wrapper ===" << std::endl;

    Widget w;
    auto ref = std::ref(w);

    std::invoke(&Widget::member_function, ref, 7);
}

int main() {
    demo_invoke_basics();
    demo_vs_traditional();
    demo_with_std_function();
    demo_reference_wrapper();

    std::cout << "\n=== Key Benefits ===" << std::endl;
    std::cout << "- Uniform syntax for all callable types" << std::endl;
    std::cout << "- No need to remember .* or ->* syntax" << std::endl;
    std::cout << "- Works with std::reference_wrapper" << std::endl;
    std::cout << "- Enables generic programming with callables" << std::endl;

    return 0;
}

#include <iostream>
#include <memory>
#include <string>
#include <grpc++/grpc++.h>
#include "bzl/examples/grpc/proto/test_service.grpc.pb.h"
using grpc::Channel;
using grpc::ClientContext;
using grpc::Status;
using test_service_package::IntRequest;
using test_service_package::IntReply;
using test_service_package::Decompositor;
class DecompositorClient {
 public:
  DecompositorClient(std::shared_ptr<Channel> channel)
      : stub_(Decompositor::NewStub(channel)) {}
  // Assambles the client's payload, sends it and presents the response back
  // from the server.
  std::string Decompose(const int& question_int) {
    // Data we are sending to the server.
    IntRequest request;
    request.set_value(question_int);
    // Container for the data we expect from the server.
    IntReply reply;
    // Context for the client. It could be used to convey extra information to
    // the server and/or tweak certain RPC behaviors.
    ClientContext context;
    // The actual RPC.
    Status status = stub_->Decompose(&context, request, &reply);
    // Act upon its status.
    if (status.ok()) {
      return reply.message();
    } else {
      std::cout << status.error_code() << ": " << status.error_message()
                << std::endl;
      return "RPC failed";
    }
  }
 private:
  std::unique_ptr<Decompositor::Stub> stub_;
};
int main(int argc, char** argv) {
  // Instantiate the client. It requires a channel, out of which the actual RPCs
  // are created. This channel models a connection to an endpoint (in this case,
  // localhost at port 50051). We indicate that the channel isn't authenticated
  // (use of InsecureChannelCredentials()).
  DecompositorClient greeter(grpc::CreateChannel(
      "localhost:50051", grpc::InsecureChannelCredentials()));
  int value = 42;
  std::string reply = greeter.Decompose(value);
  std::cout << "Decompositor received: " << reply << std::endl;
  return 0;
}

