namespace py = pybind11;
namespace {
class MLIRInitializer {
public:
    static MLIRInitializer& instance() {
        static MLIRInitializer inst;
        return inst;
    }
    mlir::DialectRegistry& registry() { return registry_; }
private:
    MLIRInitializer() {
        // Register all standard MLIR dialects
        mlir::registerAllDialects(registry_);
        // Register all passes
        mlir::registerAllPasses();
        // Register SDFG code generators and serializers
        ::sdfg::codegen::register_default_dispatchers();
        ::sdfg::serializer::register_default_serializers();
    }
    mlir::DialectRegistry registry_;
};
class PyMLIRModule {
public:
    explicit PyMLIRModule(const std::string& mlir_text) {
        auto& initializer = MLIRInitializer::instance();
        context_ = std::make_unique<mlir::MLIRContext>(initializer.registry());
        context_->loadAllAvailableDialects();
        module_ = mlir::parseSourceString<mlir::ModuleOp>(mlir_text, context_.get());
        if (!module_) {
            throw std::runtime_error("Failed to parse MLIR module");
        }
    }
    std::string to_string() {
        std::string result;
        llvm::raw_string_ostream os(result);
        module_->print(os);
        return result;
    }
    void convert() {
        mlir::PassManager pm(context_.get());
        pm.addPass(mlir::createLinalgSpecializeGenericOpsPass());
        if (mlir::failed(pm.run(*module_))) {
            throw std::runtime_error("Failed to convert MLIR module");
        }
    }
    std::string translate() {
        std::string result;
        llvm::raw_string_ostream os(result);
        if (mlir::failed(mlir::sdfg::translateToSDFG(module_->getOperation(), os))) {
            throw std::runtime_error("Failed to translate to SDFG code");
        }
        return result;
    }
    mlir::Operation* get_operation() { return module_->getOperation(); }
private:
    std::unique_ptr<mlir::MLIRContext> context_;
    mlir::OwningOpRef<mlir::ModuleOp> module_;
};
} // namespace
PYBIND11_MODULE(_sdfg_mlir, m) {
    m.doc() = "Native Python bindings for MLIR to SDFG conversion";
    // Expose the PyMLIRModule class
    py::class_<PyMLIRModule>(m, "MLIRModule")
        .def(py::init<const std::string&>(), py::arg("mlir_text"), "Create an MLIR module from MLIR text representation")
        .def("to_string", &PyMLIRModule::to_string, "Get the MLIR module as a string")
        .def("convert", &PyMLIRModule::convert, "Convert MLIR module")
        .def("translate", &PyMLIRModule::translate, "Translate the SDFG dialect module to a serialized SDFG");
}

#include <asio/io_context.hpp>
#include <asio/ip/tcp.hpp>
#include <asio/spawn.hpp>
#include <asio/steady_timer.hpp>
#include <asio/write.hpp>
#include <iostream>
#include <memory>
using asio::ip::tcp;
class session : public std::enable_shared_from_this<session>
{
public:
  explicit session(tcp::socket socket)
    : socket_(std::move(socket)),
      timer_(socket_.get_io_context()),
      strand_(socket_.get_io_context())
  {
  }
  void go()
  {
    auto self(shared_from_this());
    asio::spawn(strand_,
        [this, self](asio::yield_context yield)
        {
          try
          {
            char data[128];
            for (;;)
            {
              timer_.expires_from_now(std::chrono::seconds(10));
              std::size_t n = socket_.async_read_some(asio::buffer(data), yield);
              asio::async_write(socket_, asio::buffer(data, n), yield);
            }
          }
          catch (std::exception& e)
          {
            socket_.close();
            timer_.cancel();
          }
        });
    asio::spawn(strand_,
        [this, self](asio::yield_context yield)
        {
          while (socket_.is_open())
          {
            asio::error_code ignored_ec;
            timer_.async_wait(yield[ignored_ec]);
            if (timer_.expires_from_now() <= std::chrono::seconds(0))
              socket_.close();
          }
        });
  }
private:
  tcp::socket socket_;
  asio::steady_timer timer_;
  asio::io_context::strand strand_;
};
int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: echo_server <port>\n";
      return 1;
    }
    asio::io_context io_context;
    asio::spawn(io_context,
        [&](asio::yield_context yield)
        {
          tcp::acceptor acceptor(io_context,
            tcp::endpoint(tcp::v4(), std::atoi(argv[1])));
          for (;;)
          {
            asio::error_code ec;
            tcp::socket socket(io_context);
            acceptor.async_accept(socket, yield[ec]);
            if (!ec) std::make_shared<session>(std::move(socket))->go();
          }
        });
    io_context.run();
  }
  catch (std::exception& e)
  {
    std::cerr << "Exception: " << e.what() << "\n";
  }
  return 0;
}

class Solution {
    multiset<long long> l, r;
public:
    long long minimumCost(vector<int>& nums, int k, int dist) {
        int n = nums.size();
        k--;
        long long cur = nums[0];
        for (int i = 1; i <= dist + 1; i++) cur += nums[i], l.insert(nums[i]);
        while (l.size() > k) {
            cur -= *l.rbegin();
            r.insert(*l.rbegin());
            l.erase(l.find(*l.rbegin()));
        }
        long long ans = cur;
        for (int i = dist + 2; i < n; i++) {
            if (l.find(nums[i - dist - 1]) != l.end()) {
                cur -= nums[i - dist - 1];
                l.erase(l.find(nums[i - dist - 1]));
            } else {
                r.erase(r.find(nums[i - dist - 1]));
            }
            if (nums[i] < *l.rbegin()) {
                cur += nums[i];
                l.insert(nums[i]);
            } else {
                r.insert(nums[i]);
            }
            while (l.size() < k) {
                cur += *r.begin();
                l.insert(*r.begin());
                r.erase(r.find(*r.begin()));
            }
            while (l.size() > k) {
                cur -= *l.rbegin();
                r.insert(*l.rbegin());
                l.erase(l.find(*l.rbegin()));
            }
            ans = min(ans, cur);
        }
        return ans;
    }
};

#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>
#include <vector>
#include <map>
#include <iostream>
// nested allows serialization of maps with vectors inside, and
// vice-versa all from a nested structure of Lua tables it has
// less control over which pieces are considered tables in Lua,
// and which ones are considered userdata, but it covers a good
// 90% of cases where someone wants to handle a nested table
void demo(
     sol::nested<std::map<std::string, std::vector<std::string>>>
          src) {
	std::cout << "demo, sol::nested<...>" << std::endl;
	const auto& listmap = src.value();
	SOL_ASSERT(listmap.size() == 2);
	for (const auto& kvp : listmap) {
		const std::vector<std::string>& strings = kvp.second;
		SOL_ASSERT(strings.size() == 3);
		std::cout << "\t" << kvp.first << " = ";
		for (const auto& s : strings) {
			std::cout << "'" << s << "'"
			          << " ";
		}
		std::cout << std::endl;
	}
	std::cout << std::endl;
}
// This second demo is equivalent to the first
// Nota bene the signature here
// Every container-type that's meant to be
// a table must be wrapped in `sol::as_table_t`
// it's verbose, so feel free to use typedefs to make it easy on
// you you can mix which parts are considered tables from Lua,
// and which parts are considered other kinds of types, such as
// userdata and the like
void demo_explicit(sol::as_table_t<std::map<std::string,
          sol::as_table_t<std::vector<std::string>>>>
          src) {
	std::cout << "demo, explicit sol::as_table_t<...>"
	          << std::endl;
	// Have to access the "source" member variable for
	// as_table_t
	const auto& listmap = src.value();
	SOL_ASSERT(listmap.size() == 2);
	for (const auto& kvp : listmap) {
		// Have to access the internal "source" for the inner
		// as_table_t, as well
		const std::vector<std::string>& strings
		     = kvp.second.value();
		SOL_ASSERT(strings.size() == 3);
		std::cout << "\t" << kvp.first << " = ";
		for (const auto& s : strings) {
			std::cout << "'" << s << "'"
			          << " ";
		}
		std::cout << std::endl;
	}
	std::cout << std::endl;
}
int main(int, char**) {
	std::cout << "=== containers retrieved from lua tables ==="
	          << std::endl;
	sol::state lua;
	// bind the function
	lua.set_function("f", &demo);
	lua.set_function("g", &demo_explicit);
	// Call it with a table that has string sequences set to
	// distinct keys
	lua.script(R"(
t = { 
	key1 = {'hello', 'there', 'world'},
	key2 = {'bark', 'borf', 'woof'}
}
f(t)
g(t)
	)");
	std::cout << std::endl;
	return 0;
}

