// A reference wrapper for a sub-vector of fixed size
template <typename T, size_t N>
class vector_ref {
private:
    T* data;
    size_t size;

public:
    // Constructor to initialize with raw pointer and size
    vector_ref(T* data, size_t size) : data(data), size(size) {}

    // Assignment operator: copy elements from another vector_ref
    vector_ref& operator=(const vector_ref& other) {
        for (size_t i = 0; i < size; ++i) {
            data[i] = other.data[i];
        }
        return *this;
    }

    // Addition operator: element-wise addition
    vector_ref operator+(const vector_ref& other) const {
        vector_ref result(*this);
        for (size_t i = 0; i < size; ++i) {
            result.data[i] += other.data[i];
        }
        return result;
    }
};

int main() {
