    vector_ref<float, 4> v1(&m1[0], 4);

    // v2 refers to elements starting at index 2 (overlapping with v1)
    vector_ref<float, 4> v2(&m1[2], 4);

    // Perform arithmetic: v2 becomes v1 + v2
    v2 = v1 + v2;

