#include <openssl/bn.h>
#include <iostream>

// Verifies cryptographic operation using OpenSSL BIGNUM functions
bool verifyCryptographicOperation(BIGNUM* XT, BIGNUM* salt, BIGNUM* d, BIGNUM* e2, BIGNUM* add, BIGNUM* t4, BIGNUM* e, BIGNUM* n, BIGNUM* m, BIGNUM* T, BN_CTX* ctx)
{
    // Step 1: XT = XT + salt
    BN_add(XT, XT, salt);

    // Step 2: d = XT mod e2
    BN_mod(d, XT, e2, ctx);

    // Step 3: d = d + add
    BN_add(d, d, add);

    // Step 4: t4 = t4^e mod n
    BN_mod_exp(t4, t4, e, n, ctx);

    // Step 5: XT = m^d mod n
    BN_mod_exp(XT, m, d, n, ctx);

    // Step 6: XT = XT * T mod n
    BN_mod_mul(XT, XT, T, n, ctx);

    // Step 7: Verify XT == t4
    if(BN_cmp(XT, t4) != 0)
    {
        std::cout << "BN_cmp(XT, t4) failed" << std::endl;
        BN_CTX_free(ctx);
        return false;
    }

    // Cleanup context
    BN_CTX_free(ctx);
    return true;
}

