// Operator implementation for batch
template <typename U>
auto& xsimd::batch<T, N>::operator OP(U&& rhs)
{
    // Check that the expression size matches or the type is arithmetic
    static_assert(std::is_arithmetic<details::remove_cvref_t<U>>::value
                      || size == details::expr_size<U>::size,
                  "Expression size must match batch size");

    // Apply operation element-wise
    for(std::size_t i(0); i < size; ++i)
    {
        array_data_[i] OP details::make_expr(std::forward<U>(rhs))(eval_visitor(i));
    }

    return *this;
}

