    {
        return ypos;
    }

    // Method to set angle
    void setTheta(double angle)
    {
        theta = angle;
    }

    // Method to get angle
    double getTheta() const
    {
        return theta;
    }

    // Method to move the position by a given distance in a given direction
    void move(double distance, double direction)
    {
        xpos += distance * cos(direction);
        ypos += distance * sin(direction);
    }
};

