// Calculates edge scores based on selection and attributes
std::vector<double> calculateEdgeScores(const Graph& G, 
                                        const std::vector<double>& attribute0, 
                                        const std::vector<double>& attribute1, 
                                        const std::vector<bool>& selection) 
{
    std::vector<double> scoreData;

    // Check if edges are indexed
    if (!G.hasEdgeIds()) 
    {
        throw std::runtime_error("edges have not been indexed - call indexEdges first");
    }

    // Resize score data to accommodate all edge IDs
    scoreData.resize(G.upperEdgeIdBound());

    // Process edges in parallel
    G.parallelForEdges([&](node u, node v, edgeid eid) 
    {
        // Assign score based on selection flag
        scoreData[eid] = (selection[eid] ? attribute1[eid] : attribute0[eid]);
    });

    // Return computed scores
    return scoreData;

}

