// Define a struct to hold the parsed command-line options
struct CommandLineOptions {
    std::string scriptFileName;
    std::vector<std::string> inlineStrings;
    int testNumber;
    bool is3D;
    bool runDiffTest;
    double diffTestPerturbationScale;
};

// Function to parse the command-line arguments and store the values
CommandLineOptions parseCommandLineArguments(int argc, char* argv[])
{
    CommandLineOptions options;

    // Define a map to store the option flags and corresponding variables
    std::unordered_map<std::string, std::pair<void*, std::string>> optionMap = {
        {"-script", {&options.scriptFileName, "Lua script to read for initial data"}},
        {"-i", {&options.inlineStrings, "Append string to script"}},
        {"-test", {&options.testNumber, "Test number (non-lua test)"}},
        {"--3d", {&options.is3D, "Dimension is 3(non-lua test)"}},
        {"--run_diff_test", {&options.runDiffTest, "Run diff test (non-lua test)"}},
        {"-dtps", {&options.diffTestPerturbationScale, "diff_test_perturbation_scale (non-lua test)"}}
    };

    // Iterate through the command-line arguments and parse the options
    for (int i = 1; i < argc; ++i)
    {
        std::string arg = argv[i];

        if (optionMap.find(arg) != optionMap.end())
        {
            if (arg == "-i")
            {
                if (i + 1 < argc && argv[i + 1][0] != '-')
                {
                    ((std::vector<std::string>*)optionMap[arg].first)->push_back(argv[i + 1]);
                    ++i;
                }
            }
            else if (arg == "--3d" || arg == "--run_diff_test")
            {
                *((bool*)optionMap[arg].first) = true;
            }
            else
            {
                if (i + 1 < argc && argv[i + 1][0] != '-')
                {
                    if (arg == "-dtps")
                    {
                        *((double*)optionMap[arg].first) = std::stod(argv[i + 1]);
                    }
                    else
                    {
                        *((std::string*)optionMap[arg].first) = argv[i + 1];
                    }
                    ++i;
                }
            }
        }
    }

    return options;
}

int main(int argc, char* argv[])
{
    CommandLineOptions options = parseCommandLineArguments(argc, argv);

    // Use the parsed options for further processing
    std::cout << "Script File Name: " << options.scriptFileName << std::endl;
    std::cout << "Inline Strings: ";
    for (const auto& str : options.inlineStrings)
    {
        std::cout << str << " ";
    }
    std::cout << std::endl;
    std::cout << "Test Number: " << options.testNumber << std::endl;
    std::cout << "Is 3D: " << (options.is3D ? "true" : "false") << std::endl;
    std::cout << "Run Diff Test: " << (options.runDiffTest ? "true" : "false") << std::endl;
    std::cout << "Diff Test Perturbation Scale: " << options.diffTestPerturbationScale << std::endl;

    return 0;
}

