    return {v1.x + v2.x, v1.y + v2.y};
}

// Subtraction operator for Vector2
template <typename T>
Vector2<T> operator-(const Vector2<T>& v1, const Vector2<T>& v2) {
#ifdef RM_MATH_STAT
    PROFILE_FUNCTION();
#endif
    return {v1.x - v2.x, v1.y - v2.y};
}

// Dot product function
template <typename T>
T dotProduct(const Vector2<T>& v1, const Vector2<T>& v2) {
#ifdef RM_MATH_STAT
    PROFILE_FUNCTION();
#endif
    return v1.x * v2.x + v1.y * v2.y;
}

// Cross product function (2D scalar result)
template <typename T>
T crossProduct(const Vector2<T>& v1, const Vector2<T>& v2) {
#ifdef RM_MATH_STAT
    PROFILE_FUNCTION();
#endif
    return v1.x * v2.y - v1.y * v2.x;
}

// Normalize a vector
template <typename T>
Vector2<T> normalize(const Vector2<T>& v) {
#ifdef RM_MATH_STAT
    PROFILE_FUNCTION();
#endif
    T magnitude = std::sqrt(v.x * v.x + v.y * v.y);
    return {v.x / magnitude, v.y / magnitude};
}

// Magnitude (length) of a vector
template <typename T>
T magnitude(const Vector2<T>& v) {
#ifdef RM_MATH_STAT
    PROFILE_FUNCTION();
#endif
    return std::sqrt(v.x * v.x + v.y * v.y);
}

