// Node structure for the stack
struct Node {
    int val;
    int min;
    Node* next;
    // Constructor to initialize node
    Node(int x, int m, Node* n) : val(x), min(m), next(n) {}
};

// MinStack class implementation
class MinStack {
private:
    Node* topNode;  // Pointer to the top of the stack

public:
    // Constructor initializes empty stack
    MinStack() {
        topNode = nullptr;
    }

    // Push element onto stack while tracking minimum
    void push(int x) {
        if (topNode == nullptr) {
            topNode = new Node(x, x, nullptr);
        } else {
            topNode = new Node(x, std::min(x, topNode->min), topNode);
        }
    }

    // Pop element from stack
    void pop() {
        assert(topNode != nullptr);  // Ensure stack is not empty
        Node* temp = topNode;
        topNode = topNode->next;
        delete temp;
    }

    // Return top element
    int top() {
        assert(topNode != nullptr);  // Ensure stack is not empty
        return topNode->val;
    }

    // Return minimum element in the stack
    int getMin() {
        assert(topNode != nullptr);  // Ensure stack is not empty
        return topNode->min;
    }
};

// Main function to demonstrate MinStack functionality
int main() {
    MinStack stack;

    // Push elements onto the stack
    stack.push(5);
    stack.push(3);
    stack.push(7);
    stack.push(2);

    // Display current top and minimum
    std::cout << "Top element: " << stack.top() << std::endl;  // Output: 2
    std::cout << "Minimum element: " << stack.getMin() << std::endl;  // Output: 2

    // Pop one element and check updated values
    stack.pop();
    std::cout << "Top element after pop: " << stack.top() << std::endl;  // Output: 7
    std::cout << "Minimum element after pop: " << stack.getMin() << std::endl;  // Output: 3

    return 0;
}

