{
    double precision, recall, sum, score;
    std::cin >> precision >> recall >> sum >> score;
    // Output results with high precision
    std::cout << std::setprecision(9) << harmonic_mean(precision, recall) / sum << '\n'
              << score / sum << '\n';
    return 0;

}

