    // Flushes all buffered colors to the output stream
    void flush() {
        for (const auto& color : m_colorBuffer) {
            if (m_useStandardOutput) {
                std::cout << std::get<0>(color) << " " << std::get<1>(color) << " " << std::get<2>(color) << "\n";
