#include <type_traits>

// Helper template to define a type list
template<typename...>
struct list {};

// Comparison template: returns true if sizeof(T) < sizeof(U)
template<typename T, typename U>
struct less : std::integral_constant<bool, sizeof(T) < sizeof(U)> {};

// Forward declaration for the merge implementation
template<typename...>
struct _merge_impl;

// Base case: first list empty, second list non-empty
template<typename... ys>
struct _merge_impl<list<>, list<ys...>, list<ys...>, less>
{};

// Base case: second list empty, first list non-empty
template<typename... xs>
struct _merge_impl<list<xs...>, list<>, list<xs...>, less>
{};

// Recursive case: both lists non-empty
template<typename x, typename... xt, typename y, typename... yt, typename... zs, typename cmp>
struct _merge_impl<list<x, xt...>, list<y, yt...>, list<zs...>, cmp>
    : std::conditional_t<cmp::template apply<x, y>::value,
                        _merge_impl<list<xt...>, list<y, yt...>, list<zs..., x>, cmp>,
                        _merge_impl<list<x, xt...>, list<yt...>, list<zs..., y>, cmp>>
{};

int main()
{
    // Merge two sorted lists of types based on size comparison
    using merged_list = _merge_impl<list<1, 3, 5>, list<2, 4, 6>, list<>, less>::type;
    // merged_list is now list<1, 2, 3, 4, 5, 6>
    return 0;
}

#include <queue>
#include <mutex>
#include <condition_variable>
#include <memory>

// Thread-safe queue implementation
template <typename T>
class ThreadSafeQueue {
public:
    // Pushes a value into the queue
    void push(const T& value) {
        std::unique_lock<std::mutex> lock(mutex);
        queue.push(value);
        lock.unlock();
        condition.notify_one();
    }

    // Pops and returns a shared pointer to the front element
    std::shared_ptr<T> pop() {
        std::unique_lock<std::mutex> lock(mutex);
        condition.wait(lock, [this] { return !queue.empty(); });
        auto value = std::make_shared<T>(queue.front());
        queue.pop();
        return value;
    }

private:
    std::queue<T> queue;
    std::mutex mutex;
    std::condition_variable condition;
};

