    // Reverses the input string
    std::string reverseString(const std::string& input)
    {
        std::string reversed = input;  // Create a copy of the input string
        int left = 0;                  // Pointer to the beginning of the string
        int right = reversed.length() - 1;  // Pointer to the end of the string

        while (left < right)
        {
            // Swap characters at the left and right pointers
            char temp = reversed[left];
            reversed[left] = reversed[right];
            reversed[right] = temp;

            // Move the pointers towards each other
            left++;
            right--;
        }

        return reversed;  // Return the reversed string
    }

}  // namespace cudf::test

