// Main function to process matrix traversal
int main()
{
    int n, k;
    cin >> n;

    // Declare 2D array with size (n+1)x(n+1)
    int a[n+1][n+1];

    // Read matrix elements
    for(int i=1; i<=n; i++)
        for(int j=1; j<=n; j++)
            cin >> a[i][j];

    // Extract elements in specific pattern
    int x = 0;
    int v[n*n+1];

    // First segment
    for(int i=1; i<=n/2; i++) {
        x++;
        v[x] = a[i][n/2-i+1];
    }

    // Second segment
    for(int i=1; i<=n/2; i++) {
        x++;
        v[x] = a[n/2+i][i];
    }

    // Third segment
    for(int i=1; i<=n/2; i++) {
        x++;
        v[x] = a[n-i+1][n/2+i];
    }

    // Fourth segment
    for(int i=1; i<=n/2; i++) {
        x++;
        v[x] = a[n/2-i+1][n-i+1];
    }

    // Read rotation parameter
    cin >> k;

    // Output rotated sequence
    for(int i=k+1; i<=x; i++)
        cout << v[i] << " ";
    for(int i=1; i<=k; i++)
        cout << v[i] << " ";

    return 0;
}

