// Define the MSRIO class
class MSRIO {
public:
    virtual void write_msr(int cpu, uint64_t offset, uint64_t value, uint64_t mask) = 0;
};

// Define the MSR class
class MSR {
public:
    enum m_function {
        M_FUNCTION_SCALE
    };
};

// Define the MSRFieldControl class
class MSRFieldControl {
public:
    MSRFieldControl(std::shared_ptr<MSRIO> msrio, int cpu, uint64_t offset,
                    int begin_bit, int end_bit, MSR::m_function function, double scalar)
        : m_msrio(msrio), m_cpu(cpu), m_offset(offset), m_begin_bit(begin_bit),
          m_end_bit(end_bit), m_function(function), m_scalar(scalar) {}

    void write(double value) {
        // Perform the necessary operations to write the value to the specified MSR field
        uint64_t mask = (1ULL << (m_end_bit - m_begin_bit + 1)) - 1;
        uint64_t field_value = static_cast<uint64_t>(value / m_scalar);
        field_value <<= m_begin_bit;
        mask <<= m_begin_bit;
        m_msrio->write_msr(m_cpu, m_offset, field_value, mask);
    }

private:
    std::shared_ptr<MSRIO> m_msrio;
    int m_cpu;
    uint64_t m_offset;
    int m_begin_bit;
    int m_end_bit;
    MSR::m_function m_function;
    double m_scalar;
};

