void velocityCallback(const geometry_msgs::Twist::ConstPtr& msg)
{
    // Extract linear and angular velocities from the message
    double linear_velocity = msg->linear.x;
    double angular_velocity = msg->angular.z;

    // Compute control command using proportional control
    // Note: k_linear and k_angular should be defined or passed appropriately
    double control_command = k_linear * linear_velocity + k_angular * angular_velocity;

    // Advertise and publish control command
    ros::NodeHandle nh;
    ros::Publisher control_pub = nh.advertise<std_msgs::Float64>("/control_commands", 1);
    std_msgs::Float64 control_msg;
    control_msg.data = control_command;
    control_pub.publish(control_msg);
}

