#include <unistd.h>  // For sysconf

// Calculates CPU utilization for a given process ID
float LinuxParser::CpuUtilization(int pid)
{
    long activeJiffies = LinuxParser::ActiveJiffies(pid);
    long uptime = LinuxParser::UpTime();

    // Convert jiffies to seconds
    long total_time = activeJiffies / sysconf(_SC_CLK_TCK);  
    // Time the process has been running (in seconds)
    float seconds = uptime - (LinuxParser::UpTime(pid) / sysconf(_SC_CLK_TCK));  

    // Calculate CPU utilization percentage
    float cpu_utilization = 100.0 * ((total_time / seconds) / sysconf(_SC_NPROCESSORS_ONLN));  

    return cpu_utilization;
}

