// TaskScheduler class definition
class TaskScheduler {
public:
    // Constructor initializes counter to 0
    TaskScheduler() : counter(0) {}

    // Schedule a task to be executed later
    void schedule(const std::function<void()>& task) {
        std::unique_lock<std::mutex> lock(mutex);
        tasks.push_back(task);
    }

    // Execute all scheduled tasks concurrently
    void execute() {
        std::vector<std::thread> threads;

        // Launch threads for each task
        for (int i = 0; i < tasks.size(); ++i) {
            threads.emplace_back([this, i] {
                std::unique_lock<std::mutex> lock(mutex);

                // Execute the task if it exists
                if (i < tasks.size()) {
                    tasks[i]();
                    ++counter;
                }

                // Notify waiting threads
                cv.notify_one();
            });
        }

        // Wait for all threads to complete
        for (auto& t : threads) {
            t.join();
        }
    }

    // Get the number of executed tasks
    int getCounter() const {
        return counter;
    }

private:
    std::vector<std::function<void()>> tasks;
    std::mutex mutex;
    std::condition_variable cv;
    int counter;
};

// Main function
int main() {
    TaskScheduler scheduler;

    // Schedule tasks
    scheduler.schedule([] { std::cout << "Task 1 executed" << std::endl; });
    scheduler.schedule([] { std::cout << "Task 2 executed" << std::endl; });
    scheduler.schedule([] { std::cout << "Task 3 executed" << std::endl; });

    // Execute tasks concurrently
    scheduler.execute();

    // Verify the counter
    std::cout << "Total tasks executed: " << scheduler.getCounter() << std::endl;

    return 0;
}

