std::tuple<int, int, int> getHighestResolutionMode(const std::vector<std::tuple<int, int, int>>& videoModes)
{
    // Initialize with the first mode
    std::tuple<int, int, int> highestMode = videoModes[0];

    for(const auto& mode : videoModes)
    {
        // Check for higher resolution
        if(std::get<0>(mode) > std::get<0>(highestMode) || 
           // Check for same resolution but higher refresh rate
           (std::get<0>(mode) == std::get<0>(highestMode) && std::get<1>(mode) > std::get<1>(highestMode)) || 
           // Check for same resolution and refresh rate but higher depth
           (std::get<0>(mode) == std::get<0>(highestMode) && std::get<1>(mode) == std::get<1>(highestMode) && std::get<2>(mode) > std::get<2>(highestMode)))
        {
            // Update highest mode
            highestMode = mode;
        }
    }

    return highestMode;
}

