            };
            namespace util {
                class Converter {
                    // Class implementation
                };
            }
        }
    )";

    // Search for nested namespaces and classes using regex
    std::smatch match;
    std::string::const_iterator searchStart(codeSnippet.cbegin());
    while (std::regex_search(searchStart, codeSnippet.cend(), match, nestedRegex))
    {
        nestedElements.push_back(match[1]);
        searchStart = match.suffix().first;
    }

    return nestedElements;
}

int main()
{
    std::vector<std::string> result = extractNestedElements("osquery");

    // Print each extracted element
    for (const auto& element : result)
    {
        std::cout << element << std::endl;
    }

    return 0;
}

