    Screen(int id) : id(id) {}
    virtual void display() = 0;
    int getId() const { return id; }
private:
    int id;
};

// App class managing screens
class App {
public:
    // Add a screen to the map
    void addScreen(Screen* screen) {
        screens[screen->getId()] = screen;
    }

    // Remove a screen by ID and delete it
    void removeScreen(int id) {
        auto it = screens.find(id);
        if (it != screens.end()) {
            delete it->second;
            screens.erase(it);
        }
    }

    // Display a screen by ID
    void showScreen(int id) {
        auto it = screens.find(id);
        if (it != screens.end()) {
            it->second->display();
        } else {
            std::cout << "Screen not found" << std::endl;
        }
    }

    // Destructor: clean up all remaining screens
    ~App() {
        for (auto& pair : screens) {
            delete pair.second;
        }
    }

private:
    std::unordered_map<int, Screen*> screens;
};

