// DnsProvisionerVubercool implementation

void DnsProvisionerVubercool::provisionHostname(const string &hostname, const cb_t& onDone)
{
    int retries = 3; // Maximum number of retries allowed
    provisionWithRetries(hostname, onDone, retries);
}

void DnsProvisionerVubercool::provisionWithRetries(const string &hostname, const cb_t& onDone, int retries)
{
    client_->Post("https://"s + config_.host + "/zone/" + hostname,
                  [this, hostname, onDone, retries](Response& response) {
                      if (response.success) {
                          // Provisioning successful
                          onDone(true);
                      } else {
                          if (retries > 0) {
                              // Retry provisioning with decremented retry count
                              provisionWithRetries(hostname, onDone, retries - 1);
                          } else {
                              LOG_ERROR << "Failed to provision hostname (no more retries left): " << hostname;
                              onDone(false); // Provisioning failed after exhausting all retries
                          }
                      }
                  });
}

void DnsProvisionerVubercool::deleteHostname(const string &hostname, const cb_t& onDone)
{
    client_->Delete("https://"s + config_.host + "/zone/" + hostname,
                    [onDone](Response& response) {
                        onDone(response.success); // Call onDone with deletion success status
                    });
}

