#include <string>
#include <algorithm>

// Solution class for shortest distance to character
class Solution
{
public:
    std::vector<int> shortestToChar(std::string &s, char c)
    {
        // Initialize result array with maximum possible distance
        std::vector<int> res(s.size(), s.size());

        // Initialize position of last occurrence of character c
        int pos = -s.size();

        // Traverse from left to right
        for(int i=0; i<s.size(); ++i)
        {
            if(s[i] == c)
                pos = i;

            // Update minimum distance
            res[i] = std::min(res[i], std::abs(i - pos));
        }

        // Traverse from right to left
        for(int i=s.size()-1; i>=0; --i)
        {
            if(s[i] == c)
                pos = i;

            // Update minimum distance
            res[i] = std::min(res[i], std::abs(i - pos));
        }

        return res;
    }
};

