// Updates particle positions and removes expired particles
void ParticleEmitter::updateParticles(float dt)
{
    for(auto it = particles.begin(); it != particles.end();)
    {
        // Update position based on velocity
        it->x += it->vx * dt;
        it->y += it->vy * dt;
        // Reduce remaining lifetime
        it->lifetime -= dt;
        if(it->lifetime <= 0.0f)
        {
            // Remove particle if lifetime has expired
            it = particles.erase(it);
        }
        else
        {
            ++it;
        }
    }
}

