// Template struct for codec mapping
template <typename T>
struct codec_map {
    // Decode function to populate a map from protobuf stream
    static bool decode(pb_istream_t *stream, const pb_field_t *field, void **arg) {
        // Cast the argument to the expected map type
        auto *mapping = static_cast<std::map<typename T::KeyType, typename T::ValueType> *>(*arg);

        // Create a temporary entry for decoding
        T map_entry;

        // Attempt to decode the protobuf message into the entry
        if (!pb_decode(stream, field, &map_entry)) {
            return false;  // Decoding failed
        }

        // Insert the decoded key-value pair into the map
        mapping->insert(std::make_pair(map_entry.key, map_entry.value));

        return true;  // Success
    }
};

