// Binary tree class definition
class BinaryTree {
private:
    // Node structure for the binary tree
    struct Node {
        int value;
        Node* left;
        Node* right;
        Node(int val) : value(val), left(nullptr), right(nullptr) {}
    };
    Node* root;

    // Helper method to recursively construct the binary tree
    Node* constructTreeHelper(const std::vector<int>& values, int index) {
        if (index < values.size()) {
            Node* newNode = new Node(values[index]);
            newNode->left = constructTreeHelper(values, 2 * index + 1);
            newNode->right = constructTreeHelper(values, 2 * index + 2);
            return newNode;
        }
        return nullptr;
    }

public:
    // Public method to construct the binary tree
    void constructTree(const std::vector<int>& values) {
        root = constructTreeHelper(values, 0);
    }

    // Type conversion operator to unsigned int
    operator unsigned int() {
        return root->value;
    }
};

int main() {
    BinaryTree tree;
    tree.constructTree({1, 2, 3, 4, 5, 6, 7});

    // Implicit conversion to unsigned int
    unsigned int rootValue = tree;

    std::cout << "Root value: " << rootValue << std::endl;
    return 0;
}

