// Function to manipulate vector based on M and N
std::vector<std::pair<int, int>> manipulateVector(int M, int N)
{
    std::vector<std::pair<int, int>> ans;
    int L = 1;

    // Process while M + 1 > 0
    while(M + 1 > 0)
    {
        --M;
        ans.push_back({++L, ++L});
    }

    // Add final pair
    ans.push_back({1, ++L});

    // Check if size exceeds N
    if(ans.size() > N) return {};

    // Fill up to N elements
    while(ans.size() < N)
    {
        ans.push_back({++L, ++L});
    }

    return ans;
}

