#include <glm/glm.hpp>
#include <glm/gtc/matrix_transform.hpp>

// Applies rotations to a 3D position
glm::vec3 applyRotations(const glm::vec3& initialPosition, float ry, float rz)
{
    // Create rotation matrices for Y and Z axes
    glm::mat4 roty = glm::rotate(glm::mat4(1.0f), glm::radians(ry), glm::vec3(0.0f, 1.0f, 0.0f));
    glm::mat4 rotz = glm::rotate(glm::mat4(1.0f), glm::radians(rz), glm::vec3(0.0f, 0.0f, 1.0f));

    // Convert initial position to homogeneous coordinates
    glm::vec4 position4(initialPosition, 1.0f);

    // Apply rotations: first around Y, then around Z
    position4 = rotz * roty * position4;

    // Convert back to 3D vector and return
    return glm::vec3(position4);
}

#include <mutex>
#include <stack>

// Base class to prevent copying
class Uncopyable {
protected:
    Uncopyable() {}
    ~Uncopyable() {}
private:
    Uncopyable(const Uncopyable&);
    Uncopyable& operator=(const Uncopyable&);
};

// Critical section wrapper using std::mutex
class CriticalSection {
public:
    void Lock() {
        mutex.lock();
    }
    void Unlock() {
        mutex.unlock();
    }
private:
    std::mutex mutex;
};

// RAII-style scoped lock for CriticalSection
class ScopedLock : private Uncopyable {
public:
    ScopedLock(CriticalSection& criticalSection)
        : cs(criticalSection) {
        REF_CHECK(criticalSection);
        cs.Lock();
    }
    ~ScopedLock() {
        cs.Unlock();
    }
private:
    CriticalSection& cs;
};

// Thread-safe stack implementation
template <typename T>
class ThreadSafeStack {
public:
    void Push(const T& value) {
        ScopedLock lock(cs);
        data.push(value);
    }
    bool Pop(T& value) {
        ScopedLock lock(cs);
        if (data.empty()) {
            return false;
        }
        value = data.top();
        data.pop();
        return true;
    }
    bool IsEmpty() {
        ScopedLock lock(cs);
        return data.empty();
    }
private:
    std::stack<T> data;
    CriticalSection cs;
};

#include <functional>

// Computes the integral using the trapezoidal rule
double trapezoidalIntegral(std::function<double(double)> f, double a, double b, int N)
{
    double h = (b - a) / N;  // Width of each subinterval
    double sum = 0.5 * (f(a) + f(b));  // Initialize sum with the first and last function evaluations

    for(int i=1;i<N;++i)
    {
        double x = a + i * h;  // Calculate the x value for the current subinterval
        sum += f(x);  // Add the function value at x to the sum
    }

    // Return the approximate integral value
    return h * sum;
}

