template <typename T>
struct AristaDirigida {
    size_t elem;
    T weight;
};

// Graph class using adjacency list representation
template <typename T>
class Graph {
    std::vector<std::vector<AristaDirigida<T>>> adjacencyList;
public:
    // Constructor to initialize graph with given number of vertices
    Graph(size_t vertices) : adjacencyList(vertices) {}

    // Add an edge from 'from' vertex to 'to' vertex with given weight
    void addEdge(size_t from, size_t to, T weight) {
        adjacencyList[from].push_back({to, weight});
    }

    // Get adjacency list for a specific vertex
    const std::vector<AristaDirigida<T>>& adj(size_t vertex) const {
        return adjacencyList[vertex];
    }
};

// Relax function - placeholder for Dijkstra's algorithm relaxation step
void relax(const AristaDirigida<size_t>& edge, std::priority_queue<AristaDirigida<size_t>>& pq) {
    // Implement the relax function based on the requirements of the graph traversal algorithm
    // Update the priority queue based on the given edge and the current state of the priority queue
}

// Function to compute seconds (shortest path distance) using modified Dijkstra's algorithm
size_t getSegundos(const Graph<size_t>& graph, std::priority_queue<AristaDirigida<size_t>>& pq, size_t v, size_t destino) {
    // Initialize all distances to -1 (unvisited)
    std::vector<size_t> seconds(graph.adjacencyList.size(), -1);
    seconds[v] = 0; // Distance to source is 0

    while (!pq.empty()) {
        size_t currentVertex = pq.top().elem;
        pq.pop();

        // If we reached destination, return the distance
        if (currentVertex == destino) {
            return seconds[currentVertex];
        }

        // Explore neighbors
        for (const AristaDirigida<size_t>& edge : graph.adj(currentVertex)) {
            size_t newSeconds = seconds[currentVertex] + edge.weight;

            // Update distance if shorter path found
            if (seconds[edge.elem] == -1 || newSeconds < seconds[edge.elem]) {
                seconds[edge.elem] = newSeconds;
                pq.push({edge.elem, newSeconds});
            }
        }
    }

    return -1; // Destination not reachable
}

int main() {
    // Example usage
    Graph<size_t> graph(5);

    // Add edges: from, to, weight
    graph.addEdge(0, 1, 2);
    graph.addEdge(0, 2, 5);
    graph.addEdge(1, 3, 3);
    graph.addEdge(2, 3, 1);
    graph.addEdge(3, 4, 4);

    // Priority queue for Dijkstra's algorithm
    std::priority_queue<AristaDirigida<size_t>> pq;
    pq.push({0, 0}); // Start from vertex 0 with distance 0

    size_t v = 0;      // Current vertex
    size_t destino = 4; // Destination vertex

    // Compute shortest path
    size_t seconds = getSegundos(graph, pq, v, destino);

    std::cout << "Seconds taken to reach the destination: " << seconds << std::endl;

    return 0;
}

