class NetworkingModule : public cSimpleModule
{
  private:
    Ipv6RoutingTable *rt;
    Ipv6NeighbourDiscovery *nd;
    Icmpv6 *icmp;

  protected:
    // Initialize the module and obtain references to other modules
    virtual void initialize() override
    {
        rt = getModuleFromPar<Ipv6RoutingTable>(par("routingTableModule"), this);
        nd = getModuleFromPar<Ipv6NeighbourDiscovery>(par("ipv6NeighbourDiscoveryModule"), this);
        icmp = getModuleFromPar<Icmpv6>(par("icmpv6Module"), this);
        // Your initialization code here
    }

  public:
    // Method to send ICMPv6 echo request
    void sendEchoRequest(const Ipv6Address& destination)
    {
        // Check if the destination is reachable
        if (rt->isReachable(destination))
        {
            // Get the MAC address of the destination
            MacAddress mac = nd->getLinkLayerAddress(destination);
            // Send ICMPv6 echo request
            icmp->sendEchoRequest(destination, mac);
