// Function to read and process a module from the input buffer
// Returns 0 on success, non-zero on error
int ReadModule(char SizeofPtr, const char* Begin, const char* End)
{
    if (Begin == nullptr || End == nullptr || Begin > End)
    {
        std::cerr << "Invalid input buffer pointers" << std::endl;
        return 1;
    }
    if (Begin + 1 > End)
    {
        std::cerr << "Insufficient data to read module size" << std::endl;
        return 1;
    }

    // Read the size of the module from the buffer
    int moduleSize = static_cast<unsigned char>(*Begin);

    // Check if the module size is valid
    if (Begin + moduleSize > End)
    {
        std::cerr << "Invalid module size or incomplete module data" << std::endl;
        return 1;
    }

    // Process the module (placeholder for actual processing logic)
    // Example: Print the module content
    std::cout << "Processing module: ";
    for (int i = 0; i < moduleSize; ++i)
    {
        std::cout << *(Begin + i + 1);  // Output module content
    }
    std::cout << std::endl;

    // Update the Begin pointer to point to the next module
    Begin += moduleSize + 1;

    return 0;  // Return success
}

