#include <set>

class Solution {
public:
    // Set to store remainders (not used in current implementation)
    std::set<int> ss;

    // Returns the length of the smallest repunit divisible by K
    int smallestRepunitDivByK(int K)
    {
        // If K is divisible by 2 or 5, no repunit can be divisible by K
        if (K % 2 == 0 || K % 5 == 0)
        {
            return -1;
        }

        int remainder = 0;

        // Check for lengths from 1 to K
        for (int length = 1; length <= K; length++)
        {
            // Update remainder using modular arithmetic
            remainder = (remainder * 10 + 1) % K;

            // If remainder is 0, we found our answer
            if (remainder == 0)
            {
                return length;
            }
        }

        // No solution found within K iterations
        return -1;
    }
};

#include <windows.h>  // Assuming Windows platform for timer functionality

// DPC class definition
class DPC {
public:
    using FunctionType = void(*)(void*);

    // Constructor
    DPC(FunctionType function, void* context) 
        : function_(function), context_(context), timerId_(0) {}

    // Set timer with specified delay in milliseconds
    void SetTimer(unsigned int delayMs) {
        timerId_ = SetTimer(NULL, 0, delayMs, TimerProc);
    }

    // Cancel the timer if active
    void Cancel() {
        if (timerId_ != 0) {
            KillTimer(NULL, timerId_);
            timerId_ = 0;
        }
    }

    // Destructor - ensures timer is cancelled
    ~DPC() {
        Cancel();
    }

private:
    // Static callback procedure for Windows timer
    static void CALLBACK TimerProc(HWND hwnd, UINT uMsg, UINT_PTR idEvent, DWORD dwTime) {
        DPC* dpc = reinterpret_cast<DPC*>(idEvent);
        dpc->function_(dpc->context_);
    }

    // Member variables
    FunctionType function_;
    void* context_;
    UINT_PTR timerId_;
};

