    void addBook(const Book& book) {
        m_books.push_back(book);
    }

    // Remove a book by title
    void removeBook(const std::string& title) {
        m_books.erase(
            std::remove_if(m_books.begin(), m_books.end(),
                [title](const Book& book) { return book.getTitle() == title; }),
            m_books.end()
        );
    }

    // Calculate total pages in the collection
    int getTotalPages() const {
        int total = 0;
        for (const auto& book : m_books) {
            total += book.getPageCount();
        }
        return total;
    }

    // Get information about a specific book
    std::string getBookInfo(const std::string& title) const {
        for (const auto& book : m_books) {
            if (book.getTitle() == title) {
                return "Author: " + book.getAuthor() + ", Page Count: " + std::to_string(book.getPageCount());
            }
        }
        return "Book not found";
    }

private:
    std::vector<Book> m_books;
};

