#include <iostream>

// SelectivityVector example with Array<Map<int64_t, int64_t>>
int main()
{
    // Create a SelectivityVector for the given number of rows
    SelectivityVector rows{num_rows};

    // Define the type: Array<Map<int64_t, int64_t>>
    auto type = TypeFactory<TypeKind::ARRAY>::create(
        TypeFactory<TypeKind::MAP>::create(BIGINT(), BIGINT()));

    // Create a leaf memory pool
    auto pool = memory::memoryManager()->addLeafPool();

    // Result vector pointer
    VectorPtr result;

    // 1. Ensure the result vector is writable for the selected rows
    BaseVector::ensureWritable(rows, type, pool.get(), result);

    // 2. Define a vector writer for Array<Map<int64_t, int64_t>>
    exec::VectorWriter<Array<Map<int64_t, int64_t>>> vectorWriter;

    // 3. Initialize the writer to write into the result vector
    vectorWriter.init(*result->as<ArrayVector>());

    // Process each selected row
    rows.applyToSelected([&](vector_size_t row) {
        // Set the current row offset
        vectorWriter.setOffset(row);

        // Get the array writer for this row
        auto& arrayWriter = vectorWriter.current();

        // Add first map element with two key-value pairs
        auto& child = arrayWriter.add_item();
        child.emplace(serial(), serial());
        child.emplace(serial(), serial());

        // Add an empty map as second element
        arrayWriter.add_item();

        // Commit the written row
        vectorWriter.commit();
    });

    // Finalize writing all rows
    vectorWriter.finish();

    /****************** Vector Reader **********************/
    // 1. Decode the result vector for the selected rows
    DecodedVector decoded;
    decoded.decode(*result, rows);

    // 2. Define a vector reader for Array<Map<int64_t, int64_t>>
    exec::VectorReader<Array<Map<int64_t, int64_t>>> reader(&decoded);

    std::cout << "Reading Vector: " << std::endl;

    // Read and print each selected row
    rows.applyToSelected([&](vector_size_t row) {
        // Check if the row is null
        if (reader.isSet(row) == false) {
            std::cout << "[]" << std::endl;
            return;
        }

        std::cout << "[";

        // Get the array view for this row
        auto arrayView = reader[row];

        // Iterate over array elements (maps)
        for (const auto& container : arrayView) {
            if (container.has_value()) {
                std::cout << " {";
                // Iterate over key-value pairs in the map
                for (const auto& [k, v] : container.value()) {
                    std::cout << "(" << k << ", "
                              << (v.has_value() ? std::to_string(v.value()) : "") << ")";
                }
                std::cout << "} ";
            } else {
                std::cout << " null ";
            }
        }

        std::cout << "]" << std::endl;
    });

    // Null-free reading when we know there are no nulls
    assert(!decoded.mayHaveNullsRecursive());

    std::cout << "Reading null-free Vector: " << std::endl;

    rows.applyToSelected([&](vector_size_t row) {
        std::cout << "[";

        // Read the row without null checks (faster path)
        auto arrayView = reader.readNullFree(row);

        // Iterate over array elements (now non-optional maps)
        for (const auto& container : arrayView) {
            std::cout << " {";
            // Iterate over key-value pairs (now non-optional values)
            for (const auto& [k, v] : container) {
                std::cout << "(" << k << ", " << v << ")";
            }
            std::cout << "} ";
        }

        std::cout << "]" << std::endl;
    });

    return 0;
}

