/// @brief Reboot machine in either ACPI or by triple faulting.
/// @return nothing it's a reboot.
Void ACPIFactoryInterface::Reboot() {
  asm volatile(
      ".intel_syntax noprefix; "
      "rt_reset_hardware:; "
      "cli; "
      "wait_gate1: ; "
      "in al,0x64 ; "
      "and al,2 ; "
      "jnz wait_gate1 ; "
      "mov al,0x0D1 ; "
      "out 0x64,al ; "
      "wait_gate2: ; "
      "in al,0x64 ; "
      "and al,2 ; "
      "jnz wait_gate2 ; "
      "mov al,0x0FE ; "
      "out 0x60,al ; "
      "xor rax,rax ; "
      "lidt [rax] ; "
      "reset_wait: ; "
      "jmp reset_wait ; "
      ".att_syntax; ");
}

