        MPI_Iprobe(MPI_ANY_SOURCE, MPI_ANY_TAG, MPI_COMM_WORLD, &flag, &status);
        if (flag) {
          // Handle incoming MPI message here when needed
        }

        // Blocking Pop from Queue with 1 second timeout
        auto job = redis.bzpopmax("queue:jobs", 1);
        if (job) {
