class Solution {
public:
    // Finds the first missing positive integer
    int firstMissingPositive(vector<int>& nums)
    {
        int n = nums.size();
        // Mark non-positive and out-of-range numbers
        for(int i=0;i<n;i++)
        {
            if(nums[i]<=0 || nums[i]>n+1)
            {
                nums[i] = n+1;
            }
        }
        // Mark indices corresponding to present numbers
        for(int i=0;i<n;i++)
        {
            int index = abs(nums[i]);
            if(index>=1 && index<=n)
            {
                nums[index-1] = -abs(nums[index-1]);
            }
        }
        // Find first unmarked index
        for(int i=0;i<n;i++)
        {
            if(nums[i]>0)
            {
                return i+1;
            }
        }
        // If all positions are marked, return n+1
        return n+1;
    }
};

#include <iostream>
