// Main function to parse URDF file
int main(int argc, char** argv)
{
    // Check command line arguments
    if (argc != 2)
    {
        fprintf(stderr, "Usage: %s <urdf>\n", argv[0]);
        return 1;
    }

    // Infinite loop for parsing
    while (true)
    {
        std::string xml_string;
        std::fstream xml_file(argv[1], std::fstream::in);

        // Read file content line by line
        while (xml_file.good())
        {
            std::string line;
            std::getline(xml_file, line);
            xml_string += (line + "\n");
        }

        xml_file.close();

        // Parse the URDF string
        urdf::parseURDF(xml_string);
    }

    return 0;
}

#include <vector>
#include <stack>

// Solution class for daily temperatures problem
class Solution {
public:
    // Function to compute the number of days until a warmer temperature
    vector<int> dailyTemperatures(vector<int>& temp) {
        stack<int> st;
        int n = temp.size();
        vector<int> ans(n);

        // Start from the last day
        st.push(n - 1);
        ans[n - 1] = 0;

        // Traverse from right to left
        for (int i = n - 2; i >= 0; --i) {
            // Pop indices with temperature less than or equal to current
            while (!st.empty() && temp[st.top()] <= temp[i]) {
                st.pop();
            }

            // If no warmer day ahead
            if (st.empty()) {
                ans[i] = 0;
            } else {
                // Days until warmer temperature
                ans[i] = st.top() - i;
            }

            // Push current index onto stack
            st.push(i);
        }

        return ans;
    }
};

