{
    // Disable synchronization with C I/O for faster input/output
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int task_type;
    std::cin >> task_type;

    if (task_type == 0)
    {
        solve_small_task();
    }
    else
    {
        solve_large_task();
    }

    return 0;
}

