#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>
#include <iostream>

// Exception handler for Lua script errors
int my_exception_handler(lua_State* L,
     sol::optional<const std::exception&> maybe_exception,
     sol::string_view description) 
{
	// L is the lua state, which you can wrap in a state_view if
	// necessary maybe_exception will contain exception, if it
	// exists description will either be the what() of the
	// exception or a description saying that we hit the
	// general-case catch(...)
	std::cout << "An exception occurred in a function, here's "
	             "what it says ";
	if (maybe_exception) {
		std::cout << "(straight from the exception): ";
		const std::exception& ex = *maybe_exception;
		std::cout << ex.what() << std::endl;
	}
	else {
		std::cout << "(from the description parameter): ";
		std::cout.write(description.data(),
		     static_cast<std::streamsize>(description.size()));
		std::cout << std::endl;
	}
	// you must push 1 element onto the stack to be
	// transported through as the error object in Lua
	// note that Lua -- and 99.5% of all Lua users and libraries
	// -- expects a string so we push a single string (in our
	// case, the description of the error)
	return sol::stack::push(L, description);
}

// Function that throws an exception
void will_throw() {
	throw std::runtime_error("oh no not an exception!!!");
}

int main() {
	std::cout << "=== exception_handler ===" << std::endl;
	sol::state lua;
	lua.open_libraries(sol::lib::base);
	lua.set_exception_handler(&my_exception_handler);
	lua.set_function("will_throw", &will_throw);
	sol::protected_function_result pfr = lua.safe_script(
	     "will_throw()", &sol::script_pass_on_error);
	SOL_ASSERT(!pfr.valid());
	sol::error err = pfr;
	std::cout << err.what() << std::endl;
	std::cout << std::endl;
	return 0;
}

#include <stack>
#include <string>

class Solution {
public:
    // Checks if the input string has valid parentheses
    bool isValid(std::string s) {
        int s1 = s.size();
        // If length is odd, cannot be valid
        if(s1 % 2 != 0) return false;

        std::stack<char> st;

        for(char &c : s) {
            // Push opening brackets
            if(c == '{' || c == '[' || c == '(') {
                st.push(c);
            }
            else {
                // Closing bracket without matching opening
                if(st.empty()) return false;

                // Check for matching pairs
                if((st.top() == '{' && c == '}') ||
                   (st.top() == '[' && c == ']') ||
                   (st.top() == '(' && c == ')')) {
                    st.pop();
                }
                else {
                    return false;
                }
            }
        }

        // All brackets matched if stack is empty
        return st.empty();
    }
};

#include <iostream>

// same goes for classes, unions, enums, etc. - the const-qualification rules are the same for all of them
struct A {};

void f1(A obj);
void f2(const A obj);
void f3(A& ref);
void f4(const A& ref);
void f5(A* ptr);
void f6(const A* ptr);

void f1(A obj)
{
    f1(obj); // ok (recursion)
    f2(obj); // ok
    f3(obj); // ok
    f4(obj); // ok
    f5(&obj); // ok
    f6(&obj); // ok
}

void f2(const A obj)
{
    f1(obj); // ok
    f2(obj); // ok (recursion)
    f3(obj); // compilation error (we can modify obj from f3)
    f4(obj); // ok
    f5(&obj); // compilation error (we can modify obj from f5)
    f6(&obj); // ok
}

void f3(A& ref)
{
    f1(ref); // ok
    f2(ref); // ok
    f3(ref); // ok (recursion)
    f4(ref); // ok
    f5(&ref); // ok
    f6(&ref); // ok
}

void f4(const A& ref)
{
    f1(ref); // ok
    f2(ref); // ok
    f3(ref); // compilation error (we can modify ref from f3)
    f4(ref); // ok (recursion)
    f5(&ref); // compilation error (we can modify ref from f5)
    f6(&ref); // ok
}

void f5(A* ptr)
{
    f1(*ptr); // ok
    f2(*ptr); // ok
    f3(*ptr); // ok
    f4(*ptr); // ok
    f5(ptr); // ok (recursion)
    f6(ptr); // ok
}

void f6(const A* ptr)
{
    f1(*ptr); // ok
    f2(*ptr); // ok
    f3(*ptr); // compilation error (we can modify ptr from f3)
    f4(*ptr); // ok
    f5(ptr); // compilation error (we can modify ptr from f5)
    f6(ptr); // ok (recursion)
}

