namespace {
    int testStatus = 0;

    // Assertion function
    void aSsErT(bool condition, const char *message, int line)
    {
        if (condition) {
            std::cout << "Error " __FILE__ "(" << line << "): " << message
                 << "    (failed)" << std::endl;
            if (0 <= testStatus && testStatus <= 100) {
                ++testStatus;
            }
        }
    }
}  // close unnamed namespace

#define ASSERT(X)                                              \
    aSsErT(!(X), #X, __LINE__);

