#include <cstdlib>
#include <iostream>
#include <boost/bind.hpp>
#include "asio.hpp"

using asio::ip::udp;

// UDP echo server implementation
class server
{
public:
  // Constructor initializes socket and starts async receive
  server(asio::io_context& io_context, short port)
    : socket_(io_context, udp::endpoint(udp::v4(), port))
  {
    // Start asynchronous receive operation
    socket_.async_receive_from(
        asio::buffer(data_, max_length), sender_endpoint_,
        boost::bind(&server::handle_receive_from, this,
          asio::placeholders::error,
          asio::placeholders::bytes_transferred));
  }

  // Handle completion of receive operation
  void handle_receive_from(const asio::error_code& error,
      size_t bytes_recvd)
  {
    if (!error && bytes_recvd > 0)
    {
      // Echo received data back to sender
      socket_.async_send_to(
          asio::buffer(data_, bytes_recvd), sender_endpoint_,
          boost::bind(&server::handle_send_to, this,
            asio::placeholders::error,
            asio::placeholders::bytes_transferred));
    }
    else
    {
      // Continue receiving if error occurred
      socket_.async_receive_from(
          asio::buffer(data_, max_length), sender_endpoint_,
          boost::bind(&server::handle_receive_from, this,
            asio::placeholders::error,
            asio::placeholders::bytes_transferred));
    }
  }

  // Handle completion of send operation
  void handle_send_to(const asio::error_code& /*error*/,
      size_t /*bytes_sent*/)
  {
    // Resume receiving after successful send
    socket_.async_receive_from(
        asio::buffer(data_, max_length), sender_endpoint_,
        boost::bind(&server::handle_receive_from, this,
          asio::placeholders::error,
          asio::placeholders::bytes_transferred));
  }

private:
  udp::socket socket_;
  udp::endpoint sender_endpoint_;
  enum { max_length = 1024 };
  char data_[max_length];
};

// Main function
int main(int argc, char* argv[])
{
  try
  {
    // Check command line arguments
    if (argc != 2)
    {
      std::cerr << "Usage: async_udp_echo_server <port>\n";
      return 1;
    }

    asio::io_context io_context;
    using namespace std; // For atoi.

    // Create server instance with specified port
    server s(io_context, atoi(argv[1]));

    // Run the I/O context to process asynchronous operations
    io_context.run();
  }
  catch (std::exception& e)
  {
    std::cerr << "Exception: " << e.what() << "\n";
  }

  return 0;
}

#include "kml/serdes.hpp"
#include "kml/serdes_binary.hpp"
#include "indexer/classificator_loader.hpp"
#include "coding/file_reader.hpp"
#include "coding/file_writer.hpp"
#include <iostream>

// Main function to convert KMB files to KML format
int main(int argc, char ** argv)
{
    if (argc < 2)
    {
        std::cout << "Converts kmb file(s) to kml\n";
        std::cout << "Usage: " << argv[0] << " path_to_kmb_file [path_to_another_kmb_file...]\n";
        return 1;
    }

    // Load classifier for bookmarks serialization
    classificator::Load();

    do
    {
        std::string filePath = argv[argc - 1];
        kml::FileData kmlData;

        try
        {
            FileReader reader(filePath);
            kml::binary::DeserializerKml des(kmlData);
            des.Deserialize(reader);
        }
        catch (kml::binary::DeserializerKml::DeserializeException const & ex)
        {
            std::cerr << "Error reading kmb file " << filePath << ": " << ex.what() << std::endl;
            return 1;
        }

        try
        {
            // Change extension from .kmb to .kml
            filePath[filePath.size() - 1] = 'l';
            kml::SerializerKml ser(kmlData);
            FileWriter kmlFile(filePath);
            ser.Serialize(kmlFile);
        }
        catch (kml::SerializerKml::SerializeException const & ex)
        {
            std::cerr << "Error encoding to kml file " << filePath << ": " << ex.what() << std::endl;
            return 1;
        }
        catch (FileWriter::Exception const & ex)
        {
            std::cerr << "Error writing to kml file " << filePath << ": " << ex.what() << std::endl;
            return 1;
        }

        std::cout << "Saved converted file as " << filePath << std::endl;
    }
    while (--argc > 1);

    return 0;
}

#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>
#include <iostream>

// Main function for script error handling demonstration
int main(int, char**)
{
    std::cout << "=== script error handling ===" << std::endl;

    sol::state lua;

    std::string code = R"(
bad&$#*$syntax
bad.code = 2
return 24
)";

    /* OPTION 1 */
    // Handling code like this can be robust
    // If you disable exceptions, then obviously you would
    // remove the try-catch branches, and then rely on the
    // `lua_atpanic` function being called and trapping errors
    // there before exiting the application
    {
        // script_default_on_error throws / panics when the
        // code is bad: trap the error
        try
        {
            int value = lua.script(
                code, sol::script_default_on_error);
            // This will never be reached
            std::cout << value << std::endl;
            SOL_ASSERT(value == 24);
        }
        catch (const sol::error& err)
        {
            std::cout << "Something went horribly wrong: "
                      << "thrown error"
                      << "\n\t" << err.what() << std::endl;
        }
    }

    /* OPTION 2 */
    // Use the script_pass_on_error handler
    // this simply passes through the protected_function_result,
    // rather than throwing it or calling panic
    // This will check code validity and also whether or not it
    // runs well
    {
        sol::protected_function_result result
            = lua.script(code, sol::script_pass_on_error);
        SOL_ASSERT(!result.valid());

        if (!result.valid())
        {
            sol::error err = result;
            sol::call_status status = result.status();
            std::cout << "Something went horribly wrong: "
                      << sol::to_string(status) << " error"
                      << "\n\t" << err.what() << std::endl;
        }
    }

    /* OPTION 3 */
    // This is a lower-level, more explicit way to load code
    // This explicitly loads the code, giving you access to any
    // errors plus the load status then, it turns the loaded
    // code into a sol::protected_function which is then called
    // so that the code can run you can then check that too, for
    // any errors The two previous approaches are recommended
    {
        sol::load_result loaded_chunk = lua.load(code);
        SOL_ASSERT(!loaded_chunk.valid());

        if (!loaded_chunk.valid())
        {
            sol::error err = loaded_chunk;
            sol::load_status status = loaded_chunk.status();
            std::cout << "Something went horribly wrong "
                      << "loading the code: "
                      << sol::to_string(status) << " error"
                      << "\n\t" << err.what() << std::endl;
        }
        else
        {
            // Because the syntax is bad, this will never be
            // reached
            SOL_ASSERT(false);

            // If there is a runtime error (lua GC memory
            // error, nil access, etc.) it will be caught here
            sol::protected_function script_func
                = loaded_chunk
                    .get<sol::protected_function>();

            sol::protected_function_result result
                = script_func();

            if (!result.valid())
            {
                sol::error err = result;
                sol::call_status status = result.status();
                std::cout
                    << "Something went horribly wrong "
                       "running the code: "
                    << sol::to_string(status) << " error"
                    << "\n\t" << err.what() << std::endl;
            }
        }
    }

    std::cout << std::endl;
    return 0;
}

