#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>
#include <iostream>

// Simple sol2 version of the below
void simple(sol::this_state ts, sol::this_environment te) 
{
    sol::state_view lua = ts;

    if (te) 
    {
        sol::environment& env = te;
        sol::environment freshenv = lua["freshenv"];
        bool is_same_env = freshenv == env;

        std::cout << "this_environment -- env == freshenv : "
                  << is_same_env << std::endl;
    }

    std::cout << "this_environment -- no environment present"
              << std::endl;
}

// NOTE:
// THIS IS A LOW-LEVEL EXAMPLE, using pieces of sol2
// to facilitate better usage
// It is recommended you just do the simple version, as it is
// basically this code but it is sometimes useful to show the
// hoops you need to jump through to use the Lua C API
void complicated(sol::this_state ts) 
{
    lua_State* L = ts;
    lua_Debug info;

    // Level 0 means current function (this C function, which is
    // useless for our purposes) Level 1 means next call frame
    // up the stack. This is probably the environment we're
    // looking for?
    int level = 1;
    int pre_stack_size = lua_gettop(L);

    if (lua_getstack(L, level, &info) != 1) 
    {
        // failure: call it quits
        std::cout << "error: unable to traverse the stack"
                  << std::endl;
        lua_settop(L, pre_stack_size);
        return;
    }

    // the "f" identifier is the most important here
    // it pushes the function running at `level` onto the stack:
    // we can get the environment from this
    // the rest is for printing / debugging purposes
    if (lua_getinfo(L, "fnluS", &info) == 0) 
    {
        // failure?
        std::cout << "manually -- error: unable to get stack "
                     "information"
                  << std::endl;
        lua_settop(L, pre_stack_size);
        return;
    }

    // Okay, so all the calls worked.
    // Print out some information about this "level"
    std::cout << "manually -- [" << level << "] "
              << info.short_src << ":" << info.currentline
              << " -- " << (info.name ? info.name : "<unknown>")
              << "[" << info.what << "]" << std::endl;

    // Grab the function off the top of the stack
    // remember: -1 means top, -2 means 1 below the top, and so
    // on... 1 means the very bottom of the stack, 2 means 1
    // more up, and so on to the top value...
    sol::function f(L, -1);

    // The environment can now be ripped out of the function
    sol::environment env(sol::env_key, f);

    if (!env.valid()) 
    {
        std::cout << "manually -- error: no environment to get"
                  << std::endl;
        lua_settop(L, pre_stack_size);
        return;
    }

    sol::state_view lua(L);
    sol::environment freshenv = lua["freshenv"];
    bool is_same_env = freshenv == env;

    std::cout << "manually -- env == freshenv : " << is_same_env
              << std::endl;
}

int main() 
{
    std::cout << "=== environment snooping ===" << std::endl;

    sol::state lua;
    sol::environment freshenv(lua, sol::create, lua.globals());
    lua["freshenv"] = freshenv;

    lua.set_function("f", simple);
    lua.set_function("g", complicated);

    lua.script("f()", freshenv);
    lua.script("g()", freshenv);

    std::cout << std::endl;

    return 0;
}

class Solution {
public:
    // Sorts the colors in-place
    void sortColors(vector<int>& nums)
    {
        int n = nums.size();
        int temp;
        for(int i = 0; i < n; ++i)
        {
            for(int j = 0; j < n - i - 1; ++j)
            {
                if(nums[j] > nums[j + 1])
                {
                    temp = nums[j];
                    nums[j] = nums[j + 1];
                    nums[j + 1] = temp;
                }
            }
        }

    }
};

#include "comms/torchcomms/nccl/TorchCommNCCLCCA.hpp"

namespace torch::comms {

// Global function to be registered as a hook
void cachingAllocatorHookFn(
    const c10::cuda::CUDACachingAllocator::TraceEntry& te) {
  // Forward to the singleton instance
  CachingAllocatorHook::getInstance().regDeregMem(te);
}

CachingAllocatorHookImpl& CachingAllocatorHook::getInstance() {
  // Use std::call_once for thread-safe singleton initialization
  // NOLINTNEXTLINE(facebook-hte-std::call_once)
  std::call_once(init_flag_, createInstance);
  return *instance_;
}

DefaultCachingAllocatorHookImpl::DefaultCachingAllocatorHookImpl() {
  // Setup memory registration hooks
  at::globalContext().lazyInitDevice(c10::DeviceType::CUDA);
  registerMemPreHook();
  c10::cuda::CUDACachingAllocator::attachAllocatorTraceTracker(&cachingAllocatorHookFn);
}

void CachingAllocatorHookImpl::registerMemPreHook() {
  // We assume no mem pool and no comm has been created yet, we just loop up the
  // snapshot of the default pool for all devices.
  auto snapshot = c10::cuda::CUDACachingAllocator::snapshot();
  for (const auto& segmentInfo : snapshot.segments) {
    // NOLINTNEXTLINE(performance-no-int-to-ptr)
    void* addr = reinterpret_cast<void*>(segmentInfo.address);
    size_t len = segmentInfo.total_size;
    if (registeredMemMap_.contains(addr)) {
      throw std::runtime_error("Memory already registered with NCCL");
    } else {
      registeredMemMap_.emplace(addr, MemInfo{len, segmentInfo.device});
    }
  }
}

void CachingAllocatorHookImpl::regDeregMem(
    const c10::cuda::CUDACachingAllocator::TraceEntry& te) {
  std::lock_guard<std::mutex> lock(mutex_);
  bool register_mem = te.action_ ==
      c10::cuda::CUDACachingAllocator::TraceEntry::Action::SEGMENT_ALLOC;
  bool unregister_mem = te.action_ ==
      c10::cuda::CUDACachingAllocator::TraceEntry::Action::SEGMENT_FREE;

  if (register_mem) {
    // Memory got allocated, register it with NCCL
    // NOLINTNEXTLINE(performance-no-int-to-ptr)
    void* addr = reinterpret_cast<void*>(static_cast<uintptr_t>(te.addr_));
    size_t len = te.size_;
    if (registeredMemMap_.contains(addr)) {
      throw std::runtime_error("Memory already registered with NCCL");
    } else {
      registeredMemMap_.emplace(addr, MemInfo{len, te.device_});
    }

    // Register the memory through ncclCommRegister and add to commRegHandles_
    for (auto& comm : registeredComms_) {
      if (te.device_ == comm->getDevice().index()) {
        comm->register_address(TorchCommNCCL::AddressWithLen(addr, len));
      }
    }
  } else if (unregister_mem) {
    // Memory got freed, deregister it with NCCL
    // NOLINTNEXTLINE(performance-no-int-to-ptr)
    void* addr = reinterpret_cast<void*>(static_cast<uintptr_t>(te.addr_));
    if (!registeredMemMap_.contains(addr)) {
      throw std::runtime_error("Memory not registered with NCCL");
    } else {
      registeredMemMap_.erase(addr);
    }

    for (auto& comm : registeredComms_) {
      if (te.device_ == comm->getDevice().index()) {
        comm->deregister_address(TorchCommNCCL::Address(addr));
      }
    }
  }
}

void CachingAllocatorHookImpl::registerComm(TorchCommNCCL* comm) {
  std::lock_guard<std::mutex> lock(mutex_);

  // Check if the communicator is already registered
  if (registeredComms_.contains(comm)) {
    throw std::runtime_error("Communicator already registered");
  }

  // Register all memory that has already been allocated
  for (const auto& [addr, mem_info] : registeredMemMap_) {
    if (mem_info.device == comm->getDevice().index()) {
      comm->register_address(TorchCommNCCL::AddressWithLen(addr, mem_info.len));
    }
  }

  registeredComms_.insert(comm);
}

void CachingAllocatorHookImpl::deregisterComm(TorchCommNCCL* comm) {
  std::lock_guard<std::mutex> lock(mutex_);

  if (!registeredComms_.contains(comm)) {
    // Should this be fatal?
    return;
  }

  // De-register all memory that has already been allocated
  for (const auto& [addr, mem_info] : registeredMemMap_) {
    if (mem_info.device == comm->getDevice().index()) {
      comm->deregister_address(TorchCommNCCL::Address(addr));
    }
  }

  registeredComms_.erase(comm);
}

void CachingAllocatorHookImpl::clear() {
  std::lock_guard<std::mutex> lock(mutex_);

  for (auto& comm : registeredComms_) {
    for (const auto& [addr, mem_info] : registeredMemMap_) {
      if (mem_info.device == comm->getDevice().index()) {
        comm->deregister_address(TorchCommNCCL::Address(addr));
      }
    }
  }

  registeredMemMap_.clear();
  registeredComms_.clear();
}

bool CachingAllocatorHookImpl::isCommRegistered(TorchCommNCCL* comm) {
  std::lock_guard<std::mutex> lock(mutex_);
  return registeredComms_.contains(comm);
}

