class Biome;

// Spike centre positions, calculated using
// for(int i=0;i<8;i++)
// {
// int x=40 * Mth::cos(2*(-PI+(PI/8)*i));
// int z=40* Mth::sin(2*(-PI+(PI/8)*i));
// }
TheEndBiomeDecorator::SPIKE TheEndBiomeDecorator::SpikeValA[8] = {
    // The chunk that the spike is in has to be the smallest x and z that any
    // part of it is in a chunk(x,z) will only be post-processed when the chunks
    // (x+1,z), (x,z+1) and (x+1,z+1) are also loaded
    // first two values are the smallest x and z of the chunk that the feature
    // is in - so the centre point minus the radius
    {32,  -16, 40,  0,   2}, // smallest block - 38,-2
    {16,  16,  28,  28,  2}, // smallest block - 26,26
    {-16, 32,  0,   40,  2}, // smallest block - -2,38
    {-32, 16,  -28, 28,  3}, // smallest block - -31,26
    {-48, -16, -40, 0,   3}, // smallest block - -43,-3
    {-32, -32, -28, -28, 3}, // smallest block - -31,-31
    {-16, -48, 0,   -40, 4}, // smallest block - -4,-44
    {16,  -32, 28,  -28, 4}, // smallest block - 24,-32
};

TheEndBiomeDecorator::TheEndBiomeDecorator(Biome* biome)
: BiomeDecorator(biome)
{
    spikeFeature     = new SpikeFeature(Tile::whiteStone_Id);
    endPodiumFeature = new EndPodiumFeature(Tile::whiteStone_Id);
}

void TheEndBiomeDecorator::decorate()
{
    decorateOres();
    // this will only set the y to the top y of the chunks already processed...
    int y = level->getTopSolidBlock(xo + 8, zo + 8);
    if (y > level->GetHighestY()) level->SetHighestY(y);

    // 4J-PB - editing to place 8 spikes in a circle, with increasing height
    // are we within the chunk with a spike?
    for (int i = 0; i < 8; i++)
    {
        if ((xo == SpikeValA[i].iChunkX) && (zo == SpikeValA[i].iChunkZ))
        {
            // in the right chunk
            spikeFeature->placeWithIndex(
                level,
                random,
                SpikeValA[i].x,
                level->GetHighestY(),
                SpikeValA[i].z,
                i,
                SpikeValA[i].radius
            );
        }
    }

    if (xo == 0 && zo == 0)
    {
        std::shared_ptr<EnderDragon> enderDragon =
            std::shared_ptr<EnderDragon>(new EnderDragon(level));
        enderDragon->moveTo(0, 128, 0, random->nextFloat() * 360, 0);
        level->addEntity(enderDragon);
    }

    // end podium radius is 4, position is 0,0, so chunk needs to be the -16,-16
    // one since this guarantees that all chunks required for the podium are
    // loaded
    if (xo == -16 && zo == -16)
    {
        endPodiumFeature->place(level, random, 0, Level::genDepth / 2, 0);
    }
}

#include <ros/ros.h>
#include <grid_map_ros/grid_map_ros.hpp>
#include <grid_map_cv/grid_map_cv.hpp>
#include <cv_bridge/cv_bridge.h>
#include <opencv2/highgui/highgui.hpp>

using namespace grid_map;
using namespace ros;

int main(int argc, char** argv)
{
  // Initialize node and publisher.
  init(argc, argv, "opencv_demo");
  NodeHandle nodeHandle("~");
  Publisher publisher = nodeHandle.advertise<grid_map_msgs::GridMap>("grid_map", 1, true);
  const bool useTransparency = false;

  // Create grid map.
  GridMap map({"original", "elevation"});
  map.setFrameId("map");
  map.setGeometry(Length(1.2, 2.0), 0.01);

  ROS_INFO("Created map with size %f x %f m (%i x %i cells).",
    map.getLength().x(), map.getLength().y(),
    map.getSize()(0), map.getSize()(1));

  // Add data.
  if (!useTransparency) map["original"].setZero();

  grid_map::Polygon polygon;
  polygon.setFrameId(map.getFrameId());

  polygon.addVertex(Position( 0.480,  0.000));
  polygon.addVertex(Position( 0.164,  0.155));
  polygon.addVertex(Position( 0.116,  0.500));
  polygon.addVertex(Position(-0.133,  0.250));
  polygon.addVertex(Position(-0.480,  0.399));
  polygon.addVertex(Position(-0.316,  0.000));
  polygon.addVertex(Position(-0.480, -0.399));
  polygon.addVertex(Position(-0.133, -0.250));
  polygon.addVertex(Position( 0.116, -0.500));
  polygon.addVertex(Position( 0.164, -0.155));
  polygon.addVertex(Position( 0.480,  0.000));

  for (grid_map::PolygonIterator iterator(map, polygon); !iterator.isPastEnd(); ++iterator)
  {
    map.at("original", *iterator) = 0.3;
  }

  // Convert to CV image.
  cv::Mat originalImage;
  if (useTransparency)
  {
    // Note: The template parameters have to be set based on your encoding
    // of the image. For 8-bit images use `unsigned char`.
    GridMapCvConverter::toImage<unsigned short, 4>(map, "original", CV_16UC4, 0.0, 0.3, originalImage);
  }
  else
  {
    GridMapCvConverter::toImage<unsigned short, 1>(map, "original", CV_16UC1, 0.0, 0.3, originalImage);
  }

  // Create OpenCV window.
  cv::namedWindow("OpenCV Demo");

  // Work with copy of image in a loop.
  while (nodeHandle.ok())
  {
    // Initialize.
    ros::Time time = ros::Time::now();
    map.setTimestamp(time.toNSec());

    cv::Mat modifiedImage;
    int blurRadius = 200 - abs((int)(200.0 * sin(time.toSec())));
    blurRadius = blurRadius - (blurRadius % 2) + 1;

    // Apply Gaussian blur.
    cv::GaussianBlur(originalImage, modifiedImage, cv::Size(blurRadius, blurRadius), 0.0, 0.0);

    // Visualize as image.
    cv::imshow("OpenCV Demo", modifiedImage);
    cv::waitKey(40);

    // Convert resulting image to a grid map.
    if (useTransparency)
    {
      GridMapCvConverter::addLayerFromImage<unsigned short, 4>(modifiedImage, "elevation", map, 0.0, 0.3, 0.3);
    }
    else
    {
      GridMapCvConverter::addLayerFromImage<unsigned short, 1>(modifiedImage, "elevation", map, 0.0, 0.3);
    }

    // Publish grid map.
    grid_map_msgs::GridMap message;
    GridMapRosConverter::toMessage(map, message);
    publisher.publish(message);

    ROS_INFO_STREAM("Published image and grid map with blur radius " << blurRadius << ".");
  }

  return 0;
}

#include <iostream>
