#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>
#include <iostream>

struct test {
    static int muh_variable;
};

int test::muh_variable = 25;

// Main function demonstrating static variable binding in sol2
int main()
{
    std::cout << "=== static_variables ===" << std::endl;

    sol::state lua;
    lua.open_libraries();

    // Register usertype with different kinds of static variable bindings
    lua.new_usertype<test>("test",
        "direct", sol::var(2),
        "global", sol::var(test::muh_variable),
        "ref_global", sol::var(std::ref(test::muh_variable))
    );

    // Retrieve direct value (copy)
    int direct_value = lua["test"]["direct"];
    // direct_value == 2
    SOL_ASSERT(direct_value == 2);
    std::cout << "direct_value: " << direct_value << std::endl;

    // Retrieve global values (one by value, one by reference)
    int global = lua["test"]["global"];
    int global2 = lua["test"]["ref_global"];

    // global == 25
    // global2 == 25
    SOL_ASSERT(global == 25);
    SOL_ASSERT(global2 == 25);

    std::cout << "First round of values --" << std::endl;
    std::cout << global << std::endl;
    std::cout << global2 << std::endl;

    // Modify the original static variable
    test::muh_variable = 542;

    // Re-fetch values
    global = lua["test"]["global"];
    // global == 25 (still, because it was captured by value)
    global2 = lua["test"]["ref_global"];
    // global2 == 542 (reflects current value via reference)

    SOL_ASSERT(global == 25);
    SOL_ASSERT(global2 == 542);

    std::cout << "Second round of values --" << std::endl;
    std::cout << "global : " << global << std::endl;
    std::cout << "global2: " << global2 << std::endl;

    std::cout << std::endl;
    return 0;
}

