#include "BufferProcessor.hpp"
#include "Buffer.hpp"
#include "MayaFlux/Journal/Archivist.hpp"

namespace MayaFlux::Buffers {

// Process a buffer with ownership semantics
void BufferProcessor::process(const std::shared_ptr<Buffer>& buffer)
{
    // Check if buffer can be acquired for processing
    if (!buffer->try_acquire_processing())
    {
        MF_RT_ERROR(Journal::Component::Buffers, Journal::Context::BufferProcessing,
            "Buffer is already being processed, skipping processor");
        return;
    }

    // Increment active processing counter
    m_active_processing.fetch_add(1, std::memory_order_acquire);

    try 
    {
        // Execute the processing function
        processing_function(buffer);
    } 
    catch (...) 
    {
        // Release buffer and decrement counter on exception
        buffer->release_processing();
        m_active_processing.fetch_sub(1, std::memory_order_release);
        throw;
    }

    // Release buffer and decrement counter on success
    buffer->release_processing();
    m_active_processing.fetch_sub(1, std::memory_order_release);
}

// Process a buffer without ownership semantics
void BufferProcessor::process_non_owning(const std::shared_ptr<Buffer>& buffer)
{
    // Increment active processing counter
    m_active_processing.fetch_add(1, std::memory_order_acquire);

    try 
    {
        // Execute the processing function
        processing_function(buffer);
    } 
    catch (...) 
    {
        // Decrement counter on exception
        m_active_processing.fetch_sub(1, std::memory_order_release);
        throw;
    }

    // Decrement counter on success
    m_active_processing.fetch_sub(1, std::memory_order_release);
}

}

class Solution {
public:
    // Finds the maximum binary gap
    int binaryGap(unsigned n)
    {
        int d = 0, p = 32;
        for (; n > 0; n &= (n - 1))
        {
            int ctz = countr_zero(n);
            d = max(d, ctz - p);
            p = ctz;
        }
        return d;
    }
};

