#include <vector>
#include <algorithm>

class Solution {
public:
    // Finds the maximum number of content children
    int findContentChildren(vector<int>& g, vector<int>& s)
    {
        int n1 = g.size();
        int n2 = s.size();

        // Sort both arrays
        sort(g.begin(), g.end());
        sort(s.begin(), s.end());

        int i = 0;
        int j = 0;
        int count = 0;

        // Greedy matching
        while(i < n1 && j < n2)
        {
            if(g[i] <= s[j])
            {
                count++;
                i++;
                j++;
            }
            else
            {
                j++;
            }
        }

        return count;      
    }
};

