using namespace ptn;

// Parse JSON recursively with indentation
void parse_json(const json &j, int depth = 0)
{
    match(j)
        .when(
            bind()[is_type(json::value_t::null)] >> print_null(depth))
        .when(
            bind()[is_type(json::value_t::boolean)] >> print_bool(depth))
        .when(
            bind()[is_type(json::value_t::number_integer)] >>
            print_number<int>("int", depth))
        .when(
            bind()[is_type(json::value_t::number_unsigned)] >>
            print_number<unsigned>("uint", depth))
        .when(
            bind()[is_type(json::value_t::number_float)] >>
            print_number<double>("float", depth))
        .when(
            bind()[is_type(json::value_t::string)] >> print_string(depth))
        .when(
            bind()[is_empty_array] >>
            [=](const json &) {
                indent(depth);
                std::cout << "array []\n";
            })
        .when(
            bind()[is_type(json::value_t::array)] >>
            [=](const json &arr) {
                indent(depth);
                std::cout << "array (" << arr.size() << ")\n";
                for(auto &e : arr)
                {
                    parse_json(e, depth + 1);
                }
            })
        .when(
            bind()[has_field("name")] >>
            [=](const json &obj) {
                indent(depth);
                std::cout << "object <named>\n";
                for(auto &&[k, v] : obj.items())
                {
                    indent(depth + 1);
                    std::cout << k << ":\n";
                    parse_json(v, depth + 2);
                }
            })
        .otherwise([=] {
            indent(depth);
            std::cout << "<unknown>\n";
        });
}

#include <asio.hpp>
#include <boost/bind.hpp>
#include <iostream>
#include "logger.hpp"

using asio::ip::tcp;

char read_buffer[1024];

// Handler for asynchronous read operations
void read_handler(const asio::error_code& e,
    std::size_t bytes_transferred, tcp::socket* s)
{
  if (!e)
  {
    std::cout.write(read_buffer, bytes_transferred);
    s->async_read_some(asio::buffer(read_buffer),
        boost::bind(read_handler, asio::placeholders::error,
          asio::placeholders::bytes_transferred, s));
  }
  else
  {
    services::logger logger(s->get_executor().context(), "read_handler");
    std::string msg = "Read error: ";
    msg += e.message();
    logger.log(msg);
  }
}

// Handler for asynchronous connect operations
void connect_handler(const asio::error_code& e, tcp::socket* s)
{
  services::logger logger(s->get_executor().context(), "connect_handler");
  if (!e)
  {
    logger.log("Connection established");
    s->async_read_some(asio::buffer(read_buffer),
        boost::bind(read_handler, asio::placeholders::error,
          asio::placeholders::bytes_transferred, s));
  }
  else
  {
    std::string msg = "Unable to establish connection: ";
    msg += e.message();
    logger.log(msg);
  }
}

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: daytime_client <host>" << std::endl;
      return 1;
    }

    asio::io_context io_context;

    // Set the name of the file that all logger instances will use.
    services::logger logger(io_context, "");
    logger.use_file("log.txt");

    // Resolve the address corresponding to the given host.
    tcp::resolver resolver(io_context);
    tcp::resolver::results_type endpoints =
      resolver.resolve(argv[1], "daytime");

    // Start an asynchronous connect.
    tcp::socket socket(io_context);
    asio::async_connect(socket, endpoints,
        boost::bind(connect_handler,
          asio::placeholders::error, &socket));

    // Run the io_context until all operations have finished.
    io_context.run();
  }
  catch (std::exception& e)
  {
    std::cerr << e.what() << std::endl;
  }

  return 0;
}

