// Main entry point for odometry benchmark
int main(int argc, char** argv)
{
    using namespace small_gicp;

    // Check command-line arguments
    if (argc < 3)
    {
        std::cout << "USAGE: odometry_benchmark <dataset_path> <output_path> [options]" << std::endl;
        std::cout << "OPTIONS:" << std::endl;
        std::cout << "  --visualize" << std::endl;
        std::cout << "  --num_threads <value> (default: 4)" << std::endl;
        std::cout << "  --num_neighbors <value> (default: 20)" << std::endl;
        std::cout << "  --downsampling_resolution <value> (default: 0.25)" << std::endl;
        std::cout << "  --voxel_resolution <value> (default: 2.0)" << std::endl;

        const auto odom_names = odometry_names();
        std::stringstream sst;
        for (size_t i = 0; i < odom_names.size(); i++)
        {
            if (i)
            {
                sst << "|";
            }
            sst << odom_names[i];
        }
        std::cout << "  --engine <" << sst.str() << "> (default: small_gicp)" << std::endl;
        return 0;
    }

    // Parse positional arguments
    const std::string dataset_path = argv[1];
    const std::string output_path = argv[2];

    // Initialize parameters with defaults
    OdometryEstimationParams params;
    std::string engine = "small_gicp";

    // Parse optional arguments
    for (int i = 0; i < argc; i++)
    {
        const std::string arg = argv[i];
        if (arg == "--visualize")
        {
            params.visualize = true;
        }
        else if (arg == "--num_threads")
        {
            params.num_threads = std::stoi(argv[i + 1]);
        }
        else if (arg == "--num_neighbors")
        {
            params.num_neighbors = std::stoi(argv[i + 1]);
        }
        else if (arg == "--downsampling_resolution")
        {
            params.downsampling_resolution = std::stod(argv[i + 1]);
        }
        else if (arg == "--voxel_resolution")
        {
            params.voxel_resolution = std::stod(argv[i + 1]);
        }
        else if (arg == "--engine")
        {
            engine = argv[i + 1];
        }
        else if (arg.size() >= 2 && arg.substr(0, 2) == "--")
        {
            std::cerr << "unknown option: " << arg << std::endl;
            return 1;
        }
    }

    // Print configuration
    std::cout << "SIMD in use=" << Eigen::SimdInstructionSetsInUse() << std::endl;
    std::cout << "dataset_path=" << dataset_path << std::endl;
    std::cout << "output_path=" << output_path << std::endl;
    std::cout << "registration_engine=" << engine << std::endl;
    std::cout << "num_threads=" << params.num_threads << std::endl;
    std::cout << "num_neighbors=" << params.num_neighbors << std::endl;
    std::cout << "downsampling_resolution=" << params.downsampling_resolution << std::endl;
    std::cout << "voxel_resolution=" << params.voxel_resolution << std::endl;
    std::cout << "visualize=" << params.visualize << std::endl;

    // Create odometry estimator
    std::shared_ptr<OdometryEstimation> odom = create_odometry(engine, params);
    if (odom == nullptr)
    {
        return 1;
    }

    // Load KITTI dataset
    KittiDataset kitti(dataset_path);
    std::cout << "num_frames=" << kitti.points.size() << std::endl;
    std::cout << fmt::format("num_points={} [points]", summarize(kitti.points, [](const auto& pts) { return pts.size(); })) << std::endl;

    // Convert to PointCloud format
    auto raw_points = kitti.convert<PointCloud>(true);

    // Estimate trajectory
    std::vector<Eigen::Isometry3d> traj = odom->estimate(raw_points);
    std::cout << "done!" << std::endl;

    // Report performance metrics
    odom->report();

    // Save trajectory to file
    std::ofstream ofs(output_path);
    for (const auto& T : traj)
    {
        for (int i = 0; i < 3; i++)
        {
            for (int j = 0; j < 4; j++)
            {
                if (i || j)
                {
                    ofs << " ";
                }
                ofs << fmt::format("{:.6f}", T(i, j));
            }
        }
        ofs << std::endl;
    }

    return 0;
}

#include <madvoro/Voronoi3D.hpp>
#include <iostream>
#include <vector>

int main(int argc, char *argv[])
{
    // Define bounding box corners
    MadVoro::Vector3D ll(-10, -10, -10); // lower left corner
    MadVoro::Vector3D ur(10, 10, 10);   // upper right corner

    // Create Voronoi diagram
    MadVoro::Voronoi3D diagram(ll, ur);

    // Input points (sites)
    std::vector<MadVoro::Vector3D> points 
    { 
        { -0.115, 4.484, 0.688 },
        { -6.121, 6.335, -9.093 },
        { -5.529, -7.464, 2.459 },
        { -3.448, -7.794, -6.939 },
        { -3.231, 8.213, -7.829 },
        { 5.204, 9.943, 6.175 },
        { -7.018, 7.155, -0.226 },
        { 0.567, 2.263, -0.962 },
        { 9.998, -3.030, 7.772 },
        { 3.811, 6.672, -8.231 },
        { 4.252, -8.460, -2.693 },
        { 5.184, 0.449, -1.665 },
        { -3.333, 3.909, 5.544 },
        { 3.495, -0.703, 5.494 },
        { -4.844, 4.808, -4.166 },
        { 3.016, -0.006, -1.534 },
        { -3.990, -1.579, 0.691 },
        { 6.928, 1.059, 6.088 },
        { 9.439, -6.873, 5.741 },
        { 6.238, -6.793, -4.822 }
    };

    // Get bounding box coordinates
    std::pair<MadVoro::Vector3D, MadVoro::Vector3D> boundingBox = diagram.GetBoxCoordinates();

    // Build the diagram serially
    diagram.Build(points);

    // Output bounding box info
    std::cout << "ll is " << boundingBox.first << ", ur is " << boundingBox.second << std::endl;
    std::cout << "Number of points (sites/cells) is: " << diagram.GetPointNo() << std::endl;

    // Analyze cell for example point (index 3)
    size_t examplePointIdx = 3; // index 3
    const MadVoro::face_vec &faces = diagram.GetCellFaces(examplePointIdx);

    std::cout << "Number of faces of point number " << examplePointIdx 
              << " (" << diagram.GetMeshPoint(examplePointIdx) << ") is " 
              << faces.size() << std::endl;
    std::cout << "The number of neighbors of point number " << examplePointIdx 
              << " is " << faces.size() << std::endl;

    // Get all face vertices
    std::vector<MadVoro::Vector3D> facesVertices = diagram.GetFacePoints();
    std::cout << "And these are the faces: " << std::endl;

    for(const size_t &faceIdx : faces)
    {
        // Compute center of mass for the face
        MadVoro::Vector3D centerOfMass = diagram.FaceCM(faceIdx);

        // Get neighboring points across this face
        const std::pair<size_t, size_t> neighbors = diagram.GetFaceNeighbors(faceIdx);

        // Determine which neighbor is not the current point
        size_t neighborIdx = (neighbors.first == examplePointIdx)? neighbors.second : neighbors.first;

        std::cout << "Face number " << faceIdx 
                  << ", the other side neighbor is point number " << neighborIdx 
                  << " (which is " << diagram.GetMeshPoint(neighborIdx) << ")" << std::endl;

        std::cout << "Vertices of the face are: ";
        for(const size_t &vertexIdx : diagram.GetPointsInFace(faceIdx))
        {
            std::cout << facesVertices[vertexIdx] << ", ";
        }
        std::cout << "\b\b " << std::endl;
    }

    return 0;
}

