using namespace std;

// Custom comparator to sort based on the second element of the pair
bool compare(pair<int, int> a, pair<int, int> b) {
    return a.second < b.second;
}

int main()
{
    // Vector of pairs of integers
    vector<pair<int, int>> v = {{5, 2}, {8, 1}, {4, 3}};

    // Sort the vector in ascending order based on the first element of the pair
    sort(v.begin(), v.end());

    cout << "Sorted vector in ascending order based on first element: ";
    // Iterate over the sorted vector
    for(auto it = v.begin(); it != v.end(); ++it)
    {
        // Print each pair in the sorted vector
        cout << "(" << it->first << ", " << it->second << ") ";
    }
    cout << endl; // print a newline

    // Sort the vector in ascending order based on the second element of the pair using custom comparator
    sort(v.begin(), v.end(), compare);

    cout << "Sorted vector in ascending order based on second element: ";
    // Iterate over the sorted vector
    for(auto it = v.begin(); it != v.end(); ++it)
    {
        // Print each pair in the sorted vector
        cout << "(" << it->first << ", " << it->second << ") ";
    }
    cout << endl; // print a newline

    return 0;
}

