// Creates an InputStreamReader that uses the default charset.
// Parameters:
// in - An InputStream
InputStreamReader::InputStreamReader(InputStream* in)
: stream(new DataInputStream(in)) {}

// Closes the stream and releases any system resources associated with it.
// Once the stream has been closed, further read(), ready(), mark(), reset(), or
// skip() invocations will throw an IOException. Closing a previously closed
// stream has no effect.
void InputStreamReader::close()
{
    stream->close();
}

// Reads a single character.
// Returns:
// The character read, or -1 if the end of the stream has been reached
int InputStreamReader::read()
{
    return stream->readUTFChar();
}

// Reads characters into a portion of an array.
// Parameters:
// cbuf - Destination buffer
// offset - Offset at which to start storing characters
// length - Maximum number of characters to read
// Returns:
// The number of characters read, or -1 if the end of the stream has been
// reached
int InputStreamReader::read(
    wchar_t      cbuf[],
    unsigned int offset,
    unsigned int length
)
{
    unsigned int charsRead = 0;
    for(unsigned int i=offset; i<offset+length; i++)
    {
        wchar_t value = (wchar_t)stream->readUTFChar();
        if(value != -1)
        {
            cbuf[i] = value;
            charsRead++;
        }
        // TODO 4J Stu - The read might throw an exception? In which case we
        // should return -1
        else
            break;
    }
    return charsRead;
}

#include <iostream>
#include <vector>
#include <utility>
#include <algorithm>

// Global variables for board size and state
int N;

// Using 1-based indexing for convenience to match problem statement.
// Global arrays are zero-initialized, which works perfectly for 'unvisited'.
int board[667][667];

// Knight's move offsets (8 directions, ordered clockwise)
const int dr[] = {-2, -1, 1, 2, 2, 1, -1, -2};
const int dc[] = {1, 2, 2, 1, -1, -2, -2, -1};

// Check if a square (r, c) is on the board and unvisited.
// Inlining can give a minor performance boost.
inline bool isValid(int r, int c)
{
    return r >= 1 && r <= N && c >= 1 && c <= N && board[r][c] == 0;
}

// Calculate the number of available moves from a square (Warnsdorff's rule).
// This is the 'degree' of the vertex in the graph of unvisited squares.
int getDegree(int r, int c)
{
    int count = 0;
    for(int i = 0; i < 8; ++i)
    {
        if(isValid(r + dr[i], c + dc[i]))
        {
            count++;
        }
    }
    return count;
}

int main()
{
    // Use fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int start_r, start_c;
    std::cin >> N >> start_r >> start_c;

    // `path` will store the sequence of visited squares.
    std::vector<std::pair<int, int>> path;

    // Set the starting position.
    int r = start_r;
    int c = start_c;

    // Mark the starting square as visited (step 1).
    board[r][c] = 1;
    path.push_back({r, c});

    // Generate the rest of the path, up to N*N-1 more moves.
    for(int move_count = 2; move_count <= N * N; ++move_count)
    {
        int next_r = -1;
        int next_c = -1;

        // Max possible degree is 8, so 9 is a safe initial value for min_degree.
        int min_degree = 9;

        // Apply Warnsdorff's rule: find the next move that has the minimum number of onward moves.
        for(int i = 0; i < 8; ++i)
        {
            int nr = r + dr[i];
            int nc = c + dc[i];

            if(isValid(nr, nc))
            {
                int degree = getDegree(nr, nc);
                if(degree < min_degree)
                {
                    min_degree = degree;
                    next_r = nr;
                    next_c = nc;
                }
            }
        }

        // If next_r is -1, it means we are stuck and cannot make any more moves.
        if(next_r == -1)
        {
            break;
        }

        // Make the chosen move.
        r = next_r;
        c = next_c;
        board[r][c] = move_count;
        path.push_back({r, c});
    }

    // Output the length of the path found.
    std::cout << path.size() << "\n";

    // Output the coordinates of each square in the path.
    for(const auto& p : path)
    {
        std::cout << p.first << " " << p.second << "\n";
    }

    return 0;
}

#include <unordered_map>
#include <map>
#include <string>

// First solution using unordered_map
class Solution {
public:
    int firstUniqChar(string s) {
        // Count character frequencies
        unordered_map<char, int> character_count;
        for(int i = 0; i < s.size(); i++) {
            character_count[ s[i] - 'a' ]++;
        }
        // Find first unique character
        for(int i = 0; i < s.size(); i++) {
            if(character_count[ s[i] - 'a' ] == 1) {
                return i;
            }
        }
        return -1;
    }
};

// Second solution using map
class Solution {
public:
    int firstUniqChar(string s) {
        // Count character frequencies
        map<char, int> character_count;
        for(int i = 0; i < s.size(); i++) {
            character_count[ s[i] - 'a' ]++;
        }
        // Find first unique character
        for(int i = 0; i < s.size(); i++) {
            if(character_count[ s[i] - 'a' ] == 1) {
                return i;
            }
        }
        return -1;
    }
};

