#include <asio/post.hpp>
#include <asio/thread_pool.hpp>
#include <iostream>

using asio::post;
using asio::thread_pool;

// Active object pattern implementation for bank_account
class bank_account
{
  int balance_ = 0;
  mutable thread_pool pool_{1};
public:
  // Deposit amount asynchronously
  void deposit(int amount)
  {
    post(pool_, [=]
      {
        balance_ += amount;
      });
  }

  // Withdraw amount conditionally (only if sufficient balance)
  void withdraw(int amount)
  {
    post(pool_, [=]
      {
        if (balance_ >= amount)
          balance_ -= amount;
      });
  }

  // Print current balance asynchronously
  void print_balance() const
  {
    post(pool_, [=]
      {
        std::cout << "balance = " << balance_ << "\n";
      });
  }

  // Clean up thread pool on destruction
  ~bank_account()
  {
    pool_.join();
  }
};

int main()
{
  bank_account acct;
  acct.deposit(20);
  acct.withdraw(10);
  acct.print_balance();
}

#include "isdiag.h"

// Check if matrix is diagonal
template <typename Scalar>
IGL_INLINE bool igl::isdiag(const Eigen::SparseMatrix<Scalar> & A)
{
    // Iterate over outside of A
    for(int k=0; k<A.outerSize(); ++k)
    {
        // Iterate over inside
        for(typename Eigen::SparseMatrix<Scalar>::InnerIterator it(A,k); it; ++it)
        {
            if(it.row() != it.col() && it.value()!=0)
            {
                return false;
            }
        }
    }
    return true;
}

