namespace Karm::Aio {

// Adapter for making types conform to Reader/Writer interface
export template <typename T>
struct Adapter : Reader, Writer {
    T& _inner;

    // Constructor
    Adapter(T& inner)
        : _inner(inner) {}

    // Write implementation
    Async::Task<usize> writeAsync(Bytes buf, Async::CancellationToken) override {
        if constexpr (Io::Writable<T>) {
            co_return _inner.write(buf);
        } else {
            co_return Ok(buf.len());
        }
    }

    // Read implementation
    Async::Task<usize> readAsync(MutBytes buf, Async::CancellationToken) override {
        if constexpr (Io::Readable<T>) {
            co_return _inner.read(buf);
        } else {
            co_return Ok(0);
        }
    }
};

// Helper function to create an adapter
export template <typename T>
Adapter<T> adapt(T& t) {
    return {t};
}

} // namespace Karm::Aio

#include <vector>
#include <numeric>

class Solution {
public:
    // Binary search to find maximum possible minimum power
    long long maxPower(std::vector<int>& stations, int r, int k) {
        long long left = 0;
        // The answer = `right`, when `r = n`, all value of stations are the same!
        long long right = std::accumulate(stations.begin(), stations.end(), 0LL) + k;
        long long ans = 0;

        while (left <= right) {
            long long mid = (left + right) / 2;
            if (isGood(stations, r, mid, k)) {
                ans = mid; // This is the maximum possible minimum power so far
                left = mid + 1; // Search for a larger value in the right side
            } else {
                right = mid - 1; // Decrease minPowerRequired to need fewer additional power stations
            }
        }
        return ans;
    }

    // Check if it's possible to achieve minPowerRequired with given additionalStations
    bool isGood(std::vector<int>& stations, int r, long long minPowerRequired, int additionalStations) {
        int n = stations.size();
        // init windowPower to store power of 0th city (minus stations[r])
        long long windowPower = std::accumulate(stations.begin(), stations.begin() + r, 0LL);
        std::vector<int> additions(n, 0);

        for (int i = 0; i < n; i++) {
            if (i + r < n) {
                // now, windowPower stores sum of power stations from [i-r..i+r],
                // it also means it's the power of city `ith`
                windowPower += stations[i + r];
            }

            if (windowPower < minPowerRequired) {
                long long needed = minPowerRequired - windowPower;
                if (needed > additionalStations) {
                    // Not enough additional stations to plant
                    return false;
                }
                // Plant the additional stations on the farthest city in the range
                // to cover as many cities as possible
                additions[std::min(n - 1, i + r)] += needed;
                windowPower = minPowerRequired;
                additionalStations -= needed;
            }

            if (i - r >= 0) {
                // out of window range
                windowPower -= stations[i - r] + additions[i - r];
            }
        }
        return true;
    }
};

