// Structure A definition
struct A {
public:
    // Virtual destructor
    virtual ~A() = default;

    // Regular member function
    void func() {}

    // Virtual member function
    virtual void Vfunc() {}
};

// Structure B inherits from A
struct B : public A {
public:
    // Overrides func (hides base class version)
    void func() {}

    // Overrides Vfunc with override specifier
    void Vfunc() override {}
};

// Main function
int main()
{
    // Create B object through A pointer
    A *a = new B;

    // Call functions
    a->func();
    a->Vfunc();

    // Clean up
    delete a;

    return 0;
}

