using grpc::Channel;
using grpc::ClientContext;
using grpc::Status;
using test_service_package::IntRequest;
using test_service_package::IntReply;
using test_service_package::Decompositor;

// Client class for the Decompositor service
class DecompositorClient {
 public:
  // Constructor: initializes the stub with the provided channel
  DecompositorClient(std::shared_ptr<Channel> channel)
      : stub_(Decompositor::NewStub(channel)) {}

  // Sends a request to decompose an integer and returns the response message
  std::string Decompose(const int& question_int) {
    // Prepare the request
    IntRequest request;
    request.set_value(question_int);

    // Container for the expected response
    IntReply reply;

    // Context for this RPC call
    ClientContext context;

    // Perform the RPC call
    Status status = stub_->Decompose(&context, request, &reply);

    // Handle the result
    if (status.ok()) {
      return reply.message();
    } else {
      std::cout << status.error_code() << ": " << status.error_message()
                << std::endl;
      return "RPC failed";
    }
  }

 private:
  std::unique_ptr<Decompositor::Stub> stub_;
};

int main(int argc, char** argv) {
  // Create client with insecure channel to localhost:50051
  DecompositorClient client(grpc::CreateChannel(
      "localhost:50051", grpc::InsecureChannelCredentials()));

  int value = 42;
  std::string reply = client.Decompose(value);
  std::cout << "Decompositor received: " << reply << std::endl;

  return 0;
}

