// Choose token based on boolean condition
MatchForwardOrderSafe::token MatchForwardOrderSafe::choose(const bool b)
{
    if (b)
    {
        return token::A;
    }
    else
    {
        return token::B;
    }
}

// Encode token to unsigned integer
unsigned int
MatchForwardOrderSafe::encode(const MatchForwardOrderSafe::token x)
{
    return [&](void) {
        switch (x)
        {
        case token::A:
            return (0 + 1);
        case token::B:
            return 0;
        }
    }();
}

