namespace {

// Singleton initializer for MLIR context
class MLIRInitializer {
public:
    static MLIRInitializer& instance() {
        static MLIRInitializer inst;
        return inst;
    }

    mlir::DialectRegistry& registry() { return registry_; }

private:
    MLIRInitializer() {
        // Register all standard MLIR dialects
        mlir::registerAllDialects(registry_);

        // Register all passes
        mlir::registerAllPasses();

        // Register SDFG code generators and serializers
        ::sdfg::codegen::register_default_dispatchers();
        ::sdfg::serializer::register_default_serializers();
    }

    mlir::DialectRegistry registry_;
};

// Python-exposed wrapper for MLIR module operations
class PyMLIRModule {
public:
    explicit PyMLIRModule(const std::string& mlir_text) {
        auto& initializer = MLIRInitializer::instance();
        context_ = std::make_unique<mlir::MLIRContext>(initializer.registry());
        context_->loadAllAvailableDialects();

        module_ = mlir::parseSourceString<mlir::ModuleOp>(mlir_text, context_.get());
        if (!module_) {
            throw std::runtime_error("Failed to parse MLIR module");
        }
    }

    std::string to_string() {
        std::string result;
        llvm::raw_string_ostream os(result);
        module_->print(os);
        return result;
    }

    void convert() {
        mlir::PassManager pm(context_.get());
        pm.addPass(mlir::createLinalgSpecializeGenericOpsPass());

        if (mlir::failed(pm.run(*module_))) {
            throw std::runtime_error("Failed to convert MLIR module");
        }
    }

    std::string translate() {
        std::string result;
        llvm::raw_string_ostream os(result);

        if (mlir::failed(mlir::sdfg::translateToSDFG(module_->getOperation(), os))) {
            throw std::runtime_error("Failed to translate to SDFG code");
        }

        return result;
    }

    mlir::Operation* get_operation() { return module_->getOperation(); }

private:
    std::unique_ptr<mlir::MLIRContext> context_;
    mlir::OwningOpRef<mlir::ModuleOp> module_;
};

} // namespace

PYBIND11_MODULE(_sdfg_mlir, m) {
    m.doc() = "Native Python bindings for MLIR to SDFG conversion";

    // Expose the PyMLIRModule class
    py::class_<PyMLIRModule>(m, "MLIRModule")
        .def(py::init<const std::string&>(), py::arg("mlir_text"), 
             "Create an MLIR module from MLIR text representation")
        .def("to_string", &PyMLIRModule::to_string, 
             "Get the MLIR module as a string")
        .def("convert", &PyMLIRModule::convert, 
             "Convert MLIR module")
        .def("translate", &PyMLIRModule::translate, 
             "Translate the SDFG dialect module to a serialized SDFG");
}

#include <asio/io_context.hpp>
#include <asio/ip/tcp.hpp>
#include <asio/spawn.hpp>
#include <asio/steady_timer.hpp>
#include <asio/write.hpp>
#include <iostream>
#include <memory>

using asio::ip::tcp;

class session : public std::enable_shared_from_this<session>
{
public:
  explicit session(tcp::socket socket)
    : socket_(std::move(socket)),
      timer_(socket_.get_io_context()),
      strand_(socket_.get_io_context())
  {
  }

  void go()
  {
    auto self(shared_from_this());

    // Read and echo data
    asio::spawn(strand_,
        [this, self](asio::yield_context yield)
        {
          try
          {
            char data[128];
            for (;;)
            {
              timer_.expires_from_now(std::chrono::seconds(10));
              std::size_t n = socket_.async_read_some(asio::buffer(data), yield);
              asio::async_write(socket_, asio::buffer(data, n), yield);
            }
          }
          catch (std::exception& e)
          {
            socket_.close();
            timer_.cancel();
          }
        });

    // Timeout handler
    asio::spawn(strand_,
        [this, self](asio::yield_context yield)
        {
          while (socket_.is_open())
          {
            asio::error_code ignored_ec;
            timer_.async_wait(yield[ignored_ec]);
            if (timer_.expires_from_now() <= std::chrono::seconds(0))
              socket_.close();
          }
        });
  }

private:
  tcp::socket socket_;
  asio::steady_timer timer_;
  asio::io_context::strand strand_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: echo_server <port>\n";
      return 1;
    }

    asio::io_context io_context;

    // Accept connections
    asio::spawn(io_context,
        [&](asio::yield_context yield)
        {
          tcp::acceptor acceptor(io_context,
            tcp::endpoint(tcp::v4(), std::atoi(argv[1])));
          for (;;)
          {
            asio::error_code ec;
            tcp::socket socket(io_context);
            acceptor.async_accept(socket, yield[ec]);
            if (!ec) std::make_shared<session>(std::move(socket))->go();
          }
        });

    io_context.run();
  }
  catch (std::exception& e)
  {
    std::cerr << "Exception: " << e.what() << "\n";
  }

  return 0;
}

#include <vector>
#include <set>
#include <algorithm>

class Solution {
    std::multiset<long long> l, r;
public:
    // Calculates the minimum cost
    long long minimumCost(std::vector<int>& nums, int k, int dist) {
        int n = nums.size();
        k--;
        long long cur = nums[0];

        // Initialize with first window
        for (int i = 1; i <= dist + 1; i++) {
            cur += nums[i];
            l.insert(nums[i]);
        }

        // Adjust to keep exactly k elements in left set
        while (l.size() > k) {
            cur -= *l.rbegin();
            r.insert(*l.rbegin());
            l.erase(l.find(*l.rbegin()));
        }

        long long ans = cur;

        // Slide the window
        for (int i = dist + 2; i < n; i++) {
            // Remove element going out of window
            if (l.find(nums[i - dist - 1]) != l.end()) {
                cur -= nums[i - dist - 1];
                l.erase(l.find(nums[i - dist - 1]));
            } else {
                r.erase(r.find(nums[i - dist - 1]));
            }

            // Add new element
            if (nums[i] < *l.rbegin()) {
                cur += nums[i];
                l.insert(nums[i]);
            } else {
                r.insert(nums[i]);
            }

            // Rebalance left set to have exactly k elements
            while (l.size() < k) {
                cur += *r.begin();
                l.insert(*r.begin());
                r.erase(r.find(*r.begin()));
            }
            while (l.size() > k) {
                cur -= *l.rbegin();
                r.insert(*l.rbegin());
                l.erase(l.find(*l.rbegin()));
            }

            ans = std::min(ans, cur);
        }

        return ans;
    }
};

