#include <vector>
#include <algorithm>
#include <cmath>

// Solution class for minimum operations
class Solution {
public:
    int minOperations(std::vector<int>& nums) {
        int n = nums.size();
        // Count number of 1s in the array
        int c = std::count(nums.begin(), nums.end(), 1);

        // If there's at least one 1, we only need to convert remaining elements
        if (c != 0) 
            return n - c;

        // Dummy large value for result
        int res = 1e7;

        // Check all possible subarrays for GCD = 1
        for (int i = 0; i < n; i++) {
            int g = nums[i];
            for (int j = i + 1; j < n; j++) {
                g = __gcd(g, nums[j]);

                // Found subarray with GCD 1
                if (g == 1) {
                    // Operations: (j-i) to make one element 1 + (n-1) to make rest 1
                    res = std::min(res, j - i + (n - 1));
                    break;
                }
            }
        }

        // Return result or -1 if impossible
        return res == 1e7 ? -1 : res;
    }
};

