// Main activation logic for the network sync task
void UAbilityTask_NetworkSyncPoint::Activate()
{
	FScopedPredictionWindow ScopedPrediction(AbilitySystemComponent, IsPredictingClient());

	if (AbilitySystemComponent)
	{
		if (IsPredictingClient())
		{
			// Client-side prediction path
			if (SyncType != EAbilityTaskNetSyncType::OnlyServerWait)
			{
				// Listen for server signal unless only waiting for server
				ReplicatedEventToListenFor = EAbilityGenericReplicatedEvent::GenericSignalFromServer;
			}

			if (SyncType != EAbilityTaskNetSyncType::OnlyClientWait)
			{
				// Notify server of client signal unless only waiting for client
				AbilitySystemComponent->ServerSetReplicatedEvent(
					EAbilityGenericReplicatedEvent::GenericSignalFromClient,
					GetAbilitySpecHandle(),
					GetActivationPredictionKey(),
					AbilitySystemComponent->ScopedPredictionKey
				);
			}
		}
		else if (IsForRemoteClient())
		{
			// Remote client path
			if (SyncType != EAbilityTaskNetSyncType::OnlyClientWait)
			{
				// Listen for client signal unless only waiting for client
				ReplicatedEventToListenFor = EAbilityGenericReplicatedEvent::GenericSignalFromClient;
			}

			if (SyncType != EAbilityTaskNetSyncType::OnlyServerWait)
			{
				// Notify client of server signal unless only waiting for server
				AbilitySystemComponent->ClientSetReplicatedEvent(
					EAbilityGenericReplicatedEvent::GenericSignalFromServer,
					GetAbilitySpecHandle(),
					GetActivationPredictionKey()
				);
			}
		}

		// If we're waiting for a replicated event, register the delegate
		if (ReplicatedEventToListenFor != EAbilityGenericReplicatedEvent::MAX)
		{
			CallOrAddReplicatedDelegate(
				ReplicatedEventToListenFor,
				FSimpleMulticastDelegate::FDelegate::CreateUObject(this, &UAbilityTask_NetworkSyncPoint::OnSignalCallback)
			);
		}
		else
		{
			// No replication needed - sync complete immediately
			SyncFinished();
		}
	}
}

// Finalize synchronization and broadcast completion
void UAbilityTask_NetworkSyncPoint::SyncFinished()
{
	if (!IsPendingKill())
	{
		if (ShouldBroadcastAbilityTaskDelegates())
		{
			OnSync.Broadcast();
		}
		EndTask();
	}
}

