using namespace tabulate;
using Row_t = Table::Row_t;

std::atomic_bool keep_running(true);

// Function to wait for user input (ENTER key)
void waitingForWorkEnterKey()
{
    while (keep_running)
    {
        if (std::cin.get() == 10)
        {
            keep_running = false;
        }
    }
    return;
}

int main()
{
    std::thread tUserInput(waitingForWorkEnterKey);

    while (keep_running)
    {
        Table process_table;

        // Random number generation setup
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<> dis(0, 1);

        // Add table rows
        process_table.add_row(Row_t{"PID", "%CPU", "%MEM", "User", "NI"});
        process_table.add_row(Row_t{"4297", std::to_string((int)round(dis(gen) * 100)),
                                    std::to_string((int)round(dis(gen) * 100)), "ubuntu", "20"});
        process_table.add_row(Row_t{"12671", std::to_string((int)round(dis(gen) * 100)),
                                    std::to_string((int)round(dis(gen) * 100)), "root", "0"});
        process_table.add_row({"810", std::to_string((int)round(dis(gen) * 100)),
                               std::to_string((int)round(dis(gen) * 100)), "root", "-20"});

        // Format columns
        process_table.column(2).format().font_align(FontAlign::center);
        process_table.column(3).format().font_align(FontAlign::right);
        process_table.column(4).format().font_align(FontAlign::right);

        // Format header row
        for (size_t i = 0; i < 5; ++i)
        {
            process_table[0][i]
                .format()
                .font_color(Color::yellow)
                .font_align(FontAlign::center)
                .font_style({FontStyle::bold});
        }

        // Output table and instructions
        std::cout << process_table << std::endl;
        std::cout << "Press ENTER to exit..." << std::endl;
        std::this_thread::sleep_for(std::chrono::milliseconds(1000));

        // Move cursor up multiple lines to overwrite next iteration
        std::cout << "\033[F\033[F\033[F\033[F\033[F\033[F\033[F\033[F\033[F\033[F";
    }

    // Move cursor down after loop ends
    std::cout << "\033[B\033[B\033[B\033[B\033[B\033[B\033[B\033[B\033[B\033[B";

    // Join thread before exiting
    tUserInput.join();

    return 0;
}

#include <vector>
#include <unordered_map>
#include <queue>

class Solution {
public:
    vector<int> findXSum(vector<int>& nums, int k, int x) 
    {
        int n = nums.size();
        vector<int> answer;
        unordered_map<int, int> freq;

        // Initialize frequency map for the first window
        for (int j = 0; j < k; j++) {
            freq[nums[j]]++;
        }

        // Calculate x-sum for the first window
        answer.push_back(calculateXSum(freq, x));

        // Slide the window
        for (int i = 1; i <= n - k; i++) {
            // Remove the element going out of the window
            freq[nums[i - 1]]--;
            if (freq[nums[i - 1]] == 0) {
                freq.erase(nums[i - 1]);
            }
            // Add the new element coming into the window
            freq[nums[i + k - 1]]++;
            // Calculate x-sum for the current window
            answer.push_back(calculateXSum(freq, x));
        }

        return answer;
    }

private:
    int calculateXSum(const unordered_map<int, int>& freq, int x) {
        // Use a priority queue (max heap) to get the top x elements
        priority_queue<pair<int, int>> pq; // (frequency, value)
        for (const auto& entry : freq) {
            pq.push({entry.second, entry.first});
        }
        int sum = 0;
        for (int i = 0; i < x && !pq.empty(); i++) {
            auto top = pq.top();
            pq.pop();
            sum += top.second * top.first; // sum = value * frequency
        }
        return sum;
    }
};

