#include "src/QuantumRegister.hpp"
#include <cassert>
#include <cmath>
#include <iostream>
#include <mpi.h>
#include <vector>

using qubit_engine::QuantumRegister;

// Helper function to compare complex numbers with tolerance
bool are_close(std::complex<double> a, std::complex<double> b,
               double tol = 1e-5) {
  return std::abs(a - b) < tol;
}

int main(int argc, char **argv) {
  MPI_Init(&argc, &argv);

  int world_rank;
  MPI_Comm_rank(MPI_COMM_WORLD, &world_rank);

  int world_size;
  MPI_Comm_size(MPI_COMM_WORLD, &world_size);

  // Verify correct number of MPI processes
  if (world_size != 2) {
    if (world_rank == 0) {
      std::cerr << "Error: This test requires exactly 2 MPI ranks."
                << std::endl;
    }
    MPI_Finalize();
    return 1;
  }

  // Setup: 4 qubits, each rank holds half the amplitude vector (dim=8)
  size_t num_qubits = 4;
  QuantumRegister reg(num_qubits);

  // Initial state: |0000> -> amplitude 1.0 at global index 0 (local index 0 on rank 0)
  // All other amplitudes zero

  // Step 1: Apply Hadamard gate to qubit 3 (MSB)
  if (world_rank == 0)
    std::cout << "Applying H(3)..." << std::endl;

  reg.applyHadamard(3);
  auto state = reg.getStateVector();

  double inv_sqrt2 = 1.0 / std::sqrt(2.0);

  // After H(3): (|0000> + |1000>) / sqrt(2)
  // Rank 0 holds indices 0–7 (global), rank 1 holds 8–15
  // So local index 0 on both ranks corresponds to global |0000> and |1000>
  if (world_rank == 0) {
    assert(are_close(state[0], inv_sqrt2));
  } else {
    assert(are_close(state[0], inv_sqrt2)); // Global index 8 = |1000>
  }

  // Step 2: Apply CNOT(control=3, target=0)
  // Control is MSB (qubit 3), target is LSB (qubit 0)
  // |1000> → |1001>, |0000> unchanged
  if (world_rank == 0)
    std::cout << "Applying CNOT(3, 0)..." << std::endl;

  reg.applyCNOT(3, 0);
  state = reg.getStateVector(); // Refresh state vector

  if (world_rank == 0) {
    // Local index 0 = global |0000>, should remain 1/sqrt(2)
    if (are_close(state[0], inv_sqrt2)) {
      std::cout << "[Rank 0] |0000> verified." << std::endl;
    } else {
      std::cerr << "[Rank 0] FAILED: |0000> amplitude mismatch." << std::endl;
      return 1;
    }
  } else {
    // Local index 0 = global |1000>, now 0
    // Local index 1 = global |1001>, now 1/sqrt(2)
    if (are_close(state[0], 0.0) && are_close(state[1], inv_sqrt2)) {
      std::cout << "[Rank 1] |1001> verified." << std::endl;
    } else {
      std::cerr << "[Rank 1] FAILED: |1001> amplitude mismatch." << std::endl;
      return 1;
    }
  }

  MPI_Finalize();
  return 0;
}

