// Solves the problem by querying and collecting words
void solve()
{
    int n;
    std::cin >> n;

    // Handle special case when n is 0
    if (n == 0)
    {
        std::cout << "answer" << std::endl;
        std::cout.flush();
        return;
    }

    // Store initial single-letter prefixes that have matches
    std::vector<std::string> initial_prefixes;
    std::set<std::string> found_words;

    // Check each letter from 'a' to 'z'
    for (char c = 'a'; c <= 'z'; ++c)
    {
        std::string prefix(1, c);
        std::cout << "query " << prefix << " " << 1 << std::endl;
        std::cout.flush();

        int k;
        std::cin >> k;

        if (k > 0)
        {
            initial_prefixes.push_back(prefix);
            std::string word;
            std::cin >> word;
            found_words.insert(word);
        }
    }

    // Process prefixes in reverse alphabetical order as a heuristic
    std::sort(initial_prefixes.rbegin(), initial_prefixes.rend());
    int n_rem = n;

    // Process each prefix
    for (size_t i = 0; i < initial_prefixes.size(); ++i)
    {
        const std::string& prefix = initial_prefixes[i];

        // Count how many known words start with this prefix
        int known_for_prefix = 0;
        for (const auto& word : found_words)
        {
            if (word.rfind(prefix, 0) == 0)
            {
                known_for_prefix++;
            }
        }

        // Calculate how many words we need to query for this prefix
        int query_k = n - (found_words.size() - known_for_prefix);

        // For the last prefix, calculate exact count
        if (i == initial_prefixes.size() - 1)
        {
            query_k = n - found_words.size() + known_for_prefix;
        }

        // Skip if no more words needed
        if (query_k <= 0) continue;

        std::cout << "query " << prefix << " " << query_k << std::endl;
        std::cout.flush();

        int k;
        std::cin >> k;

        // Read and store the words
        for (int j = 0; j < k; ++j)
        {
            std::string word;
            std::cin >> word;
            found_words.insert(word);
        }
    }

    // Output final answer
    std::cout << "answer";
    for (const auto& word : found_words)
    {
        std::cout << " " << word;
    }
    std::cout << std::endl;
    std::cout.flush();
}

int main()
{
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int t;
    std::cin >> t;

    while (t--)
    {
        solve();
    }

    return 0;
}

