template <typename T, size_t N>
class array_view {
private:
    T* elements;
    size_t length;
public:
    array_view(T* ptr, size_t len) : elements(ptr), length(len) {}

    // Assignment operator: copy values from another view
    array_view& operator=(const array_view& other) {
        for (size_t idx = 0; idx < length; ++idx) {
            elements[idx] = other.elements[idx];
        }
        return *this;
    }

    // Addition operator: element-wise sum with another view
    array_view operator+(const array_view& other) const {
        array_view temp(*this);
        for (size_t idx = 0; idx < length; ++idx) {
            temp.elements[idx] += other.elements[idx];
        }
        return temp;
    }
};

