// Perform DFS-based topological sort helper
void Graph::depthFirstOrdering(int node, bool* seenNodes, std::stack<int>& resultStack) {
    // Indicate that this vertex has been processed
    seenNodes[node] = true;

    // Explore all neighbors recursively
    for (auto neighbor = adjacencyList[node].begin(); neighbor != adjacencyList[node].end(); ++neighbor) {
        if (!seenNodes[*neighbor]) {
            depthFirstOrdering(*neighbor, seenNodes, resultStack);
        }
    }

    // Add current node to result after all descendants are processed
    resultStack.push(node);
}

std::vector<int> Graph::computeTopologicalOrder() {
    std::stack<int> tempStack;

    // Initialize tracking array for visited status
    bool* processed = new bool[totalVertices];
    for (int index = 0; index < totalVertices; ++index) {
        processed[index] = false;
    }

    // Process each unvisited vertex
    for (int vertex = 0; vertex < totalVertices; ++vertex) {
        if (!processed[vertex]) {
            depthFirstOrdering(vertex, processed, tempStack);
        }
    }

    // Build final ordering by extracting from stack
    std::vector<int> orderResult;
    while (!tempStack.empty()) {
        orderResult.push_back(tempStack.top());
        tempStack.pop();
    }

    delete[] processed;
    return orderResult;
}

