// Check if a mathematical expression has balanced parentheses and valid operators
bool checkMathExpression(const std::string& expr) {
    std::stack<char> bracketStack;

    // Process each character in the expression
    for (char ch : expr) {
        if (ch == '(') {
            bracketStack.push(ch);
        } else if (ch == ')') {
            if (bracketStack.empty() || bracketStack.top() != '(') {
                return false;  // Mismatched or unbalanced closing parenthesis
            }
            bracketStack.pop();
        } else if (!isdigit(ch) && ch != '+' && ch != '-' && ch != '*' && ch != '/') {
            return false;  // Contains invalid characters
        }
    }

    // Ensure all opening parentheses have been closed
    if (!bracketStack.empty()) {
        return false;
    }

    // Check for operators at the start or end of the expression
    if (expr.front() == '+' || expr.front() == '-' || 
        expr.front() == '*' || expr.front() == '/') {
        return false;
    }

    if (expr.back() == '+' || expr.back() == '-' || 
        expr.back() == '*' || expr.back() == '/') {
        return false;
    }

    // Verify no two consecutive operators exist
    for (size_t pos = 0; pos < expr.length() - 1; ++pos) {
        if ((expr[pos] == '+' || expr[pos] == '-' || 
             expr[pos] == '*' || expr[pos] == '/') &&
            (expr[pos + 1] == '+' || expr[pos + 1] == '-' || 
             expr[pos + 1] == '*' || expr[pos + 1] == '/')) {
            return false;
        }
    }

    return true;  // Expression passes all validation checks
}

