// Rearrange array so all zeros are moved to the end while maintaining order of non-zero elements
void moveZerosToEnd(int arr[], int size) {
    int pos = 0;  // Position index for placing next non-zero element

    for (int j = 0; j < size; j++) {
        if (arr[j] != 0) {
            // Exchange current non-zero element with element at position 'pos'
            std::swap(arr[pos], arr[j]);
            pos++;  // Move position pointer forward
        }
    }
}

