// Determine if enough valid contours exist based on area and aspect ratio constraints
bool FilterAndFind(const std::vector<std::vector<cv::Point>>& inputContours) {
    int matchingCount = 0;
    for (const auto& contour : inputContours) {
        double contourAreaVal = cv::contourArea(contour);
        if (contourAreaVal > AREA_LOWER_BOUND && contourAreaVal < AREA_UPPER_BOUND) {
            // Compute the bounding rectangle for this contour
            cv::Rect rectBounds = cv::boundingRect(contour);
            double ratioWidthToHeight = static_cast<double>(rectBounds.width) / rectBounds.height;
            // Validate aspect ratio falls within acceptable range
            if (ratioWidthToHeight >= ASPECT_MIN && ratioWidthToHeight <= ASPECT_MAX) {
                // Increase count of qualifying contours
                matchingCount += 1;
            }
        }
    }
    // Accept only if number of valid contours exceeds minimum requirement
    return matchingCount > REQUIRED_VALID_COUNT;
}

