// Check if coordinates are within grid boundaries
bool isValid(int row, int col, int gridSize) {
    return row >= 0 && row < gridSize && col >= 0 && col < gridSize;
}

// Update probability distribution based on movement probabilities
void updateProbabilities(double grid[MAX_SIZE][MAX_SIZE], int row, int col, double probability, 
                        double probRight, double probUp, double probLeft, int gridSize) {
    // Move right
    if(row != gridSize-1 && isValid(row+1, col, gridSize))
        grid[row+1][col] += probability * probRight;
    else
        grid[row][col] += probability * probRight;

    // Move up
    if(col != gridSize-1 && isValid(row, col+1, gridSize))
        grid[row][col+1] += probability * probUp;
    else
        grid[row][col] += probability * probUp;

    // Move left
    if(row != 0 && isValid(row-1, col, gridSize))
        grid[row-1][col] += probability * probLeft;
}

