int main() {
    // Initialize a socket for the server
    int listenFd = socket(AF_INET, SOCK_STREAM, 0);

    // Configure the server address structure
    sockaddr_in localAddr;
    localAddr.sin_family = AF_INET;
    localAddr.sin_port = htons(8080);
    localAddr.sin_addr.s_addr = INADDR_ANY;

    // Bind the socket to the specified address and port
    bind(listenFd, (struct sockaddr *)&localAddr, sizeof(localAddr));

    // Start listening for incoming connections
    listen(listenFd, 5);

    // Continuously accept and handle client connections
    while (true) {
        int clientFd = accept(listenFd, NULL, NULL);
        processConnection(clientFd);
    }

    // Close the listening socket (unreachable in practice due to infinite loop)
    close(listenFd);
    return 0;
}

