class Location {
private:
    double xcoord;
    double ycoord;
    double angle;
public:
    // Constructor to initialize the location
    Location() : xcoord(0), ycoord(0), angle(0) {}

    // Method to set x-coordinate
    void setX(double xval) {
        xcoord = xval;
    }

    // Method to get x-coordinate
    double getX() const {
        return xcoord;
    }

    // Method to set y-coordinate
    void setY(double yval) {
        ycoord = yval;
    }

    // Method to get y-coordinate
    double getY() const {
        return ycoord;
    }

    // Method to set angle
    void setAngle(double theta) {
        angle = theta;
    }

    // Method to get angle
    double getAngle() const {
        return angle;
    }

    // Method to move the location by a given distance in a given direction
    void advance(double dist, double dir) {
        xcoord += dist * cos(dir);
        ycoord += dist * sin(dir);
    }
};

