};

// Circle implementation
class CircularRegion : public Shape {
private:
    double radialLength;
public:
    CircularRegion(double r) : radialLength(r) {}
    void computeSurfaceArea() override {
        surfaceArea = 3.14159 * radialLength * radialLength;
    }
};

// Rectangle implementation
class RectangularRegion : public Shape {
private:
    double extentX;
    double extentY;
public:
    RectangularRegion(double l, double w) : extentX(l), extentY(w) {}
    void computeSurfaceArea() override {
        surfaceArea = extentX * extentY;
    }
};

