// Compute edge weights based on attribute selection
std::vector<double> computeEdgeWeights(const Graph& network, 
                                       const std::vector<double>& baseValues, 
                                       const std::vector<double>& modifiedValues, 
                                       const std::vector<bool>& useModified) {
    std::vector<double> result;

    if (!network.hasEdgeIds()) {
        throw std::runtime_error("edge identifiers not available - invoke indexEdges first");
    }

    result.resize(network.upperEdgeIdBound());
    network.parallelForEdges([&](node src, node dst, edgeid edgeIndex) {
        result[edgeIndex] = (useModified[edgeIndex] ? modifiedValues[edgeIndex] : baseValues[edgeIndex]);
    });

    return result;
}

