#include <iostream>
#include <functional>
#include <list>

template <typename T>
class Signal {
public:
    using Callback = std::function<void(T)>;

    void subscribe(const Callback& callback) {
        callbacks.push_back(callback);
    }

    void unsubscribe(const Callback& callback) {
        callbacks.remove(callback);
    }

    void trigger(const T& value) {
        for (const auto& cb : callbacks) {
            cb(value);
        }
    }

private:
    std::list<Callback> callbacks;
};

class DataProcessor {
public:
    void handleData(int data) {
        std::cout << "Signal processed with value: " << data << std::endl;
    }
};

int main() {
    DataProcessor processor;
    Signal<int> signal;

    // Subscribe the handler
    signal.subscribe([&processor](int val) { 
        processor.handleData(val); 
    });

    // Trigger the signal
    if (!signal.callbacks.empty()) {
        signal.trigger(2);  // will print once
    }

    // Unsubscribe all handlers
    signal.unsubscribe([&processor](int val) { 
        processor.handleData(val); 
    });

    // Check if any handlers remain
    if (!signal.callbacks.empty()) {
        signal.trigger(3);  // will not be printed
    }

    return 0;
}

#include <iostream>
