// Structure to store parsed command-line configuration
struct CliConfig {
    std::string scriptPath;
    std::vector<std::string> extraInputs;
    int testCaseId;
    bool isThreeDimensional;
    bool enableDiffTesting;
    double diffPerturbationFactor;
};

// Function to process command-line arguments and populate the configuration
CliConfig processArguments(int argc, char* argv[]) {
    CliConfig config;

    // Map argument flags to their corresponding fields and descriptions
    std::unordered_map<std::string, std::pair<void*, std::string>> argMap = {
        {"-script", {&config.scriptPath, "Lua script file path for initial data"}},
        {"-e", {&config.extraInputs, "Additional input string to append"}},
        {"-t", {&config.testCaseId, "Identifier for test case (non-Lua)"}},
        {"--3d", {&config.isThreeDimensional, "Enable 3D mode (non-Lua)"}},
        {"--diff_test", {&config.enableDiffTesting, "Activate differential testing (non-Lua)"}},
        {"-dpf", {&config.diffPerturbationFactor, "Perturbation magnitude for diff test (non-Lua)"}}
    };

    // Process each command-line token
    for (int idx = 1; idx < argc; ++idx) {
        std::string token = argv[idx];
        if (argMap.find(token) != argMap.end()) {
            if (token == "-e") {
                if (idx + 1 < argc && argv[idx + 1][0] != '-') {
                    auto& vec = *((std::vector<std::string>*)argMap[token].first);
                    vec.push_back(argv[idx + 1]);
                    ++idx;
                }
            } else if (token == "--3d" || token == "--diff_test") {
                *((bool*)argMap[token].first) = true;
            } else {
                if (idx + 1 < argc && argv[idx + 1][0] != '-') {
                    if (token == "-dpf") {
                        *((double*)argMap[token].first) = std::stod(argv[idx + 1]);
                    } else {
                        *((std::string*)argMap[token].first) = argv[idx + 1];
                    }
                    ++idx;
                }
            }
        }
    }
    return config;
}

int main(int argc, char* argv[]) {
    CliConfig config = processArguments(argc, argv);

    // Output the parsed configuration values
    std::cout << "Script Path: " << config.scriptPath << std::endl;
    std::cout << "Extra Inputs: ";
    for (const auto& input : config.extraInputs) {
        std::cout << input << " ";
    }
    std::cout << std::endl;
    std::cout << "Test Case ID: " << config.testCaseId << std::endl;
    std::cout << "3D Mode: " << (config.isThreeDimensional ? "enabled" : "disabled") << std::endl;
    std::cout << "Diff Test Active: " << (config.enableDiffTesting ? "yes" : "no") << std::endl;
    std::cout << "Perturbation Factor: " << config.diffPerturbationFactor << std::endl;

    return 0;
}

