}

template <typename T>
Vector2<T> operator-(const Vector2<T>& vecA, const Vector2<T>& vecB) {
#ifdef RM_MATH_STAT
    PROFILE_FUNCTION();
#endif
    return {vecA.x - vecB.x, vecA.y - vecB.y};
}

template <typename T>
T dotProduct(const Vector2<T>& vecA, const Vector2<T>& vecB) {
#ifdef RM_MATH_STAT
    PROFILE_FUNCTION();
#endif
    return vecA.x * vecB.x + vecA.y * vecB.y;
}

template <typename T>
T crossProduct(const Vector2<T>& vecA, const Vector2<T>& vecB) {
#ifdef RM_MATH_STAT
    PROFILE_FUNCTION();
#endif
    return vecA.x * vecB.y - vecA.y * vecB.x;
}

template <typename T>
Vector2<T> normalize(const Vector2<T>& v) {
#ifdef RM_MATH_STAT
    PROFILE_FUNCTION();
#endif
    T len = std::sqrt(v.x * v.x + v.y * v.y);
    return {v.x / len, v.y / len};
}

