void TabResponseHeaders::populateHeaders(const QMap<QString, QString>& headerData)
{
    // Remove existing entries from the table
    headersTable->clearContents();
    headersTable->setRowCount(headerData.size());
    int rowIndex = 0;
    for (auto iter = headerData.constBegin(); iter != headerData.constEnd(); ++iter) {
        QTableWidgetItem* keyItem = new QTableWidgetItem(iter.key());
        QTableWidgetItem* valItem = new QTableWidgetItem(iter.value());
        headersTable->setItem(rowIndex, 0, keyItem);   // Insert header name in first column
        headersTable->setItem(rowIndex, 1, valItem);   // Insert header value in second column
        rowIndex++;
    }
    headersTable->resizeColumnsToContents();
}

