class Cone : public Shape {
private:
    double baseRadius;
    double coneHeight;
public:
    Cone(double r, double h) : baseRadius(r), coneHeight(h) {}
    double computeVolume() {
        return (1.0 / 3.0) * PI * baseRadius * baseRadius * coneHeight;
    }
    double computeSurfaceArea() {
        return PI * baseRadius * (baseRadius + sqrt(baseRadius * baseRadius + coneHeight * coneHeight));
    }
};
