public:
    Cylinder(double r, double h) : baseRadius(r), cylHeight(h) {}
    double computeVolume() {
        return PI * baseRadius * baseRadius * cylHeight;
    }
    double computeSurfaceArea() {
        return 2 * PI * baseRadius * (baseRadius + cylHeight);
    }
};
