    double innerRadius;
public:
    HollowCylinder(double r, double h, double ir) : Cylinder(r, h), innerRadius(ir) {}
    double computeVolume() {
        return Cylinder::computeVolume() - (PI * innerRadius * innerRadius * cylHeight);
    }
    double computeSurfaceArea() {
        return Cylinder::computeSurfaceArea() - (2 * PI * innerRadius * cylHeight);
    }
};
