void memcpy(void* dest, const void* src, std::int64_t size);

template <typename ElementT>
inline void copy_elements(ElementT* destination, const ElementT* source, std::int64_t element_count) {
    // Validate input parameters to prevent integer overflow
    if (element_count < 0 || sizeof(ElementT) <= 0 || (sizeof(ElementT) * element_count) < 0) {
        // Throw exception on overflow condition
        throw std::overflow_error("Buffer copy operation detected potential overflow");
    }

    // Ensure multiplication safety before performing the copy
    ONEDAL_ASSERT_MUL_OVERFLOW(std::int64_t, sizeof(ElementT), element_count);

    // Execute the low-level memory copy
    memcpy(destination, source, sizeof(ElementT) * element_count);
}

