struct StackNode {
    int value;
    int currentMin;
    StackNode* nextNode;

    StackNode(int x, int m, StackNode* n) : value(x), currentMin(m), nextNode(n) {}
};

class MinimumStack {
private:
    StackNode* head;
public:
    MinimumStack() {
        head = nullptr;
    }

    void pushElement(int x) {
        if (head == nullptr) {
            head = new StackNode(x, x, nullptr);
        } else {
            head = new StackNode(x, std::min(x, head->currentMin), head);
        }
    }

    void removeTop() {
        assert(head != nullptr);  // Ensure stack is not empty
        StackNode* temp = head;
        head = head->nextNode;
        delete temp;
    }

    int peek() {
        assert(head != nullptr);  // Ensure stack is not empty
        return head->value;
    }

    int findMinimum() {
        assert(head != nullptr);  // Ensure stack is not empty
        return head->currentMin;
    }
};

int main() {
    MinimumStack stack;
    stack.pushElement(5);
    stack.pushElement(3);
    stack.pushElement(7);
    stack.pushElement(2);

    std::cout << "Top element: " << stack.peek() << std::endl;  // Output: 2
    std::cout << "Minimum element: " << stack.findMinimum() << std::endl;  // Output: 2

    stack.removeTop();
    std::cout << "Top element after pop: " << stack.peek() << std::endl;  // Output: 7
    std::cout << "Minimum element after pop: " << stack.findMinimum() << std::endl;  // Output: 3

    return 0;
}

