int main(int argument_count, char* arguments[]) {
    if (argument_count != 3) {
        std::cerr << "Usage: ./worker <filepath> <count>\n";
        return -1;
    }

    unsigned int worker_count;
    if (sscanf(arguments[2], "%u", &worker_count) == 0) {
        std::cerr << "Invalid count format\n";
        return -1;
    }

    WorkerNode** workers = new WorkerNode*[worker_count];

    int parent_to_worker_pipe[2];
    if (pipe(parent_to_worker_pipe) == -1) {
        perror("Pipe initialization failed");
        return -1;
    }

    int input_file_descriptor = open(arguments[1], O_RDONLY);
    if (input_file_descriptor == -1) {
        perror("File opening failed");
        return -1;
    }

    for (int index = 0; index < worker_count; ++index) {
        int worker_to_parent_pipe[2];
        if (pipe(worker_to_parent_pipe) == -1) {
            perror("Pipe creation failed");
            return -1;
        }

        pid_t process_id = fork();
        if (process_id == -1) {
            perror("Fork operation failed");
            return -1;
        }

        if (process_id == 0) {  // Child process
            close(worker_to_parent_pipe[1]);  // Close write end
            close(parent_to_worker_pipe[0]);  // Close read end of parent pipe

            char data_buffer[2048];
            ssize_t received_bytes = read(worker_to_parent_pipe[0], data_buffer, sizeof(data_buffer));
            if (received_bytes == -1) {
                perror("Data reading failed");
                return -1;
            }

            // Handle the received data here
            // ...

            close(worker_to_parent_pipe[0]);
            exit(0);
        } else {  // Parent process
            close(worker_to_parent_pipe[0]);  // Close read end

            char file_data[2048];
            ssize_t file_bytes_read = read(input_file_descriptor, file_data, sizeof(file_data));
            if (file_bytes_read == -1) {
                perror("Input file reading error");
                return -1;
            }

            ssize_t sent_bytes = write(worker_to_parent_pipe[1], file_data, file_bytes_read);
            if (sent_bytes == -1) {
                perror("Data transmission error");
                return -1;
            }

            close(worker_to_parent_pipe[1]);
        }
    }

    close(input_file_descriptor);

    // Wait for all child processes to finish
    for (int j = 0; j < worker_count; ++j) {
        wait(NULL);
    }

    delete[] workers;
    return 0;
}

