// WindowCycleManager class definition
class WindowCycleManager {
public:
    enum MoveDirection { NEXT, PREV };

    void ProcessWindowCycle(MoveDirection dir, bool allowWrap) {
        // Skip if screen is locked
        if (Shell::GetActive()->GetHandler()->IsLocked()) {
            return;
        }

        // Acquire current window list
        std::vector<Window*> openList = RetrieveWindows();

        // Locate currently focused window
        auto currentFocus = std::find_if(openList.begin(), openList.end(),
            [](Window* w) { return w->isActive; });

        if (currentFocus != openList.end()) {
            // Navigate based on direction
            if (dir == NEXT) {
                currentFocus = (currentFocus == openList.end() - 1) ? openList.begin() : currentFocus + 1;
            } else {
                currentFocus = (currentFocus == openList.begin()) ? openList.end() - 1 : currentFocus - 1;
            }

            // Update focus status for all windows
            for (auto& win : openList) {
                win->isActive = (win == *currentFocus);
            }
        }

        // Handle wrap-around when requested
        if (allowWrap && openList.size() > 1) {
            for (auto& win : openList) {
                win->isActive = false;
            }
            openList[0]->isActive = true;
        }
    }

    bool IsInCycleMode() {
        // Determine if cycling operation is in progress
        return true;
