// Compare two version strings in format "v X.Y"
bool AreVersionsCompatible(const std::wstring& currentVersion, const std::wstring& requiredVersion) {
    // Parse version components
    int curMajor, curMinor, reqMajor, reqMinor;
    wchar_t dummyChar;
    std::wistringstream curStream(currentVersion), reqStream(requiredVersion);

    curStream >> dummyChar >> curMajor >> dummyChar >> curMinor;
    reqStream >> dummyChar >> reqMajor >> dummyChar >> reqMinor;

    // Check if required version is higher than current
    if (reqMajor > curMajor) {
        return true;
    } else if (reqMajor == curMajor && reqMinor > curMinor) {
        return true;
    }
    return false;
}

int main() {
    std::wstring wsz_CURRENT_VERSION = L"v 1.0";
    std::wstring wsz_REQUIRED_VERSION = L"v 5.00";

    if (AreVersionsCompatible(wsz_CURRENT_VERSION, wsz_REQUIRED_VERSION)) {
        std::wcout << L"The required version is greater than the current version." << std::endl;
    } else {
        std::wcout << L"The required version is not greater than the current version." << std::endl;
    }

    return 0;
}

#include <boost/asio.hpp>
#include <boost/thread.hpp>
#include <boost/bind.hpp>
#include <boost/ptr_container/ptr_vector.hpp>

class ThreadPoolManager {
public:
    ThreadPoolManager(size_t threadCount) : m_services(threadCount), m_tasks(threadCount) {
        for (size_t idx = 0; idx < threadCount; ++idx) {
            m_tasks.push_back(new boost::asio::io_service::work(m_services[idx]));
            m_pool.create_thread(boost::bind(&boost::asio::io_service::run, &m_services[idx]));
        }
    }

    void enqueueJob(const std::function<void()>& job) {
        size_t position = m_roundRobin.fetch_add(1) % m_services.size();
        m_services[position].post(job);
    }

    void shutdownAll() {
        for (size_t k = 0; k < m_services.size(); ++k) {
            m_tasks[k].reset();  // Release work to allow services to finish
            m_services[k].stop();  // Halt the I/O service
        }
        m_pool.join_all();  // Synchronize all worker threads
    }

private:
    boost::ptr_vector<boost::asio::io_service> m_services;
    boost::ptr_vector<boost::asio::io_service::work> m_tasks;
    boost::thread_group m_pool;
    boost::atomic<size_t> m_roundRobin{0};
};

// Demonstration of usage
int main() {
    ThreadPoolManager pool(4);  // Initialize a thread pool with 4 io_service objects
    // Enqueue multiple jobs for execution
    for (int j = 0; j < 10; ++j) {
        pool.enqueueJob([j](){
            std::cout << "Job " << j << " processed by thread " << boost::this_thread::get_id() << std::endl;
        });
    }
    // Gracefully terminate all services
    pool.shutdownAll();
    return 0;
}

