#include <Eigen/Dense>
#include <sstream>
#include <stdexcept>

template <std::size_t N>
Eigen::Matrix<double, N, 1> parseVectorNd(const std::string& input) {
    Eigen::Matrix<double, N, 1> output;
    std::istringstream stream(input);
    double element;
    std::size_t index = 0;

    while (stream >> element) {
        if (index >= N) {
            throw std::invalid_argument("Input string contains more values than the specified vector size");
        }
        output(index, 0) = element;
        index++;
    }

    if (index != N) {
        throw std::invalid_argument("Input string does not contain enough values for the specified vector size");
    }

    if (!stream.eof()) {
        throw std::runtime_error("Error parsing input string");
    }

    return output;
}

