void initializeSDL(int argCount, char* arguments[])
{
    // Initialize SDL video subsystem
    if (SDL_Init(SDL_INIT_VIDEO) < 0)
    {
        std::cerr << "SDL Video initialization failed:" << std::endl;
        std::cerr << "SDL Error: " << SDL_GetError() << std::endl;
        SDL_Quit();
        std::exit(EXIT_FAILURE);
    }

    // Handle command line arguments
    if (argCount == 1)
    {
        std::cout << "Usage: application_name [options]" << std::endl;
    }
    else if (argCount == 2 && (std::string(arguments[1]) == "-h" || std::string(arguments[1]) == "--help"))
    {
        std::cout << "Help: Display usage instructions for this program." << std::endl;
    }
    else if (argCount == 3 && (std::string(arguments[1]) == "-f" || std::string(arguments[1]) == "--file"))
    {
        std::ifstream input_file(arguments[2]);
        if (input_file.is_open())
        {
            std::string current_line;
            while (std::getline(input_file, current_line))
            {
                std::cout << current_line << std::endl;
            }
            input_file.close();
        }
        else
        {
            std::cerr << "Error: Unable to open the specified file." << std::endl;
        }
    }
    else if (argCount == 4 && (std::string(arguments[1]) == "-s" || std::string(arguments[1]) == "--size"))
    {
        int window_width = std::stoi(arguments[2]);
        int window_height = std::stoi(arguments[3]);
        SDL_Window* created_window = SDL_CreateWindow("SDL Application Window", 
                                                      SDL_WINDOWPOS_UNDEFINED, 
                                                      SDL_WINDOWPOS_UNDEFINED, 
                                                      window_width, 
                                                      window_height, 
                                                      SDL_WINDOW_SHOWN);
        if (created_window == nullptr)
        {
            std::cerr << "Error: Could not create SDL window." << std::endl;
        }
    }
    else
    {
        std::cerr << "Error: Incorrect command-line arguments provided." << std::endl;
    }
}

