    // Initiates an HTTP request and returns a unique call identifier
    CallIdentifier initiateRequest(RequestHandle handle) {
        CallIdentifier id = handle;  // Simplified mapping for demo
        return id;
    }

    // Associates a callback with a specific request handle
    void setHandler(RequestHandle handle, ResponseHandler handler) {
        handlerMap[handle] = std::move(handler);
    }

