#include <type_traits>

// Helper alias for type list
template<typename...>
struct sequence {};

// Comparison metafunction: returns true if sizeof(T) <= sizeof(U)
template<typename T, typename U>
struct smaller_or_equal : std::integral_constant<bool, sizeof(T) <= sizeof(U)> {};

// Implementation details for merging sequences
template<typename...>
struct _merge_helper;

// Base case: first list empty
template<typename... elements>
struct _merge_helper<sequence<>, sequence<elements...>, sequence<elements...>, smaller_or_equal>
{};

// Base case: second list empty
template<typename... items>
struct _merge_helper<sequence<items...>, sequence<>, sequence<items...>, smaller_or_equal>
{};

// Recursive case: compare heads and merge accordingly
template<typename head1, typename... tail1, 
         typename head2, typename... tail2,
         typename... accumulated, typename predicate>
struct _merge_helper<sequence<head1, tail1...>, 
                     sequence<head2, tail2...>, 
                     sequence<accumulated...>, 
                     predicate>
    : std::conditional_t<predicate::template test<head1, head2>::value,
                        _merge_helper<sequence<tail1...>, 
                                     sequence<head2, tail2...>, 
                                     sequence<accumulated..., head1>, 
                                     predicate>,
                        _merge_helper<sequence<head1, tail1...>, 
                                     sequence<tail2...>, 
                                     sequence<accumulated..., head2>, 
                                     predicate>>
{};

int main() {
    using result = _merge_helper<sequence<int, double, char>, 
                                sequence<float, short, long>, 
                                sequence<>, 
                                smaller_or_equal>::type;
    // result contains merged types ordered by size
    return 0;
}

#include <queue>
#include <mutex>
#include <condition_variable>
#include <memory>

template <typename DataType>
class ConcurrentQueue {
public:
    void add(const DataType& item) {
        std::unique_lock<std::mutex> guard(mtx);
        dataQueue.push(item);
        guard.unlock();
        cv.notify_one();
    }

    std::shared_ptr<DataType> remove() {
        std::unique_lock<std::mutex> guard(mtx);
        cv.wait(guard, [this] { return !dataQueue.empty(); });
        auto result = std::make_shared<DataType>(dataQueue.front());
        dataQueue.pop();
        return result;
    }

private:
    std::queue<DataType> dataQueue;
    mutable std::mutex mtx;
    std::condition_variable cv;
};

