  void init_token(name creator, asset max_supply) {
    require_auth(_self);
    symbol_code sym_code = max_supply.symbol.code();
    check(max_supply.symbol.is_valid(), "symbol is not valid");
    check(max_supply.is_valid(), "supply parameters invalid");
    check(max_supply.amount > 0, "maximum supply must be greater than zero");

    token_stats stat_table(_self, sym_code.raw());
    auto existing_entry = stat_table.find(sym_code.raw());
    check(existing_entry == stat_table.end(), "token with this symbol already exists");

    stat_table.emplace(creator, [&](auto& record) {
      record.total_supply.symbol = max_supply.symbol;
      record.limit_supply = max_supply;
      record.owner = creator;
    });
  }

  // Issue additional tokens to a recipient
  [[eosio::action]]
  void mint(name beneficiary, asset amount, std::string note) {
    symbol_code sym = amount.symbol.code();
    check(amount.symbol.is_valid(), "invalid symbol in mint operation");
    check(note.length() <= 128, "note exceeds maximum allowed length");

    token_stats stat_table(_self, sym.raw());
    auto entry = stat_table.find(sym.raw());
    check(entry != stat_table.end(), "no such token defined");

    const auto& token_info = *entry;
    require_auth(token_info.owner);

    check(amount.is_valid(), "minted amount is invalid");
    check(amount.amount > 0, "must mint positive amount");
    check(amount.symbol == token_info.total_supply.symbol, "symbol mismatch");
    check(amount.amount <= token_info.limit_supply.amount - token_info.total_supply.amount, 
          "insufficient remaining supply");

    stat_table.modify(token_info, same_payer, [&](auto& s) {
      s.total_supply += amount;
    });

    update_account_balance(token_info.owner, amount, token_info.owner);

    if (beneficiary != token_info.owner) {
      SEND_INLINE_ACTION(*this, move_funds, {token_info.owner, "active"_n}, 
                         {token_info.owner, beneficiary, amount, note});
    }
  }

  // Transfer tokens between accounts
  [[eosio::action]]
  void move_funds(name sender, name receiver, asset amount, std::string message) {
    check(sender != receiver, "sender and receiver must differ");
    require_auth(sender);
    check(is_account(receiver), "receiver account does not exist");

    symbol_code sym = amount.symbol.code();
    token_stats stat_table(_self, sym.raw());
    const auto& token_record = stat_table.get(sym.raw());

    require_recipient(sender);
    require_recipient(receiver);

    check(amount.is_valid(), "transfer amount invalid");
    check(amount.amount > 0, "transfer quantity must be positive");
    check(message.size() <= 128, "message too long");

    deduct_from(sender, amount);
    credit_to(receiver, amount, sender);
  }

  // Query account balance
  [[eosio::action]]
  void view_balance(name holder) {
    require_auth(holder);
    user_accounts account_table(_self, holder.value);
    const auto& record = account_table.get(holder.value, "account not found");
    print("Current balance: ", record.holding);
  }

private:
  struct [[eosio::table]] user_account {
    asset holding;
    uint64_t primary_key() const { return holding.symbol.code().raw(); }
  };

  struct [[eosio::table]] token_registry {
    asset total_supply;
    asset limit_supply;
    name owner;
    uint64_t primary_key() const { return total_supply.symbol.code().raw(); }
  };

  typedef multi_index<"accounts"_n, user_account> user_accounts;
  typedef multi_index<"tokens"_n, token_registry> token_stats;

  void deduct_from(name account, asset amount) {
    user_accounts from_table(_self, account.value);
    const auto& item = from_table.get(amount.symbol.code().raw(), "no balance entry");
    check(item.holding.amount >= amount.amount, "insufficient funds");

    if (item.holding.amount == amount.amount) {
      from_table.erase(item);
    } else {
      from_table.modify(item, account, [&](auto& entry) {
        entry.holding -= amount;
      });
    }
  }

  void credit_to(name account, asset amount, name ram_payer) {
    user_accounts to_table(_self, account.value);
    auto position = to_table.find(amount.symbol.code().raw());

    if (position == to_table.end()) {
      to_table.emplace(ram_payer, [&](auto& entry) {
        entry.holding = amount;
      });
    } else {
      to_table.modify(position, same_payer, [&](auto& entry) {
        entry.holding += amount;
      });
    }
  }
};

