#include "../include/cpp_lane_line_detection.h"
int main(int argc, char * argv[])
{
    // Process each input image provided as command-line argument
    for (int index = 1; index < argc; index++) {
        // Load the current image from disk
        cv::Mat sourceImage = cv::imread(argv[index]);

        // Convert to grayscale and apply Gaussian blur
        cv::Mat grayscaleFrame, smoothedFrame, edgesFrame;
        cv::cvtColor(sourceImage, grayscaleFrame, cv::COLOR_BGR2GRAY);
        cv::GaussianBlur(grayscaleFrame, smoothedFrame, cv::Size(5, 5), 0);
        cv::Canny(smoothedFrame, edgesFrame, 50, 150);

        // Define and apply a region-of-interest mask
        cv::Mat roiMask = cv::Mat::zeros(edgesFrame.size(), edgesFrame.type());
        cv::Point vertices[4] = {
            cv::Point(100, edgesFrame.rows),
            cv::Point(450, 300),
            cv::Point(550, 300),
            cv::Point(edgesFrame.cols - 100, edgesFrame.rows)
        };
        cv::fillConvexPoly(roiMask, vertices, 4, cv::Scalar(255));
        cv::bitwise_and(edgesFrame, roiMask, edgesFrame);

        // Detect line segments using probabilistic Hough transform
        std::vector<cv::Vec4i> detectedSegments;
        cv::HoughLinesP(edgesFrame, detectedSegments, 1, CV_PI / 180, 50, 50, 10);

        // Draw each detected line segment onto the original image
        for (size_t k = 0; k < detectedSegments.size(); k++) {
            cv::Vec4i segment = detectedSegments[k];
            cv::line(sourceImage,
                     cv::Point(segment[0], segment[1]),
                     cv::Point(segment[2], segment[3]),
                     cv::Scalar(0, 0, 255),
                     3,
                     cv::LINE_AA);
        }

        // Show the result with overlaid lane lines
        cv::imshow("Lane Detection Result", sourceImage);
        cv::waitKey(0);
    }

    return 0;
}

