template <typename U>
class python_converter {
public:
    python_converter(PyObject* input)
        : m_base(input)
    {
        // Initialization logic
    }
    U execute_conversion() {
        if (!PyCallable_Check(m_base)) {
            PyErr_SetString(PyExc_TypeError, "Input must be a callable object");
            throw error_already_set();
        }
        PyObject* output = PyObject_CallObject(m_base, nullptr);
        if (output == nullptr) {
            throw error_already_set();
        }
        if (!PyArg_Parse(output, "U", &m_stored_value)) {
            PyErr_SetString(PyExc_TypeError, "Unable to convert Python object to C++ type");
            throw error_already_set();
        }
        Py_DECREF(output);
        return m_stored_value;
    }
private:
    PyObject* m_base;
    U m_stored_value;
};

