class MemoryManager {
public:
    void* requestMemory(size_t bytes) {
        void* addr = mcpputil::pointer_utils::allocate(bytes);
        m_active_blocks.insert(addr);
        m_cumulative_usage += bytes;
        return addr;
    }
    void releaseMemory(void* addr, size_t bytes) {
        auto iter = m_active_blocks.find(addr);
        if (iter != m_active_blocks.end()) {
            mcpputil::pointer_utils::deallocate(addr, bytes);
            m_active_blocks.erase(iter);
            m_cumulative_usage -= bytes;
        }
    }
    ~MemoryManager() {
        for (auto addr : m_active_blocks) {
            std::cerr << "Unreleased memory block at: " << addr << std::endl;
            mcpputil::pointer_utils::deallocate(addr, /* size */); // Cleanup without known size for demo
        }
    }
    size_t getCurrentUsage() const {
        return m_cumulative_usage;
    }
private:
    std::unordered_set<void*> m_active_blocks;
    size_t m_cumulative_usage = 0;
};

int main() {
    MemoryManager manager;
    // Request memory blocks
    void* blockA = manager.requestMemory(128);
    void* blockB = manager.requestMemory(256);
    // Release one block
    manager.releaseMemory(blockA, 128);
    // blockB intentionally left allocated to simulate leak
    // Report current usage
    std::cout << "Current memory usage: " << manager.getCurrentUsage() << " bytes" << std::endl;
    // Destructor will report remaining leaked block
    return 0;
}

