// Thread-local storage mapping lock flags to their associated state
thread_local std::unordered_map<LockFlags, LockState> local_lock_states;

// Global mutex to protect access to thread-local data
std::mutex local_lock_states_mutex;

LockState* RetrieveThreadLockState(LockFlags flag) {
  // Acquire exclusive access to the thread-local map
  std::lock_guard<std::mutex> guard(local_lock_states_mutex);

  // Look up the state for the given flag
  auto iter = local_lock_states.find(flag);
  if (iter == local_lock_states.end()) {
    // If not present, initialize a new state for this flag
    local_lock_states[flag] = LockState{};
  }

  // Return pointer to the corresponding state object
  return &local_lock_states[flag];
}

