// Abstract base class for logging
class LogHandler {
public:
    virtual void write(const std::string& severity, const std::string& content) = 0;
};

// Concrete logger using formatted timestamp
class StdoutLogger : public LogHandler {
public:
    void write(const std::string& severity, const std::string& content) override {
        std::time_t currentTime = std::time(nullptr);
        std::tm* localTime = std::localtime(&currentTime);
        char timeBuffer[80];
        std::strftime(timeBuffer, sizeof(timeBuffer), "%Y-%m-%d %H:%M:%S", localTime);
        std::cout << "[" << timeBuffer << "] " << severity << ": " << content << std::endl;
    }
};

// Simple custom logger without timestamps
class SimpleLogger : public LogHandler {
public:
    void write(const std::string& severity, const std::string& content) override {
        std::cout << severity << ": " << content << std::endl;
    }
};

// Manager class to handle logging with different handlers
class LoggingManager {
private:
    LogHandler* handler;
public:
    LoggingManager(LogHandler* logHandler) : handler(logHandler) {}

    void Warning(const char* fmt, ...) {
        va_list arguments;
        va_start(arguments, fmt);
        char messageBuffer[256];
        vsnprintf(messageBuffer, sizeof(messageBuffer), fmt, arguments);
        va_end(arguments);
        handler->write("WARNING", messageBuffer);
    }
};

int main() {
    StdoutLogger stdoutImpl;
    SimpleLogger simpleImpl;

    LoggingManager manager1(&stdoutImpl);
    manager1.Warning("Test message: %s", "value1");

    LoggingManager manager2(&simpleImpl);
    manager2.Warning("Test message: %s", "value1");

    return 0;
}

