class NumericExpression {
public:
    NumericExpression(double num) : number(num) {}
    double evaluate() const { return number; }
private:
    double number;
};

class ExponentiationExpression {
public:
    ExponentiationExpression(const NumericExpression* baseExpr, const NumericExpression* expExpr) 
        : baseExpression(baseExpr), exponentExpression(expExpr) {}
    double evaluate() const { 
        return std::pow(baseExpression->evaluate(), exponentExpression->evaluate()); 
    }
private:
    const NumericExpression* baseExpression;
    const NumericExpression* exponentExpression;
};

void runExponentiationTests() {
    // First test scenario
    {
        NumericExpression baseNum(2);
        NumericExpression expNum(5);
        ExponentiationExpression powerOp(&baseNum, &expNum);
        assert(powerOp.evaluate() == 32);
    }

    // Second test scenario
    {
        NumericExpression baseNum(3);
        NumericExpression expNum(4);
        ExponentiationExpression powerOp(&baseNum, &expNum);
        assert(powerOp.evaluate() == 81);
    }

    // Third test scenario
    {
        NumericExpression baseNum(5);
        NumericExpression expNum(2);
        ExponentiationExpression powerOp(&baseNum, &expNum);
        assert(powerOp.evaluate() == 25);
    }
}

int main() {
    runExponentiationTests();
    std::cout << "All tests passed successfully!" << std::endl;
    return 0;
}

