// Determine if there's a valid path through the maze from top-left to bottom-right
bool checkPath(int rows, int cols, char grid[20][20]) {
    bool visited[20][20] = {{false}};  // Track reachable positions using dynamic programming

    // Initial condition: starting cell is accessible only if it's not blocked
    visited[0][0] = (grid[0][0] == '0');

    // Build the solution table using DP approach
    for (int x = 0; x < rows; x++) {
        for (int y = 0; y < cols; y++) {
            if (grid[x][y] == '0') {
                if (x > 0) visited[x][y] = visited[x][y] || visited[x - 1][y];  // Check upper neighbor
                if (y > 0) visited[x][y] = visited[x][y] || visited[x][y - 1];  // Check left neighbor
            }
        }
    }

    return visited[rows - 1][cols - 1];  // Return whether destination is reachable
}

int main() {
    int rows = 5, cols = 5;
    char grid[20][20] = {
                    "00000",
                    "00X00",
                    "000X0",
                    "0X000",
                    "00000"
                };
    cout << (checkPath(rows, cols, grid) ? "Path found" : "No path available") << endl;
    return 0;
}

