// Function to read and decode a 2-bit sequence file
std::vector<std::string> read2BitFile(const std::string& filePath) {
    std::ifstream inputStream(filePath, std::ios::binary);
    if (!inputStream.is_open()) {
        throw std::runtime_error("Unable to open file: " + filePath);
    }

    // Read number of sequences from header
    int numSequences;
    inputStream.read(reinterpret_cast<char*>(&numSequences), sizeof(numSequences));

    std::vector<std::string> namesOfSequences(numSequences);
    for (int idx = 0; idx < numSequences; ++idx) {
        int lenName;
        inputStream.read(reinterpret_cast<char*>(&lenName), sizeof(lenName));
        namesOfSequences[idx].resize(lenName);
        inputStream.read(&namesOfSequences[idx][0], lenName);
    }

    // Process each sequence
    std::vector<std::string> resultSequences;
    for (const auto& name : namesOfSequences) {
        int seqLen;
        inputStream.read(reinterpret_cast<char*>(&seqLen), sizeof(seqLen));

        std::string compressedData;
        compressedData.resize(seqLen);
        inputStream.read(&compressedData[0], seqLen);

        // Decode 2-bit encoded data into nucleotide characters
        std::string expandedSequence;
        for (char byteVal : compressedData) {
            std::bitset<2> bitPattern(byteVal);
            expandedSequence += "TGCA"[bitPattern.to_ulong()];
        }
        resultSequences.push_back(expandedSequence);
    }

    inputStream.close();
    return resultSequences;
}

#include <iostream>

// Determine if a number is a power of two
bool checkPowerOfTwo(int value) {
    if (value <= 0) {
        return false;  // Non-positive values cannot be powers of two
    }
    return (value & (value - 1)) == 0;  // Powers of two have exactly one bit set in binary form
}

int main() {
    int userInput;
    std::cout << "Enter a positive integer: ";
    std::cin >> userInput;

    if (checkPowerOfTwo(userInput)) {
        std::cout << "The provided number is a power of two" << std::endl;
    } else {
        std::cout << "The provided number is not a power of two" << std::endl;
    }

    return 0;
}

