class Logger {
private:
    std::ostream& stream;
    std::string prefix;
public:
    Logger(std::ostream& out, const std::string& fileName, const std::string& level) : stream(out) {
        prefix = '[' + std::filesystem::path(fileName).filename().string() + "] " + level + '\t';
    }

    template <typename Type>
    std::ostream& operator<<(Type value) {
        return stream << prefix << value;
    }
};

int main() {
    // Demonstration of logger usage
    std::ofstream logFile("output.log");
    Logger fileLogger(logFile, "main.cpp", "DEBUG");
    fileLogger << "Debugging information here." << std::endl;

    Logger consoleLogger(std::cout, "main.cpp", "WARNING");
    consoleLogger << "Warning: something unexpected happened!" << std::endl;

    return 0;
}

