class Camera2D {
private:
    sf::RenderTarget* m_renderTarget;
    sf::View m_cameraView;
public:
    Camera2D(sf::RenderTarget* target, float width, float height)
        : m_renderTarget(target) {
        m_cameraView = m_renderTarget->getView();
        m_cameraView.setViewport(sf::FloatRect(0, 0, width, height));
        resize(m_renderTarget->getSize());
        applyView();
    }

    void applyView() {
        m_renderTarget->setView(m_cameraView);
    }

    void resize(sf::Vector2u dimensions) {
        m_cameraView.setSize(static_cast<float>(dimensions.x), static_cast<float>(dimensions.y));
    }
};

