#include <iostream>
#include <unordered_map>
#include <sstream>

class QueryBuilder {
private:
    std::unordered_map<std::string, std::string> parameters;
public:
    void Add(const std::string& name, const std::string& val) {
        parameters[name] = val;
    }
    std::string Build() const {
        if (parameters.empty()) {
            return "";
        }
        std::stringstream stream;
        stream << "?";
        for (auto iter = parameters.begin(); iter != parameters.end(); ++iter) {
            stream << iter->first << "=" << iter->second;
            if (std::next(iter) != parameters.end()) {
                stream << "&";
            }
        }
        return stream.str();
    }
};

int main() {
    QueryBuilder builder1, builder2, builder3;
    std::cout << "builder1: " << builder1.Build() << std::endl;  // Output: ""

    builder1.Add("param1", "data1");
    std::cout << "builder1: " << builder1.Build() << std::endl;  // Output: "?param1=data1"

    builder1.Add("param2", "data2");
    std::cout << "builder1: " << builder1.Build() << std::endl;  // Output: "?param1=data1&param2=data2"
    return 0;
}

