// A class for creating and managing histogram data
class DataDistribution {
private:
    const double &lowerBound;
    const double &upperBound;
    const int &numSegments;
    double segmentSize;
    std::vector<int> counts;

    // Determine which segment a value belongs to
    int locateSegment(const double &value) {
        return static_cast<int>((value - lowerBound) / segmentSize);
    }

public:
    DataDistribution(const double &low, const double &high, const int &segments)
        : lowerBound(low), upperBound(high), numSegments(segments), counts(segments, 0) {
        segmentSize = (upperBound - lowerBound) / numSegments;
    }

    void includeValue(const double &value) {
        int segmentIndex = locateSegment(value);
        if (segmentIndex >= 0 && segmentIndex < numSegments) {
            counts[segmentIndex]++;
        }
    }

    int getSegmentFrequency(const int &index) {
        if (index >= 0 && index < numSegments) {
            return counts[index];
        }
        return 0;
    }
};

int main() {
    DataDistribution distribution(0.0, 10.0, 5);
    distribution.includeValue(2.5);
    distribution.includeValue(7.8);
    distribution.includeValue(11.0);

    std::cout << "Segment 2 frequency: " << distribution.getSegmentFrequency(2) << std::endl;  // Output: Segment 2 frequency: 1
    std::cout << "Segment 4 frequency: " << distribution.getSegmentFrequency(4) << std::endl;  // Output: Segment 4 frequency: 0

    return 0;
}

#include <iostream>
#include <fstream>
using namespace std;

int main() {
    int size, shift;
    cin >> size;
    int matrix[size+1][size+1];

    for(int row = 1; row <= size; row++) {
        for(int col = 1; col <= size; col++) {
            cin >> matrix[row][col];
        }
    }

    int index = 0;
    int extracted[size*size+1];

    // First quadrant extraction
    for(int i = 1; i <= size/2; i++) {
        index++;
        extracted[index] = matrix[i][size/2 - i + 1];
    }

    // Second quadrant extraction
    for(int i = 1; i <= size/2; i++) {
        index++;
        extracted[index] = matrix[size/2 + i][i];
    }

    // Third quadrant extraction
    for(int i = 1; i <= size/2; i++) {
        index++;
        extracted[index] = matrix[size - i + 1][size/2 + i];
    }

    // Fourth quadrant extraction
    for(int i = 1; i <= size/2; i++) {
        index++;
        extracted[index] = matrix[size/2 - i + 1][size - i + 1];
    }

    cin >> shift;

    // Output elements from position shift+1 to end, then wrap around
    for(int i = shift + 1; i <= index; i++) {
        cout << extracted[i] << " ";
    }
    for(int i = 1; i <= shift; i++) {
        cout << extracted[i] << " ";
    }

    return 0;
}

