// Determine the minimum buffer size needed for a specific computational task
int determineMinBufferSize(char operation, int stride, int matrixOrder) {
    if (operation == 'E') {
        return 1;  // Buffer size for eigenvalue computation
    } else {
        // Compute buffer size for Schur decomposition using stride and matrix dimensions
        return stride * (matrixOrder + 6);
    }
}

