    int strideVal = 10; // Leading dimension of the working buffer
    int dim = 5;        // Size of the square matrix
    // Compute and output the required buffer size
    int bufferSize = determineMinBufferSize(opType, strideVal, dim);
    std::cout << "Minimum buffer size required: " << bufferSize << std::endl;
    return 0;
}

