#include <iostream>

// Define the maximum number of threads allowed
#define MAX_THREADS 8

class ThreadManager {
private:
    unsigned int _threadCount;
public:
    // Constructor initializes thread count to 1
    ThreadManager() : _threadCount(1) {}

    // Method to configure the number of threads
    HRESULT ConfigureThreadCount(unsigned int requestedThreads) {
        const unsigned int maxAllowed = MAX_THREADS;

        if (requestedThreads < 1) {
            requestedThreads = 1;
        }
        if (requestedThreads > maxAllowed) {
            requestedThreads = maxAllowed;
        }

        _threadCount = requestedThreads;
        return S_OK;
    }

    // Accessor method to retrieve current thread count
    unsigned int GetThreadCount() const {
        return _threadCount;
    }
};

int main() {
    ThreadManager manager;

    manager.ConfigureThreadCount(5);
    std::cout << "Configured threads: " << manager.GetThreadCount() << std::endl;  // Output: Configured threads: 5

    manager.ConfigureThreadCount(10);
    std::cout << "Configured threads: " << manager.GetThreadCount() << std::endl;  // Output: Configured threads: 8 (capped at maximum)

    manager.ConfigureThreadCount(0);
    std::cout << "Configured threads: " << manager.GetThreadCount() << std::endl;  // Output: Configured threads: 1 (minimum enforced)

    return 0;
}

