class custom_error : public std::runtime_error {
public:
    custom_error(const char *format_str, ...) : std::runtime_error("") {
        va_list args;
        va_start(args, format_str);
        char msg_buffer[512];  // Increased buffer size for longer messages
        vsnprintf(msg_buffer, sizeof(msg_buffer), format_str, args);
        va_end(args);
        error_message = msg_buffer;
    }
    const char* what() const noexcept override {
        return error_message.c_str();
    }
private:
    std::string error_message;
};

int main() {
    try {
        throw custom_error("Error: %d %s", 404, "Not Found");
    }
    catch (const std::exception& e) {
        printf("Caught: %s\n", e.what());
    }
    return 0;
}

