// Structure representing a file creation request
struct FileRequest {
    FileId              fileId;
    Utility::TextView   fileName;
    Utility::U32        permissions;
    AccessMode          accessMode;
};

// Structure representing the outcome of an operation
struct OperationResult {
    bool success;
    Utility::TextView description;
};

// Simple user representation for demonstration
struct UserAccount {
    int accountId;
    std::unordered_map<FileId, AccessMode> accessRights;
};

// Predefined user database for testing
std::unordered_map<int, UserAccount> accountDatabase = {
    {101, {101, {{10, AccessMode::WriteOnly}, {20, AccessMode::ReadOnly}}}},
    {102, {102, {{10, AccessMode::ReadOnly}, {20, AccessMode::WriteOnly}}}}
};

// Function to handle file creation with permission checks
OperationResult handleFileCreation(const FileRequest& req, int userId) {
    auto userIt = accountDatabase.find(userId);
    if (userIt != accountDatabase.end()) {
        auto& user = userIt->second;
        auto permIt = user.accessRights.find(req.fileId);
        if (permIt != user.accessRights.end() && permIt->second == AccessMode::WriteOnly) {
            // Proceed with file creation logic
            return {true, "File successfully created"};
        } else {
            return {false, "Permission denied: insufficient rights for this directory"};
        }
    } else {
        return {false, "User account does not exist"};
    }
}

int main() {
    // Example scenario
    FileRequest request{10, "document.txt", 0640, AccessMode::WriteOnly};
    OperationResult outcome = handleFileCreation(request, 101);
    std::cout << "Creation status: " << outcome.description << std::endl;
    return 0;
}

