class DiningPhilosophers {
public:
    DiningPhilosophers(int count) : forks(count) {}

    void wantsToEat(int philosopher, 
                    function<void()> takeLeftFork, 
                    function<void()> takeRightFork, 
                    function<void()> consume, 
                    function<void()> releaseLeftFork, 
                    function<void()> releaseRightFork) {

        int leftForkIndex = philosopher;
        int rightForkIndex = (philosopher + 1) % forks.size();

        if (philosopher % 2 == 0) {
            // Even-numbered philosophers: pick left first, then right
            forks[leftForkIndex].lock();
            takeLeftFork();
            forks[rightForkIndex].lock();
            takeRightFork();
            consume();
            releaseRightFork();
            forks[rightForkIndex].unlock();
            releaseLeftFork();
            forks[leftForkIndex].unlock();
        } else {
            // Odd-numbered philosophers: pick right first, then left
            forks[rightForkIndex].lock();
            takeRightFork();
            forks[leftForkIndex].lock();
            takeLeftFork();
            consume();
            releaseLeftFork();
            forks[leftForkIndex].unlock();
            releaseRightFork();
            forks[rightForkIndex].unlock();
        }
    }

private:
    vector<mutex> forks;
};

