public:
    GridManager(const std::vector<std::vector<char>>& startGrid) : matrix(startGrid) {}

    std::string extract(int row, int col, Orientation orientation, int size) {
        std::string result;
        if (orientation == Orientation::Horizontal) {
            for (int index = col; index < col + size; ++index) {
                result += matrix[row][index];
            }
        } else if (orientation == Orientation::Vertical) {
            for (int index = row; index < row + size; ++index) {
