#include <mutex>
#include <ctime>

enum class Severity { TRACE, NOTICE, ALERT, CRITICAL, PANIC };

class LogHandler {
public:
    LogHandler() : minSeverity(Severity::NOTICE) {}

    void setMinimumSeverity(Severity level) {
        minSeverity = level;
    }

    void enableConsole() {
        targets.push_back(&std::cout);
    }

    void enableFile(const std::string& path) {
        std::ofstream* stream = new std::ofstream(path);
        targets.push_back(stream);
    }

    void write(Severity level, const std::string& text) {
        if (level >= minSeverity) {
            std::lock_guard<std::mutex> guard(mtx);
            for (auto out : targets) {
                *out << timestamp() << " [" << severityName(level) << "] " << text << std::endl;
            }
        }
    }

    ~LogHandler() {
        for (auto out : targets) {
            if (out != &std::cout) {
                std::ofstream* file = static_cast<std::ofstream*>(out);
                file->close();
                delete file;
            }
        }
    }

private:
    Severity minSeverity;
    std::vector<std::ostream*> targets;
    std::mutex mtx;

    std::string timestamp() {
        std::time_t now = std::time(nullptr);
        char buf[64];
        std::strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", std::localtime(&now));
        return std::string(buf);
    }

    std::string severityName(Severity sev) {
        switch (sev) {
            case Severity::TRACE:   return "TRACE";
            case Severity::NOTICE:  return "NOTICE";
            case Severity::ALERT:   return "ALERT";
            case Severity::CRITICAL:return "CRITICAL";
            case Severity::PANIC:   return "PANIC";
            default:                return "UNKNOWN";
        }
    }
};

int main() {
    LogHandler handler;
    handler.enableConsole();
    handler.enableFile("application.log");
    handler.setMinimumSeverity(Severity::TRACE);

    handler.write(Severity::NOTICE,  "Application started successfully");
    handler.write(Severity::ALERT,   "Memory usage exceeded threshold");
    handler.write(Severity::CRITICAL,"Disk space running low");
    handler.write(Severity::TRACE,   "Entering function processInput()");

    return 0;
}

