// Process a string by reversing it and folding into segments separated by commas
std::string transformAndSegment(const std::string& source, int segmentSize) {
    std::string reversedCopy = source;
    std::reverse(reversedCopy.begin(), reversedCopy.end());

    std::string result;
    for (size_t index = 0; index < reversedCopy.length(); index += segmentSize) {
        result += reversedCopy.substr(index, segmentSize);
        if (index + segmentSize < reversedCopy.length()) {
            result += ",";
        }
    }
    return result;
}

