// Hash table implementation using separate chaining for collision resolution
class HashMap {
private:
    struct Entry {
        LPVOID key;
        LPVOID value;
        Entry* next;  // Next entry in the chain
    };
    Entry** buckets;  // Array of bucket pointers
    size_t capacity;
    size_t count;
    double maxLoadFactor;

    // Compute hash index from key data
    size_t computeIndex(LPVOID pKey, size_t keySize) {
        // Simple hash computation: sum bytes and apply modulo
        unsigned long hash = 0;
        unsigned char* bytes = static_cast<unsigned char*>(pKey);
        for (size_t i = 0; i < keySize; ++i) {
            hash = hash * 31 + bytes[i];
        }
        return hash % capacity;
    }

    // Insert new entry at the front of the chain at given bucket index
    void addEntry(size_t bucketIdx, LPVOID pKey, LPVOID pValue) {
        Entry* newNode = new Entry;
        newNode->key = pKey;
        newNode->value = pValue;
        newNode->next = buckets[bucketIdx];
        buckets[bucketIdx] = newNode;
    }

    // Expand storage when load factor becomes too high
    void expandBuckets() {
        size_t newCapacity = capacity * 2;
        Entry** newBuckets = new Entry*[newCapacity];
        std::memset(newBuckets, 0, sizeof(Entry*) * newCapacity);

        for (size_t i = 0; i < capacity; ++i) {
            Entry* current = buckets[i];
            while (current != nullptr) {
                size_t newIndex = computeIndex(current->key, /* key size would need to be stored */ 0);
                Entry* next = current->next;
                current->next = newBuckets[newIndex];
                newBuckets[newIndex] = current;
                current = next;
            }
        }

        delete[] buckets;
        buckets = newBuckets;
        capacity = newCapacity;
    }

public:
    HashMap(size_t initialCapacity, double loadLimit) {
        capacity = initialCapacity;
        maxLoadFactor = loadLimit;
        buckets = new Entry*[capacity];
        std::memset(buckets, 0, sizeof(Entry*) * capacity);
        count = 0;
    }

    ~HashMap() {
        // Clean up all entries to prevent memory leaks
        for (size_t i = 0; i < capacity; ++i) {
            Entry* current = buckets[i];
            while (current != nullptr) {
                Entry* next = current->next;
                delete current;
                current = next;
            }
        }
        delete[] buckets;
    }

    // Add a new key-value mapping
    void put(LPVOID pKey, size_t keySize, LPVOID pValue) {
        if ((double)count / capacity > maxLoadFactor) {
            expandBuckets();
        }

        size_t idx = computeIndex(pKey, keySize);
        if (buckets[idx] == nullptr) {
            buckets[idx] = new Entry;
            buckets[idx]->key = pKey;
            buckets[idx]->value = pValue;
            buckets[idx]->next = nullptr;
        } else {
            addEntry(idx, pKey, pValue);
        }
        count++;
    }

    // Get value associated with a key, or nullptr if not found
    LPVOID get(LPVOID pKey, size_t keySize) {
        size_t idx = computeIndex(pKey, keySize);
        Entry* node = buckets[idx];
        while (node != nullptr) {
            // In real code, would compare actual key contents here
            if (/* key comparison logic */ true) {
                return node->value;
            }
            node = node->next;
        }
        return nullptr;
    }

    // Delete a key-value pair by key
    void erase(LPVOID pKey, size_t keySize) {
        size_t idx = computeIndex(pKey, keySize);
        Entry* prev = nullptr;
        Entry* current = buckets[idx];

        while (current != nullptr) {
            if (/* key match check */) {
                if (prev == nullptr) {
                    buckets[idx] = current->next;
                } else {
                    prev->next = current->next;
                }
                delete current;
                count--;
                return;
            }
            prev = current;
            current = current->next;
        }
    }
};

