// Process and output queued log entries 
void drainLogBuffer() {
    std::unique_lock<std::recursive_mutex> guard(this->sync.lock);

    // Exit early if no logs are waiting
    if (this->buffer.empty()) {
        return;
    }

    // Capture current logs for processing
    auto bufferedEntries = this->buffer;
    this->buffer.clear();

    // Wait for any ongoing flush operation to complete
    auto isFlushComplete = [this] { return !this->sync.inProgress.load(); };
    this->sync.condition.wait(guard, isFlushComplete);

    // Mark that we're now processing logs
    this->sync.inProgress.store(true);
    guard.unlock(); // Release synchronization before I/O operations

    // Output each captured log entry
    for (const auto& entry : bufferedEntries) {
        // Simulate log output
        std::cout << "Outputting entry: " << entry << std::endl;
    }

    guard.lock(); // Reacquire lock for state update
    this->sync.inProgress.store(false); // Indicate processing is done
    this->sync.condition.notify_all(); // Wake up any waiting threads
}

#include <vector>

class FloodFill {
private:
    std::vector<std::vector<int>> matrix;
    int height;
    int width;

    void expand(int row, int col, int prevValue, int newValue) {
        if (row < 0 || row >= height || col < 0 || col >= width || matrix[row][col] != prevValue) {
            return;
        }

        matrix[row][col] = newValue;
        expand(row + 1, col, prevValue, newValue);
        expand(row - 1, col, prevValue, newValue);
        expand(row, col + 1, prevValue, newValue);
        expand(row, col - 1, prevValue, newValue);
    }

public:
    FloodFill() : height(10), width(10), 
                  matrix(std::vector<std::vector<int>>(10, std::vector<int>(10, 0))) {
        // Set up the matrix with initial dimensions and zero values
    }

    void performFill(int x, int y, int replacementColor) {
        if (x < 0 || x >= height || y < 0 || y >= width) {
            return;
        }

        int originalColor = matrix[x][y];
        if (originalColor == replacementColor) {
            return;
        }

        expand(x, y, originalColor, replacementColor);
    }
};

