#include <iostream>
#include <vector>
#include <algorithm>
#include <stack>

// Implementation of Tarjan's algorithm for finding strongly connected components (SCCs)
class TarjanSCC {
private:
    int n;
    std::vector<std::vector<int>> graph;
    std::vector<int> ids;
    std::vector<int> low;
    std::vector<bool> onStack;
    std::stack<int> stack;
    int idCounter;
    std::vector<std::vector<int>> sccs;

    void dfs(int vertex) {
        stack.push(vertex);
        onStack[vertex] = true;
        ids[vertex] = low[vertex] = idCounter++;

        for (int neighbor : graph[vertex]) {
            if (ids[neighbor] == -1) {
                dfs(neighbor);
                low[vertex] = std::min(low[vertex], low[neighbor]);
            } else if (onStack[neighbor]) {
                low[vertex] = std::min(low[vertex], ids[neighbor]);
            }
        }

        if (ids[vertex] == low[vertex]) {
            std::vector<int> component;
            int current;
            do {
                current = stack.top();
                stack.pop();
                onStack[current] = false;
                component.push_back(current);
                low[current] = ids[vertex];
            } while (current != vertex);

            std::sort(component.begin(), component.end());
            sccs.push_back(component);
        }
    }

public:
    TarjanSCC(int numVertices) : n(numVertices), 
                                  graph(numVertices), 
                                  ids(numVertices, -1), 
                                  low(numVertices), 
                                  onStack(numVertices, false),
                                  idCounter(0) {}

    void addEdge(int from, int to) {
        graph[from].push_back(to);
    }

    std::vector<std::vector<int>> findSCCs() {
        for (int i = 0; i < n; ++i) {
            if (ids[i] == -1) {
                dfs(i);
            }
        }

        std::sort(sccs.begin(), sccs.end());
        return sccs;
    }
};

