void AnimateSprite(Entity* entity, float deltaTime, uint32_t frameCount) {
    sf::Clock* clock = entity->mProperties.Get<sf::Clock>("AnimationClock");
    uint32_t currentFrameIndex = entity->mProperties.GetUint32("uCurrentFrame");

    // Calculate time elapsed since last frame update
    float secondsPerFrame = 1.0f; // Each frame displays for 1 second
    float timeAccumulated = clock->restart().asSeconds();

    // Advance frame count based on accumulated time
    currentFrameIndex += static_cast<uint32_t>(timeAccumulated / secondsPerFrame);

    // Wrap around to keep frame index within bounds
    currentFrameIndex %= frameCount;

    // Store updated frame index back to properties
    entity->mProperties.SetUint32("uCurrentFrame", currentFrameIndex);
}

