// Represents a property of a class element
class Property {
public:
    std::string identifier;
    std::string dataType;
    // Additional details about the property can be included here
};

// Holds structural information about a class
class ClassInfo {
public:
    std::string className;
    bool isNested;
    std::vector<Property> properties;
    std::vector<ClassInfo> nestedClasses;
};

// Manages registration and storage of class metadata
class MetadataManager {
private:
    std::vector<ClassInfo> storedClasses;
public:
    // Add a new class to the registry
    voidaddClass(const std::string& className, bool isNested = false) {
        ClassInfo newEntry;
        newEntry.className = className;
        newEntry.isNested = isNested;
        storedClasses.push_back(newEntry);
    }

    // Register a nested class under an existing parent class
    void addNestedClass(const std::string& parentName, const std::string& nestedName) {
        for (auto& entry : storedClasses) {
            if (entry.className == parentName) {
                ClassInfo nestedEntry;
                nestedEntry.className = nestedName;
                nestedEntry.isNested = true;
                entry.nestedClasses.push_back(nestedEntry);
                return;
            }
        }
        std::cerr << "Warning: Parent class '" << parentName << "' does not exist." << std::endl;
    }

    // Attach a property to a specific class
    void attachProperty(const std::string& className, const std::string& propName, const std::string& type) {
        for (auto& entry : storedClasses) {
            if (entry.className == className) {
                Property newItem;
                newItem.identifier = propName;
                newItem.dataType = type;
                entry.properties.push_back(newItem);
                return;
            }
        }
        std::cerr << "Error: Class '" << className << "' is not registered." << std::endl;
    }

    // Additional functionality for metadata retrieval or modification can be implemented here
};

