#include <mpi.h>

#define MATRIX_DIM 100 // Define the dimension of square matrices

int main(int argc, char *argv[]) {
    int my_rank, comm_size;
    MPI_Init(&argc, &argv);
    MPI_Comm_rank(MPI_COMM_WORLD, &my_rank);
    MPI_Comm_size(MPI_COMM_WORLD, &comm_size);

    if (argc != 2) {
        if (my_rank == 0) {
            std::cerr << "Usage: " << argv[0] << " <num_procs>" << std::endl;
        }
        MPI_Finalize();
        return 1;
    }

    int num_procs = std::stoi(argv[1]);
    if (num_procs < 1) {
        if (my_rank == 0) {
            std::cerr << "Process count must be >= 1." << std::endl;
        }
        MPI_Finalize();
        return 1;
    }

    // Matrix A and B storage
    std::vector<std::vector<int>> matA(MATRIX_DIM, std::vector<int>(MATRIX_DIM));
    std::vector<std::vector<int>> matB(MATRIX_DIM, std::vector<int>(MATRIX_DIM));

    if (my_rank == 0) {
        // Load matrices from files (placeholder for actual file reading)
        // ...

        // Distribute matrices to all processes
        MPI_Bcast(&matA[0][0], MATRIX_DIM * MATRIX_DIM, MPI_INT, 0, MPI_COMM_WORLD);
        MPI_Bcast(&matB[0][0], MATRIX_DIM * MATRIX_DIM, MPI_INT, 0, MPI_COMM_WORLD);
    }

    // Compute portion of result matrix C
    int rows_per_proc = MATRIX_DIM / num_procs;
    std::vector<std::vector<int>> local_C(rows_per_proc, std::vector<int>(MATRIX_DIM, 0));

    for (int row = my_rank * rows_per_proc; row < (my_rank + 1) * rows_per_proc; ++row) {
        for (int col = 0; col < MATRIX_DIM; ++col) {
            for (int k = 0; k < MATRIX_DIM; ++k) {
                local_C[row - my_rank * rows_per_proc][col] += matA[row][k] * matB[k][col];
            }
        }
    }

    // Collect results on rank 0
    std::vector<std::vector<int>> full_C(MATRIX_DIM, std::vector<int>(MATRIX_DIM));
    MPI_Gather(&local_C[0][0], rows_per_proc * MATRIX_DIM, MPI_INT,
               &full_C[0][0], rows_per_proc * MATRIX_DIM, MPI_INT, 0, MPI_COMM_WORLD);

    if (my_rank == 0) {
        // Save result to output file
        std::ofstream out_file("matrix_product.txt");
        for (int i = 0; i < MATRIX_DIM; ++i) {
            for (int j = 0; j < MATRIX_DIM; ++j) {
                out_file << full_C[i][j] << " ";
            }
            out_file << "\n";
        }
        out_file.close();
    }

    MPI_Finalize();
    return 0;
}

