// Function to decode and unflatten IPC parameters
bool IPCIntelPGParam::serverUnflattenDecode(void* buffer, int bufferSize, uintptr_t* outClient,
                                            int32_t* outPayloadCount, ia_binary_data** outPayloads) {
    // Validate input buffer pointer
    CheckError(!buffer, false, "@%s, buffer is nullptr", __func__);
    // Ensure buffer size is sufficient for expected structure
    CheckError(bufferSize < sizeof(pg_param_decode_params), false, "@%s, insufficient size", __func__);
    // Verify client output pointer
    CheckError(!outClient, false, "@%s, null client output", __func__);
    // Verify payload count output pointer
    CheckError(!outPayloadCount, false, "%s, null payload count output", __func__);

    // Interpret buffer as parameter structure
    pg_param_decode_params* params = static_cast<pg_param_decode_params*>(buffer);

    // Extract client identifier
    *outClient = params->client;
    // Extract number of payloads
    *outPayloadCount = params->payloadCount;

    // Allocate memory for payloads and copy them
    *outPayloads = new ia_binary_data[params->payloadCount];
    for (int index = 0; index < params->payloadCount; ++index) {
        (*outPayloads)[index] = params->payloads[index];
    }

    // Update statistics handle in the parameters
    params->clientStatsHandle = statsHandle;

    return true;
}

#include <iostream>
#include <stack>
#include <string>

class ThreadIdManager {
public:
    using ThreadName = std::string;
    using ThreadIdentifier = std::pair<ThreadName, int>;

    ThreadIdManager() : next_id(0) {}

    ThreadIdentifier create() {
        ThreadIdentifier identifier;
        if (freelist.empty()) {
            identifier.second = next_id++;
        } else {
            identifier.second = freelist.top();
            freelist.pop();
        }
        return identifier;
    }

    void release(const ThreadName& name) {
        // Mark the thread name as released for reuse
        std::cout << "Releasing thread name: " << name << std::endl;
    }

private:
    int next_id;
    std::stack<int> freelist;
};

int main() {
    ThreadIdManager manager;
    ThreadIdManager::ThreadIdentifier id1 = manager.create();
    ThreadIdManager::ThreadIdentifier id2 = manager.create();

    std::cout << "Created thread ID 1: " << id1.second << std::endl;
    std::cout << "Created thread ID 2: " << id2.second << std::endl;

    manager.release(id1.first);
    manager.release(id2.first);

    return 0;
}

