    std::string reverseWords(const std::string& text) {
        std::istringstream stream(text);
        std::string token, output;
        while (stream >> token) {
            std::reverse(token.begin(), token.end());
            output = (output.empty()) ? token : token + " " + output;
        }
        return output;
    }
