// Different terrain categories for the map
enum class MapTerrain { FOREST, RIVER, HILL, SAND }; // Modified terrain types

// Generate a 2D terrain map with specified parameters
void generate_terrain_map(int cols, int rows, float fill_ratio, int random_seed, int terrain_count) {
    // Validate input parameters
    if (cols == 0 || rows == 0) {
        throw std::invalid_argument("Map dimensions cannot be zero.");
    }
    if (fill_ratio <= 0.0f || fill_ratio > 1.0f) {
        throw std::invalid_argument("Fill ratio must be in the range (0.0, 1.0].");
    }

    // Initialize random number generator with seed
    std::mt19937 rng(random_seed);
    std::uniform_real_distribution<float> distribution(0.0f, 1.0f);

    // Create 2D grid initialized with default terrain (FOREST)
    std::vector<std::vector<MapTerrain>> grid(rows, std::vector<MapTerrain>(cols, MapTerrain::FOREST));

    // Populate map based on density
    for (int row = 0; row < rows; ++row) {
        for (int col = 0; col < cols; col++) {
            float random_value = distribution(rng);
            if (random_value < fill_ratio) {
                int selected_terrain = rand() % terrain_count;
                grid[row][col] = static_cast<MapTerrain>(selected_terrain);
            }
        }
    }

    // Display the generated terrain map
    for (int row = 0; row < rows; ++row) {
        for (int col = 0; col < cols; col++) {
            std::cout << static_cast<int>(grid[row][col]) << " ";
        }
        std::cout << std::endl;
    }
}

int main(int argc, char **args) {
    try {
        // Generate a 30x20 map with full density and 4 terrain types
        generate_terrain_map(30, 20, 1.0f, 0, 4);
    } catch (const std::invalid_argument &error) {
        std::cerr << "Error: " << error.what() << std::endl;
    }
    return 0;
}

