template <typename T>
class RGBAColor {
public:
    T r, g, b, a;
    RGBAColor(T red, T green, T blue, T alpha) : r(red), g(green), b(blue), a(alpha) {}
};
typedef RGBAColor<unsigned char> RGBA8; // Represents RGBA color with unsigned char components
using Color = RGBA8;
constexpr Color WHITE{255, 255, 255, 255}; // Represents the color white
constexpr Color BLUE{0, 0, 255, 255};       // Represents the color blue
Color mixColors(const Color& first, const Color& second, float weight) {
    // Interpolation operation for each color channel
    unsigned char mixed_r = static_cast<unsigned char>((1.0f - weight) * first.r + weight * second.r);
    unsigned char mixed_g = static_cast<unsigned char>((1.0f - weight) * first.g + weight * second.g);
    unsigned char mixed_b = static_cast<unsigned char>((1.0f - weight) * first.b + weight * second.b);

    // Return the mixed color with alpha from the first color
    return Color(mixed_r, mixed_g, mixed_b, first.a);
}
int main() {
    // Mix WHITE and BLUE with various interpolation weights
    float weights[] = {0.25f, 0.75f};
    for (float w : weights) {
        Color result = mixColors(WHITE, BLUE, w);
        std::cout << "Mixed color with weight " << w << ": (" << static_cast<int>(result.r) << ", "
                  << static_cast<int>(result.g) << ", " << static_cast<int>(result.b) << ", "
                  << static_cast<int>(result.a) << ")\n";
    }
    return 0;
}

#include <array>

namespace detail {
    // Recursive helper for transform-reduce operation
    template <typename U, std::size_t N, std::size_t pos>
    struct TransformReduceImpl {
        static constexpr auto execute(const std::array<U, N>& first,
                                     const std::array<U, N>& second,
                                     const auto& op_transform,
                                     const auto& op_combine) {
            return op_combine(op_transform(first[pos], second[pos]),
                             TransformReduceImpl<U, N, pos - 1>::execute(first, second, op_transform, op_combine));
        }
    };

    // Base case specialization when position reaches 0
    template <typename U, std::size_t N>
    struct TransformReduceImpl<U, N, 0> {
        static constexpr auto execute(const std::array<U, N>& first,
                                     const std::array<U, N>& second,
                                     const auto& op_transform,
                                     const auto& op_combine) {
            return op_combine(op_transform(first[0], second[0]), U{});
        }
    };
} // namespace detail

// Public interface for array transform-reduce
template <typename T, std::size_t count, typename Func1, typename Func2>
constexpr auto transform_accumulate(const std::array<T, count>& arr1,
                                   const std::array<T, count>& arr2,
                                   Func1 transform_fn,
                                   Func2 accumulate_fn) 
    -> decltype(transform_fn(arr1[0], arr2[0])) {
    static_assert(count > 0, "Array size must be positive");
    return detail::TransformReduceImpl<T, count, count - 1>::execute(arr1, arr2, transform_fn, accumulate_fn);
}

