#include <unistd.h>  // For sysconf

float LinuxParser::CpuUtilization(int processId) {
  long activeTicks = LinuxParser::ActiveJiffies(processId);
  long systemUptime = LinuxParser::UpTime();

  long elapsedSeconds = activeTicks / sysconf(_SC_CLK_TCK);  // Convert jiffies to seconds
  float runtimeSeconds = systemUptime - (LinuxParser::UpTime(processId) / sysconf(_SC_CLK_TCK));  // Duration the process has been active

  float cpuPercentage = 100.0 * ((elapsedSeconds / runtimeSeconds) / sysconf(_SC_NPROCESSORS_ONLN));  // Compute CPU usage percentage

  return cpuPercentage;
}

