#include <mutex>
#include <condition_variable>

class WorkDispatcher {
public:
    WorkDispatcher() : completedCount(0) {}

    void addTask(const std::function<void()>& workItem) {
        std::unique_lock<std::mutex> guard(mtx);
        pendingTasks.push_back(workItem);
    }

    void runAll() {
        std::vector<std::thread> workerThreads;

        for (int index = 0; index < pendingTasks.size(); ++index) {
            workerThreads.emplace_back([this, index] {
                std::unique_lock<std::mutex> lock(mtx);

                if (index < pendingTasks.size()) {
                    pendingTasks[index]();
                    ++completedCount;
                }

                conditionVar.notify_one();
            });
        }

        for (auto& threadRef : workerThreads) {
            threadRef.join();
        }
    }

    int getCompletedCount() const {
        return completedCount;
    }

private:
    std::vector<std::function<void()>> pendingTasks;
    mutable std::mutex mtx;
    std::condition_variable conditionVar;
    int completedCount;
};

int main() {
    WorkDispatcher dispatcher;

    // Add tasks to be processed
    dispatcher.addTask([] { std::cout << "First job done" << std::endl; });
    dispatcher.addTask([] { std::cout << "Second job done" << std::endl; });
    dispatcher.addTask([] { std::cout << "Third job done" << std::endl; });

    // Launch all tasks in parallel
    dispatcher.runAll();

    // Check how many were completed
    std::cout << "Number of completed tasks: " << dispatcher.getCompletedCount() << std::endl;

    return 0;
}

