// Find the video mode with the highest resolution, refresh rate, and bit depth
std::tuple<int, int, int> findBestVideoMode(const std::vector<std::tuple<int, int, int>>& availableModes) {
    std::tuple<int, int, int> currentBest = availableModes[0];  // Start with the first available mode
    for (const auto& candidate : availableModes) {
        if (std::get<0>(candidate) > std::get<0>(currentBest) ||  // Compare horizontal resolution
            (std::get<0>(candidate) == std::get<0>(currentBest) && std::get<1>(candidate) > std::get<1>(currentBest)) ||  // Same width, compare height
            (std::get<0>(candidate) == std::get<0>(currentBest) && std::get<1>(candidate) == std::get<1>(currentBest) && std::get<2>(candidate) > std::get<2>(currentBest))) {  // Same resolution, compare bit depth
            currentBest = candidate;  // Update to better mode
        }
    }
    return currentBest;
}

