// Interpolate between two group elements using Sophus library
template <class GroupElement, class Parameter>
GroupElement lerp_group(const GroupElement& start, const GroupElement& end, const Parameter& alpha) {
    // Compute relative transformation and apply exponential scaling
    GroupElement diff = end.inverse() * start;
    GroupElement result = start * GroupElement::exp(diff.log() * alpha);
    return result;
}

