// Abstract interface for logging destinations
class LogDestination {
public:
    virtual void emit(const std::string& text) = 0;
    virtual ~LogDestination() {}
};

// Output to standard console
class StdoutLogDestination : public LogDestination {
public:
    void emit(const std::string& text) override {
        std::cout << text << std::endl;
    }
};

// Output to a file
class FileLogDestination : public LogDestination {
private:
    std::ofstream logFile;
public:
    FileLogDestination(const std::string& path) {
        logFile.open(path, std::ios::out | std::ios::app);
    }
    void emit(const std::string& text) override {
        logFile << text << std::endl;
    }
    ~FileLogDestination() {
        logFile.close();
    }
};

// Core logging mechanism
class ApplicationLogger {
private:
    Severity threshold;
    LogDestination* destination;
public:
    ApplicationLogger(Severity minLevel, LogDestination* out) 
        : threshold(minLevel), destination(out) {}

    void record(Severity level, const std::string& content) {
        if (level >= threshold) {
            std::time_t currentTime = std::time(nullptr);
            std::string timeString = std::ctime(&currentTime);
            std::string formattedTime = "[" + timeString.substr(0, timeString.length() - 1) + "] ";
            std::string fullMessage = formattedTime + content;
            destination->emit(fullMessage);
        }
    }
};

