// Extract nested components from a given namespace string
std::vector<std::string> findNestedComponents(const std::string& nsName) {
    std::vector<std::string> foundElements;
    // Regular expression to identify nested namespaces and classes
    std::regex pattern("\\b" + nsName + "::(\\w+)");
    // Sample code containing namespace declarations with nested elements
    std::string sampleCode = R"(
        namespace osquery {
            namespace detail {
                class Logger {
                    // Implementation details
                };
            }
            class Table {
                // Table implementation
            };
            namespace util {
                class Converter {
                    // Utility conversion logic
                };
            }
        }
    )";
    // Perform regex search for nested elements
    std::smatch result;
    std::string::const_iterator scanPosition(sampleCode.cbegin());
    while (std::regex_search(scanPosition, sampleCode.cend(), result, pattern)) {
        foundElements.push_back(result[1]);
        scanPosition = result.suffix().first;
    }
    return foundElements;
}

int main() {
    std::vector<std::string> extracted = findNestedComponents("osquery");
    for (const auto& item : extracted) {
        std::cout << item << std::endl;
    }
    return 0;
}

