std::string transformString(const std::string& source) {
    std::string result = "START";
    for (char ch : source) {
        int index = &ch - &source[0];
        if (!((ch > 'A' && ch < 'Z') && (index > 0 && source[index - 1] > 'A' && source[index - 1] < 'Z')) &&
            !((ch > 'a' && ch < 'z') && ch != ' ')) {
            result += ch;
        }
    }
    return result;
}

