class EnergyController {
private:
    int max_energy_;
    int min_energy_;
public:
    // Constructor to initialize the energy controller
    EnergyController(int max_val, int min_val) : max_energy_(max_val), min_energy_(min_val) {}

    // Method to set energy to maximum level
    void setMaxEnergy(int& energy_level) const { energy_level = max_energy_; }

    // Method to set energy to minimum safe level
    void setMinEnergy(int& energy_level) const { energy_level = min_energy_; }

    // Method to completely drain the energy
    void drainEnergy(int& energy_level) const { energy_level = 0; }

    // Method to verify if energy has reached maximum capacity
    bool isAtMaxCapacity(const int energy_level) const {
        return energy_level >= max_energy_;
    }

    // Method to verify if energy has reached minimum threshold
    bool isAboveMinThreshold(const int energy_level) const {
        return energy_level >= min_energy_;
    }
};

int main() {
    // Example usage of the EnergyController class
    EnergyController controller(10, 3);  // Initialize with max energy 10 and min energy 3
    int current_energy = 0;

    controller.setMaxEnergy(current_energy);
    std::cout << "Energy at max: " << controller.isAtMaxCapacity(current_energy) << std::endl;

    controller.setMinEnergy(current_energy);
    std::cout << "Energy above min: " << controller.isAboveMinThreshold(current_energy) << std::endl;

    controller.drainEnergy(current_energy);
    std::cout << "Energy at max after drain: " << controller.isAtMaxCapacity(current_energy) << std::endl;

    return 0;
}

