#include <GL/gl.h>

// Render top or bottom face based on Y-dimension sign
void renderFace() {
    if (dimensions.getY() > 0) {
        // Top face rendering
        glNormal3f(0.0F, dimensions.getY() + 2, 0.0F);

        glVertex3f(coords.getX(), coords.getY() + dimensions.getY(), coords.getZ() + dimensions.getZ());
        glTexCoord2f(0, scaleY);

        glVertex3f(coords.getX(), coords.getY() + dimensions.getY(), coords.getZ());
        glTexCoord2f(0, 0);

        glVertex3f(coords.getX() + dimensions.getX(), coords.getY() + dimensions.getY(), coords.getZ());
        glTexCoord2f(scaleX, 0);

        glVertex3f(coords.getX() + dimensions.getX(), coords.getY() + dimensions.getY(), coords.getZ() + dimensions.getZ());
        glTexCoord2f(scaleX, scaleY);

        glEnd();
    } else if (dimensions.getY() < 0) {
        // Bottom face rendering
        glNormal3f(0.0F, dimensions.getY() + 2, 0.0F);

        glVertex3f(coords.getX(), coords.getY(), coords.getZ());
        glTexCoord2f(0, 0);

        glVertex3f(coords.getX(), coords.getY(), coords.getZ() + dimensions.getZ());
        glTexCoord2f(0, scaleZ);

        glVertex3f(coords.getX() + dimensions.getX(), coords.getY(), coords.getZ() + dimensions.getZ());
        glTexCoord2f(scaleX, scaleZ);

        glEnd();
    }
}

