#include <cmath>

// Minimum divisor threshold to prevent division by zero
const float MIN_DIVISOR_THRESHOLD = 0.0001f;

// Calculate sphere thickness at a given position
float calculateSphereThickness(const float inverseMatrix[16], const float pointPosition[3], float squaredThickness) {
    // Extract translation components from the inverse matrix
    const float offsetX = inverseMatrix[12] + pointPosition[0];
    const float offsetY = inverseMatrix[13] + pointPosition[1];
    const float offsetZ = inverseMatrix[14] + pointPosition[2];

    // Compute normalized thickness using distance from center
    return squaredThickness / (offsetX * offsetX + offsetY * offsetY + offsetZ * offsetZ + MIN_DIVISOR_THRESHOLD);
}

