// Structure representing a rotation in 3D space
struct RotationData
{
    float Pitch;
    float Yaw;
    float Roll;
};

// Convert RotationData to a byte array
void RotationToBytes(const RotationData& data, unsigned char* buffer)
{
    memcpy(buffer, &data, sizeof(RotationData));
}

// Convert byte array back to RotationData
RotationData BytesToRotation(const unsigned char* buffer)
{
    RotationData result;
    memcpy(&result, buffer, sizeof(RotationData));
    return result;
}

int main()
{
    RotationData initialRotation = {30.0f, 60.0f, 90.0f};
    unsigned char byteBuffer[sizeof(RotationData)];

    // Serialize the rotation to bytes
    RotationToBytes(initialRotation, byteBuffer);

    std::cout << "Serialized byte values: ";
    for (int index = 0; index < sizeof(RotationData); ++index)
    {
        std::cout << std::hex << static_cast<int>(byteBuffer[index]) << " ";
    }
    std::cout << std::endl;

    // Deserialize bytes back to rotation
    RotationData restoredRotation = BytesToRotation(byteBuffer);

    std::cout << "Restored Rotation: Pitch=" << restoredRotation.Pitch
              << ", Yaw=" << restoredRotation.Yaw
              << ", Roll=" << restoredRotation.Roll << std::endl;

    return 0;
}

