enum class PinMode { INPUT, OUTPUT, PWM_OUTPUT, SERVO_OUTPUT };
enum class LogicLevel { active, inactive };

class HardwarePin {
private:
    std::map<int, int> pinValues;
    std::function<void(int, int)> onPinChange;
public:
    void setPin(int pinNumber, int value, PinMode mode) {
        auto iter = this->pinValues.find(pinNumber);
        if (iter == this->pinValues.end()) return;

        switch (mode) {
            case PinMode::INPUT:
            case PinMode::OUTPUT:
                iter->second = (value != 0) ? static_cast<int>(LogicLevel::active) : static_cast<int>(LogicLevel::inactive);
                break;
            case PinMode::PWM_OUTPUT:
            case PinMode::SERVO_OUTPUT:
                iter->second = value;
                break;
            default:
                return;
        }

        if (this->onPinChange != nullptr) {
            this->onPinChange(pinNumber, iter->second);
        }
    }

    void setCallback(std::function<void(int, int)> callback) {
        this->onPinChange = callback;
    }
};

