// Validates whether a given string conforms to the expected project path format
bool checkProjectPathFormat(const std::string& path) {
    // Ensure the path string is not empty
    if (path.empty()) {
        return false;
    }

    // Verify that no whitespace characters are present in the path
    if (std::any_of(path.begin(), path.end(), ::isspace)) {
        return false;
    }

    // Define regex pattern for valid Windows-style paths (e.g., C:\folder\subfolder)
    std::regex pathPattern(R"([A-Za-z]:[\\\/][\w\s.-]+[\\\/][\w\s.-]+)");

    // Confirm the path matches the required structure
    return std::regex_match(path, pathPattern);
}

