    void save(Archive &ar, const unsigned int version) const {
        ar & posX;
        ar & posY;
    }

    template <class Archive>
    void load(Archive &ar, const unsigned int version) {
        ar & posX;
        ar & posY;
    }

    BOOST_SERIALIZATION_SPLIT_MEMBER()

public:
    Coordinate() : posX(0), posY(0) {}
    Coordinate(int x, int y) : posX(x), posY(y) {}

    void store(std::ostream &stream) const {
        boost::archive::text_oarchive oa(stream);
        oa << *this;
    }

    void restore(std::istream &stream) {
        boost::archive::text_iarchive ia(stream);
        ia >> *this;
    }

    int getHorizontal() const {
        return posX;
    }

    int getVertical() const {
        return posY;
    }
};

int main() {
    // Initialize a Coordinate object
    Coordinate pt1(5, 10);

    // Serialize the Coordinate object
    std::stringstream buffer;
    pt1.store(buffer);

    // Deserialize into a new object
    Coordinate pt2;
    pt2.restore(buffer);

    // Display the restored coordinates
    std::cout << "Restored Coordinate - Horizontal: " << pt2.getHorizontal() 
              << ", Vertical: " << pt2.getVertical() << std::endl;

