    int imgWidth;
    int imgHeight;
    int colorMode;  // e.g., RGB, RGBA
    // Other relevant fields and methods
};

// Function to convert image wrapper to OpenGL texture
GLuint ConvertToGLTexture(const TextureData& srcImage) {
    GLuint texID;
    glGenTextures(1, &texID);
    glBindTexture(GL_TEXTURE_2D, texID);

    glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, srcImage.imgWidth, srcImage.imgHeight, 0, GL_RGBA, GL_UNSIGNED_BYTE, &srcImage.pixels[0]);

    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);

    glBindTexture(GL_TEXTURE_2D, 0);  // Unbind the texture

    return texID;
}

