    template<typename Type>
    void transpose_inplace(Array<Type> &input, const bool need_conjugate)
    {
        dim4 inDims = input.dims();
        if(need_conjugate) {
            if(inDims[0] % kernel::TILE_DIM == 0 && inDims[1] % kernel::TILE_DIM == 0)
                kernel::transpose_inplace<Type, true, true>(input);
            else
                kernel::transpose_inplace<Type, true, false>(input);
        } else {
            if(inDims[0] % kernel::TILE_DIM == 0 && inDims[1] % kernel::TILE_DIM == 0)
                kernel::transpose_inplace<Type, false, true>(input);
            else
                kernel::transpose_inplace<Type, false, false>(input);
        }
    }
}

