// Process a list of text commands to build two strings: baseText and searchWord
std::pair<std::string, std::string> processText(const std::vector<std::pair<int, std::string>>& instructions) {
  std::string baseText, searchWord;
  for (const auto& instruction : instructions) {
    switch (instruction.first) {
      case 1:
        if (!baseText.empty()) baseText += " ";
        baseText += instruction.second;
        break;
      case 2:
        if (!searchWord.empty()) searchWord += " ";
        searchWord += instruction.second;
        break;
      case 3:
        baseText.clear();
        break;
      case 4:
        searchWord.clear();
        break;
      // additional cases can be handled here
    }
  }
  return std::make_pair(baseText, searchWord);
}

