template <typename K, typename V>
class ConcurrentMap {
public:
    void add(const K& k, const V& v) {
        std::lock_guard<std::mutex> guard(mtx_);
        data_[k] = v;
    }

    void remove(const K& k) {
        std::lock_guard<std::mutex> guard(mtx_);
        data_.erase(k);
    }

    V fetch(const K& k) {
        std::lock_guard<std::mutex> guard(mtx_);
        auto iter = data_.find(k);
        if (iter != data_.end()) {
            return iter->second;
        }
        throw std::invalid_argument("Specified key does not exist");
    }

    bool has(const K& k) {
        std::lock_guard<std::mutex> guard(mtx_);
        return data_.find(k) != data_.end();
    }

private:
    std::map<K, V> data_;
    mutable std::mutex mtx_;
};

