// Helper class to track function call counts
class FunctionTracker {
public:
  static int updateDMXCount;
  static int fetchUniverseDataCount;

  static void reset() {
    updateDMXCount = 0;
    fetchUniverseDataCount = 0;
  }

  static void recordUpdateDMX() {
    updateDMXCount++;
  }

  static void recordFetchUniverseData() {
    fetchUniverseDataCount++;
  }
};

int FunctionTracker::updateDMXCount = 0;
int FunctionTracker::fetchUniverseDataCount = 0;

// Wrapper functions that delegate to the tracker
void updateDMXMerger() {
  FunctionTracker::recordUpdateDMX();
}

void fetchUniverseData() {
  FunctionTracker::recordFetchUniverseData();
}

// Target function to be tested
void handleUniverseProcessing() {
  updateDMXMerger();
  fetchUniverseData();
}

// Test case verifying correct function invocation
TEST(HandleUniverseProcessingTest, InvokesBothFunctionsExactlyOnce) {
  FunctionTracker::reset();  // Clear counters before test execution
  handleUniverseProcessing();  // Execute the function under test

  // Confirm each tracked function was called precisely one time
  EXPECT_EQ(FunctionTracker::updateDMXCount, 1);
  EXPECT_EQ(FunctionTracker::fetchUniverseDataCount, 1);
