namespace {
bool checkCertificateValidity(const net::x509_certificate& cert, const net::x509_certificate& issuerCert) {
    // Verify that the certificate hasn't expired yet
    if (net::x509_util::current_time() >= cert.not_after()) {
        return false; // Certificate has expired
    }
    // Validate the certificate signature using the trusted CA certificate
    net::ssl_info connectionInfo;
    connectionInfo.set_cert(&cert);
    connectionInfo.set_issuer(&issuerCert);
    return net::x509_util::VerifySignedBy(&connectionInfo);
}
