    int windowId;
};

class Manager {
public:
    void registerWindow(Window* window) {
        windows[window->getWindowId()] = window;
    }

    void unregisterWindow(int id) {
        auto it = windows.find(id);
        if (it != windows.end()) {
            delete it->second;
            windows.erase(it);
        }
    }

    void activateWindow(int id) {
        auto it = windows.find(id);
        if (it != windows.end()) {
            it->second->render();
        } else {
            std::cout << "Window does not exist" << std::endl;
        }
    }

    ~Manager() {
        for (auto& entry : windows) {
            delete entry.second;
        }
    }

private:
    std::unordered_map<int, Window*> windows;
};

class DetailWindow : public Window {
public:
    DetailWindow(int id, const std::string& text) : Window(id), text(text) {}
    void render() override {
        std::cout << "Window " << getWindowId() << ": " << text << std::endl;
    }
private:
    std::string text;
};

