    {
        iter->positionX += iter->velocityX * deltaTime;  // Update position based on velocity
        iter->positionY += iter->velocityY * deltaTime;
        iter->remainingLife -= deltaTime;  // Reduce remaining lifetime
        if (iter->remainingLife <= 0.0f)
        {
            iter = particles.erase(iter);  // Remove particle if lifetime has expired
        }
        else
        {
            ++iter;
        }
    }
}

