// Simulate water propagation using BFS from a source point
void waterfill(const Grid& grid, int src_x, int src_y, Grid& water_grid) {
    // Initialize a queue for breadth-first search traversal
    std::queue<std::pair<int, int>> bfs_queue;
    bfs_queue.push({src_x, src_y});

    // Mark the starting tile as containing water
    water_grid[src_x][src_y] = Filled;

    // Define movement directions: up, down, left, right
    const std::vector<std::pair<int, int>> offsets = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    // Process tiles in the queue until it's empty
    while (!bfs_queue.empty()) {
        auto [curr_x, curr_y] = bfs_queue.front();
        bfs_queue.pop();

        // Examine all adjacent tiles
        for (const auto& offset : offsets) {
            int adj_x = curr_x + offset.first;
            int adj_y = curr_y + offset.second;

            // Verify adjacency is within bounds and not already filled
            if (adj_x >= 0 && adj_x < static_cast<int>(grid.size()) &&
                adj_y >= 0 && adj_y < static_cast<int>(grid[0].size()) &&
                water_grid[adj_x][adj_y] != Filled) {

                // Apply custom condition to determine if water should spread
                if (TileRoutines::waterfill_touch_right(grid[curr_x][curr_y], grid[adj_x][adj_y], tile)) {
                    // Update status and enqueue for further processing
                    water_grid[adj_x][adj_y] = Filled;
                    bfs_queue.push({adj_x, adj_y});
                }
            }
        }
    }
}

