#include "Components/Lights/LightInterface.hpp"
#include <vector>
#include <algorithm>

namespace Components::Lights {
    class PointLight : public LightInterface {
    public:
        PointLight(const glm::vec3& pos, const glm::vec3& col)
            : position_(pos), color_(col) {}

        virtual glm::vec3 CalculateIllumination(const glm::vec3& p) const override {
            glm::vec3 dir = position_ - p;
            float dist = glm::length(dir);
            dir = glm::normalize(dir);
            float atten = 1.0f / (dist * dist);
            return color_ * atten * std::max(glm::dot(glm::vec3(0, 0, 1), dir), 0.0f);
        }

    private:
        glm::vec3 position_;
        glm::vec3 color_;
    };

    class DirectionalLight : public LightInterface {
    public:
        DirectionalLight(const glm::vec3& dir, const glm::vec3& col)
            : direction_(dir), color_(col) {}

        virtual glm::vec3 CalculateIllumination(const glm::vec3& p) const override {
            return color_ * std::max(glm::dot(glm::vec3(0, 0, 1), -direction_), 0.0f);
        }

    private:
        glm::vec3 direction_;
        glm::vec3 color_;
    };

    glm::vec3 CalculateIllumination(const glm::vec3& point, const std::vector<std::shared_ptr<LightInterface>>& lightList) {
        glm::vec3 result(0.0f);
        for (const auto& light : lightList) {
            result += light->CalculateIllumination(point);
        }
        return result;
    }
}

