// Wrapper class for safe floating-point operations
template <typename FloatingPointType>
class SafeFloat {
public:
    using SafeFloatType = boost::safe_float::safe_float<FloatingPointType>;

    SafeFloat(FloatingPointType val) : value_(val) {}

    SafeFloatType add(const SafeFloatType& other) {
        SafeFloatType result = other + value_;
        return result;
    }

    void displayErrorFlags(const SafeFloatType& result) {
        std::cout << "Overflow: " << result.error().overflow() << std::endl;
        std::cout << "Underflow: " << result.error().underflow() << std::endl;
        std::cout << "Inexact: " << result.error().inexact() << std::endl;
        std::cout << "Invalid Result: " << result.error().invalid_result() << std::endl;
    }

private:
    SafeFloatType value_;
};

int main() {
    // Initialize safe float objects with different values
    SafeFloat<float> sfA(3.5f);
    SafeFloat<float> sfB(4.25f);

    // First addition with overflow and inexactness checks
    SafeFloat<float>::SafeFloatType resA = sfA.add(sfB, 
        boost::safe_float::policy::check_addition_overflow{}, 
        boost::safe_float::policy::check_addition_inexact{});
    sfA.displayErrorFlags(resA);

    // Second addition with underflow and invalid result checks
    SafeFloat<float>::SafeFloatType resB = sfA.add(sfB, 
        boost::safe_float::policy::check_addition_underflow{}, 
        boost::safe_float::policy::check_addition_invalid_result{});
    sfA.displayErrorFlags(resB);

    return 0;
}

