#include <iostream>
#include <cmath>

class ComplexNumber {
private:
    double realPart;
    double imaginaryPart;

public:
    // Default constructor
    ComplexNumber() : realPart(0), imaginaryPart(0) {}

    // Parameterized constructor
    ComplexNumber(double re, double im) : realPart(re), imaginaryPart(im) {}

    // Addition operator overloading
    ComplexNumber operator+(const ComplexNumber& other) const {
        return ComplexNumber(realPart + other.realPart, imaginaryPart + other.imaginaryPart);
    }

    // Subtraction operator overloading
    ComplexNumber operator-(const ComplexNumber& other) const {
        return ComplexNumber(realPart - other.realPart, imaginaryPart - other.imaginaryPart);
    }

    // Multiplication operator overloading
    ComplexNumber operator*(const ComplexNumber& other) const {
        return ComplexNumber(
            realPart * other.realPart - imaginaryPart * other.imaginaryPart,
            realPart * other.imaginaryPart + imaginaryPart * other.realPart
        );
    }

    // Division operator overloading
    ComplexNumber operator/(const ComplexNumber& other) const {
        double denom = other.realPart * other.realPart + other.imaginaryPart * other.imaginaryPart;
        return ComplexNumber(
            (realPart * other.realPart + imaginaryPart * other.imaginaryPart) / denom,
            (imaginaryPart * other.realPart - realPart * other.imaginaryPart) / denom
        );
    }

    // Output stream insertion operator overloading
    friend std::ostream& operator<<(std::ostream& os, const ComplexNumber& num) {
        os << num.realPart << (num.imaginaryPart >= 0 ? " + " : " - ") 
           << std::abs(num.imaginaryPart) << "i";
        return os;
    }

    // Method to calculate the magnitude of the complex number
    double getMagnitude() const {
        return std::sqrt(realPart * realPart + imaginaryPart * imaginaryPart);
    }
};

int main() {
    ComplexNumber num1;
    ComplexNumber num2(8, 0);
    ComplexNumber num3(0, -4);
    ComplexNumber num4(29.99, 88.44);

    std::cout << "Complex number num1: " << num1 << std::endl;
    std::cout << "Complex number num2: " << num2 << std::endl;
    std::cout << "Complex number num3: " << num3 << std::endl;
    std::cout << "Complex number num4: " << num4 << std::endl;

    ComplexNumber sumResult = num2 + num3;
    ComplexNumber diffResult = num2 - num3;
    ComplexNumber prodResult = num2 * num3;
    ComplexNumber quotResult = num2 / num3;

    std::cout << "Sum of num2 and num3: " << sumResult << std::endl;
    std::cout << "Difference of num2 and num3: " << diffResult << std::endl;
    std::cout << "Product of num2 and num3: " << prodResult << std::endl;
    std::cout << "Quotient of num2 and num3: " << quotResult << std::endl;
    std::cout << "Magnitude of num2: " << num2.getMagnitude() << std::endl;

    return 0;
}

