namespace Debug
{
    template<size_t BUFFER_SIZE>
    class StackAllocator
    {
    public:
        StackAllocator() : stackTop(0) {
            static_assert(BUFFER_SIZE > 0, "Buffer size must be positive");
            static_assert((BUFFER_SIZE & (BUFFER_SIZE - 1)) == 0, "Buffer size must be power of two for alignment");
            static_assert(BUFFER_SIZE <= UINT32_MAX, "Buffer size exceeds uint32_t limit");
            static_assert(alignof(std::max_align_t) <= 4, "Alignment constraint not met for this implementation");
        }

        void* allocate(size_t byteCount) {
            assert(stackTop + byteCount <= BUFFER_SIZE && "Memory exhausted");
            void* result = &memoryBuffer[stackTop];
            stackTop += byteCount;
            return result;
        }

        void deallocate(void* ptr, size_t byteCount) {
            assert(byteCount <= stackTop && "Invalid deallocation size");
            assert(ptr == &memoryBuffer[stackTop - byteCount] && "Invalid deallocation address");
            stackTop -= byteCount;
        }

    private:
        uint8_t memoryBuffer[BUFFER_SIZE];
        size_t stackTop;
    };
}

int main() {
    Debug::StackAllocator<2048> allocator;

    // Allocate memory for an integer
    int* valuePtr = static_cast<int*>(allocator.allocate(sizeof(int)));
    *valuePtr = 42;

    // Deallocate the memory block
    allocator.deallocate(valuePtr, sizeof(int));

    return 0;
}

