class Point2D {
public:
    // Constructor to initialize the point with given x and y coordinates
    Point2D(double xVal, double yVal) : xCoord(xVal), yCoord(yVal) {}
    // Set the x coordinate of the point
    void setXValue(double newX) { xCoord = newX; }
    // Set the y coordinate of the point
    void setYValue(double newY) { yCoord = newY; }
    // Get the x coordinate of the point
    double getXValue() const { return xCoord; }
    // Get the y coordinate of the point
    double getYValue() const { return yCoord; }
    // Calculate the distance between this point and another point
    double distanceFrom(const Point2D& otherPoint) const {
        double deltaX = xCoord - otherPoint.xCoord;
        double deltaY = yCoord - otherPoint.yCoord;
