#include <QObject>
#include <QThread>
#include <QVector>
#include <complex>
#include <fftw3.h>

class FFTProcessor : public QObject {
    Q_OBJECT
public:
    FFTProcessor(int fftSize) : m_fftSize(fftSize) {
        m_inputData.resize(fftSize);
        m_outputData.resize(fftSize);
        // Setup FFTW plan with specified parameters
        m_plan = fftw_plan_dft_1d(fftSize, reinterpret_cast<fftw_complex*>(m_inputData.data()),
                                  reinterpret_cast<fftw_complex*>(m_outputData.data()), FFTW_FORWARD, FFTW_ESTIMATE);
    }
    ~FFTProcessor() {
        fftw_destroy_plan(m_plan);
    }

public slots:
    void handleNewInput(const QVector<double>& inputData) {
        // Transfer incoming data to internal buffer for processing
        std::copy(inputData.begin(), inputData.end(), m_inputData.begin());
        // Launch computation in a dedicated thread
        m_workerThread = new QThread();
        moveToThread(m_workerThread);
        connect(m_workerThread, &QThread::started, this, &FFTProcessor::runFFT);
        connect(this, &FFTProcessor::processingDone, m_workerThread, &QThread::quit);
        connect(this, &FFTProcessor::processingDone, this, &FFTProcessor::deleteLater);
        connect(m_workerThread, &QThread::finished, m_workerThread, &QThread::deleteLater);
        m_workerThread->start();
    }

signals:
    void processingDone(const QVector<std::complex<double>>& output);

private:
    int m_fftSize;
    QVector<double> m_inputData;
    QVector<std::complex<double>> m_outputData;
    fftw_plan m_plan;
    QThread* m_workerThread;

    void runFFT() {
        // Execute the FFT algorithm
        fftw_execute(m_plan);
        // Prepare result vector from internal buffer
        QVector<std::complex<double>> result(m_fftSize);
        for (int idx = 0; idx < m_fftSize; ++idx) {
            result[idx] = std::complex<double>(m_outputData[idx].real(), m_outputData[idx].imag());
        }
        // Emit completed result
        emit processingDone(result);
    }
};

