class BinarySearchTree {
private:
    struct TreeNode {
        int data;
        TreeNode* leftChild;
        TreeNode* rightChild;
        TreeNode(int val) : data(val), leftChild(nullptr), rightChild(nullptr) {}
    };
    TreeNode* head;

    // Recursive helper to build the tree from array representation
    TreeNode* buildTreeRecursively(const std::vector<int>& arr, int pos) {
        if (pos < arr.size()) {
            TreeNode* current = new TreeNode(arr[pos]);
            current->leftChild = buildTreeRecursively(arr, 2 * pos + 1);
            current->rightChild = buildTreeRecursively(arr, 2 * pos + 2);
            return current;
        }
        return nullptr;
    }

public:
    // Public interface to initialize the tree structure
    void initializeTree(const std::vector<int>& elements) {
        head = buildTreeRecursively(elements, 0);
    }

    // Conversion operator to extract root node's data as unsigned integer
    operator unsigned int() const {
        return static_cast<unsigned int>(head->data);
    }
};

int main() {
    BinarySearchTree treeInstance;
    treeInstance.initializeTree({10, 20, 30, 40, 50, 60, 70});
    unsigned int rootNodeData = treeInstance; // Automatic type conversion
