// Generate a vector of integer pairs based on parameters X and Y
std::vector<std::pair<int, int>> generatePairs(int X, int Y) {
    std::vector<std::pair<int, int>> result;
    int value = 1;

    // Process while X is non-negative
    while (X >= 0) {
        --X;
        result.push_back({ ++value, ++value });
    }

    // Add initial pair with first element as 1
    result.push_back({ 1, ++value });

    // Check if result size exceeds the required count
    if (result.size() > Y) return {};

    // Pad the result to reach exactly Y elements
    while (result.size() < Y) {
        result.push_back({ ++value, ++value });
    }

    return result;
}

