    class value_generator {
    private:
        std::mt19937 engine;  // Mersenne Twister random number generator
    public:
        value_generator(int seed_value) : engine(seed_value) {}
        std::vector<ResultType> produce(int num_elements) {
            std::vector<ResultType> output;
            std::uniform_real_distribution<double> distribution(0.0, 1.0);  // Standard distribution for floating-point types
