// Check if two points lie on the same horizontal or vertical line
bool isSameLine(int x1, int y1, int x2, int y2) {
    return (x1 == x2) || (y1 == y2);
}

// Check if two points lie on the same diagonal
bool isSameDiagonal(int x1, int y1, int x2, int y2) {
    return (std::abs(x1 - x2) == std::abs(y1 - y2));
}

int main() {
    int startX, startY, endX, endY;
    std::cin >> startX >> startY >> endX >> endY;

    if (startX == endX && startY == endY) {
        std::cout << 0; // Already at the destination
    } else if (isSameLine(startX, startY, endX, endY) || isSameDiagonal(startX, startY, endX, endY)) {
        std::cout << 1; // Can reach in one move
    } else {
        std::cout << 2; // Requires two moves to reach
