// Class representing an output port of a node
class OutputPort {
public:
    // Constructor initializes the output with its associated node, index, and tensor
    OutputPort(ComputationNode* nodeRef, int portIndex, TensorData* tensorRef) 
        : m_nodeReference(nodeRef), m_portIndex(portIndex), m_tensorReference(tensorRef) {}

    // Add a new input connection to this output
    void attach_input(ConnectionInput* inputRef) {
        // Maintain insertion order for deterministic behavior
        if (std::find(m_connectedInputs.begin(), m_connectedInputs.end(), inputRef) == m_connectedInputs.end()) {
            m_connectedInputs.push_back(inputRef);
        }
    }

    // Remove an existing input connection from this output
    void detach_input(ConnectionInput* inputRef) {
        auto iterator = std::find(m_connectedInputs.begin(), m_connectedInputs.end(), inputRef);
        if (iterator != m_connectedInputs.end()) {
            m_connectedInputs.erase(iterator);
        }
    }

    // Get the current number of connected inputs
    int get_input_count() const {
        return static_cast<int>(m_connectedInputs.size());
    }

private:
    ComputationNode* m_nodeReference;
    int m_portIndex;
    TensorData* m_tensorReference;
    std::vector<ConnectionInput*> m_connectedInputs;
};

