class MyString {
private:
    char* buffer;
public:
    // Default constructor
    MyString() : buffer(new char[1]) {
        buffer[0] = '\0';
    }
    // Parameterized constructor
    MyString(const char* input) : buffer(new char[strlen(input) + 1]) {
        strcpy(buffer, input);
    }
    // Destructor
    ~MyString() {
        delete[] buffer;
    }
    // Method to get the length of the string
    size_t size() const {
        return strlen(buffer);
    }
    // Method to append another MyString
    void concat(const MyString& other) {
        char* temp = new char[size() + other.size() + 1];
        strcpy(temp, buffer);
        strcat(temp, other.buffer);
        delete[] buffer;
        buffer = temp;
    }
    // Method to get the C-style string representation
    const char* data() const {
        return buffer;
    }
};

int main() {
