namespace musher {
    namespace core {
        /**
         * @brief Applies rectangular windowing to the input signal.
         * 
         * @param signal The input signal data.
         * @param winLen The length of the rectangular window.
         */
        void RectangularWindowing(std::vector<double>& signal, size_t winLen) {
            // Ensure window length does not exceed the signal size
            winLen = std::min(winLen, signal.size());
            // Apply rectangular windowing (value 1 within the window)
            for (size_t idx = 0; idx < winLen; ++idx) {
                signal[idx] = signal[idx] * 1.0;
            }
        }
