    NonCopyable& operator=(const NonCopyable&) = delete;
};

class LockGuard {
public:
    void Acquire() {
        mtx.lock();
    }
    void Release() {
        mtx.unlock();
    }
private:
    std::mutex mtx;
};

class AutoLock : private NonCopyable {
public:
    explicit AutoLock(LockGuard& guard)
        : lg(guard) {
        lg.Acquire();
    }
    ~AutoLock() {
        lg.Release();
    }
private:
    LockGuard& lg;
};

template <typename Type>
class ConcurrentStack {
public:
    void Emplace(const Type& item) {
        AutoLock lock(lg);
        stck.push(item);
    }
    bool Extract(Type& result) {
        AutoLock lock(lg);
        if (stck.empty()) {
            return false;
        }
        result = stck.top();
        stck.pop();
        return true;
    }
    bool Empty() const {
        AutoLock lock(lg);
        return stck.empty();
    }
private:
    std::stack<Type> stck;
    LockGuard lg;
};

#include <functional>

// Approximate definite integral using the trapezoidal rule
double numericalIntegration(std::function<double(double)> func, double leftBound, double rightBound, int segments) {
    double stepSize = (rightBound - leftBound) / segments;  // Length of each subinterval
    double result = 0.5 * (func(leftBound) + func(rightBound));  // Start with endpoints contribution
    for (int index = 1; index < segments; ++index) {
        double point = leftBound + index * stepSize;  // Current x-coordinate
        result += func(point);  // Accumulate interior function values
    }
    return stepSize * result;  // Multiply by step size for final approximation
}

