#include <iostream>

// Class for detecting supported CPU instructions and features
class ProcessorFeatureChecker {
public:
    bool HAS_SSE2;
    bool HAS_AVX;
    bool HAS_AVX2;

    // Execute CPUID instruction to get processor information
    void executeCpuid(int registers[4], int functionId) {
        __asm__ __volatile__(
            "cpuid"
            : "=a" (registers[0]), "=b" (registers[1]), "=c" (registers[2]), "=d" (registers[3])
            : "a" (functionId)
        );
    }

    // Analyze CPU capabilities and update feature flags
    void analyzeFeatures() {
        int cpuRegs[4];
        executeCpuid(cpuRegs, 0);
        int maxLeaf = cpuRegs[0];

        if (maxLeaf >= 1) {
            executeCpuid(cpuRegs, 1);
            // Determine SSE2 availability: bit 26 in EDX register
            HAS_SSE2 = (cpuRegs[3] & (1 << 26)) != 0;
            // Determine AVX availability: bit 28 in ECX register
            HAS_AVX = (cpuRegs[2] & (1 << 28)) != 0;
        }

        if (maxLeaf >= 7) {
            executeCpuid(cpuRegs, 7);
            // Determine AVX2 availability: bit 5 in EBX register
            HAS_AVX2 = (cpuRegs[1] & (1 << 5)) != 0;
        }
    }
};

int main() {
    ProcessorFeatureChecker processorInfo;
    processorInfo.analyzeFeatures();

    std::cout << "SSE2 available: " << (processorInfo.HAS_SSE2 ? "Yes" : "No") << std::endl;
    std::cout << "AVX available: " << (processorInfo.HAS_AVX ? "Yes" : "No") << std::endl;
    std::cout << "AVX2 available: " << (processorInfo.HAS_AVX2 ? "Yes" : "No") << std::endl;

    return 0;
}

