class Coordinate {
private:
    double a, b;
public:
    Coordinate(double xVal, double yVal) : a(xVal), b(yVal) {}

    double getDistanceTo(const Coordinate& otherPoint) {
        return std::sqrt(std::pow(otherPoint.a - a, 2) + std::pow(otherPoint.b - b, 2));
    }

    Coordinate getMidpointWith(const Coordinate& otherPoint) {
        double centerX = (a + otherPoint.a) / 2.0;
        double centerY = (b + otherPoint.b) / 2.0;
        return Coordinate(centerX, centerY);
    }

    bool checkCollinearity(const Coordinate& point2, const Coordinate& point3) {
        return ((point2.b - b) * (point3.a - point2.a) == (point3.b - point2.b) * (point2.a - a));
    }
};

