void SMExtractRGBI(IplImage* srcImage, CvMat* &redChannel, CvMat* &greenChannel, CvMat* &blueChannel, CvMat* &intensityChannel)
{
    // Convert input image to OpenCV Mat
    cv::Mat srcMat(srcImage);
    // Split the input image into its RGB components
    std::vector<cv::Mat> channels;
    cv::split(srcMat, channels);
    // Convert RGB channels to floating point format
    cv::Mat R_float, G_float, B_float;
    channels[2].convertTo(R_float, CV_32F);
    channels[1].convertTo(G_float, CV_32F);
    channels[0].convertTo(B_float, CV_32F);
    // Calculate intensity (I) as the average of RGB channels
    cv::Mat I_float = (R_float + G_float + B_float) / 3.0f;
    // Allocate memory for output matrices
    redChannel = cvCreateMat(srcImage->height, srcImage->width, CV_32FC1);
    greenChannel = cvCreateMat(srcImage->height, srcImage->width, CV_32FC1);
    blueChannel = cvCreateMat(srcImage->height, srcImage->width, CV_32FC1);
    intensityChannel = cvCreateMat(srcImage->height, srcImage->width, CV_32FC1);
    // Copy data from OpenCV Mat to CvMat
    std::memcpy(redChannel->data.fl, R_float.data, R_float.total() * sizeof(float));
    std::memcpy(greenChannel->data.fl, G_float.data, G_float.total() * sizeof(float));
    std::memcpy(blueChannel->data.fl, B_float.data, B_float.total() * sizeof(float));
    std::memcpy(intensityChannel->data.fl, I_float.data, I_float.total() * sizeof(float));
}

