// Insert a new material into the scene at a given position
bool insertMaterialToScene(aiScene* scene, int pos, Material newMat) {
    if (pos >= 0 && pos < scene->mNumMaterials) {
        // Move existing materials one position forward to create space
        for (int j = scene->mNumMaterials - 1; j >= pos; j--) {
            scene->mMaterials[j + 1] = scene->mMaterials[j];
        }
        // Place the new material at the designated position
        scene->mMaterials[pos] = newMat;
        scene->mNumMaterials++;  // Update the count of materials in the scene
        return true;  // Successfully inserted
    }
    return false;  // Position is invalid
}

