std::vector<std::tuple<std::unique_ptr<IOBuf>, bool, TestStreamingCallback>> encodeFlightData(
    const std::vector<Header>& requestHeaders,
    const std::vector<std::string>& payloadValues,
    int dynamicTableCapacity) {

  std::vector<std::tuple<std::unique_ptr<IOBuf>, bool, TestStreamingCallback>> results;

  for (size_t idx = 0; idx < payloadValues.size(); ++idx) {
    // Generate callback instance first
    TestStreamingCallback handler;

    // Perform encoding operation
    std::unique_ptr<IOBuf> buffer = encodeData(requestHeaders, payloadValues[idx], dynamicTableCapacity);

    // Determine success status based on buffer validity
    bool encodedSuccessfully = !!buffer;

    // Add completed record to result collection
    results.emplace_back(std::move(buffer), encodedSuccessfully, handler);
  }

  return results;
}

