#include <glslang/Public/ShaderLang.h>
#include <SPIRV/GlslangToSpv.h>
#include <SPIRV/SpvTools.h>
#include <SPIRV/disassemble.h>

// Convert GLSL shader source to SPIR-V bytecode
bool compileGLSLToSPIRV(const std::string& shaderSource, std::vector<unsigned int>& spirvOutput) {
    glslang::InitializeProcess();

    // Create a vertex shader object
    glslang::TShader vertexShader(EShLangVertex);
    const char* shaderCode[1];
    shaderCode[0] = shaderSource.c_str();
    vertexShader.setStrings(shaderCode, 1);

    if (!vertexShader.parse(&glslang::DefaultTBuiltInResource, 100, false, EShMsgDefault)) {
        KG_LOGE(LM_RENDER, "[Compile GLSL to SPIR-V] Shader Parsing Failed\n%s", vertexShader.getInfoLog());
        glslang::FinalizeProcess();
        return false;
    }

    std::unique_ptr<glslang::TProgram> shaderProgram(new glslang::TProgram());
    shaderProgram->addShader(&vertexShader);

    if (!shaderProgram->link(EShMsgDefault)) {
        KG_LOGE(LM_RENDER, "[Compile GLSL to SPIR-V] Program Linking Failed\n%s", shaderProgram->getInfoLog());
        glslang::FinalizeProcess();
        return false;
    }

    spv::SpvBuildLogger messageLogger;
    glslang::GlslangToSpv(*shaderProgram->getIntermediate(EShLangVertex), spirvOutput, &messageLogger);

    if (messageLogger.getAllMessages().length() > 0) {
        KG_LOGW(LM_RENDER, "[Compile GLSL to SPIR-V] SPIR-V Generation Messages\n%s", messageLogger.getAllMessages().c_str());
    }

    glslang::FinalizeProcess();
    return true;
}

