namespace Rider {
    namespace Faiz {
        // Logical OR implementation for type traits
        template <typename... Types>
        struct or_trait : std::false_type {};

        template <typename First>
        struct or_trait<First> : First {};

        template <typename First, typename... Rest>
        struct or_trait<First, Rest...> 
            : std::conditional<First::value, First, or_trait<Rest...>>::type {};

        // Compile-time assertion macro
        #define COMPILE_CHECK(condition) static_assert(condition, "Compile-time check failed")

        // Type aliases for boolean traits
        using yes_type = std::true_type;
        using no_type = std::false_type;

        // Verify disjunction behavior
        COMPILE_CHECK(or_trait<yes_type, no_type>::value);
        COMPILE_CHECK(or_trait<no_type, yes_type, no_type>::value);
        COMPILE_CHECK(!or_trait<no_type, no_type, no_type>::value);
    }
}

