struct callable_traits;

// Specialization for raw function pointers
template <typename R, typename... P>
struct callable_traits<R(*)(P...)> {
    using type = R(*)(P...);
};

// Specialization for std::function objects
template <typename R, typename... P>
struct callable_traits<std::function<R(P...)>> {
    using type = R(*)(P...);
};

// Specialization for generic callable types (e.g., lambdas)
template <typename F>
struct callable_traits {
    using type = typename callable_traits<decltype(&F::operator())>::type;
};

// Utility function to transform a callable into a function pointer
