// Function to parse and handle a data segment from the input stream
// Returns 0 for success, non-zero for failure
int ParseDataSegment(char PointerSize, const char* Start, const char* Limit) {
    // Validate input pointers
    if (Start == nullptr || Limit == nullptr || Start > Limit) {
        std::cerr << "Invalid buffer pointers" << std::endl;
        return 1;
    }

    // Check if there's enough data to read the segment length
    if (Start + 1 > Limit) {
        std::cerr << "Not enough data to determine segment size" << std::endl;
        return 1;
    }

    // Extract the size of the current segment
    int segmentLength = static_cast<unsigned char>(*Start);

    // Verify that the segment fits within the buffer bounds
    if (Start + segmentLength > Limit) {
        std::cerr << "Segment size exceeds available data or segment is incomplete" << std::endl;
        return 1;
    }

    // Simulate processing of the segment content (placeholder logic)
    std::cout << "Handling segment: ";
    for (int index = 0; index < segmentLength; ++index) {
        std::cout << *(Start + index + 1);  // Display segment payload
    }
    std::cout << std::endl;

    // Advance the start pointer to the next segment
    Start += segmentLength + 1;
    return 0;  // Indicate successful processing
}

