class WordCounter {
private:
    map<string, int> wordCounts;
public:
    WordCounter(const string& fileName) {
        ifstream inputFile(fileName);
        if (inputFile.is_open()) {
            string currentWord;
            while (inputFile >> currentWord) {
                // Strip punctuation from the current word
                currentWord.erase(remove_if(currentWord.begin(), currentWord.end(), ::ispunct), currentWord.end());
                // Convert current word to lowercase
                transform(currentWord.begin(), currentWord.end(), currentWord.begin(), ::tolower);
                wordCounts[currentWord]++;
            }
            inputFile.close();
        } else {
            cerr << "Error: Cannot open file" << endl;
        }
    }

    int getCount(const string& targetWord) {
        string normalizedWord = targetWord;
        transform(normalizedWord.begin(), normalizedWord.end(), normalizedWord.begin(), ::tolower);
        return wordCounts[normalizedWord];
    }
};

