// Apply image smoothing and preprocessing based on geometric parameters
void applyGeometricFilter(cv::Mat& inputImage, float radius, float thickness1, float thickness2, int kernelSize) {
    // Convert the input image to grayscale
    cv::Mat grayscale;
    cv::cvtColor(inputImage, grayscale, cv::COLOR_BGR2GRAY);

    // Apply Gaussian blur for smoothing
    cv::Mat smoothed;
    cv::GaussianBlur(grayscale, smoothed, cv::Size(kernelSize, kernelSize), 0);

    // Replace original image content with processed result
    inputImage = smoothed;
}

