#include <set>

class Solution {
public:
    std::set<int> seenRemainders;
    int smallestRepunitDivByK(int divisor) {
        if (divisor % 2 == 0 || divisor % 5 == 0) {
            return -1; // If divisor is divisible by 2 or 5, no repunit can be divisible by it
        }
        int currentRemainder = 0;
        for (int numDigits = 1; numDigits <= divisor; numDigits++) {
            currentRemainder = (currentRemainder * 10 + 1) % divisor;
            if (currentRemainder == 0) {
                return numDigits; // Found the smallest repunit divisible by divisor
            }
        }
        return -1; // No such repunit found within divisor digits
    }
};

