// Custom timer-based callback handler class
class DeferredProcedure {
public:
    using CallbackFunction = void(*)(void*);

    DeferredProcedure(CallbackFunction callback, void* userData) 
        : callback_(callback), data_(userData), timerHandle_(0) {}

    void StartTimer(unsigned int intervalInMilliseconds) {
        timerHandle_ = SetTimer(NULL, 0, intervalInMilliseconds, TimerCallback);
    }

    void Stop() {
        if (timerHandle_ != 0) {
            KillTimer(NULL, timerHandle_);
            timerHandle_ = 0;
        }
    }

    ~DeferredProcedure() {
        Stop();
    }

private:
    static void CALLBACK TimerCallback(HWND, UINT, UINT_PTR timerId, DWORD) {
        DeferredProcedure* instance = reinterpret_cast<DeferredProcedure*>(timerId);
        instance->callback_(instance->data_);
    }

    CallbackFunction callback_;
    void* data_;
    UINT_PTR timerHandle_;
};

