    std::lock_guard<std::mutex> guard(statsMutex);
    auto now = std::chrono::steady_clock::now();

    if (clientRequestStats.find(clientAddr) == clientRequestStats.end() || 
        now - clientRequestStats[clientAddr].second >= std::chrono::seconds(WINDOW_SIZE)) {
        // Reset counter when time window expires
        clientRequestStats[clientAddr] = {1, now};
    } else {
        // Increase counter while within the allowed time frame
        clientRequestStats[clientAddr].first++;
    }

    if (clientRequestStats[clientAddr].first > MAX_REQUESTS) {
        // Return 429 Too Many Requests when threshold is surpassed
        resp.headers().add<Http::Header::AccessControlAllowOrigin>("*");
        resp.send(Pistache::Http::Code::Too_Many_Requests, "Rate limit exceeded");
    } else {
        // Continue normal request processing
        // ...
    }
}

