#include <iostream>

// Function to process and modify the first Modbus request and response packets
void updateInitialModbusRequestAndResponsePackets(PcapFileReaderDevice *inputReader, PcapFileWriterDevice *outputWriter) {
    bool requestFound = false;
    bool responseFound = false;

    // Process each packet in the input PCAP file
    while (true) {
        RawPacket currentPacket;
        if (!inputReader->getNextPacket(currentPacket)) {
            // End of packet stream reached
            break;
        }

        // Decode the raw packet into a Modbus packet structure
        ModbusPacket decodedPacket = decodeModbusPacket(currentPacket);

        // Check for the first Modbus request packet
        if (decodedPacket.packetType == ModbusPacketType::Request && !requestFound) {
            // Apply modifications to the first Modbus request
            applyModificationsToModbusRequest(decodedPacket);
            requestFound = true;
        } 
        // Check for the first Modbus response packet
        else if (decodedPacket.packetType == ModbusPacketType::Response && !responseFound) {
            // Apply modifications to the first Modbus response
            applyModificationsToModbusResponse(decodedPacket);
            responseFound = true;
        }

        // Save the (potentially modified) packet to the output file
        outputWriter->writePacket(currentPacket);
    }

    // Validate that both packet types were found
    if (!requestFound || !responseFound) {
        // Report error if either packet type is missing
        EXIT_WITH_ERROR("Missing required Modbus request or response packets");
    }
}

#include <iostream>
#include <vector>
#include <cstdint>
#include <algorithm>

class Uint64Array {
private:
    std::vector<uint64_t> m_Data;
public:
    // Constructor to initialize the array with a specified value
    Uint64Array(uint64_t val) : m_Data(64, val) {}

    // Method to add two arrays element-wise
    Uint64Array sum(const Uint64Array& rhs) const {
        Uint64Array temp(0);
        for (size_t idx = 0; idx < 64; ++idx) {
            temp.m_Data[idx] = m_Data[idx] + rhs.m_Data[idx];
        }
        return temp;
    }

    // Method to subtract two arrays element-wise
    Uint64Array difference(const Uint64Array& rhs) const {
        Uint64Array temp(0);
        for (size_t idx = 0; idx < 64; ++idx) {
            temp.m_Data[idx] = m_Data[idx] - rhs.m_Data[idx];
        }
        return temp;
    }

    // Method to multiply two arrays element-wise
    Uint64Array product(const Uint64Array& rhs) const {
        Uint64Array temp(0);
        for (size_t idx = 0; idx < 64; ++idx) {
            temp.m_Data[idx] = m_Data[idx] * rhs.m_Data[idx];
        }
        return temp;
    }

    // Method to divide two arrays element-wise
    Uint64Array quotient(const Uint64Array& rhs) const {
        Uint64Array temp(0);
        for (size_t idx = 0; idx < 64; ++idx) {
            if (rhs.m_Data[idx] != 0) {
                temp.m_Data[idx] = m_Data[idx] / rhs.m_Data[idx];
            } else {
                // On division by zero, assign maximum uint64_t value
                temp.m_Data[idx] = std::numeric_limits<uint64_t>::max();
            }
        }
        return temp;
    }

    // Accessor for smallest element in the array
    uint64_t minimum() const {
        return *std::min_element(m_Data.begin(), m_Data.end());
    }

    // Accessor for largest element in the array
    uint64_t maximum() const {
        return *std::max_element(m_Data.begin(), m_Data.end());
    }
};

int main() {
    Uint64Array arr1(5);
    Uint64Array arr2(3);

    Uint64Array resultSum = arr1.sum(arr2);
    Uint64Array resultDiff = arr1.difference(arr2);
    Uint64Array resultProd = arr1.product(arr2);
    Uint64Array resultQuo = arr1.quotient(arr2);

    std::cout << "Minimum of sum: " << resultSum.minimum() << std::endl;
    std::cout << "Maximum of sum: " << resultSum.maximum() << std::endl;
    std::cout << "Minimum of difference: " << resultDiff.minimum() << std::endl;
    std::cout << "Maximum of difference: " << resultDiff.maximum() << std::endl;
    std::cout << "Minimum of product: " << resultProd.minimum() << std::endl;
    std::cout << "Maximum of product: " << resultProd.maximum() << std::endl;
    std::cout << "Minimum of quotient: " << resultQuo.minimum() << std::endl;
    std::cout << "Maximum of quotient: " << resultQuo.maximum() << std::endl;

    return 0;
}

#include <iostream>
#include <algorithm>

// Compute minimum cost using two different pricing strategies
int64_t calculateMinimumExpense(int64_t pricePerUnit, int64_t bulkPrice, int64_t totalUnits, int64_t bundleSize) {
    int64_t remainder = totalUnits % bundleSize;
    int64_t fullBundles = totalUnits / bundleSize;

    // Option 1: Buy some individual units + full bundles
    int64_t option1 = remainder * pricePerUnit + fullBundles * bulkPrice;

    // Option 2: Buy one more bundle instead of remaining units
    int64_t option2 = fullBundles * bulkPrice + bulkPrice;

    return std::min(option1, option2);
}

int main() {
    std::cout << calculateMinimumExpense(3, 5, 7, 2) << std::endl;  // Output: 26
    std::cout << calculateMinimumExpense(2, 3, 5, 3) << std::endl;  // Output: 9
    return 0;
}

