template <typename T>
std::string convert_to_string(T value) {
    char buffer[32]; // Buffer size of 32 characters for string representation
    if constexpr (std::is_same_v<T, int>) {
        sprintf_s(buffer, sizeof(buffer), "%i", value);
    } else if constexpr (std::is_same_v<T, unsigned int>) {
        sprintf_s(buffer, sizeof(buffer), "%u", value);
    } else if constexpr (std::is_same_v<T, long>) {
        sprintf_s(buffer, sizeof(buffer), "%li", value);
    } else if constexpr (std::is_same_v<T, short>) {
        sprintf_s(buffer, sizeof(buffer), "%hi", value);
    } else if constexpr (std::is_same_v<T, unsigned short>) {
        sprintf_s(buffer, sizeof(buffer), "%hu", value);
    } else if constexpr (std::is_same_v<T, long long>) {
        sprintf_s(buffer, sizeof(buffer), "%lli", value);
    } else if constexpr (std::is_same_v<T, unsigned long>) {
        sprintf_s(buffer, sizeof(buffer), "%lu", value);
    } else if constexpr (std::is_same_v<T, unsigned long long>) {
        sprintf_s(buffer, sizeof(buffer), "%llu", value);
    }
    return buffer;
}

