struct Body {
    int px, py, dx, dy;
    void update() {
        px += dx;
        py += dy;
    }
};

int main(int argc, char** argv) {
    if (argc < 3) {
        std::cout << "usage: " << argv[0] << " <data_file> <iterations>" << std::endl;
        return 1;
    }

    std::ifstream data_stream(argv[1]);
    if (!data_stream.is_open()) {
        std::cerr << "Error: Cannot open file " << argv[1] << std::endl;
        return 1;
    }

    int iterations = std::stoi(argv[2]);
    std::vector<Body> bodies;
    std::string current_line;

    while (std::getline(data_stream, current_line)) {
        if (current_line.find("body") != std::string::npos) {
            Body obj;

            // Read position information
            std::getline(data_stream, current_line);
            std::sscanf(current_line.c_str(), "  location: <%d, %d>", &obj.px, &obj.py);

            // Read velocity information
            std::getline(data_stream, current_line);
            std::sscanf(current_line.c_str(), "  motion: <%d, %d>", &obj.dx, &obj.dy);

            bodies.push_back(obj);
        }
    }

    for (int step = 0; step < iterations; ++step) {
        for (auto& body : bodies) {
            body.update();
        }
    }

    for (const auto& body : bodies) {
        std::cout << "Final coordinates: (" << body.px << ", " << body.py << ")" << std::endl;
    }

    return 0;
}

