class FunctionRegistry {
private:
    std::unordered_map<std::string, std::function<void()>> funcMap;
public:
    void addFunction(const std::string& funcName, const std::function<void()>& funcPtr) {
        if (funcMap.find(funcName) != funcMap.end()) {
            throw std::invalid_argument("Function named " + funcName + " already exists");
        }
        funcMap[funcName] = funcPtr;
    }
    template<typename... Args>
    void callFunction(const std::string& funcName, Args&&... args) {
        if (funcMap.find(funcName) == funcMap.end()) {
            throw std::invalid_argument("Function named " + funcName + " is not registered");
        }
        funcMap[funcName](std::forward<Args>(args)...);
    }
};

