#include <iostream>
#include <cmath>

// Abstract base class for geometric shapes
class Shape {
public:
    virtual double calculateArea() = 0;
    virtual double calculatePerimeter() = 0;
    virtual void showInfo() = 0;
};

// Circle implementation
class Circle : public Shape {
private:
    double radiusValue;
public:
    Circle(double r) : radiusValue(r) {}
    double calculateArea() override {
        return M_PI * radiusValue * radiusValue;
    }
    double calculatePerimeter() override {
        return 2 * M_PI * radiusValue;
    }
    void showInfo() override {
        std::cout << "Circle - Radius: " << radiusValue << ", Area: " << calculateArea() << ", Perimeter: " << calculatePerimeter() << std::endl;
    }
};

// Rectangle implementation
class Rectangle : public Shape {
private:
    double lengthValue, widthValue;
public:
    Rectangle(double l, double w) : lengthValue(l), widthValue(w) {}
    double calculateArea() override {
        return lengthValue * widthValue;
    }
    double calculatePerimeter() override {
        return 2 * (lengthValue + widthValue);
    }
    void showInfo() override {
        std::cout << "Rectangle - Length: " << lengthValue << ", Width: " << widthValue << ", Area: " << calculateArea() << ", Perimeter: " << calculatePerimeter() << std::endl;
    }
};

// Triangle implementation using Heron's formula
class Triangle : public Shape {
private:
    double sideA, sideB, sideC;
public:
    Triangle(double s1, double s2, double s3) : sideA(s1), sideB(s2), sideC(s3) {}
    double calculateArea() override {
        double semiPerimeter = (sideA + sideB + sideC) / 2;
        return sqrt(semiPerimeter * (semiPerimeter - sideA) * (semiPerimeter - sideB) * (semiPerimeter - sideC));
    }
    double calculatePerimeter() override {
        return sideA + sideB + sideC;
    }
    void showInfo() override {
        std::cout << "Triangle - Side1: " << sideA << ", Side2: " << sideB << ", Side3: " << sideC << ", Area: " << calculateArea() << ", Perimeter: " << calculatePerimeter() << std::endl;
    }
};

int main() {
    Circle c(5.0);
    Rectangle r(4.0, 6.0);
    Triangle t(3.0, 4.0, 5.0);
    c.showInfo();
    r.showInfo();
    t.showInfo();
    return 0;
}

