TInt64 CliTask::command_lsahci(TInt argCount, char **argValues) {
  // Validate argument count - must have exactly one parameter
  if (argCount != 2) {
    Error("lsahci requires precisely one argument");
    return -1;  // Indicate failure with error code
  }

  std::string targetPath = argValues[1];  // Extract directory path from command arguments
  if (!std::filesystem::exists(targetPath)) {
    Error("Specified directory does not exist");
    return -1;  // Return error status
  }

  if (!std::filesystem::is_directory(targetPath)) {
    Error("Provided path is not a directory");
    return -1;  // Return error status
  }

  mWindow->WriteFormatted("Directory listing for '%s':\n", targetPath.c_str());

  // Iterate through all entries in the directory
  for (const auto& item : std::filesystem::directory_iterator(targetPath)) {
    mWindow->WriteFormatted("%s\n", item.path().filename().string().c_str());
  }

  return 0;  // Signal successful completion
}

