        // Examine the character between the quotes
        char ch = text[1];
        if (ch >= 32 && ch <= 126 && ch != '\'') {
            return true;  // Valid single character in printable ASCII range
        }
    }
    return false;  // Does not meet criteria for valid character literal
}

