// Validates tensor configuration for L2 normalization operation
arm_compute::Status ClL2NormalizationWorkloadValidate(const TensorInfo& tensor,
                                                      const DataLayout& layout)
{
    // Verify tensor is resizable and has correct data layout
    if (!tensor.is_resizable() || tensor.data_layout() != layout)
    {
        return arm_compute::Status(arm_compute::ErrorCode::RUNTIME_ERROR, "Invalid input tensor");
    }

    // Confirm data type supports L2 normalization (FP16 or FP32)
    if (tensor.data_type() != DataType::F16 && tensor.data_type() != DataType::F32)
    {
        return arm_compute::Status(arm_compute::ErrorCode::RUNTIME_ERROR, "Unsupported data type for L2 normalization");
    }

    // Validate tensor dimensions: must be 4D with spatial dimensions of 1x1
    const TensorShape& shape = tensor.tensor_shape();
    if (shape.num_dimensions() != 4 || shape[2] != 1 || shape[3] != 1)
    {
        return arm_compute::Status(arm_compute::ErrorCode::RUNTIME_ERROR, "Invalid input tensor dimensions for L2 normalization");
    }

    // All validation checks passed successfully
    return arm_compute::Status::Success;
}

#include <iostream>

// Custom smart pointer implementation with reference counting
template <typename T>
class SmartPointer {
private:
    T* dataPtr;
    unsigned long* countPtr;

public:
    // Constructor: takes ownership of a raw pointer
    explicit SmartPointer(T* p) : dataPtr(p), countPtr(new unsigned long(1)) {}

    // Copy constructor: shares ownership and increments reference count
    SmartPointer(const SmartPointer& other) : dataPtr(other.dataPtr), countPtr(other.countPtr) {
        ++(*countPtr);
    }

    // Assignment operator: handles self-assignment, decrements old ref count, increments new one
    SmartPointer& operator=(const SmartPointer& other) {
        if (this != &other) {
            if (--(*countPtr) == 0) {
                delete dataPtr;
                delete countPtr;
            }
            dataPtr = other.dataPtr;
            countPtr = other.countPtr;
            ++(*countPtr);
        }
        return *this;
    }

    // Destructor: releases resources when reference count reaches zero
    ~SmartPointer() {
        if (--(*countPtr) == 0) {
            delete dataPtr;
            delete countPtr;
        }
    }

    // Access the underlying raw pointer
    T* access() const {
        return dataPtr;
    }

    // Query current number of shared owners
    unsigned long count() const {
        return *countPtr;
    }
};

int main() {
    // Initialize first smart pointer with value 42
    SmartPointer<int> sp1(new int(42));

    // Create second smart pointer by copying the first
    SmartPointer<int> sp2 = sp1;

    // Output the reference count after duplication
    std::cout << "Reference count: " << sp1.count() << std::endl;

    // Create third smart pointer with different value
    SmartPointer<int> sp3(new int(100));

    // Assign third pointer to second (causing first to release its resource)
    sp2 = sp3;

    // Output final reference count
    std::cout << "Reference count: " << sp3.count() << std::endl;

    return 0;
}

