// Template class for Binary Indexed Tree (Fenwick Tree)
template <typename T>
class fenwick_tree {
  std::vector<T> tree;
  T combine(T left, T right) const { return left + right; }
  // ... other constructors and methods
public:
  fenwick_tree(size_t size) : tree(size + 1, NEUTRAL) {}
  fenwick_tree(size_t size, T value) : tree(size + 1, NEUTRAL) {
    for (int index = 0; index < (int)size; ++index) {
      add(index, value);
    }
  }
  // Your completed methods
  void add(int position, T delta) {
    position++;
    while (position < tree.size()) {
      tree[position] = combine(tree[position], delta);
      position += position & -position;
    }
  }
  T prefix_sum(int index) const {
    T result = NEUTRAL;
    while (index > 0) {
      result = combine(result, tree[index]);
      index -= index & -index;
    }
    return result;
  }
};

