// Compute the trimmed average of a list of integer scores
int computeTrimmedMean(std::vector<int> grades) {
    if (grades.size() <= 2) {
        return 0;  // Not enough data points to trim and average
    }

    // Arrange grades in ascending order
    std::sort(grades.begin(), grades.end());

    // Sum all grades except the lowest and highest
    int accumulated = std::accumulate(grades.begin() + 1, grades.end() - 1, 0);

    // Determine count of remaining elements after trimming
    int count = grades.size() - 2;

    // Compute mean and round to nearest whole number
    int result = static_cast<int>(std::round(static_cast<double>(accumulated) / count));

    return result;
}

