// Perform topological sorting on the given nodes
std::vector<Node::Ptr> topologicalSort(const std::vector<Node::Ptr>& inputNodes) {
    std::vector<Node::Ptr> resultOrder;
    std::queue<Node::Ptr> readyQueue;
    std::unordered_map<Node::Ptr, int> incomingCount;

    // Compute incoming edge count for each node
    for (const auto& currentNode : inputNodes) {
        for (const auto& adjacentNode : getNeighbors(currentNode)) {
            incomingCount[adjacentNode]++;
        }
    }

    // Add all nodes with zero incoming edges to the queue
    for (const auto& currentNode : inputNodes) {
        if (incomingCount[currentNode] == 0) {
            readyQueue.push(currentNode);
        }
    }

    // Process nodes in topological order
    while (!readyQueue.empty()) {
        Node::Ptr current = readyQueue.front();
        readyQueue.pop();
        resultOrder.push_back(current);

        for (const auto& adjacentNode : getNeighbors(current)) {
            incomingCount[adjacentNode]--;
            if (incomingCount[adjacentNode] == 0) {
                readyQueue.push(adjacentNode);
            }
        }
    }

    return resultOrder;
}

