Variable nansum(const Variable &input_var, const Dim axis, const Masks &masks) {
  if (const auto combined_mask = irreducible_mask(masks, axis);
      combined_mask.is_valid()) {
    // Exclude elements based on the combined mask and recursively compute sum
    return nansum(where(combined_mask, zero_like(input_var), input_var), axis, masks);
  } else {
    // Compute the sum of valid (non-NaN) elements along the specified axis
    switch (axis) {
      case Dim::ROW:
        return sum(where(isnan(input_var), 0.0, input_var), Dim::ROW);
      case Dim::COLUMN:
        return sum(where(isnan(input_var), 0.0, input_var), Dim::COLUMN);
      // Support for other dimensions can be added here
      default:
        throw std::invalid_argument("Unsupported dimension provided");
    }
  }
}

