#include "Font/LoadPSF.hpp"
#include <SDL.h>
#include <iostream>

// Renders a PSF font texture to the renderer with scaling
SDL_Texture* DrawPSF(const char* psfFilePath, SDL_Renderer* renderer, int scaleFactor) {
    // Load the PSF font data from file
    PSFFont psfData = LoadPSF(psfFilePath);

    // Extract character dimensions from the loaded font header
    int charWidth = psfData.header->width;
    int charHeight = psfData.header->height;

    // Create an off-screen surface for rendering font glyphs
    SDL_Surface* tempSurface = SDL_CreateRGBSurface(0, charWidth, charHeight, 32, 0, 0, 0, 0);

    // Iterate through all possible character codes (0-255)
    for (int charIndex = 0; charIndex < 256; charIndex++) {
        // Retrieve the bitmap for the current character
        const uint8_t* glyphBitmap = psfData.chars[charIndex];

        // Render each pixel of the character based on the bitmap
        for (int row = 0; row < charHeight; row++) {
            for (int col = 0; col < charWidth; col++) {
                // Extract the bit corresponding to the current pixel position
                uint8_t bitValue = (glyphBitmap[row] >> (7 - col)) & 1;
                // Set pixel color: white for set bits, black for unset
                uint32_t pixelColor = bitValue ? 0xFFFFFFFF : 0x00000000;

                // Write the pixel to the surface buffer
                *((uint32_t*)tempSurface->pixels + row * charWidth + col) = pixelColor;
            }
        }

        // Convert the surface into a texture for rendering
        SDL_Texture* charTexture = SDL_CreateTextureFromSurface(renderer, tempSurface);

        // Define destination rectangle for scaled placement
        SDL_Rect renderRect = { charIndex * charWidth * scaleFactor, 0, 
                                charWidth * scaleFactor, charHeight * scaleFactor };

        // Copy the character texture to the renderer
        SDL_RenderCopy(renderer, charTexture, nullptr, &renderRect);

        // Release the temporary texture to avoid memory leaks
        SDL_DestroyTexture(charTexture);
    }

    // Free the temporary surface after all characters are processed
    SDL_FreeSurface(tempSurface);

    // Return the last created texture (note: this may be undefined behavior if no texture was created)
    return charTexture;
}

