// Compute the molar mass of a chemical compound
double CalculateMolarMass(std::istream& input) {
  // Dictionary mapping element symbols to their atomic masses
  std::map<std::string, double> elementMasses = {
    {"H", 1.008}, {"C", 12.011}, {"O", 15.999}, {"N", 14.007}
    // Additional elements can be added here as needed
  };

  double mass = 0.0;
  std::string symbol;
  int quantity;

  // Parse the chemical formula from the input stream
  while (input >> symbol >> quantity) {
    if (elementMasses.find(symbol) != elementMasses.end()) {
      mass += elementMasses[symbol] * quantity;
    } else {
      std::cerr << "Warning: Unknown element '" << symbol << "' encountered" << std::endl;
      return -1.0;  // Indicates an error due to unknown element
    }
  }

  return mass;
}

int main() {
  // Demonstration with water
  std::string compound = "H2O";
  std::istringstream inputStream(compound);
  double molarMass = CalculateMolarMass(inputStream);
  std::cout << "Molar mass of " << compound << " equals " << molarMass << std::endl;
  return 0;
}

