// Compute the sigmoid activation function
float activationFunction(int value) {
    return 1.0f / (1.0f + exp(-static_cast<float>(value)));
}

// Assess the performance metric based on network outputs
float assessPerformance(const std::vector<float>& results) {
    float score = 0.0f;

    // Accumulate correction term for each result entry
    for (float val : results) {
        score -= (1.0f - val);
    }

    // Evaluate model response to input pair {1, 1}
    float outputVal = network->compute({1, 1})->results[0]->data;
    score -= outputVal;

    // Apply structural penalty if output neuron has non-zero but inconsistent impulse count
    if (network->output[0]->signalCount > 0 && 
        network->output[0]->signalCount != network->output[0]->inputCount) {
        network->printDetails();
        int stepCounter = 0;  // Reset counter
        stepCounter++;        // Advance counter by one
    }

    // Incorporate hidden layer regularization term
    score += -activationFunction(network->hidden.size()) + 1.0f;

    return score;
}

