// Function to produce a random value from a standard normal distribution (mean=0, stddev=1)
double produceRandomValue(std::default_random_engine& rng) {
    std::normal_distribution<double> dist(0.0, 1.0);
    return dist(rng);
}

int main() {
    // Set up simulation parameters
    double velocity = 0.0;      // Starting velocity
    double position = 0.0;      // Starting position
    double velStdDev = 0.1;     // Standard deviation for velocity changes
    double posStdDev = 0.2;     // Standard deviation for position changes
    int totalSteps = 100;       // Total number of simulation steps
    std::default_random_engine generator;  // Random engine

    // Container to hold data for each time step
    std::map<std::string, double> record;

    int index = 0;              // Record counter
    double currentTime = 0.0;   // Simulation time variable

    // Perform the simulation loop
    for (int step = 0; step < totalSteps; ++step) {
        // Apply stochastic updates using Euler-Maruyama approach
        velocity += velStdDev * produceRandomValue(generator);
        position += posStdDev * produceRandomValue(generator);

        // Store current state in the record
        record["Idx"] = index++;
        record["Time"] = currentTime;
        record["Vel"] = velocity;
        record["Pos"] = position;
        record["PosStd"] = posStdDev;
        record["VelStd"] = velStdDev;

        // Output all recorded values
        for (const auto& item : record) {
            std::cout << item.first << ": " << item.second << std::endl;
        }

        // Advance time
        currentTime += 1.0;

        // Reset record for next iteration
        record.clear();
    }

    return 0;
}

