// Function to compute the intersection point between a ray and a plane
Vector3 FindRayPlaneIntersection(const Ray& inputRay, const Vector3& pointOnPlane, const Vector3& planeOrientation) {
    float denom = DotProduct(planeOrientation, inputRay.direction);

    // Determine if the ray is parallel or lies on the plane
    if (std::abs(denom) < TOLERANCE) {
        // No intersection exists due to parallelism
        return InvalidResult; // Placeholder for no-intersection case
    }

    Vector3 originToPlane = pointOnPlane - inputRay.startPoint;
    float param = DotProduct(originToPlane, planeOrientation) / denom;

    // Verify that the intersection occurs in the forward direction of the ray
    if (param < 0) {
        // Intersection lies behind the ray's starting point
        return InvalidResult; // Placeholder for no-intersection case
    }

    // Compute the actual intersection coordinates
    Vector3 resultPoint = inputRay.startPoint + inputRay.direction * param;
    return resultPoint;
}

