#include <png.h>
#include <fstream>
#include <iostream>

void PNGImageReader::LoadGrayscalePNG(const std::string &filepath, GrayscaleFloatImage &output) {
    // Open the PNG file for reading in binary mode
    std::ifstream input(filepath, std::ios::binary);
    if (!input) {
        std::cerr << "Error: Cannot open file " << filepath << std::endl;
        return;
    }

    // Initialize PNG read structure
    png_structp png_reader = png_create_read_struct(PNG_LIBPNG_VER_STRING, nullptr, nullptr, nullptr);
    if (!png_reader) {
        std::cerr << "Error: Could not allocate PNG read structure" << std::endl;
        input.close();
        return;
    }

    // Create and initialize info structure
    png_infop png_info = png_create_info_struct(png_reader);
    if (!png_info) {
        std::cerr << "Error: Could not create PNG info structure" << std::endl;
        png_destroy_read_struct(&png_reader, nullptr, nullptr);
        input.close();
        return;
    }

    // Set up exception handling for PNG errors
    if (setjmp(png_jmpbuf(png_reader))) {
        std::cerr << "Error: PNG processing failed during file reading" << std::endl;
        png_destroy_read_struct(&png_reader, &png_info, nullptr);
        input.close();
        return;
    }

    // Connect the file stream to the PNG reader
    png_init_io(png_reader, input);

    // Extract image metadata from PNG header
    png_read_info(png_reader, png_info);
    int img_width  = png_get_image_width(png_reader, png_info);
    int img_height = png_get_image_height(png_reader, png_info);
    int depth      = png_get_bit_depth(png_reader, png_info);
    int color_mode = png_get_color_type(png_reader, png_info);

    // Validate image format: must be 8-bit grayscale
    if (color_mode != PNG_COLOR_TYPE_GRAY || depth != 8) {
        std::cerr << "Error: Unsupported PNG configuration. Only 8-bit grayscale images are allowed." << std::endl;
        png_destroy_read_struct(&png_reader, &png_info, nullptr);
        input.close();
        return;
    }

    // Allocate row buffers for pixel data
    png_bytep scanlines[img_height];
    size_t row_size = png_get_rowbytes(png_reader, png_info);
    for (int row = 0; row < img_height; ++row) {
        scanlines[row] = static_cast<png_bytep>(malloc(row_size));
    }

    // Read all image rows into memory
    png_read_image(png_reader, scanlines);

    // Convert raw byte data to normalized floating-point pixel values
    for (int row = 0; row < img_height; ++row) {
        for (int col = 0; col < img_width; ++col) {
            float normalized = static_cast<float>(scanlines[row][col]) / 255.0f;
            output.SetPixelValue(col, row, normalized);
        }
    }

    // Release allocated resources
    for (int row = 0; row < img_height; ++row) {
        free(scanlines[row]);
    }
    png_destroy_read_struct(&png_reader, &png_info, nullptr);
    input.close();
}

#include <memory>

class CustomMemoryManager {
    std::shared_ptr<void> memoryBlock;

    template<typename U>
    static void customDeleter(void* rawPtr) {
        static_cast<U*>(rawPtr)->~U();
        operator delete(rawPtr);
    }

public:
    template<typename U>
    U* getMemory() {
        memoryBlock.reset(new U, customDeleter<U>);
        return static_cast<U*>(memoryBlock.get());
    }

    template<typename U>
    void releaseMemory(U* ptr) {
        if (ptr == memoryBlock.get()) {
            memoryBlock.reset();
        }
    }
};

