// Program to determine the day of the week for a given date using Zeller's congruence
int main(int argc, char* argv[]) {
    int d, m, y;

    // Get day input either from command line or user prompt
    if (argc > 1) {
        d = std::atoi(argv[1]);
    } else { 
        std::cout << "Enter day: ";
        std::cin >> d;
    }

    std::cout << "Enter month: ";
    std::cin >> m;
    std::cout << "Enter year: ";
    std::cin >> y;

    // Adjust month and year for Zeller's formula (January/February are months 13/14 of previous year)
    if (m < 3) {
        m += 12;
        y--;
    }

    int c = y / 100;     // century
    y %= 100;            // year within century

    // Zeller's congruence calculation
    int w = (d + 13 * (m + 1) / 5 + y + y / 4 + c / 4 - 2 * c) % 7;

    // Handle negative modulo results
    if (w < 0) w += 7;

    // Output corresponding day of week
    switch (w) {
        case 0:
            std::cout << "Saturday" << std::endl;
            break;
        case 1:
            std::cout << "Sunday" << std::endl;
            break;
        case 2:
            std::cout << "Monday" << std::endl;
            break;
        case 3:
            std::cout << "Tuesday" << std::endl;
            break;
        case 4:
            std::cout << "Wednesday" << std::endl;
            break;
        case 5:
            std::cout << "Thursday" << std::endl;
            break;
        case 6:
            std::cout << "Friday" << std::endl;
            break;
    }

    return 0;
}

