// Helper function to extract comparison key from element
static inline int GetKey(const _E& item) {
    // Extract the comparable value from the element
    // Assumes _E has a public member 'value'
    return item.value;
}

// Less-than comparison based on extracted keys
static inline bool IsLess(const _E& first, const _E& second) {
    return GetKey(first) < GetKey(second);
}

// Lexicographical comparison of two element arrays
static inline int CompareArrays(const _E* arr1, const _E* arr2, size_t count) {
    for (size_t index = 0; index < count; ++index) {
        if (IsLess(arr1[index], arr2[index])) {
            return -1;  // First array is lexicographically smaller
        } else if (IsLess(arr2[index], arr1[index])) {
            return 1;   // First array is lexicographically larger
        }
    }
    return 0;  // Arrays are equal
}

