// Compute the squared Euclidean distance between two vectors
double computeVectorDistanceSquared(const std::vector<double>& firstVec, const std::vector<double>& secondVec) {
    // Ensure both vectors have identical dimensions
    if (firstVec.size() != secondVec.size()) {
        throw std::invalid_argument("Vector dimensions must match");
    }

    // Map standard vectors to Eigen vector objects for optimized operations
    Eigen::Map<const Eigen::VectorXd> eigenRep1(firstVec.data(), firstVec.size());
    Eigen::Map<const Eigen::VectorXd> eigenRep2(secondVec.data(), secondVec.size());

    // Calculate squared distance via Eigen's norm method
    double result = (eigenRep1 - eigenRep2).squaredNorm();
    return result;
}

