// Derive encryption keys using HKDF-based key schedule
std::pair<std::vector<uint8_t>, std::unique_ptr<folly::IOBuf>> deriveKeys(
    const std::vector<uint8_t>& inputSecret,
    const std::vector<uint8_t>& clientPsk,
    const SuiteId& algorithmSuite,
    const KeyScheduleContext& scheduleContext,
    const Cipher& encryptionCipher) {

  // Perform HKDF extraction with labeled salt
  std::vector<uint8_t> derivedSecret = hkdf->labeledExtract(
      folly::ByteRange(inputSecret),
      folly::ByteRange(folly::StringPiece("secret")),
      folly::ByteRange(clientPsk),
      algorithmSuite.clone());

  // Expand to generate the actual key material
  std::unique_ptr<folly::IOBuf> keyMaterial = hkdf->labeledExpand(
      derivedSecret,
      folly::ByteRange(folly::StringPiece("key")),
      scheduleContext.clone(),
      encryptionCipher.keyLength());

  return std::make_pair(derivedSecret, std::move(keyMaterial));
}

