#include <iostream>
#include <vector>

// Compute the mean waiting duration for a collection of tasks
float computeMeanWaitingDuration(const std::vector<std::pair<int, int>>& tasks) {
    int count = tasks.size();
    int accumulatedWait = 0;
    int currentTick = 0;

    for (const auto& task : tasks) {
        int startDelay = task.first;
        int workDuration = task.second;

        // Determine idle time before processing this task
        int waitInterval = std::max(0, currentTick - startDelay);
        accumulatedWait += waitInterval;

        // Advance timeline by the task's execution length
        currentTick += workDuration;

        // Adjust timeline if the task arrived later than expected
        if (startDelay > currentTick) {
            currentTick = startDelay + workDuration;
        }
    }

    // Derive the average waiting interval
    float meanWaitingDuration = static_cast<float>(accumulatedWait) / count;
    return meanWaitingDuration;
}

