// Define an abstract base class for animators
class AnimationController {
public:
    virtual void step() = 0;
};

// Define a position animator class
class PositionAnimation : public AnimationController {
private:
    Vector2D currentLocation;
public:
    PositionAnimation(float startX, float startY) : currentLocation(startX, startY) {}

    void step() override {
        // Simulate movement by incrementing coordinates
        currentLocation.horizontal += 1.0f;
        currentLocation.vertical += 0.5f;
    }

    Vector2D getPosition() const {
        return currentLocation;
    }
};

// Define a color animator class
class ColorAnimation : public AnimationController {
private:
    Color presentColor;
public:
    ColorAnimation(int startR, int startG, int startB) : presentColor(startR, startG, startB) {}

    void step() override {
        // Cycle through RGB values with increments
        presentColor.red = (presentColor.red + 1) % 256;
        presentColor.green = (presentColor.green + 2) % 256;
        presentColor.blue = (presentColor.blue + 3) % 256;
    }

    Color getCurrentColor() const {
        return presentColor;
    }
};

int main() {
    // Initialize animators with starting values
    PositionAnimation posAnim(100.0f, 100.0f);
    ColorAnimation colAnim(255, 0, 0);

    // Run animation loop
    for (int frame = 0; frame < 10; ++frame) {
        posAnim.step();
        colAnim.step();

        // Get updated state
        Vector2D location = posAnim.getPosition();
        Color color = colAnim.getCurrentColor();

        // Output the drawing command
        std::cout << "Drawing circle at (" << location.horizontal << ", " << location.vertical 
                  << ") with color (" << color.red << ", " << color.green 
                  << ", " << color.blue << ")" << std::endl;
