namespace blmc_controllers
{
    class CentroidalPDController
    {
    public:
        CentroidalPDController(double proportional_gain, double derivative_gain)
            : kp_(proportional_gain), kd_(derivative_gain) {}

        void update(const RobotState& current_robot_state, ActuatorCommand& output_actuator_command)
        {
            // Retrieve current center of mass position and velocity from robot state
            Eigen::Vector3d com_position = current_robot_state.getCenterOfMassPosition();
            Eigen::Vector3d com_velocity = current_robot_state.getCenterOfMassVelocity();

            // Compute error between desired and actual center of mass position and velocity
            Eigen::Vector3d com_position_deviation = desired_com_position_ - com_position;
            Eigen::Vector3d com_velocity_deviation = desired_com_velocity_ - com_velocity;

            // Determine control command using PD control law
            Eigen::Vector3d control_output = kp_ * com_position_deviation + kd_ * com_velocity_deviation;

            // Apply the control command to the actuator command
            output_actuator_command.setControlCommand(control_output);
        }

        void setTargetCenterOfMass(const Eigen::Vector3d& target_position, const Eigen::Vector3d& target_velocity)
        {
            desired_com_position_ = target_position;
            desired_com_velocity_ = target_velocity;
        }

    private:
        double kp_;  // Proportional gain
        double kd_;  // Derivative gain
        Eigen::Vector3d desired_com_position_;
        Eigen::Vector3d desired_com_velocity_;
    };
}  // namespace blmc_controllers

#include <fcppt/math/vector/object.hpp>
#include <fcppt/math/vector/static.hpp>

// Compute the cross product of two 3D vectors
template <typename T, typename S1, typename S2>
fcppt::math::vector::static_<T, 3> cross_product(
    fcppt::math::vector::object<T, 3, S1> const &lhs, 
    fcppt::math::vector::object<T, 3, S2> const &rhs)
{
  return fcppt::math::vector::static_<T, 3>(
      lhs[1] * rhs[2] - lhs[2] * rhs[1],
      lhs[2] * rhs[0] - lhs[0] * rhs[2],
      lhs[0] * rhs[1] - lhs[1] * rhs[0]);
}

