// Calculate minimum number of boats required to rescue all people
int numRescueBoats(std::vector<int>& weights, int maxCapacity) {
    int count = weights.size();
    int result = 0;
    int paired = 0;

    std::sort(weights.begin(), weights.end());

    for (int i = count - 1; i >= paired; i--) {
        result++;
        if (weights[i] + weights[paired] <= maxCapacity) {
            paired++;
        }
    }

    return result;
}

