#include <queue>
using namespace std;

class Solution {
public:
    vector<int> maxSlidingWindow(vector<int>& nums, int windowSize) {
        vector<int> output;
        priority_queue<pair<int, int>> maxHeap;

        // Initialize heap with first 'windowSize' elements
        for(int index = 0; index < windowSize; index++) {
            maxHeap.push({nums[index], index});
        }

        // Store maximum of first window
        output.push_back(maxHeap.top().first);

        // Process remaining windows
        for(int right = windowSize; right < nums.size(); right++) {
            // Add current element to heap
            maxHeap.push({nums[right], right});

            // Remove elements outside current window
            while(!maxHeap.empty() && maxHeap.top().second <= right - windowSize) {
                maxHeap.pop();
            }

            // Record maximum of current window
            output.push_back(maxHeap.top().first);
        }

        return output;
    }
};

