// Function to demonstrate writing and reading nested array-of-map vectors
int main() {
    int rowCount = 10;
    SelectivityVector rows{rowCount};

    // Construct type: Array<Map<int64_t, int64_t>>
    auto vectorType = TypeFactory<TypeKind::ARRAY>::create(
        TypeFactory<TypeKind::MAP>::create(BIGINT(), BIGINT()));

    auto memoryPool = memory::memoryManager()->addLeafPool();
    VectorPtr outputVector;

    // Step 1: Ensure output vector is writable for target rows
    BaseVector::ensureWritable(rows, vectorType, memoryPool.get(), outputVector);

    // Step 2: Create vector writer for Array<Map<int64_t, int64_t>>
    exec::VectorWriter<Array<Map<int64_t, int64_t>>> dataWriter;

    // Step 3: Initialize writer with the result array vector
    dataWriter.init(*outputVector->as<ArrayVector>());

    rows.applyToSelected([&](vector_size_t index) {
        // Step 4: Set current row offset and get writer reference
        dataWriter.setOffset(index);
        auto& arrayBuilder = dataWriter.current();

        // Add first map with two key-value pairs
        auto& firstMap = arrayBuilder.add_item();
        firstMap.emplace(generateId(), generateId());
        firstMap.emplace(generateId(), generateId());

        // Add second (empty) map
        arrayBuilder.add_item();

        // Step 5: Commit the written row
        dataWriter.commit();
    });

    // Step 6: Finalize writing process
    dataWriter.finish();

    /****************** Vector Reader Section **********************/
    DecodedVector decodedData;
    decodedData.decode(*outputVector, rows);

    exec::VectorReader<Array<Map<int64_t, int64_t>>> dataReader(&decodedData);

    std::cout << "Reading Vector Data: " << std::endl;
    rows.applyToSelected([&](vector_size_t rowIndex) {
        if (!dataReader.isSet(rowIndex)) {
            std::cout << "[]" << std::endl;
            return;
        }

        std::cout << "[";
        auto arrayData = dataReader[rowIndex];

        for (const auto& mapEntry : arrayData) {
            if (mapEntry.has_value()) {
                std::cout << " {";
                for (const auto& [key, value] : mapEntry.value()) {
                    std::cout << "(" << key << ", "
                              << (value.has_value() ? std::to_string(value.value()) : "") << ")";
                }
                std::cout << "} ";
            } else {
                std::cout << " null ";
            }
        }
        std::cout << "]" << std::endl;
    });

    // Null-free reading path (asserted safe due to known structure)
    assert(!decodedData.mayHaveNullsRecursive());

    std::cout << "Reading Non-nullable Vector Data: " << std::endl;
    rows.applyToSelected([&](vector_size_t rowIndex) {
        std::cout << "[";
        auto flatArray = dataReader.readNullFree(rowIndex);

        for (const auto& mapItem : flatArray) {
            std::cout << " {";
            for (const auto& [k, v] : mapItem) {
                std::cout << "(" << k << ", " << v << ")";
            }
            std::cout << "} ";
        }
        std::cout << "]" << std::endl;
    });

    return 0;
}

