// Function to query the number of value-contiguous segments in the range [start, end]
int count_segments(int start, int end) {
    if (start > end) return 0;
    cout << "1 " << start << " " << end << endl;
    int response;
    cin >> response;
    return response;
}

// Function to swap elements at positions pos_a and pos_b
void execute_swap(int pos_a, int pos_b) {
    if (pos_a == pos_b) return;
    cout << "2 " << pos_a << " " << pos_b << endl;
    int result;
    cin >> result;
}

int main() {
    // Optimize I/O operations, though flush is handled by endl
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int array_size, range1, range2;
    if (!(cin >> array_size >> range1 >> range2)) return 0;

    // chain_length represents the length of the prefix p[1...chain_length]
    // which forms a value-contiguous chain (e.g., values y, y+1, y+2...).
    int chain_length = 1;
    while (chain_length < array_size) {
        // Check if the current end of the chain (p[chain_length]) has a neighbor (value-wise)
        // in the remaining unknown part of the array p[chain_length+1 ... array_size].
        // The number of segments in [chain_length, array_size] will be equal to or less than 
        // the number of segments in [chain_length+1, array_size] if p[chain_length] connects to something in the rest.
        int total_query = count_segments(chain_length, array_size);
        int rest_query = count_segments(chain_length + 1, array_size);

        if (total_query <= rest_query) {
            // A neighbor exists in p[chain_length+1 ... array_size].
            // Use binary search to find its exact index.
            int left = chain_length + 1;
            int right = array_size;

            while (left < right) {
                int middle = left + (right - left) / 2;
                // Check if the neighbor is in the left half [chain_length+1, middle]
                int sub_total = count_segments(chain_length, middle);
                int sub_rest = count_segments(chain_length + 1, middle);

                if (sub_total <= sub_rest) {
                    right = middle; // Neighbor is in the left half
                } else {
                    left = middle + 1; // Neighbor is in the right half
                }
            }
            // left is the index of the neighbor. Move it to the next position in the chain.
            execute_swap(chain_length + 1, left);
            chain_length++;
        } else {
            // No neighbor found in the rest. This implies p[chain_length] is an endpoint (value 1 or n).
            // We reverse the currently known chain p[1...chain_length] so that the other end
            // (which must have a neighbor in the rest) is now at p[chain_length].
            for (int i = 1; i <= chain_length / 2; ++i) {
                execute_swap(i, chain_length - i + 1);
            }
            // Continue the loop; the next iteration will find a neighbor.
        }
    }
    // Output the final permutation.
    // Since we constructed a chain of length n, the array contains either 1...n or n...1.
    // The problem states we just need to find one of the possible permutations.
    cout << "3";
    for (int idx = 1; idx <= array_size; ++idx) {
        cout << " " << idx;
    }
    cout << endl;
    return 0;
}

