// Process lines from a text file with buffer overflow detection
void processFileLines() {
    std::ifstream inputStream("data.txt");
    if (!inputStream) return;

    constexpr int BUFFER_CAPACITY = 256;
    char lineBuffer[BUFFER_CAPACITY];

    // Read lines until newline delimiter or buffer limit is reached
    while (inputStream.getline(lineBuffer, BUFFER_CAPACITY)) {
        std::cout << "Line content: " << lineBuffer << std::endl;
    }

    // Check for stream failure due to line exceeding buffer size
    if (inputStream.fail() && !inputStream.eof()) {
        std::cout << "WARNING: Encountered a line longer than the allocated buffer." << std::endl;
        // Reset stream state flags to allow further operations
        inputStream.clear();
    }
}

