          SetArgPointee<3>(reinterpret_cast<void*>(0x6000)),
          Return(ncclSuccess)));

  ON_CALL(*this, commDeregister(_, _)).WillByDefault(Return(ncclSuccess));

  // Default collective operations
  ON_CALL(*this, allReduce(_, _, _, _, _, _, _))
