std::vector<StringBox> internStrings(StringCache& stringCache, const std::vector<std::string>& inputStrings) {
    std::vector<StringBox> resultStrings;
    for (const auto& currentString : inputStrings) {
        resultStrings.emplace_back(stringCache.makeString(currentString));
    }
    return resultStrings;
}

std::default_random_engine rngEngine;
std::uniform_int_distribution<char> charRangeDistribution(' ', '~');
auto charGenerator = std::bind(charRangeDistribution, rngEngine);

std::string generateRandomString(size_t length) {
    std::string result;
    for (size_t index = 0; index < length; ++index) {
        result.push_back(charGenerator());
    }
    return result;
}

std::vector<std::string> generateRandomStringList(size_t length) {
    std::vector<std::string> result;
    for (int i = 0; i < 10; ++i) {
        result.emplace_back(generateRandomString(length));
