// Test guide track is laid crosswise the OSM road graph. It doesn't match the OSM roads so we
// can test route length, time and points number and it is enough to guarantee that the route
// built during the test is the route through the guide which we expect.
GuidesTracks GetTestGuides()
{
  // Guide with single track.
  GuidesTracks guides;
  guides[20] = {{{mercator::FromLatLon(48.13999, 11.56873), 20},
                 {mercator::FromLatLon(48.14096, 11.57246), 20},
                 {mercator::FromLatLon(48.14487, 11.57259), 20}}};
  return guides;
}

void TestGuideRoute(Checkpoints const & startPoints, double expectedDistanceM, double expectedDurationS,
                    size_t expectedWaypointCount)
{
  TRouteResult const routeOutcome = integration::CalculateRoute(
      integration::GetVehicleComponents(VehicleType::Pedestrian), startPoints, GetTestGuides());
  TEST_EQUAL(routeOutcome.second, RouterResultCode::NoError, ());
  integration::TestRouteLength(*routeOutcome.first, expectedDistanceM);
  integration::TestRouteTime(*routeOutcome.first, expectedDurationS);
  integration::TestRoutePointsNumber(*routeOutcome.first, expectedWaypointCount);
}

void ReverseCheckpoints(Checkpoints const & originalPoints)
{
  auto points = originalPoints.GetPoints();
  std::reverse(points.begin(), points.end());
}

// Start and finish checkpoints are connected to the track via single fake edge.
UNIT_TEST(Guides_TwoPointsOnTrack)
{
  // Checkpoints lie on the track.
  Checkpoints const waypoints{mercator::FromLatLon(48.14367, 11.57257), mercator::FromLatLon(48.13999, 11.56873)};
  double const targetDistM = 600.8;
  double const targetTimeS = 721.0;
  size_t const targetPointsCount = 7;
  TestGuideRoute(waypoints, targetDistM, targetTimeS, targetPointsCount);
  ReverseCheckpoints(waypoints);
  TestGuideRoute(waypoints, targetDistM, targetTimeS, targetPointsCount);
}

// One checkpoint is connected to the track projection via OSM,
// other checkpoint is connected to the track projection via single fake edge.
UNIT_TEST(Guides_TwoPointsOnTrackOneViaOsm)
{
  // Start is further from track then |kEqDistToTrackPointM|, but finish is closer.
  Checkpoints const waypoints{mercator::FromLatLon(48.13998, 11.56982), mercator::FromLatLon(48.14448, 11.57259)};
  double const targetDistM = 788.681;
  double const targetTimeS = 903.3;
  size_t const targetPointsCount = 13;
  TestGuideRoute(waypoints, targetDistM, targetTimeS, targetPointsCount);
  ReverseCheckpoints(waypoints);
  TestGuideRoute(waypoints, targetDistM, targetTimeS, targetPointsCount);
}

// Start checkpoint is far away from the track, finish checkpoint lies in meters from
// the middle of the track. We build the first part of the route from start to the terminal
// track point, second part - from the terminal point to the finish.
UNIT_TEST(Guides_FinishPointOnTrack)
{
  Checkpoints const waypoints{mercator::FromLatLon(48.1394659, 11.575924),
                              mercator::FromLatLon(48.1407632, 11.5716992)};
  TestGuideRoute(waypoints, 840.1 /* expectedDistM */, 736.279 /* expectedTimeS */, 37 /* expectedPointsCount */);
}

// Start checkpoint is on the track, finish checkpoint is far away. We build the first part of the
// route through the track and the second part - through the OSM roads.
UNIT_TEST(Guides_StartPointOnTrack)
{
  Checkpoints const waypoints{mercator::FromLatLon(48.14168, 11.57244), mercator::FromLatLon(48.13741, 11.56095)};
  TestGuideRoute(waypoints, 1200.45 /* expectedDistM */, 1056.45 /* expectedTimeS */, 52 /* expectedPointsCount */);
}

// Start and finish lie on the track; 3 intermediate points are far away from the track.
UNIT_TEST(Guides_MultipleIntermediatePoints)
{
  Checkpoints const waypoints({mercator::FromLatLon(48.14403, 11.57259), mercator::FromLatLon(48.14439, 11.57480),
                               mercator::FromLatLon(48.14192, 11.57548), mercator::FromLatLon(48.14106, 11.57279),
                               mercator::FromLatLon(48.14044, 11.57061)});
  TestGuideRoute(waypoints, 1231.91 /* expectedDistM */, 1042.65 /* expectedTimeS */, 67 /* expectedPointsCount */);
}
