// ============================================================================
// Python override helper for RenderPipelineCallback
// ============================================================================
class PyRenderPipelineCallback : public RenderPipelineCallback
{
  public:
    using RenderPipelineCallback::RenderPipelineCallback;

    void Execute(ScriptableRenderContext &ctx, const std::vector<Camera *> &cams) override
    {
        // Search for Python method named "execute" (matches Python style)
        PYBIND11_OVERRIDE_PURE_NAME(void, RenderPipelineCallback, "execute", Execute, &ctx, cams);
    }

    void Cleanup() override
    {
        PYBIND11_OVERRIDE_NAME(void, RenderPipelineCallback, "cleanup", Cleanup);
    }
};

// ============================================================================
// Binding registration logic
// ============================================================================
namespace infengine
{
void RegisterRenderPipelineBindings(py::module_ &mod)
{
    // ---- CullingResults ----
    py::class_<CullingResults>(mod, "CullingResults")
        .def_property_readonly("visible_object_count",
                               [](const CullingResults &self) { return self.visibleObjectCount(); })
        .def_property_readonly("visible_light_count",
                               [](const CullingResults &self) { return self.visibleLightCount(); });

    // ---- Camera is already registered in BindingScene.cpp as Camera(Component) ----
    // Avoid redundant binding here.

    // ---- ScriptableRenderContext ----
    py::class_<ScriptableRenderContext>(mod, "ScriptableRenderContext")
        .def_property_readonly("scene", &ScriptableRenderContext::GetScene, py::return_value_policy::reference,
                               "Access the scene bound to this rendering context")
        .def("configure_camera", &ScriptableRenderContext::SetupCameraProperties, py::arg("camera"),
             "Initialize camera view-projection matrices for rendering")
        .def("perform_culling", &ScriptableRenderContext::Cull, py::arg("camera"), 
             "Perform frustum culling on the scene; returns CullingResults")
        // RenderGraph-based API
        .def("load_graph", &ScriptableRenderContext::ApplyGraph, py::arg("graph_desc"),
             "Load a graph topology defined in Python into the render pipeline")
        .def("dispatch_culling", &ScriptableRenderContext::SubmitCulling, py::arg("cull_data"),
             "Submit all accumulated culling results as full draw calls (filtered by pass callbacks)")
        // Phase 2: CommandBuffer integration
        .def("run_command_buffer", &ScriptableRenderContext::ExecuteCommandBuffer, py::arg("buffer"),
             "Execute a queued CommandBuffer (commands are buffered until submission)")
        .def("fetch_render_target", &ScriptableRenderContext::GetCameraTarget, py::arg("camera"),
             "Retrieve the render target handle used for final camera output")
        // Phase 2: Global shader parameters (immediate mode)
        .def(
            "assign_global_texture",
            [](ScriptableRenderContext &self, const std::string &param_name, RenderTargetHandle tex_handle) {
                self.SetGlobalTexture(param_name, tex_handle);
            },
            py::arg("name"), py::arg("handle"), "Assign a global texture to a shader parameter")
        .def("assign_global_float", &ScriptableRenderContext::SetGlobalFloat, py::arg("name"), py::arg("val"),
             "Set a scalar float value for a shader parameter")
        .def("assign_global_vector", &ScriptableRenderContext::SetGlobalVector, py::arg("name"), py::arg("vx"),
             py::arg("vy"), py::arg("vz"), py::arg("vw"), "Set a vec4 vector for a shader parameter");

    // ---- RenderPipelineCallback (abstract base, extended via trampoline) ----
    py::class_<RenderPipelineCallback, PyRenderPipelineCallback, std::shared_ptr<RenderPipelineCallback>>(
        mod, "RenderPipelineCallback")
        .def(py::init<>())
        .def("execute", &RenderPipelineCallback::Execute, py::arg("context"), py::arg("cameras"),
             "Invoked once per frame to define the sequence of rendering passes")
        .def("cleanup", &RenderPipelineCallback::Cleanup, "Called when the pipeline is being destroyed");
}
} // namespace infengine

