// Verify fundamental boolean literals
void verify_boolean_literals(SMTParser::ParserPtr& parser) {
    std::cout << "=== Validating Boolean Literals ===" << std::endl;
    auto t = parser->mkExpr("true");
    assert(t && t->isTrue() && !t->isFalse());
    std::cout << "Expression: true" << std::endl;
    std::cout << "  Output: " << parser->toString(t) << std::endl;
    std::cout << "  isTrue: yes" << std::endl;
    std::cout << "  isFalse: no" << std::endl << std::endl;

    auto f = parser->mkExpr("false");
    assert(f && f->isFalse() && !f->isTrue());
    std::cout << "Expression: false" << std::endl;
    std::cout << "  Output: " << parser->toString(f) << std::endl;
    std::cout << "  isTrue: no" << std::endl;
    std::cout << "  isFalse: yes" << std::endl << std::endl;
}

// Evaluate logical operators (expected outcomes: true/false)
void evaluate_logical_operators(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, bool>> test_cases = {
        {"(not true)", false},
        {"(not false)", true},
        {"(and true true)", true},
        {"(and true false)", false},
        {"(and false false)", false},
        {"(or true true)", true},
        {"(or true false)", true},
        {"(or false false)", false},
        {"(=> true true)", true},
        {"(=> true false)", false},
        {"(=> false true)", true},
        {"(=> false false)", true},
        {"(xor true true)", false},
        {"(xor true false)", true},
        {"(xor false false)", false}
    };

    std::cout << "=== Assessing Logical Operators ===" << std::endl;
    for (const auto& item : test_cases) {
        std::cout << "Expression: " << item.first << std::endl;
        std::shared_ptr<SMTParser::DAGNode> evaluation = parser->mkExpr(item.first);
        assert(evaluation);
        assert(evaluation->isTrue() == item.second || evaluation->isFalse() == !item.second);
        std::cout << "  Output: " << parser->toString(evaluation) << std::endl;
        std::cout << std::endl;
    }
}

// Analyze intricate boolean formulas
void analyze_complex_formulas(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, bool>> scenarios = {
        {"(and (or true false) (not false))", true},
        {"(or (and true false) (not true))", false},
        {"(=> (or true false) (and true true))", true},
        {"(xor (not false) (and true false))", true},
        {"(and (=> true false) (or false true))", false},
        {"(not (and (or true false) (=> false true)))", false}
    };

    std::cout << "=== Examining Complex Boolean Formulas ===" << std::endl;
    for (const auto& scenario : scenarios) {
        std::cout << "Expression: " << scenario.first << std::endl;
        std::shared_ptr<SMTParser::DAGNode> outcome = parser->mkExpr(scenario.first);
        assert(outcome);
        assert(outcome->isTrue() == scenario.second || outcome->isFalse() == !scenario.second);
        std::cout << "  Output: " << parser->toString(outcome) << std::endl;
        std::cout << std::endl;
    }
}

int main() {
    std::cout << "======= Boolean Logic Evaluation Suite =======" << std::endl;

    SMTParser::ParserPtr parser = SMTParser::newParser();

    verify_boolean_literals(parser);
    evaluate_logical_operators(parser);
    analyze_complex_formulas(parser);

    return 0;
}

#include <iostream>
#include <vector>
#include <numeric>
#include <random>
#include <algorithm>

// Function to perform a query operation
int performQuery(int value) {
    std::cout << "? " << value << std::endl;
    int response;
    std::cin >> response;
    if (response == -1) {
        exit(0); // Terminate if judge signals error
    }
    return response;
}

// Function to output the final answer pair
void reportResult(int first, int second) {
    std::cout << "! " << first << " " << second << std::endl;
}

// Recursive function to solve the problem by partitioning elements
void process(std::vector<int>& items) {
    if (items.empty()) {
        return;
    }

    if (items.size() == 2) {
        reportResult(items[0], items[1]);
        return;
    }

    // Select a pivot element from the end of the vector
    int center = items.back();
    items.pop_back();

    // Query with the pivot element
    performQuery(center);

    std::vector<int> same_group;
    same_group.push_back(center);
    std::vector<int> diff_group;

    // Track how many distinct types are currently in the device
    int type_count = 1;

    // Partition remaining items based on whether they match the pivot group
    for (int item : items) {
        int new_type_count = performQuery(item);

        if (new_type_count == type_count) {
            // The type count didn't increase, meaning this item pairs with an existing one
            same_group.push_back(item);
        } else {
            // Type count increased, so this item belongs to another group
            diff_group.push_back(item);
            type_count = new_type_count;
        }
    }

    // Remove all elements of same_group from the device
    for (int item : same_group) {
        performQuery(item);
    }

    // Recursively process both groups
    process(same_group);
    process(diff_group);
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;
    if (n == 0) {
        return 0;
    }

    std::vector<int> all_items(2 * n);
    std::iota(all_items.begin(), all_items.end(), 1);

    // Shuffle to randomize pivot selection
    std::random_device rd;
    std::mt19937 gen(rd());
    std::shuffle(all_items.begin(), all_items.end(), gen);

    process(all_items);
    return 0;
}

#include <asio/ts/executor.hpp>
#include <asio/thread_pool.hpp>
#include <iostream>
#include <string>

using asio::bind_executor;
using asio::dispatch;
using asio::make_work_guard;
using asio::post;
using asio::thread_pool;

// Function to asynchronously read one line from input stream
template <typename Callback>
void async_read_line(std::istream& input_stream, Callback callback)
{
  // Create work guard for the callback's associated executor
  auto guard = make_work_guard(callback);

  // Schedule work to be done asynchronously
  post([input_stream, guard, callback=std::move(callback)]() mutable
      {
        std::string buffer;
        std::getline(input_stream, buffer);

        // Forward result to callback through executor
        dispatch(guard.get_executor(),
            [buffer=std::move(buffer), callback=std::move(callback)]() mutable
            {
              callback(std::move(buffer));
            });
      });
}

int main()
{
  thread_pool worker_pool;
  std::cout << "Input a line: ";
  async_read_line(std::cin,
      bind_executor(worker_pool, [](std::string data)
        {
          std::cout << "Received: " << data << "\n";
        }));
  worker_pool.join();
}

