namespace ap::application {

//-------------------------------------------------------------------------
/// @details
///		Setup the paths. This looks in the current directory and all the
///		way up to the root for the testdata and testdata/source directory
///		Once it is found, the rest of the paths are set to the dir
//-------------------------------------------------------------------------
Error setupPaths() {
    // Configure the paths
    config::paths() = testPath();
    // Create required directories
    if (auto err = config::paths().makePaths()) return err;
    // Log diagnostic information
    LOG(Test, "Executable   :", application::execPath());
    LOG(Test, "Arguments    :", application::cmdline());
    LOG(Test, "Test path    :", testPath());
    return {};
}

//-------------------------------------------------------------------------
/// @details
///		Main entry point -- configure the environment and invoke the
///		TestMain function to actually run the tests
//-------------------------------------------------------------------------
ErrorCode Main() {
    // Redirect default logging to test console
    ::engine::monitor::MonitorType.setValue("TestConsole");
    // Reinitialize options from command line
    ::ap::application::Options::get().init();
    // Initialize engine drivers
    auto initCode = engine::init();
    if (initCode) dev::fatality(_location, "Engine initialization failed", initCode);

    // Activate specific log levels
    log::enableLevel<true>(Lvl::Perf, Lvl::Dev);

    // Attempt path configuration
    if (auto err = setupPaths()) return err.code();

    // Handle Python execution if enabled
    if (engine::python::isPython()) {
        if (auto err = engine::python::execPython()) return err;
        return {};
    }

    // Handle Java execution if enabled
    if (auto err = engine::java::isJava()) {
        if (auto err = engine::java::execJava()) return err;
        return {};
    }

#if ROCKETRIDE_PLAT_LIN
    // Prevent execution under WSL1 due to known compatibility issues
    if (plat::isWsl1())
        dev::fatality(_location,
                      "Word DB does not work under WSL1: "
                      "https://github.com/microsoft/WSL/issues/902");
#endif

    // Apply test-specific configuration
    config::nodeId(false) = *NodeIdentifier;
    config::vars().add("NodeId", config::nodeId());

    // Parse command-line arguments into vector format
    std::vector<const Utf8Chr *> argVector;
    std::list<Text> argStorage;
    std::istringstream stream(TestParameters.val());
    Text token;

    while (stream >> token) {
        argStorage.push_front(token);
        argVector.push_back(&argStorage.front());
    }

    // Execute test suite
    auto result = TestMain(argVector);
    LOG(Test, "Test returning code", result);

    // Cleanup engine resources
    engine::deinit();
    return result;
}

