/// @brief Reboot machine using ACPI or via triple fault.
/// @return This function does not return on success.
Void ACPIFactoryInterface::Reboot() {
  asm volatile(
      ".intel_syntax noprefix; "
      "rt_reset_hardware:; "
      "cli; "
      "wait_input_empty:; "
      "in al,0x64; "
      "test al,2; "
      "jnz wait_input_empty; "
      "mov al,0xD1; "
      "out 0x64,al; "
      "wait_output_empty:; "
      "in al,0x64; "
      "test al,2; "
      "jnz wait_output_empty; "
      "mov al,0xFE; "
      "out 0x60,al; "
      "xor rax,rax; "
      "lidt [rax]; "
      "infinite_loop:; "
      "jmp infinite_loop; "
      ".att_syntax; ");
}
