std::atomic<bool> termination_flag(false);

void handleTerminationSignal(int sig) {
  spdlog::info("Termination signal received (code: {})...", sig);
  termination_flag = true;
}

void startService() {
  std::string listen_address("0.0.0.0:50051");
  QubitEngineServiceImpl handler;
  grpc::ServerBuilder builder;
  builder.AddListeningPort(listen_address, grpc::InsecureServerCredentials());
  builder.RegisterService(&handler);

  // CRITICAL: Initialize the reflection plugin
  // grpc::reflection::InitProtoReflectionServerBuilderPlugin();

  std::unique_ptr<grpc::Server> grpc_server(builder.BuildAndStart());

  spdlog::set_level(spdlog::level::debug);
  spdlog::set_pattern("[%Y-%m-%d %H:%M:%S.%e] [%^%l%$] [thread %t] %v");
  spdlog::info("QubitEngine (C++) listening on {}", listen_address);
  spdlog::info("QubitEngine v2 (Debug) - VisualizeCircuit enabled");

  // Start Prometheus Metrics Exposer
  QuantumMetrics::Instance().Start();

  // Register signals
  std::signal(SIGINT, handleTerminationSignal);
  std::signal(SIGTERM, handleTerminationSignal);

  // Wait loop
  while (!termination_flag) {
    std::this_thread::sleep_for(std::chrono::milliseconds(500));
  }

  spdlog::info("Stopping gRPC server...");
  grpc_server->Shutdown();
}

