int main(int argc, char **argv) {
#ifdef MPI_ENABLED
  // Initialize MPI
  MPI_Init(&argc, &argv);
  int my_rank;
  MPI_Comm_rank(MPI_COMM_WORLD, &my_rank);
  int total_ranks;
  MPI_Comm_size(MPI_COMM_WORLD, &total_ranks);

  if (my_rank == 0) {
    spdlog::info("MPI Initialized with size: {}", total_ranks);
    startService();
  } else {
    // Worker nodes wait for instructions (or just run loop if architected that
    // way) For now, let's just have rank 0 run the server and others wait or
    // exit. In a real distributed kernel, the server would dispatch commands to
    // workers. We'll keep them alive to receive MPI calls.

    // Go Scheduler Decoupling: C++ Worker nodes now poll Redis directly instead
    // of waiting on gRPC This removes the heavy 1,000-thread gRPC bottleneck
    // from Go completely.
    try {
      sw::redis::Redis redis("tcp://localhost:6379");
      spdlog::info("Worker Node {} connected to Redis.", my_rank);
      while (!termination_flag) {
        // MPI Probe for distributed tensor/networking (non-blocking)
        int flag = 0;
        MPI_Status status;
        MPI_Iprobe(MPI_ANY_SOURCE, MPI_ANY_TAG, MPI_COMM_WORLD, &flag, &status);
        if (flag) {
          // Handle incoming message when detected
        }

        // Blocking Pop from Queue with 1 second timeout
        auto job = redis.bzpopmax("queue:jobs", 1);
        if (job) {
          spdlog::info("Worker Node {} pulled job ID: {}", my_rank,
                       std::get<1>(*job));
          // executeJob(std::get<1>(*job)); // Hook into engine cleanly
        }
      }
    } catch (const sw::redis::Error &err) {
      spdlog::error("Redis Error: {}", err.what());
    }
  }
  MPI_Finalize();
#else
  // Single-node execution: The server still runs gRPC for development testing
  // But ideally, we should also spin a local polling thread here too.
  startService();
#endif
  return 0;
}

#include <vector>
#include <cmath>

class Solution {
public:
    int firstMissingPositive(std::vector<int>& values) {
        int size = values.size();

        // Normalize non-positive and out-of-range values
        for(int i = 0; i < size; i++) {
            if(values[i] <= 0 || values[i] > size + 1) {
                values[i] = size + 1;
            }
        }

        // Mark presence of numbers by negating corresponding indices
        for(int i = 0; i < size; i++) {
            int position = std::abs(values[i]);
            if(position >= 1 && position <= size) {
                values[position - 1] = -std::abs(values[position - 1]);
            }
        }

        // Find first positive index which indicates missing number
        for(int i = 0; i < size; i++) {
            if(values[i] > 0) {
                return i + 1;
            }
        }

        return size + 1;   
    }
};

