#include <vector>
#include <algorithm>

class Solution {
public:
    // Merge two sorted arrays into nums1
    void merge(std::vector<int>& firstArray, int size1, std::vector<int>& secondArray, int size2) {
        int totalSize1 = firstArray.size();
        int totalSize2 = secondArray.size();

        // Copy elements from secondArray to the end of valid elements in firstArray
        for(int index = 0; index < size2; index++) {
            firstArray[size1 + index] = secondArray[index];
        }

        // Sort the merged array
        std::sort(firstArray.begin(), firstArray.end());
        return;
    }
};

