namespace tpa {

// Entry point for performing pointer analysis on a semi-sparse program.
//
// The overall process is divided into two main stages:
//
// Stage 1: Global Setup
// Leverages GlobalPointerAnalysis to inspect the module and identify global variables and functions.
// Builds an initial Environment (Env) containing information about globals,
// and initializes the Store with results from processing global initializers.
//
// Stage 2: Iterative Data-Flow Computation
// Establishes the GlobalState (encapsulating read-only context like program structure, type info, etc.)
// and instantiates the DataFlowAnalysis engine. This engine operates using:
// - GlobalState: Immutable shared data (program representation, managers, etc.)
// - Memo: Cache for storing previously computed results
// - TransferFunction: Logic for interpreting individual CFG nodes
// - SemiSparsePropagator: Algorithm for exploring control flow and propagating state changes
//
// Execution continues until no further state updates occur (fixpoint reached).
void SemiSparsePointerAnalysis::runOnProgram(const SemiSparseProgram &ssProg) {
  LOG_INFO("Stage 1: Processing global pointers and initializers...");
  Store initStore;

  // Extract environment and store after analyzing global declarations
  std::tie(env, initStore) =
      GlobalPointerAnalysis(ptrManager, memManager, ssProg.getTypeMap())
          .runOnModule(ssProg.getModule());

  LOG_INFO("Global pointer analysis finished");
  LOG_INFO("Stage 2: Starting iterative data-flow computation...");

  // Prepare the global context object used during transfer function evaluation.
  // Note: 'env' is passed by reference and will be modified as analysis proceeds.
  GlobalState globalState(ptrManager, memManager, ssProg, extTable, env);

  // Instantiate the generic data-flow solver with our specialized components.
  util::DataFlowAnalysis<GlobalState, Memo, TransferFunction,
                         SemiSparsePropagator> dfa(globalState, memo);

  // Begin fixpoint iteration starting from the store built during global setup.
  dfa.runOnInitialState<Initializer>(std::move(initStore));

  LOG_INFO("Data-flow computation completed");
}

