// Function to discover words using query-based strategy with exponential search
void findWords() {
    int totalWords;
    if (!(cin >> totalWords)) return;

    // Set to store unique words discovered so far (automatically sorted)
    set<string> discovered;

    // Process each letter from 'a' to 'z'
    for (char startChar = 'a'; startChar <= 'z'; ++startChar) {
        // Early exit if we've already found all required words
        if (discovered.size() == totalWords) break;

        string prefix(1, startChar);
        int currentCount = 0;      // Words found for this prefix
        int queryBound = 1;        // Current upper bound for query size

        while (discovered.size() < totalWords) {
            // Double the bound if it's not larger than what we already have
            if (queryBound <= currentCount) {
                queryBound *= 2;
                continue;
            }

            // Compute how many words starting with this prefix could still exist
            int otherPrefixesCount = discovered.size() - currentCount;
            int maxPossibleForCurrent = totalWords - otherPrefixesCount;

            // Determine actual K value: min of bound and remaining capacity
            int requested = min(queryBound, maxPossibleForCurrent);

            // Ensure we request more than what we already know
            if (requested <= currentCount) {
                queryBound *= 2;
                continue;
            }

            cout << "request " << prefix << " " << requested << endl;
            int received;
            cin >> received;

            // Read the returned words
            for (int idx = 0; idx < received; ++idx) {
                string word;
                cin >> word;
                discovered.insert(word);
            }

            currentCount = received;

            // If fewer words returned than requested, no more words with this prefix
            if (received < requested) {
                break;
            }

            // Check global termination condition
            if (discovered.size() == totalWords) break;

            // Continue searching with larger bound
            queryBound *= 2;
        }
    }

    // Output final answer
    cout << "result";
    for (const auto& word : discovered) {
        cout << " " << word;
    }
    cout << endl;
}

int main() {
    int testCases;
    if (cin >> testCases) {
        while (testCases--) {
            findWords();
        }
    }
    return 0;
}

#include <vector>
#include <iostream>

class Solution {
public:
    // Precomputed array for exponential sums at powers of 4
    long long precomputedSums[18] = {1};

    // Calculate exponential sum for a given value x
    long long expSum(unsigned x) {
        if (x == 0) return 0;

        int powerIndex = (31 - __builtin_clz(x)) / 2;
        int remainder = x - (1 << (2 * powerIndex));

        return precomputedSums[powerIndex] + remainder * (powerIndex + 1LL);
    }

    long long minOperations(std::vector<std::vector<int>>& queries) {
        // Build precomputed sums array
        for (int i = 1; i < 18; i++) {
            precomputedSums[i] = precomputedSums[i-1] + (3LL * i * (1LL << (2 * (i-1)))) + 1;
        }

        long long totalOps = 0;
        for (auto& query : queries) {
            int leftBound = query[0] - 1;
            int rightBound = query[1];

            // Compute operations using the difference in exponential sums
            long long diff = expSum(rightBound) - expSum(leftBound);
            totalOps += (diff + 1) / 2;
        }

        return totalOps;
    }
};

