DwarfFile::DwarfFile(AsmPrinter *AP, StringRef Prefix, BumpPtrAllocator &DA)
    : Asm(AP), Abbrevs(AbbrevAllocator), StrPool(DA, *Asm, Prefix) {}

void DwarfFile::addCompilationUnit(std::unique_ptr<DwarfCompileUnit> U) {
  CompilationUnits.push_back(std::move(U));
}

// Output the dwarf compilation units into the designated section USection,
// with their abbreviations placed in ASection.
void DwarfFile::emitCompilationUnits(bool UseOffsets) {
  for (const auto &CU : CompilationUnits)
    emitCompilationUnit(CU.get(), UseOffsets);
}

void DwarfFile::emitCompilationUnit(DwarfUnit *TheU, bool UseOffsets) {
  if (TheU->getCUNode()->isDebugDirectivesOnly())
    return;

  MCSection *Section = TheU->getSection();
  if (!Section)
    return;

  // Omit CUs that are no longer required (e.g., split CUs that contributed
  // no additional data beyond the main CU)
  if (TheU->getUnitDie().values().empty())
    return;

  Asm->OutStreamer->switchSection(Section);
  TheU->emitHeader(UseOffsets);
  Asm->emitDwarfDIE(TheU->getUnitDie());
  if (MCSymbol *EndSym = TheU->getEndLabel())
    Asm->OutStreamer->emitLabel(EndSym);
}

// Determine size and offsets for all DIEs
void DwarfFile::computeSizeAndOffsets() {
  // Initial offset from the start of the debug info section is zero.
  uint64_t SectionOffset = 0;
  // Traverse each compile unit to assign sizes and offsets to its DIEs.
  // Offsets are relative to the start of each CU.
  for (const auto &CU : CompilationUnits) {
    if (CU->getCUNode()->isDebugDirectivesOnly())
      continue;
    // Skip CUs that ended up not being needed (split CUs that were abandoned
    // because they added no information beyond the non-split CU)
    if (CU->getUnitDie().values().empty())
      return;
    CU->setDebugSectionOffset(SectionOffset);
    SectionOffset += computeSizeAndOffsetsForUnit(CU.get());
  }
  if (SectionOffset > UINT32_MAX && !Asm->isDwarf64())
    report_fatal_error("The generated debug information is too large "
                       "for the 32-bit DWARF format.");
}

unsigned DwarfFile::computeSizeAndOffsetsForUnit(DwarfUnit *TheU) {
  // Reset offset relative to the start of the CU to zero.
  unsigned Offset = Asm->getUnitLengthFieldByteSize() + // Unit Length Field
                    TheU->getHeaderSize();              // CU-specific header size
  // Return value is CU-relative offset after processing the root DIE.
  return computeSizeAndOffset(TheU->getUnitDie(), Offset);
}

// Calculate size and offset for a single DIE. Offset is CU-relative.
// Returns the final offset after processing the DIE.
unsigned DwarfFile::computeSizeAndOffset(DIE &Die, unsigned Offset) {
  return Die.computeOffsetsAndAbbrevs(Asm->getDwarfFormParams(), Abbrevs,
                                      Offset);
}

void DwarfFile::emitAbbreviationTable(MCSection *Section) { 
  Abbrevs.Emit(Asm, Section); 
}

// Write string literals into the string section.
void DwarfFile::emitStringData(MCSection *StrSection, MCSection *OffsetSection,
                               bool UseRelativeOffsets) {
  StrPool.emit(*Asm, StrSection, OffsetSection, UseRelativeOffsets);
}

void DwarfFile::addScopeVariable(LexicalScope *LS, DbgVariable *Var) {
  auto &VarsInScope = ScopeVariables[LS];
  const DILocalVariable *DV = Var->getVariable();
  if (unsigned ArgIndex = DV->getArg()) {
    auto InsertResult = VarsInScope.Args.insert({ArgIndex, Var});
    assert(InsertResult.second);
    (void)InsertResult;
  } else {
    VarsInScope.Locals.push_back(Var);
  }
}

void DwarfFile::addScopeLabel(LexicalScope *LS, DbgLabel *Label) {
  SmallVectorImpl<DbgLabel *> &LabelsInScope = ScopeLabels[LS];
  LabelsInScope.push_back(Label);
}

std::pair<uint32_t, RangeSpanList *>
DwarfFile::addRange(const DwarfCompileUnit &CU, SmallVector<RangeSpan, 2> R) {
  CURangeLists.push_back(
      RangeSpanList{Asm->createTempSymbol("debug_ranges"), &CU, std::move(R)});
  return std::make_pair(CURangeLists.size() - 1, &CURangeLists.back());
}

