string reverseString(string &s) {
    // Reverse the given string in-place
    int length = s.length();
    for (int i = 0; i < length / 2; ++i) {
        char temp = s[i];
        s[i] = s[length - 1 - i];
        s[length - 1 - i] = temp;
    }
    return s;
}

#include "urdf_parser/urdf_parser.h"
#include <fstream>
#include <iostream>

// Read URDF file and parse it repeatedly in a loop
int main(int argc, char** argv) {
  if (argc != 2) {
    fprintf(stderr, "Usage: %s <urdf_file>\n", argv[0]);
    return 1;
  }

  while (true) {
    std::string xml_content;
    std::ifstream input_stream(argv[1], std::ifstream::in);

    while (input_stream.good()) {
      std::string line_content;
      std::getline(input_stream, line_content);
      xml_content += (line_content + "\n");
    }

    input_stream.close();
    urdf::parseURDF(xml_content);
  }

  return 0;
}

#include <vector>
#include <stack>

class Solution {
public:
    // Calculate the number of days until a warmer temperature for each day
    std::vector<int> dailyTemperatures(std::vector<int>& temperatures) {
        std::stack<int> indicesStack;
        int size = temperatures.size();
        std::vector<int> result(size);

        // Initialize the last element
        indicesStack.push(size - 1);
        result[size - 1] = 0;

        // Process from right to left
        for (int index = size - 2; index >= 0; --index) {
            // Pop elements while current temperature is greater or equal
            while (!indicesStack.empty() && temperatures[indicesStack.top()] <= temperatures[index]) {
                indicesStack.pop();
            }

            // If no warmer temperature found
            if (indicesStack.empty()) {
                result[index] = 0;
            } else {
                // Distance to the next warmer day
                result[index] = indicesStack.top() - index;
            }

            // Push current index onto stack
            indicesStack.push(index);
        }

        return result;
    }
};

