void log_start(bool is_overlay_mode) {
    const char *log_path = is_overlay_mode ? "advancely_overlay_log.txt" : "advancely_log.txt";

    // Open log file in write mode to reset contents on each launch
    log_handle = fopen(log_path, "w");
    if (log_handle == nullptr) {
        fprintf(stderr, "CRITICAL: Unable to open log file advancely_log.txt\n");
        return;
    }

    // Insert timestamp at beginning of log
    time_t current_time = time(nullptr);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&current_time));

    // Select appropriate header depending on process type
    const char* header_text = is_overlay_mode ?
                              "Advancely Overlay Log - %s\n" :
                              "Advancely Log - %s\n";

    fprintf(log_handle, header_text, timestamp);
    fprintf(log_handle, "========================================\n\n");
    fflush(log_handle); // Force immediate write of header
}

void log_write(LogLevel severity, const char *fmt, ...) {
    // Skip informational messages unless debug output is enabled
    if (severity == LOG_INFO && (g_config == nullptr || !g_config->print_debug_status)) {
        return;
    }

    // Storage for formatted message
    char buffer[4096];
    va_list arg_list;

    // Construct the final message string
    va_start(arg_list, fmt);
    vsnprintf(buffer, sizeof(buffer), fmt, arg_list);
    va_end(arg_list);

    // Output to console with optional color formatting
    if (severity == LOG_ERROR) {
#ifdef _WIN32
        HANDLE console_handle = GetStdHandle(STD_ERROR_HANDLE);
        CONSOLE_SCREEN_BUFFER_INFO info;
        WORD original_color;

        GetConsoleScreenBufferInfo(console_handle, &info);
        original_color = info.wAttributes;

        SetConsoleTextAttribute(console_handle, FOREGROUND_RED | FOREGROUND_INTENSITY);
        fprintf(stderr, "%s", buffer);

        SetConsoleTextAttribute(console_handle, original_color);
#else
        fprintf(stderr, "\033[91m%s\033[0m", buffer);
#endif
    } else {
        printf("%s", buffer);
    }

    // Also record to persistent log file if available
    if (log_handle != nullptr) {
        char time_str[16];
        time_t now = time(nullptr);
        strftime(time_str, sizeof(time_str), "%H:%M:%S", localtime(&now));
        fprintf(log_handle, "[%s] %s", time_str, buffer);
        fflush(log_handle); // Keep log up-to-date in case of failure
    }
}

void log_shutdown(void) {
    if (log_handle != nullptr) {
        fprintf(log_handle, "\n========================================\n");
        fprintf(log_handle, "Session ended.\n");
        fclose(log_handle);
        log_handle = nullptr;
    }
}

