// Modified active object implementation for bank account operations
class financial_account
{
  int current_balance_ = 0;
  mutable thread_pool worker_pool_{1};
public:
  void credit(int value)
  {
    post(worker_pool_, [=]
      {
        current_balance_ += value;
      });
  }
  void debit(int value)
  {
    post(worker_pool_, [=]
      {
        if (current_balance_ >= value)
          current_balance_ -= value;
      });
  }
  void display_status() const
  {
    post(worker_pool_, [=]
      {
        std::cout << "account balance = " << current_balance_ << "\n";
      });
  }
  ~financial_account()
  {
    worker_pool_.join();
  }
};

int main()
{
  financial_account my_acct;
  my_acct.credit(20);
  my_acct.debit(10);
  my_acct.display_status();
}

#include "Alias/TPA/Context/Context.h"
#include "Alias/TPA/Context/ProgramPoint.h"
using namespace llvm;

namespace context {

// Adds a new context frame to the top of the current context stack.
// This overload accepts a ProgramPoint, and internally extracts the context and instruction.
const Context *Context::pushContext(const ProgramPoint &pp) {
  return pushContext(pp.getContext(), pp.getInstruction());
}

// Adds a new context frame to the stack.
// Parameters:
//   callerCtx - The context of the calling function (parent context).
//   callInst  - The call instruction that triggered this context change.
// Returns: A pointer to the canonical (interned) Context instance representing the updated state.
const Context *Context::pushContext(const Context *callerCtx,
                                    const Instruction *callInst) {
  // Construct a temporary context object for lookup/insertion
  auto tempCtx = Context(callInst, callerCtx);
  // Attempt insertion into the interned set; iterator points to existing or newly inserted element
  auto iter = ctxSet.insert(tempCtx).first;
  return &(*iter);
}

// Removes the topmost context frame from the stack.
// Returns the preceding (caller's) context.
const Context *Context::popContext(const Context *currCtx) {
  assert(currCtx->size != 0 && "Attempted to pop from an empty context stack");
  return currCtx->prevContext;
}

// Provides access to the unique global context object.
// Used when analyzing global variables or the function entry point.
const Context *Context::getGlobalContext() {
  auto iter = ctxSet.insert(Context()).first;
  return &(*iter);
}

// Utility function returning all contexts created so far.
// Helpful for diagnostics, testing, or reporting analysis statistics.
std::vector<const Context *> Context::getAllContexts() {
  std::vector<const Context *> result;
  result.reserve(ctxSet.size());
  for (auto const &ctx : ctxSet)
    result.push_back(&ctx);
  return result;
}

} // namespace context

#include "BufferedOutputStream.h"
#include "util/console/ArrayWithLength.h"
#include "win/extraX64.h"

// Constructs a buffered output stream that wraps the given output stream,
// using a buffer of the specified size.
// Parameters: out - the target output stream. size - the internal buffer capacity.
BufferedOutputStream::BufferedOutputStream(OutputStream* out, int bufferSize) {
    targetStream = out;
    buffer       = byteArray(bufferSize);
    currentCount = 0;
}

BufferedOutputStream::~BufferedOutputStream() { 
    delete buffer.data; 
}

// Ensures all buffered data is written to the underlying stream and resets the buffer index.
void BufferedOutputStream::flush() {
    targetStream->write(buffer, 0, currentCount);
    currentCount = 0;
}

// Finalizes the stream by flushing remaining data and closing the underlying stream.
void BufferedOutputStream::close() {
    flush();
    targetStream->close();
}

// Writes a sequence of bytes from an array to the buffered stream.
// If the requested length exceeds or equals the buffer capacity, the buffer is flushed
// and data is written directly to the underlying stream to avoid unnecessary copying.
//
// Parameters:
//   data      - source byte array
//   startIndex - starting position in the array
//   byteCount  - number of bytes to write
void BufferedOutputStream::write(
    byteArray    data,
    unsigned int startIndex,
    unsigned int byteCount
) {
    // If the write request is larger than our buffer, bypass buffering entirely
    if (byteCount >= buffer.length) {
        flush();
        targetStream->write(data, startIndex, byteCount);
    } else {
        for (unsigned int idx = 0; idx < byteCount; idx++) {
            write(data[startIndex + idx]);
        }
    }
}

// Convenience method: writes an entire byte array to the stream.
void BufferedOutputStream::write(byteArray data) { 
    write(data, 0, data.length); 
}

// Writes a single byte to the buffer.
// When the buffer becomes full, it is automatically flushed.
void BufferedOutputStream::write(unsigned int value) {
    buffer[currentCount++] = (byte)value;
    if (currentCount == buffer.length) {
        flush();
    }
}

