// A function that uses assertions not only for unit testing but also to enforce preconditions in production code
static void validate_conditions() {
    CHECK_EQ(true, false);
    CHECK_UNARY(false);
    CHECK_UNARY_FALSE(true);
    CHECK(false);
    CHECK_THROWS(std::cout << "hello! \n");
