#include <iostream>
#include <vector>
using namespace std;

// Maximum size for the answer array
const int MAX_SIZE = 200005;
int result[MAX_SIZE];

// Recursive divide-and-conquer function to determine elements in range [left, right]
// Key insight: if a query returns frequency equal to range length, all elements are identical.
// Otherwise, split and recurse. With at most k distinct values, total queries ~ O(k log(n/k)).
void reconstruct(int left, int right) {
    if (left > right) return;

    // Ask interactive query about subarray [left, right]
    cout << "? " << left << " " << right << endl;

    int modeValue, frequency;
    cin >> modeValue >> frequency;

    // Handle error condition from judge
    if (modeValue == -1) exit(0);

    // If all elements in range are the same
    if (frequency == right - left + 1) {
        for (int idx = left; idx <= right; ++idx) {
            result[idx] = modeValue;
        }
        return;
    }

    // Split the range and process both halves
    int center = (left + right) / 2;
    reconstruct(left, center);
    reconstruct(center + 1, right);
}

int main() {
    // Speed up I/O for interactive problems
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (cin >> n) {
        // Begin reconstruction on full array
        reconstruct(1, n);

        // Output final answer
        cout << "! ";
        for (int i = 1; i <= n; ++i) {
            cout << result[i];
            if (i < n) cout << " ";
        }
        cout << endl;
    }

    return 0;
}

