class network_pinger
{
public:
  network_pinger(asio::io_context& ctx, const char* target_host)
    : resolver_(ctx), socket_(ctx, icmp::v4()),
      timer_(ctx), seq_num_(0), reply_count_(0)
  {
    destination_ = *resolver_.resolve(icmp::v4(), target_host, "").begin();
    initiate_send();
    initiate_receive();
  }

private:
  void initiate_send()
  {
    std::string payload("\"Hello!\" from Asio ping.");

    // Build ICMP echo request header
    icmp_header request;
    request.type(icmp_header::echo_request);
    request.code(0);
    request.identifier(get_identifier());
    request.sequence_number(++seq_num_);
    compute_checksum(request, payload.begin(), payload.end());

    // Prepare packet buffer
    asio::streambuf packet_buffer;
    std::ostream os(&packet_buffer);
    os << request << payload;

    // Send packet and set timeout
    send_timestamp_ = steady_timer::clock_type::now();
    socket_.send_to(packet_buffer.data(), destination_);

    // Configure timeout for response
    reply_count_ = 0;
    timer_.expires_at(send_timestamp_ + chrono::seconds(5));
    timer_.async_wait(boost::bind(&network_pinger::on_timeout, this));
  }

  void on_timeout()
  {
    if (reply_count_ == 0)
      std::cout << "Request timed out" << std::endl;

    // Enforce minimum delay between requests
    timer_.expires_at(send_timestamp_ + chrono::seconds(1));
    timer_.async_wait(boost::bind(&network_pinger::initiate_send, this));
  }

  void initiate_receive()
  {
    // Clear any existing data in receive buffer
    response_buffer_.consume(response_buffer_.size());

    // Prepare buffer for incoming data (up to 64KB)
    socket_.async_receive(response_buffer_.prepare(65536),
        boost::bind(&network_pinger::on_packet_arrival, this, _2));
  }

  void on_packet_arrival(std::size_t bytes_received)
  {
    // Commit received bytes to buffer for reading
    response_buffer_.commit(bytes_received);

    // Parse packet headers
    std::istream is(&response_buffer_);
    ipv4_header ip_header;
    icmp_header icmp_header;
    is >> ip_header >> icmp_header;

    // Validate: correct type, matching ID and sequence number
    if (is && icmp_header.type() == icmp_header::echo_reply
          && icmp_header.identifier() == get_identifier()
          && icmp_header.sequence_number() == seq_num_)
    {
      // Cancel timeout on first successful reply
      if (reply_count_++ == 0)
        timer_.cancel();

      // Calculate and display round-trip time
      chrono::steady_clock::time_point current_time = chrono::steady_clock::now();
      auto duration = current_time - send_timestamp_;

      std::cout << bytes_received - ip_header.header_length()
        << " bytes from " << ip_header.source_address()
        << ": icmp_seq=" << icmp_header.sequence_number()
        << ", ttl=" << ip_header.time_to_live()
        << ", time="
        << chrono::duration_cast<chrono::milliseconds>(duration).count()
        << " ms" << std::endl;
    }

    // Continue listening for packets
    initiate_receive();
  }

  static unsigned short get_identifier()
  {
#if defined(ASIO_WINDOWS)
    return static_cast<unsigned short>(::GetCurrentProcessId());
#else
    return static_cast<unsigned short>(::getpid());
#endif
  }

  icmp::resolver resolver_;
  icmp::endpoint destination_;
  icmp::socket socket_;
  steady_timer timer_;
  unsigned short seq_num_;
  chrono::steady_clock::time_point send_timestamp_;
  asio::streambuf response_buffer_;
  std::size_t reply_count_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: ping <host>" << std::endl;
#if !defined(ASIO_WINDOWS)
      std::cerr << "(You may need to run this program as root.)" << std::endl;
#endif
      return 1;
    }

    asio::io_context context;
    network_pinger pinger(context, argv[1]);
    context.run();
  }
  catch (std::exception& e)
  {
    std::cerr << "Exception: " << e.what() << std::endl;
  }
}

