// Generate a label string for the plot legend based on parameters
std::string generate_legend_label (double slope, double shift)
{
    namespace uc = mplot::unicode;
    std::stringstream slope_txt;
    if (slope != 1.0) { slope_txt << slope; }

    std::stringstream paren_open;
    std::stringstream paren_close;

    if (shift != 0.0) {
        paren_open << "(";
        if (shift > 0.0) {
            paren_close << " - " << shift << ")";
        } else {
            paren_close << " + " << -shift << ")";
        }
    }

    std::stringstream eqn_str;
    eqn_str << "k=" << slope << ", x" << uc::toUtf8(uc::subs0) << "=" << shift;
    eqn_str << ": f(x) = 1 / [1 + exp (-" << slope_txt.str() 
            << paren_open.str() << "x" << paren_close.str() << ")]";
    return eqn_str.str();
}

int main()
{
    // Initialize a mplot::Visual environment with specified dimensions and title
    mplot::Visual scene(1280, 960, "Sigmoidal Functions");

    // Create a GraphVisual object at offset (-0.5, -0.5, 0.0)
    auto graph_view = std::make_unique<mplot::GraphVisual<double>> (sm::vec<float>({-0.5f,-0.5f,0.0f}));
    scene.bindmodel(graph_view);

    // Prepare x-axis data using vvec (vectorized vector with math operations)
    sm::vvec<double> x_vals;
    x_vals.linspace(-100, 30, 250);  // from -100 to 30 with 250 points

    // Add multiple logistic/sigmoid curves with different parameters
    graph_view->setdata(x_vals, x_vals.logistic(0.15, -8), generate_legend_label(0.15, -8));

    // Use in-place modification for one curve
    sm::vvec<double> y_transformed = x_vals;
    y_transformed.logistic_inplace(0.3, -4);
    graph_view->setdata(x_vals, y_transformed, generate_legend_label(0.3, -4));

    graph_view->setdata(x_vals, x_vals.logistic(0.6, 0), generate_legend_label(0.6, 0));
    graph_view->setdata(x_vals, x_vals.logistic(1.2, 6), generate_legend_label(1.2, 6));
    graph_view->setdata(x_vals, x_vals.logistic(2.5, 12), generate_legend_label(2.5, 12));

    // Finalize graph geometry before rendering
    graph_view->finalize();

    // Transfer ownership of the graph model to the visual scene
    scene.addVisualModel(graph_view);

    // Keep window open until user exits (Ctrl-q)
    scene.keepOpen();
    return 0;
}

#include <iostream>

// Function to query a range and obtain the response
int query(int left, int right) {
    std::cout << "? " << left << " " << right << std::endl;
    int response;
    std::cin >> response;
    return response;
}

void process() {
    int size;
    std::cin >> size;

    // Step 1: Locate reference element (position of 'size-1')
    // and decide whether 'size' lies left or right of it.
    int ref = query(1, size);
    int low, high;
    bool ref_on_left;

    if (ref < size && query(ref, size) == ref) {
        // 'size' resides in [ref+1, size], so reference is on the left side
        low = ref + 1;
        high = size;
        ref_on_left = true;
    } else {
        // 'size' resides in [1, ref-1], so reference is on the right side
        low = 1;
        high = ref - 1;
        ref_on_left = false;
    }

    // Step 2: Perform binary search to pinpoint position of 'size'
    while (low < high) {
        int mid = low + (high - low) / 2;

        if (ref_on_left) {
            // Reference is left of current segment. Check if 'size' is in [low, mid].
            // Query [ref, mid] includes 'size' iff target is within [low, mid]
            if (query(ref, mid) == ref) {
                high = mid;
            } else {
                low = mid + 1;
            }
        } else {
            // Reference is right of current segment. Check if 'size' is in [mid+1, high].
            // Query [mid+1, ref] includes 'size' iff target is within [mid+1, high]
            if (query(mid + 1, ref) == ref) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
    }

    std::cout << "! " << low << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    while (test_cases--) {
        process();
    }

    return 0;
}

