// Tile Accelerator (TA) state machine for PowerVR2 (Dreamcast) emulation
// Manages DMA and Store Queue operations, routes polygon/vertex/control parameters
namespace TASplitter
{
    // Pointer to the current command handler in the state machine
    TaListFP* ActiveTaCmd = nullptr;
}
using namespace TASplitter;

// Store Queue path: single 32-byte write (e.g., through SQ registers)
void libPvr_TaSQ(u32* buffer)
{
    verify(ActiveTaCmd != nullptr);
    Ta_Dma* entry = (Ta_Dma*)buffer;
    ActiveTaCmd(entry, entry);
}

// DMA path: process a contiguous block of 32-byte TA entries
// 'length' specifies the number of Ta_Dma elements (each 32 bytes), not bytes
void libPvr_TaDMA(u32* buffer, u32 length)
{
    verify(ActiveTaCmd != nullptr);
    verify(length > 0);
    Ta_Dma* current_entry   = (Ta_Dma*)buffer;
    Ta_Dma* last_entry      = current_entry + length - 1;
    do
    {
        current_entry = ActiveTaCmd(current_entry, last_entry);
    }
    while (current_entry <= last_entry);
}

