// Recursive factorial implementation with base cases
int computeFactorial(const int value) {
    return value < 1 ? 1 : value <= 1 ? value : computeFactorial(value - 1) * value;
}

// Test suite for factorial function verification
TEST_CASE("validating the factorial computation") {
    CHECK(computeFactorial(0) == 1);
    CHECK(computeFactorial(1) == 1);
    CHECK(computeFactorial(2) == 2);
    CHECK(computeFactorial(3) == 6);
    CHECK(computeFactorial(10) == 3628800);
}

