using namespace lbug::binder;

namespace lbug {
namespace planner {

f_group_pos_set LogicalOrderBy::getGroupsPosToFlatten() {
    // We only allow ordering by keys that are unflattened if they belong to a single factorization group
    // and no other factorized groups exist in the schema. This ensures the input and output schemas
    // maintain the same factorization structure.
    // Rationale: (1) Preserve schema consistency across the operator; (2) Avoid explicit flattening
    // when possible to prevent falling back to tuple-at-a-time processing. In simple cases, we can
    // sort directly on unflat vectors within one data chunk/group. Complex scenarios (e.g., multiple
    // factorization groups) require flattening since FactorizedTable cannot materialize flat results
    // into unflat vectors.
    auto parentSchema = children[0]->getSchema();
    if (parentSchema->getNumGroups() > 1) {
        return FlattenAll::getGroupsPosToFlatten(expressionsToOrderBy, *parentSchema);
    }
    return f_group_pos_set{};
}

void LogicalOrderBy::computeFactorizedSchema() {
    resetSchema();
    auto parentSchema = children[0]->getSchema();
    SinkOperatorUtil::recomputeSchema(*parentSchema, parentSchema->getExpressionsInScope(), *schema);
}

void LogicalOrderBy::computeFlatSchema() {
    resetSchema();
    schema->createGroup();
    for (auto& expr : children[0]->getSchema()->getExpressionsInScope()) {
        schema->insertToGroupAndScope(expr, 0);
    }
}

std::string LogicalOrderBy::getExpressionsForPrinting() const {
    auto result = ExpressionUtil::toString(expressionsToOrderBy) + " ";
    if (hasSkipNum() && ExpressionUtil::canEvaluateAsLiteral(*skipNum)) {
        result += "SKIP " + std::to_string(ExpressionUtil::evaluateAsSkipLimit(*skipNum));
    }
    if (hasLimitNum() && ExpressionUtil::canEvaluateAsLiteral(*limitNum)) {
        result += "LIMIT " + std::to_string(ExpressionUtil::evaluateAsSkipLimit(*limitNum));
    }
    return result;
}

