#include <engLib/eng.h>
namespace engine::store::filter::filesys::base {
//-------------------------------------------------------------------------
/// @details
///		Determines whether the stored object has been modified. This is 
///		done by comparing timestamps and other metadata against the current
///		state of the file system. If any discrepancies are found, the 
///		entry.markChanged<> method should be invoked, and all affected 
///		fields in the entry must be updated accordingly.
///	@param[inout] targetEntry
///		The entry to inspect and potentially update
///	@returns
///		Error status indicating success or failure
//-------------------------------------------------------------------------
template <log::Lvl LvlT>
Error IBaseSysInstance<LvlT>::checkChanged(Entry &targetEntry) noexcept {
    Error errCode;
    // Acquire the OS-specific path
    Text osFilePath;
    if (errCode = Url::osPath(targetEntry.url(), osFilePath)) return errCode;

    auto statResult = ap::file::stat(osFilePath, true);
    if (!statResult) return statResult.ccode();

    auto fileStat = _mv(*statResult);

    // Assume no change initially
    targetEntry.changed(false);

    // Compare creation time
    if (targetEntry.createTime.get() != fileStat.createTime) {
        targetEntry.markChanged(LogLevel, "Creation time mismatch");
        targetEntry.createTime(fileStat.createTime);
    }

    // Compare access time (update but do not mark as changed)
    if (targetEntry.accessTime.get() != fileStat.accessTime) {
        targetEntry.accessTime(fileStat.accessTime);
    }

    // Compare modification time
    if (targetEntry.modifyTime.get() != fileStat.modifyTime) {
        targetEntry.markChanged(LogLevel, "Modification time mismatch");
        targetEntry.modifyTime(fileStat.modifyTime);
    }

    // Compare file attributes (may want to restrict to specific flags)
    if (targetEntry.attrib() != fileStat.plat.st_mode) {
        targetEntry.markChanged(LogLevel, "File attributes have changed");
        targetEntry.attrib(fileStat.plat.st_mode);
    }

    // Compare logical file size
    if (targetEntry.size() != fileStat.size) {
        targetEntry.markChanged(LogLevel, "File size differs");
        targetEntry.size(fileStat.size);
    }

    // Compare physical space used on disk
    if (targetEntry.storeSize() != fileStat.sizeOnDisk) {
        targetEntry.markChanged(LogLevel, "Disk space usage differs");
        targetEntry.storeSize(fileStat.sizeOnDisk);
    }

    return {};
}
}  // namespace engine::store::filter::filesys::base

