#include <apLib/ap.h>
#include <intrin.h>

namespace ap::plat {

std::array<uint32_t, 4> CpuInfo::cpuid(int functionId) noexcept {
    // Use __cpuidex instead of __cpuid to preserve ECX register contents
    std::array<int, 4> registers;
    __cpuidex(registers.data(), functionId, 0);

    std::array<uint32_t, 4> result = {};
    for (size_t idx = 0; idx < registers.size(); ++idx) {
        result[idx] = static_cast<uint32_t>(registers[idx]);
    }
    return result;
}

uint32_t CpuInfo::cpuidMax() noexcept {
    // Invoke __cpuid with leaf 0x0 to determine the maximum supported CPUID leaf
    std::array<int, 4> cpuRegs;
    __cpuid(cpuRegs.data(), 0);
    return static_cast<uint32_t>(cpuRegs[0]);
}

uint32_t CpuInfo::cpuidExMax() noexcept {
    // Invoke __cpuid with extended leaf 0x80000000 to get highest extended function number
    std::array<int, 4> extRegs;
    __cpuid(extRegs.data(), 0x80000000);
    return static_cast<uint32_t>(extRegs[0]);
}

}  // namespace ap::plat

