#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    // Grid dimensions
    int rows = 20;
    int cols = 20;

    // Output grid size
    cout << rows << " " << cols << endl;

    // Initialize grid with '0' (walls)
    vector<string> maze(rows, string(cols, '0'));

    // Build a "snake" layout to maximize path length.
    // Horizontal paths are placed on even-numbered rows (0, 2, ..., 18).
    // Vertical connectors are inserted in odd rows (1, 3, ..., 17).

    // Create horizontal corridors on even rows
    for (int r = 0; r <= 18; r += 2) {
        for (int c = 0; c < cols; ++c) {
            maze[r][c] = '1';
        }
    }

    // Insert vertical connectors between consecutive corridors
    // Alternate connection points: right side for first pair, left side for next, etc.
    for (int r = 0; r < 18; r += 2) {
        if ((r / 2) % 2 == 0) {
            // Even corridor index: connect at the rightmost column
            maze[r + 1][cols - 1] = '1';
        } else {
            // Odd corridor index: connect at the leftmost column
            maze[r + 1][0] = '1';
        }
    }

    // Add "teeth" (dead-end branches) from the last corridor row (row 18)
    // to utilize remaining space while preserving tree structure (no cycles)
    // Place teeth only at even column indices to avoid adjacency
    for (int c = 0; c < cols; c += 2) {
        maze[rows - 1][c] = '1';
    }

    // Display the final grid
    for (int i = 0; i < rows; ++i) {
        cout << maze[i] << endl;
    }
    return 0;
}

