	void SanitizeFilenameFormat(FString& InOutFilenameFormatString, const bool bCheckRenderPass, const bool bCheckFrameNumber)
	{
		const FString FrameTokenIdentifiers[] = { TEXT("{frame_number}"), TEXT("{frame_number_shot}"), TEXT("{frame_number_rel}"), TEXT("{frame_number_shot_rel}") };

		// If multiple files are generated per frame, ensure unique naming
		if (bCheckRenderPass)
		{
			if (!InOutFilenameFormatString.Contains(TEXT("{render_pass}"), ESearchCase::IgnoreCase))
			{
				UE_LOG(LogMovieRenderPipeline, Warning, TEXT("Multiple render passes exported but no {render_pass} format found. Automatically adding!"));

				// Locate a frame number token in the output string
				int32 TokenPosition = INDEX_NONE;
				for (const FString& Token : FrameTokenIdentifiers)
				{
					TokenPosition = InOutFilenameFormatString.Find(Token, ESearchCase::IgnoreCase, ESearchDir::FromEnd);
					if (TokenPosition != INDEX_NONE)
					{
						break;
					}
				}

				if (TokenPosition == INDEX_NONE)
				{
					// No frame token found, append render_pass at the end
					InOutFilenameFormatString += TEXT("{render_pass}");
				}
				else
				{
					// Insert render_pass just before the frame token to preserve sequence recognition
					InOutFilenameFormatString.InsertAt(TokenPosition, TEXT("{render_pass}."));
				}
			}
		}

		if (bCheckFrameNumber)
		{
			// Verify presence of a frame identifier for unique file naming in sequences
			int32 FrameTokenIndex = INDEX_NONE;
			for (const FString& Token : FrameTokenIdentifiers)
			{
				FrameTokenIndex = InOutFilenameFormatString.Find(Token, ESearchCase::IgnoreCase, ESearchDir::FromEnd);
				if (FrameTokenIndex != INDEX_NONE)
				{
					break;
				}
			}

			// Insert {file_dup} before the frame token if present
			if (FrameTokenIndex == INDEX_NONE)
			{
				// User did not specify a frame identifier — warn about potential overwrites
				UE_LOG(LogMovieRenderPipeline, Warning, TEXT("Frame number identifier not found. Files may be overwritten."));
			}
			else
			{
				// Prepend {file_dup} before the existing frame token
				InOutFilenameFormatString.InsertAt(FrameTokenIndex, TEXT("{file_dup}"));
			}
		}

		// Ensure {file_dup} is always present for duplicate handling
		if (!InOutFilenameFormatString.Contains(TEXT("{file_dup}"), ESearchCase::IgnoreCase))
		{
			InOutFilenameFormatString.Append(TEXT("{file_dup}"));
		}
	}

	void StripFrameTokens(FString& InOutFilenameFormatString, const bool bRemoveShotFrames)
	{
		// Remove frame-related tokens to prevent per-frame output files
		InOutFilenameFormatString.ReplaceInline(TEXT("{frame_number}"), TEXT(""));
		InOutFilenameFormatString.ReplaceInline(TEXT("{frame_number_rel}"), TEXT(""));

		if (bRemoveShotFrames)
		{
			InOutFilenameFormatString.ReplaceInline(TEXT("{frame_number_shot}"), TEXT(""));
			InOutFilenameFormatString.ReplaceInline(TEXT("{frame_number_shot_rel}"), TEXT(""));
		}
	}
}
