#include "ByteArrayOutputStream.h"
#include <cassert>
#include <cstddef>
#include <type_traits>
#include "util/console/ArrayWithLength.h"
#include "win/extraX64.h"

// Creates a new byte array output stream. The buffer capacity starts at 32 bytes,
// expanding as needed.
ByteArrayOutputStream::ByteArrayOutputStream() {
    writtenCount = 0;
    buffer       = byteArray(32);
}

// Creates a new byte array output stream with an initial buffer of the given size.
ByteArrayOutputStream::ByteArrayOutputStream(unsigned int initialSize) {
    writtenCount = 0;
    buffer       = byteArray(initialSize);
}

ByteArrayOutputStream::~ByteArrayOutputStream() {
    if (buffer.data != nullptr) delete[] buffer.data;
}

// Writes a single byte to the stream.
void ByteArrayOutputStream::write(unsigned int value) {
    // Expand buffer if necessary
    if (writtenCount + 1 >= buffer.length) buffer.resize(buffer.length * 2);
    buffer[writtenCount] = static_cast<byte>(value);
    ++writtenCount;
}

// Writes all bytes from the provided array.
void ByteArrayOutputStream::write(byteArray source) { 
    write(source, 0, source.length); 
}

// Writes a specified number of bytes from the source array, starting at offset.
void ByteArrayOutputStream::write(
    byteArray    source,
    unsigned int startIndex,
    unsigned int countToWrite
) {
    assert(source.length >= startIndex + countToWrite);

    // Ensure sufficient buffer space
    if (writtenCount + countToWrite >= buffer.length)
        buffer.resize(std::max(writtenCount + countToWrite + 1, buffer.length * 2));

    XMemCpy(&buffer[writtenCount], &source[startIndex], countToWrite);
    writtenCount += countToWrite;
}

// No-op: closing this stream has no effect.
void ByteArrayOutputStream::close() {}

// Returns a copy of the current contents of the stream as a new byte array.
byteArray ByteArrayOutputStream::toByteArray() {
    byteArray result(writtenCount);
    memcpy(result.data, buffer.data, writtenCount);
    return result;
}

#include "EntityIDRebaser.h"
#include "BioAssert.h"

using namespace db;

EntityIDRebaser::EntityIDRebaser() = default;
EntityIDRebaser::~EntityIDRebaser() = default;
EntityIDRebaser::EntityIDRebaser(const EntityIDRebaser& other) = default;
EntityIDRebaser& EntityIDRebaser::operator=(const EntityIDRebaser& other) = default;
EntityIDRebaser::EntityIDRebaser(EntityIDRebaser&& other) noexcept = default;
EntityIDRebaser& EntityIDRebaser::operator=(EntityIDRebaser&& other) noexcept = default;

// When a @ref Change makes local commits, it assigns NodeIDs based on its own view
// of what the next available ID should be. This view is fixed at the moment the 
// Change branches off from the main branch. As time passes and other Changes submit,
// new nodes may be introduced via NodeID injection (e.g., using CREATE statements).
// For instance:
// @code
// CREATE (n:NEWNODE) <- Node created in this Change
// COMMIT             <- NEWNODE gets assigned ID 7
// CREATE (n @ 7)-[e:NEWEDGE]-(m:NEWNODE) <- Edge referencing node 7
// @endcode
// If another Change submitted to main after our branch point but before ours, 
// node ID 7 might already exist on main. Without rebasing, our edge would end up 
// connecting unintended nodes. To prevent this, we compare:
// 1. The nextNodeID on main when our Change was created (_branchTimeNextNodeID)
// 2. The current nextNodeID on main (_newNextNodeID)
// If they differ, we adjust all locally-created IDs (those >= _branchTimeNextNodeID)
// by the difference.
NodeID EntityIDRebaser::rebaseNodeID(NodeID original) const {
    bioassert(_branchTimeNextNodeID <= _newNextNodeID, "invalid _branchTimeNextNodeID");
    return original >= _branchTimeNextNodeID ? original + _newNextNodeID - _branchTimeNextNodeID
                                             : original;
}

EdgeID EntityIDRebaser::rebaseEdgeID(EdgeID original) const {
    bioassert(_branchTimeNextEdgeID <= _newNextEdgeID, "invalid _branchTimeNextEdgeID");
    return original >= _branchTimeNextEdgeID ? original + _newNextEdgeID - _branchTimeNextEdgeID
                                             : original;
}

