    // Execute a test command asynchronously
    QFuture<command_streams> future_result =
        komander->call_bk_future("list", QVariantMap{}, QStringList{});

    QFutureWatcher<command_streams> status_watcher;
    QEventLoop event_loop;

    QObject::connect(&status_watcher, &QFutureWatcher<command_streams>::finished,
                    &event_loop, &QEventLoop::quit);

    status_watcher.setFuture(future_result);
    event_loop.exec();

    command_streams results = future_result.result();

    DEBUG_LOG("Command execution completed without blocking.");

    std::cout << "--- Output (stdout) ---" << std::endl;
    std::cout << results.stdout_str << std::endl;

    std::cout << "--- Errors (stderr) ---" << std::endl;
    std::cout << results.stderr_str << std::endl;

    return 0;
}

