#include <sol/sol.hpp>
#include <iostream>

int custom_error_handler(lua_State* L,
     sol::optional<const std::exception&> maybe_ex,
     sol::string_view msg) {
	// L is the lua state, which you can wrap in a state_view if
	// necessary maybe_ex will contain exception, if it
	// exists msg will either be the what() of the
	// exception or a description saying that we hit the
	// general-case catch(...)
	std::cout << "An error occurred during script execution: ";
	if (maybe_ex) {
		std::cout << "(from the exception object): ";
		const std::exception& ex = *maybe_ex;
		std::cout << ex.what() << std::endl;
	}
	else {
		std::cout << "(from the message parameter): ";
		std::cout.write(msg.data(),
		     static_cast<std::streamsize>(msg.size()));
		std::cout << std::endl;
	}
	// you must push 1 element onto the stack to be
	// transported through as the error object in Lua
	// note that Lua -- and 99.5% of all Lua users and libraries
	// -- expects a string so we push a single string (in our
	// case, the description of the error)
	return sol::stack::push(L, msg);
}

void trigger_error() {
	throw std::runtime_error("unexpected failure detected!!!");
}

int main() {
	std::cout << "=== error_handling_demo ===" << std::endl;
	sol::state vm;
	vm.open_libraries(sol::lib::base);
	vm.set_exception_handler(&custom_error_handler);
	vm.set_function("trigger_error", &trigger_error);
	sol::protected_function_result res = vm.safe_script(
	     "trigger_error()", &sol::script_pass_on_error);
	SOL_ASSERT(!res.valid());
	sol::error exception = res;
	std::cout << exception.what() << std::endl;
	std::cout << std::endl;
	return 0;
}

#include <stack>
#include <string>

class Solution {
public:
    bool checkValidParentheses(std::string str) {
        int length = str.length();
        if (length % 2 != 0) return false;

        std::stack<char> stack;
        for (char &ch : str) {
            if (ch == '{' || ch == '[' || ch == '(') {
                stack.push(ch);
            } else {
                if (stack.empty()) return false;
                if ((stack.top() == '{' && ch == '}') ||
                    (stack.top() == '[' && ch == ']') ||
                    (stack.top() == '(' && ch == ')')) {
                    stack.pop();
                } else {
                    return false;
                }
            }
        }
        return stack.empty();
    }
};

#include <iostream>

// Similar rules apply to classes, unions, enums, etc. - const-qualification behaves consistently across all types
struct B {};

void g1(B obj);
void g2(const B obj);
void g3(B& reference);
void g4(const B& reference);
void g5(B* pointer);
void g6(const B* pointer);

void g1(B obj) {
    g1(obj); // valid (recursive call)
    g2(obj); // valid
    g3(obj); // valid
    g4(obj); // valid
    g5(&obj); // valid
    g6(&obj); // valid
}

void g2(const B obj) {
    g1(obj); // valid
    g2(obj); // valid (recursive call)
    g3(obj); // compile-time error (g3 may modify obj)
    g4(obj); // valid
    g5(&obj); // compile-time error (g5 may modify obj via pointer)
    g6(&obj); // valid
}

void g3(B& reference) {
    g1(reference); // valid
    g2(reference); // valid
    g3(reference); // valid (recursive call)
    g4(reference); // valid
    g5(&reference); // valid
    g6(&reference); // valid
}

void g4(const B& reference) {
    g1(reference); // valid
    g2(reference); // valid
    g3(reference); // compile-time error (g3 may modify reference)
    g4(reference); // valid (recursive call)
    g5(&reference); // compile-time error (g5 may modify reference via pointer)
    g6(&reference); // valid
}

void g5(B* pointer) {
    g1(*pointer); // valid
    g2(*pointer); // valid
    g3(*pointer); // valid
    g4(*pointer); // valid
    g5(pointer); // valid (recursive call)
    g6(pointer); // valid
}

void g6(const B* pointer) {
    g1(*pointer); // valid
    g2(*pointer); // valid
    g3(*pointer); // compile-time error (g3 may modify the pointee)
    g4(*pointer); // valid
    g5(pointer); // compile-time error (g5 may modify pointer itself or pointee)
    g6(pointer); // valid (recursive call)
}

