#include <karm/macros>
export module Karm.Core:base.scopeguard;
import :meta.nocopy;
import :base.base;

namespace Karm {

/// Execute a function when exiting the current scope.
/// Multiple guards are invoked in reverse order of creation.
export template <typename Func>
struct ScopeGuard : Meta::Pinned {
    Func _action;
    always_inline ScopeGuard(Func action) : _action(action) {}
    always_inline ~ScopeGuard() {
        _action();
    }
};

export template <typename Func>
ScopeGuard(Func) -> ScopeGuard<Func>;

/// A scope guard that can be manually disabled or triggered early.
/// The action runs only if the guard is still armed at destruction.
export template <typename Func>
struct DismissibleGuard : Meta::NoCopy {
    Func _action;
    bool _isActive = true;

    always_inline DismissibleGuard(Func action) : _action(action) {}

    always_inline ~DismissibleGuard() {
        if (_isActive)
            _action();
    }

    always_inline void cancel() {
        _isActive = false;
    }

    always_inline void activate() {
        _isActive = true;
    }

    always_inline void triggerNow() {
        if (_isActive) {
            _action();
        }
        cancel();
    }
};

export template <typename Func>
DismissibleGuard(Func) -> DismissibleGuard<Func>;

} // namespace Karm

