#include <iostream>
#include <boost/array.hpp>
#include <asio.hpp>

using asio::ip::tcp;

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: client <host>" << std::endl;
      return 1;
    }

    asio::io_context ioc;
    tcp::resolver res(ioc);
    tcp::resolver::results_type server_endpoints =
      res.resolve(argv[1], "daytime");

    tcp::socket sock(ioc);
    asio::connect(sock, server_endpoints);

    for (;;)
    {
      boost::array<char, 256> buffer;
      asio::error_code ec;
      size_t bytes_transferred = sock.read_some(asio::buffer(buffer), ec);

      if (ec == asio::error::eof)
        break; // Connection closed cleanly by peer.
      else if (ec)
        throw asio::system_error(ec); // Some other error.

      std::cout.write(buffer.data(), bytes_transferred);
    }
  }
  catch (std::exception& err)
  {
    std::cerr << err.what() << std::endl;
  }

  return 0;
}

