using asio::post;
using asio::thread_pool;
using asio::use_future;

// Modified active object pattern implementation
class bank_account
{
  int current_balance_ = 0;
  mutable thread_pool worker_pool_{1};
public:
  void credit(int amount)
  {
    post(worker_pool_,
      use_future([=]
        {
          current_balance_ += amount;
        })).get();
  }
  void debit(int amount)
  {
    post(worker_pool_,
      use_future([=]
        {
          if (current_balance_ >= amount)
            current_balance_ -= amount;
        })).get();
  }
  int get_balance() const
  {
    return post(worker_pool_,
      use_future([=]
        {
          return current_balance_;
        })).get();
  }
};

int main()
{
  bank_account account;
  account.credit(20);
  account.debit(10);
  std::cout << "account balance = " << account.get_balance() << "\n";
}

