// Function to determine which items are demagnetized
void process_case() {
    int size;
    std::cin >> size;

    int suspect = -1;
    // Find the first index where interaction is non-zero
    for (int idx = 2; idx <= size; ++idx) {
        std::cout << "? 1 " << idx - 1 << std::endl;
        std::cout << idx << std::endl;

        for (int j = 1; j < idx; ++j) {
            std::cout << j << (j == idx - 1 ? "" : " ");
        }
        std::cout << std::endl;
        std::cout.flush();

        int response;
        std::cin >> response;
        if (response != 0) {
            suspect = idx;
            break;
        }
    }

    std::vector<int> result;

    // Binary search to find the specific magnetized item in range [1, suspect-1]
    int left = 1, right = suspect - 1;
    while (left < right) {
        int middle = left + (right - left) / 2;
        int count = middle - left + 1;

        std::cout << "? 1 " << count << std::endl;
        std::cout << suspect << std::endl;

        for (int i = left; i <= middle; ++i) {
            std::cout << i << (i == middle ? "" : " ");
        }
        std::cout << std::endl;
        std::cout.flush();

        int check;
        std::cin >> check;
        if (check != 0) {
            right = middle;
        } else {
            left = middle + 1;
        }
    }

    int magnetized_index = left;

    // Collect all items except the magnetized one in range [1, suspect-1]
    for (int i = 1; i < suspect; ++i) {
        if (i != magnetized_index) {
            result.push_back(i);
        }
    }

    // Check remaining items from suspect+1 to size
    for (int item = suspect + 1; item <= size; ++item) {
        std::cout << "? 1 1" << std::endl;
        std::cout << magnetized_index << std::endl;
        std::cout << item << std::endl;
        std::cout.flush();

        int measurement;
        std::cin >> measurement;
        if (measurement == 0) {
            result.push_back(item);
        }
    }

    // Output the result
    std::cout << "! " << result.size();
    for (int val : result) {
        std::cout << " " << val;
    }
    std::cout << std::endl;
    std::cout.flush();
}

