#include <iostream>
#include <fstream>
#include <string>
#include <vector>

int main(int argc, char* argv[]) {
    std::string rootPath = "";
    bool all_passed = true;
    std::cout << "Initiating diagnostic read for .ans files in " << rootPath << std::endl;
    for (int index = 1; index <= 10; ++index) {
        std::string filepath = rootPath + std::to_string(index) + ".ans";
        std::cout << "\n--- Processing file: " << filepath << " ---" << std::endl;
        std::ifstream input(filepath);
        if (!input.is_open()) {
            std::cerr << "  [ERROR] Unable to open the file. It may not exist." << std::endl;
            all_passed = false;
            continue;
        }
        // Verify if the file is empty
        if (input.peek() == std::ifstream::traits_type::eof()) {
            std::cerr << "  [ERROR] File has no content and is completely empty." << std::endl;
            all_passed = false;
            input.close();
            continue;
        }
        std::vector<std::pair<int, int>> dataPairs;
        int row, col;
        while (input >> row >> col) {
            dataPairs.emplace_back(row, col);
        }
        // After the loop, determine why iteration stopped
        if (input.eof()) {
            // Expected case: reached end of file naturally.
            if (dataPairs.empty()) {
                std::cerr << "  [WARNING] File was opened but held no valid integer pairs." << std::endl;
            } else {
                std::cout << "  [SUCCESS] Parsed " << dataPairs.size() << " integer pairs successfully." << std::endl;
            }
        } else if (input.fail()) {
            // Problematic case: parsing halted due to invalid format.
            std::cerr << "  [ERROR] Parsing interrupted. File likely contains non-integer or malformed data." << std::endl;
            all_passed = false;
        }
        input.close();
    }
    std::cout << "\n--- Final Report ---" << std::endl;
    if (all_passed) {
        std::cout << "All processed .ans files were read without issues." << std::endl;
    } else {
        std::cout << "One or more .ans files encountered errors during reading. Check the logs above." << std::endl;
    }
    return 0;
}

