// Determine if the array is sorted in non-decreasing order starting from a given position
bool checkSorted(const vector<int>& data, int pos) {
    // Base case: if we've reached the last element, the array is sorted up to this point
    if (pos == data.size() - 1) {
        return true;
    }
    // Check if current element is greater than the next one
    if (data[pos] > data[pos + 1]) {
        return false; // Violation of sorting order found
    }
    // Continue checking the remaining elements recursively
    return checkSorted(data, pos + 1);
}

int main() {
    vector<int> numbers = {2, 4, 6, 8, 10}; // Modify this to test different arrays
    if (checkSorted(numbers, 0)) {
        cout << "The sequence is in ascending order." << endl;
    } else {
        cout << "The sequence is not in ascending order." << endl;
    }
    return 0;
}

#include <iostream>
#include <cmath>

// Recursively computes the sequence of moves for the Tower of Hanoi puzzle
// disks: count of disks to transfer
// start: initial peg number
// end: target peg number
// temp: auxiliary peg number
void hanoi(int disks, int start, int end, int temp) {
    if (disks == 0) {
        return;
    }

    // First phase: transfer top (disks-1) from start to temp peg
    hanoi(disks - 1, start, temp, end);

    // Second phase: move the largest disk from start to end
    std::cout << start << " " << end << "\n";

    // Third phase: move (disks-1) disks from temp to end peg
    hanoi(disks - 1, temp, end, start);
}

int main() {
    // Optimize input/output operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int diskCount;
    std::cin >> diskCount;

    // Calculate minimum moves required: 2^diskCount - 1
    // Using 1LL promotes calculation to 64-bit to avoid overflow
    long long totalMoves = (1LL << diskCount) - 1;

    std::cout << totalMoves << "\n";

    // Only output individual moves when there are disks to move
    if (diskCount > 0) {
        hanoi(diskCount, 1, 3, 2);
    }

    return 0;
}

