COMPILER_RT_ABI fp_t __addtf3(fp_t a, fp_t b);
// Perform subtraction by inverting the sign bit of operand b and performing addition
COMPILER_RT_ABI fp_t __subtf3(fp_t a, fp_t b) {
  return __addtf3(a, fromRep(toRep(b) ^ (1ULL << (sizeof(fp_t) * 8 - 1))));
}
