using grpc::Server;
using grpc::ServerBuilder;
using grpc::ServerContext;
using grpc::Status;
using test_service_package::IntRequest;
using test_service_package::IntReply;
using test_service_package::Decompositor;
using namespace std::chrono_literals;

namespace 
{
  std::unique_ptr<Server> gActiveServer;
  auto gTimeoutDuration = 15s;
}

// Implementation of the Decompositor service
class DecompositionServiceImpl final : public Decompositor::Service 
{

  Status Decompose(ServerContext* context, 
                   const IntRequest* request,
                   IntReply* reply) override {
    int target_value = request->value();
    std::vector<int> parts;

    while (target_value != 0)
    {
      std::random_device seed_generator;  
      std::mt19937 random_engine(seed_generator());
      std::uniform_int_distribution<> distribution(1, target_value);
      int random_part = distribution(random_engine);
      parts.push_back(random_part);
      target_value -= random_part;
    }

    std::string result_string;
    for(auto part : parts)
    {
      result_string += std::to_string(part) + " ";
    }

    result_string += " = ";

    reply->set_message(result_string + std::to_string(request->value()));

    return Status::OK;
  }
};

void start_grpc_server() {
  std::string server_endpoint("0.0.0.0:50051");
  DecompositionServiceImpl service_instance;
  ServerBuilder builder;

  builder.AddListeningPort(server_endpoint, grpc::InsecureServerCredentials());
  builder.RegisterService(&service_instance);

  gActiveServer = builder.BuildAndStart();
  std::cout << "gRPC server started and listening on " << server_endpoint << std::endl;

  gActiveServer->Wait();
}

void shutdown_server_after_timeout()
{
  std::this_thread::sleep_for(gTimeoutDuration);
  std::cout << "Initiating server shutdown after " << gTimeoutDuration.count() << " seconds" << std::endl;
  gActiveServer->Shutdown(); 
}

int main(int argc, char** argv) {

  std::thread background_thread(shutdown_server_after_timeout);
  start_grpc_server();
  background_thread.join();
  return 0;
}

