int main() {
    std::cout << "=== FetchContent UniConv Demonstration ===" << std::endl;

    try {
        // Retrieve the singleton instance of UniConv
        auto converter = UniConv::GetInstance();

        // Perform encoding conversion tests
        std::string input_text = "Hello UniConv! Sample text containing only ASCII characters.";
        std::cout << "Input UTF-8 string: " << input_text << std::endl;

        // Convert from UTF-8 to GBK using optimized API
        auto gbk_output = converter->ConvertEncodingFast(input_text, "UTF-8", "GBK");
        if (!gbk_output.IsSuccess()) {
            std::cout << "FAILURE: Conversion to GBK encountered an error: " << gbk_output.GetErrorMessage() << std::endl;
            return 1;
        }
        std::cout << "Successfully converted to GBK; size: " << gbk_output.GetValue().size() << " bytes" << std::endl;

        // Revert back to UTF-8
        auto utf8_back = converter->ConvertEncodingFast(gbk_output.GetValue(), "GBK", "UTF-8");
        if (!utf8_back.IsSuccess()) {
            std::cout << "FAILURE: Conversion back to UTF-8 failed: " << utf8_back.GetErrorMessage() << std::endl;
            return 1;
        }
        std::cout << "Reconverted to UTF-8: " << utf8_back.GetValue() << std::endl;

        // Validate that round-trip conversion preserved original content
        if (input_text == utf8_back.GetValue()) {
            std::cout << "VERIFIED: Round-trip encoding conversion completed without data loss!" << std::endl;
        } else {
            std::cout << "FAILURE: Round-trip conversion mismatch detected" << std::endl;
            std::cout << "Original: '" << input_text << "'" << std::endl;
            std::cout << "Recovered: '" << utf8_back.GetValue() << "'" << std::endl;
            return 1;
        }

        // Attempt system codepage identification
        auto sys_codepage = converter->GetSystemCodePageFast();
        if (sys_codepage.IsSuccess()) {
            std::cout << "Detected system codepage: " << sys_codepage.GetValue() << std::endl;
        } else {
            std::cout << "Notice: System codepage detection failed: " << sys_codepage.GetErrorMessage() << std::endl;
        }

        std::cout << std::endl << "=== FetchContent Integration Verification Passed! ===" << std::endl;
        std::cout << "UniConv has been successfully incorporated as a subproject using FetchContent" << std::endl;

    } catch (const std::exception& ex) {
        std::cerr << "Exception occurred: " << ex.what() << std::endl;
        return 1;
    }

    return 0;
}

#include <iostream>
// Enable optional load/save functionality for HexGrid
#define HEXGRID_COMPILE_LOAD_AND_SAVE 1
#include <sm/hexgrid>
#include <sm/vec>
#include <mplot/ReadCurves.h>
#include <mplot/tools.h>
#include <mplot/ColourMap.h>
#include <mplot/Visual.h>
#include <mplot/HexGridVisual.h>

int main() {
    int exitCode = 0;
    std::size_t hexCount = 0;

    std::cout << "Initializing at " << mplot::tools::timeNow() << std::endl;

    try {
        // Generate hexagonal grid from SVG path
        std::string currentDir = mplot::tools::getPwd();
        std::string svgInputPath = "../../tests/trial.svg";

        mplot::ReadCurves curveReader(svgInputPath);
        sm::hexgrid grid(0.01, 3, 0);
        grid.setBoundary(curveReader.getCorticalPath());

        std::cout << "Grid extent: " << grid.extent() << std::endl;
        hexCount = grid.num();
        std::cout << "Total hexagons: " << grid.num() << std::endl;
        std::cout << "Last vector index: " << grid.lastVectorIndex() << std::endl;

        grid.save("../trialhexgrid.h5");
    } catch (const std::exception& ex) {
        std::cerr << "Error during grid generation: " << ex.what() << std::endl;
        std::cerr << "Working directory: " << mplot::tools::getPwd() << std::endl;
        exitCode = -1;
    }

    std::cout << "Generation complete at " << mplot::tools::timeNow() << std::endl;

    // Load saved grid and visualize
    try {
        sm::hexgrid loadedGrid("../trialhexgrid.h5");
        std::cout << "Loaded grid at " << mplot::tools::timeNow() << std::endl;

        if (hexCount != loadedGrid.num()) {
            exitCode = -1;
        }

        // Setup visualization window
        mplot::Visual viewer(1600, 1000, "hexgrid");
        viewer.lightingEffects();

        sm::vec<float, 3> translation = { 0.0f, 0.0f, 0.0f };
        auto hexVis = std::make_unique<mplot::HexGridVisual<float>>(&loadedGrid, translation);

        viewer.bindmodel(hexVis);

        // Prepare color data based on hex state flags
        std::vector<float> hexColors(loadedGrid.num(), 0.0f);
        static constexpr float COLOR_BOUNDARY_INSIDE = 0.9f;
        static constexpr float COLOR_ONLY_BOUNDARY = 0.8f;
        static constexpr float COLOR_DOMAIN_INTERIOR = 0.5f;
        static constexpr float COLOR_INSIDE_ONLY = 0.15f;

        if (loadedGrid.d_flags.size() < loadedGrid.num()) {
            throw std::runtime_error("Flag array d_flags not initialized properly");
        }

        for (std::size_t idx = 0; idx < loadedGrid.num(); ++idx) {
            bool isBoundary = (loadedGrid.d_flags[idx] & HEX_IS_BOUNDARY) != 0;
            bool isInterior = (loadedGrid.d_flags[idx] & HEX_INSIDE_BOUNDARY) != 0;

            if (isBoundary && isInterior) {
                hexColors[idx] = COLOR_BOUNDARY_INSIDE;   // red
            } else if (isBoundary) {
                hexColors[idx] = COLOR_ONLY_BOUNDARY;     // orange
            } else if (isInterior) {
                hexColors[idx] = COLOR_INSIDE_ONLY;       // blue
            } else {
                hexColors[idx] = COLOR_DOMAIN_INTERIOR;   // greenish
            }
        }

        hexVis->cm.setType(mplot::ColourMapType::Jet);
        hexVis->zScale.null_scaling(); // Flat z-output, but retains coloring
        hexVis->setScalarData(&hexColors);
        hexVis->hexVisMode = mplot::HexVisMode::HexInterp; // Smooth interpolation

        hexVis->finalize();
        viewer.addVisualModel(hexVis);

        // Render loop
        while (!viewer.readyToFinish()) {
            glfwWaitEventsTimeout(0.018);
            viewer.render();
        }

    } catch (const std::exception& ex) {
        std::cerr << "Error during visualization: " << ex.what() << std::endl;
        std::cerr << "Working directory: " << mplot::tools::getPwd() << std::endl;
        exitCode = -1;
    }

    return exitCode;
}

