#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    // Speed up input/output operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int size;
    if (!(cin >> size)) return 0;

    // Prepare array with 1-based indexing
    vector<int> arr(size + 1);
    for (int idx = 1; idx <= size; ++idx) {
        cin >> arr[idx];
    }

    // Fixed pivot value: choose k = 3
    // This yields reversal segments of length k-1=2 and k+1=4
    // Length 2 reversals swap adjacent elements (step size 1)
    // Length 4 reversals shift endpoints by 3 positions (step size 3)
    cout << 3 << "\n";

    vector<pair<int, int>> operations;

    // Lambda to record and apply a reversal operation
    auto apply_reverse = [&](int left, int right) {
        operations.emplace_back(left, right);
        reverse(arr.begin() + left, arr.begin() + right + 1);
    };

    // Greedy sorting using two-pointer technique
    // Maintain the unsorted segment [start, end]
    int start = 1, end = size;
    while (start < end) {
        int posMin = -1, posMax = -1;

        // Locate current indices of values 'start' and 'end'
        for (int j = 1; j <= size; ++j) {
            if (arr[j] == start) posMin = j;
            if (arr[j] == end) posMax = j;
        }

        // Compute distances to target positions
        int distToStart = posMin - start;
        int distToEnd = end - posMax;

        // Decide which element to move based on fewer required moves
        if (distToStart <= distToEnd) {
            // Bring 'start' value to its correct position at index 'start'
            int current = posMin;
            while (current > start) {
                if (current - 3 >= start) {
                    // Use length-4 reversal to jump back by 3 positions
                    apply_reverse(current - 3, current);
                    current -= 3;
                } else {
                    // Fall back to length-2 reversal for single-step movement
                    apply_reverse(current - 1, current);
                    current -= 1;
                }
            }
            start++;
        } else {
            // Move 'end' value to its final position at index 'end'
            int current = posMax;
            while (current < end) {
                if (current + 3 <= end) {
                    // Apply length-4 reversal to advance by 3 positions
                    apply_reverse(current, current + 3);
                    current += 3;
                } else {
                    // Use length-2 reversal for one-step advancement
                    apply_reverse(current, current + 1);
                    current += 1;
                }
            }
            end--;
        }
    }

    // Output number of operations followed by each operation
    cout << operations.size() << "\n";
    for (const auto& op : operations) {
        cout << op.first << " " << op.second << "\n";
    }

    return 0;
}

#include "WinCFGuard.h"
#include "llvm/CodeGen/AsmPrinter.h"
#include "llvm/CodeGen/MachineFunction.h"
#include "llvm/CodeGen/MachineModuleInfo.h"
#include "llvm/IR/Constants.h"
#include "llvm/IR/InstrTypes.h"
#include "llvm/MC/MCObjectFileInfo.h"
#include "llvm/MC/MCStreamer.h"
#include <vector>

using namespace llvm;

// Constructor for WinCFGuard class
WinCFGuard::WinCFGuard(AsmPrinter *printer) : Asm(printer) {}

// Destructor
WinCFGuard::~WinCFGuard() = default;

// Process end of function: collect longjmp targets if present
void WinCFGuard::endFunction(const MachineFunction *func) {
  // Skip if no longjmp targets exist in this function
  if (func->getLongjmpTargets().empty())
    return;

  // Append current function's longjmp targets to module-wide list
  LongjmpTargets.insert(LongjmpTargets.end(),
                        func->getLongjmpTargets().begin(),
                        func->getLongjmpTargets().end());
}

/// Determine whether the given function may be invoked indirectly.
/// Checks all uses of the function (and its casts) to detect escapes that could
/// lead to indirect calls. Skips block addresses and direct calls with matching prototypes.
static bool mightBeIndirectCallTarget(const Function *F) {
  SmallVector<const Value *, 4> workList{F};
  while (!workList.empty()) {
    const Value *current = workList.pop_back_val();
    for (const Use &U : current->uses()) {
      const User *user = U.getUser();
      if (isa<BlockAddress>(user))
        continue;
      if (const auto *call = dyn_cast<CallBase>(user)) {
        if (!call->isCallee(&U))
          return true;
      } else if (isa<Instruction>(user)) {
        // Any other instruction usage counts as escape
        return true;
      } else if (const auto *constant = dyn_cast<Constant>(user)) {
        // If it's a pointer cast of the original function, continue analyzing
        if (constant->stripPointerCasts() == F)
          workList.push_back(constant);
        else
          return true; // Other constants imply escape
      }
    }
  }
  return false;
}

// Look up the corresponding "__imp_" symbol for a given symbol, if applicable
MCSymbol *WinCFGuard::lookupImpSymbol(const MCSymbol *sym) {
  if (sym->getName().starts_with("__imp_"))
    return nullptr;
  return Asm->OutContext.lookupSymbol(Twine("__imp_") + sym->getName());
}

// Finalize module-level control flow guard data structures
void WinCFGuard::endModule() {
  const Module *module = Asm->MMI->getModule();
  std::vector<const MCSymbol *> gfidsSymbols;
  std::vector<const MCSymbol *> giatsSymbols;

  // Traverse all functions in the module
  for (const Function &func : *module) {
    if (mightBeIndirectCallTarget(&func)) {
      // For dllimport functions, add their __imp_ symbol to .giats if available
      if (func.hasDLLImportStorageClass()) {
        if (MCSymbol *impSym = lookupImpSymbol(Asm->getSymbol(&func))) {
          giatsSymbols.push_back(impSym);
        }
      }
      // Always add the function's own symbol to .gfids
      gfidsSymbols.push_back(Asm->getSymbol(&func));
    }
  }

  // Early exit if no entries needed
  if (gfidsSymbols.empty() && giatsSymbols.empty() && LongjmpTargets.empty())
    return;

  auto &stream = *Asm->OutStreamer;

  // Emit .gfids section
  stream.switchSection(Asm->OutContext.getObjectFileInfo()->getGFIDsSection());
  for (const MCSymbol *symbol : gfidsSymbols)
    stream.emitCOFFSymbolIndex(symbol);

  // Emit .giats section
  stream.switchSection(Asm->OutContext.getObjectFileInfo()->getGIATsSection());
  for (const MCSymbol *symbol : giatsSymbols)
    stream.emitCOFFSymbolIndex(symbol);

  // Emit .gljmp section
  stream.switchSection(Asm->OutContext.getObjectFileInfo()->getGLJMPSection());
  for (const MCSymbol *symbol : LongjmpTargets)
    stream.emitCOFFSymbolIndex(symbol);
}

#include "large_enum.h"
