    void validateCondition(bool expr, const char *desc, int lineNumber) {
        if (!expr) {
            std::cout << "Assertion failed at " __FILE__ "(" << lineNumber << "): " << desc
                 << "    (failed)" << std::endl;
            if (0 <= testResult && testResult <= 100) {
                ++testResult;
            }
        }
    }
}  // close unnamed namespace

