void TFileListTest::TestSimple() {
    TTempDir tempDirectory("nonexistingdir");
    MakeDirIfNotExist((tempDirectory() + LOCSLASH_S "subdirectory").data());
    TFile((tempDirectory() + LOCSLASH_S "subdirectory" LOCSLASH_S "datafile").data(), CreateAlways);
    TFileList fileList;
    fileList.Fill(tempDirectory().data(), "", "", 1000);
    TString filePath(fileList.Next());
    UNIT_ASSERT_EQUAL(filePath, "subdirectory" LOCSLASH_S "datafile");
    UNIT_ASSERT_EQUAL(fileList.Next(), nullptr);
}

void TFileListTest::TestPrefix() {
    TTempDir tempDirectory("nonexistingdir");
    TFile((tempDirectory() + LOCSLASH_S "match_file1").data(), CreateAlways);
    TFile((tempDirectory() + LOCSLASH_S "match_file2").data(), CreateAlways);
    TFile((tempDirectory() + LOCSLASH_S "skip_file1").data(), CreateAlways);
    TFile((tempDirectory() + LOCSLASH_S "skip_file2").data(), CreateAlways);

    const bool ENABLE_SORTING = true;
    TFileList fileList;
    {
        fileList.Fill(tempDirectory().data(), "match_file", ENABLE_SORTING);
        UNIT_ASSERT_EQUAL(TString(fileList.Next()), "match_file1");
        UNIT_ASSERT_EQUAL(TString(fileList.Next()), "match_file2");
        UNIT_ASSERT_EQUAL(fileList.Next(), nullptr);
    }
    {
        fileList.Fill(tempDirectory().data(), "skip_file", ENABLE_SORTING);
        UNIT_ASSERT_EQUAL(TString(fileList.Next()), "skip_file1");
        UNIT_ASSERT_EQUAL(TString(fileList.Next()), "skip_file2");
        UNIT_ASSERT_EQUAL(fileList.Next(), nullptr);
    }
}

