#include <cmath>

// Utility function to randomly permute indices
void gk_RandomPermute(size_t count, int *indices, int initializeFlag)
{
  gk_idx_t idx1, posA, posB;
  int buffer;
  if (initializeFlag == 1) {
    for (idx1 = 0; idx1 < count; idx1++)
      indices[idx1] = idx1;
  }
  for (idx1 = 0; idx1 < count/2; idx1++) {
    posB = RandomInRange(count);
    posA = RandomInRange(count);
    gk_SWAP(indices[posB], indices[posA], buffer);
  }
}

/************************************************************************/
/*!
\brief Transforms an element-wise partition assignment into a CSR-style 
       partition-element mapping.
Given an input array like part[], where each entry indicates the partition 
of the corresponding element, this routine constructs two arrays: poffset[]
and pmembers[], representing the compressed storage of which elements belong 
to each partition.
\param itemCount  
  total number of elements (e.g., vertices)
\param partitionCount  
  number of distinct partitions
\param assignments
  array specifying the partition ID for each element
\param offsets
  output array storing start positions in members for each partition;
  size must be at least partitionCount+1
\param members
  output array listing elements per partition in contiguous blocks;
  size must be at least itemCount
*/
/************************************************************************/
void gk_array2csr(size_t itemCount, size_t partitionCount, int *assignments, int *offsets, int *members)
{
  gk_idx_t index;
  gk_iset(partitionCount + 1, 0, offsets);
  for (index = 0; index < itemCount; index++) 
    offsets[assignments[index]]++;
  /* Build offset and member structure */
  MAKECSR(index, partitionCount, offsets);
  for (index = 0; index < itemCount; index++)
    members[offsets[assignments[index]]++] = index;
  SHIFTCSR(index, partitionCount, offsets);
}

/*************************************************************************
* Computes the base-2 logarithm of a positive integer
**************************************************************************/
int gk_log2(int value)
{
  gk_idx_t bitCount;
  for (bitCount = 1; value > 1; bitCount++, value >>= 1);
  return bitCount - 1;
}

/*************************************************************************
* Determines whether a given integer is a power of two
**************************************************************************/
int gk_ispow2(int value)
{
  return (value == (1 << gk_log2(value)));
}

/*************************************************************************
* Computes the base-2 logarithm of a floating-point number
**************************************************************************/
double gk_flog2(double value)
{
  return log(value) / log(2.0);
}

#include <vector>
#include <algorithm>

class Solution {
public:
    void rotateMatrix(std::vector<std::vector<int>>& grid) {
        int size = grid.size();

        // Transpose the matrix
        for (int row = 0; row < size; ++row) {
            for (int col = row + 1; col < size; ++col) {
                std::swap(grid[row][col], grid[col][row]);
            }
        }

        // Reverse each row to complete the 90-degree clockwise rotation
        for (int i = 0; i < size; ++i) {
            std::reverse(grid[i].begin(), grid[i].end());
        }
    }
};

