#include "ByteArrayOutputStream.h"

// Constructs a new byte array output stream with an initial buffer capacity of 64 bytes
ByteArrayOutputStream::ByteArrayOutputStream()
{
    position = 0;
    buffer = byteArray(64);
}

// Constructs a new byte array output stream with the specified initial capacity
// Parameters:
// capacity - the initial buffer size in bytes
ByteArrayOutputStream::ByteArrayOutputStream(unsigned int capacity)
{
    position = 0;
    buffer = byteArray(capacity);
}

ByteArrayOutputStream::~ByteArrayOutputStream()
{
    if (buffer.data != nullptr)
        delete[] buffer.data;
}

// Writes a single byte to the stream
// Parameters:
// value - the byte to be written
void ByteArrayOutputStream::write(unsigned int value)
{
    // Expand buffer if necessary
    if (position + 1 >= buffer.length)
        buffer.resize(buffer.length * 2);

    buffer[position] = static_cast<byte>(value);
    position++;
}

// Writes all bytes from the given byte array to the stream
// The behavior is equivalent to write(b, 0, b.length)
void ByteArrayOutputStream::write(byteArray b)
{
    write(b, 0, b.length);
}

// Writes a subsequence of bytes from the given array to the stream
// Parameters:
// data - source byte array
// startIndex - starting position in the source array
// count - number of bytes to copy
void ByteArrayOutputStream::write(byteArray data, unsigned int startIndex, unsigned int count)
{
    assert(data.length >= startIndex + count);

    // Ensure sufficient buffer space
    if (position + count >= buffer.length)
        buffer.resize(std::max(position + count + 1, buffer.length * 2));

    memcpy(&buffer[position], &data[startIndex], count);
    position += count;
}

// No-op implementation: closing this stream has no effect
void ByteArrayOutputStream::close()
{
}

// Returns a copy of the current stream contents as a new byte array
// The returned array's length equals the current stream size
byteArray ByteArrayOutputStream::toByteArray()
{
    byteArray result(position);
    memcpy(result.data, buffer.data, position);
    return result;
}

