namespace quantclaw::cli {

CLIManager::CLIManager() = default;

void CLIManager::AddCommand(const Command& cmd) {
    commands_.emplace_back(cmd);
}

int CLIManager::Run(int arg_count, char** arg_values) {
    if (arg_count < 2) {
        ShowHelp();
        return 1;
    }

    std::string requested_command = arg_values[1];

    // Process global flags first
    if (requested_command == "--version" || requested_command == "-v") {
        std::cout << "quantclaw " << kVersion
                  << " (build " << kGitCommit << " " << kBuildDate << ")"
                  << std::endl;
        return 0;
    }

    if (requested_command == "--help" || requested_command == "-h") {
        ShowHelp();
        return 0;
    }

    // Search for matching command
    for (const auto& available_cmd : commands_) {
        if (available_cmd.name == requested_command ||
            std::find(available_cmd.aliases.begin(), available_cmd.aliases.end(), requested_command) != available_cmd.aliases.end()) {
            char** subcommand_argv = &arg_values[1];
            int subcommand_argc = arg_count - 1;
            return available_cmd.handler(subcommand_argc, subcommand_argv);
        }
    }

    std::cerr << "Unknown command: " << requested_command << std::endl;
    ShowHelp();
    return 1;
}

void CLIManager::ShowHelp() const {
    std::cout << "QuantClaw - High-performance C++ AI assistant" << std::endl;
    std::cout << std::endl;
    std::cout << "Usage: quantclaw <command> [options]" << std::endl;
    std::cout << std::endl;
    std::cout << "Commands:" << std::endl;
    for (const auto& cmd_entry : commands_) {
        std::cout << "  " << cmd_entry.name;
        if (!cmd_entry.aliases.empty()) {
            std::cout << " (";
            for (size_t idx = 0; idx < cmd_entry.aliases.size(); ++idx) {
                if (idx > 0) std::cout << ", ";
                std::cout << cmd_entry.aliases[idx];
            }
            std::cout << ")";
        }
        std::cout << "\t" << cmd_entry.description << std::endl;
    }
    std::cout << std::endl;
    std::cout << "Global flags:" << std::endl;
    std::cout << "  --version, -v\tPrint version" << std::endl;
    std::cout << "  --help, -h\tShow help" << std::endl;
    std::cout << "  --json\tJSON output mode" << std::endl;
    std::cout << std::endl;
    std::cout << "Examples:" << std::endl;
    std::cout << "  quantclaw gateway              Start gateway (foreground)" << std::endl;
    std::cout << "  quantclaw gateway install       Install as system service" << std::endl;
    std::cout << "  quantclaw gateway status         Show gateway status" << std::endl;
    std::cout << "  quantclaw agent -m \"Hello\"       Send message to agent" << std::endl;
    std::cout << "  quantclaw sessions list          List sessions" << std::endl;
    std::cout << "  quantclaw health                 Health check" << std::endl;
    std::cout << "  quantclaw config get gateway.port Get config value" << std::endl;
}

