#include <cstdlib>
#include <iostream>
#include <boost/bind.hpp>
#include "asio.hpp"

using asio::ip::udp;

class echo_server
{
public:
  echo_server(asio::io_context& context, unsigned short port_number)
    : udp_socket(context, udp::endpoint(udp::v4(), port_number))
  {
    udp_socket.async_receive_from(
        asio::buffer(buffer_, buffer_size), remote_endpoint_,
        boost::bind(&echo_server::on_receive, this,
          asio::placeholders::error,
          asio::placeholders::bytes_transferred));
  }

  void on_receive(const asio::error_code& ec, std::size_t length)
  {
    if (!ec && length > 0)
    {
      udp_socket.async_send_to(
          asio::buffer(buffer_, length), remote_endpoint_,
          boost::bind(&echo_server::on_send, this,
            asio::placeholders::error,
            asio::placeholders::bytes_transferred));
    }
    else
    {
      udp_socket.async_receive_from(
          asio::buffer(buffer_, buffer_size), remote_endpoint_,
          boost::bind(&echo_server::on_receive, this,
            asio::placeholders::error,
            asio::placeholders::bytes_transferred));
    }
  }

  void on_send(const asio::error_code& /*ignored*/, std::size_t /*sent*/)
  {
    udp_socket.async_receive_from(
        asio::buffer(buffer_, buffer_size), remote_endpoint_,
        boost::bind(&echo_server::on_receive, this,
          asio::placeholders::error,
          asio::placeholders::bytes_transferred));
  }

private:
  udp::socket udp_socket;
  udp::endpoint remote_endpoint_;
  static const std::size_t buffer_size = 2048;
  char buffer_[buffer_size];
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: async_udp_echo_server <port>\n";
      return 1;
    }

    asio::io_context io_context;
    using namespace std; // For atoi.
    echo_server server_instance(io_context, static_cast<unsigned short>(atoi(argv[1])));
    io_context.run();
  }
  catch (const std::exception& exception_obj)
  {
    std::cerr << "Error: " << exception_obj.what() << "\n";
  }

  return 0;
}

#include "kml/serdes.hpp"
#include "kml/serdes_binary.hpp"
#include "indexer/classificator_loader.hpp"
#include "coding/file_reader.hpp"
#include "coding/file_writer.hpp"
#include <iostream>

int main(int argc, char ** argv)
{
  if (argc < 2)
  {
    std::cout << "Converts kmb file(s) to kml\n";
    std::cout << "Usage: " << argv[0] << " path_to_kmb_file [path_to_another_kmb_file...]\n";
    return 1;
  }

  classificator::Load();

  do
  {
    std::string inputPath = argv[argc - 1];
    kml::FileData outputData;

    try
    {
      FileReader inputFile(inputPath);
      kml::binary::DeserializerKml parser(outputData);
      parser.Deserialize(inputFile);
    }
    catch (kml::binary::DeserializerKml::DeserializeException const & error)
    {
      std::cerr << "Error reading kmb file " << inputPath << ": " << error.what() << std::endl;
      return 1;
    }

    try
    {
      // Modify extension from .kmb to .kml
      inputPath[inputPath.size() - 1] = 'l';
      kml::SerializerKml exporter(outputData);
      FileWriter outputFile(inputPath);
      exporter.Serialize(outputFile);
    }
    catch (kml::SerializerKml::SerializeException const & error)
    {
      std::cerr << "Error encoding to kml file " << inputPath << ": " << error.what() << std::endl;
      return 1;
    }
    catch (FileWriter::Exception const & error)
    {
      std::cerr << "Error writing to kml file " << inputPath << ": " << error.what() << std::endl;
      return 1;
    }

    std::cout << "Saved converted file as " << inputPath << std::endl;
  }
  while (--argc > 1);

  return 0;
}

#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>
#include <iostream>

int main(int argc, char** argv) {
    std::cout << "=== Lua error handling demonstration ===" << std::endl;
    sol::state lua_vm;

    std::string malformed_script = R"(
bad&$#*$syntax
bad.code = 2
return 24
)";

    // Approach A: Exception-based error handling
    {
        try {
            int result_value = lua_vm.script(
                malformed_script, sol::script_default_on_error);
            // Should never reach here due to syntax error
            std::cout << "Result: " << result_value << std::endl;
            // SOL_ASSERT(result_value == 24); // Commented out for safety
        }
        catch (const sol::error& e) {
            std::cout << "Critical error occurred: "
                         "exception caught"
                      << "\n\t" << e.what() << std::endl;
        }
    }

    // Approach B: Result-based error checking
    {
        sol::protected_function_result outcome
             = lua_vm.script(malformed_script, sol::script_pass_on_error);
        // SOL_ASSERT(!outcome.valid()); // Commented out for safety

        if (!outcome.valid()) {
            sol::error err_obj = outcome;
            sol::call_status err_code = outcome.status();
            std::cout << "Script execution failed: "
                      << sol::to_string(err_code) << " status"
                      << "\n\t" << err_obj.what() << std::endl;
        }
    }

    // Approach C: Manual chunk loading and execution
    {
        sol::load_result loaded_chunk = lua_vm.load(malformed_script);
        // SOL_ASSERT(!loaded_chunk.valid()); // Commented out for safety

        if (!loaded_chunk.valid()) {
            sol::error err_obj = loaded_chunk;
            sol::load_status load_status = loaded_chunk.status();
            std::cout << "Failed to load script: "
                         "syntax or compilation error"
                      << "\n\t" << sol::to_string(load_status) 
                      << " status\n\t" << err_obj.what() << std::endl;
        }
        else {
            // This branch should not execute due to syntax errors
            // SOL_ASSERT(false);

            sol::protected_function func = loaded_chunk
                .get<sol::protected_function>();
            sol::protected_function_result run_result = func();

            if (!run_result.valid()) {
                sol::error err_obj = run_result;
                sol::call_status call_status = run_result.status();
                std::cout << "Runtime error during execution: "
                          << sol::to_string(call_status) 
                          << " status"
                          << "\n\t" << err_obj.what() << std::endl;
            }
        }
    }

    std::cout << std::endl;
    return 0;
}

