class FPlatformCryptoAdapter : public IEngineCrypto
{
public:
	FPlatformCryptoAdapter()
	{
		IModularFeatures::Get().RegisterModularFeature(IEngineCrypto::GetFeatureName(), this);
	}

	virtual ~FPlatformCryptoAdapter()
	{
		Cleanup();
	}

	virtual void Cleanup() override
	{
		EncryptionContext.Reset();
	}

	/** IEngineCrypto implementation */
	virtual FRSAKeyHandle CreateRSAKey(const TArrayView<const uint8> InExponentPublic, const TArrayView<const uint8> InExponentPrivate, const TArrayView<const uint8> InModulusValue) override
	{
		return GetContext()->CreateKey_RSA(InExponentPublic, InExponentPrivate, InModulusValue);
	}

	virtual void DestroyRSAKey(FRSAKeyHandle InKeyHandle) override
	{
		GetContext()->DestroyKey_RSA(InKeyHandle);
	}

	virtual int32 GetKeyLength(FRSAKeyHandle InKeyHandle) override
	{
		return GetContext()->GetKeySize_RSA(InKeyHandle);
	}

	virtual int32 GetMaximumDataLength(FRSAKeyHandle InKeyHandle) override
	{
		return GetContext()->GetMaxDataSize_RSA(InKeyHandle);
	}

	virtual int32 EncryptWithPublic(const TArrayView<const uint8> InInputData, TArray<uint8>& OutEncryptedData, FRSAKeyHandle InKeyHandle) override
	{
		return GetContext()->EncryptPublic_RSA(InInputData, OutEncryptedData, InKeyHandle);
	}

	virtual int32 EncryptWithPrivate(const TArrayView<const uint8> InInputData, TArray<uint8>& OutEncryptedData, FRSAKeyHandle InKeyHandle) override
	{
		return GetContext()->EncryptPrivate_RSA(InInputData, OutEncryptedData, InKeyHandle);
	}

	virtual int32 DecryptWithPublic(const TArrayView<const uint8> InInputData, TArray<uint8>& OutDecryptedData, FRSAKeyHandle InKeyHandle) override
	{
		return GetContext()->DecryptPublic_RSA(InInputData, OutDecryptedData, InKeyHandle);
	}

	virtual int32 DecryptWithPrivate(const TArrayView<const uint8> InInputData, TArray<uint8>& OutDecryptedData, FRSAKeyHandle InKeyHandle) override
	{
		return GetContext()->DecryptPrivate_RSA(InInputData, OutDecryptedData, InKeyHandle);
	}

private:
	TUniquePtr<FEncryptionContext>& GetContext()
	{
		if (!EncryptionContext.IsValid())
		{
			EncryptionContext = IPlatformCrypto::Get().CreateContext();
		}
		return EncryptionContext;
	}

	/** Context used by IEngineCrypto implementation */
	TUniquePtr<FEncryptionContext> EncryptionContext;
};

