#include "../store.h"
namespace {
auto indexConfiguration = R"(
		{
			"config": {
				"index": {
					"compress": true,
					"maxWordCount": 250000000,
					"batchId": 1,
					"indexOutput": "datafile://data/output-words-%BatchId%.dat"
				}
			}
		}
	)"_json;
}
TEST_CASE("store::index") {
    // Creates a small subset of words
    SECTION("write a few words") {
        IFilterTest filter({engine::store::filter::indexer::Type}, indexConfiguration);
        Error errorCode;
        // Build and connect the endpoint
        REQUIRE_NO_ERROR(filter.connect());
        // Get a source pipe, open a dummy object on it
        auto stream = filter.openObject("test.txt"_tv, Entry::FLAGS::INDEX);
        REQUIRE_NO_ERROR(stream);
        WordVector terms{"word1"_tv, "word2"_tv, "word4"_tv};
        REQUIRE_NO_ERROR(stream->writeWords(terms));
        REQUIRE_NO_ERROR(filter.closeObject(*stream));
    }
    // Adds a huge number of unique words
    SECTION("write lots of words") {
        IFilterTest filter({engine::store::filter::indexer::Type}, indexConfiguration);
        Error errorCode;
        // Build and connect the endpoint
        REQUIRE_NO_ERROR(filter.connect());
        // Get a source pipe, open a dummy object on it
        auto stream = filter.openObject("test.txt"_tv, Entry::FLAGS::INDEX);
        REQUIRE_NO_ERROR(stream);
        // Write out 1,000,000 words - non-duplicated
        _const int totalTerms = 1'000'000;
        _const int numberOfBatches = 10;
        _const int termsPerBatch = totalTerms / numberOfBatches;
        for (int batchIndex = 0; batchIndex < numberOfBatches; batchIndex++) {
            WordVector terms;
            LOG(Test, "Batch {}", batchIndex);
            // Add in batches
            for (int termIndex = 0; termIndex < termsPerBatch; termIndex++) {
                // Create the term
                Text term =
                    string::format("this.is.a.longer.phrase.{}",
                                   batchIndex * termsPerBatch + termIndex);
                // Save it in the text list - we need to do this
                // since the writeWords takes a view
                terms.push_back(_mv(term));
            }
            REQUIRE_NO_ERROR(stream->writeWords(terms));
        }
        // Close the object
        REQUIRE_NO_ERROR(filter.closeObject(*stream));
    }
}

