    // The internal map is default-constructed
}

void MessageBus::store(Message *msg) {
    // Insert or update the message at its address
    messages[msg->get_address()] = msg;
}

Message *MessageBus::fetch(uint64_t addr) {
    // Look up the message by its address
    auto iter = messages.find(addr);
    if (iter != messages.end()) {
        return iter->second;
    }
    return nullptr; // No message exists for this address
}

