namespace engine::task::actionTransform {
//-----------------------------------------------------------------
/// @details
///		Initialization for a transformation operation
//-----------------------------------------------------------------
Error Task::beginTask() noexcept {
    // Acquire the target endpoint first, as source endpoint configuration
    // depends on it
    if (!(m_targetEndpoint = IServiceEndpoint::getTargetEndpoint(
              {.jobConfig = jobConfig(),
               .taskConfig = taskConfig(),
               .serviceConfig = taskConfig()["destination"],
               .openMode = OPEN_MODE::TRANSFORM})))
        return m_targetEndpoint.ccode();

    // Determine how the source endpoint should be opened
    OPEN_MODE sourceOpenMode{};
    if (m_targetEndpoint->config.taskConfig.lookup<bool>("requiresPolicies") ||
        m_targetEndpoint->config.taskConfig.lookup<bool>("requiresContext") ||
        m_targetEndpoint->config.taskConfig.lookup<bool>("requiresText")) {
        sourceOpenMode =
            m_targetEndpoint->config.taskConfig.lookup<bool>("requiresData")
                ? OPEN_MODE::SOURCE_INDEX
                : OPEN_MODE::INDEX;
    } else {
        sourceOpenMode = OPEN_MODE::SOURCE;
    }

    // Acquire the source endpoint
    if (!(m_sourceEndpoint = IServiceEndpoint::getSourceEndpoint(
              {.jobConfig = jobConfig(),
               .taskConfig = taskConfig(),
               .serviceConfig = taskConfig()["origin"],
               .openMode = sourceOpenMode})))
        return m_sourceEndpoint.ccode();

    // Perform base class initialization
    return Parent::beginTask();
}
//-----------------------------------------------------------------
///	@details
///		Processes an incoming line to generate and queue an entry
/// @param[in] inputLine
///		A single line of input — JSON formatted
/// @param[in] basePath
///		The current parent URL path
//-----------------------------------------------------------------
ErrorOr<Entry> Task::processLine(TextView inputLine, const Url &basePath) noexcept {
    // Handle lines starting with 'A' followed by '{...}'
    auto entry = Parent::processLine("A"_tv, inputLine, basePath);
    if (entry.hasCcode()) return entry;

    // Transform action requires classification; update flags accordingly
    entry.value().flags(entry.value().flags() | Entry::FLAGS::INDEX |
                        Entry::FLAGS::CLASSIFY | Entry::FLAGS::OCR);
    return entry;
}
//-----------------------------------------------------------------
/// @details
///		Applies transformation to a given entry
/// @param[in] itemEntry
///		The entry to be transformed
//-----------------------------------------------------------------
Error Task::processItem(Entry &itemEntry) noexcept {
    // Apply base transformation logic
    if (auto ccode = Parent::processItem(itemEntry)) return ccode;

    // The Transform action may include full text content during classification,
    // which can significantly increase disk or network usage.
    // Since output batches are not further processed, we discard classifications.
    itemEntry.classifications.reset();

    // Handle success/failure states
    if (itemEntry.objectFailed()) {
        // Check if object was skipped
        if (itemEntry.completionCode() == Ec::Skipped) {
            // Record as completed without writing result
            MONITOR(addCompleted, 1, itemEntry.size());
        } else {
            // Record as failed
            MONITOR(addFailed, 1, itemEntry.size());
            // Log error if applicable
            if (auto ccode = Parent::writeError(itemEntry, itemEntry.completionCode()))
                return ccode;
        }
    } else {
        // Record successful completion
        MONITOR(addCompleted, 1, itemEntry.size());
        // Write transformed output
        if (auto ccode = Parent::writeResult('A', itemEntry)) return ccode;
    }

    // Operation complete
    return {};
}
}  // namespace engine::task::actionTransform

