#include <vector>

class Solution {
public:
    int minOperations(std::vector<int>& values) {
        int length = values.size();
        long long count = 0;
        for (int index = 1; index < values.size(); index++) {
            if (values[index] <= values[index - 1]) {
                int required = values[index - 1] + 1 - values[index];
                count += required;
                values[index] = values[index - 1] + 1;
            }
        }
        return count;
    }
};

