// NOTE:
// THIS IS A LOW-LEVEL EXAMPLE, using pieces of sol2
// to facilitate better usage
// It is recommended you just do the simple version, as it is
// basically this code but it is sometimes useful to show the
// hoops you need to jump through to use the Lua C API
void complicated(sol::this_state L_state) {
    lua_State* raw_L = L_state;
    lua_Debug debug_info;

    // Level 0 refers to the current function (useless here)
    // Level 1 points to the calling function — likely the desired environment
    int stack_level = 1;
    int initial_stack_depth = lua_gettop(raw_L);

    if (lua_getstack(raw_L, stack_level, &debug_info) != 1) {
        std::cout << "error: unable to traverse the stack"
                  << std::endl;
        lua_settop(raw_L, initial_stack_depth);
        return;
    }

    // "f" retrieves the function at the specified level
    // Remaining logic handles debugging output
    if (lua_getinfo(raw_L, "fnluS", &debug_info) == 0) {
        std::cout << "manually -- error: unable to get stack "
                     "information"
                  << std::endl;
        lua_settop(raw_L, initial_stack_depth);
        return;
    }

    // Print diagnostic info about the stack frame
    std::cout << "manually -- [" << stack_level << "] "
              << debug_info.short_src << ":" << debug_info.currentline
              << " -- " << (debug_info.name ? debug_info.name : "<unknown>")
              << "[" << debug_info.what << "]" << std::endl;

    // Extract function from top of stack
    sol::function func_obj(raw_L, -1);

    // Retrieve its environment
    sol::environment captured_env(sol::env_key, func_obj);
    if (!captured_env.valid()) {
        std::cout << "manually -- error: no environment to get"
                  << std::endl;
        lua_settop(raw_L, initial_stack_depth);
        return;
    }

    sol::state_view lua_vm(raw_L);
    sol::environment freshenv = lua_vm["freshenv"];
    bool env_equality = freshenv == captured_env;
    std::cout << "manually -- env == freshenv : " << env_equality
              << std::endl;
}

int main() {
    std::cout << "=== environment snooping ===" << std::endl;
    sol::state lua_vm;
    sol::environment freshenv(lua_vm, sol::create, lua_vm.globals());
    lua_vm["freshenv"] = freshenv;
    lua_vm.set_function("f", simple);
    lua_vm.set_function("g", complicated);
    lua_vm.script("f()", freshenv);
    lua_vm.script("g()", freshenv);
    std::cout << std::endl;
    return 0;
}

#include <vector>
using namespace std;

class Solution {
public:
    // Sort an array containing only 0s, 1s, and 2s
    void sortColors(vector<int>& colors) {
        int size = colors.size();
        int holder;

        for(int pass = 0; pass < size; pass++) {
            for(int index = 0; index < size - pass - 1; index++) {
                if(colors[index] > colors[index + 1]) {
                    holder = colors[index];
                    colors[index] = colors[index + 1];
                    colors[index + 1] = holder;
                }
            }
        }
    }
};

#include "comms/torchcomms/nccl/TorchCommNCCLCCA.hpp"

namespace torch::comms {

// Hook function registered globally for allocator tracing
void allocatorTraceCallback(
    const c10::cuda::CUDACachingAllocator::TraceEntry& entry) {
  // Delegate to singleton handler
  CachingAllocatorHook::getInstance().handleMemEvent(entry);
}

// Singleton accessor with thread-safe initialization
CachingAllocatorHookImpl& CachingAllocatorHook::getInstance() {
  static std::once_flag onceFlag;
  std::call_once(onceFlag, [] { instance_ = new CachingAllocatorHookImpl(); });
  return *instance_;
}

// Constructor: initialize CUDA context and attach hooks
DefaultCachingAllocatorHookImpl::DefaultCachingAllocatorHookImpl() {
  at::globalContext().lazyInitDevice(c10::DeviceType::CUDA);
  setupMemoryHooks();
  c10::cuda::CUDACachingAllocator::attachAllocatorTraceTracker(&allocatorTraceCallback);
}

// Pre-scan existing memory segments and register them
void CachingAllocatorHookImpl::setupMemoryHooks() {
  auto memSnapshot = c10::cuda::CUDACachingAllocator::snapshot();
  for (const auto& seg : memSnapshot.segments) {
    void* ptr = reinterpret_cast<void*>(seg.address);
    size_t size = seg.total_size;
    if (memRegistry_.count(ptr)) {
      throw std::runtime_error("Duplicate memory registration detected");
    }
    memRegistry_[ptr] = SegmentInfo{size, static_cast<int>(seg.device)};
  }
}

// Handle allocation/deallocation events from allocator trace
void CachingAllocatorHookImpl::handleMemEvent(
    const c10::cuda::CUDACachingAllocator::TraceEntry& entry) {
  std::lock_guard<std::mutex> guard(mutex_);
  bool isAlloc = (entry.action_ == c10::cuda::CUDACachingAllocator::TraceEntry::Action::SEGMENT_ALLOC);
  bool isFree = (entry.action_ == c10::cuda::CUDACachingAllocator::TraceEntry::Action::SEGMENT_FREE);

  if (isAlloc) {
    void* addr = reinterpret_cast<void*>(static_cast<uintptr_t>(entry.addr_));
    size_t len = entry.size_;
    if (memRegistry_.find(addr) != memRegistry_.end()) {
      throw std::runtime_error("Attempted to re-register already-registered memory");
    }
    memRegistry_[addr] = SegmentInfo{len, static_cast<int>(entry.device_)};

    // Register with all matching communicators
    for (auto& comm : activeComms_) {
      if (comm->getDevice().index() == entry.device_) {
        comm->register_address(TorchCommNCCL::AddressWithLen(addr, len));
      }
    }
  } else if (isFree) {
    void* addr = reinterpret_cast<void*>(static_cast<uintptr_t>(entry.addr_));
    if (memRegistry_.find(addr) == memRegistry_.end()) {
      throw std::runtime_error("Attempting to free unregistered memory");
    }
    memRegistry_.erase(addr);

    // Deregister from matching communicators
    for (auto& comm : activeComms_) {
      if (comm->getDevice().index() == entry.device_) {
        comm->deregister_address(TorchCommNCCL::Address(addr));
      }
    }
  }
}

// Register a new communicator and pre-populate its memory registrations
void CachingAllocatorHookImpl::attachCommunicator(TorchCommNCCL* comm) {
  std::lock_guard<std::mutex> guard(mutex_);
  if (activeComms_.find(comm) != activeComms_.end()) {
    throw std::runtime_error("Communicator already attached");
  }

  for (const auto& [ptr, info] : memRegistry_) {
    if (info.devId == comm->getDevice().index()) {
      comm->register_address(TorchCommNCCL::AddressWithLen(ptr, info.length));
    }
  }
  activeComms_.insert(comm);
}

// Unregister a communicator and clean up its memory associations
void CachingAllocatorHookImpl::detachCommunicator(TorchCommNCCL* comm) {
  std::lock_guard<std::mutex> guard(mutex_);
  if (activeComms_.find(comm) == activeComms_.end()) {
    return; // silently ignore if not registered
  }

  for (const auto& [ptr, info] : memRegistry_) {
    if (info.devId == comm->getDevice().index()) {
      comm->deregister_address(TorchCommNCCL::Address(ptr));
    }
  }
  activeComms_.erase(comm);
}

// Clear all registrations: communicators and memory
void CachingAllocatorHookImpl::reset() {
  std::lock_guard<std::mutex> guard(mutex_);
  for (auto& comm : activeComms_) {
    for (const auto& [ptr, info] : memRegistry_) {
      if (info.devId == comm->getDevice().index()) {
        comm->deregister_address(TorchCommNCCL::Address(ptr));
      }
    }
  }
  memRegistry_.clear();
  activeComms_.clear();
}

// Query whether a given communicator is currently registered
bool CachingAllocatorHookImpl::hasCommunicator(TorchCommNCCL* comm) {
  std::lock_guard<std::mutex> guard(mutex_);
  return activeComms_.find(comm) != activeComms_.end();
}

