class Biome;

// Spike centre positions, calculated using
// for(int i=0;i<8;i++)
// {
// int x=40 * Mth::cos(2*(-PI+(PI/8)*i));
// int z=40* Mth::sin(2*(-PI+(PI/8)*i));
// }
TheEndBiomeDecorator::SPIKE TheEndBiomeDecorator::SpikeValB[8] = {
    // The chunk that the spike is in has to be the smallest x and z that any
    // part of it is in a chunk(x,z) will only be post-processed when the chunks
    // (x+1,z), (x,z+1) and (x+1,z+1) are also loaded
    // first two values are the smallest x and z of the chunk that the feature
    // is in - so the centre point minus the radius
    {32,  -16, 40,  0,   2}, // smallest block - 38,-2
    {16,  16,  28,  28,  2}, // smallest block - 26,26
    {-16, 32,  0,   40,  2}, // smallest block - -2,38
    {-32, 16,  -28, 28,  3}, // smallest block - -31,26
    {-48, -16, -40, 0,   3}, // smallest block - -43,-3
    {-32, -32, -28, -28, 3}, // smallest block - -31,-31
    {-16, -48, 0,   -40, 4}, // smallest block - -4,-44
    {16,  -32, 28,  -28, 4}, // smallest block - 24,-32
};

TheEndBiomeDecorator::TheEndBiomeDecorator(Biome* biome)
: BiomeDecorator(biome) {
    spikeFeature     = new SpikeFeature(Tile::whiteStone_Id);
    endPodiumFeature = new EndPodiumFeature(Tile::whiteStone_Id);
}

void TheEndBiomeDecorator::decorate() {
    decorateOres();

    // Determine the top solid block at center of current chunk
    int surfaceY = level->getTopSolidBlock(xo + 8, zo + 8);
    if (surfaceY > level->GetHighestY()) 
        level->SetHighestY(surfaceY);

    // Place 8 spikes in a circular pattern with increasing height
    for (int index = 0; index < 8; ++index) {
        if ((xo == SpikeValB[index].iChunkX) && (zo == SpikeValB[index].iChunkZ)) {
            spikeFeature->placeWithIndex(
                level,
                random,
                SpikeValB[index].x,
                level->GetHighestY(),
                SpikeValB[index].z,
                index,
                SpikeValB[index].radius
            );
        }
    }

    // Spawn Ender Dragon at world center (0, 128, 0)
    if (xo == 0 && zo == 0) {
        std::shared_ptr<EnderDragon> dragonEntity =
            std::shared_ptr<EnderDragon>(new EnderDragon(level));
        dragonEntity->moveTo(0, 128, 0, random->nextFloat() * 360, 0);
        level->addEntity(dragonEntity);
    }

    // Place End Podium feature in the required chunk (-16, -16)
    if (xo == -16 && zo == -16) {
        endPodiumFeature->place(level, random, 0, Level::genDepth / 2, 0);
    }
}

#include <ros/ros.h>
#include <grid_map_ros/grid_map_ros.hpp>
#include <grid_map_cv/grid_map_cv.hpp>
#include <cv_bridge/cv_bridge.h>
#include <opencv2/highgui/highgui.hpp>

using namespace grid_map;
using namespace ros;

int main(int argc, char** argv)
{
  // Initialize ROS node and publisher.
  init(argc, argv, "opencv_demo");
  NodeHandle nh("~");
  Publisher pub = nh.advertise<grid_map_msgs::GridMap>("grid_map", 1, true);
  const bool enableAlpha = false;

  // Create grid map with layers.
  GridMap layers({"input_layer", "processed_elevation"});
  layers.setFrameId("map");
  layers.setGeometry(Length(1.2, 2.0), 0.01);

  ROS_INFO("Generated map of dimensions %f x %f m (%i x %i cells).",
    layers.getLength().x(), layers.getLength().y(),
    layers.getSize()(0), layers.getSize()(1));

  // Populate initial data.
  if (!enableAlpha) layers["input_layer"].setZero();

  grid_map::Polygon boundary;
  boundary.setFrameId(layers.getFrameId());
  boundary.addVertex(Position( 0.480,  0.000));
  boundary.addVertex(Position( 0.164,  0.155));
  boundary.addVertex(Position( 0.116,  0.500));
  boundary.addVertex(Position(-0.133,  0.250));
  boundary.addVertex(Position(-0.480,  0.399));
  boundary.addVertex(Position(-0.316,  0.000));
  boundary.addVertex(Position(-0.480, -0.399));
  boundary.addVertex(Position(-0.133, -0.250));
  boundary.addVertex(Position( 0.116, -0.500));
  boundary.addVertex(Position( 0.164, -0.155));
  boundary.addVertex(Position( 0.480,  0.000));

  for (grid_map::PolygonIterator iter(layers, boundary); !iter.isPastEnd(); ++iter) {
    layers.at("input_layer", *iter) = 0.3;
  }

  // Convert to OpenCV image.
  cv::Mat sourceImage;
  if (enableAlpha) {
    GridMapCvConverter::toImage<unsigned short, 4>(layers, "input_layer", CV_16UC4, 0.0, 0.3, sourceImage);
  } else {
    GridMapCvConverter::toImage<unsigned short, 1>(layers, "input_layer", CV_16UC1, 0.0, 0.3, sourceImage);
  }

  // Setup visualization window.
  cv::namedWindow("OpenCV Demo");

  // Main processing loop.
  while (nh.ok()) {
    ros::Time timestamp = ros::Time::now();
    layers.setTimestamp(timestamp.toNSec());

    cv::Mat processedImage;
    int kernelSize = 200 - abs((int)(200.0 * sin(timestamp.toSec())));
    kernelSize = kernelSize - (kernelSize % 2) + 1;

    // Apply Gaussian smoothing.
    cv::GaussianBlur(sourceImage, processedImage, cv::Size(kernelSize, kernelSize), 0.0, 0.0);

    // Display result.
    cv::imshow("OpenCV Demo", processedImage);
    cv::waitKey(40);

    // Update elevation layer from processed image.
    if (enableAlpha) {
      GridMapCvConverter::addLayerFromImage<unsigned short, 4>(processedImage, "processed_elevation", layers, 0.0, 0.3, 0.3);
    } else {
      GridMapCvConverter::addLayerFromImage<unsigned short, 1>(processedImage, "processed_elevation", layers, 0.0, 0.3);
    }

    // Publish updated grid map.
    grid_map_msgs::GridMap msg;
    GridMapRosConverter::toMessage(layers, msg);
    pub.publish(msg);

    ROS_INFO_STREAM("Sent updated map with blur kernel size " << kernelSize << ".");
  }

  return 0;
}

#include <iostream>
