#include <nlohmann/json.hpp>

using namespace std::string_view_literals;
using json = nlohmann::json;

int main()
{
    // Initialize a JSON object with key-value pairs
    const json data =
    {
        {"the good", "il buono"},
        {"the bad", "il cattivo"},
        {"the ugly", "il brutto"}
    };

    // Print the value associated with key "the ugly" using string_view
    std::cout << data.at("the ugly"sv) << '\n';

    // Handle type_error exception when calling at() on non-object JSON
    try
    {
        const json text = "I am a string";
        std::cout << text.at("the good"sv) << '\n';
    }
    catch (const json::type_error& err)
    {
        std::cout << err.what() << '\n';
    }

    // Handle out_of_range exception for nonexistent key
    try
    {
        std::cout << data.at("the fast"sv) << '\n';
    }
    catch (const json::out_of_range&)
    {
        std::cout << "key not found" << '\n';
    }
}

#ifdef WITH_SYSTEMD
#include "sd_platform.hpp"
extern "C"
{
#include <net/if.h>
}
#include "linux/dbus.hpp"
namespace srouter::dns::sd
{
    void Platform::set_resolver(unsigned int interface_index, quic::Address dns_server, bool is_global)
    {
        linux::DBUS _dbus_obj{"org.freedesktop.resolve1", "/org/freedesktop/resolve1", "org.freedesktop.resolve1.Manager"};
        // This passing address by bytes and using two separate calls for ipv4/ipv6 is gross, but
        // the alternative is to build up a bunch of crap with va_args, which is slightly more
        // gross.
        _dbus_obj("SetLinkDefaultRoute", "ib", (int32_t)interface_index, false);
        _dbus_obj("SetLinkDNSOverTLS", "is", (int32_t)interface_index, "off");
        if (dns_server.is_ipv6())
        {
            auto& addr_bytes = dns_server.in6().sin6_addr.s6_addr;
            static_assert(sizeof(addr_bytes) == 16);
            _dbus_obj(
                "SetLinkDNSEx",
                "ia(iayqs)",
                (int32_t)interface_index,
                (int)1,             // number of "iayqs"s we are passing
                (int32_t)AF_INET6,  // network address type
                (int)16,            // network addr byte size
                // clang-format off
                addr_bytes[0], addr_bytes[1], addr_bytes[2],  addr_bytes[3],  addr_bytes[4],  addr_bytes[5],  addr_bytes[6],  addr_bytes[7],
                addr_bytes[8], addr_bytes[9], addr_bytes[10], addr_bytes[11], addr_bytes[12], addr_bytes[13], addr_bytes[14], addr_bytes[15], // yuck
                // clang-format on
                dns_server.port(),
                nullptr  // dns server name (for TLS SNI which we don't care about)
            );
        }
        else
        {
            std::span<const uint8_t, 4> ipv4_bytes{reinterpret_cast<const uint8_t*>(&dns_server.in4().sin_addr.s_addr), 4};
            _dbus_obj(
                "SetLinkDNSEx",
                "ia(iayqs)",
                (int32_t)interface_index,
                (int)1,            // number of "iayqs"s we are passing
                (int32_t)AF_INET,  // network address type
                (int)4,            // network addr byte size
                // clang-format off
                ipv4_bytes[0], ipv4_bytes[1], ipv4_bytes[2], ipv4_bytes[3], // yuck
                // clang-format on
                dns_server.port(),
                nullptr  // dns server name (for TLS SNI which we don't care about)
            );
        }
        if (is_global)
            // Setting "." as a routing domain gives this DNS server higher priority in resolution
            // compared to dns servers that are set without a domain (e.g. the default for a
            // DHCP-configured DNS server)
            _dbus_obj(
                "SetLinkDomains",
                "ia(sb)",
                (int32_t)interface_index,
                (int)1,  // array size
                "."      // global DNS root
            );
        else
            // Only resolve .sesh/.loki/.snode through Session Router (so you keep using your local DNS
            // server for everything else, which is nicer than forcing everything though Session Router's
            // upstream DNS).
            _dbus_obj(
                "SetLinkDomains",
                "ia(sb)",
                (int32_t)interface_index,
                (int)3,   // array size
                "sesh",   // domain
                (int)1,   // routing domain = true
                "snode",  // domain
                (int)1,   // routing domain = true
                "loki",   // domain
                (int)1    // routing domain = true
            );
    }
}  // namespace srouter::dns::sd
#endif

