void createFile() {
    ofstream fileStream;
    char buffer[100], response;

    fileStream.open("datafile.txt");
    if (fileStream.fail()) {
        cout << "Cannot open file for writing" << endl;
        getchar();
        exit(1);
    }

    do {
        cout << "Enter text to save: ";
        fflush(stdin);
        fgets(buffer, sizeof(buffer), stdin);
        fileStream << buffer;

        cout << "Continue entering text? (y/n): ";
        fflush(stdin);
        cin >> response;
    } while (response == 'y' || response == 'Y');

    fileStream.close();
}

