    ifstream inputStream;
    char character;

    cout << "File contents:" << endl;
    inputStream.open("datafile.txt");

    if (inputStream.fail()) {
        getchar();
        exit(1);
    }

    while (!inputStream.eof()) {
        inputStream.get(character);
        cout.put(character);
    }

    inputStream.close();
}

