    readFile();
    return 0;
}

#include "dap/io.h"
#include "dap/network.h"
#include "dap/protocol.h"
#include "dap/session.h"
#include <condition_variable>
#include <mutex>

int main(int, char*[]) {
  constexpr int kServerPort = 19021;

  // Handler invoked when a client establishes a connection to the server
  auto onClientConnected =
      [&](const std::shared_ptr<dap::ReaderWriter>& conn) {
        auto session = dap::Session::create();
        // Configure session to close upon receiving malformed data, ensuring basic validation
        session->setOnInvalidData(dap::kClose);
        session->bind(conn);

        // Handle InitializeRequest: first message from client, response defines debugger features
        // Ref: https://microsoft.github.io/debug-adapter-protocol/specification#Requests_Initialize
        session->registerHandler([&](const dap::InitializeRequest&) {
          dap::InitializeResponse resp;
          printf("Server got initialize request from client\n");
          return resp;
        });

        // Flag and synchronization primitives for shutdown signaling
        bool shouldExit = false;
        std::condition_variable condVar;
        std::mutex mtx;  // protects 'shouldExit'

        // Handle DisconnectRequest: sent by client before closing connection
        // Ref: https://microsoft.github.io/debug-adapter-protocol/specification#Requests_Disconnect
        session->registerHandler([&](const dap::DisconnectRequest&) {
          std::unique_lock<std::mutex> guard(mtx);
          shouldExit = true;
          condVar.notify_one();
          return dap::DisconnectResponse{};
        });

        // Block until disconnect or timeout (5 seconds)
        std::unique_lock<std::mutex> guard(mtx);
        condVar.wait_for(guard, std::chrono::seconds(5), [&] { return shouldExit; });
        printf("Server shutting down connection\n");
      };

  // Error callback
  auto onError = [&](const char* err) { printf("Server issue: %s\n", err); };

  // Instantiate network server
  auto server = dap::net::Server::create();

  // Begin listening on kServerPort; invoke handlers as needed
  server->start(kServerPort, onClientConnected, onError);

  // Establish client-side socket connection
  auto clientConn = dap::net::connect("localhost", kServerPort);
  if (!clientConn) {
    printf("Failed to connect to server\n");
    return 1;
  }

  // Attach session to client socket
  auto clientSession = dap::Session::create();
  clientSession->bind(clientConn);

  // Send InitializeRequest and await response
  auto futureResp = clientSession->send(dap::InitializeRequest{});
  printf("Client dispatched initialize request to server\n");
  printf("Awaiting server response...\n");

  auto initResponse = futureResp.get();
  printf("Received response from server\n");
  printf("Initiating disconnection...\n");

  // Send DisconnectRequest to terminate session
  clientSession->send(dap::DisconnectRequest{});
  return 0;
}

