#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
using namespace std;

// Constraints: n * m <= 100000
// By enforcing rows <= columns, we ensure rows <= sqrt(100000) ≈ 316
// Using a slightly larger bound for safety
const int MAX_ROWS = 350;

// conflict[i][j] tracks if rows i and j have been paired in any previous column
bool conflict[MAX_ROWS][MAX_ROWS];

// constraint_count[i] counts how many other rows row i has already been paired with
int constraint_count[MAX_ROWS];

struct Coordinate {
    int row_idx;
    int col_idx;
};

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int input_rows, input_cols;
    if (!(cin >> input_rows >> input_cols)) return 0;

    bool dimensions_swapped = false;
    int rows = input_rows;
    int cols = input_cols;

    // Ensure rows <= cols for optimization
    if (rows > cols) {
        swap(rows, cols);
        dimensions_swapped = true;
    }

    // Initialize RNG with fixed seed for deterministic behavior
    mt19937 engine(12345);

    vector<int> row_indices(rows);
    for (int i = 0; i < rows; ++i) {
        row_indices[i] = i;
    }

    vector<Coordinate> output_points;

    // Process each column to determine valid row placements
    for (int current_col = 0; current_col < cols; ++current_col) {
        // Randomize row order to improve exploration
        shuffle(row_indices.begin(), row_indices.end(), engine);

        // Sort rows by constraint count (ascending) to prioritize less-constrained rows
        stable_sort(row_indices.begin(), row_indices.end(), [&](int a, int b) {
            return constraint_count[a] < constraint_count[b];
        });

        vector<int> selected_rows_for_col;

        // Greedy selection of compatible rows for current column
        for (int candidate_row : row_indices) {
            bool can_use = true;
            for (int used_row : selected_rows_for_col) {
                if (conflict[candidate_row][used_row]) {
                    can_use = false;
                    break;
                }
            }
            if (can_use) {
                selected_rows_for_col.push_back(candidate_row);
            }
        }

        // Record chosen points and update constraints
        for (size_t i = 0; i < selected_rows_for_col.size(); ++i) {
            int r1 = selected_rows_for_col[i];
            output_points.push_back({r1 + 1, current_col + 1});

            for (size_t j = i + 1; j < selected_rows_for_col.size(); ++j) {
                int r2 = selected_rows_for_col[j];
                conflict[r1][r2] = true;
                conflict[r2][r1] = true;
                constraint_count[r1]++;
                constraint_count[r2]++;
            }
        }
    }

    // Output total number of points
    cout << output_points.size() << "\n";

    // Print coordinates with dimension adjustment if needed
    for (const auto& pt : output_points) {
        if (dimensions_swapped) {
            cout << pt.col_idx << " " << pt.row_idx << "\n";
        } else {
            cout << pt.row_idx << " " << pt.col_idx << "\n";
        }
    }

    return 0;
}

#include "test/jemalloc_test.h"

/*
 * GCC "-Walloc-size-larger-than" warning detects when one of the memory
 * allocation functions is called with a size larger than the maximum size that
 * they support. Here we want to explicitly test that the allocation functions
 * do indeed fail properly when this is the case, which triggers the warning.
 * Therefore we disable the warning for these tests.
 */
JEMALLOC_DIAGNOSTIC_PUSH
JEMALLOC_DIAGNOSTIC_IGNORE_ALLOC_SIZE_LARGER_THAN

TEST_BEGIN(test_large_alloc_failure) {
    unsigned num_large_extents;
    size_t ctl_mib[4];
    size_t value_size, mib_length, max_allocable_size;
    void *ptr;

    value_size = sizeof(unsigned);
    expect_d_eq(mallctl("arenas.nlextents", (void *)&num_large_extents, &value_size, NULL, 0),
        0, "Unexpected mallctl() error");

    mib_length = sizeof(ctl_mib) / sizeof(size_t);
    expect_d_eq(mallctlnametomib("arenas.lextent.0.size", ctl_mib, &mib_length), 0,
        "Unexpected mallctlnametomib() error");

    ctl_mib[2] = num_large_extents - 1;
    value_size = sizeof(size_t);
    expect_d_eq(mallctlbymib(ctl_mib, mib_length, (void *)&max_allocable_size, &value_size,
        NULL, 0), 0, "Unexpected mallctlbymib() error");

    expect_ptr_null(malloc(max_allocable_size + 1),
        "Expected OOM due to over-sized allocation request");
    expect_ptr_null(malloc(SIZE_T_MAX),
        "Expected OOM due to over-sized allocation request");
    expect_ptr_null(calloc(1, max_allocable_size + 1),
        "Expected OOM due to over-sized allocation request");
    expect_ptr_null(calloc(1, SIZE_T_MAX),
        "Expected OOM due to over-sized allocation request");

    ptr = malloc(1);
    expect_ptr_not_null(ptr, "Unexpected malloc() OOM");
    expect_ptr_null(realloc(ptr, max_allocable_size + 1),
        "Expected OOM due to over-sized allocation request");
    expect_ptr_null(realloc(ptr, SIZE_T_MAX),
        "Expected OOM due to over-sized allocation request");
    free(ptr);
}
TEST_END

/* Re-enable the "-Walloc-size-larger-than=" warning */
JEMALLOC_DIAGNOSTIC_POP

int
main(void) {
    return test(
        test_large_alloc_failure);
}

