        TTempFileHandle tmp("./test_locker.locker");
        TFileLock lockExcl1("./test_locker.locker");
        TFileLock lockExcl2("./test_locker.locker");
        TFileLock lockShare1("./test_locker.locker", EFileLockType::Shared);
        TFileLock lockShare2("./test_locker.locker", EFileLockType::Shared);
        TFileLock lockShare3("./test_locker.locker", EFileLockType::Shared);

        {
            TGuard<TFileLock> guard(lockExcl1);
        }

        {
            TTryGuard<TFileLock> tryGuard(lockExcl1);
            UNIT_ASSERT(tryGuard.WasAcquired());
        }

        {
            TGuard<TFileLock> guard1(lockExcl1);
            TTryGuard<TFileLock> guard2(lockExcl2);
            UNIT_ASSERT(!guard2.WasAcquired());
        }

        {
            TGuard<TFileLock> guard1(lockShare1);
            TTryGuard<TFileLock> guard2(lockShare2);
