#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<std::vector<int>> minimumAbsDifference(std::vector<int>& data) {
        int size = data.size();
        std::sort(data.begin(), data.end());

        if (size < 2) return {};

        int currentDiff = 0;
        int minDiff = data[1] - data[0];

        for (int index = 0; index < size - 1; ++index) {
            currentDiff = data[index + 1] - data[index];
            minDiff = std::min(currentDiff, minDiff);
        }

        std::vector<std::vector<int>> result;
        for (int pos = 0; pos < size - 1; ++pos) {
            if (data[pos + 1] - data[pos] == minDiff) {
                result.push_back({data[pos], data[pos + 1]});
            }
        }

        return result;
    }
};

