    reverse(numbers.begin(), numbers.end()); // reverse the vector in place
    cout << "Reversed vector: ";
    for(int element : numbers) { // iterate over the reversed vector
        cout << element << " "; // print each element in the reversed vector
    }
    cout << endl; // print a newline

    vector<int> partialNumbers = {1, 2, 3, 4, 5}; // vector of integers
    reverse(partialNumbers.begin(), partialNumbers.begin() + 3); // reverse the first 3 elements of the vector in place
    cout << "Partially reversed vector: ";
    for(int element : partialNumbers) { // iterate over the partially reversed vector
        cout << element << " "; // print each element in the partially reversed vector
    }
    cout << endl; // print a newline

    return 0;
}

