    std::cout << "direct_val: " << direct_val << std::endl;

    int static_copy = lua_vm["ExampleData"]["static_copy"];
    int static_ref = lua_vm["ExampleData"]["static_ref"];
    // static_copy == 25
    // static_ref == 25
    SOL_ASSERT(static_copy == 25);
    SOL_ASSERT(static_ref == 25);

    std::cout << "Initial values --" << std::endl;
    std::cout << static_copy << std::endl;
    std::cout << static_ref << std::endl;

    ExampleData::shared_value = 542;

    static_copy = lua_vm["ExampleData"]["static_copy"];
    // static_copy remains 25 (copy of original value)
    static_ref = lua_vm["ExampleData"]["static_ref"];
    // static_ref now reflects updated value (542) due to reference
    SOL_ASSERT(static_copy == 25);
    SOL_ASSERT(static_ref == 542);

    std::cout << "After modification --" << std::endl;
    std::cout << "static_copy : " << static_copy << std::endl;
    std::cout << "static_ref  : " << static_ref << std::endl;
    std::cout << std::endl;

