using namespace std;

class Solution {
public:
    bool searchMatrix(vector<vector<int>>& grid, int goal) {
        int rows = grid.size();
        int cols = grid[0].size();
        int row = 0;
        int col = cols - 1;
        while (row < rows && col >= 0) {
            int currentVal = grid[row][col];
            if (currentVal > goal) {
                col--;
            } else if (currentVal < goal) {
                row++;
            } else {
                return true;
            }
        }
        return false;
    }
};

