#include <iostream>
#include <vector>
#include <map>
#include <cstdlib>
using namespace std;

// Upper bound for N as specified in the problem constraints
const int MAX_SIZE = 200005;

// Array to hold the final sequence
int result_arr[MAX_SIZE];

// Map to track the first occurrence position of each unique value
map<int, int> first_occurrence;

/**
 * Recursive function to reconstruct the sorted array within range [start, end].
 * Employs a divide-and-conquer approach with optimizations leveraging sorted properties.
 */
void reconstruct(int start, int end) {
    // Skip already-filled positions from the left
    while (start <= end && result_arr[start] != 0) start++;
    // Skip already-filled positions from the right
    while (end >= start && result_arr[end] != 0) end--;

    // Terminate if the valid range is exhausted
    if (start > end) return;

    // Perform query on current segment
    cout << "? " << start << " " << end << endl;
    int value, frequency;
    cin >> value >> frequency;

    if (value == -1) exit(0); // Handle unexpected termination

    // Full coverage optimization: entire segment consists of 'value'
    if (frequency == end - start + 1) {
        for (int idx = start; idx <= end; ++idx) {
            result_arr[idx] = value;
        }
        first_occurrence[value] = start;
        return;
    }

    // Anchor-based optimization using previously recorded position of 'value'
    if (first_occurrence.find(value) != first_occurrence.end()) {
        int anchor_pos = first_occurrence[value];

        if (anchor_pos < start) {
            // Value block starts at 'start' and extends for 'frequency' elements
            for (int offset = 0; offset < frequency; ++offset) {
                result_arr[start + offset] = value;
            }
            first_occurrence[value] = start;
            // Continue processing remaining part
            reconstruct(start + frequency, end);
            return;
        } else if (anchor_pos > end) {
            // Value block ends at 'end' and spans 'frequency' elements backwards
            for (int offset = 0; offset < frequency; ++offset) {
                result_arr[end - offset] = value;
            }
            first_occurrence[value] = end;
            // Continue processing remaining part
            reconstruct(start, end - frequency);
            return;
        }
    }

    // Fallback: split range and process recursively
    int midpoint = (start + end) / 2;
    reconstruct(start, midpoint);
    reconstruct(midpoint + 1, end);
}

int main() {
    // Speed up I/O for interactive problems
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    // Initiate reconstruction for full array
    reconstruct(1, n);

    // Output final reconstructed array
    cout << "! ";
    for (int i = 1; i <= n; ++i) {
        cout << result_arr[i];
        if (i < n) cout << " ";
    }
    cout << endl;

    return 0;
}

