namespace yams::search {

bool SearchFilters::matches(const SearchResultItem& result) const {
    // Apply date constraints
    for (const auto& constraint : dateConstraints_) {
        std::chrono::system_clock::time_point checkDate;
        switch (constraint.field) {
            case DateRangeFilter::DateField::LastModified:
                checkDate = result.lastModified;
                break;
            case DateRangeFilter::DateField::Created:
                // Assuming creation timestamp is stored in metadata
                // For now, use lastModified as fallback
                checkDate = result.lastModified;
                break;
            case DateRangeFilter::DateField::Indexed:
                checkDate = result.indexedAt;
                break;
        }
        if (!constraint.satisfies(checkDate)) {
            return false;
        }
    }

    // Apply size constraints
    for (const auto& constraint : sizeConstraints_) {
        if (!constraint.satisfies(result.fileSize)) {
            return false;
        }
    }

    // Apply content type constraints
    for (const auto& constraint : contentTypeConstraints_) {
        if (!constraint.satisfies(result.contentType)) {
            return false;
        }
    }

    // Apply language constraints
    for (const auto& constraint : languageConstraints_) {
        if (!constraint.satisfies(result.detectedLanguage, result.languageConfidence)) {
            return false;
        }
    }

    // Apply path constraints
    for (const auto& constraint : pathConstraints_) {
        if (!constraint.satisfies(result.path)) {
            return false;
        }
    }

    // Apply metadata constraints
    for (const auto& constraint : metadataConstraints_) {
        if (!constraint.satisfies(result.metadata)) {
            return false;
        }
    }

    // Apply relevance constraints
    for (const auto& constraint : relevanceConstraints_) {
        if (!constraint.satisfies(result.relevanceScore)) {
            return false;
        }
    }

    // Apply user-defined filters
    for (const auto& filter : customFilters_) {
        if (!filter(result)) {
            return false;
        }
    }

    return true;
}

std::vector<SearchResultItem>
SearchFilters::apply(const std::vector<SearchResultItem>& results) const {
    if (!hasFilters()) {
        return results; // No filters present, return original list
    }

    std::vector<SearchResultItem> matchedItems;
    matchedItems.reserve(results.size());
    for (const auto& result : results) {
        if (matches(result)) {
            matchedItems.emplace_back(result);
        }
    }
    return matchedItems;
}

} // namespace yams::search

