#include "app_state.hpp"
#include "curses_interface.hpp"
#include <boost/filesystem/operations.hpp>
#include <boost/filesystem/path.hpp>
#include <iostream>

int main(int argc, char * argv[])
{
    if (argc < 2) {
        std::cerr << "error: You must supply at least a filename.\n";
        return 1;
    }

    boost::filesystem::path file_path(argv[1]);
    if (!exists(file_path)) {
        std::cerr << "error: Could not access filename " << argv[1] << ".\n";
        return 1;
    }

    // Requirement of libcurses.
    std::locale::global(std::locale(""));
    curses_interface_t curses_view;

    // Read the size, but just this once; resizing is not supported.
    auto const display_size = curses_view.screen_size();

    app_state_t app_state = {
        // Initial state is the contents of the file from the command line.
        load_buffer(file_path, curses_view.screen_size().col_),
        // Keybindings are simplified Emacs.
        emacs_lite()};

    // Initial render.
    render(app_state.buffer_, display_size);

    // Loop until the user says we're done.  Each iteration blocks for an
    // event from libcurses, then passes the current app state and the event
    // to update(), which returns the new app state.
    boost::optional<app_state_t> updated_app_state;
    while (
        (updated_app_state =
             update(std::move(app_state), curses_view.next_event()))) {
        app_state = *updated_app_state;
        render(app_state.buffer_, display_size);
    }
}

#include "flareqt/updatechecker.h"
#include <QNetworkReply>

UpdateChecker::UpdateChecker(QUrl const& updateUrl)
    : manager_(new QNetworkAccessManager(this),
               &QNetworkAccessManager::deleteLater) {
  connect(manager_.data(), SIGNAL(finished(QNetworkReply*)), this,
          SLOT(httpRequestFinished(QNetworkReply*)));
  manager_->get(QNetworkRequest(updateUrl));
}

void UpdateChecker::httpRequestFinished(QNetworkReply* pReply) {
  QSharedPointer<QNetworkReply> reply(pReply, &QNetworkReply::deleteLater);

  // Check for network errors and abort if present
  if (reply->error() != QNetworkReply::NoError) {
    emit done(true);
    return;
  }

  // Parse the server response into a version string
  QString newVersion = QString(reply->readAll()).trimmed();

  // Validate that the version string contains at least one dot
  if (newVersion.indexOf(".") < 0) {
    // Invalid format received; skip update check
    emit done(true);
    return;
  }

  // Store the latest version and signal completion
  m_latestVersion = newVersion;
  emit done(false);
}

#include "Context.h"
#include "oneDNN/Reorder.h"
using namespace kernels::xpu::oneDNN;
namespace at {
namespace AtenTypeXPU {

at::Tensor DPCPPTensorConvertor::to_plain(const at::Tensor& src_tensor) {
  if (!is_opaque_tensor(src_tensor))
    return src_tensor;

  auto current_tensor = src_tensor;

  // [note] the dtype in tensor's meta may differ from the one stored in its
  // context. During serialization, the storage is treated as raw u8 data and
  // pickled (see reorder during pickling:
  // https://github.com/pytorch/pytorch/blob/0f4652f4989a2d196f36fe75e5c73cb88dc0800d/torch/serialization.py#L667)
  // To ensure correctness before saving, block tensors must be converted to
  // plain format using the correct meta dtype.
  // If saving a block tensor, src_tensor is a pure u8 1-D tensor.
  // Thus, current_tensor must be rebuilt with the proper meta dtype inferred
  // from the context dtype of src_tensor. After reordering, the plain u8
  // tensor should be restored.

  // is_equal(false) indicates that the meta dtype differs from the stored
  // context dtype, requiring reconstruction for correct reordering.

  auto match_status = check_equality_for_meta_dtype_and_ctx_dtype(src_tensor);

  // Scenario A:
  //   Context holds actual dtype (e.g., f32, s8), but meta has u8 — occurs
  //   during tensor serialization. Execute this branch.
  // Scenario B:
  //   Opaque u8 quantized tensor has QUInt8 meta but s8 context — no need to
  //   serialize it; skip this branch.
  // Not handling scenarios A and B here.

  if (!match_status) {
    // Derive meta dtype via opaqueTypeToScalarType based on context dtype
    // Rebuild current_tensor with correct meta dtype
    current_tensor = at::empty_like(
        src_tensor,
        src_tensor.options().dtype(opaqueTypeToScalarType(src_tensor)));
    unsafe_get_and_set_data_ptr(src_tensor, current_tensor);
  }

  // Use native API to avoid recursive calls caused by opaque guard in ATen interface
  auto dest_tensor = at::empty_like(current_tensor);
  auto ctx = *(static_cast<DPCPPTensorContext*>(
      current_tensor.unsafeGetTensorImpl()->storage().data_ptr().get_context()));
  auto dest_meta = ctx.aten_meta();
  auto dest_view = share_storage_and_set_strided_as(
      dest_tensor, dest_meta.sizes_, dest_meta.strides_, c10::nullopt);

  kernels::xpu::oneDNN::reorder(current_tensor, dest_view);

  if (!match_status) {
    // Reconstruct dest_tensor with original tensor's meta
    dest_tensor = at::empty_like(src_tensor);
    // Transfer context from dest_view to dest_tensor; now dest_tensor is plain
    // and matches src_tensor's meta
    unsafe_release_and_set_data_ptr(dest_view, dest_tensor);
    // Explicitly free current_tensor's context
    current_tensor.unsafeGetTensorImpl()
        ->storage()
        .unsafeGetStorageImpl()
        ->mutable_data_ptr()
        .release_context();
  }

  return dest_tensor;
}

at::Tensor DPCPPTensorConvertor::to_plain_(at::Tensor& input_tensor) {
  if (!is_opaque_tensor(input_tensor))
    return input_tensor;

  auto result = to_plain(input_tensor);
  auto ctx = DPCPPTensorContext::get_tensor_ctx(result);
  DPCPPTensorContext::set_tensor_ctx(input_tensor, std::move(ctx));
  return input_tensor;
}

