int main(int argc, char* argv[]) {
    std::cout << "=== environment state ===" << std::endl;
    sol::state lua_state;
    lua_state.open_libraries();

    sol::environment custom_env(lua_state, sol::create);
    // set value, and we need to explicitly allow for
    // access to "print", since a new environment hides
    // everything that's not defined inside of it
    // NOTE: hiding also hides library functions (!!)
    // BE WARNED
    custom_env["value"] = 50;
    custom_env["print"] = lua_state["print"];

    sol::environment fallback_env(
         lua_state, sol::create, lua_state.globals());
    // do not need to explicitly allow access to "print",
    // since we used the "Set a fallback" version
    // of the sol::environment constructor
    fallback_env["value"] = 443;

    // output: 50
    lua_state.script("print(value)", custom_env);
    // output: 443
    lua_state.script("print(value)", fallback_env);

    std::cout << std::endl;
    return 0;
}

#include <vector>
#include <algorithm>

class Solution {
public:
    int minimumDifference(std::vector<int>& values, int windowSize) {
        int size = values.size();
        std::sort(values.begin(), values.end());
        if (size == 1) return 0;

        int smallestDiff = values[windowSize - 1] - values[0];

        for (int index = 1; index <= size - windowSize; index++) {
            int currentDiff = values[index + windowSize - 1] - values[index];
            smallestDiff = std::min(currentDiff, smallestDiff);
        }

        return smallestDiff;
    }
};

