#include <pthread.h>
#include "libcgo.h"

// Retrieve the stack bounds for the current thread
void
x_cgo_getstackbound(uintptr bounds[2])
{
    pthread_attr_t attributes;
    void *stack_addr;
    size_t stack_size;

    // Initialize the attribute structure before use
    pthread_attr_init(&attributes);

#if defined(__GLIBC__) || defined(__BIONIC__) || (defined(__sun) && !defined(__illumos__))
    // Use GNU extension pthread_getattr_np on glibc and Solaris (non-Illumos)
    pthread_getattr_np(pthread_self(), &attributes);
    pthread_attr_getstack(&attributes, &stack_addr, &stack_size);
#elif defined(__illumos__)
    // Illumos-specific function to get thread attributes
    pthread_attr_get_np(pthread_self(), &attributes);
    pthread_attr_getstack(&attributes, &stack_addr, &stack_size);
#else
    // Fallback: no known method to retrieve stack info; set to zero
    stack_addr = nullptr;
    stack_size = 0;
#endif

    // Clean up the attribute object
    pthread_attr_destroy(&attributes);

    // Synchronize with TSAN to avoid false positives regarding stack reuse
    _cgo_tsan_acquire();
    bounds[0] = reinterpret_cast<uintptr>(stack_addr);
    bounds[1] = reinterpret_cast<uintptr>(stack_addr) + stack_size;
    _cgo_tsan_release();
}

