#include <sys/socket.h>
#include <limits.h>
#include <errno.h>
#include "syscall.h"

// Send multiple messages on a socket using sendmmsg
int sendmmsg(int sockfd, struct mmsghdr *messages, unsigned int num_msgs, unsigned int send_flags)
{
#if LONG_MAX > INT_MAX
	/* Cannot invoke the syscall directly due to type mismatches:
	 * kernel uses different types for msg_iovlen, msg_controllen, cmsg_len,
	 * and in-place modification of control message buffers is disallowed. */
	int processed = 0;
	if (num_msgs > IOV_MAX) num_msgs = IOV_MAX; /* Aligns with kernel behavior. */
	if (!num_msgs) return 0;
	for (processed = 0; processed < num_msgs; processed++) {
		/* Inconsistency: sendmmsg API returns msg_len as unsigned int,
		 * while sendmsg returns ssize_t. Nevertheless, Linux caps the
		 * total bytes via sendmsg at INT_MAX, making the conversion safe. */
		ssize_t result = sendmsg(sockfd, &messages[processed].msg_hdr, send_flags);
		if (result < 0) goto failure;
		messages[processed].msg_len = result;
	}
failure:
	return processed ? processed : -1;
#else
	return syscall_cp(SYS_sendmmsg, sockfd, messages, num_msgs, send_flags);
#endif
}

