#include "jemalloc/internal/jemalloc_preamble.h"
#include "jemalloc/internal/jemalloc_internal_includes.h"
#include "jemalloc/internal/prof_stats.h"

bool opt_prof_stats = true;
malloc_mutex_t prof_stats_lock;
static prof_stats_t live_stats[PROF_SC_NSIZES];
static prof_stats_t accum_stats[PROF_SC_NSIZES];

static void
enter_prof_stats(tsd_t *tsd, szind_t index) {
    assert(opt_prof && opt_prof_stats);
    assert(index < SC_NSIZES);
    malloc_mutex_lock(tsd_tsdn(tsd), &prof_stats_lock);
}

static void
leave_prof_stats(tsd_t *tsd) {
    malloc_mutex_unlock(tsd_tsdn(tsd), &prof_stats_lock);
}

void
update_live_stats(tsd_t *tsd, szind_t index, size_t requested_size) {
    cassert(config_prof);
    enter_prof_stats(tsd, index);
    live_stats[index].req_sum += requested_size;
    live_stats[index].count++;
    accum_stats[index].req_sum += requested_size;
    accum_stats[index].count++;
    leave_prof_stats(tsd);
}

void
decrement_live_stats(tsd_t *tsd, szind_t index, size_t requested_size) {
    cassert(config_prof);
    enter_prof_stats(tsd, index);
    live_stats[index].req_sum -= requested_size;
    live_stats[index].count--;
    leave_prof_stats(tsd);
}

void
copy_live_stats(tsd_t *tsd, szind_t index, prof_stats_t *output_stats) {
    cassert(config_prof);
    enter_prof_stats(tsd, index);
    memcpy(output_stats, &live_stats[index], sizeof(prof_stats_t));
    leave_prof_stats(tsd);
}

void
copy_accum_stats(tsd_t *tsd, szind_t index, prof_stats_t *output_stats) {
    cassert(config_prof);
    enter_prof_stats(tsd, index);
    memcpy(output_stats, &accum_stats[index], sizeof(prof_stats_t));
    leave_prof_stats(tsd);
}

