#include "BufferProcessor.hpp"
#include "Buffer.hpp"
#include "MayaFlux/Journal/Archivist.hpp"

namespace MayaFlux::Buffers {

void BufferProcessor::handle_buffer(const std::shared_ptr<Buffer>& buf)
{
    if (!buf->attempt_acquire_for_processing()) {
        MF_RT_ERROR(Journal::Component::Buffers, Journal::Context::BufferProcessing,
            "Buffer is currently processed by another handler, skipping current operation");
        return;
    }
    m_in_progress.fetch_add(1, std::memory_order_acquire);
    try {
        process_callback(buf);
    } catch (...) {
        buf->finish_processing();
        m_in_progress.fetch_sub(1, std::memory_order_release);
        throw;
    }
    buf->finish_processing();
    m_in_progress.fetch_sub(1, std::memory_order_release);
}

void BufferProcessor::handle_non_owning(const std::shared_ptr<Buffer>& buf)
{
    m_in_progress.fetch_add(1, std::memory_order_acquire);
    try {
        process_callback(buf);
    } catch (...) {
        m_in_progress.fetch_sub(1, std::memory_order_release);
        throw;
    }
    m_in_progress.fetch_sub(1, std::memory_order_release);
}

