#include <algorithm>
#include <bit>

class Solution {
public:
    // Find the maximum gap between adjacent 1s in binary representation
    int binaryGap(unsigned value) {
        int maxGap = 0;
        int prevPosition = 32;

        for (; value > 0; value &= (value - 1)) {
            int currentBitPosition = countr_zero(value);
            maxGap = std::max(maxGap, currentBitPosition - prevPosition);
            prevPosition = currentBitPosition;
        }

        return maxGap;
    }
};

