#include <boost/capy/test/thread_name.hpp>
#include "test_helpers.hpp"

namespace boost {
namespace capy {

struct thread_name_test_suite
{
    void
    verify_thread_naming()
    {
#if defined(BOOST_CAPY_TEST_CAN_GET_THREAD_NAME)
        // Set and check basic thread names
        set_current_thread_name("my-test-thread");
        BOOST_TEST(check_thread_name("my-test-thread"));

        set_current_thread_name("capy-pool-1");
        BOOST_TEST(check_thread_name("capy-pool-1"));

        // Test long name truncation behavior
        set_current_thread_name(
            "this-is-an-extremely-long-thread-name-that-definitely-exceeds-all-limits");

#if defined(__linux__) || defined(__FreeBSD__) || defined(__NetBSD__)
        // Linux/FreeBSD/NetBSD: 16-byte limit (15 chars + null terminator)
        BOOST_TEST(check_thread_name("this-is-an-extre"));
#elif defined(__APPLE__)
        // macOS: up to 64 characters (63 + null)
        BOOST_TEST(check_thread_name(
            "this-is-an-extremely-long-thread-name-that-definitely-exceeds-all-limits"));
#elif defined(_WIN32)
        // Windows: no practical limit for UTF-8
        BOOST_TEST(check_thread_name(
            "this-is-an-extremely-long-thread-name-that-definitely-exceeds-all-limits"));
#endif

        // Verify macOS-specific 63-character limit
        set_current_thread_name(
            "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789ABCDEF");

#if defined(__APPLE__)
        // Should be truncated to first 63 characters
        BOOST_TEST(check_thread_name(
            "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789ABCDE"));
#endif

#if defined(_WIN32)
        // Additional Windows-specific test with UTF-8 ASCII subset
        set_current_thread_name("worker-queue-2");
        BOOST_TEST(check_thread_name("worker-queue-2"));
#endif
#endif // BOOST_CAPY_TEST_CAN_GET_THREAD_NAME

        // Edge case: empty string should not cause crash
        // Result is platform-dependent, so we don't assert on it
        set_current_thread_name("");
    }

    void
    execute_tests()
    {
        verify_thread_naming();
    }
};

TEST_SUITE(
    thread_name_test_suite,
    "boost.capy.thread_name");

} // capy
} // boost

