#include <hip/hip_runtime.h>
#include <cstddef>
#include <cstdlib>
#include <iostream>

#define HIP_ERROR_CHECK(expr)                         \
{                                                     \
    hipError_t err = expr;                            \
    if (err != hipSuccess)                            \
    {                                                 \
        std::cerr << "HIP runtime error: " << err     \
                  << " (" << hipGetErrorString(err)   \
                  << ") at " << __FILE__ << ":"       \
                  << __LINE__ << std::endl;           \
        std::exit(EXIT_FAILURE);                      \
    }                                                 \
}

int main()
{
    hipMemPool_t pool;
    int devId = 0; // Device identifier

    // Set the active device
    HIP_ERROR_CHECK(hipSetDevice(devId));

    // Retrieve the default memory pool for the selected device
    HIP_ERROR_CHECK(hipDeviceGetDefaultMemPool(&pool, devId));

    // Request a memory block of size 2 MB
    std::size_t bytesRequested = 2 * 1024 * 1024;
    void* devicePtr = nullptr;
    HIP_ERROR_CHECK(hipMalloc(&devicePtr, bytesRequested));

    // Release the allocated memory back to the system
    HIP_ERROR_CHECK(hipFree(devicePtr));

    // Reduce the pool's reserved memory to 768 KB
    std::size_t targetSize = 768 * 1024;
    HIP_ERROR_CHECK(hipMemPoolTrimTo(pool, targetSize));

    std::cout << "Memory pool successfully trimmed to " 
              << targetSize << " bytes." << std::endl;

    return EXIT_SUCCESS;
}

