bool FCrashDebugHelperWindows::ProduceMinidumpDiagnosticReport(const FString& InDumpFilePath)
{
	FWindowsPlatformStackWalkExt StackWalker(CrashInfo);
	const bool bInitialized = StackWalker.StartStackWalking();
	bool bSuccess = false;

	if (bInitialized && StackWalker.LoadDumpFile(InDumpFilePath))
	{
		if (CrashInfo.SourceRevision != FCrashInfo::INVALID_CHANGELIST)
		{
			// Retrieve executable version and module information
			FCrashModuleInfo ExecutableVersion;
			StackWalker.RetrieveExeVersionAndModules(ExecutableVersion);

			// Initialize symbol resolution
			StackWalker.InitializeSymbols();

			// Configure symbol search paths using loaded modules
			StackWalker.ConfigureSymbolPathsFromLoadedModules();

			// Extract detailed module metadata
			StackWalker.FetchDetailedModuleData();

			// Acquire system context details
			StackWalker.AcquireSystemContext();

			// Gather thread state information
			StackWalker.CollectThreadDetails();

			// Extract exception context
			StackWalker.ExtractExceptionDetails();

			// Generate stack traces for all threads
			StackWalker.GenerateThreadStackTraces();

			// Embed source code context around crash location
			IncludeSourceContextInReport();

			// Mark success
			bSuccess = true;
		}
		else
		{
			UE_LOG(LogCrashDebugHelper, Warning, TEXT("Changelist identifier is invalid"));
		}
	}
	else
	{
		UE_LOG(LogCrashDebugHelper, Warning, TEXT("Unable to open dump file: %s"), *InDumpFilePath);
	}

	return bSuccess;
}

