#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>

int size;
std::vector<std::vector<int>> parity_table;

// Retrieves parity_table[left][right] safely; returns 0 when left >= right,
// since ranges with no elements or just one element have zero inversions.
int fetch_safe(int left, int right) {
    if (left >= right) {
        return 0;
    }
    return parity_table[left][right];
}

// Computes whether p[i] > p[j] modulo 2 for i < j using precomputed data.
// Based on inclusion-exclusion applied to inversion counts.
int compute_relation(int pos_i, int pos_j) {
    return fetch_safe(pos_i, pos_j) ^ 
           fetch_safe(pos_i + 1, pos_j) ^ 
           fetch_safe(pos_i, pos_j - 1) ^ 
           fetch_safe(pos_i + 1, pos_j - 1);
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::cin >> size;

    // Handle base case: single element permutation
    if (size == 1) {
        std::cout << "1 1" << std::endl;
        return 0;
    }

    // Precompute all pairwise inversion parities for subarrays [l, r]
    parity_table.assign(size + 2, std::vector<int>(size + 2, 0));
    for (int left = 1; left <= size; ++left) {
        for (int right = left + 1; right <= size; ++right) {
            std::cout << "0 " << left << " " << right << std::endl;
            std::cin >> parity_table[left][right];
        }
    }

    // Prepare index list [1, 2, ..., size]
    std::vector<int> positions(size);
    std::iota(positions.begin(), positions.end(), 1);

    // Sort positions based on underlying permutation values using stable sort
    std::stable_sort(positions.begin(), positions.end(), [&](int idx_a, int idx_b) {
        if (idx_a == idx_b) return false;

        // Return true if p[idx_a] < p[idx_b]
        if (idx_a < idx_b) {
            // p[idx_a] < p[idx_b] iff [p[idx_a] > p[idx_b]] == 0
            return compute_relation(idx_a, idx_b) == 0;
        } else { // idx_a > idx_b
            // p[idx_a] < p[idx_b] iff [p[idx_b] > p[idx_a]] == 1
            return compute_relation(idx_b, idx_a) == 1;
        }
    });

    // Build inverse permutation: p[pos] = value at position pos
    std::vector<int> perm(size + 1);
    for (int rank = 0; rank < size; ++rank) {
        perm[positions[rank]] = rank + 1;
    }

    // Output result in required format
    std::cout << "1 ";
    for (int idx = 1; idx <= size; ++idx) {
        std::cout << perm[idx];
        if (idx != size) std::cout << " ";
    }
    std::cout << std::endl;

    return 0;
}

#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>
#include <string>
#include <iostream>

// Demonstrates accessing and extracting data from Lua tables
int main() {
    std::cout << "=== table access ===" << std::endl;
    sol::state lua_vm;

    // Initialize a Lua array-style table
    lua_vm.script(R"(arrayTable = {"data", "info"})");

    // Initialize a nested Lua table with key-value pairs
    lua_vm.script(R"(
        complexTable = {
            ["inner"] = {
                ["first"] = "alpha",
                ["second"] = "beta",
            },
            ["label"] = "complexTable",
        }
    )");

    /* Compact retrieval approach: */
    // Extract values directly from arrayTable
    /*std::cout << (std::string)lua_vm["arrayTable"][1] << " "
         << (std::string)lua_vm["arrayTable"][2] << '\n';*/

    // Retrieve values from the nested structure using chained access
    auto outerTable = lua_vm.get<sol::table>("complexTable");
    auto innerTable = outerTable.get<sol::table>("inner");

    // Alternative method:
    // sol::table outerTable = lua_vm["complexTable"];
    // sol::table innerTable = outerTable["inner"];

    std::string valueB = lua_vm["complexTable"]["inner"]["second"];
    std::cout << "inner table: first : "
              << innerTable.get<std::string>("first")
              << ", second: " << valueB << '\n';

    std::cout << "label of outer: " << outerTable.get<std::string>("label")
              << '\n';

    std::string labelStr = outerTable["label"];
    std::cout << "label of outer: " << labelStr << '\n';

    /* Explicit retrieval approach: */
    // Direct extraction from arrayTable using get<>
    std::cout << lua_vm.get<sol::table>("arrayTable").get<std::string>(
         1) << " "
              << lua_vm.get<sol::table>("arrayTable").get<std::string>(
                      2)
              << '\n';

    // Nested value extraction via chained get<> calls
    std::cout << "inner table: first : "
              << innerTable.get<std::string>("first")
              << ", second: "
              // Chaining get<> calls for nested access
              << lua_vm.get<sol::table>("complexTable")
                      .get<sol::table>("inner")
                      .get<std::string>("second")
              << '\n';

    std::cout << "label of outer: " << outerTable.get<std::string>("label")
              << '\n';

    std::cout << std::endl;
    return 0;
}

