#include "ByteArrayInputStream.h"
#include <cstddef>
#include "util/console/ArrayWithLength.h"
#include "win/extraX64.h"

// Constructor: initializes stream with specified buffer, offset, and length
ByteArrayInputStream::ByteArrayInputStream(
    byteArray    buffer,
    unsigned int startOffset,
    unsigned int maxLength
)
: currentPos(startOffset),
  totalBytes(std::min(startOffset + maxLength, buffer.length)),
  markPosition(startOffset) {
    this->buffer = buffer;
}

// Creates a ByteArrayInputStream using the provided buffer as its internal storage.
// The buffer is not duplicated; ownership remains with the caller.
// Initial position (currentPos) is set to 0, and totalBytes equals buffer.length.
ByteArrayInputStream::ByteArrayInputStream(byteArray buffer)
: currentPos(0),
  totalBytes(buffer.length),
  markPosition(0) {
    this->buffer = buffer;
}

// Reads a single byte from the stream.
// Returns the byte value (0-255) or -1 if no more data is available.
int ByteArrayInputStream::read() {
    if (currentPos >= totalBytes) return -1;
    else return buffer[currentPos++];
}

// Reads multiple bytes into the provided buffer b.
// Equivalent to calling read(b, 0, b.length).
int ByteArrayInputStream::read(byteArray b) { return read(b, 0, b.length); }

// Reads up to 'length' bytes into array 'b', starting at index 'offset'.
// Returns the number of bytes actually read, or -1 if end-of-stream reached.
int ByteArrayInputStream::read(
    byteArray    destinationBuffer,
    unsigned int destOffset,
    unsigned int maxBytesToRead
) {
    if (currentPos == totalBytes) return -1;

    int bytesRead = std::min(maxBytesToRead, totalBytes - currentPos);
    XMemCpy(&destinationBuffer[destOffset], &buffer[currentPos], bytesRead);

    currentPos += bytesRead;
    return bytesRead;
}

// No-op implementation: closing a ByteArrayInputStream has no effect.
void ByteArrayInputStream::close() { return; }

// Skips up to 'n' bytes forward in the stream.
// Returns the actual number of bytes skipped.
std::int64_t ByteArrayInputStream::skip(std::int64_t n) {
    std::int64_t proposedNewPos = currentPos + n;
    if (proposedNewPos > totalBytes) proposedNewPos = totalBytes;

    std::int64_t skipped = proposedNewPos - currentPos;
    currentPos = static_cast<unsigned int>(proposedNewPos);
    return skipped;
}

// Destructor: releases allocated memory for the internal buffer if owned.
ByteArrayInputStream::~ByteArrayInputStream() {
    if (buffer.data != nullptr) delete[] buffer.data;
}

