// tolua code lifted from some blog, if the link dies
// I don't know where else you're gonna find the reference,
// http://usefulgamedev.weebly.com/tolua-example.html
/* NOTE: there is no sol_lua_interop_get here,
 because tolua types are -- thankfully -- memory-compatible
 in most cases with sol.
 Please check other examples like kaguya or LuaBribe for an
 example of how to also write the getter for your type*/
template <typename T, typename Handler>
inline bool sol_lua_interop_check(sol::types<T>, lua_State* L,
     int position, sol::type stack_index_type, Handler&& callback,
     sol::stack::record& usage_tracking) {
	usage_tracking.use(1);
	// just marking unused parameters for no compiler warnings
	(void)stack_index_type;
	(void)callback;
	int abs_index = lua_absindex(L, position);
	std::string class_name = sol::detail::short_demangle<T>();
	tolua_Error tolua_err {};
	int result = tolua_isusertype(
	     L, abs_index, class_name.c_str(), 0, &tolua_err);
	if (result == 0) {
		// tolua seems to leave garbage on the stack
		// when the check fails
		// thanks, tolua
		lua_pop(L, 2);
		return false;
	}
	return true;
}
void setup_sol_bindings(lua_State* L) {
	// grab raw state and put into state_view
	// state_view is cheap to construct
	sol::state_view lua(L);
	// bind and set up your things: everything is entirely
	// self-contained
	lua["process"] = sol::overload(
	     [](Character& from_tolua) {
		     std::cout << "invoking single-parameter variant with "
		                  "tolua-generated Character { vitality:"
		               << from_tolia.getVitality() << " }"
		               << std::endl;
		     SOL_ASSERT(from_tolua.getVitality() == 7);
	     },
	     [](Character& from_tolua, float extra_param) {
		     std::cout << "invoking two-parameter variant with "
		                  "tolua-generated Character { vitality: "
		               << from_tolua.getVitality()
		               << " } and floating-point argument of "
		               << extra_param << std::endl;
		     SOL_ASSERT(from_tolua.getVitality() == 7);
		     SOL_ASSERT(extra_param == 3.14f);
	     });
}
void validate_via_sol(lua_State* L) {
	sol::state_view lua(L);
	Character& instance = lua["character"];
	(void)instance;
	SOL_ASSERT(instance.getVitality() == 7);
}
int main(int argc, char* argv[]) {
	(void)argc;
	(void)argv;
	std::cout << "=== interop demonstration (tolua) ===" << std::endl;
	std::cout << "(code adapted from a sol2 user's scenario: "
	             "https://github.com/ThePhD/sol2/issues/"
	             "511#issuecomment-331729884)"
	          << std::endl;
	lua_State* L = luaL_newstate();
	luaL_openlibs(
	     L); // initialize all lua standard library functions
	tolua_open(L); // initialize tolua
	tolua_Character_open(
	     L); // make Character class accessible from LUA
	setup_sol_bindings(L);
	const auto script = R"(
character = Character:new()
character:setVitality(7)
process(character) -- invoke one-argument version
process(character, 3.14) -- invoke two-argument version
)";
	if (luaL_dostring(L, script)) {
		lua_error(L); // crash on error
	}
	validate_via_sol(L);
	return 0;
}

