// Destructor for ValueSymbolTable
ValueSymbolTable::~ValueSymbolTable() {
#ifndef NDEBUG
  // Only perform checks in debug builds
  for (const auto &VI : vmap) {
    dbgs() << "Value still present in symbol table! Type = '"
           << *VI.getValue()->getType() << "' Name = '" << VI.getKeyData()
           << "'\n";
  }
  assert(vmap.empty() && "Values remain in the symbol table!");
#endif
}

// Generate a unique name for a value by appending a suffix
ValueName *ValueSymbolTable::makeUniqueName(Value *V,
                                            SmallString<256> &UniqueName) {
  unsigned BaseSize = UniqueName.size();
  while (true) {
    // Reset to base size and append next unique number
    UniqueName.resize(BaseSize);
    raw_svector_ostream S(UniqueName);

    if (auto *GV = dyn_cast<GlobalValue>(V)) {
      const Module *M = GV->getParent();
      // Append dot separator unless targeting NVPTX (which doesn't allow dots)
      if (!(M && Triple(M->getTargetTriple()).isNVPTX()))
        S << ".";
    }

    S << ++LastUnique;

    // Attempt insertion into the map
    auto IterBool = vmap.insert(std::make_pair(UniqueName.str(), V));
    if (IterBool.second)
      return &*IterBool.first;
  }
}

// Re-insert a named value, renaming it if necessary
void ValueSymbolTable::reinsertValue(Value *V) {
  assert(V->hasName() && "Cannot insert a nameless Value into symbol table");

  // Try inserting directly first
  if (vmap.insert(V->getValueName())) {
    return;
  }

  // Conflict: rename the value
  SmallString<256> UniqueName(V->getName().begin(), V->getName().end());

  MallocAllocator Allocator;
  V->getValueName()->Destroy(Allocator);

  ValueName *VN = makeUniqueName(V, UniqueName);
  V->setValueName(VN);
}

// Remove a value name from the symbol table
void ValueSymbolTable::removeValueName(ValueName *V) {
  vmap.remove(V);
}

// Create a new value name, auto-renaming on conflict
ValueName *ValueSymbolTable::createValueName(StringRef Name, Value *V) {
  // Truncate if exceeding max allowed size
  if (MaxNameSize > -1 && Name.size() > (unsigned)MaxNameSize)
    Name = Name.substr(0, std::max(1u, (unsigned)MaxNameSize));

  // Common case: no conflict
  auto IterBool = vmap.insert(std::make_pair(Name, V));
  if (IterBool.second) {
    return &*IterBool.first;
  }

  // Conflict: generate a unique name
  SmallString<256> UniqueName(Name.begin(), Name.end());
  return makeUniqueName(V, UniqueName);
}

#if !defined(NDEBUG) || defined(LLVM_ENABLE_DUMP)
// Debug dump method
LLVM_DUMP_METHOD void ValueSymbolTable::dump() const {
  for (const auto &I : *this) {
    I.getValue()->dump();
  }
}
#endif

