#include <array>
#include <iostream>
#include <string>
#include "asio.hpp"

constexpr unsigned short udp_multicast_port = 30001;

class multicast_listener
{
public:
  multicast_listener(asio::io_context& context,
      const asio::ip::address& bind_addr,
      const asio::ip::address& group_addr)
    : socket_(context)
  {
    // Configure the UDP socket for multicast reception
    asio::ip::udp::endpoint endpoint(bind_addr, udp_multicast_port);
    socket_.open(endpoint.protocol());
    socket_.set_option(asio::ip::udp::socket::reuse_address(true));
    socket_.bind(endpoint);

    // Subscribe to the multicast group
    socket_.set_option(asio::ip::multicast::join_group(group_addr));

    start_receiving();
  }

private:
  void start_receiving()
  {
    socket_.async_receive_from(
        asio::buffer(buffer_), remote_endpoint_,
        [this](std::error_code error, std::size_t bytes_transferred)
        {
          if (!error)
          {
            std::cout.write(buffer_.data(), bytes_transferred);
            std::cout << std::endl;
            start_receiving();
          }
        });
  }

  asio::ip::udp::socket socket_;
  asio::ip::udp::endpoint remote_endpoint_;
  std::array<char, 2048> buffer_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 3)
    {
      std::cerr << "Usage: multicast_receiver <listen_address> <group_address>\n";
      std::cerr << "  For IPv4, try:\n";
      std::cerr << "    multicast_receiver 0.0.0.0 239.255.0.1\n";
      std::cerr << "  For IPv6, try:\n";
      std::cerr << "    multicast_receiver :: ff31::8000:1234\n";
      return 1;
    }

    asio::io_context io_context;
    multicast_listener listener(io_context,
        asio::ip::make_address(argv[1]),
        asio::ip::make_address(argv[2]));

    io_context.run();
  }
  catch (const std::exception& exception)
  {
    std::cerr << "Error: " << exception.what() << "\n";
    return 1;
  }

  return 0;
}

#include <vector>
#include <climits>
#include <algorithm>

class Solution {
public:
    // Find minimum cost by checking all valid triplets
    int minimumCost(std::vector<int>& nums) {
        int length = nums.size();
        int result = INT_MAX;

        for (int i = 1; i < length - 1; i++) {
            for (int j = i + 1; j < length; j++) {
                int currentSum = nums[0] + nums[i] + nums[j];
                result = std::min(currentSum, result);
            }
        }

        return result;
    }
};

