#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>

// Process a single test scenario
void run_case() {
    int size;
    std::cin >> size;

    // Set up initial list of possible pens (0-indexed)
    std::vector<int> pool(size);
    std::iota(pool.begin(), pool.end(), 0);

    // Continue eliminating until only two remain
    while (pool.size() > 2) {
        std::vector<int> survivors;

        // Handle odd count: last pen advances automatically
        if (pool.size() % 2 == 1) {
            survivors.push_back(pool.back());
            pool.pop_back();
        }

        // Compare pairs and keep winners
        for (size_t idx = 0; idx < pool.size(); idx += 2) {
            int first = pool[idx];
            int second = pool[idx + 1];

            // Check first pen
            std::cout << "0 " << first << std::endl;
            int result_first;
            std::cin >> result_first;

            // Check second pen
            std::cout << "0 " << second << std::endl;
            int result_second;
            std::cin >> result_second;

            // Winner selection logic:
            // If first has ink (result_first == 1), it wins
            // Otherwise, second pen wins
            if (result_first == 1) {
                survivors.push_back(first);
            } else {
                survivors.push_back(second);
            }
        }

        // Update pool for next round
        pool = survivors;
    }

    // Report the final pair
    std::cout << "1 " << pool[0] << " " << pool[1] << std::endl;
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    for (int case_num = 0; case_num < test_cases; ++case_num) {
        run_case();
    }

    return 0;
}

