#include <iostream>
#include <vector>
#include <queue>
#include <climits>
#include <list>

using namespace std;

class WeightedGraph {
public:
    int numVertices; // Total number of vertices in the graph
    list<pair<int, int>>* adjacencyList; // Adjacency list representation

    WeightedGraph(int V) {
        numVertices = V;
        adjacencyList = new list<pair<int, int>>[V];
    }

    void insertEdge(int fromNode, int toNode, int edgeWeight) {
        adjacencyList[fromNode].push_back({toNode, edgeWeight});
        adjacencyList[toNode].push_back({fromNode, edgeWeight}); // Undirected graph: add both directions
    }

    void computeShortestPaths(int startVertex) {
        // Min-heap priority queue: (distance, vertex)
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> minHeap;

        // Initialize distances to infinity except for the source
        vector<int> shortestDistances(numVertices, INT_MAX);
        minHeap.push({0, startVertex});
        shortestDistances[startVertex] = 0;

        while (!minHeap.empty()) {
            int currentVertex = minHeap.top().second;
            minHeap.pop();

            // Explore all neighbors of the current vertex
            for (auto& edge : adjacencyList[currentVertex]) {
                int adjacentVertex = edge.first;
                int weight = edge.second;

                // Relaxation step: update distance if shorter path found
                if (shortestDistances[currentVertex] + weight < shortestDistances[adjacentVertex]) {
                    shortestDistances[adjacentVertex] = shortestDistances[currentVertex] + weight;
                    minHeap.push({shortestDistances[adjacentVertex], adjacentVertex});
                }
            }
        }

        // Output results
        cout << "Node\tDistance from Source" << endl;
        for (int i = 0; i < numVertices; i++) {
            cout << i << "\t" << shortestDistances[i] << endl;
        }
    }

    void displayGraphStructure() {
        for (int i = 0; i < numVertices; i++) {
            cout << "Node " << i << ":";
            for (auto& edge : adjacencyList[i]) {
                cout << " -> (" << edge.first << ", " << edge.second << ")";
            }
            cout << endl;
        }
    }
};

int main() {
    WeightedGraph g(5);
    g.insertEdge(0, 1, 10);
    g.insertEdge(0, 2, 5);
    g.insertEdge(1, 2, 2);
    g.insertEdge(1, 3, 1);
    g.insertEdge(2, 1, 3);
    g.insertEdge(2, 3, 9);
    g.insertEdge(2, 4, 2);
    g.insertEdge(3, 4, 4);

    cout << "Running Dijkstra's Algorithm from node 0:" << endl;
    g.computeShortestPaths(0);

    return 0;
}
// Dijkstra's Algorithm is a well-known method for finding the shortest paths from a source vertex 
// to all other vertices in a weighted graph with non-negative edge weights.
// Implementation uses a min-priority queue for optimal performance.
// Time Complexity: O((V + E) log V), where V is vertices count and E is edges count.
// Space Complexity: O(V) for storing distances and the priority queue.

