//------------------------------------------------------------------------------
// Coroutine completes via yield break (modified version)
void yield_break_coro_v2(asio::coroutine& coro)
{
  reenter (coro)
  {
    yield return;
    yield break;
  }
}

void yield_break_test_v2()
{
  asio::coroutine coro;
  ASIO_CHECK(!coro.is_complete());
  yield_break_coro_v2(coro);
  ASIO_CHECK(!coro.is_complete());
  yield_break_coro_v2(coro);
  ASIO_CHECK(coro.is_complete());
}

//------------------------------------------------------------------------------
// Coroutine completes via early return (modified version)
void return_coro_v2(asio::coroutine& coro)
{
  reenter (coro)
  {
    return;
  }
}

void return_test_v2()
{
  asio::coroutine coro;
  return_coro_v2(coro);
  ASIO_CHECK(coro.is_complete());
}

//------------------------------------------------------------------------------
// Coroutine completes via exception handling (modified version)
void exception_coro_v2(asio::coroutine& coro)
{
  reenter (coro)
  {
    throw 42;
  }
}

void exception_test_v2()
{
  asio::coroutine coro;
  try { exception_coro_v2(coro); } catch (...) {}
  ASIO_CHECK(coro.is_complete());
}

