// Coroutine completes by falling off the end (modified version)
void fall_off_end_coro_v2(asio::coroutine& coro)
{
  reenter (coro)
  {
    int dummy = 0;
    dummy++;
  }
}

void fall_off_end_test_v2()
{
  asio::coroutine coro;
  fall_off_end_coro_v2(coro);
  ASIO_CHECK(coro.is_complete());
}

