#include <vector>
#include <algorithm>

class Solution {
public:
    int findContentChildren(std::vector<int>& children, std::vector<int>& cookies) {
        int childCount = children.size();
        int cookieCount = cookies.size();

        std::sort(children.begin(), children.end());
        std::sort(cookies.begin(), cookies.end());

        int childIndex = 0;
        int cookieIndex = 0;
        int assignedCount = 0;

        while (childIndex < childCount && cookieIndex < cookieCount) {
            if (children[childIndex] <= cookies[cookieIndex]) {
                assignedCount++;
                childIndex++;
                cookieIndex++;
            } else {
                cookieIndex++;
            }
        }

        return assignedCount;      
    }
};

