    shared_const_buffer time_buffer(std::ctime(&current_time));
    auto self(shared_from_this());

    asio::async_write(socket_, time_buffer,
        [this, self](std::error_code err_code, std::size_t /*bytes_transferred*/)
        {
          // Write operation completed
        });
  }

  // The socket used to communicate with the client.
  tcp::socket socket_;
};

class server_instance
{
public:
  server_instance(asio::io_context& service_context, short listening_port)
    : acceptor_(service_context, tcp::endpoint(tcp::v4(), listening_port))
  {
    start_accepting();
  }

private:
  void start_accepting()
  {
    acceptor_.async_accept(
        [this](std::error_code error_code, tcp::socket accepted_socket)
        {
          if (!error_code)
          {
            std::make_shared<connection_handler>(std::move(accepted_socket))->initiate();
          }
          start_accepting();
        });
  }

  tcp::acceptor acceptor_;
};

