#include "llvm/Analysis/ScalarEvolutionNormalization.h"
#include "llvm/Analysis/LoopInfo.h"
#include "llvm/Analysis/ScalarEvolution.h"
#include "llvm/Analysis/ScalarEvolutionExpressions.h"

using namespace llvm;

/// OperationType - Variants of transformations supported by RewriteForPostInc.
enum OperationType {
  /// ShiftDown - Adjust expression to be compatible with post-increment semantics.
  ShiftDown,
  /// ShiftUp   - Reverse the adjustment, restoring original semantics.
  ShiftUp
};

namespace {

class TransformRewriter : public SCEVRewriteVisitor<TransformRewriter> {
  const OperationType Op;
  const NormalizePredTy Constraint;

public:
  TransformRewriter(OperationType Kind, NormalizePredTy Pred, ScalarEvolution &S)
      : SCEVRewriteVisitor<TransformRewriter>(S), Op(Kind), Constraint(Pred) {}

  const SCEV *visitAddRecExpr(const SCEVAddRecExpr *Expr);
};

} // end anonymous namespace

const SCEV *
TransformRewriter::visitAddRecExpr(const SCEVAddRecExpr *AR) {
  SmallVector<const SCEV *, 8> NewOps;
  std::transform(AR->operands().begin(), AR->operands().end(),
                 std::back_inserter(NewOps),
                 [this](const SCEV *E) { return this->visit(E); });

  if (!Constraint(AR))
    return SE.getAddRecExpr(NewOps, AR->getLoop(), SCEV::FlagAnyWrap);

  // Shifting down/up corresponds to decrementing/incrementing the recurrence
  // relative to its associated loop.
  if (Op == ShiftUp) {
    // ShiftUp: partial increment — similar to getPostIncExpr but done explicitly.
    for (size_t idx = 0, last = NewOps.size() - 1; idx < last; ++idx)
      NewOps[idx] = SE.getAddExpr(NewOps[idx], NewOps[idx + 1]);
  } else {
    assert(Op == ShiftDown && "Only two operation types exist!");
    // ShiftDown: partial decrement — more involved due to changing step.
    //
    // Recursive construction from least-significant operand:
    //
    // Base: single-term addrec is self-normalizing.
    //
    // Inductive step: For {A_{n-1},+,A_{n-2},+,...,+,A_0},
    // let S = {A_{n-2},+,...,+,A_0} be the step recurrence.
    // Its normalized form N(S) is known by induction.
    // Then normalized full expr = A_{n-1} - N(S).
    for (int pos = static_cast<int>(NewOps.size()) - 2; pos >= 0; --pos)
      NewOps[pos] = SE.getMinusSCEV(NewOps[pos], NewOps[pos + 1]);
  }

  return SE.getAddRecExpr(NewOps, AR->getLoop(), SCEV::FlagAnyWrap);
}

const SCEV *llvm::normalizeForPostIncUse(const SCEV *Expr,
                                         const PostIncLoopSet &TargetLoops,
                                         ScalarEvolution &SE,
                                         bool VerifyInvertible) {
  if (TargetLoops.empty())
    return Expr;

  auto MatchLoop = [&](const SCEVAddRecExpr *AR) {
    return TargetLoops.contains(AR->getLoop());
  };

  const SCEV *Adjusted =
      TransformRewriter(ShiftDown, MatchLoop, SE).visit(Expr);

  const SCEV *Restored = denormalizeForPostIncUse(Adjusted, TargetLoops, SE);

  if (VerifyInvertible && Restored != Expr)
    return nullptr;

  return Adjusted;
}

const SCEV *llvm::normalizeForPostIncUseIf(const SCEV *Expr,
                                           NormalizePredTy Pred,
                                           ScalarEvolution &SE) {
  return TransformRewriter(ShiftDown, Pred, SE).visit(Expr);
}

const SCEV *llvm::denormalizeForPostIncUse(const SCEV *Expr,
                                           const PostIncLoopSet &TargetLoops,
                                           ScalarEvolution &SE) {
  if (TargetLoops.empty())
    return Expr;

  auto MatchLoop = [&](const SCEVAddRecExpr *AR) {
    return TargetLoops.contains(AR->getLoop());
  };

  return TransformRewriter(ShiftUp, MatchLoop, SE).visit(Expr);
}

#include <vector>
#include <cmath>

class Solution {
public:
    std::vector<int> findDisappearedNumbers(std::vector<int>& inputArray) {
        int size = inputArray.size();

        // Mark the presence of numbers by negating values at corresponding indices
        for (int i = 0; i < size; ++i) {
            int position = std::abs(inputArray[i]) - 1;
            if (inputArray[position] > 0) {
                inputArray[position] = -inputArray[position];
            }
        }

        // Collect indices that have positive values (missing numbers)
        std::vector<int> result;
        for (int i = 0; i < size; ++i) {
            if (inputArray[i] > 0) {
                result.push_back(i + 1);
            }
        }

        return result;
    }
};

#include "ptn/patternia.hpp"
#include "parse_json_pred.hpp"
#include "parse_json_handler.hpp"

using namespace ptn;

// Recursive JSON parser with depth-based indentation
void parse_json(const json &j, int level = 0) {
  match(j)
      .when(bind()[is_type(json::value_t::null)] >> print_null(level))
      .when(bind()[is_type(json::value_t::boolean)] >> print_bool(level))
      .when(
          bind()[is_type(json::value_t::number_integer)] >>
          print_number<int>("int", level))
      .when(
          bind()[is_type(json::value_t::number_unsigned)] >>
          print_number<unsigned>("uint", level))
      .when(
          bind()[is_type(json::value_t::number_float)] >>
          print_number<double>("float", level))
      .when(bind()[is_type(json::value_t::string)] >> print_string(level))
      .when(
          bind()[is_empty_array] >>
          [=](const json &) {
            indent(level);
            std::cout << "array []\n";
          })
      .when(
          bind()[is_type(json::value_t::array)] >>
          [=](const json &arr) {
            indent(level);
            std::cout << "array (" << arr.size() << ")\n";
            for (auto &item : arr) {
              parse_json(item, level + 1);
            }
          })
      .when(
          bind()[has_field("name")] >>
          [=](const json &obj) {
            indent(level);
            std::cout << "object <named>\n";
            for (auto &&[key, val] : obj.items()) {
              indent(level + 1);
              std::cout << key << ":\n";
              parse_json(val, level + 2);
            }
          })
      .otherwise([=] {
        indent(level);
        std::cout << "<unknown>\n";
      });
}

#include <asio.hpp>
#include <boost/bind.hpp>
#include <iostream>
#include "logger.hpp"

using asio::ip::tcp;

// Buffer for incoming data
char input_buffer[2048];

// Handler for asynchronous read operations
void read_handler(const asio::error_code& ec,
    std::size_t length, tcp::socket* sock)
{
  if (!ec)
  {
    std::cout.write(input_buffer, length);
    sock->async_read_some(asio::buffer(input_buffer),
        boost::bind(read_handler, asio::placeholders::error,
          asio::placeholders::bytes_transferred, sock));
  }
  else
  {
    services::logger log(sock->get_executor().context(), "read_handler");
    std::string error_msg = "Read failed: ";
    error_msg += ec.message();
    log.log(error_msg);
  }
}

// Handler for asynchronous connect operations
void connect_handler(const asio::error_code& ec, tcp::socket* sock)
{
  services::logger log(sock->get_executor().context(), "connect_handler");
  if (!ec)
  {
    log.log("Successfully connected to server");
    sock->async_read_some(asio::buffer(input_buffer),
        boost::bind(read_handler, asio::placeholders::error,
          asio::placeholders::bytes_transferred, sock));
  }
  else
  {
    std::string error_msg = "Connection attempt failed: ";
    error_msg += ec.message();
    log.log(error_msg);
  }
}

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: daytime_client <hostname>" << std::endl;
      return 1;
    }

    asio::io_context context;

    // Configure global logging file
    services::logger base_logger(context, "");
    base_logger.use_file("client_log.txt");

    // Resolve the target host and service
    tcp::resolver resolver(context);
    tcp::resolver::results_type results =
      resolver.resolve(argv[1], "daytime");

    // Create socket and initiate connection
    tcp::socket socket(context);
    asio::async_connect(socket, results,
        boost::bind(connect_handler,
          asio::placeholders::error, &socket));

