enum class Status { OFF = 1, ON = 2, PAUSE = 4 };

template <>
struct magic_enum::customize::enum_range<Status> {
  static constexpr bool is_flags = true;
};

int main() {
  auto status_bitset = magic_enum::containers::bitset<Status>();
  status_bitset.set(Status::ON);
  status_bitset.set(Status::PAUSE);

  std::cout << std::boolalpha;
  std::cout << status_bitset.size() << std::endl; // 3 == magic_enum::enum_count<Status>()
  std::cout << status_bitset.all() << std::endl;  // false
  std::cout << status_bitset.any() << std::endl;  // true
  std::cout << status_bitset.none() << std::endl; // false
  std::cout << status_bitset.count() << std::endl; // 2
  std::cout << status_bitset.test(Status::OFF) << std::endl;   // false
  std::cout << status_bitset.test(Status::ON) << std::endl;    // true
  std::cout << status_bitset.test(Status::PAUSE) << std::endl; // true

  return 0;
}

