#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    // Group anagrams together from the input list of strings
    std::vector<std::vector<string>> groupAnagrams(std::vector<std::string>& strs) {
        // Map to store sorted string as key and list of anagrams as value
        std::unordered_map<std::string, std::vector<std::string>> anagramMap;

        // Process each string in the input
        for (const auto& word : strs) {
            std::string sortedWord = word;
            std::sort(sortedWord.begin(), sortedWord.end());
            anagramMap[sortedWord].push_back(word);
        }

        // Collect all groups of anagrams into the result
        std::vector<std::vector<std::string>> groups;
        for (const auto& entry : anagramMap) {
            groups.push_back(entry.second);
        }

        return groups;
    }
};

