namespace yams::tools {

// Forward declarations for command classes
class GCCommand;
class StatsCommand;
class VerifyCommand;

// Factory functions to create command instances
std::unique_ptr<Command> createGCCommand();
std::unique_ptr<Command> createStatsCommand();
std::unique_ptr<Command> createVerifyCommand();

class YamsTools {
public:
    YamsTools() : cliApp_("yams-tools", "YAMS Storage Maintenance Utilities") {
        configureApplication();
        addCommands();
    }

    int execute(int argc, char** argv) {
        try {
            cliApp_.parse(argc, argv);

            // Execute the selected subcommand
            for (const auto& [label, handler] : commandRegistry_) {
                if (cliApp_.got_subcommand(label)) {
                    return handler->perform();
                }
            }

            // No subcommand provided; display help
            std::cout << cliApp_.help() << std::endl;
            return 0;
        } catch (const CLI::ParseError& err) {
            return cliApp_.exit(err);
        } catch (const std::exception& ex) {
            std::cerr << "Failure: " << ex.what() << std::endl;
            return 1;
        }
    }

private:
    void configureApplication() {
        cliApp_.set_version_flag("-V,--version", "1.0.0");
        cliApp_.require_subcommand(0, 1);

        // Global configuration flags
        cliApp_.add_flag("--verbose", verboseLogging_, "Activate detailed logging");
    }

    void addCommands() {
        // Register all available commands
        registerSingleCommand(createGCCommand());
        registerSingleCommand(createStatsCommand());
        registerSingleCommand(createVerifyCommand());
    }

    void registerSingleCommand(std::unique_ptr<Command> cmd) {
        if (!cmd)
            return;

        const std::string& identifier = cmd->getName();
        cmd->configureOptions(cliApp_);
        commandRegistry_[identifier] = std::move(cmd);
    }

    CLI::App cliApp_;
    std::map<std::string, std::unique_ptr<Command>> commandRegistry_;
    bool verboseLogging_ = false;
};

// Command factory implementations reside in separate translation units.
// Refer to: src/commands/*.cpp
} // namespace yams::tools

// Global interrupt handling
std::atomic<bool> g_userAbort{false};
void handleTerminationSignal(int sigNumber) {
    if (sigNumber == SIGINT || sigNumber == SIGTERM) {
        g_userAbort = true;
        std::cerr << "\nOperation cancelled. Performing cleanup..." << std::endl;
    }
}

int main(int argumentCount, char** argumentVector) {
    // Install signal handlers
    std::signal(SIGINT, handleTerminationSignal);
    std::signal(SIGTERM, handleTerminationSignal);

    // Configure log format
    spdlog::set_pattern("[%Y-%m-%d %H:%M:%S.%e] [%l] %v");

    // Launch the tool
    yams::tools::YamsTools program;
    return program.execute(argumentCount, argumentVector);
}

