#include <asio.hpp>
#include <ctime>
#include <chrono>
#include <iostream>

// Custom clock implementation using time_t for second-level precision
struct epoch_clock
{
  // Duration type definition
  using tick_type = std::chrono::steady_clock::duration;
  // Representation type for duration values
  using value_type = tick_type::rep;
  // Period type for duration representation
  using scale_type = tick_type::period;
  // Time point type based on this clock
  using instant = std::chrono::time_point<epoch_clock>;
  // Indicates whether the clock is monotonic
  static const bool steady = false;

  // Retrieve current time point
  static instant current() noexcept
  {
    return instant() + std::chrono::seconds(std::time(nullptr));
  }
};

// Custom traits for handling wait operations with reduced precision
struct second_precision_traits
{
  // Calculate wait duration for relative timeouts
  static epoch_clock::tick_type prepare_wait(
      const epoch_clock::tick_type& interval)
  {
    if (interval > std::chrono::seconds(1))
      return interval - std::chrono::seconds(1);
    else if (interval > std::chrono::seconds(0))
      return std::chrono::milliseconds(50);
    else
      return std::chrono::seconds(0);
  }

  // Calculate wait duration for absolute time points
  static epoch_clock::tick_type prepare_wait(
      const epoch_clock::instant& target)
  {
    return prepare_wait(target - epoch_clock::current());
  }
};

// Alias for the timer type using our custom clock and traits
using epoch_timer = asio::basic_waitable_timer<
    epoch_clock, second_precision_traits>;

int main()
{
  try
  {
    asio::io_context context;
    epoch_timer scheduler(context);

    // First test: blocking wait
    scheduler.expires_after(std::chrono::seconds(5));
    std::cout << "Blocking wait initiated\n";
    scheduler.wait();
    std::cout << "Blocking wait completed\n";

    // Second test: non-blocking async wait
    scheduler.expires_after(std::chrono::seconds(5));
    std::cout << "Asynchronous wait started\n";
    scheduler.async_wait(
        [](const std::error_code& /*ec*/)
        {
          std::cout << "timer expired\n";
        });
    context.run();
    std::cout << "Asynchronous wait finished\n";
  }
  catch (std::exception& err)
  {
    std::cerr << "Error occurred: " << err.what() << "\n";
  }

  return 0;
}

