void ThrownEnderpearl::onCollision(HitResult *impact)
{
	if (impact->entityTarget != NULL)
	{
		DamageSource *source = DamageSource::thrown(shared_from_this(), getThrower());
		impact->entityTarget->takeDamage(source, 0);
		delete source;
	}

	for (int index = 0; index < 32; ++index)
	{
		world->spawnParticle(eParticleType_ender, x, y + random->nextDouble() * 2, z, random->nextGaussian(), 0, random->nextGaussian());
	}

	if (!world->isClientSide)
	{
		// Fix for #67486 - TCR #001: BAS Game Stability: Customer Encountered: TU8: Code: Gameplay: The title crashes on Host's console when Client Player leaves the game before the Ender Pearl thrown by him touches the ground.
		// If the owner has been removed, then ignore
		// 4J-JEV: Cheap type check first.
		if ((getThrower() != NULL) && getThrower()->instanceof(eTYPE_SERVERPLAYER))
		{
			shared_ptr<ServerPlayer> remotePlayer = dynamic_pointer_cast<ServerPlayer>(getThrower());
			if (!remotePlayer->removed)
			{
				if (!remotePlayer->connection->completed && remotePlayer->dimension == this->world)
				{
					if (getThrower()->isPassenger())
					{
						getThrower()->stopRiding();
					}
					getThrower()->moveTo(x, y, z);
					getThrower()->fallDistance = 0;
					getThrower()->hurt(DamageSource::fall, 5);
				}
			}
		}
		destroy();
	}
}

