int main(int argc, char** argv) {
  using namespace small_gicp;

  if (argc < 3) {
    std::cout << "USAGE: odometry_benchmark <dataset_path> <output_path> [options]" << std::endl;
    std::cout << "OPTIONS:" << std::endl;
    std::cout << "  --visualize" << std::endl;
    std::cout << "  --num_threads <value> (default: 4)" << std::endl;
    std::cout << "  --num_neighbors <value> (default: 20)" << std::endl;
    std::cout << "  --downsampling_resolution <value> (default: 0.25)" << std::endl;
    std::cout << "  --voxel_resolution <value> (default: 2.0)" << std::endl;

    const auto engine_names = odometry_names();
    std::stringstream sst;
    for (size_t idx = 0; idx < engine_names.size(); idx++) {
      if (idx > 0) {
        sst << "|";
      }
      sst << engine_names[idx];
    }
    std::cout << "  --engine <" << sst.str() << "> (default: small_gicp)" << std::endl;
    return 0;
  }

  const std::string dataset_dir = argv[1];
  const std::string result_file = argv[2];

  OdometryEstimationParams config;
  std::string reg_method = "small_gicp";

  for (int i = 0; i < argc; i++) {
    const std::string token = argv[i];
    if (token == "--visualize") {
      config.visualize = true;
    } else if (token == "--num_threads") {
      config.num_threads = std::stoi(argv[i + 1]);
    } else if (token == "--num_neighbors") {
      config.num_neighbors = std::stoi(argv[i + 1]);
    } else if (token == "--downsampling_resolution") {
      config.downsampling_resolution = std::stod(argv[i + 1]);
    } else if (token == "--voxel_resolution") {
      config.voxel_resolution = std::stod(argv[i + 1]);
    } else if (token == "--engine") {
      reg_method = argv[i + 1];
    } else if (token.size() >= 2 && token.substr(0, 2) == "--") {
      std::cerr << "unknown option: " << token << std::endl;
      return 1;
    }
  }

  std::cout << "SIMD in use=" << Eigen::SimdInstructionSetsInUse() << std::endl;
  std::cout << "dataset_path=" << dataset_dir << std::endl;
  std::cout << "output_path=" << result_file << std::endl;
  std::cout << "registration_engine=" << reg_method << std::endl;
  std::cout << "num_threads=" << config.num_threads << std::endl;
  std::cout << "num_neighbors=" << config.num_neighbors << std::endl;
  std::cout << "downsampling_resolution=" << config.downsampling_resolution << std::endl;
  std::cout << "voxel_resolution=" << config.voxel_resolution << std::endl;
  std::cout << "visualize=" << config.visualize << std::endl;

  std::shared_ptr<OdometryEstimation> estimator = create_odometry(reg_method, config);
  if (estimator == nullptr) {
    return 1;
  }

  KittiDataset dataset(dataset_dir);
  std::cout << "num_frames=" << dataset.points.size() << std::endl;
  std::cout << fmt::format("num_points={} [points]", summarize(dataset.points, [](const auto& pts) { return pts.size(); })) << std::endl;

  auto point_clouds = dataset.convert<PointCloud>(true);
  std::vector<Eigen::Isometry3d> trajectory = estimator->estimate(point_clouds);

  std::cout << "done!" << std::endl;
  estimator->report();

  std::ofstream ofs(result_file);
  for (const auto& pose : trajectory) {
    for (int row = 0; row < 3; row++) {
      for (int col = 0; col < 4; col++) {
        if (row || col) {
          ofs << " ";
        }
        ofs << fmt::format("{:.6f}", pose(row, col));
      }
    }
    ofs << std::endl;
  }

  return 0;
}

#include <madvoro/Voronoi3D.hpp>
#include <iostream>
#include <vector>

int main(int argc, char *argv[])
{
    // Define the bounding box corners
    MadVoro::Vector3D minCorner(-10, -10, -10); 
    MadVoro::Vector3D maxCorner(10, 10, 10); 

    // Initialize Voronoi diagram with the bounding box
    MadVoro::Voronoi3D voronoiDiagram(minCorner, maxCorner);

    // Set of input points (sites)
    std::vector<MadVoro::Vector3D> sitePoints {{ -0.115, 4.484, 0.688 },
                                                { -6.121, 6.335, -9.093 },
                                                { -5.529, -7.464, 2.459 },
                                                { -3.448, -7.794, -6.939 },
                                                { -3.231, 8.213, -7.829 },
                                                { 5.204, 9.943, 6.175 },
                                                { -7.018, 7.155, -0.226 },
                                                { 0.567, 2.263, -0.962 },
                                                { 9.998, -3.030, 7.772 },
                                                { 3.811, 6.672, -8.231 },
                                                { 4.252, -8.460, -2.693 },
                                                { 5.184, 0.449, -1.665 },
                                                { -3.333, 3.909, 5.544 },
                                                { 3.495, -0.703, 5.494 },
                                                { -4.844, 4.808, -4.166 },
                                                { 3.016, -0.006, -1.534 },
                                                { -3.990, -1.579, 0.691 },
                                                { 6.928, 1.059, 6.088 },
                                                { 9.439, -6.873, 5.741 },
                                                { 6.238, -6.793, -4.822 }
                                            };

    // Retrieve and display bounding box coordinates
    std::pair<MadVoro::Vector3D, MadVoro::Vector3D> boxLimits = voronoiDiagram.GetBoxCoordinates();

    // Construct the Voronoi diagram using the provided points
    voronoiDiagram.Build(sitePoints);

    std::cout << "Lower-left corner: " << boxLimits.first 
              << ", Upper-right corner: " << boxLimits.second << std::endl;
    std::cout << "Total number of sites (cells): " << voronoiDiagram.GetPointNo() << std::endl;

    // Analyze cell for a specific point (index 3)
    size_t targetPointIndex = 3;
    const MadVoro::face_vec &cellFaces = voronoiDiagram.GetCellFaces(targetPointIndex);

    std::cout << "Point index " << targetPointIndex 
              << " at position " << voronoiDiagram.GetMeshPoint(targetPointIndex) 
              << " has " << cellFaces.size() << " faces." << std::endl;
    std::cout << "It has " << cellFaces.size() << " neighboring cells." << std::endl;

    // Get all face vertex coordinates
    std::vector<MadVoro::Vector3D> allFaceVertices = voronoiDiagram.GetFacePoints();

    std::cout << "Face details:" << std::endl;
    for(const size_t &faceID : cellFaces)
    {
        // Compute center of mass for this face
        MadVoro::Vector3D faceCentroid = voronoiDiagram.FaceCM(faceID);

        // Get neighbor indices across this face
        const std::pair<size_t, size_t> adjacentSites = voronoiDiagram.GetFaceNeighbors(faceID);

        // Determine which neighbor is not the current point
        size_t adjacentPointIndex = (adjacentSites.first == targetPointIndex) ? adjacentSites.second : adjacentSites.first;

        std::cout << "Face #" << faceID 
                  << " shares boundary with point #" << adjacentPointIndex 
                  << " at " << voronoiDiagram.GetMeshPoint(adjacentPointIndex) << std::endl;

        std::cout << "Vertices of this face: ";
        for(const size_t &vertexID : voronoiDiagram.GetPointsInFace(faceID))
        {
            std::cout << allFaceVertices[vertexID] << ", ";
        }
        std::cout << "\b\b" << std::endl;
    }

    return 0;
}

