#include <iostream>
#include <fstream>  // we will be reading and writing -> include fstream
#include "program.hpp"

int main(void){
    char input_file_name[MAX_FILE_NAME]; 
    // read the file name from the console
    std::cout << "Enter file name: ";
    std::cin.getline(input_file_name, MAX_FILE_NAME);
    std::ifstream input_stream(input_file_name);
    if(!input_stream.is_open())
    {
        std::cout << "Invalid file name!\n";
        return -1;
    }
    // automatically creates the file, if it exists it wipes its data
    std::ofstream output_stream("Result.txt");
    if(!output_stream.is_open())
    {
        std::cout << "Could not create Result file!";
        input_stream.close();
        return -1;
    }
    // while there is something to read
    while(input_stream)
    {
        program_context current_program_context;
        int status = read_program(current_program_context, input_stream);
        if(status == 1) // success
        {
            output_stream << current_program_context.program_name << '\n';
            for(int index = 0; index < ALPHABET_SIZE; ++index)
            {
                if(current_program_context.defined[index])
                {
                    output_stream 
                    << (char)('a' + index)
                    << '='
                    << current_program_context.values[index] << '\n';
                }
            }
        }
        else if(status == 0) output_stream << current_program_context.program_name << ' ' << FAIL_MESSAGE << '\n';
        clear_context(current_program_context);
    }
    input_stream.close();
    output_stream.close();
    return 0;
}

