// Date structure definition
struct CalendarDate {
    unsigned short day;       // Uninitialized member - the value is undefined
    unsigned short month;     // Uninitialized member - the value is undefined
    unsigned short year;      // Uninitialized member - the value is undefined
};

struct ClockTime {
    unsigned short hour = 0;         // Initialized member - the value is 0
    unsigned short minute{};         // Initialized member - the value is 0
    unsigned short second{15};       // Initialized member - the value is 15
};

const int kMaxNameLength = 50;

struct Worker {
    int identifier{ 0 };
    char fullName[kMaxNameLength]{};
    double wage{ 12000.0 };
    CalendarDate startDate{}; // A struct, can have another struct as a member
};

void displayDate(const CalendarDate& date);
void displayTime(const ClockTime& time);

int main() {
    // Defining a struct object
    CalendarDate anniversary; 
    ClockTime arbitraryTime; 

    // Member access
    anniversary.day = 17;
    anniversary.month = 7;
    anniversary.year = 1956;
    std::cout << "I was born on ";
    displayDate(anniversary);
    std::cout << "Arbitrary time: ";
    displayTime(arbitraryTime);

    // Struct initialization
    CalendarDate currentDay = { 24, 2, 2026 };
    std::cout << "Today is ";
    displayDate(currentDay);

    // Another way to initialize a struct
    ClockTime arbitraryTime2{ 12, 30, 45 };
    std::cout << "Arbitrary time 2: ";
    displayTime(arbitraryTime2);

    // If the struct has members that have a default value, we can omit them
    // But we should not mix the order of the members
    ClockTime arbitraryTime3{ 12, 30 };
    std::cout << "Arbitrary time 3: ";
    displayTime(arbitraryTime3);

    // Const structs
    // The members of a const (or constexpr) struct cannot be modified
    const CalendarDate startOfYear{ 1, 1, 2026 };
    // startOfYear.day = 2; // Error: startOfYear is const

    // Worker struct
    Worker staffMember{ 1, "Alice Smith", 2500.0, { 1, 1, 2021 } };

    // Passing temporary structs
    displayDate(CalendarDate { 23, 3, 2027 });
    displayDate({ 23, 3, 2027 }); // Struct type can be omitted

    return 0;
}

void displayDate(const CalendarDate& date) {
    std::cout << date.day << '/' << date.month << '/' << date.year << std::endl;
}

void displayTime(const ClockTime& time) {
    std::cout << time.hour << ':' << time.minute << ':' << time.second;
}

