void UIScene_DebugOptionsMenu::handleInput(
    int   controllerID,
    int   inputKey,
    bool  isRepeat,
    bool  isPressed,
    bool  isReleased,
    bool& isHandled
) {
    switch (inputKey) {
    case ACTION_MENU_CANCEL:
        if (isPressed) {
            int          currentBitIndex = 0;
            unsigned int updatedDebugMask = 0L;

            for (int index = 0; index < m_iTotalCheckboxElements; index++) {
                updatedDebugMask |= m_checkboxes[index].IsChecked()
                                    ? (1 << currentBitIndex)
                                    : 0;
                currentBitIndex++;
            }

            if (updatedDebugMask != app.GetGameSettingsDebugMask(controllerID)) {
                app.SetGameSettingsDebugMask(controllerID, updatedDebugMask);

                if (app.DebugSettingsOn()) {
                    app.ActionDebugMask(controllerID);
                } else {
                    // force debug mask off
                    app.ActionDebugMask(controllerID, true);
                }
                app.CheckGameSettingsChanged(true, controllerID);
            }
            navigateBack();
        }
        break;

    case ACTION_MENU_OK:
    case ACTION_MENU_UP:
    case ACTION_MENU_DOWN:
    case ACTION_MENU_PAGEUP:
    case ACTION_MENU_PAGEDOWN:
        sendInputToMovie(inputKey, isRepeat, isPressed, isReleased);
        break;
    }
}

