    void TFormattedOutput::Print(IOutputStream& stream) {
        for (auto& [level, text] : Lines_) {
            if (level && !text.empty()) {
                TTempBuf spaceBuffer(level);
                Fill(spaceBuffer.Data(), spaceBuffer.Data() + level, ' ');
                stream.Write(spaceBuffer.Data(), level);
            }
            stream << text;
            if (!text.EndsWith('\n')) {
                stream << Endl;
            }
        }
    }
}

