#define _GNU_SOURCE
#define ROCPROFSYS_PUBLIC_API   __attribute__((visibility("default")));
#define ROCPROFSYS_HIDDEN_API   __attribute__((visibility("hidden")));
#define ROCPROFSYS_INTERNAL_API __attribute__((visibility("internal")));
#include <dlfcn.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

//
// local type definitions
//
typedef int (*entry_point_t)(int, char**, char**);
typedef void (*setup_func_t)(void);
typedef int (*libc_entry_t)(int (*)(int, char**, char**), int, char**, void (*)(void),
                            void (*)(void), void (*)(void), void*);

//
// local function declarations
//
int
rocprofsys_runtime_start(int (*)(int, char**, char**), int, char**, void (*)(void),
                         void (*)(void), void (*)(void), void*) ROCPROFSYS_INTERNAL_API;
int
__libc_runtime_start(int (*)(int, char**, char**), int, char**, void (*)(void),
                     void (*)(void), void (*)(void), void*) ROCPROFSYS_PUBLIC_API;

//
// external function declarations
//
extern int
rocprofsys_load_library(void);
extern void
rocprofsys_cleanup(void);
extern void
rocprofsys_enter_region(const char* label);
extern void
rocprofsys_exit_region(const char* label);
extern void
rocprofsys_bootstrap_tooling(void);
extern void
rocprofsys_initialize(const char*, bool, const char*);
extern char*
path_basename(const char*);
extern void rocprofsys_assign_entry(entry_point_t) ROCPROFSYS_INTERNAL_API;
extern void
rocprofsys_assign_setup(setup_func_t func) ROCPROFSYS_INTERNAL_API;
extern void
rocprofsys_run_setup(void) ROCPROFSYS_INTERNAL_API;
extern int
rocprofsys_execute(int argc, char** argv, char** envp) ROCPROFSYS_INTERNAL_API;

int
rocprofsys_runtime_start(int (*_entry)(int, char**, char**), int _count, char** _args,
                         void (*_setup)(void), void (*_cleanup)(void),
                         void (*_rtld_cleanup)(void), void* _stack_top)
{
    int _loaded = rocprofsys_load_library();
    // avoid recursive calls
    static int _nested = 0;
    if(_nested > 0) return -1;
    _nested = 1;

    // capture current function address
    void* _current_addr = __builtin_return_address(0);

    // store original entry point
    rocprofsys_assign_entry(_entry);
    rocprofsys_assign_setup(_setup);

    // locate the actual libc entry function
    libc_entry_t real_entry = dlsym(RTLD_NEXT, "__libc_start_main");

    // disable subsequent preloading
    setenv("ROCPROFSYS_PRELOAD", "0", 1);

    if(real_entry && real_entry != _current_addr)
    {
        if(_loaded == 0)
        {
            // delegate to original entry
            return real_entry(_entry, _count, _args, _setup, _cleanup, _rtld_cleanup, _stack_top);
        }
        else
        {
            // invoke rocprof-sys wrapper
            return real_entry(rocprofsys_execute, _count, _args, _setup, _cleanup, _rtld_cleanup,
                              _stack_top);
        }
    }
    else
    {
        fprintf(stderr, "Error! rocprof-sys failed to locate __libc_start_main!\n");
        return -1;
    }
}

int
__libc_runtime_start(int (*_entry)(int, char**, char**), int _count, char** _args,
                     void (*_setup)(void), void (*_cleanup)(void), void (*_rtld_cleanup)(void),
                     void* _stack_top)
{
    // redirect control flow through our instrumentation layer
    return rocprofsys_runtime_start(_entry, _count, _args, _setup, _cleanup, _rtld_cleanup,
                                    _stack_top);
}

