#include "ReduceGlobalVarInitializers.h"
#include "llvm/IR/Constants.h"
#include "llvm/IR/GlobalValue.h"
using namespace llvm;

/// Eliminates initial values for global variables that are outside the target regions.
static void stripGVInitializers(Oracle &O, ReducerWorkItem &WorkItem) {
  // Clear initializers for globals not marked for retention
  for (auto &global : WorkItem.getModule().globals()) {
    if (global.hasInitializer() && !O.shouldKeep()) {
      global.setInitializer(nullptr);
      global.setLinkage(GlobalValue::LinkageTypes::ExternalLinkage);
      global.setComdat(nullptr);
    }
  }
}

void llvm::reduceGlobalsInitializersDeltaPass(TestRunner &Test) {
  runDeltaPass(Test, stripGVInitializers, "Stripping GV Initializers");
}

#include <iostream>
#include <iomanip>
#include <nlohmann/json.hpp>

using json = nlohmann::json;
using namespace nlohmann::literals;

// Helper function to display UBJSON byte values
void show_byte(uint8_t val)
{
    if (32 < val && val < 128)
    {
        std::cout << static_cast<char>(val);
    }
    else
    {
        std::cout << static_cast<int>(val);
    }
}

int main()
{
    // Build a JSON object
    json obj = R"({"compact": true, "schema": false})"_json;

    // Convert to UBJSON format
    std::vector<std::uint8_t> bytes_obj = json::to_ubjson(obj);

    // Output the encoded bytes
    for (auto& b : bytes_obj)
    {
        show_byte(b);
    }
    std::cout << std::endl;

    // Create a numeric array
    json numbers = {1, 2, 3, 4, 5, 6, 7, 8};

    // Encode with different optimization options
    std::vector<std::uint8_t> bytes_default = json::to_ubjson(numbers);
    std::vector<std::uint8_t> bytes_size_opt = json::to_ubjson(numbers, true);
    std::vector<std::uint8_t> bytes_full_opt = json::to_ubjson(numbers, true, true);

    // Print each encoding result on separate lines
    for (auto& b : bytes_default)
    {
        show_byte(b);
    }
    std::cout << std::endl;

    for (auto& b : bytes_size_opt)
    {
        show_byte(b);
    }
    std::cout << std::endl;

    for (auto& b : bytes_full_opt)
    {
        show_byte(b);
    }
    std::cout << std::endl;

    return 0;
}

