// Verify two complex numbers are approximately equal
void validateComplex(Complex x, Complex y, std::string description) {
    if (std::abs(x - y) > 1e-5) {
        std::cerr << "ERROR: " << description << " — Expected " << y << ", got " << x << std::endl;
        exit(1);
    }
}

// Display non-zero amplitudes of the quantum state
void showAmplitudes(const std::vector<Complex>& amplitudes) {
    for (size_t index = 0; index < amplitudes.size(); ++index) {
        if (std::abs(amplitudes[index]) > 1e-5) {
            std::cout << "|" << index << ">: " << amplitudes[index] << std::endl;
        }
    }
}

int main() {
    std::cout << "Executing Quantum Circuit Validation..." << std::endl;

    // Test A: Apply Hadamard gate
    {
        std::cout << "[Test A] Hadamard on Qubit 0" << std::endl;
        QuantumRegister qreg(1); // Single-qubit system
        qreg.applyHadamard(0);
        auto amplitudes = qreg.getStateVector();
        // Expected: |+> = 1/sqrt(2) (|0> + |1>)
        double magnitude = 1.0 / std::sqrt(2.0);
        validateComplex(amplitudes[0], Complex(magnitude, 0), "H|0> amplitude for |0>");
        validateComplex(amplitudes[1], Complex(magnitude, 0), "H|0> amplitude for |1>");
        std::cout << "SUCCESS" << std::endl;
    }

    // Test B: Create Bell state using Hadamard and CNOT
    {
        std::cout << "[Test B] Bell State Generation (H + CNOT)" << std::endl;
        QuantumRegister qreg(2);
        qreg.applyHadamard(0); // Prepare |+>|0>
        qreg.applyCNOT(0, 1);  // Entangle to form |00> + |11>
        auto amplitudes = qreg.getStateVector();
        double magnitude = 1.0 / std::sqrt(2.0);
        validateComplex(amplitudes[0], Complex(magnitude, 0), "|00> amplitude");
        validateComplex(amplitudes[1], Complex(0, 0), "|01> amplitude (should vanish)");
        validateComplex(amplitudes[2], Complex(0, 0), "|10> amplitude (should vanish)");
        validateComplex(amplitudes[3], Complex(magnitude, 0), "|11> amplitude");
        std::cout << "SUCCESS" << std::endl;
    }

    // Test C: Apply Pauli-X gate
    {
        std::cout << "[Test C] Pauli-X Gate" << std::endl;
        QuantumRegister qreg(1);
        qreg.applyX(0); // Flip |0> to |1>
        auto amplitudes = qreg.getStateVector();
        validateComplex(amplitudes[0], Complex(0, 0), "|0> amplitude after X");
        validateComplex(amplitudes[1], Complex(1, 0), "|1> amplitude after X");
        std::cout << "SUCCESS" << std::endl;
    }

    std::cout << "ALL QUANTUM OPERATIONS VALIDATED" << std::endl;
    return 0;
}

#include "InputStreamReader.h"
#include "DataInputStream.h"

// Constructs an InputStreamReader that utilizes the default character encoding.
// Parameters:
// input - An InputStream object
InputStreamReader::InputStreamReader(InputStream* input)
: stream(new DataInputStream(input)) {}

// Releases the stream and deallocates any system resources tied to it.
// After closing, calls to read(), ready(), mark(), reset(), or skip() will
// raise an IOException. Re-closing an already closed stream is safe and has no effect.
void InputStreamReader::close() { 
    stream->close(); 
}

// Reads one character from the stream.
// Returns:
// The character obtained, or -1 when the end of the stream is encountered
int InputStreamReader::read() { 
    return stream->readUTFChar(); 
}

// Reads characters into a subsection of a wide character array.
// Parameters:
// buffer - Target array for storing the characters
// startIndex - Position in the array to begin writing
// maxChars - Upper limit on how many characters to read
// Returns:
// Number of characters successfully read, or -1 if the stream ends prematurely
int InputStreamReader::read(
    wchar_t      buffer[],
    unsigned int startIndex,
    unsigned int maxChars
) {
    unsigned int numRead = 0;
    for (unsigned int index = startIndex; index < startIndex + maxChars; index++) {
        wchar_t tempChar = (wchar_t)stream->readUTFChar();
        if (tempChar != -1) {
            buffer[index] = tempChar;
            numRead++;
        }
        // NOTE 4J Stu - Exception handling may be needed here? If so, return -1
        else
            break;
    }
    return numRead;
}

#include <iostream>
#include <vector>
#include <utility>
#include <algorithm>

// Global variables for board size and state
int gridSize;
// Using 1-based indexing for convenience to match problem statement.
// Global arrays are zero-initialized, which works perfectly for 'unvisited'.
int chessBoard[667][667]; 
// Knight's move offsets (8 directions, ordered clockwise)
const int rowOffsets[] = {-2, -1, 1, 2, 2, 1, -1, -2};
const int colOffsets[] = {1, 2, 2, 1, -1, -2, -2, -1};

// Check if a square (row, col) is on the board and unvisited.
// Inlining can give a minor performance boost.
inline bool isPositionValid(int row, int col) {
    return row >= 1 && row <= gridSize && col >= 1 && col <= gridSize && chessBoard[row][col] == 0;
}

// Calculate the number of available moves from a square (Warnsdorff's rule).
// This is the 'degree' of the vertex in the graph of unvisited squares.
int countAvailableMoves(int row, int col) {
    int count = 0;
    for (int i = 0; i < 8; ++i) {
        if (isPositionValid(row + rowOffsets[i], col + colOffsets[i])) {
            count++;
        }
    }
    return count;
}

int main() {
    // Use fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int initialRow, initialCol;
    std::cin >> gridSize >> initialRow >> initialCol;

    // `tourPath` will store the sequence of visited squares.
    std::vector<std::pair<int, int>> tourPath;

    // Set the starting position.
    int currentRow = initialRow;
    int currentCol = initialCol;

    // Mark the starting square as visited (step 1).
    chessBoard[currentRow][currentCol] = 1;
    tourPath.push_back({currentRow, currentCol});

    // Generate the rest of the path, up to gridSize*gridSize-1 more moves.
    for (int step = 2; step <= gridSize * gridSize; ++step) {
        int nextRow = -1;
        int nextCol = -1;

        // Max possible degree is 8, so 9 is a safe initial value for minDegree.
        int minDegree = 9;

        // Apply Warnsdorff's rule: find the next move that has the minimum number of onward moves.
        for (int i = 0; i < 8; ++i) {
            int candidateRow = currentRow + rowOffsets[i];
            int candidateCol = currentCol + colOffsets[i];

            if (isPositionValid(candidateRow, candidateCol)) {
                int degree = countAvailableMoves(candidateRow, candidateCol);
                if (degree < minDegree) {
                    minDegree = degree;
                    nextRow = candidateRow;
                    nextCol = candidateCol;
                }
            }
        }

        // If nextRow is -1, it means we are stuck and cannot make any more moves.
        if (nextRow == -1) {
            break; 
        }

        // Make the chosen move.
        currentRow = nextRow;
        currentCol = nextCol;
        chessBoard[currentRow][currentCol] = step;
        tourPath.push_back({currentRow, currentCol});
    }

    // Output the length of the path found.
    std::cout << tourPath.size() << "\n";

    // Output the coordinates of each square in the path.
    for (const auto& pos : tourPath) {
        std::cout << pos.first << " " << pos.second << "\n";
    }

    return 0;
}

#include <unordered_map>
#include <string>

class Solution {
public:
    int firstUniqChar(std::string text) {
        std::unordered_map<char, int> freq_map;

        // Count frequency of each character
        for (int idx = 0; idx < text.length(); idx++) {
            char current_char = text[idx];
            freq_map[current_char]++;
        }

        // Find first character with frequency 1
        for (int pos = 0; pos < text.length(); pos++) {
            if (freq_map[text[pos]] == 1) {
                return pos;
            }
        }

        return -1;
    }
};

#include <iostream>
#include <istream>
#include <ostream>
#include <string>
#include <asio/ts/internet.hpp>
using asio::ip::tcp;

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 3)
    {
      std::cout << "Usage: http_client <server> <path>\n";
      std::cout << "Example:\n";
      std::cout << "  http_client www.boost.org /LICENSE_1_0.txt\n";
      return 1;
    }

    tcp::iostream connection;
    // Set timeout for the entire operation to 60 seconds
    connection.expires_after(std::chrono::seconds(60));

    // Connect to the specified server and service
    connection.connect(argv[1], "http");

    if (!connection)
    {
      std::cout << "Connection failed: " << connection.error().message() << "\n";
      return 1;
    }

    // Build and send HTTP GET request
    connection << "GET " << argv[2] << " HTTP/1.0\r\n";
    connection << "Host: " << argv[1] << "\r\n";
    connection << "Accept: */*\r\n";
    connection << "Connection: close\r\n\r\n";

    // Read and validate HTTP version
    std::string version;
    connection >> version;

    unsigned int code;
    connection >> code;

    std::string message;
    std::getline(connection, message);

    // Verify response format
    if (!connection || version.substr(0, 5) != "HTTP/")
    {
      std::cout << "Malformed HTTP response\n";
      return 1;
    }

    // Check status code
    if (code != 200)
    {
      std::cout << "HTTP error: " << code << "\n";
      return 1;
    }

    // Output headers until blank line
    std::string line;
    while (std::getline(connection, line) && line != "\r")
      std::cout << line << "\n";

    std::cout << "\n";

    // Output remaining body content
    std::cout << connection.rdbuf();
  }
  catch (const std::exception& ex)
  {
    std::cout << "Error occurred: " << ex.what() << "\n";
  }

  return 0;
}

