Y_UNIT_TEST_SUITE(TThreadLocalStorageTest) {
    struct TestData {
        inline TestData()
            : Value(0)
        {
        }

        inline void Increment() {
            ++TlsRef(Value);
        }

        inline int Retrieve() {
            return TlsRef(Value);
        }

        Y_THREAD(int)
        Value;
    };

    Y_UNIT_TEST(TestLargeScaleSetup) {
        TArrayHolder<TestData> data(new TestData[100000]);

        struct Worker: public ISimpleThread {
            inline Worker(TestData* buffer)
                : Buffer(buffer)
            {
            }

            void* ThreadProc() noexcept override {
                for (size_t idx = 0; idx < 100000; ++idx) {
                    Buffer[idx].Increment();
                }
                return nullptr;
            }

            TestData* Buffer;
        };

        Worker worker1(data.Get());
        Worker worker2(data.Get());

        worker1.Start();
        worker2.Start();

        worker1.Join();
        worker2.Join();

        for (size_t idx = 0; idx < 100000; ++idx) {
            UNIT_ASSERT_VALUES_EQUAL(data.Get()[idx].Retrieve(), 0);
        }
    }
} // Y_UNIT_TEST_SUITE(TThreadLocalStorageTest)

