#include <QtWidgets/QApplication>
#include <sm/vvec>
#include <mplot/qt/viswidget.h>
#include <mplot/GraphVisual.h>

// Construct a Qt-based visualization application using mplot
int main (int argc, char **argv)
{
    QApplication app(argc, argv);

    // Instantiate the visualization widget; specify OpenGL version via template parameter
    // Index 0 denotes the first widget instance
    mplot::qt::viswidget<0> view;

    // Displaying the widget triggers initialization of the OpenGL context via initializeGL()
    // Alternatively, one could defer showing until setting up callbacks like buildmodels (see alternative example)
    view.show();

    // Prepare a GraphVisual object to represent data in 3D space
    // Position is set at origin (0,0,0) using sm::vec<float>
    auto graph = std::make_unique<mplot::GraphVisual<double, mplot::qt::gl_version>> (sm::vec<float>({0.0f, 0.0f, 0.0f}));

    // Essential boilerplate: associate the visual model with the widget and bind internal functions
    view.v.bindmodel(graph);

    // Enable three-dimensional rendering for this visual model
    graph->twodimensional(false);

    // Define x-axis data using sm::vvec, which supports vectorized mathematical operations
    sm::vvec<double> x_coords;

    // Generate evenly spaced points from -0.5 to 0.8 across 14 samples
    x_coords.linspace(-0.5, 0.8, 14);

    // Configure the graph to plot y = x^3
    graph->setdata(x_coords, x_coords.pow(3));

    // Finalize the model: compute vertex data and prepare for OpenGL rendering
    graph->finalize();

    // Transfer ownership of the GraphVisual to the scene by adding it to the Visual container
    view.v.addVisualModel(graph);

    // Start the Qt event loop
    return app.exec();
}

#include "utl/JsonEncode.h"

void JSONStrEncode(const char *input, String &output) {
    int len = strlen(input);
    for (int index = 0; index < len; index++) {
        unsigned char current = input[index];
        if (current == '"') {
            output += "\\\"";
        } else if (current == '\\') {
            output += "\\\\";
        } else if (current == '/') {
            output += "\\/";
        } else if (current == '\b') {
            output += "\\b";
        } else if (current == '\r') {
            output += "\\r";
        } else if (current == '\n') {
            output += "\\n";
        } else if (current == '\t') {
            output += "\\t";
        } else if (current < ' ') {
            output += "\\u00";
            output += "0123456789ABCDEF"[current >> 4];
            output += "0123456789ABCDEF"[current & 0xF];
        } else {
            output += current;
        }
    }
}

