#include <vector>
#include <string>
#include <unordered_map>
#include <sstream>

class Solution {
private:
    const int ALPHABET_SIZE = 26;  // Number of lowercase English letters

public:
    vector<vector<string>> groupAnagrams(vector<string>& inputStrings) {
        unordered_map<string, vector<string>> signature_to_words;

        for (const auto& word : inputStrings) {
            vector<int> charFrequency(ALPHABET_SIZE, 0);

            // Count frequency of each character in the current word
            for (char c : word) {
                charFrequency[c - 'a']++;
            }

            // Create a unique signature string from character frequencies
            string signature = "";
            for (int freq : charFrequency) {
                signature += to_string(freq) + ",";
            }

            // Group words by their signature
            signature_to_words[signature].push_back(word);
        }

        // Collect all anagram groups into result
        vector<vector<string>> result;
        for (const auto& entry : signature_to_words) {
            result.push_back(entry.second);
        }

        return result;
    }
};

