// Constructor for LogToFile class that initializes logging to a file
LogToFile::LogToFile(std::string const& filename, int flags)
    :
    Logger::Listener(flags),
    mFilename(filename)
{
    std::ofstream logStream(filename);
    if (logStream)
    {
        // Clear any existing content in the file from prior executions.
        logStream.close();
    }
    else
    {
        // Unable to open the file; set filename to empty so Report() knows not to try again.
        mFilename = "";
    }
}

// Write a message to the log file
void LogToFile::Report(std::string const& message)
{
    if (!mFilename.empty())
    {
        // Open file in append mode.
        std::ofstream logStream(mFilename,
            std::ios_base::out | std::ios_base::app);
        if (logStream)
        {
            logStream << message.c_str();
            logStream.close();
        }
        else
        {
            // Failed to open the file; disable future attempts by clearing filename.
            mFilename = "";
        }
    }
}

