#include <vector>
#include <algorithm>
#include <climits>

class Solution {
public:
    bool canReach(int leftPos, int rightPos, int currentPos, int maxSteps) {
        if (rightPos <= currentPos) {
            return currentPos - leftPos <= maxSteps;
        } else if (leftPos >= currentPos) {
            return rightPos - currentPos <= maxSteps;
        } else {
            int distLeft = currentPos - leftPos;
            int distRight = rightPos - currentPos;
            return (2 * distLeft + distRight) <= maxSteps || (2 * distRight + distLeft) <= maxSteps;
        }
    }

    int maxTotalFruits(std::vector<std::vector<int>>& fruits, int startPos, int k) {
        int n = fruits.size();
        int result = INT_MIN;
        int currentSum = 0;
        int leftIndex = 0;

        for (int rightIndex = 0; rightIndex < n; rightIndex++) {
            currentSum += fruits[rightIndex][1];

            while (leftIndex <= rightIndex && !canReach(fruits[leftIndex][0], fruits[rightIndex][0], startPos, k)) {
                currentSum -= fruits[leftIndex][1];
                leftIndex++;
            }

            result = std::max(result, currentSum);
        }

        return result;
    }
};

