// Configure Wi-Fi power state based on enable flag
void configureWifiPower(bool isActive)
{
  if (!isActive) {
    WiFi.setAutoReconnect(false);
    WiFi.disconnect(true, true);
    WiFi.mode(WIFI_OFF);
    return;
  }

  // Activate Wi-Fi in station mode
  WiFi.mode(WIFI_STA);
  WiFi.setAutoReconnect(true);

  String networkSsid, networkPassword;
  if (wifiStoreLoad(networkSsid, networkPassword)) {
    WiFi.begin(networkSsid.c_str(), networkPassword.c_str());
  } else {
    // No credentials found => prevent automatic reconnection
    WiFi.setAutoReconnect(false);
    WiFi.disconnect(true, true);
  }
}

// Reset Wi-Fi configuration by clearing stored credentials
void resetWifiConfiguration()
{
  Preferences storage;
  storage.begin("rh_wifi", false);
  storage.putString("ssid", "");
  storage.putString("pass", "");
  storage.end();

  // Terminate current connection
  WiFi.disconnect(true, true);
  delay(50);
}

#include "ps2recomp/elf_analyzer.h"
#include <iostream>
#include <string>

void showHelp()
{
    std::cout << "PS2 ELF Analyzer\n";
    std::cout << "A utility for analyzing PS2 ELF binaries and producing TOML settings for PS2Recomp\n\n";
    std::cout << "Command line: ps2_analyzer <source_elf> <dest_toml>\n";
    std::cout << "  source_elf   Location of the PS2 ELF file to process\n";
    std::cout << "  dest_toml    Destination path for the generated TOML configuration\n";
}

int main(int argc, char *argv[])
{
    if (argc < 3)
    {
        showHelp();
        return 1;
    }

    std::string inputElf = argv[1];
    std::string outputToml = argv[2];

    std::cout << "PS2 ELF Analyzer\n";
    std::cout << "----------------\n";
    std::cout << "Source ELF: " << inputElf << "\n";
    std::cout << "Target TOML: " << outputToml << "\n\n";

    try
    {
        ps2recomp::ElfAnalyzer analyzer(inputElf);

        if (!analyzer.process())
        {
            std::cerr << "Error: Unable to analyze the ELF file\n";
            return 1;
        }

        if (!analyzer.writeToml(outputToml))
        {
            std::cerr << "Error: Could not create the TOML configuration\n";
            return 1;
        }

        std::cout << "\nProcessing finished successfully\n";
        std::cout << "TOML configuration saved to: " << outputToml << "\n";
        std::cout << "\nNext step: run PS2Recomp with the generated config:\n";
        std::cout << "  ps2recomp " << outputToml << "\n";
        return 0;
    }
    catch (const std::exception &e)
    {
        std::cerr << "Exception caught: " << e.what() << "\n";
        return 1;
    }
}

#include <engLib/eng.h>
namespace engine::store::pythonBase {
//-----------------------------------------------------------------
/// @details
///		Produce static, immutable configuration identifiers
///	@param[out]	configKey
///		Stores the distinctive configuration identifier for this endpoint
//-----------------------------------------------------------------
Error IPythonEndpointBase::getConfigSubKey(Text &configKey) noexcept {
    // Terminate python endpoint processing
    const auto pythonHandler = localfcn()->Error {
        // If the underlying driver lacks this capability, 
        // return an empty result (wildcard match)
        if (!py::hasattr(m_pyEndpoint, "getConfigSubKey")) return {};
        // Execute the method
        auto subkey = m_pyEndpoint.attr("getConfigSubKey")();
        // If no value returned, delegate to base class
        if (subkey.is_none()) return Parent::getConfigSubKey(configKey);
        // Convert to string type
        configKey = py::cast<std::string>(subkey);
        return {};
    };
    // Execute the handler
    return callPython(pythonHandler);
}
//-----------------------------------------------------------------
/// @details
///		Verify the integrity of service configuration parameters. 
///		Most validation issues should be logged as warnings/errors 
///		rather than returning hard failures; only critical errors 
///		will cause task failure
///	@param[in]	syntaxOnlyCheck
///		When true, perform only lexical/syntactic verification
//-----------------------------------------------------------------
Error IPythonEndpointBase::validateConfig(bool syntaxOnlyCheck) noexcept {
    // Delegate to parent implementation first
    if (auto status = Parent::validateConfig(syntaxOnlyCheck)) return status;
    // Wrap python endpoint operations
    const auto pythonHandler = localfcn()->Error {
        // If available, invoke python-side validation
        if (py::hasattr(m_pyEndpoint, "validateConfig"))
            m_pyEndpoint.attr("validateConfig")(syntaxOnlyCheck);
        return {};
    };
    // Run the python handler
    return callPython(pythonHandler);
}
//-----------------------------------------------------------------
/// @details
///		Retrieve ordered list of pipe stack filter specifications
///	@param[out]	filterList
///		Aggregated collection of required filter definitions
//-----------------------------------------------------------------
Error IPythonEndpointBase::getPipeFilters(IPipeFilters &filterList) noexcept {
    Error status;
    // Python filter retrieval routine
    const auto pythonHandler = localfcn()->Error {
        if (py::hasattr(m_pyEndpoint, "getPipeFilters")) {
            // Acquire filters from python endpoint
            pybind11::object rawResult = m_pyEndpoint.attr("getPipeFilters")();
            // Only process actual list objects
            if (!py::isinstance<py::list>(rawResult)) return {};
            // Extract list contents
            py::list pyFilterList = rawResult.cast<py::list>();
            // Iterate through each filter specification
            for (auto &entry : pyFilterList) {
                if (py::isinstance<py::str>(entry)) {
                    // String entries become Text objects
                    filterList.emplace_back(Text(py::cast<std::string>(entry)));
                } else if (py::isinstance<py::dict>(entry)) {
                    // Dictionary entries convert to JSON values
                    json::Value configValue =
                        engine::python::pyjson::dictToJson(entry);
                    filterList.emplace_back(
                        configValue);  // Insert copy into filter list
                } else {
                    throw APERR(Ec::InvalidParam,
                                "getPipeFilters item must be string or dict");
                }
            }
        }
        return {};
    };
    status = callPython(pythonHandler);
    if (checkCallParent(status)) return Parent::getPipeFilters(filterList);
    return status;
}
}  // namespace engine::store::pythonBase

