#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>
#include <iostream>

struct data_pair {
    int value;
    bool flag;
};

template <typename Handler>
bool sol_lua_check(sol::types<data_pair>, lua_State* L,
     int index, Handler&& handler,
     sol::stack::record& tracking) {
    int absolute_index = lua_absindex(L, index);
    bool result
         = sol::stack::check<int>(L, absolute_index, handler)
         && sol::stack::check<bool>(
              L, absolute_index + 1, handler);
    tracking.use(2);
    return result;
}

data_pair sol_lua_get(sol::types<data_pair>, lua_State* L,
     int index, sol::stack::record& tracking) {
    int absolute_index = lua_absindex(L, index);
    int value = sol::stack::get<int>(L, absolute_index);
    bool flag = sol::stack::get<bool>(L, absolute_index + 1);
    tracking.use(2);
    return data_pair { value, flag };
}

int sol_lua_push(lua_State* L, const data_pair& pair) {
    int count = sol::stack::push(L, pair.value);
    count += sol::stack::push(L, pair.flag);
    return count;
}

int main() {
    std::cout << "=== customization ===" << std::endl;
    std::cout << std::boolalpha;
    sol::state lua;
    lua.open_libraries(sol::lib::base);

    lua.script(
         "function process ( x, y ) print(x, y) return x, y end");

    sol::function process = lua["process"];
    data_pair input = process(data_pair { 42, true });
    SOL_ASSERT(input.value == 42);
    SOL_ASSERT(input.flag == true);

    std::cout << "input.value: " << input.value << std::endl;
    std::cout << "input.flag: " << input.flag << std::endl;
    std::cout << std::endl;
    return 0;
}

#include <shmem.h>
#include <stdio.h>

int main(void) {
    // Initialize the SHMEM runtime environment
    shmem_init();

    // Determine current PE identity and total count
    int my_id   = shmem_my_pe();   // Current processing element index
    int num_pes = shmem_n_pes();   // Total number of processing elements

    // Print initial greeting from each PE
    printf("Greetings from PE %d among %d PEs\n", my_id, num_pes);

    // -------------------------------------------------------------------------
    // Demonstrate point-to-point communication using symmetric memory
    // -------------------------------------------------------------------------

    // Allocate a shared integer in symmetric heap accessible by all PEs
    int* shared_val = (int*) shmem_malloc(sizeof(int));

    // Each PE writes its own ID into the shared location
    *shared_val = my_id;

    // Ensure all PEs have completed their write operations
    shmem_barrier_all();

    // Compute which PE will be our communication partner (next PE, wrapping around)
    int target_pe = (my_id + 1) % num_pes;
    int recv_data;

    // Perform blocking get operation to read value from target PE
    shmem_int_get(&recv_data, shared_val, 1, target_pe);

    // Report received data with source information
    printf("PE %d obtained value %d from PE %d\n", my_id, recv_data, target_pe);

    // Ensure all remote memory operations are globally visible
    shmem_quiet();

    // -------------------------------------------------------------------------
    // Cleanup resources before exit
    // -------------------------------------------------------------------------
    shmem_free(shared_val);

    // Terminate SHMEM environment properly
    shmem_finalize();

    return 0;
}

