namespace hsa
{
namespace
{
auto&
get_hsa_api_table_impl()
{
    static auto _api_table = std::atomic<HsaApiTable*>{ nullptr };
    return _api_table;
}

void
register_profiler_impl()
{
    static auto _base_api_table = HsaApiTable{};
    initialize_hsa_api_table(&_base_api_table);

    get_hsa_api_table_impl().exchange(&_base_api_table);

    static auto _modified_api_table = HsaApiTable{};
    copy_hsa_api_table(&_modified_api_table, &_base_api_table);

    void* _table_ptr = static_cast<void*>(&_modified_api_table);

    rocprofiler_register_library_indentifier_t lib_id{};
    auto status =
        rocprofiler_register_library_api_table("hsa",
                                               &ROCPROFILER_REGISTER_IMPORT_FUNC(hsa),
                                               ROCP_REG_VERSION,
                                               &_table_ptr,
                                               1,
                                               &lib_id);

    if(status == 0)
    {
        printf("[%s] hsa identifier %lu\n", ROCP_REG_FILE_NAME, lib_id.handle);

        auto* current_table = &_base_api_table;
        if(!get_hsa_api_table_impl().compare_exchange_strong(current_table,
                                                             &_modified_api_table))
        {
            std::cerr
                << "register_profiler_impl expected the API table to be the internal "
                   "implementation and yet it is not. something went wrong.\n";
            abort();
        }
    }
    else if(status != ROCP_REG_NO_TOOLS)
    {
        std::cerr << "HSA library failed to register with rocprofiler-register: "
                  << rocprofiler_register_error_string(status) << "\n";
        exit(EXIT_FAILURE);
    }
}

void
register_profiler()
{
    static auto _flag = std::atomic<bool>{ false };
    if(!_flag.load(std::memory_order_acquire))
    {
        using lock_type      = std::recursive_mutex;
        using guard_type     = std::unique_lock<lock_type>;
        static auto _flag_once  = std::once_flag{};
        static auto _mutex_lock = lock_type{};

        auto lk = guard_type{ _mutex_lock, std::defer_lock };

        if(lk.owns_lock()) return;

        lk.lock();

        std::call_once(_flag_once, register_profiler_impl);

        _flag.exchange(true, std::memory_order_release);
    }
}
}  // namespace

HsaApiTable*
get_hsa_api_table()
{
    register_profiler();
    return get_hsa_api_table_impl().load(std::memory_order_relaxed);
}

void
hsa_init()
{
    printf("[%s] %s\n", ROCP_REG_FILE_NAME, __FUNCTION__);
}
}  // namespace hsa

extern "C" {
void
hsa_init(void)
{
    hsa::get_hsa_api_table()->hsa_init_fn();
}
}

#include <Windows.h>
#include "zeal.h"

// Checks whether Zeal has already been loaded in the current session
static bool is_zeal_already_loaded() {
  // Simple detection: check if client-side mana ticking was disabled (pre-0.3.0 behavior)
  // Patch applied as: mem::set(0x4C3F93, 0x90, 7);
  const unsigned char* address = reinterpret_cast<unsigned char*>(0x004C3F93);
  bool is_patched = (*address == 0x90);  // NOP indicates prior loading
  return is_patched;
}

// zeal.asi gets loaded by mss between login screen and character selection
// Unlike typical libraries, it may be reloaded across cycles; to prevent multiple patching,
// this module pins itself in memory using GetModuleHandleEx with the PIN flag.
// Safe initialization is deferred to loadOptions(), where a hook replaces the original call.
static const int hook_patch_offset = 0x005282f8;
static int* const patch_target_address = reinterpret_cast<int*>(hook_patch_offset + 1);
static const int original_call_relative_value = 0x0000e9e3;

static void __fastcall setup_zeal_module(void* game_instance, int edx_unused) {
  // Pin the DLL into memory so it persists despite FreeLibrary calls
  static HMODULE module_handle = nullptr;
  GetModuleHandleExA(GET_MODULE_HANDLE_EX_FLAG_PIN | GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS,
                     (LPCSTR)&setup_zeal_module,
                     &module_handle);

  // Skip re-initialization if another instance is already active
  if (!is_zeal_already_loaded()) {
    // Initialize core Zeal functionality: patches, hooks, callbacks, named pipe thread, etc.
    ZealService::create();
  }

  // Invoke original loadOptions function
  reinterpret_cast<void(_fastcall*)(void*, int)>(0x00536ce0)(game_instance, edx_unused);
}

static void apply_hook_on_attach() {
  // Exit early if hook already installed (multiple logins or duplicate ASI files)
  if (*patch_target_address != original_call_relative_value) return;

  // Replace relative jump in the 'call loadOptions' instruction with one pointing to setup_zeal_module
  const int next_instruction_addr = hook_patch_offset + 5;
  const int relative_jump = reinterpret_cast<int>(&setup_zeal_module) - next_instruction_addr;

  DWORD protection;
  VirtualProtect(patch_target_address, sizeof(int), PAGE_EXECUTE_READWRITE, &protection);
  *patch_target_address = relative_jump;
  VirtualProtect(patch_target_address, sizeof(int), protection, &protection);
  FlushInstructionCache(GetCurrentProcess(), patch_target_address, sizeof(int));
}

BOOL APIENTRY DllMain(HMODULE hModule, DWORD reason, LPVOID lpReserved) {
  switch (reason) {
    case DLL_PROCESS_ATTACH:
      apply_hook_on_attach();
      break;
    case DLL_PROCESS_DETACH:
      // Module remains pinned; no cleanup needed
      break;
    default:
      // Ignore other events
      break;
  }
  return TRUE;
}

