// Modified active object pattern implementation
class bank_account
{
  int current_balance_ = 0;
  mutable thread_pool executor_{1};
public:
  void credit(int value)
  {
    post(executor_, [=]
      {
        current_balance_ += value;
      });
  }
  void debit(int value)
  {
    post(executor_, [=]
      {
        if (current_balance_ >= value)
          current_balance_ -= value;
      });
  }
  void show_status() const
  {
    post(executor_, [=]
      {
        std::cout << "account balance = " << current_balance_ << "\n";
      });
  }
  ~bank_account()
  {
    executor_.join();
  }
};

int main()
{
  bank_account account;
  account.credit(20);
  account.debit(10);
  account.show_status();
}

#include "isdiag.h"
template <typename T>
IGL_INLINE bool igl::isdiag(const Eigen::SparseMatrix<T> & matrix)
{
  // Check each column for off-diagonal non-zero entries
  for(int col = 0; col < matrix.outerSize(); ++col)
  {
    // Iterate through non-zero elements in this column
    for(typename Eigen::SparseMatrix<T>::InnerIterator it(matrix, col); it; ++it)
    {
      if(it.row() != it.col() && it.value() != 0)
      {
        return false;
      }
    }
  }
  return true;
}
