#include <iostream>
#include <vector>
using namespace std;

// LeetCode 136: Single Number
// Given a non-empty array of integers nums, every element appears twice except for one. Find that single one.
// You must implement a solution with a linear runtime complexity and use only constant extra space.
class Solution {
public:
    int singleNumber(vector<int>& nums) {
        int result = 0;
        for (int num : nums) {
            result ^= num;
        }
        return result;
    }
};

// Logic Explanation:
// We can use the XOR bitwise operation to solve this problem efficiently.
// The XOR operation has the following properties:
// 1. x ^ x = 0 (any number XORed with itself is 0)
// 2. x ^ 0 = x (any number XORed with 0 is the number itself)
// 3. XOR is commutative and associative, meaning the order of operations does not matter.
// By XORing all the numbers in the array together, the numbers that appear twice will cancel each other out
// (resulting in 0), and we will be left with the single number that appears only once.
// Time Complexity: O(n) where n is the number of elements in the array.
// Space Complexity: O(1) since we are using only a constant amount of extra space.

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

// Convert character to index: 'A'-'Z' -> 0-25, '0'-'9' -> 26-35
inline int char_to_index(char ch) {
    if (ch >= 'A' && ch <= 'Z') {
        return ch - 'A';
    }
    // Assuming ch is a digit '0'-'9' per problem constraints
    return ch - '0' + 26;
}

// Greedy algorithm to find common subsequence
// Traverses target_str and matches characters using precomputed positions from source_str
// Time complexity: O(|target_str| + |source_str|)
std::string find_common_subsequence(const std::string& target_str, const std::vector<std::vector<int>>& char_positions) {
    std::string result;
    if (target_str.empty()) {
        return result;
    }
    result.reserve(target_str.length());

    int last_matched_pos = -1;
    std::vector<int> indices(36, 0);

    for (char current_char : target_str) {
        int char_id = char_to_index(current_char);
        const std::vector<int>& available_positions = char_positions[char_id];
        int& current_ptr = indices[char_id];

        // Move pointer to next valid position after last_matched_pos
        while (static_cast<size_t>(current_ptr) < available_positions.size() && 
               available_positions[current_ptr] <= last_matched_pos) {
            current_ptr++;
        }

        // If a valid position exists, include the character in result
        if (static_cast<size_t>(current_ptr) < available_positions.size()) {
            result.push_back(current_char);
            last_matched_pos = available_positions[current_ptr];
            current_ptr++;
        }
    }
    return result;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::string str_a, str_b;
    std::cin >> str_a >> str_b;

    // Precompute character positions for both strings
    std::vector<std::vector<int>> pos_a(36);
    std::vector<std::vector<int>> pos_b(36);

    for (size_t idx = 0; idx < str_a.length(); ++idx) {
        pos_a[char_to_index(str_a[idx])].push_back(idx);
    }
    for (size_t idx = 0; idx < str_b.length(); ++idx) {
        pos_b[char_to_index(str_b[idx])].push_back(idx);
    }

    // Compute LCS-like results in both directions
    std::string candidate_1 = find_common_subsequence(str_a, pos_b);
    std::string candidate_2 = find_common_subsequence(str_b, pos_a);

    // Output the longer of the two candidates
    if (candidate_1.length() >= candidate_2.length()) {
        std::cout << candidate_1 << '\n';
    } else {
        std::cout << candidate_2 << '\n';
    }

    return 0;
}

#include <pybind11/eigen.h>
