namespace py = pybind11;

/**
 * @brief Compute eigenvalues and eigenvectors for a symmetric dense matrix using LAPACK's syev.
 *
 * @param input_matrix Input square matrix (NumPy array).
 * @return A tuple with the computed eigenvalues and eigenvectors.
 */
py::tuple symmetric_eigensolver(const py::array_t<double>& input_matrix) {
  // Check dimensionality
  if (input_matrix.ndim() != 2) {
    throw std::invalid_argument("Input must be a 2D array.");
  }

  auto dims = input_matrix.shape();
  if (dims[0] != dims[1]) {
    throw std::invalid_argument("Matrix must be square.");
  }

  int size = dims[0];

  // Convert NumPy array to Eigen matrix
  Eigen::MatrixXd A = Eigen::Map<const Eigen::MatrixXd>(input_matrix.data(), size, size);
  Eigen::VectorXd eigenvals(size);

  // Call LAPACK routine
  int result = lapack::syev(lapack::Job::Vec, lapack::Uplo::Lower, size, A.data(), size, eigenvals.data());
  if (result != 0) {
    throw std::runtime_error("LAPACK syev computation failed.");
  }

  return py::make_tuple(eigenvals, A);
}

/**
 * @brief Expose the symmetric eigensolver to Python.
 *
 */
void expose_eigensolver(py::module& module) {
  module.def("solve_symmetric_eigen", &symmetric_eigensolver,
        R"(
            Compute eigenvalues and eigenvectors of a symmetric dense matrix via LAPACK's syev.

            Parameters
            ----------
            input_matrix : numpy.ndarray
                Square symmetric matrix.

            Returns
            -------
            tuple of (numpy.ndarray, numpy.ndarray)
                - ``eigenvalues``: 1D array of eigenvalues in ascending order
                - ``eigenvectors``: 2D array where each column is an eigenvector

            Raises
            ------
            ValueError
                If the input is not square or not 2-dimensional.
            RuntimeError
                If the underlying LAPACK solver fails.
        )",
        py::arg("input_matrix"));
}

#include <vector>
#include <algorithm>

class Solution {
public:
    // Find the highest total balance across all customers
    int maximumWealth(std::vector<std::vector<int>>& accounts) {
        int customerCount = accounts.size();
        if (customerCount == 0) return 0;

        int accountCount = accounts[0].size();
        int bestWealth = 0;

        for (int customerIndex = 0; customerIndex < customerCount; customerIndex++) {
            int currentBalance = 0;

            for (int bankIndex = 0; bankIndex < accountCount; bankIndex++) {
                currentBalance += accounts[customerIndex][bankIndex];
            }

            bestWealth = std::max(currentBalance, bestWealth);
        }

        return bestWealth;
    }
};

#include <asio/post.hpp>
