#include <mplot/loadpng.h>
#include <mplot/Visual.h>
#include <mplot/VisualDataModel.h>
#include <mplot/GridVisual.h>
#include <mplot/HexGridVisual.h>

int main() {
    mplot::Visual viewer(1600, 1200, "Demonstration: Grid-based Image Resampling");
    viewer.setSceneTrans(sm::vec<float,3>({-2.5f, 1.4f, -10.8f}));

    unsigned int reduction_factor = 3U;
    sm::vec<float, 2> cell_size = { 0.025f, 0.025f };
    sm::vec<float, 2> coarser_cell = cell_size * reduction_factor;

    // Create original grid with specified dimensions and resolution
    sm::grid base_grid(256U, 128U, cell_size);
    std::cout << "Base grid bounds: (xmin,xmax,ymin,ymax): " << base_grid.extents() << std::endl;

    // Create downsampled grid
    sm::grid refined_grid(256U / reduction_factor, 128U / reduction_factor, coarser_cell);
    std::cout << "Refined grid bounds: (xmin,xmax,ymin,ymax): " << refined_grid.extents() << std::endl;

    // Load image data
    std::string img_path = "../examples/sample_image.png";
    sm::vvec<float> pixel_values; // loaded in bottom-left-to-top-right order
    sm::vec<unsigned int, 2> image_dims = mplot::loadpng(img_path, pixel_values);
    std::cout << "Loaded image dimensions: " << image_dims << std::endl;

    if (image_dims[0] != 256) {
        std::cerr << "Unexpected image width detected.\n";
        return -1;
    }

    // Prepare resampling parameters
    sm::vec<float,2> zoom_factors = {1.0f, 1.0f};
    sm::vec<float,2> translation = {0.0f, 0.0f};

    // Perform resampling on the coarser grid
    sm::vvec<float> resampled_data = refined_grid.resample_image(pixel_values, image_dims[0], zoom_factors, translation);

    // Also resample onto a hexagonal grid
    sm::vec<float, 2> hex_dx = refined_grid.get_dx();
    sm::hexgrid hex_grid(hex_dx[0], refined_grid.width() * 2.0f, 0.0f);
    hex_grid.setRectangularBoundary(refined_grid.width(), refined_grid.height());

    // Hexgrid-specific scaling to match visual dimensions
    sm::vec<float,2> hex_scaling = { refined_grid.width(), refined_grid.width() };
    sm::vvec<float> hex_resampled = hex_grid.resampleImage(pixel_values, image_dims[0], hex_scaling, translation);

    // Visualize original image using GridVisual
    auto base_visual = std::make_unique<mplot::GridVisual<float>>(&base_grid, sm::vec<float>({0,0,0}));
    viewer.bindmodel(base_visual);
    base_visual->gridVisMode = mplot::GridVisMode::RectInterp;
    base_visual->setScalarData(&pixel_values);
    base_visual->cm.setType(mplot::ColourMapType::InvertedGreyscale);
    base_visual->zScale.null_scaling();
    base_visual->addLabel("Original Image", {0, -0.2, 0}, mplot::TextFeatures(0.1f));
    base_visual->finalize();
    viewer.addVisualModel(base_visual);

    // Visualize resampled grid
    auto refined_visual = std::make_unique<mplot::GridVisual<float>>(&refined_grid, sm::vec<float>{0.0f, -2.5f, 0.0f});
    viewer.bindmodel(refined_visual);
    refined_visual->gridVisMode = mplot::GridVisMode::RectInterp;
    refined_visual->setScalarData(&resampled_data);
    refined_visual->cm.setType(mplot::ColourMapType::InvertedGreyscale);
    refined_visual->zScale.null_scaling();
    refined_visual->addLabel("Downsampled Grid", {0, -0.2, 0}, mplot::TextFeatures(0.1f));
    refined_visual->finalize();
    viewer.addVisualModel(refined_visual);

    // Visualize hexagonal grid result
    auto hex_visual = std::make_unique<mplot::HexGridVisual<float>>(&hex_grid, sm::vec<float>{ refined_grid.width() / 2.0f, refined_grid.height() / 2.0f - 5.0f , 0.0f });
    viewer.bindmodel(hex_visual);
    hex_visual->setScalarData(&hex_resampled);
    hex_visual->cm.setType(mplot::ColourMapType::InvertedGreyscale);
    hex_visual->zScale.null_scaling();
    hex_visual->addLabel("Hexagonal Resampling", {-refined_grid.width() / 2.0f, -0.2f - refined_grid.height() / 2.0f, 0}, mplot::TextFeatures(0.1f));
    hex_visual->finalize();
    viewer.addVisualModel(hex_visual);

    viewer.keepOpen();
    return 0;
}

