#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    long long maxPower(std::vector<int>& powerStations, int radius, int extraStations) {
        long long low = 0;
        // The maximum possible answer occurs when all stations have equal power after adding all extra stations
        long long high = std::accumulate(powerStations.begin(), powerStations.end(), 0LL) + extraStations;
        long long result = 0;

        while (low <= high) {
            long long mid = (low + high) / 2;
            if (canAchieve(powerStations, radius, mid, extraStations)) {
                result = mid; // Update result to current feasible value
                low = mid + 1; // Try for a higher minimum power
            } else {
                high = mid - 1; // Reduce required power to stay within station limits
            }
        }
        return result;
    }

    bool canAchieve(std::vector<int>& powerStations, int radius, long long requiredPower, int availableStations) {
        int n = powerStations.size();
        // Calculate initial window power for first city
        long long currentWindow = std::accumulate(powerStations.begin(), powerStations.begin() + std::min(radius, n), 0LL);
        std::vector<long long> placements(n, 0);

        for (int i = 0; i < n; i++) {
            // Expand window to include right boundary
            if (i + radius < n) {
                currentWindow += powerStations[i + radius];
            }

            // Check if current city meets power requirement
            if (currentWindow < requiredPower) {
                long long deficit = requiredPower - currentWindow;
                if (deficit > availableStations) {
                    return false; // Not enough stations to meet requirement
                }

                // Place additional stations at the farthest position in range
                placements[std::min(n - 1, i + radius)] += deficit;
                currentWindow = requiredPower;
                availableStations -= deficit;
            }

            // Shrink window from left as we move to next city
            if (i - radius >= 0) {
                currentWindow -= powerStations[i - radius] + placements[i - radius];
            }
        }
        return true;
    }
};

