namespace hip
{
namespace internal
{
// Atomic pointer to hold the current HIP API table
auto&
fetch_api_table()
{
    static std::atomic<HipApiTable*> s_api_table{ nullptr };
    return s_api_table;
}

void
init_profiler()
{
    // Immutable baseline API table
    static const HipApiTable s_const_table = [] {
        HipApiTable tmp{};
        initialize_hip_api_table(&tmp);
        return tmp;
    }();

    // Atomically install the constant table as initial value
    fetch_api_table().store(&s_const_table, std::memory_order_relaxed);

    // Working copy for profiler instrumentation
    static HipApiTable s_profiler_table{};
    copy_hip_api_table(&s_profiler_table, &s_const_table);

    void* p_table = &s_profiler_table;
    rocprofiler_register_library_indentifier_t lib_id{};

    auto result = rocprofiler_register_library_api_table(
        "hip",
        &ROCPROFILER_REGISTER_IMPORT_FUNC(hip),
        ROCP_REG_VERSION,
        &p_table,
        1,
        &lib_id);

    if(result == 0)
    {
        HipApiTable* expected = &s_const_table;
        if(!fetch_api_table().compare_exchange_strong(expected, &s_profiler_table))
        {
            std::cerr
                << "init_profiler expected the API table to be the internal "
                   "implementation but found something else — unexpected state.\n";
            std::abort();
        }
    }
}

void
ensure_registration()
{
    static std::atomic<bool> s_flag{ false };

    if(!s_flag.load(std::memory_order_acquire))
    {
        using lock_type   = std::recursive_mutex;
        using guard_type  = std::unique_lock<lock_type>;
        static std::once_flag s_once{};
        static lock_type s_mutex{};

        guard_type lk{s_mutex, std::defer_lock};

        // Avoid deadlock if same thread re-enters during registration
        if(lk.owns_lock()) return;

        lk.lock();

        std::call_once(s_once, init_profiler);

        s_flag.store(true, std::memory_order_release);
    }
}
}  // namespace internal

HipApiTable*
get_hip_api_table()
{
    internal::ensure_registration();
    return internal::fetch_api_table().load(std::memory_order_relaxed);
}
}  // namespace hip

