void check_environment(const std::string& var_name,
     const sol::environment& target_env, const sol::state_view& lua_state) {
	sol::optional<int> maybe_in_target = target_env[var_name];
	sol::optional<int> maybe_in_global = lua_state[var_name];
	if (maybe_in_global) {
		std::cout << "\t'" << var_name << "' is "
		          << maybe_in_global.value()
		          << " in the global scope" << std::endl;
	}
	else {
		std::cout
		     << "\t'" << var_name
		     << "' is not present in the global scope"
		     << std::endl;
	}
	if (maybe_in_target) {
		std::cout << "\t'" << var_name << "' is "
		          << maybe_in_target.value()
		          << " in the specified environment" << std::endl;
	}
	else {
		std::cout << "\t'" << var_name
		          << "' is not found in the specified environment"
		          << std::endl;
	}
}

int main(int, char**) {
	std::cout << "=== environment demonstration ===" << std::endl;
	sol::state lua_vm;

	// Define a global variable for fallback testing
	lua_vm["x"] = 2142;

	// Create an isolated environment
	sol::environment isolated_env(lua_vm, sol::create);

	// Assign a value within this environment
	lua_vm.script("y = 24", isolated_env);

	std::cout << "-- checking: isolated_env" << std::endl;
	check_environment("y", isolated_env, lua_vm);
	check_environment("x", isolated_env, lua_vm);

	std::cout << std::endl;

	// Create an environment with global fallback
	sol::environment env_with_global_fallback(
	     lua_vm, sol::create, lua_vm.globals());

	// Assign a different value in this new environment
	lua_vm.script("y = 56", env_with_global_fallback);

	std::cout << "-- checking: env_with_global_fallback (fallback is "
	             "the global table)"
	          << std::endl;
	check_environment("y", env_with_global_fallback, lua_vm);
	check_environment("x", env_with_global_fallback, lua_vm);

	std::cout << std::endl;
	return 0;
}

#include <assert.h>
#include <math.h>
#include <mpi.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Generates an array of random floating-point values in range [0, 1)
float*
generate_random_values(int count)
{
    float* values = (float*) malloc(sizeof(float) * count);
    assert(values != NULL);
    for(int idx = 0; idx < count; idx++)
    {
        values[idx] = (rand() / (float) RAND_MAX);
    }
    return values;
}

int
main(int argc, char** argv)
{
    if(argc != 2)
    {
        fprintf(stderr, "Usage: stddev num_elements_per_process\n");
        exit(1);
    }

    int elements_per_rank = atoi(argv[1]);

    MPI_Init(NULL, NULL);

    int my_rank;
    MPI_Comm_rank(MPI_COMM_WORLD, &my_rank);

    int num_ranks;
    MPI_Comm_size(MPI_COMM_WORLD, &num_ranks);

    // Initialize random seed per process using current time and rank
    srand(time(NULL) * my_rank);

    float* random_data = generate_random_values(elements_per_rank);

    // Compute local sum
    float local_sum = 0.0f;
    for(int j = 0; j < elements_per_rank; j++)
    {
        local_sum += random_data[j];
    }

    // Gather all local sums to compute global mean
    float total_sum;
    MPI_Allreduce(&local_sum, &total_sum, 1, MPI_FLOAT, MPI_SUM, MPI_COMM_WORLD);
    float avg = total_sum / (elements_per_rank * num_ranks);

    // Compute local sum of squared deviations from the mean
    float local_variance_contrib = 0.0f;
    for(int k = 0; k < elements_per_rank; k++)
    {
        float diff = random_data[k] - avg;
        local_variance_contrib += diff * diff;
    }

    // Reduce to root process to get total sum of squared deviations
    float global_variance_contrib;
    MPI_Reduce(&local_variance_contrib, &global_variance_contrib, 1, MPI_FLOAT, MPI_SUM, 0, MPI_COMM_WORLD);

    // Calculate standard deviation on root
    if(my_rank == 0)
    {
        float variance = global_variance_contrib / (elements_per_rank * num_ranks);
        float std_dev = sqrt(variance);
        printf("Average - %f, Standard deviation = %f\n", avg, std_dev);
    }

    // Cleanup resources
    free(random_data);
    MPI_Barrier(MPI_COMM_WORLD);
    MPI_Finalize();
}

