int main() {
    pugi::xml_document document;
    if (!document.load_string("<element id='456'>content</element><!-- additional comment -->", pugi::parse_default | pugi::parse_comments)) return -1;

    // tag::node[]
    pugi::xml_node element = document.child("element");
    // modify element name
    std::cout << element.set_name("renamed_element");
    std::cout << ", updated element name: " << element.name() << std::endl;

    // modify comment content
    std::cout << document.last_child().set_value("deprecated comment");
    std::cout << ", updated comment content: " << document.last_child().value() << std::endl;

    // attempting invalid operations
    std::cout << element.set_value("0") << ", " << document.last_child().set_name("invalid") << std::endl;
    // end::node[]

    // tag::attr[]
    pugi::xml_attribute attribute = element.attribute("id");
    // update attribute name and value
    std::cout << attribute.set_name("identifier") << ", " << attribute.set_value("789");
    std::cout << ", new attribute: " << attribute.name() << "=" << attribute.value() << std::endl;

    // assign numeric or boolean values
    attribute.set_value(3.14159);
    std::cout << "numeric attribute value: " << attribute.value() << std::endl;

    // use assignment operator for brevity
    attribute = false;
    std::cout << "final attribute value: " << attribute.value() << std::endl;
    // end::attr[]
}

