namespace snap::utils::time {
using std::chrono::nanoseconds;
using std::chrono::seconds;

// Omit the implementation for WebAssembly targets. While boot-time measurement might be feasible in Node.js,
// browsers restrict access to OS-level boot information. For scenarios requiring only monotonic timing,
// UptimeClock remains available and typically sufficient.
#if !defined(SC_WASM)
BoottimeClock::time_point BoottimeClock::now() noexcept {
    // Implementation derived from LLVM's reference code:
    // https://github.com/llvm/llvm-project/blob/master/libcxx/src/chrono.cpp
    struct timespec ts;

#if defined(__APPLE__)
    // Aligns with iOS mach_continuous_time behavior.
    // See: https://opensource.apple.com/source/Libc/Libc-1158.1.2/gen/clock_gettime.c.auto.html
    if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) != 0) {
        std::__throw_system_error(errno, "clock_gettime(CLOCK_MONOTONIC_RAW) failed");
    }
#else
    // Mirrors Android's elapsedRealtime implementation.
    // See: https://cs.android.com/android/platform/superproject/+/master:system/core/libutils/SystemClock.cpp
    if (clock_gettime(CLOCK_BOOTTIME, &ts) != 0) {
        std::__throw_system_error(errno, "clock_gettime(CLOCK_BOOTTIME) failed");
    }
#endif

    return time_point(seconds(ts.tv_sec) + nanoseconds(ts.tv_nsec));
}
#endif
} // namespace snap::utils::time

