int main() {
    // Optimized I/O operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n, range1, range2;
    std::cin >> n >> range1 >> range2;

    // `location[k]` stores the original index of the element currently at position `k`.
    // Initially, position `k` holds the element originally at index `k`.
    std::vector<int> location(n + 1);
    std::iota(location.begin(), location.end(), 0);

    // Strategy: Build a chain of consecutive-value elements incrementally.
    // After step `k`, positions 1..k contain a chain of k consecutive-value elements.
    // In each step, find a neighbor of the last element in the chain from remaining positions.
    for (int step = 1; step < n; ++step) {
        // Current pivot is the element at position `step`.
        // Search for its value-adjacent neighbor among positions `step+1` to `n`.
        for (int candidate = step + 1; candidate <= n; ++candidate) {
            // Move candidate to position `step+1` for testing adjacency.
            execute_swap(step + 1, candidate);
            std::swap(location[step + 1], location[candidate]);

            // Query on [step, step+1] checks if adjacent values exist.
            // Returns 3 if values are consecutive, otherwise 2.
            if (execute_query(step, step + 1) == 3) {
                // Found valid neighbor; keep it at position `step+1`.
                break;
            }

            // Not a neighbor; restore previous state for next candidate.
            execute_swap(step + 1, candidate);
            std::swap(location[step + 1], location[candidate]);
        }
    }

    // Now positions 1..n form a chain of consecutive integers.
    // The sequence must be either increasing (1,2,...,n) or decreasing (n,...,2,1).
    // Map positions to original indices and assign values accordingly.
    std::vector<int> final_solution(n + 1);
    for (int pos = 1; pos <= n; ++pos) {
        final_solution[location[pos]] = pos;
    }

    // Problem constraints ensure only two possible solutions exist; we output one.
    present_result(final_solution);
    return 0;
}

#include "llvm/Transforms/Utils/UnifyFunctionExitNodes.h"
#include "llvm/IR/BasicBlock.h"
#include "llvm/IR/Function.h"
#include "llvm/IR/Instructions.h"
#include "llvm/IR/Type.h"
#include "llvm/Transforms/Utils.h"

using namespace llvm;

namespace {
// Merge all unreachable terminators into a single block
bool consolidateUnreachableBlocks(Function &F) {
  std::vector<BasicBlock *> UnreachableList;
  for (BasicBlock &BB : F) {
    if (isa<UnreachableInst>(BB.getTerminator()))
      UnreachableList.push_back(&BB);
  }

  if (UnreachableList.size() <= 1)
    return false;

  BasicBlock *MergedBlock =
      BasicBlock::Create(F.getContext(), "MergedUnreachable", &F);
  new UnreachableInst(F.getContext(), MergedBlock);

  for (BasicBlock *BB : UnreachableList) {
    BB->getTerminator()->eraseFromParent();
    BranchInst::Create(MergedBlock, BB);
  }
  return true;
}

// Merge all return blocks into one, handling return values via PHI nodes
bool consolidateReturnBlocks(Function &F) {
  std::vector<BasicBlock *> ReturnList;
  for (BasicBlock &BB : F) {
    if (isa<ReturnInst>(BB.getTerminator()))
      ReturnList.push_back(&BB);
  }

  if (ReturnList.size() <= 1)
    return false;

  BasicBlock *NewReturnBlock = BasicBlock::Create(F.getContext(),
                                                  "MergedReturn", &F);
  PHINode *PN = nullptr;

  if (F.getReturnType()->isVoidTy()) {
    ReturnInst::Create(F.getContext(), NewReturnBlock);
  } else {
    PN = PHINode::Create(F.getReturnType(), ReturnList.size(), "MergedRetValue");
    PN->insertInto(NewReturnBlock, NewReturnBlock->end());
    ReturnInst::Create(F.getContext(), PN, NewReturnBlock);
  }

  for (BasicBlock *BB : ReturnList) {
    if (PN)
      PN->addIncoming(BB->getTerminator()->getOperand(0), BB);
    BB->getTerminator()->eraseFromParent();
    BranchInst::Create(NewReturnBlock, BB);
  }
  return true;
}
} // namespace

PreservedAnalyses UnifyFunctionExitNodesPass::run(Function &F,
                                                  FunctionAnalysisManager &AM) {
  bool Modified = false;
  Modified |= consolidateUnreachableBlocks(F);
  Modified |= consolidateReturnBlocks(F);
  return Modified ? PreservedAnalyses() : PreservedAnalyses::all();
}

