#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Structure representing an operation
struct Operation {
    int box_value;
    int dest_stack;
};

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int total_boxes, num_stacks;
    if (!(cin >> total_boxes >> num_stacks)) return 0;

    // Stacks are 1-indexed (index 0 unused)
    vector<vector<int>> stacks(num_stacks + 1);

    // Initialize stacks with given configuration
    int boxes_per_stack = total_boxes / num_stacks;
    for (int s = 1; s <= num_stacks; ++s) {
        for (int b = 0; b < boxes_per_stack; ++b) {
            int value;
            cin >> value;
            stacks[s].push_back(value);
        }
    }

    vector<Operation> sequence;
    int next_target = 1;

    // Process each box in order from 1 to total_boxes
    while (next_target <= total_boxes) {
        int source_stack = -1;
        int position_in_stack = -1;

        // Find where the current target box is located
        for (int s = 1; s <= num_stacks; ++s) {
            for (int p = 0; p < stacks[s].size(); ++p) {
                if (stacks[s][p] == next_target) {
                    source_stack = s;
                    position_in_stack = p;
                    break;
                }
            }
            if (source_stack != -1) break;
        }

        // If the target box is on top, remove it directly
        if (position_in_stack == (int)stacks[source_stack].size() - 1) {
            sequence.push_back({next_target, 0});
            stacks[source_stack].pop_back();
            next_target++;
            continue;
        }

        // Otherwise, determine how many boxes above need to be moved
        int count_above = stacks[source_stack].size() - 1 - position_in_stack;

        int optimal_chunk_size = -1;
        int optimal_destination = -1;
        long long best_evaluation = -2e18;

        // Try all possible chunk sizes
        for (int chunk = 1; chunk <= count_above; ++chunk) {
            int start_index = stacks[source_stack].size() - chunk;

            // Find maximum value in this chunk
            int max_in_chunk = -1;
            for (int k = 0; k < chunk; ++k) {
                max_in_chunk = max(max_in_chunk, stacks[source_stack][start_index + k]);
            }

            // Evaluate each possible destination stack
            for (int dest = 1; dest <= num_stacks; ++dest) {
                if (dest == source_stack) continue;

                int top_of_dest = stacks[dest].empty() ? 1000 : stacks[dest].back();

                long long evaluation;

                if (max_in_chunk < top_of_dest) {
                    // Valid move: maintain decreasing order
                    evaluation = 200000LL + (long long)chunk * 1000 - (top_of_dest - max_in_chunk);
                } else {
                    // Invalid move: place larger on smaller
                    evaluation = (long long)top_of_dest * 1000 + chunk;
                }

                if (evaluation > best_evaluation) {
                    best_evaluation = evaluation;
                    optimal_chunk_size = chunk;
                    optimal_destination = dest;
                }
            }
        }

        // Execute the best move
        int move_start = stacks[source_stack].size() - optimal_chunk_size;
        int first_moved_box = stacks[source_stack][move_start];

        sequence.push_back({first_moved_box, optimal_destination});

        // Transfer boxes to destination
        vector<int> transferred;
        transferred.reserve(optimal_chunk_size);
        for (int k = 0; k < optimal_chunk_size; ++k) {
            transferred.push_back(stacks[source_stack][move_start + k]);
        }

        stacks[source_stack].resize(move_start);
        for (int val : transferred) {
            stacks[optimal_destination].push_back(val);
        }
    }

    // Print the sequence of operations
    for (const auto& op : sequence) {
        cout << op.box_value << " " << op.dest_stack << "\n";
    }

    return 0;
}

