#include <iostream>
#include <cmath>
#include <algorithm>

class Solution {
public:
    // Compute greatest common divisor using binary method
    static int GCD(unsigned a, unsigned b) {
        const int tz_a = countr_zero(a), tz_b = countr_zero(b);
        const int min_tz = std::min(tz_a, tz_b);
        a >>= tz_a;
        b >>= tz_b;
        for (unsigned temp; b != 0; b = std::min(b, temp)) {
            temp = a % b;
            a = std::exchange(b, temp);
        }
        return a << min_tz;
    }

    // Count the number of Pythagorean triples with hypotenuse <= n
    static int countTriples(int limit) {
        int result = 0;
        int sqrt_limit = static_cast<int>(std::sqrt(limit));

        for (int m = 2; m <= sqrt_limit; m++) {
            for (int n = 1 + (m & 1); n < m; n += 2) {
                if (GCD(m, n) != 1) continue;

                int hypotenuse = m * m + n * n;
                if (hypotenuse > limit) break;

                int max_multiplier = limit / hypotenuse;
                result += 2 * max_multiplier;
            }
        }
        return result;
    }
};

#include <asio/dispatch.hpp>
#include <asio/post.hpp>
#include <asio/spawn.hpp>
