using asio::dispatch;
using asio::spawn;
using asio::strand;
using asio::thread_pool;
using asio::yield_context;

void display_result(std::string filename, std::string matched_line)
{
  std::cout << filename << ':' << matched_line << std::endl;
}

void process_file(std::string keyword, std::string filepath,
    strand<thread_pool::executor_type> sync_output, yield_context ctx)
{
  std::ifstream file_stream(filepath.c_str());
  std::string current_line;
  std::size_t line_index = 0;
  while (std::getline(file_stream, current_line))
  {
    // If a match is found, dispatch the result to the output strand
    if (current_line.find(keyword) != std::string::npos)
    {
      dispatch(sync_output, boost::bind(&display_result, filepath, current_line));
    }

    // Yield periodically to allow other coroutines to run
    if (++line_index % 10 == 0)
      post(ctx);
  }
}

int main(int argc, char* argv[])
{
  try
  {
    if (argc < 2)
    {
      std::cerr << "Usage: parallel_grep <pattern> <files...>\n";
      return 1;
    }

    // Create a thread pool for concurrent file processing
    thread_pool worker_pool;

    // Use a strand to ensure thread-safe output operations
    strand<thread_pool::executor_type> output_strand(worker_pool.get_executor());

    // Extract search term from command line arguments
    std::string search_term = argv[1];

    // Spawn coroutines for each input file
    for (int arg_idx = 2; arg_idx < argc; ++arg_idx)
    {
      std::string file_path = argv[arg_idx];
      spawn(worker_pool, boost::bind(&process_file,
            search_term, file_path, output_strand, _1));
    }

    // Wait for all tasks in the pool to complete
    worker_pool.join();
  }
  catch (std::exception& ex)
  {
    std::cerr << "Error: " << ex.what() << "\n";
  }

  return 0;
}

#include <iostream>
#include <functional>
#include <string>

// Standalone function
void standalone_func(int val) {
    std::cout << "standalone_func: " << val << std::endl;
}

// Callable struct
struct CallableStruct {
    void operator()(int val) const {
        std::cout << "CallableStruct: " << val << std::endl;
    }
};

// Class containing various callable members
struct DataHolder {
    void instance_method(int val) {
        std::cout << "DataHolder::instance_method: " << val << std::endl;
    }

    void readonly_method(int val) const {
        std::cout << "DataHolder::readonly_method: " << val << std::endl;
    }

    double value = 99;
};

void showcase_invoke_usage() {
    std::cout << "=== std::invoke Demonstration ===" << std::endl;

    CallableStruct c;
    DataHolder h;

    // Call free function
    std::invoke(standalone_func, 17);

    // Call functor
    std::invoke(c, 34);

    // Call lambda expression
    std::invoke([](int v) { std::cout << "LambdaExpr: " << v << std::endl; }, 55);

    // Invoke member function using object reference
    std::invoke(&DataHolder::instance_method, h, 8);

    // Invoke member function using pointer to object
    std::invoke(&DataHolder::instance_method, &h, 12);

    // Invoke const member function
    std::invoke(&DataHolder::readonly_method, h, 20);

    // Access data member
    double retrieved = std::invoke(&DataHolder::value, h);
    std::cout << "DataHolder::value = " << retrieved << std::endl;
}

void contrast_with_old_style() {
    std::cout << "\n=== Old Style vs std::invoke ===" << std::endl;

    DataHolder h;

    // Legacy approach
    std::cout << "Legacy:" << std::endl;
    h.instance_method(4);                    // Direct invocation
    (h.*&DataHolder::instance_method)(6);    // Pointer-to-member with ref
    (&h->*&DataHolder::instance_method)(9);  // Pointer-to-member with ptr

    // Unified syntax via std::invoke
    std::cout << "\nUnified via std::invoke:" << std::endl;
    std::invoke(&DataHolder::instance_method, h, 4);
    std::invoke(&DataHolder::instance_method, &h, 6);
}

void integrate_with_std_function() {
    std::cout << "\n=== std::invoke with std::function ===" << std::endl;

    std::function<void(int)> wrapper = [](int v) {
        std::cout << "std::function wrapper: " << v << std::endl;
    };

    std::invoke(wrapper, 200);
}

void handle_reference_wrapper() {
    std::cout << "\n=== std::invoke with std::reference_wrapper ===" << std::endl;

    DataHolder h;
    auto wrapped = std::ref(h);

    std::invoke(&DataHolder::instance_method, wrapped, 11);
}

int main() {
    showcase_invoke_usage();
    contrast_with_old_style();
    integrate_with_std_function();
    handle_reference_wrapper();

    std::cout << "\n=== Advantages of std::invoke ===" << std::endl;
    std::cout << "- Consistent calling interface across all callable entities" << std::endl;
    std::cout << "- Eliminates need for .* and ->* operators" << std::endl;
    std::cout << "- Compatible with std::reference_wrapper objects" << std::endl;
    std::cout << "- Supports generic templates that accept arbitrary callables" << std::endl;

    return 0;
}

