using test_service_package::IntRequest;
using test_service_package::IntReply;
using test_service_package::Decompositor;

class DecompositionClient {
 public:
  DecompositionClient(std::shared_ptr<Channel> channel)
      : stub_(Decompositor::NewStub(channel)) {}

  // Sends a request to decompose an integer and returns the server's response
  std::string ProcessInteger(const int& input_value) {
    // Prepare the request with the input value
    IntRequest request;
    request.set_value(input_value);

    // Object to hold the response from the server
    IntReply reply;

    // Client context for RPC configuration
    ClientContext context;

    // Perform the RPC call
    Status status = stub_->Decompose(&context, request, &reply);

    // Handle the result
    if (status.ok()) {
      return reply.message();
    } else {
      std::cerr << "Error code: " << status.error_code() 
                << ", Message: " << status.error_message() << std::endl;
      return "RPC invocation failed";
    }
  }

 private:
  std::unique_ptr<Decompositor::Stub> stub_;
};

int main(int argc, char** argv) {
  // Create client with insecure channel to localhost:50051
  DecompositionClient client(grpc::CreateChannel(
      "localhost:50051", grpc::InsecureChannelCredentials()));

  int number_to_process = 42;
  std::string result = client.ProcessInteger(number_to_process);

  std::cout << "Response from server: " << result << std::endl;
