#include "IntBuffer.h"

// Creates a new integer buffer with specified capacity
// The buffer will have position=0, limit=capacity, and an undefined mark
// It uses a newly allocated backing array starting at offset 0
//
// Parameters:
// size - The maximum number of integers the buffer can hold
IntBuffer::IntBuffer(unsigned int size) : Buffer(size)
{
	dataArray = new int[size];
	memset(dataArray, 0, sizeof(int) * size);
}

// Creates a new integer buffer using an existing array as backing storage
// The buffer will have position=0, limit=capacity, and an undefined mark
//
// Parameters:
// size - The maximum number of integers the buffer can hold
// externalArray - Pre-allocated integer array to use as backing store
IntBuffer::IntBuffer(unsigned int size, int* externalArray) : Buffer(size)
{
	hasBackingArray = true;
	dataArray = externalArray;
}

IntBuffer::~IntBuffer()
{
	if (!hasBackingArray)
		delete[] dataArray;
}

int* IntBuffer::getInternalArray()
{
	return dataArray;
}

// Reverses the buffer's state by setting the limit to current position and resetting position to zero
// Any existing mark is cleared
//
// Returns:
// Reference to this buffer for method chaining
IntBuffer* IntBuffer::flip()
{
	m_limit = m_position;
	m_position = 0;
	return this;
}

// Reads an integer from a specific location in the buffer
//
// Parameters:
// idx - Zero-based index within the buffer's current limit
// Returns:
// The integer value stored at the specified position
int IntBuffer::get(unsigned int idx)
{
	assert(idx < m_limit);
	return dataArray[idx];
}

// Copies multiple integers from a source array into this buffer
// Transfers elements starting at 'startIdx' in the source array for 'count' elements
// into this buffer beginning at the current position
//
// Parameters:
// source - Source array containing integers to copy
// startIdx - First element index in source array to read (must be valid)
// count - Number of elements to transfer (must fit in remaining buffer space)
// Returns:
// Reference to this buffer for method chaining
IntBuffer* IntBuffer::put(intArray* srcArray, unsigned int startIdx, unsigned int count)
{
	assert(startIdx + count < srcArray->length);
	std::copy(srcArray->data + startIdx, srcArray->data + startIdx + count, dataArray + m_position);
	m_position += count;
	return this;
}

// Copies all elements from a source array into this buffer
// 
// Parameters:
// source - Complete source array to copy from
// Returns:
// Reference to this buffer for method chaining
IntBuffer* IntBuffer::put(intArray srcData)
{
	if (srcData.length > remaining())
		assert(false); // TODO 4J Stu - Some kind of exception?

	std::copy(srcData.data, srcData.data + srcData.length, dataArray + m_position);
	m_position += srcData.length;
	return this;
}

// Writes a single integer to the current position and advances the position pointer
//
// Parameters:
// value - Integer to store in the buffer
// Returns:
// Reference to this buffer for method chaining
IntBuffer* IntBuffer::put(int value)
{
	assert(m_position < m_limit);
	dataArray[m_position++] = value;
	return this;
}

