    ::GetConsoleMode(consoleHandle, &modeFlags);

    // Attempt to enable virtual terminal processing; fall back if it fails
    if (!::SetConsoleMode(consoleHandle, modeFlags | ENABLE_VIRTUAL_TERMINAL_PROCESSING)) {
        log::options().disableAllColors = true;
    }

    // Set output code page to UTF-8
    ::SetConsoleOutputCP(CP_UTF8);

    // Add backup privileges to current process
    ASSERTD_MSG(!addRights(),
                "Failed to acquire backup privileges for the process");

    // Register console control handler
    ::SetConsoleCtrlHandler(plat::consoleEventHandler, TRUE);

    // Override default COM error handling to use logging instead of exceptions
    ::_set_com_error_handler([](HRESULT errorCode, IErrorInfo *) noexcept {
        if (log::isLevelEnabled<false>(Lvl::Error)) {
            APERR(errorCode, "Global COM error encountered");
        }
    });

    // Initialize Winsock
    WSADATA wsaData = {};
    int socketResult = ::WSAStartup(MAKEWORD(2, 2), &wsaData);
    if (socketResult != 0) {
        ASSERTD_MSG(false, "Failed to initialize socket manager", socketResult);
    }
}

void deinit() noexcept {
    // Cleanup Winsock resources
    ::WSACleanup();
}

