using namespace lbug::binder;
namespace lbug {
namespace planner {

std::string LogicalPlanUtil::encodeJoin(LogicalPlan& plan) {
    return encode(plan.getLastOperator().get());
}

std::string LogicalPlanUtil::encode(LogicalOperator* op) {
    std::string encoded;
    encodeRecursive(op, encoded);
    return encoded;
}

void LogicalPlanUtil::encodeRecursive(LogicalOperator* op, std::string& buffer) {
    switch (op->getOperatorType()) {
    case LogicalOperatorType::CROSS_PRODUCT: {
        encodeCrossProduct(op, buffer);
        for (size_t idx = 0; idx < op->getNumChildren(); ++idx) {
            buffer += "{";
            encodeRecursive(op->getChild(idx).get(), buffer);
            buffer += "}";
        }
    } break;
    case LogicalOperatorType::INTERSECT: {
        encodeIntersect(op, buffer);
        for (size_t idx = 0; idx < op->getNumChildren(); ++idx) {
            buffer += "{";
            encodeRecursive(op->getChild(idx).get(), buffer);
            buffer += "}";
        }
    } break;
    case LogicalOperatorType::HASH_JOIN: {
        encodeHashJoin(op, buffer);
        buffer += "{";
        encodeRecursive(op->getChild(0).get(), buffer);
        buffer += "}{";
        encodeRecursive(op->getChild(1).get(), buffer);
        buffer += "}";
    } break;
    case LogicalOperatorType::EXTEND: {
        encodeExtend(op, buffer);
        encodeRecursive(op->getChild(0).get(), buffer);
    } break;
    case LogicalOperatorType::SCAN_NODE_TABLE: {
        encodeScanNodeTable(op, buffer);
    } break;
    case LogicalOperatorType::FILTER: {
        encodeFilter(op, buffer);
        encodeRecursive(op->getChild(0).get(), buffer);
    } break;
    default:
        for (size_t idx = 0; idx < op->getNumChildren(); ++idx) {
            encodeRecursive(op->getChild(idx).get(), buffer);
        }
    }
}

void LogicalPlanUtil::encodeCrossProduct(LogicalOperator* /*op*/, std::string& buffer) {
    buffer += "CP()";
}

void LogicalPlanUtil::encodeIntersect(LogicalOperator* op, std::string& buffer) {
    auto& intersectOp = op->constCast<LogicalIntersect>();
    buffer += "I(" + intersectOp.getIntersectNodeID()->toString() + ")";
}

void LogicalPlanUtil::encodeHashJoin(LogicalOperator* op, std::string& buffer) {
    auto& joinOp = op->constCast<LogicalHashJoin>();
    buffer += "HJ(" + joinOp.getExpressionsForPrinting() + ")";
}

void LogicalPlanUtil::encodeExtend(LogicalOperator* op, std::string& buffer) {
    auto& extendOp = op->constCast<LogicalExtend>();
    buffer += "E(" + extendOp.getNbrNode()->toString() + ")";
}

void LogicalPlanUtil::encodeScanNodeTable(LogicalOperator* op, std::string& buffer) {
    auto& scanOp = op->constCast<LogicalScanNodeTable>();
    if (scanOp.getScanType() == LogicalScanNodeTableType::PRIMARY_KEY_SCAN) {
        buffer += "IndexScan";
    } else {
        buffer += "S";
    }
    buffer += "(" + scanOp.getNodeID()->constCast<PropertyExpression>().getRawVariableName() + ")";
}

void LogicalPlanUtil::encodeFilter(LogicalOperator*, std::string& buffer) {
    buffer += "Filter()";
}

