// Helper function to interact with the system by moving.
// It sends the move command and returns the interactor's response.
int execute_move(int color) {
    std::cout << "move " << color << std::endl;
    int response;
    std::cin >> response;
    return response;
}

// Helper function to query the current distance to the exit.
int get_distance() {
    std::cout << "query" << std::endl;
    int distance;
    std::cin >> distance;
    return distance;
}

int main() {
    // Fast I/O for competitive programming
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int startingDepth;
    std::cin >> startingDepth;
    int remainingDistance = startingDepth;

    // If we start at the exit, we are done.
    if (remainingDistance == 0) {
        return 0;
    }

    int incomingColor;

    // --- First step ---
    // At the beginning, we have no information. We test colors 0 and 1.
    // If both lead down, color 2 must be the way up.
    int upwardColor = -1;
    for (int color = 0; color < 2; ++color) {
        if (execute_move(color) == 1) {
            return 0;
        }
        int newDist = get_distance();
        if (newDist < remainingDistance) {
            upwardColor = color;
            break;
        }
        execute_move(color); // Move back
    }

    if (upwardColor == -1) {
        upwardColor = 2;
        if (execute_move(upwardColor) == 1) {
            return 0;
        }
    }

    remainingDistance--;
    incomingColor = upwardColor;

    // --- Subsequent steps ---
    // For every step after the first, we know the color of the edge we just used.
    // This color leads "down", so we only need to test the other two colors.
    while (remainingDistance > 0) {
        // Determine the other two colors to test using modulo arithmetic
        int altColor1 = (incomingColor + 1) % 3;
        int altColor2 = (incomingColor + 2) % 3;

        // Test the first candidate color
        if (execute_move(altColor1) == 1) {
            return 0;
        }
        int newDist = get_distance();
        if (newDist < remainingDistance) {
            // altColor1 is the "up" color
            upwardColor = altColor1;
        } else {
            // altColor1 leads "down", so move back.
            execute_move(altColor1);
            // By elimination, altColor2 must be the "up" color.
            upwardColor = altColor2;
            if (execute_move(upwardColor) == 1) {
                return 0;
            }
        }
        remainingDistance--;
        incomingColor = upwardColor;
    }

    return 0;
}

