namespace unravel
{
    selection_action_t::selection_action_t(editing_manager* mgr,
                                           const std::vector<entt::meta_any>& prev_sel,
                                           const std::vector<entt::meta_any>& curr_sel, bool is_select)
        : manager(mgr), old_selection(prev_sel), new_selection(curr_sel), is_select(is_select)
    {
        name = is_select ? "Select" : "Unselect";
        undoable = true;
    }

    void selection_action_t::do_action()
    {
        if (!manager)
        {
            return;
        }
        // Apply the current selection state using the internal method
        manager->restore_selection_impl(new_selection);
    }

    void selection_action_t::undo_action()
    {
        if (!manager)
        {
            return;
        }
        // Revert to the previous selection state using the internal method
        manager->restore_selection_impl(old_selection);
    }

    auto selection_action_t::is_mergeable(const editing_action_t& prior) const -> bool
    {
        const auto& other_selection_action = static_cast<const selection_action_t&>(prior);
        if(other_selection_action.is_select != is_select)
        {
            return false;
        }

        // For sequential selection actions (like area picking), merge if:
        // The current action's old_selection matches the prior action's new_selection
        // This means the current action continues from where the prior one ended

        // Handle empty selections
        if(old_selection.empty() && other_selection_action.new_selection.empty())
        {
            return true;
        }

        if(old_selection.size() != other_selection_action.new_selection.size())
        {
            return false;
        }

        // Check if old_selection matches prior new_selection (order-independent comparison)
        // This handles cases where entities are selected in different orders
        for(const auto& curr_old_item : old_selection)
        {
            bool found = false;
            for(const auto& prior_new_item : other_selection_action.new_selection)
            {
                if(curr_old_item == prior_new_item)
                {
                    found = true;
                    break;
                }
            }
            if(!found)
            {
                return false;
            }
        }
        return true;
    }

    void selection_action_t::merge_with(const editing_action_t& prior)
    {
        // When merging, retain the old_selection from the prior action
        // and preserve the new_selection from the current action (which represents the latest state)
        const auto& other_selection_action = static_cast<const selection_action_t&>(prior);
        old_selection = other_selection_action.old_selection;
        // new_selection remains unchanged (it reflects the most recent state)
    }

    auto selection_action_t::is_valid() const -> bool
    {
        return manager != nullptr;
    }
} // namespace unravel

