// Function to perform a query on the range [low, high]
int performQuery(int low, int high) {
    std::cout << "? " << low << " " << high << std::endl;
    int response;
    std::cin >> response;
    return response;
}

// Function to output the final result and flush the stream
void outputResult(int value) {
    std::cout << "! " << value << std::endl;
}

// Core logic for processing each test case
void processTestCase() {
    int size;
    std::cin >> size;

    // First, locate the position of the second largest element (value n-1)
    int pivot = performQuery(1, size);

    // Determine whether the maximum element 'n' lies to the left or right of 'pivot'
    bool maxOnLeft = false;
    if (pivot > 1) {
        int check = performQuery(1, pivot);
        if (check == pivot) {
            maxOnLeft = true;
        }
    }

    if (maxOnLeft) {
        // Search for 'n' in the interval [1, pivot-1]
        int left = 1, right = pivot - 1;
        while (left < right) {
            int mid = left + (right - left) / 2; // Floor division

            int res = performQuery(mid + 1, pivot);
            if (res == pivot) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        outputResult(left);
    } else {
        // Search for 'n' in the interval [pivot+1, size]
        int left = pivot + 1, right = size;
        while (left < right) {
            int mid = left + (right - left + 1) / 2; // Ceiling division

            int res = performQuery(pivot, mid - 1);
            if (res == pivot) {
                right = mid - 1;
            } else {
                left = mid;
            }
        }
        outputResult(left);
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int testCases;
    std::cin >> testCases;

    while (testCases--) {
        processTestCase();
    }

    return 0;
}

#include <vector>
using namespace std;

// Determine if the last character is a one-bit character
class Solution {
public:
    bool isOneBitCharacter(vector<int>& data) {
        const int length = data.size();
        int index = 0;
        for (; index < length - 1; index++) {
            if (data[index] == 1) index++;
        }
        return index == length - 1;
    }
};

