std::vector<rclcpp::Node::SharedPtr> ComponentLoader::load_and_create_nodes(
  const std::vector<rslcpp::dynamic_composition::ComponentDescription> & component_list,
  rclcpp::NodeOptions const & node_options)
{
  std::vector<rclcpp::Node::SharedPtr> created_nodes;
  for (const auto & comp : component_list) {
    created_nodes.emplace_back(load_single_component(comp, node_options));
  }
  return created_nodes;
}

/// @brief Load a single RCLCPP component and instantiate its node
/// @param comp_desc Description of the component to load
/// @return std::shared_ptr<rclcpp::Node> Pointer to the newly created node
std::shared_ptr<rclcpp::Node> ComponentLoader::load_single_component(
  rslcpp::dynamic_composition::ComponentDescription const & comp_desc,
  rclcpp::NodeOptions const & base_options)
{
  std::cout << ">> Loading Component | " << comp_desc.component_name << std::endl;

  std::string lib_path = rslcpp::dynamic_composition::utils::get_shared_library_path(comp_desc);

  if (loaders.find(lib_path) == loaders.end()) {
    loaders[lib_path] = std::make_unique<class_loader::ClassLoader>(lib_path);
  }

  std::string factory_class =
    "rclcpp_components::NodeFactoryTemplate<" + comp_desc.component_name + ">";

  auto factory_instance =
    loaders[lib_path]->createInstance<rclcpp_components::NodeFactory>(factory_class);

  // Customize options with component-specific arguments
  rclcpp::NodeOptions custom_options = base_options;
  custom_options.arguments(comp_desc.component_arguments);

  // Instantiate the node
  auto node_wrapper = factory_instance->create_node_instance(custom_options);
  auto node_ptr = std::static_pointer_cast<rclcpp::Node>(node_wrapper.get_node_instance());

  stored_wrappers.push_back(node_wrapper);
  return node_ptr;
}

std::vector<ComponentDescription> parse_components_from_command_line_arguments(
  int & arg_count, char **& arg_values)
{
  std::vector<ComponentDescription> parsed_components;
  std::size_t idx = 0;

  while (idx < static_cast<std::size_t>(arg_count)) {
    // Stop parsing when encountering ROS-specific args
    if (std::string(arg_values[idx]) == "--ros-args") {
      break;
    }

    if (std::string(arg_values[idx]) == "--component") {
      // Locate the end of this component's argument block
      std::size_t end_idx = idx + 1;
      while (end_idx < static_cast<std::size_t>(arg_count)) {
        std::string current_arg = std::string(arg_values[end_idx]);
        if (current_arg == "--ros-args" || current_arg == "--component") {
          break;
        }
        end_idx++;
      }

      std::size_t num_sub_args = end_idx - idx - 1;
      if (num_sub_args < 2) {
        throw std::runtime_error(
          "DynamicComposition | '--component' specified without package and class arguments.");
      }

      // Extract required fields: package and component name
      std::string pkg_name = arg_values[idx + 1];
      std::string cls_name = arg_values[idx + 2];

      std::vector<std::string> extra_args;
      if (num_sub_args >= 3) {
        if (std::string(arg_values[idx + 3]) == "--ros-args") {
          extra_args.push_back("--ros-args");
        } else {
          throw std::runtime_error(
            "DynamicComposition | If you want to add per-component arguments, use "
            "'--component-ros-args' after the component name");
        }
      }

      // Collect additional arguments beyond the first three
      for (std::size_t k = 4; k <= num_sub_args; ++k) {
        extra_args.push_back(arg_values[idx + k]);
      }

      parsed_components.emplace_back(pkg_name, cls_name, extra_args);

      idx += num_sub_args + 1;
      continue;
    }

    idx++;
  }

  // Shift remaining arguments forward and adjust counts
  arg_values += idx;
  arg_count -= idx;

  if (arg_count <= 0) {
    arg_count = 0;
    arg_values = nullptr;
  }

  return parsed_components;
}
}  // namespace rslcpp::dynamic_composition

