int main() {
    // Initialize a JSON structure with different data
    json data = {
        {"value", 10}, 
        {"text", "hello"}, 
        {"list", {5, 6}}
    };

    // Access elements using JSON pointers
    std::cout << data["/value"_json_pointer] << '\n';
    std::cout << data["/text"_json_pointer] << '\n';
    std::cout << data["/list"_json_pointer] << '\n';
    std::cout << data["/list/0"_json_pointer] << '\n';

    // Modify existing values
    data["/text"_json_pointer] = "world";
    std::cout << data["text"] << '\n';

    // Add new key-value pair
    data["/active"_json_pointer] = false;
    std::cout << data << '\n';

    // Update array element
    data["/list/1"_json_pointer] = 99;

    // Extend array with new index
    data["/list/3"_json_pointer] = 77;
    std::cout << data["list"] << '\n';

    // Append to array using "-" pointer
    data["/list/-"_json_pointer] = 88;
    std::cout << data["list"] << '\n';

    return 0;
}

#include <iostream>
#include <vector>
#include <string>

int main() {
    // Optimize input/output operations for speed
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // Set grid size - using 19x19 to have a distinct central cell
    int rows = 19;
    int cols = 19;

    // Output the dimensions of the grid
    std::cout << rows << " " << cols << "\n";

    // Initialize the grid with walls (represented by '0')
    std::vector<std::string> grid(rows, std::string(cols, '0'));

    // Calculate center indices for the cross pattern
    int mid_row = rows / 2;
    int mid_col = cols / 2;

    // Draw the vertical line of the cross
    for (int r = 0; r < rows; ++r) {
        grid[r][mid_col] = '1';
    }

    // Draw the horizontal line of the cross
    // The intersection point gets set twice, which doesn't cause issues
    for (int c = 0; c < cols; ++c) {
        grid[mid_row][c] = '1';
    }

    // Display the final grid
    for (int r = 0; r < rows; ++r) {
        std::cout << grid[r] << "\n";
    }

    return 0;
}

