using namespace llvm;
namespace {
/// Regular expression corresponding to the value given in one of the
/// -pass-remarks* command line flags. Passes whose name matches this regexp
/// will emit a diagnostic when calling the associated diagnostic function
/// (emitOptimizationRemark, emitOptimizationRemarkMissed or
/// emitOptimizationRemarkAnalysis).
struct RemarkFilter {
  std::shared_ptr<Regex> Pattern;
  void operator=(const std::string &Val) {
    // Create a regexp object to match pass names for emitOptimizationRemark.
    if (!Val.empty()) {
      Pattern = std::make_shared<Regex>(Val);
      std::string RegexError;
      if (!Pattern->isValid(RegexError))
        report_fatal_error(Twine("Invalid regular expression '") + Val +
                               "' in -pass-remarks: " + RegexError,
                           false);
    }
  }
};
static RemarkFilter PassedRemarksFilter;
static RemarkFilter MissedRemarksFilter;
static RemarkFilter AnalysisRemarksFilter;
// -pass-remarks
//    Command line flag to enable emitOptimizationRemark()
static cl::opt<RemarkFilter, true, cl::parser<std::string>> PassRemarks(
    "pass-remarks", cl::value_desc("pattern"),
    cl::desc("Enable optimization remarks from passes whose name match "
             "the given regular expression"),
    cl::Hidden, cl::location(PassedRemarksFilter), cl::ValueRequired);
// -pass-remarks-missed
//    Command line flag to enable emitOptimizationRemarkMissed()
static cl::opt<RemarkFilter, true, cl::parser<std::string>> PassRemarksMissed(
    "pass-remarks-missed", cl::value_desc("pattern"),
    cl::desc("Enable missed optimization remarks from passes whose name match "
             "the given regular expression"),
    cl::Hidden, cl::location(MissedRemarksFilter), cl::ValueRequired);
// -pass-remarks-analysis
//    Command line flag to enable emitOptimizationRemarkAnalysis()
static cl::opt<RemarkFilter, true, cl::parser<std::string>>
    PassRemarksAnalysis(
        "pass-remarks-analysis", cl::value_desc("pattern"),
        cl::desc(
            "Enable optimization analysis remarks from passes whose name match "
            "the given regular expression"),
        cl::Hidden, cl::location(AnalysisRemarksFilter), cl::ValueRequired);
}
bool DiagnosticHandler::isAnalysisRemarkEnabled(StringRef PassName) const {
  return (AnalysisRemarksFilter.Pattern &&
          AnalysisRemarksFilter.Pattern->match(PassName));
}
bool DiagnosticHandler::isMissedOptRemarkEnabled(StringRef PassName) const {
  return (MissedRemarksFilter.Pattern &&
          MissedRemarksFilter.Pattern->match(PassName));
}
bool DiagnosticHandler::isPassedOptRemarkEnabled(StringRef PassName) const {
  return (PassedRemarksFilter.Pattern &&
          PassedRemarksFilter.Pattern->match(PassName));
}
bool DiagnosticHandler::isAnyRemarkEnabled() const {
  return (PassedRemarksFilter.Pattern || MissedRemarksFilter.Pattern ||
          AnalysisRemarksFilter.Pattern);
}

