// Force static initialization.
extern "C" LLVM_EXTERNAL_VISIBILITY void LLVMInitializeWebAssemblyTargetMC() {
  for (Target *target :
       {&getTheWebAssemblyTarget32(), &getTheWebAssemblyTarget64()}) {
    // Register the MC asm info.
    RegisterMCAsmInfoFn X(*target, createMCAsmInfo);
    // Register the MC instruction info.
    TargetRegistry::RegisterMCInstrInfo(*target, createMCInstrInfo);
    // Register the MC register info.
    TargetRegistry::RegisterMCRegInfo(*target, createMCRegisterInfo);
    // Register the MCInstPrinter.
    TargetRegistry::RegisterMCInstPrinter(*target, createMCInstPrinter);
    // Register the MC code emitter.
    TargetRegistry::RegisterMCCodeEmitter(*target, createCodeEmitter);
    // Register the ASM Backend.
    TargetRegistry::RegisterMCAsmBackend(*target, createAsmBackend);
    // Register the MC subtarget info.
    TargetRegistry::RegisterMCSubtargetInfo(*target, createMCSubtargetInfo);
    // Register the object target streamer.
    TargetRegistry::RegisterObjectTargetStreamer(*target,
                                                 createObjectTargetStreamer);
    // Register the asm target streamer.
    TargetRegistry::RegisterAsmTargetStreamer(*target, createAsmTargetStreamer);
    // Register the null target streamer.
    TargetRegistry::RegisterNullTargetStreamer(*target, createNullTargetStreamer);
  }
}

