// Selects token based on boolean condition
MatchForwardOrderSafe::token MatchForwardOrderSafe::choose(const bool flag) {
  if (flag) {
    return token::A;
  } else {
    return token::B;
  }
}

// Encodes token value to unsigned integer representation
unsigned int
MatchForwardOrderSafe::encode(const MatchForwardOrderSafe::token tokenValue) {
  return [&](void) {
    switch (tokenValue) {
    case token::A: {
      return (1 * 1);
    }
    case token::B: {
      return 0;
    }
    }
  }();
}

