#include <iostream>
#include <map>
#include <string>

#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>

struct data_container {
    std::map<std::string, int> container_data {
        { "alpha", 15 },
        { "beta", 45 },
        { "gamma", 25 },
        { "delta", 8 },
    };

    data_container() = default;
};

struct custom_iterator {
    using iterator_type = std::map<std::string, int>::iterator;
    iterator_type current;
    iterator_type end;

    custom_iterator(data_container& dc)
    : current(dc.container_data.begin()), end(dc.container_data.end()) {
    }
};

int iterate_next(lua_State* L) {
    custom_iterator& iter_state = sol::stack::get<sol::user<custom_iterator>>(L, 1);
    auto& iter = iter_state.current;

    if (iter == iter_state.end) {
        return sol::stack::push(L, sol::lua_nil);
    }

    auto pair_value = *iter;
    int pushed_count = sol::stack::push(L, pair_value.first);
    pushed_count += sol::stack::push_reference(L, pair_value.second);

    ++iter;
    return pushed_count;
}

int iterate_pairs(lua_State* L) {
    data_container& container = sol::stack::get<data_container>(L, 1);
    custom_iterator iter_obj(container);

    int pushed = sol::stack::push(L, iterate_next);
    pushed += sol::stack::push<sol::user<custom_iterator>>(L, std::move(iter_obj));
    pushed += sol::stack::push(L, sol::lua_nil);

    return pushed;
}

int main(int, char*[]) {
    std::cout << "===== Custom pairs iteration example =====" << std::endl;

    sol::state lua_vm;
    lua_vm.open_libraries(sol::lib::base);

    lua_vm.new_usertype<data_container>(
        "data_container",
        sol::meta_function::pairs, &iterate_pairs
    );

#if SOL_LUA_VERSION_I_ > 501
    lua_vm.safe_script(R"(
local dc = data_container.new()
for key, value in pairs(dc) do 
    print(key, value) 
end
)");
#endif

    std::cout << std::endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <set>
#include <algorithm>

// Process one test case
void process() {
    int count;
    std::cin >> count;
    std::set<std::string> collected;

    // Try each starting character from 'a' to 'z'
    for (char ch = 'a'; ch <= 'z'; ++ch) {
        if (collected.size() == count) {
            break;
        }

        std::string base(1, ch);
        int limit = 1;

        // Binary search-like probing for words with this prefix
        while (true) {
            if (collected.size() == count) {
                break;
            }

            std::cout << "ask " << base << " " << limit << std::endl;
            int received;
            std::cin >> received;

            for (int idx = 0; idx < received; ++idx) {
                std::string item;
                std::cin >> item;
                collected.insert(item);
            }

            // If we got fewer items than requested, no more words exist for this prefix
            if (received < limit) {
                break;
            }

            // Prevent over-asking when near the total count
            if (limit == count) {
                break;
            }

            // Increase the query size exponentially
            limit *= 2;
            if (limit > count) {
                limit = count;
            }
        }
    }

    // Print the final result
    std::cout << "result";
    for (const auto& str : collected) {
        std::cout << " " << str;
    }
    std::cout << std::endl;
}

int main() {
    // Optimize I/O operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int cases;
    std::cin >> cases;
    while (cases--) {
        process();
    }

    return 0;
}

