namespace {
template <typename Container>
void benchmark_swap(std::string_view label) {
    Container first;
    Container second;
    ankerl::nanobench::Rng generator(456);
    ankerl::nanobench::Bench measurement;

    for (size_t iteration = 0; iteration < 10000; ++iteration) {
        first[generator()];
        second[generator()];
    }

    measurement.run(fmt::format("exchange {}", label), [&] {
        std::swap(first, second);
    });

    ankerl::nanobench::doNotOptimizeAway(&first);
    ankerl::nanobench::doNotOptimizeAway(&second);
}
} // namespace

