static void glewPrintExtensionInfo (const char* extensionName, GLboolean condition1, GLboolean condition2, GLboolean condition3)
{
  unsigned int index;
  fprintf(logFile, "\n%s:", extensionName);
  for (index = 0; index < 62 - strlen(extensionName); index++) 
    fprintf(logFile, " ");

  fprintf(logFile, "%s ", condition1 ? "OK" : "MISSING");

  if (condition1 != condition2)
    fprintf(logFile, "[%s] ", condition2 ? "OK" : "MISSING");

  if (condition1 != condition3)
    fprintf(logFile, "[%s]\n", condition3 ? "OK" : "MISSING");
  else
    fprintf(logFile, "\n");

  for (index = 0; index < strlen(extensionName) + 1; index++) 
    fprintf(logFile, "-");

  fprintf(logFile, "\n");
  fflush(logFile);
}

static void glewReportFunctionStatus (const char* functionName, GLint isUndefined)
{
  unsigned int index;
  fprintf(logFile, "  %s:", functionName);
  for (index = 0; index < 60 - strlen(functionName); index++) 
    fprintf(logFile, " ");

  fprintf(logFile, "%s\n", isUndefined ? "MISSING" : "OK");
  fflush(logFile);
}

