#include <iostream>
#include <vector>
#include <algorithm> // for sort function
using namespace std;

int main() {
    vector<int> data = {5, 2, 8, 1, 4}; // vector of integers
    vector<int> dataDesc = {5, 2, 8, 1, 4}; // vector of integers

    // Sort in ascending order
    sort(data.begin(), data.end());
    cout << "Vector sorted ascending: ";
    for(int element : data) {
        cout << element << " ";
    }
    cout << endl;

    // Sort in descending order
    sort(dataDesc.begin(), dataDesc.end(), greater<int>());
    cout << "Vector sorted descending: ";
    for(int element : dataDesc) {
        cout << element << " ";
    }
    cout << endl;

    int numbers[5] = {5, 2, 8, 1, 4}; // array of integers
    sort(numbers, numbers + 5); // sort the array in ascending order
    cout << "Array sorted ascending: ";
    for(int i = 0; i < 5; i++) {
        cout << numbers[i] << " ";
    }
    cout << endl;

    sort(numbers, numbers + 5, greater<int>()); // sort the array in descending order
    cout << "Array sorted descending: ";
    for(int i = 0; i < 5; i++) {
        cout << numbers[i] << " ";
    }
    cout << endl;

    return 0;
}

