namespace {
class MLIRSetup {
public:
    static MLIRSetup& get() {
        static MLIRSetup setup;
        return setup;
    }
    mlir::DialectRegistry& get_registry() { return registry_; }
private:
    MLIRSetup() {
        // Initialize all standard MLIR dialects
        mlir::registerAllDialects(registry_);
        // Register all available passes
        mlir::registerAllPasses();
        // Setup SDFG-related components
        ::sdfg::codegen::register_default_dispatchers();
        ::sdfg::serializer::register_default_serializers();
    }
    mlir::DialectRegistry registry_;
};

class PythonMLIRWrapper {
public:
    explicit PythonMLIRWrapper(const std::string& input_mlir) {
        auto& setup = MLIRSetup::get();
        context_ = std::make_unique<mlir::MLIRContext>(setup.get_registry());
        context_->loadAllAvailableDialects();
        module_ = mlir::parseSourceString<mlir::ModuleOp>(input_mlir, context_.get());
        if (!module_) {
            throw std::runtime_error("Error parsing MLIR input");
        }
    }

    std::string dump() {
        std::string output;
        llvm::raw_string_ostream stream(output);
        module_->print(stream);
        return output;
    }

    void apply_transformations() {
        mlir::PassManager manager(context_.get());
        manager.addPass(mlir::createLinalgSpecializeGenericOpsPass());
        if (mlir::failed(manager.run(*module_))) {
            throw std::runtime_error("Transformation pipeline failed");
        }
    }

    std::string export_to_sdfg() {
        std::string buffer;
        llvm::raw_string_ostream os(buffer);
        if (mlir::failed(mlir::sdfg::translateToSDFG(module_->getOperation(), os))) {
            throw std::runtime_error("Translation to SDFG format failed");
        }
        return buffer;
    }

    mlir::Operation* native_handle() { return module_->getOperation(); }

private:
    std::unique_ptr<mlir::MLIRContext> context_;
    mlir::OwningOpRef<mlir::ModuleOp> module_;
};
} // anonymous namespace

PYBIND11_MODULE(_sdfg_mlir_backend, mod) {
    mod.doc() = "Python bindings for MLIR-based SDFG generation";

    py::class_<PythonMLIRWrapper>(mod, "MLIRModule")
        .def(py::init<const std::string&>(), py::arg("source"), 
             "Construct MLIR module from textual representation")
        .def("dump", &PythonMLIRWrapper::dump, "Return the module as a string")
        .def("apply_passes", &PythonMLIRWrapper::apply_transformations, 
             "Apply Linalg-specific transformations")
        .def("to_sdfg", &PythonMLIRWrapper::export_to_sdfg, 
             "Convert module to serialized SDFG format");
}

#include <asio/io_context.hpp>
#include <asio/ip/tcp.hpp>
#include <asio/spawn.hpp>
#include <asio/steady_timer.hpp>
#include <asio/write.hpp>
#include <iostream>
#include <memory>

using asio::ip::tcp;

// Connection handler class that manages a single client session
class connection_handler : public std::enable_shared_from_this<connection_handler>
{
public:
  explicit connection_handler(tcp::socket socket)
    : socket_(std::move(socket)),
      timeout_timer_(socket_.get_io_context()),
      work_strand_(socket_.get_io_context())
  {
  }

  void start()
  {
    auto self(shared_from_this());

    // First coroutine: handles data reading and echoing
    asio::spawn(work_strand_,
        [this, self](asio::yield_context yield)
        {
          try
          {
            char buffer[128];
            for (;;)
            {
              timeout_timer_.expires_from_now(std::chrono::seconds(10));
              std::size_t bytes_read = socket_.async_read_some(asio::buffer(buffer), yield);
              asio::async_write(socket_, asio::buffer(buffer, bytes_read), yield);
            }
          }
          catch (std::exception& e)
          {
            socket_.close();
            timeout_timer_.cancel();
          }
        });

    // Second coroutine: manages the timeout mechanism
    asio::spawn(work_strand_,
        [this, self](asio::yield_context yield)
        {
          while (socket_.is_open())
          {
            asio::error_code ec;
            timeout_timer_.async_wait(yield[ec]);
            if (timeout_timer_.expires_from_now() <= std::chrono::seconds(0))
              socket_.close();
          }
        });
  }

private:
  tcp::socket socket_;
  asio::steady_timer timeout_timer_;
  asio::io_context::strand work_strand_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: echo_server <port>\n";
      return 1;
    }

    asio::io_context io_context;

    asio::spawn(io_context,
        [&](asio::yield_context yield)
        {
          tcp::acceptor acceptor(io_context,
            tcp::endpoint(tcp::v4(), std::atoi(argv[1])));

          for (;;)
          {
            asio::error_code ec;
            tcp::socket client_socket(io_context);
            acceptor.async_accept(client_socket, yield[ec]);

            if (!ec) 
              std::make_shared<connection_handler>(std::move(client_socket))->start();
          }
        });

    io_context.run();
  }
  catch (std::exception& e)
  {
    std::cerr << "Error occurred: " << e.what() << "\n";
  }

  return 0;
}

#include <vector>
#include <set>
#include <algorithm>
#include <climits>

class Solution {
    std::multiset<long long> leftSet, rightSet;
public:
    long long minTotalCost(std::vector<int>& values, int kValue, int maxDistance) {
        int arraySize = values.size();
        kValue--;
        long long currentSum = values[0];

        // Initialize the first window
        for (int index = 1; index <= maxDistance + 1; index++) {
            currentSum += values[index];
            leftSet.insert(values[index]);
        }

        // Balance the sets to maintain k elements in leftSet
        while (leftSet.size() > static_cast<size_t>(kValue)) {
            currentSum -= *leftSet.rbegin();
            rightSet.insert(*leftSet.rbegin());
            leftSet.erase(leftSet.find(*leftSet.rbegin()));
        }

        long long minimumResult = currentSum;

        // Slide the window through the rest of the array
        for (int windowEnd = maxDistance + 2; windowEnd < arraySize; windowEnd++) {
            int removedElement = values[windowEnd - maxDistance - 1];

            // Remove the element going out of the window
            if (leftSet.find(removedElement) != leftSet.end()) {
                currentSum -= removedElement;
                leftSet.erase(leftSet.find(removedElement));
            } else {
                rightSet.erase(rightSet.find(removedElement));
            }

            // Add the new element coming into the window
            if (values[windowEnd] < *leftSet.rbegin()) {
                currentSum += values[windowEnd];
                leftSet.insert(values[windowEnd]);
            } else {
                rightSet.insert(values[windowEnd]);
            }

            // Rebalance leftSet to have exactly kValue elements
            while (leftSet.size() < static_cast<size_t>(kValue)) {
                currentSum += *rightSet.begin();
                leftSet.insert(*rightSet.begin());
                rightSet.erase(rightSet.find(*rightSet.begin()));
            }

            while (leftSet.size() > static_cast<size_t>(kValue)) {
                currentSum -= *leftSet.rbegin();
                rightSet.insert(*leftSet.rbegin());
                leftSet.erase(leftSet.find(*leftSet.rbegin()));
            }

            minimumResult = std::min(minimumResult, currentSum);
        }

        return minimumResult;
    }
};

