// Function to demonstrate nested table handling with sol::nested
void process_data(
     sol::nested<std::map<std::string, std::vector<std::string>>>
          data_source) {
    std::cout << "Processing nested map-vector structure" << std::endl;
    const auto& container = data_source.value();
    SOL_ASSERT(container.size() == 2);
    for (const auto& pair : container) {
        const std::vector<std::string>& items = pair.second;
        SOL_ASSERT(items.size() == 3);
