#include <iostream>
#include <vector>
#include <stack>
using namespace std;

// LeetCode 210: Course Schedule II (revised implementation)
// This function determines a valid order to complete all courses based on prerequisites
// We use DFS-based topological sorting with cycle detection
class Solution {
public:
    // Helper function to detect cycles in the directed graph
    bool hasCycle(int node, vector<bool>& visited, vector<bool>& inStack, const vector<vector<int>>& adjList) {
        visited[node] = true;
        inStack[node] = true;

        for (int i = 0; i < adjList.size(); i++) {
            int target = adjList[i][0];
            int source = adjList[i][1];

            if (source == node) {
                if (!visited[target]) {
                    if (hasCycle(target, visited, inStack, adjList)) {
                        return true;
                    }
                } else if (inStack[target]) {
                    return true;
                }
            }
        }

        inStack[node] = false;
        return false;
    }

    // Helper function to perform topological sort using DFS
    void topoSort(int node, vector<bool>& visited, stack<int>& order, const vector<vector<int>>& adjList) {
        visited[node] = true;

        for (int i = 0; i < adjList.size(); i++) {
            int neighbor = adjList[i][0];
            int fromNode = adjList[i][1];

            if (fromNode == node && !visited[neighbor]) {
                topoSort(neighbor, visited, order, adjList);
            }
        }

        order.push(node);
    }

    vector<int> findOrder(int totalCourses, vector<vector<int>>& prereqList) {
        vector<bool> visited(totalCourses, false);
        vector<bool> inStack(totalCourses, false);

        // First check for cycles
        for (int course = 0; course < totalCourses; course++) {
            if (!visited[course]) {
                if (hasCycle(course, visited, inStack, prereqList)) {
                    return {}; // Cycle found, impossible to finish all courses
                }
            }
        }

        // Reset visited array for topological sort
        visited.assign(totalCourses, false);
        stack<int> resultStack;
        vector<int> finalOrder;

        // Perform topological sort on each unvisited node
        for (int course = 0; course < totalCourses; course++) {
            if (!visited[course]) {
                topoSort(course, visited, resultStack, prereqList);
            }
        }

        // Build final order by popping from stack
        while (!resultStack.empty()) {
            finalOrder.push_back(resultStack.top());
            resultStack.pop();
        }

        return finalOrder;
    }
};

