#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    // Design a "Snake" layout on a 25x25 grid to form a winding corridor.
    // This layout forms a long path (close to Hamiltonian) through empty cells.
    // The path length is about 300 cells, enabling extended random walks.
    // Random movements (U/D/L/R) simulate a 1D random walk along this path.
    // Vertical moves in horizontal corridors are obstructed by walls,
    // halving the number of effective steps. With 60,000 total steps,
    // roughly 30,000 effective steps remain.
    // For such a walk, the expected spread (range) is around √30000 ≈ 173.
    // Since the path length (~300) exceeds the typical range (~173),
    // many simulations will not cover the entire path, leading to frequent
    // synchronization failures across test cases — maximizing failure rate.

    int rows = 25;
    int cols = 25;

    // Output dimensions
    cout << rows << " " << cols << endl;

    // Start with all walls
    vector<string> map(rows, string(cols, '0'));

    // Build snake-like corridor
    for (int r = 0; r < rows; ++r) {
        if (r % 2 == 0) {
            // Even-indexed rows: full horizontal passage
            for (int c = 0; c < cols; ++c) {
                map[r][c] = '1';
            }
        } else {
            // Odd-indexed rows: single connector cell to link adjacent rows
            // Alternating pattern: right side for r=1,5,9,...; left side for r=3,7,11,...
            if (r % 4 == 1) {
                map[r][cols - 1] = '1';
            } else {
                map[r][0] = '1';
            }
        }
    }

    // Display the constructed grid
    for (int i = 0; i < rows; ++i) {
        cout << map[i] << '\n';
    }

    return 0;
}

