#include <vector>
#include <algorithm>
#include <climits>

class Solution {
public:
    int minOperations(std::vector<int>& arr) {
        int size = arr.size();
        int ones = std::count(arr.begin(), arr.end(), 1); // Check for existing 1s

        if (ones > 0) {
            return size - ones; // If there's at least one 1, just convert rest
        }

        int minOps = INT_MAX; // Initialize with large value

        for (int start = 0; start < size; ++start) {
            int currentGcd = arr[start];
            for (int end = start + 1; end < size; ++end) {
                currentGcd = __gcd(currentGcd, arr[end]);

                if (currentGcd == 1) {
                    // Operations needed: (end - start) to create a 1 + (size - 1) to convert rest
                    minOps = std::min(minOps, (end - start) + (size - 1));
                    break;
                }
            }
        }

        return (minOps == INT_MAX) ? -1 : minOps;
    }
};

#include "cangjie/CHIR/StringWrapper.h"
using namespace Cangjie::CHIR;

// Constructor that initializes the string wrapper with initial content
StringWrapper::StringWrapper(const std::string& initVal) : storedString(initVal)
{
}

// Returns the underlying string value as a const reference
const std::string& StringWrapper::Str() const
{
    return storedString;
}

// Appends a new string directly to the current content
void StringWrapper::Append(const std::string& newContent)
{
    storedString = storedString + newContent;
}

// Appends a new string with a delimiter in between if both strings are non-empty
void StringWrapper::Append(const std::string& newContent, const std::string& separator)
{
    if (!newContent.empty() && !storedString.empty()) {
        storedString = storedString + separator + " " + newContent;
    }
}

// Removes the last 'count' characters from the stored string
void StringWrapper::RemoveLastNChars(const size_t count)
{
    for (size_t index = 0; index < count; ++index) {
        storedString.pop_back();
    }
}

// Adds a delimiter only if the current string is not empty; returns reference to self
StringWrapper& StringWrapper::AddDelimiterOrNot(const std::string& separator)
{
    if (!storedString.empty()) {
        storedString = storedString + separator;
    }
    return *this;
}

// If the new content is empty, clears the stored string; otherwise appends the content
StringWrapper& StringWrapper::AppendOrClear(const std::string& newContent)
{
    if (newContent.empty()) {
        storedString.clear();
    } else {
        storedString = storedString + newContent;
    }
    return *this;
}

