class Solution {
public:
    // Find the missing number in the range [0, n] where n is the size of the array
    int missingNumber(std::vector<int>& numbers) {
        int length = numbers.size();
        std::sort(numbers.begin(), numbers.end());
        for (int index = 0; index < length; ++index) {
            if (numbers[index] != index) {
                return index;
            }
        }
        return length;
    }
};

#include <iostream>
#include <vector>
#include <algorithm>
#include <sstream>

// Current array representation
std::vector<int> arr;
// Position tracking: pos[value] = 1-based index of that value
std::vector<int> posMap;
// Store all reversal operations
std::vector<std::pair<int, int>> operations;

void perform_reverse(int left, int right) {
    if (left > right) std::swap(left, right);
    operations.push_back({left, right});

    // Convert to 0-based indices for internal array manipulation
    std::reverse(arr.begin() + left - 1, arr.begin() + right);

    // Update position map for affected elements
    for (int idx = left; idx <= right; ++idx) {
        posMap[arr[idx - 1]] = idx;
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int size;
    std::cin >> size;

    arr.resize(size);
    posMap.resize(size + 1);

    // Read initial array and build position map
    for (int i = 0; i < size; ++i) {
        std::cin >> arr[i];
        posMap[arr[i]] = i + 1;
    }

    // Select pivot value x = 5 (alternative choice for reversals)
    int x = 5;

    // Sort by placing elements from largest to smallest
    for (int target = size; target >= 1; --target) {
        int currentPos = posMap[target];

        while (currentPos < target) {
            // Move element towards its correct position using reversals
            if (currentPos + 4 <= target) {
                // Use length-5 reversal to move element forward by 4 positions
                perform_reverse(currentPos, currentPos + 4);
            } else {
                // Use length-2 reversal to move element forward by 1 position
                perform_reverse(currentPos, currentPos + 1);
            }

            currentPos = posMap[target]; // Refresh position after reversal
        }
    }

    // Output results
    std::cout << x << "\n";
    std::cout << operations.size() << "\n";
    for (const auto& operation : operations) {
        std::cout << operation.first << " " << operation.second << "\n";
    }

    return 0;
}

