using namespace std;

// Buffer to hold the reconstructed array. Size supports maximum N (2*10^5)
int resultArray[200005];

/**
 * Recursive function to reconstruct the sequence in range [start, end].
 * Employs a divide-and-conquer strategy akin to constructing a segment tree.
 * Queries the current interval to determine the dominant value and its count.
 * If the interval is uniform (all elements identical), populate it and terminate.
 * Otherwise, partition into left and right sub-intervals for further processing.
 */
void reconstruct(int start, int end) {
    if (start > end) return;

    // Issue query: "? start end"
    cout << "? " << start << " " << end << endl;

    // Read response: "value frequency"
    long long dominantValueLong;
    int occurrenceCount;

    // Input validation for robustness
    if (!(cin >> dominantValueLong >> occurrenceCount)) {
        exit(0);
    }

    // -1 signals an invalid query or system error
    if (dominantValueLong == -1) {
        exit(0);
    }

    int dominantValue = static_cast<int>(dominantValueLong);

    // If the frequency matches the interval length, all elements are identical
    if (occurrenceCount == (end - start + 1)) {
        for (int index = start; index <= end; ++index) {
            resultArray[index] = dominantValue;
        }
        return;
    }

    // Conquer step: split the interval into two halves
    int midpoint = (start + end) / 2;
    reconstruct(start, midpoint);
    reconstruct(midpoint + 1, end);
}

int main() {
    // Optimize I/O performance for interactive problems
    // 'endl' ensures immediate output flushing, which is essential for interactive tasks
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int arraySize;

    // Read the size of the array
    if (cin >> arraySize) {
        // Initiate recursive reconstruction over the full range [1, arraySize]
        reconstruct(1, arraySize);

        // Output the final reconstructed sequence
        cout << "! ";
        for (int i = 1; i <= arraySize; ++i) {
            cout << resultArray[i];
            if (i != arraySize) {
                cout << " ";
            }
        }
        cout << endl;
    }

    return 0;
}

