    FSOAPositions RHSVector(InternalVertexCount);
    if (InternalVertexCount != VertexCount) // have boundary points
    {
        for (int32 component = 0; component < 3; ++component)
        {
            RHSVector.Array(component) = BoundaryOperator * BoundaryPositions.Array(component);
        }
