    MPI_Init(NULL, NULL);

    int my_rank;
    MPI_Comm_rank(MPI_COMM_WORLD, &my_rank);

    int num_processes;
    MPI_Comm_size(MPI_COMM_WORLD, &num_processes);

    // Root process creates the full dataset
    float* full_dataset = NULL;
    if (my_rank == 0) {
        full_dataset = generate_random_values(elements_per_process * num_processes);
    }

    // Allocate local buffer for scattered data
    float* local_data = (float*) malloc(sizeof(float) * elements_per_process);
    assert(local_data != NULL);

    // Distribute data across processes
    MPI_Scatter(full_dataset, elements_per_process, MPI_FLOAT,
                local_data, elements_per_process, MPI_FLOAT, 0, MPI_COMM_WORLD);

    // Compute local average
    float local_avg = calculate_mean(local_data, elements_per_process);

    // Gather all local averages to root
    float* local_averages = NULL;
    if (my_rank == 0) {
        local_averages = (float*) malloc(sizeof(float) * num_processes);
        assert(local_averages != NULL);
    }

    MPI_Gather(&local_avg, 1, MPI_FLOAT,
               local_averages, 1, MPI_FLOAT, 0, MPI_COMM_WORLD);

    // Final computation on root process
    if (my_rank == 0) {
        float overall_avg = calculate_mean(local_averages, num_processes);
        printf("Overall average is %f\n", overall_avg);

        // Verify against original dataset
        float reference_avg =
            calculate_mean(full_dataset, elements_per_process * num_processes);
        printf("Reference average from full data is %f\n", reference_avg);

        free(full_dataset);
        free(local_averages);
    }

    free(local_data);
    MPI_Barrier(MPI_COMM_WORLD);
    MPI_Finalize();
}

