// Evaluate bitvector literal representations
void evaluate_bitvector_literals(SMTParser::ParserPtr& parser) {
    std::vector<std::string> inputs = {
        "#b1010",                     // 4-bit binary
        "#x1A",                       // hexadecimal (26 in decimal)
