    SMTParser::ParserPtr parser = SMTParser::newParser();

    evaluate_bitvector_literals(parser);
    test_bv_bitwise_operations(parser);
    test_bv_arithmetic_functions(parser);
    test_bv_comparison_predicates(parser);

