#include <iostream>
using namespace std;

int main() {
    int dist; // current distance to the exit
    cin >> dist;

    while (dist > 0) {
        for (int color = 0; color < 3; ++color) {
            // attempt traversal using color 'color'
            cout << "move " << color << endl;
            int response;
            cin >> response;

            if (response == 1) {
                // destination reached
                return 0;
            }

            // ask for updated distance
            cout << "query" << endl;
            int updated_dist;
            cin >> updated_dist;

            if (updated_dist == dist - 1) {
                // successful move toward exit
                dist = updated_dist;
                break;
            } else {
                // moved away from exit, backtrack
                cout << "move " << color << endl;
                cin >> response;

                if (response == 1) {
                    // exit found during backtracking
                    return 0;
                }
                // proceed with next color option
            }
        }
    }
    return 0;
}

