using namespace std;

// Leetcode 1352: Product of Last K Numbers (revised implementation)
class ProductOfNumbers {
private:
    vector<int> prefixProducts;  // Stores cumulative products
public:
    ProductOfNumbers() {
        prefixProducts.push_back(1);  // Initialize with identity element for multiplication
    }

    void add(int value) {
        if (value == 0) {
            prefixProducts.clear();
            prefixProducts.push_back(1);  // Reset after zero to handle division correctly
        } else {
            prefixProducts.push_back(prefixProducts.back() * value);
        }
    }

    int getProduct(int count) {
        if (count >= prefixProducts.size()) return 0;
        return prefixProducts.back() / prefixProducts[prefixProducts.size() - count - 1];
    }
};
// Time Complexity:
// - add: O(1)
// - getProduct: O(1) (constant time division operation)
// Space Complexity: O(n) where n is the total number of elements added (space used by the prefixProducts vector)
// Note: The prefixProducts array maintains running products, enabling efficient constant-time product queries

#include <Application.h>
#include <File.h>
#include <TranslatorRoster.h>
#include <iostream>
#include <cstring>

class RTFToTextConverter : public BApplication
{
public:
	RTFToTextConverter(int argc, char** argv)
		:
		BApplication("application/x-vnd.demo-rftconverter"),
		fArgc(argc),
		fArgv(argv)
	{
	}

	void ReadyToRun() override
	{
		if (fArgc < 2) {
			std::cout << "Usage: " << fArgv[0] << " <rtf_input_file>" << std::endl;
			PostMessage(B_QUIT_REQUESTED);
			return;
		}

		const char* sourceFile = fArgv[1];

		// Open the source RTF file for reading
		BFile input(sourceFile, B_READ_ONLY);
		if (input.InitCheck() != B_OK) {
			std::cout << "Error: Unable to open input file " << sourceFile << std::endl;
			PostMessage(B_QUIT_REQUESTED);
			return;
		}

		// Prepare output file for plain text
		BFile output("converted_output.txt",
			B_CREATE_FILE | B_ERASE_FILE | B_WRITE_ONLY);

		// Access default translator roster
		BTranslatorRoster* manager = BTranslatorRoster::Default();
		if (!manager) {
			std::cout << "Error: Could not retrieve translator manager" << std::endl;
			PostMessage(B_QUIT_REQUESTED);
			return;
		}

		// Perform translation from RTF to TEXT format
		status_t result = manager->Translate(&input, nullptr, nullptr, &output, 'TEXT');
		if (result != B_OK) {
			std::cout << "Translation failed: " << strerror(result) << std::endl;
		} else {
			std::cout << "Success: RTF converted to plain text as 'converted_output.txt'" << std::endl;
		}

		PostMessage(B_QUIT_REQUESTED); // Terminate application
	}

private:
	int fArgc;
	char** fArgv;
};

int main(int argc, char** argv)
{
	RTFToTextConverter app(argc, argv);
	app.Run();
	return 0;
}

