// Function to append translated strings to a .pot file
bool export_to_pot(boost::filesystem::path filepath, const std::vector<std::pair<std::string, std::string>>& entries)
{
    boost::nowide::ofstream output_file(filepath.string(), std::ios_base::app);
    for (const auto& item : entries)
    {
        // Format: #: resources/data/hints.ini: [hint:section_name]
        // msgid "original_text"
        // msgstr ""
        output_file << "\n#: resources/data/hints.ini: [" << item.first << "]\nmsgid \"" << item.second << "\"\nmsgstr \"\"\n";
    }
    output_file.close();
    return true;
}

// Function to parse hints.ini and extract hint entries
bool load_hints_from_ini(boost::filesystem::path filepath, std::vector<std::pair<std::string, std::string>>& output_list)
{
    namespace pt = boost::property_tree;
    pt::ptree root;
    boost::nowide::ifstream input_stream(filepath.string());

    try {
        pt::read_ini(input_stream, root);
    }
    catch (const boost::property_tree::ini_parser::ini_parser_error& error) {
        std::cerr << error.what() << std::endl;
        return false;
    }

    for (const auto& section : root) {
        if (boost::starts_with(section.first, "hint:")) {
            for (const auto& property : section.second) {
                if (property.first == "text") {
                    output_list.emplace_back(section.first, property.second.data());
                    break;
                }
            }
        }
    }
    return true;
}

int main(int argc, char* argv[])
{
    std::vector<std::pair<std::string, std::string>> extracted_strings;
    boost::filesystem::path ini_path;
    boost::filesystem::path pot_path;

    if (argc != 3) {
        std::cout << "HINTS_TO_POT FAILED: WRONG NUMBER OF ARGUMENTS" << std::endl;
        return -1;
    }

    try {
        ini_path = boost::filesystem::canonical(boost::filesystem::path(argv[1])).parent_path() / "resources" / "data" / "hints.ini";
        pot_path = boost::filesystem::canonical(boost::filesystem::path(argv[2])).parent_path() / "localization" / "preFlight.pot";
    } catch (std::exception&) {
        std::cout << "HINTS_TO_POT FAILED: BOOST CANONICAL ERROR" << std::endl;
        return -1;
    }

    if (!boost::filesystem::exists(ini_path)) {
        std::cout << "HINTS_TO_POT FAILED: INI FILE PATH DOES NOT EXIST" << std::endl;
        std::cout << ini_path.string() << std::endl;
        return -1;
    }

    if (!load_hints_from_ini(std::move(ini_path), extracted_strings)) {
        std::cout << "HINTS_TO_POT FAILED TO PARSE HINTS INI FILE" << std::endl;
        return -1;
    }

    if (!export_to_pot(std::move(pot_path), extracted_strings)) {
        std::cout << "HINTS_TO_POT FAILED TO WRITE POT FILE" << std::endl;
        return -1;
    }

    std::cout << "HINTS_TO_POT SUCCESS" << std::endl;
    return 0;
}

