#include <iostream>
#include "sophus/geometry.hpp"

int main() {
  // Compute the combined rotation from three individual rotations
  const double PI_VAL = Sophus::Constants<double>::pi();
  Sophus::SO3d rotXAxis = Sophus::SO3d::rotX(PI_VAL / 4.0);
  Sophus::SO3d rotYAxis = Sophus::SO3d::rotY(PI_VAL / 6.0);
  Sophus::SO3d rotZAxis = Sophus::SO3d::rotZ(-PI_VAL / 3.0);

  std::cout << "Individual rotation matrices:" << std::endl;
  std::cout << "R_x:\n" << rotXAxis.matrix() << std::endl;
  std::cout << "R_y:\n" << rotYAxis.matrix() << std::endl;
  std::cout << "R_z:\n" << rotZAxis.matrix() << std::endl;
  std::cout << "Combined rotation R_x * R_y * R_z:\n"
            << (rotXAxis * rotYAxis * rotZAxis).matrix() << std::endl;
  std::cout << std::endl;

  // Apply rotations to a test vector
  Eigen::Vector3d testVec;
  testVec << 1.0, 0.0, 0.0;
  std::cout << "Action of rotation matrices on vectors:" << std::endl;
  std::cout << "Original vector:\n" << testVec << std::endl;
  std::cout << "R_y * testVec:\n" << rotYAxis * testVec << std::endl;
  std::cout << "R_x * (R_y * testVec):\n" << rotXAxis * (rotYAxis * testVec) << std::endl;
  std::cout << "(R_x * R_y) * testVec:\n" << (rotXAxis * rotYAxis) * testVec << std::endl;
  std::cout << std::endl;

  // Display internal representation as unit quaternion
  std::cout << "Rotation matrix form of R_x:\n" << rotXAxis.matrix() << std::endl;
  std::cout << "Unit quaternion representation of R_x:\n"
            << rotXAxis.unit_quaternion().coeffs() << std::endl;
  // Note: Eigen uses (i, j, k, r) ordering for quaternion coefficients
  std::cout << std::endl;

  return 0;
}

