#include <Application.h>
#include <Entry.h>
#include <Directory.h>
#include <FindDirectory.h>
#include <Path.h>
#include <Volume.h>
#include <Query.h>
#include <stdio.h>
#include <string.h>

class CommentFileSearcher : public BApplication
{
public:
    CommentFileSearcher()
        : BApplication("application/x-vnd.kitlab-commentfilesearcher")
    {
        ExecuteSearch();
        PostMessage(B_QUIT_REQUESTED);
    }

private:
    void ExecuteSearch()
    {
        // --- Locate the user's home directory ---
        BPath userHomePath;
        if (find_directory(B_USER_DIRECTORY, &userHomePath) != B_OK) {
            printf("Error: Could not locate home directory.\n");
            return;
        }

        BDirectory userDir(userHomePath.Path());
        BVolume vol;
        if (userDir.GetVolume(&vol) != B_OK) {
            printf("Error: Unable to retrieve volume for home directory.\n");
            return;
        }

        // --- Output search metadata ---
        printf("Scanning location: %s\n", userHomePath.Path());
        printf("Targeting files with a 'Comment' metadata field.\n\n");

        const char* targetMimeType = "text/plain";

        // --- Build and configure the query ---
        BQuery searchQuery;
        searchQuery.SetVolume(&vol);

        // Condition 1: MIME type must be text/plain
        searchQuery.PushAttr("BEOS:TYPE");
        searchQuery.PushString(targetMimeType);
        searchQuery.PushOp(B_EQ);

        // Condition 2: Must have non-empty Comment attribute
        searchQuery.PushAttr("Comment");
        searchQuery.PushString("*");
        searchQuery.PushOp(B_EQ);

        // Combine both conditions with AND logic
        searchQuery.PushOp(B_AND);

        // Execute the query
        if (searchQuery.Fetch() != B_OK) {
            printf("Error: Query execution failed.\n");
            return;
        }

        // --- Process matching entries ---
        entry_ref fileRef;
        int32 matchCount = 0;
        while (searchQuery.GetNextRef(&fileRef) == B_OK) {
            BEntry fileEntry(&fileRef);
            BPath filePath(&fileEntry);

            // Ensure the file resides within the user's home directory
            if (strncmp(filePath.Path(), userHomePath.Path(), strlen(userHomePath.Path())) == 0) {
                printf("Match: %s\n", filePath.Path());
                matchCount++;
            }
        }

        // --- Report no matches found ---
        if (matchCount == 0)
            printf("No files containing the 'Comment' attribute were found.\n");
    }
};

int main()
{
    CommentFileSearcher app;
    app.Run();
    return 0;
}

#include "Abilities/Tasks/AbilityTask_NetworkSyncPoint.h"
#include "AbilitySystemComponent.h"

UAbilityTask_NetworkSyncPoint::UAbilityTask_NetworkSyncPoint(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer)
{
	// Initialize with no event to listen for by default
	ReplicatedEventToListenFor = EAbilityGenericReplicatedEvent::MAX;
}

void UAbilityTask_NetworkSyncPoint::OnSignalCallback()
{
	if (AbilitySystemComponent.IsValid())
	{
		// Consume the replicated event that triggered this callback
		AbilitySystemComponent->ConsumeGenericReplicatedEvent(
			ReplicatedEventToListenFor, 
			GetAbilitySpecHandle(), 
			GetActivationPredictionKey()
		);
	}
	// Signal that synchronization is complete
	SyncFinished();
}

UAbilityTask_NetworkSyncPoint* UAbilityTask_NetworkSyncPoint::WaitNetSync(
	class UGameplayAbility* OwningAbility, 
	EAbilityTaskNetSyncType InSyncType)
{
	UAbilityTask_NetworkSyncPoint* TaskInstance = NewAbilityTask<UAbilityTask_NetworkSyncPoint>(OwningAbility);
	TaskInstance->SyncType = InSyncType;
	return TaskInstance;
}

void UAbilityTask_NetworkSyncPoint::Activate()
{
	FScopedPredictionWindow ScopedScope(AbilitySystemComponent, IsPredictingClient());

	if (!AbilitySystemComponent.IsValid())
	{
		return;
	}

	if (IsPredictingClient())
	{
		// Client-side logic
		if (SyncType != EAbilityTaskNetSyncType::OnlyServerWait)
		{
			// Listen for server signal if we're not exclusively server-waiting
			ReplicatedEventToListenFor = EAbilityGenericReplicatedEvent::GenericSignalFromServer;
		}

		if (SyncType != EAbilityTaskNetSyncType::OnlyClientWait)
		{
			// Notify server of our signal if client isn't the only one waiting
			AbilitySystemComponent->ServerSetReplicatedEvent(
				EAbilityGenericReplicatedEvent::GenericSignalFromClient,
				GetAbilitySpecHandle(),
				GetActivationPredictionKey(),
				AbilitySystemComponent->ScopedPredictionKey
			);
		}
	}
	else if (IsForRemoteClient())
	{
		// Server-side logic for remote client
		if (SyncType != EAbilityTaskNetSyncType::OnlyClientWait)
		{
			// Listen for client signal if not exclusively client-waiting
			ReplicatedEventToListenFor = EAbilityGenericReplicatedEvent::GenericSignalFromClient;
		}

		if (SyncType != EAbilityTaskNetSyncType::OnlyServerWait)
		{
			// Notify client of our signal if server isn't the only one waiting
			AbilitySystemComponent->ClientSetReplicatedEvent(
				EAbilityGenericReplicatedEvent::GenericSignalFromServer,
				GetAbilitySpecHandle(),
				GetActivationPredictionKey()
			);
		}
	}

	// If we have an event to wait for, register the callback; otherwise finish immediately
	if (ReplicatedEventToListenFor != EAbilityGenericReplicatedEvent::MAX)
	{
		CallOrAddReplicatedDelegate(
			ReplicatedEventToListenFor,
			FSimpleMulticastDelegate::FDelegate::CreateUObject(this, &UAbilityTask_NetworkSyncPoint::OnSignalCallback)
		);
	}
	else
	{
		// No replication needed — sync completed instantly
		SyncFinished();
	}
}

void UAbilityTask_NetworkSyncPoint::SyncFinished()
{
	if (!IsPendingKill())
	{
		if (ShouldBroadcastAbilityTaskDelegates())
		{
			OnSync.Broadcast();
		}
		EndTask();
	}
}

