static MCInstrInfo *allocateNVPTXMCInstrInfo() {
  MCInstrInfo *info = new MCInstrInfo();
  InitNVPTXMCInstrInfo(info);
  return info;
}

static MCRegisterInfo *allocateNVPTXMCRegisterInfo(const Triple &targetTriple) {
  MCRegisterInfo *regInfo = new MCRegisterInfo();
  // PTX lacks a dedicated return address register.
  InitNVPTXMCRegisterInfo(regInfo, 0);
  return regInfo;
}

static MCSubtargetInfo *
allocateNVPTXMCSubtargetInfo(const Triple &targetTriple, StringRef cpuName,
                             StringRef featureString) {
  return createNVPTXMCSubtargetInfoImpl(targetTriple, cpuName,
                                        /*TuneCPU*/ cpuName, featureString);
}

static MCInstPrinter *createNVPTXInstructionPrinter(const Triple &triple,
                                                    unsigned syntaxVariant,
                                                    const MCAsmInfo &asmInfo,
                                                    const MCInstrInfo &instrInfo,
                                                    const MCRegisterInfo &regInfo) {
  if (syntaxVariant == 0)
    return new NVPTXInstPrinter(asmInfo, instrInfo, regInfo);
  return nullptr;
}

static MCTargetStreamer *createAsmTargetStreamer(MCStreamer &stream,
                                                 formatted_raw_ostream &,
                                                 MCInstPrinter *, bool) {
  return new NVPTXAsmTargetStreamer(stream);
}

static MCTargetStreamer *createEmptyTargetStreamer(MCStreamer &stream) {
  return new NVPTXTargetStreamer(stream);
}

// Ensure static initialization occurs.
extern "C" LLVM_EXTERNAL_VISIBILITY void LLVMInitializeNVPTXTargetMC() {
  for (Target *target : {&getTheNVPTXTarget32(), &getTheNVPTXTarget64()}) {
    // Register the assembly information.
    RegisterMCAsmInfo<NVPTXMCAsmInfo> infoReg(*target);
    // Register the instruction information.
    TargetRegistry::RegisterMCInstrInfo(*target, allocateNVPTXMCInstrInfo);
    // Register the register information.
    TargetRegistry::RegisterMCRegInfo(*target, allocateNVPTXMCRegisterInfo);
    // Register the subtarget information.
    TargetRegistry::RegisterMCSubtargetInfo(*target, allocateNVPTXMCSubtargetInfo);
    // Register the instruction printer.
    TargetRegistry::RegisterMCInstPrinter(*target, createNVPTXInstructionPrinter);
    // Register the assembly target streamer.
    TargetRegistry::RegisterAsmTargetStreamer(*target, createAsmTargetStreamer);
    // Register the null target streamer.
    TargetRegistry::RegisterNullTargetStreamer(*target, createEmptyTargetStreamer);
  }
}

