#include <vector>
#include <unordered_map>
#include <queue>

class Solution {
public:
    std::vector<int> findXSum(std::vector<int>& elements, int windowSize, int topCount) 
    {
        int n = elements.size();
        std::vector<int> result;
        std::unordered_map<int, int> countMap;

        // Build frequency map for the initial window
        for (int idx = 0; idx < windowSize; idx++) {
            countMap[elements[idx]]++;
        }

        // Compute x-sum for the first window
        result.push_back(computeTopSum(countMap, topCount));

        // Slide the window across the array
        for (int start = 1; start <= n - windowSize; start++) {
            // Remove element exiting the window
            countMap[elements[start - 1]]--;
            if (countMap[elements[start - 1]] == 0) {
                countMap.erase(elements[start - 1]);
            }

            // Add new element entering the window
            countMap[elements[start + windowSize - 1]]++;

            // Compute x-sum for current window
            result.push_back(computeTopSum(countMap, topCount));
        }

        return result;
    }

private:
    int computeTopSum(const std::unordered_map<int, int>& countMap, int topCount) {
        // Max heap to retrieve elements with highest frequencies
        std::priority_queue<std::pair<int, int>> maxHeap; // (frequency, value)

        for (const auto& item : countMap) {
            maxHeap.push({item.second, item.first});
        }

        int total = 0;
        for (int i = 0; i < topCount && !maxHeap.empty(); i++) {
            auto current = maxHeap.top();
            maxHeap.pop();
            total += current.first * current.second; // contribution = frequency * value
        }

        return total;
    }
};

