#include "src/QuantumRegister.hpp"
#include <cassert>
#include <cmath>
#include <iostream>
#include <mpi.h>
#include <vector>

using qubit_engine::QuantumRegister;

// Helper function to compare complex numbers with tolerance
bool is_similar(std::complex<double> val1, std::complex<double> val2,
                double epsilon = 1e-5) {
  return std::abs(val1 - val2) < epsilon;
}

int main(int argc, char **args) {
  MPI_Init(&argc, &args);

  int my_rank;
  MPI_Comm_rank(MPI_COMM_WORLD, &my_rank);

  int total_ranks;
  MPI_Comm_size(MPI_COMM_WORLD, &total_ranks);

  if (total_ranks != 2) {
    if (my_rank == 0) {
      std::cerr << "Error: This test requires exactly 2 MPI processes."
                << std::endl;
    }
    MPI_Finalize();
    return 1;
  }

  // Setup: 4-qubit system, each rank holds half the amplitudes (8 each)
  size_t num_qb = 4;
  QuantumRegister local_reg(num_qb);

  // Initialize in |0000⟩ state: amplitude 1.0 at index 0 on rank 0, rest zero
  // After Hadamard on qubit 3:
  //   |0000⟩ → (|0000⟩ + |1000⟩)/√2
  // Rank 0 holds global indices 0–7 (MSB=0), so index 0 gets 1/√2
  // Rank 1 holds global indices 8–15 (MSB=1), so local index 0 corresponds to global 8 (|1000⟩)

  if (my_rank == 0)
    std::cout << "Executing H on qubit 3..." << std::endl;

  local_reg.applyHadamard(3);
  auto amplitudes = local_reg.getStateVector();
  double one_over_root2 = 1.0 / std::sqrt(2.0);

  if (my_rank == 0) {
    assert(is_similar(amplitudes[0], one_over_root2));
  } else {
    assert(is_similar(amplitudes[0], one_over_root2)); // Global index 8 = |1000⟩
  }

  // Apply CNOT with control = qubit 3 (global), target = qubit 0 (local)
  // |1000⟩ → |1001⟩, so rank 1's local index 0 (|1000⟩) → index 1 (|1001⟩)
  // |0000⟩ remains unchanged since control bit is 0

  if (my_rank == 0)
    std::cout << "Executing CNOT(3, 0)..." << std::endl;

  local_reg.applyCNOT(3, 0);
  amplitudes = local_reg.getStateVector();

  if (my_rank == 0) {
    // Still |0000⟩ on rank 0
    if (is_similar(amplitudes[0], one_over_root2)) {
      std::cout << "[Rank 0] |0000⟩ confirmed." << std::endl;
    } else {
      std::cerr << "[Rank 0] FAILED: amplitude mismatch for |0000⟩." << std::endl;
      MPI_Finalize();
      return 1;
    }
  } else {
    // Rank 1: |1000⟩ moved to |1001⟩
    if (is_similar(amplitudes[0], 0.0) && is_similar(amplitudes[1], one_over_root2)) {
      std::cout << "[Rank 1] |1001⟩ confirmed." << std::endl;
    } else {
      std::cerr << "[Rank 1] FAILED: amplitude mismatch for |1001⟩." << std::endl;
      MPI_Finalize();
      return 1;
    }
  }

  MPI_Finalize();
  return 0;
}

