namespace g2o {

#ifdef _WINDOWS
#if defined(_MSC_VER) || defined(_MSC_EXTENSIONS)
  #define EPOCH_DIFFERENCE_MICROSECS  11644473600000000Ui64
#else
  #define EPOCH_DIFFERENCE_MICROSECS  11644473600000000ULL
#endif

struct timezone_ex {
  int  tz_minuteswest; /* minutes W of Greenwich */
  int  tz_dsttime;     /* type of dst correction */
};

int gettimeofday(struct timeval *tv, struct timezone_ex *tz)
{
  FILETIME systemTime;
  unsigned long long timeInMicroseconds = 0;
  static int initialized = 0;

  if (NULL != tv)
  {
    GetSystemTimeAsFileTime(&systemTime);

    timeInMicroseconds |= (unsigned long long)systemTime.dwHighDateTime << 32;
    timeInMicroseconds |= systemTime.dwLowDateTime;
    timeInMicroseconds /= 10; // Convert from 100ns to microseconds
    timeInMicroseconds -= EPOCH_DIFFERENCE_MICROSECS;

    tv->tv_sec = static_cast<long>(timeInMicroseconds / 1000000UL);
    tv->tv_usec = static_cast<long>(timeInMicroseconds % 1000000UL);
  }

  if (NULL != tz) {
    if (!initialized) {
      _tzset();
      initialized++;
    }
    long secondsOffset;
    int daylightFlag;
    _get_timezone(&secondsOffset);
    _get_daylight(&daylightFlag);

    tz->tz_minuteswest = secondsOffset / 60;
    tz->tz_dsttime = daylightFlag;
  }

  return 0;
}
#endif

ScopeTime::ScopeTime(const char* label) : _label(label), _startTimestamp(get_monotonic_time()) {}

ScopeTime::~ScopeTime() {
  std::cerr << _label << " took " << 1000 * (get_monotonic_time() - _startTimestamp) << "ms.\n";
}

double get_monotonic_time()
{
#if (defined(_POSIX_TIMERS) && (_POSIX_TIMERS+0 >= 0) && defined(_POSIX_MONOTONIC_CLOCK))
  struct timespec tp;
  clock_gettime(CLOCK_MONOTONIC, &tp);
  return tp.tv_sec + tp.tv_nsec * 1e-9;
#else
  return get_time();
#endif
}

