// Trigger assertion notifications to registered listeners
void Logger::Assertion()
{
    msMutex.lock();
    for (auto observer : msListeners)
    {
        if (observer->GetFlags() & Listener::OBSERVE_ASSERTION)
        {
            observer->Assertion(mMessage);
        }
    }
    msMutex.unlock();
}

// Trigger error notifications to registered listeners
void Logger::Error()
{
    msMutex.lock();
    for (auto observer : msListeners)
    {
        if (observer->GetFlags() & Listener::OBSERVE_ERROR)
        {
            observer->Error(mMessage);
        }
    }
    msMutex.unlock();
}

// Trigger warning notifications to registered listeners
void Logger::Warning()
{
    msMutex.lock();
    for (auto observer : msListeners)
    {
        if (observer->GetFlags() & Listener::OBSERVE_WARNING)
        {
            observer->Warning(mMessage);
        }
    }
    msMutex.unlock();
}

// Trigger information notifications to registered listeners
void Logger::Information()
{
    msMutex.lock();
    for (auto observer : msListeners)
    {
        if (observer->GetFlags() & Listener::OBSERVE_INFORMATION)
        {
            observer->Information(mMessage);
        }
    }
    msMutex.unlock();
}

// Add a new listener to the logger's subscription list
void Logger::Subscribe(Listener* listener)
{
    msMutex.lock();
    msListeners.insert(listener);
    msMutex.unlock();
}

// Remove a listener from the logger's subscription list
void Logger::Unsubscribe(Listener* listener)
{
    msMutex.lock();
    msListeners.erase(listener);
    msMutex.unlock();
}

