void perform_interaction(int num_states, const std::vector<int>& trans0, const std::vector<int>& trans1) {
    std::cout << 1 << std::endl;
    std::cout << num_states << std::endl;

    for (int idx = 0; idx < num_states; ++idx) {
        std::cout << trans0[idx];
        if (idx != num_states - 1) {
            std::cout << " ";
        }
    }
    std::cout << std::endl;

    for (int idx = 0; idx < num_states; ++idx) {
        std::cout << trans1[idx];
        if (idx != num_states - 1) {
            std::cout << " ";
        }
    }
    std::cout << std::endl;
    std::cout.flush();
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int length;
    std::cin >> length;
    std::string target_string(length, '0');

    for (int position = 0; position < length; ++position) {
        // To determine the character at position 'position', we construct an automaton
        // with (position + 2) states to encode the decision process.
        int state_count = position + 2;

        std::vector<int> zero_trans(state_count);
        std::vector<int> one_trans(state_count);

        // For positions before 'position', transitions follow a linear chain:
        // state i -> state (i+1) regardless of input bit
        for (int state = 0; state < position; ++state) {
            zero_trans[state] = state + 1;
            one_trans[state] = state + 1;
        }

        // At the decision state 'position', transitions depend on the input bit
        zero_trans[position] = position;       // '0' keeps us in the decision state
        one_trans[position] = position + 1;   // '1' moves to the accepting state

        // The sink states (position and position+1) remain fixed once entered
        if (position + 1 < state_count) {
            zero_trans[position + 1] = position + 1;
            one_trans[position + 1] = position + 1;
        }

        perform_interaction(state_count, zero_trans, one_trans);

        int response;
        std::cin >> response;
        if (response == position) {
            target_string[position] = '0';
        } else {
            target_string[position] = '1';
        }
    }

    std::cout << 0 << std::endl;
    std::cout << target_string << std::endl;
    std::cout.flush();

    return 0;
}

