Protocol::Protocol()
{
}

Error Protocol::init()
{
    // Initialize pending commands array
    for (uint8_t idx = 0; idx < PROTOCOL_MAX_PENDING_COMMANDS; ++idx) {
        pending_commands[idx].id = 0;
        pending_commands[idx].callback = nullptr;
    }
    return Error::None;
}

Error Protocol::deinit()
{
    return Error::None;
}

Error Protocol::handleRequest(const Request& req, HandleResponseCallback callback)
{
    if (!callback)
    {
        Log::Add(Log::Level::Error, TAG, "Invalid callback provided for request ID %d", req.id);
        return Error::InvalidParameters;
    }

    // Locate an available slot in the pending commands array
    bool slot_found = false;
    for (uint8_t index = 0; index < PROTOCOL_MAX_PENDING_COMMANDS; ++index) {
        if (pending_commands[index].callback == nullptr) {
            pending_commands[index].id = req.id;
            pending_commands[index].callback = callback;
            slot_found = true;
            break;
        }
    }

    if (!slot_found) // No empty slot found
    {
        Log::Add(Log::Level::Error, TAG, "No free slot available for pending command ID %d", req.id);
        return Error::NoMemory;
    }

    // Find the appropriate handler for the command
    // TODO : Instead of iterating through all handlers, use an array indexed by command ID (only 255 possible commands)
    CommandHandler* handler_ptr = nullptr;
    for (auto& h : handlers)
    {
        if (h.cmd == req.cmd)
        {
            handler_ptr = &h;
            break;
        }
    }

    if (handler_ptr == nullptr) // No handler found for this command
    {
        Log::Add(Log::Level::Error, TAG, "No handler found for command 0x%02X", req.cmd);
        return Error::NotFound;
    }

    // Verify that the payload length matches the expected value
    if (handler_ptr->len != req.len)
    {
        Log::Add(Log::Level::Error, TAG, "Invalid payload length for command 0x%02X: expected %d, got %d", req.cmd, handler_ptr->len, req.len);
        return Error::InvalidParameters;
    }

    // Execute the handler's callback and return success
    handler_ptr->callback(req, [](const Response& res) {
        Robot::GetInstance().getProtocol().resolveCommand(res);
    });
    return Error::None;
}

Error Protocol::resolveCommand(const Response& res)
{
    // Search for the pending command with the matching ID
    for (uint8_t pos = 0; pos < PROTOCOL_MAX_PENDING_COMMANDS; ++pos) {
        if (pending_commands[pos].id == res.id) {
            // Invoke the associated callback
            if (pending_commands[pos].callback) {
                pending_commands[pos].callback(res);
            }
            else
            {
                Log::Add(Log::Level::Error, TAG, "No callback found for pending command ID %d", res.id);
                return Error::InvalidState;
            }
            // Reset the pending command entry
            pending_commands[pos].id = 0;
            pending_commands[pos].callback = nullptr;
            return Error::None;
        }
    }
    // No pending command matched the provided ID
    return Error::NotFound;
}

#include <iostream>
#include <vector>
#include <string>
#include <numeric>
