void solve() {
    int size;
    std::cin >> size;
    if (size == 0) {
        std::cout << "answer" << std::endl;
        std::cout.flush();
        return;
    }

    std::vector<std::string> starting_prefixes;
    std::set<std::string> collected_words;

    for (char letter = 'a'; letter <= 'z'; ++letter) {
        std::string str_prefix(1, letter);
        std::cout << "query " << str_prefix << " " << 1 << std::endl;
        std::cout.flush();

        int count;
        std::cin >> count;
        if (count > 0) {
            starting_prefixes.push_back(str_prefix);
            std::string input_word;
            std::cin >> input_word;
            collected_words.insert(input_word);
        }
    }

    // Sort prefixes in reverse alphabetical order as a heuristic approach
    std::sort(starting_prefixes.rbegin(), starting_prefixes.rend());
    int remaining = size;

    for (size_t idx = 0; idx < starting_prefixes.size(); ++idx) {
        const std::string& str_prefix = starting_prefixes[idx];

        int existing_count = 0;
        for (const auto& input_word : collected_words) {
            if (input_word.rfind(str_prefix, 0) == 0) {
                existing_count++;
            }
        }

        int target_count = size - (collected_words.size() - existing_count);
        if (idx == starting_prefixes.size() - 1) {
            // For final prefix, calculate exact remaining count
            target_count = size - collected_words.size() + existing_count;
        }

        if (target_count <= 0) continue;

        std::cout << "query " << str_prefix << " " << target_count << std::endl;
        std::cout.flush();

        int count;
        std::cin >> count;
        for (int loop_idx = 0; loop_idx < count; ++loop_idx) {
            std::string input_word;
            std::cin >> input_word;
            collected_words.insert(input_word);
        }
    }

    std::cout << "answer";
    for (const auto& input_word : collected_words) {
        std::cout << " " << input_word;
    }
    std::cout << std::endl;
    std::cout.flush();
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int t;
    std::cin >> t;
    while (t--) {
        solve();
    }

    return 0;
}

