using asio::local::stream_protocol;

class connection_handler
  : public std::enable_shared_from_this<connection_handler>
{
public:
  connection_handler(stream_protocol::socket sock)
    : socket_(std::move(sock))
  {
  }
  void begin()
  {
    perform_read();
  }
private:
  void perform_read()
  {
    auto self(shared_from_this());
    socket_.async_read_some(asio::buffer(buffer_),
        [this, self](std::error_code ec, std::size_t bytes_transferred)
        {
          if (!ec)
            perform_write(bytes_transferred);
        });
  }
  void perform_write(std::size_t size)
  {
    auto self(shared_from_this());
    asio::async_write(socket_,
        asio::buffer(buffer_, size),
        [this, self](std::error_code ec, std::size_t /*bytes*/)
        {
          if (!ec)
            perform_read();
        });
  }
  // Socket for client communication
  stream_protocol::socket socket_;
  // Data buffer for incoming/outgoing messages
  std::array<char, 2048> buffer_;
};

class local_server
{
public:
  local_server(asio::io_context& context, const std::string& path)
    : acceptor_(context, stream_protocol::endpoint(path))
  {
    initiate_accept();
  }
private:
  void initiate_accept()
  {
    acceptor_.async_accept(
        [this](std::error_code ec, stream_protocol::socket client_socket)
        {
          if (!ec)
          {
            std::make_shared<connection_handler>(std::move(client_socket))->begin();
          }
          initiate_accept();
        });
  }
  stream_protocol::acceptor acceptor_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: stream_server <path>\n";
      std::cerr << "*** NOTICE: existing file will be deleted ***\n";
      return 1;
    }
    asio::io_context service;
    std::remove(argv[1]);
    local_server handler(service, argv[1]);
    service.run();
  }
  catch (std::exception& err)
  {
    std::cerr << "Error: " << err.what() << "\n";
  }
  return 0;
}
