#include <ocs2_switched_model_interface/constraint/EndEffectorVelocityConstraint.h>

int main(int argc, char** argv) {
  // Define the constraint type with 3 dimensions and 2 degrees of freedom
  using EeVelConstraint_t = switched_model::EndEffectorVelocityConstraint<3, 2>;

  // Initialize settings and constraint object
  switched_model::EndEffectorVelocityConstraintSettings params;
  EeVelConstraint_t eeVelConstraint(params);

  // Prepare evaluation variables
  EeVelConstraint_t::scalar_t t;
  EeVelConstraint_t::state_vector_t x;
  EeVelConstraint_t::input_vector_t u;

  t = 0.0;
  x.setZero();
  u.setZero();

  // Set desired end-effector velocity to -2.0 for all components
  params.desiredEndEffectorVelocity.fill(-2.0);

  // Compute constraint value and its linear approximation
  auto constraintValues = eeVelConstraint.getValue(t, x, u);
  auto linearModel = eeVelConstraint.getLinearApproximation(t, x, u);

  std::cout << "Constraint residuals:" << std::endl;
  for (const auto& val : constraintValues) {
    std::cout << val << std::endl;
  }

  std::cout << "Jacobian w.r.t. state:" << std::endl;
  for (const auto& row : linearModel.derivativeState) {
    std::cout << row.transpose() << std::endl;
  }

  std::cout << "Jacobian w.r.t. input:" << std::endl;
  for (const auto& col : linearModel.derivativeInput) {
    std::cout << col.transpose() << std::endl;
  }

  return 0;
}

