namespace quadrants::lang {

// This optimization removes immutable local variables by propagating their values.
// It relies on the results from GatherImmutableLocalVars and replaces loads of
// such variables with the stored value, then removes the associated allocas,
// stores, and loads.
class PropagateImmutableLocals : public BasicStmtVisitor {
 private:
  using BasicStmtVisitor::visit;

  std::unordered_set<Stmt *> immutable_vars_;
  std::unordered_map<Stmt *, Stmt *> var_to_value_;
  ImmediateIRModifier ir_modifier_;
  DeferredIRModifier deferred_op_;

 public:
  explicit PropagateImmutableLocals(
      const std::unordered_set<Stmt *> &immutable_set,
      IRNode *root_node)
      : immutable_vars_(immutable_set), ir_modifier_(root_node) {
  }

  void visit(AllocaStmt *stmt) override {
    if (immutable_vars_.count(stmt) > 0) {
      deferred_op_.remove(stmt);
    }
  }

  void visit(LocalLoadStmt *stmt) override {
    if (immutable_vars_.count(stmt->src) > 0) {
      ir_modifier_.substitute(stmt, var_to_value_[stmt->src]);
      deferred_op_.remove(stmt);
    }
  }

  void visit(LocalStoreStmt *stmt) override {
    if (immutable_vars_.count(stmt->dest) > 0) {
      QD_ASSERT(var_to_value_.find(stmt->dest) == var_to_value_.end());
      var_to_value_[stmt->dest] = stmt->val;
      deferred_op_.remove(stmt);
    }
  }

  static void apply(IRNode *node) {
    PropagateImmutableLocals pass(
        irpass::analysis::collect_immutable_locals(node), node);
    node->accept(&pass);
    pass.deferred_op_.commit();
  }
};

namespace irpass {
void propagate_immutable_local_vars(IRNode *root) {
  QD_AUTO_PROF;
  PropagateImmutableLocals::apply(root);
}
}  // namespace irpass

}  // namespace quadrants::lang

