// A lightweight reference wrapper for sub-vectors with arithmetic operations
template <typename T>
class subvector_view {
private:
    T* elements;
    size_t length;
public:
    subvector_view(T* ptr, size_t len) : elements(ptr), length(len) {}

    // Copy assignment: copy values from another view into this one
    subvector_view& operator=(const subvector_view& src) {
        for (size_t idx = 0; idx < length; ++idx) {
            elements[idx] = src.elements[idx];
        }
        return *this;
    }

    // Addition operator: create a new view with element-wise sum
    subvector_view operator+(const subvector_view& rhs) const {
        subvector_view temp(*this);
        for (size_t idx = 0; idx < length; ++idx) {
            temp.elements[idx] += rhs.elements[idx];
        }
        return temp;
    }
};

