// Helper function for topological sorting using DFS
void Graph::topoSortDFS(int node, std::vector<bool>& seen, std::stack<int>& resultStack) {
    // Mark the node as visited
    seen[node] = true;

    // Explore all adjacent nodes recursively
    for (int neighbor : adj[node]) {
        if (!seen[neighbor]) {
            topoSortDFS(neighbor, seen, resultStack);
        }
    }

    // Add current node to stack after visiting all descendants
    resultStack.push(node);
}

// Main function to perform topological sort on the graph
std::vector<int> Graph::topologicalSort() {
    std::stack<int> tempStack;

    // Initialize visited array
    std::vector<bool> visited(V, false);

    // Perform DFS from each unvisited node
    for (int i = 0; i < V; ++i) {
        if (!visited[i]) {
            topoSortDFS(i, visited, tempStack);
        }
    }

    // Build the topological order by popping from stack
    std::vector<int> order;
    while (!tempStack.empty()) {
        order.push_back(tempStack.top());
        tempStack.pop();
    }

    return order;
}

