#include <openssl/bn.h>
#include <iostream>

// Verify cryptographic computation using modular exponentiation and multiplication
bool validateCryptographicComputation(BIGNUM* X, BIGNUM* s, BIGNUM* d_val, BIGNUM* e2_val, 
                                      BIGNUM* offset, BIGNUM* t4_val, BIGNUM* exp, 
                                      BIGNUM* modulus, BIGNUM* msg, BIGNUM* T_val, BN_CTX* context) {
    // Step 1: Add salt to initial value
    BN_add(X, X, s);

    // Step 2: Compute modulo with e2
    BN_mod(d_val, X, e2_val, context);

    // Step 3: Add offset value
    BN_add(d_val, d_val, offset);

    // Step 4: Compute t4 = t4^exp mod modulus
    BN_mod_exp(t4_val, t4_val, exp, modulus, context);

    // Step 5: Compute X = msg^d_val mod modulus
    BN_mod_exp(X, msg, d_val, modulus, context);

    // Step 6: Multiply by T and reduce modulo modulus
    BN_mod_mul(X, X, T_val, modulus, context);

    // Step 7: Verify equality of computed values
    if (BN_cmp(X, t4_val) != 0) {
        std::cerr << "Verification failed: XT != t4" << std::endl;
        BN_CTX_free(context);
        return false;
    }

    // Clean up context
    BN_CTX_free(context);
    return true;
}

