// Compute overall CPU usage as ratio of active to total jiffies
float Processor::Utilization() {
    long activeTime = LinuxParser::ActiveJiffies();
    long totalTime = LinuxParser::Jiffies();

    // Avoid division by zero
    if (totalTime == 0) {
