// Serialize a string using cereal binary archive (variant implementation)
std::string serializeData(const std::string& data) {
#if defined ENABLE_BOOST_IOSTREAMS && !defined DISABLE_BOOST_IOSTREAMS
    // Alternative approach: Use Boost.IOStreams with explicit buffer management
    std::string buffer;
    {
        boost::iostreams::stream<boost::iostreams::back_insert_device<std::string>> stream(
            boost::iostreams::back_insert_device<std::string>(buffer));
        cereal::BinaryOutputArchive archive(stream);
        archive(data);
        stream.flush();
    }
    return buffer;
#else
    // Fallback to standard C++ string stream handling
    std::ostringstream oss;
    {
        cereal::BinaryOutputArchive archive(oss);
        archive(data);
    }
    return oss.str();
#endif
}

