// Process a client request and send a fixed response
void processConnection(int clientFd) {
    // Define the HTTP response message for the root endpoint
    std::string reply = "HTTP/1.1 200 OK\n"
                        "Content-Type: text/plain\n"
                        "Content-Length: 12\n"
                        "\n"
                        "Hello, World!";

    // Send the complete response to the connected client
    send(clientFd, reply.c_str(), reply.length(), 0);

    // Terminate the client connection
    close(clientFd);
}

int main() {
    // Initialize a TCP socket for the server
    int serverFd = socket(AF_INET, SOCK_STREAM, 0);

    // Configure the server address structure
    sockaddr_in serverAddr;
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(8080);
    serverAddr.sin_addr.s_addr = INADDR_ANY;

    // Bind the socket to the specified port and interface
    bind(serverFd, reinterpret_cast<struct sockaddr*>(&serverAddr), sizeof(serverAddr));

    // Start listening for incoming connections with a backlog of 5
    listen(serverFd, 5);

    // Continuously accept and handle client connections
    while (true) {
        int clientFd = accept(serverFd, nullptr, nullptr);
        processConnection(clientFd);
    }

    // Close the server socket (unreachable in this infinite loop)
    close(serverFd);
    return 0;
}

