std::vector<double> computeEdgeScores(const Graph& G, 
                                      const std::vector<double>& attr0, 
                                      const std::vector<double>& attr1, 
                                      const std::vector<bool>& mask) {
    if (!G.hasEdgeIds()) {
        throw std::runtime_error("edges have not been indexed - call indexEdges first");
    }

    std::vector<double> result;
    result.reserve(G.upperEdgeIdBound());

    for (edgeid eid = 0; eid < G.upperEdgeIdBound(); ++eid) {
        result.push_back(mask[eid] ? attr1[eid] : attr0[eid]);
    }

    return result;
}

#include <cstddef>

void calculateTimeDerivative(const Scalar& lapse,
                             const Tensor& extrinsic_curvature,
                             Tensor& dt_spatial_metric,
                             const Vector& shift,
                             const Tensor& deriv_spatial_metric,
                             const Tensor& spatial_metric,
                             const Tensor& deriv_shift) {
  // Determine the spatial dimension from the metric tensor
  const size_t dim = spatial_metric.dimension();

  // Iterate through all components of the symmetric tensor
  for (size_t idx_i = 0; idx_i < dim; ++idx_i) {
    for (size_t idx_j = 0; idx_j < dim; ++idx_j) {
      // Start with the principal term involving the lapse and extrinsic curvature
      double result = -2.0 * lapse.get() * extrinsic_curvature.get(idx_i, idx_j);

      // Add contributions from the shift vector and spatial derivatives
      for (size_t idx_k = 0; idx_k < dim; ++idx_k) {
        result += shift.get(idx_k) * deriv_spatial_metric.get(idx_k, idx_i, idx_j);
        result += spatial_metric.get(idx_k, idx_i) * deriv_shift.get(idx_j, idx_k);
        result += spatial_metric.get(idx_k, idx_j) * deriv_shift.get(idx_i, idx_k);
      }

      // Store the computed value in the output tensor
      dt_spatial_metric.get(idx_i, idx_j) = result;
    }
  }
}

