// Reset cache state and pointer after flushing
void resetCacheAndPointer(void* log_map_start, std::size_t line_size, char*& current_ptr, std::atomic<void*>& nvm_flag) {
    // Flush the cache line associated with the log map
    flush_cache(log_map_start, line_size);

