#include <array>
#include <algorithm>

// Determine the highest supported SIMD instruction set version from CPUID registers
int maxSupportedSIMDVersion(const std::array<uint32_t, 4>& cpuRegs) {
    int highestVersion = 0;

    // Extract SSE4.2 support level (bits 3:0 of first register)
    int sseLevel = cpuRegs[0] & 0x0F;
    highestVersion = std::max(highestVersion, sseLevel);

    // Check for AVX support (bit 28 of fourth register)
    int avxEnabled = (cpuRegs[3] >> 28) & 1;
    highestVersion = std::max(highestVersion, avxEnabled);

    return highestVersion;
}

