// Helper macro for right rotation (32-bit)
#define ROR(x, n) (((x) >> (n)) | ((x) << (32 - (n))))

// SHA-256 logical functions
#define Ch(a, b, c) ((a & b) ^ (~a & c))
#define Maj(a, b, c) ((a & b) ^ (a & c) ^ (b & c))
#define Σ0(x) (ROR(x, 2) ^ ROR(x, 13) ^ ROR(x, 22))
#define Σ1(x) (ROR(x, 6) ^ ROR(x, 11) ^ ROR(x, 25))
#define σ0(x) (ROR(x, 7) ^ ROR(x, 18) ^ (x >> 3))
#define σ1(x) (ROR(x, 17) ^ ROR(x, 19) ^ (x >> 10))

// SHA-256 round constants
const uint32_t ROUND_CONSTANTS[] = {
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2
};

// Initial hash values (first 32 bits of fractional parts of square roots of first 8 primes)
struct HashState {
    uint32_t h[8];
};

// Function to process a single 512-bit block (simplified version)
void sha256_compress(const uint8_t block[64], HashState &state) {
    // Prepare message schedule array w[0..63]
    uint32_t w[64];

    // First 16 words come from the block
    for (int i = 0; i < 16; ++i) {
        w[i] = (static_cast<uint32_t>(block[i * 4]) << 24) |
               (static_cast<uint32_t>(block[i * 4 + 1]) << 16) |
               (static_cast<uint32_t>(block[i * 4 + 2]) << 8)  |
               (static_cast<uint32_t>(block[i * 4 + 3]));
    }

    // Extend the first 16 words into the remaining 48 words
    for (int i = 16; i < 64; ++i) {
        w[i] = σ1(w[i - 2]) + w[i - 7] + σ0(w[i - 15]) + w[i - 16];
    }

    // Initialize working variables
    uint32_t a = state.h[0];
    uint32_t b = state.h[1];
    uint32_t c = state.h[2];
    uint32_t d = state.h[3];
    uint32_t e = state.h[4];
    uint32_t f = state.h[5];
    uint32_t g = state.h[6];
    uint32_t h = state.h[7];

    // Main compression loop
    for (int i = 0; i < 64; ++i) {
        uint32_t t1 = h + Σ1(e) + Ch(e, f, g) + ROUND_CONSTANTS[i] + w[i];
        uint32_t t2 = Σ0(a) + Maj(a, b, c);

        h = g;
        g = f;
        f = e;
        e = d + t1;
        d = c;
        c = b;
        b = a;
        a = t1 + t2;
    }

    // Add the compressed chunk to the current hash value
    state.h[0] += a;
    state.h[1] += b;
    state.h[2] += c;
    state.h[3] += d;
    state.h[4] += e;
    state.h[5] += f;
    state.h[6] += g;
    state.h[7] += h;
}

// Simplified SHA-256 processing function (handles only one block)
void sha256_process(const uint8_t *data, size_t len, HashState &state) {
    // For simplicity, assume input fits in one 512-bit block and is properly padded
    // In real implementation, padding would be added here

    // Pad the message: append 1 bit, then zeros, then length
    uint8_t padded_block[64] = {0};
    size_t copy_len = (len < 56) ? len : 56;  // Keep it simple for demo

    // Copy data into padded block
    for (size_t i = 0; i < copy_len; ++i) {
        padded_block[i] = data[i];
    }

    // Append the '1' bit (as 0x80)
    padded_block[copy_len] = 0x80;

    // If there's enough room, add length at the end (in bits)
    if (copy_len < 56) {
        uint64_t bit_len = len * 8;
        padded_block[56] = static_cast<uint8_t>(bit_len >> 56);
        padded_block[57] = static_cast<uint8_t>(bit_len >> 48);
        padded_block[58] = static_cast<uint8_t>(bit_len >> 40);
        padded_block[59] = static_cast<uint8_t>(bit_len >> 32);
        padded_block[60] = static_cast<uint8_t>(bit_len >> 24);
        padded_block[61] = static_cast<uint8_t>(bit_len >> 16);
        padded_block[62] = static_cast<uint8_t>(bit_len >> 8);
        padded_block[63] = static_cast<uint8_t>(bit_len);
    } else {
        // For simplicity, just use the first block as-is for demonstration
    }

    sha256_compress(padded_block, state);
}

// Example usage
int main() {
    std::string message = "Hello, SHA-256!";
    HashState initial_state = {{
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
        0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19
    }};

    sha256_process(reinterpret_cast<const uint8_t *>(message.c_str()), message.length(), initial_state);

    for (int i = 0; i < 8; ++i) {
        std::cout << std::hex << initial_state.h[i] << " ";
    }
    std::cout << std::endl;

    return 0;
}

