// Custom event system implementation
template <typename ArgType>
class Signal {
public:
    using Callback = std::function<void(ArgType)>;

    void subscribe(const Callback& cb) {
        listeners.push_back(cb);
    }

    void unsubscribe(const Callback& cb) {
        for (auto it = listeners.begin(); it != listeners.end(); ++it) {
            if (*it == cb) {
                listeners.erase(it);
                break;
            }
        }
    }

    void emit(const ArgType& value) {
        for (const auto& listener : listeners) {
            listener(value);
        }
    }

private:
    std::list<Callback> listeners;
};

// Example class that handles events
class EventReceiver {
public:
    void handleSignal(int data) {
        std::cout << "Received signal with value: " << data << std::endl;
    }
};

int main() {
    EventReceiver receiver;
    Signal<int> signalSystem;

    // Register handler
    signalSystem.subscribe([&receiver](int val) { 
        receiver.handleSignal(val); 
    });

    // Emit first event
    signalSystem.emit(2);

    // Unsubscribe the handler
    auto handler = [&receiver](int val) { 
        receiver.handleSignal(val); 
    };
    signalSystem.unsubscribe(handler);

    // Try emitting after unsubscription - nothing should print
    signalSystem.emit(3);

    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>

// Structure to store parsed command-line configuration
struct CliConfig {
    std::string scriptPath;
    std::vector<std::string> extraInputs;
    int testCaseId;
    bool isThreeDimensional;
    bool enableDiffValidation;
    double diffPerturbationFactor;
};

// Parse command-line arguments into a CliConfig object
CliConfig parseArgs(int argc, char* argv[]) {
    CliConfig config{};

    // Map argument flags to their corresponding fields and help descriptions
    std::unordered_map<std::string, std::pair<void*, std::string>> flagMap = {
        {"-script", {&config.scriptPath, "Lua script file path for initial data"}},
        {"-i", {&config.extraInputs, "Additional inline input string"}},
        {"-test", {&config.testCaseId, "Test case identifier (non-Lua test)"}},
        {"--3d", {&config.isThreeDimensional, "Enable 3D mode (non-Lua test)"}},
        {"--run_diff_test", {&config.enableDiffValidation, "Activate differential validation (non-Lua test)"}},
        {"-dtps", {&config.diffPerturbationFactor, "Scale factor for perturbation in diff test"}}
    };

    // Process each command-line token
    for (int idx = 1; idx < argc; ++idx) {
        std::string token = argv[idx];
        auto it = flagMap.find(token);

        if (it != flagMap.end()) {
            void* targetPtr = it->second.first;

            if (token == "-i") {
                if (idx + 1 < argc && argv[idx + 1][0] != '-') {
                    static_cast<std::vector<std::string>*>(targetPtr)->push_back(argv[idx + 1]);
                    ++idx;
                }
            } else if (token == "--3d" || token == "--run_diff_test") {
                *static_cast<bool*>(targetPtr) = true;
            } else {
                if (idx + 1 < argc && argv[idx + 1][0] != '-') {
                    if (token == "-dtps") {
                        *static_cast<double*>(targetPtr) = std::stod(argv[idx + 1]);
                    } else {
                        *static_cast<std::string*>(targetPtr) = argv[idx + 1];
                    }
                    ++idx;
                }
            }
        }
    }

    return config;
}

int main(int argc, char* argv[]) {
    CliConfig config = parseArgs(argc, argv);

    // Output the parsed configuration
    std::cout << "Script Path: " << config.scriptPath << std::endl;
    std::cout << "Extra Inputs: ";
    for (const auto& input : config.extraInputs) {
        std::cout << input << " ";
    }
    std::cout << std::endl;
    std::cout << "Test Case ID: " << config.testCaseId << std::endl;
    std::cout << "3D Mode: " << (config.isThreeDimensional ? "enabled" : "disabled") << std::endl;
    std::cout << "Diff Validation: " << (config.enableDiffValidation ? "active" : "inactive") << std::endl;
    std::cout << "Perturbation Factor: " << config.diffPerturbationFactor << std::endl;

    return 0;
