template <typename T>
T dotProduct(const Vector2<T>& a, const Vector2<T>& b) {
#ifdef RM_MATH_STAT
    PROFILE_FUNCTION();
#endif
    return a.x * b.x + a.y * b.y;
}

// Compute 2D cross product (scalar magnitude)
template <typename T>
T crossProduct(const Vector2<T>& a, const Vector2<T>& b) {
#ifdef RM_MATH_STAT
    PROFILE_FUNCTION();
#endif
    return a.x * b.y - a.y * b.x;
}

// Normalize a vector to unit length
template <typename T>
Vector2<T> normalize(const Vector2<T>& vec) {
#ifdef RM_MATH_STAT
    PROFILE_FUNCTION();
#endif
    T len = std::sqrt(vec.x * vec.x + vec.y * vec.y);
    return {vec.x / len, vec.y / len};
}

// Compute magnitude (length) of a vector
template <typename T>
T magnitude(const Vector2<T>& vec) {
#ifdef RM_MATH_STAT
    PROFILE_FUNCTION();
#endif
    return std::sqrt(vec.x * vec.x + vec.y * vec.y);
}

