class UCylinder : public Cylinder {
private:
    double innerHollowRadius;
public:
    UCylinder(double r, double h, double ir) 
        : Cylinder(r, h), innerHollowRadius(ir) {}

    double computeVolume() {
        double outerVol = Cylinder::computeVolume();
        double hollowVol = PI * innerHollowRadius * innerHollowRadius * verticalHeight;
        return outerVol - hollowVol;
    }

    double computeSurfaceArea() {
        double outerSA = Cylinder::computeSurfaceArea();
        double innerHollowSA = 2.0 * PI * innerHollowRadius * verticalHeight;
        return outerSA - innerHollowSA;
    }
};
#endif

