class Paraboloid : public Shape {
private:
    double rimRadius;
    double focalHeight;
public:
    Paraboloid(double r, double h) : rimRadius(r), focalHeight(h) {}

    double computeVolume() {
        return 0.5 * PI * rimRadius * rimRadius * focalHeight;
    }

    double computeSurfaceArea() {
        double term1 = rimRadius * rimRadius + focalHeight * focalHeight;
        return PI * rimRadius * sqrt(term1);
    }
};
