class Shape {
public:
    virtual double calculateArea() const = 0;
    virtual double calculateBoundaryLength() const = 0;
    virtual ~Shape() {}
};

class Coordinate2D {
    double horizontal, vertical;
public:
    Coordinate2D(double h, double v) : horizontal(h), vertical(v) {}
    double getHorizontal() const { return horizontal; }
    double getVertical() const { return vertical; }
};

class Polyline : public Shape {
    std::vector<Coordinate2D> vertices;
public:
    Polyline(const std::vector<Coordinate2D>& coords) : vertices(coords) {}

    double calculateArea() const override {
        // Compute polygon area using the shoelace formula
        if (vertices.size() < 3) return 0.0;

        double area = 0.0;
        int n = vertices.size();
        for (int i = 0; i < n; ++i) {
            int j = (i + 1) % n;
            area += vertices[i].getHorizontal() * vertices[j].getVertical();
            area -= vertices[j].getHorizontal() * vertices[i].getVertical();
        }
        return std::abs(area) / 2.0;
    }

    double calculateBoundaryLength() const override {
        // Calculate total perimeter by summing edge lengths
        if (vertices.size() < 2) return 0.0;

        double perimeter = 0.0;
        int n = vertices.size();
        for (int i = 0; i < n; ++i) {
            int j = (i + 1) % n;
            double dx = vertices[j].getHorizontal() - vertices[i].getHorizontal();
            double dy = vertices[j].getVertical() - vertices[i].getVertical();
            perimeter += std::sqrt(dx * dx + dy * dy);
        }
        return perimeter;
    }
};

class Disk : public Shape {
    double radiusValue;
public:
    Disk(double r) : radiusValue(r) {}

    double calculateArea() const override {
        return M_PI * radiusValue * radiusValue;
    }

    double calculateBoundaryLength() const override {
        return 2.0 * M_PI * radiusValue;
    }
};

