void memcpy(void* dest, const void* src, std::int64_t size);

template <typename T>
inline void copy(T* dest, const T* src, std::int64_t count) {
    // Validate input parameters for safety
    if (count < 0) {
        throw std::invalid_argument("Copy count cannot be negative");
    }

    // Compute total byte size with overflow check
    constexpr auto elem_size = static_cast<std::int64_t>(sizeof(T));
    if (elem_size == 0) {
        throw std::runtime_error("Element size is zero, which is invalid");
    }

    // Check for multiplication overflow before computing total size
    if (count > 0 && elem_size > (std::numeric_limits<std::int64_t>::max() / count)) {
        throw std::overflow_error("Memory copy size would overflow");
    }

    const auto total_bytes = elem_size * count;

    // Perform the actual memory copy
    ONEDAL_ASSERT_MUL_OVERFLOW(std::int64_t, elem_size, count);
    memcpy(dest, src, total_bytes);
}

