// Node structure for the stack, storing value and current minimum
struct StackNode {
    int value;
    int currentMin;
    StackNode* previous;

    StackNode(int v, int m, StackNode* prev) : value(v), currentMin(m), previous(prev) {}
};

class EfficientMinStack {
private:
    StackNode* head;

public:
    EfficientMinStack() : head(nullptr) {}

    // Push element onto stack while tracking minimum
    void push(int newValue) {
        if (head == nullptr) {
            head = new StackNode(newValue, newValue, nullptr);
        } else {
            int newMin = std::min(newValue, head->currentMin);
            head = new StackNode(newValue, newMin, head);
        }
    }

    // Remove top element from stack
    void pop() {
        assert(head != nullptr);  // Verify stack is not empty
        StackNode* oldHead = head;
        head = head->previous;
        delete oldHead;
    }

    // Return top element's value
    int peekTop() {
        assert(head != nullptr);  // Verify stack is not empty
        return head->value;
    }

    // Return minimum element in the stack
    int findMinimum() {
        assert(head != nullptr);  // Verify stack is not empty
        return head->currentMin;
    }
};

int main() {
    EfficientMinStack stack;
    stack.push(5);
    stack.push(3);
    stack.push(7);
    stack.push(2);

    std::cout << "Current top: " << stack.peekTop() << std::endl;     // Output: 2
    std::cout << "Smallest value: " << stack.findMinimum() << std::endl;  // Output: 2

    stack.pop();
    std::cout << "Top after removal: " << stack.peekTop() << std::endl;   // Output: 7
    std::cout << "Minimum after removal: " << stack.findMinimum() << std::endl;  // Output: 3

    return 0;
}

