struct LocalNode {
    // Structure definition remains unchanged
};

int main(int argc, char* argv[]) {
    if (argc != 3) {
        std::cerr << "Usage: ./proxy <path> <count>\n";
        return -1;
    }

    unsigned int nodeCount;
    if (sscanf(argv[2], "%u", &nodeCount) != 1) {
        std::cerr << "Invalid number format\n";
        return -1;
    }

    LocalNode** nodes = new LocalNode*[nodeCount];

    int parentToChildPipe[2];
    if (pipe(parentToChildPipe) == -1) {
        perror("Failed to create pipe");
        return -1;
    }

    int fileDescriptor = open(argv[1], O_RDONLY);
    if (fileDescriptor == -1) {
        perror("Cannot open file");
        return -1;
    }

    for (unsigned int i = 0; i < nodeCount; ++i) {
        int childToParentPipe[2];
        if (pipe(childToParentPipe) == -1) {
            perror("Pipe creation failed");
            return -1;
        }

        pid_t processId = fork();
        if (processId == -1) {
            perror("Fork failed");
            return -1;
        }

        if (processId == 0) {  // Child process
            close(childToParentPipe[1]);  // Close write end
            close(parentToChildPipe[0]);  // Close read end of main->child pipe

            char dataBuffer[1024];
            ssize_t bytesRead = read(parentToChildPipe[0], dataBuffer, sizeof(dataBuffer));
            if (bytesRead == -1) {
                perror("Reading from pipe failed");
                return -1;
            }

            // Process the received data independently
            // ...

            close(parentToChildPipe[0]);
            exit(0);
        } else {  // Parent process
            close(childToParentPipe[0]);  // Close read end
            close(parentToChildPipe[1]);  // Close write end of main->child pipe

            char fileData[1024];
            ssize_t bytesFromDisk = read(fileDescriptor, fileData, sizeof(fileData));
            if (bytesFromDisk == -1) {
                perror("File reading error");
                return -1;
            }

            ssize_t bytesSent = write(childToParentPipe[1], fileData, bytesFromDisk);
            if (bytesSent == -1) {
                perror("Writing to pipe failed");
                return -1;
            }

            close(childToParentPipe[1]);
        }
    }

    close(fileDescriptor);

    // Wait for all child processes to finish
    for (unsigned int j = 0; j < nodeCount; ++j) {
        wait(nullptr);
    }

    delete[] nodes;
    return 0;
}

