using namespace std;

const int MAX_SIZE = 100005;
vector<pair<int, int>> edges[MAX_SIZE];
int left_vals[MAX_SIZE], right_vals[MAX_SIZE], fenwick[MAX_SIZE];

// Sort pairs by first element, then second element
void organizePairs(vector<pair<int, int>>& collection) {
    sort(collection.begin(), collection.end());
}

// Query maximum value in Fenwick tree up to position x
int queryMax(int position) {
    int result = 0;
    while (position > 0) {
        result = max(result, fenwick[position]);
        position -= position & -position;
    }
    return result;
}

// Update Fenwick tree at position x with given value
void updateTree(int position, int value) {
    while (position < MAX_SIZE) {
        fenwick[position] = max(fenwick[position], value);
        position += position & -position;
    }
}

int main() {
    // Sample data population for demonstration
    // In real scenario, this would read from input
    vector<pair<int, int>> temp;
    temp.push_back({1, 5});
    temp.push_back({2, 3});
    temp.push_back({3, 7});
    organizePairs(temp);

    // Process the organized data
    int max_value = 0;
    for (auto& p : temp) {
        int current_query = queryMax(p.first);
        int new_value = current_query + p.second;
        max_value = max(max_value, new_value);
        updateTree(p.first, new_value);
    }

    cout << max_value << '\n';
    return 0;
}

