class WindowCycleManager {
public:
    enum CycleMode { NEXT, PREVIOUS };

    void ProcessWindowSwitch(CycleMode mode, bool enableLooping) {
        // Skip if system is in locked state
        if (SystemShell::GetActive()->GetSystemDelegate()->IsLocked()) {
            return;
        }

        // Acquire current window list
        std::vector<Window*> availableWindows = RetrieveActiveWindows();

        // Locate currently focused window
        auto currentFocus = availableWindows.end();
        for (auto iter = availableWindows.begin(); iter != availableWindows.end(); ++iter) {
            if ((*iter)->isActive) {
                currentFocus = iter;
                break;
            }
        }

        if (currentFocus != availableWindows.end()) {
            // Determine next/previous window based on direction
            if (mode == NEXT) {
                currentFocus = (currentFocus == availableWindows.end() - 1) ? 
                               availableWindows.begin() : currentFocus + 1;
            } else {
                currentFocus = (currentFocus == availableWindows.begin()) ? 
                               availableWindows.end() - 1 : currentFocus - 1;
            }

            // Reset activity flags and activate new window
            for (auto& win : availableWindows) {
                win->isActive = (win == *currentFocus);
            }
        }

        // Handle wrap-around behavior when enabled
        if (enableLooping && availableWindows.size() > 1) {
            for (auto& win : availableWindows) {
                win->isActive = false;
            }
            availableWindows[0]->isActive = true;
        }
    }

    bool IsInTransition() {
