bool IsProductVersionHigher(const std::wstring& fileVer, const std::wstring& productVer) {
    int fMajor = 0, fMinor = 0;
    int pMajor = 0, pMinor = 0;
    wchar_t delimiter;

    // Parse file version string
    std::wistringstream fileStream(fileVer);
    fileStream >> delimiter >> fMajor >> delimiter >> fMinor;

    // Parse product version string
    std::wistringstream productStream(productVer);
    productStream >> delimiter >> pMajor >> delimiter >> pMinor;

    // Check if product version is greater than file version
    if (pMajor > fMajor) {
        return true;
    }
    if (pMajor == fMajor && pMinor > fMinor) {
        return true;
    }
    return false;
}

