// Custom wrapper to mimic boost::asio::io_service behavior using std::thread and std::queue
class SimpleIOService {
public:
    void post(std::function<void()> task) {
        {
            std::lock_guard<std::mutex> lock(m_mutex);
            m_tasks.push(std::move(task));
        }
        m_cv.notify_one();
    }

    void run() {
        while (true) {
            std::function<void()> task;
            {
                std::unique_lock<std::mutex> lock(m_mutex);
                m_cv.wait(lock, [this] { return !m_tasks.empty() || m_stopped; });
                if (m_stopped && m_tasks.empty()) break;
                task = std::move(m_tasks.front());
                m_tasks.pop();
            }
            task();
        }
    }

    void stop() {
        {
            std::lock_guard<std::mutex> lock(m_mutex);
            m_stopped = true;
        }
        m_cv.notify_all();
    }

private:
    std::queue<std::function<void()>> m_tasks;
    std::mutex m_mutex;
    std::condition_variable m_cv;
    bool m_stopped{false};
};

// Work guard to prevent io_service from exiting when no tasks are pending
class WorkGuard {
public:
    explicit WorkGuard(SimpleIOService& svc) : m_service(&svc), m_active(true) {}

    ~WorkGuard() {
        if (m_active) {
            m_active = false;
            // No-op in this simplified version; real io_service would release work here
        }
    }

    void reset() {
        m_active = false;
    }

private:
    SimpleIOService* m_service;
    bool m_active;
};

class IOServiceManager {
public:
    IOServiceManager(size_t numThreads) : m_ioServices(numThreads), m_works(numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            m_works[i] = std::make_unique<WorkGuard>(m_ioServices[i]);
            m_threads.emplace_back([this, i]() {
                m_ioServices[i].run();
            });
        }
    }

    void submitTask(const std::function<void()>& task) {
        size_t index = m_nextIoServiceIndex.fetch_add(1) % m_ioServices.size();
        m_ioServices[index].post(task);
    }

    void stopAllServices() {
        for (auto& service : m_ioServices) {
            service.stop();
        }
        for (auto& thread : m_threads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

private:
    std::vector<SimpleIOService> m_ioServices;
    std::vector<std::unique_ptr<WorkGuard>> m_works;
    std::vector<std::thread> m_threads;
    std::atomic<size_t> m_nextIoServiceIndex{0};
};

// Example usage
int main() {
    IOServiceManager manager(4);  // Create a manager with 4 I/O service instances
    // Submit tasks to the I/O services
    for (int i = 0; i < 10; ++i) {
        manager.submitTask([i](){
            std::cout << "Task " << i << " executed by thread " << std::this_thread::get_id() << std::endl;
        });
    }
    // Stop all I/O services gracefully
    manager.stopAllServices();
    return 0;
}

