// Class to represent an operand (e.g., a number or variable)
class Operand {
public:
  Operand(const std::string& val) : value_(val) {}

  // Overload the stream insertion operator for Operand
  friend std::ostream& operator<<(std::ostream& out, const Operand& opnd) {
    out << opnd.value_;
    return out;
  }

private:
  std::string value_;
};

// Class to represent an operator (e.g., +, -, *, /)
class Operator {
public:
  Operator(const std::string& sym) : symbol_(sym) {}

  // Overload the stream insertion operator for Operator
  friend std::ostream& operator<<(std::ostream& out, const Operator& opr) {
    out << opr.symbol_;
    return out;
  }

private:
  std::string symbol_;
};

// Function to print expression in either prefix or postfix notation
void displayExpression(std::ostream& out, bool isPostfix, const Operand& expression, const Operator& operation) {
  if (isPostfix) {
    out << expression << " " << operation;
  } else {
    out << operation << " " << expression;
  }
}

int main() {
  Operand expression("5");
  Operator operation("+");

  std::cout << "Postfix format: ";
  displayExpression(std::cout, true, expression, operation);
  std::cout << std::endl;

  std::cout << "Prefix format: ";
  displayExpression(std::cout, false, expression, operation);
  std::cout << std::endl;

  return 0;
}

