// Compute the median of a vector of integers
double getMedianValue(std::vector<int>& values) {
    std::sort(values.begin(), values.end());  // Arrange elements in ascending sequence

    size_t count = values.size();
    if (count % 2 == 0) {
        // For even-sized collections, compute mean of central pair
        int lowerMid = values[count / 2 - 1];
        int upperMid = values[count / 2];
        return (static_cast<double>(lowerMid) + static_cast<double>(upperMid)) / 2.0;
    } else {
        // For odd-sized collections, return the central element
        return static_cast<double>(values[count / 2]);
    }
}

