// Custom type trait to strip variadic arguments from member function pointers
template <typename T>
struct strip_variadic_args;

// Specialization for non-const, non-volatile member function pointers with variadic args
template <typename R, typename C, typename... Args>
struct strip_variadic_args<R(C::*)(Args..., ...)> {
    using type = R(C::*)(Args...);
};

// Specialization for const member function pointers with variadic args
template <typename R, typename C, typename... Args>
struct strip_variadic_args<R(C::*)(Args..., ...) const> {
    using type = R(C::*)(Args...) const;
};

// Specialization for volatile member function pointers with variadic args
template <typename R, typename C, typename... Args>
struct strip_variadic_args<R(C::*)(Args..., ...) volatile> {
    using type = R(C::*)(Args...) volatile;
};

// Specialization for const volatile member function pointers with variadic args
template <typename R, typename C, typename... Args>
struct strip_variadic_args<R(C::*)(Args..., ...) const volatile> {
    using type = R(C::*)(Args...) const volatile;
};

// Compile-time assertion macro
#define COMPILE_TIME_ASSERT(cond) static_assert(cond, #cond)

// Helper aliases for brevity in the test
