using va_cl = void(BOOST_CLBL_TRTS_DEFAULT_VARARGS_CC foo::*)(int&, int&&, ...) const;
using va_cr = void(BOOST_CLBL_TRTS_DEFAULT_VARARGS_CC foo::*)(int&, int&&, ...) volatile;

int main() {
    // Verify that stripping variadic args yields expected signatures
    COMPILE_TIME_ASSERT(std::is_same<va_f, typename strip_variadic_args<va_f>::type>::value == false);
    COMPILE_TIME_ASSERT(std::is_same<typename strip_variadic_args<va_f>::type, 
                                     void(BOOST_CLBL_TRTS_DEFAULT_VARARGS_CC foo::*)(int&, int&&) const volatile>::value);
    COMPILE_TIME_ASSERT(std::is_same<typename strip_variadic_args<va_l>::type, 
                                     void(BOOST_CLBL_TRTS_DEFAULT_VARARGS_CC foo::*)(int&, int&&) const>::value);
    COMPILE_TIME_ASSERT(std::is_same<typename strip_variadic_args<va_r>::type, 
                                     void(BOOST_CLBL_TRTS_DEFAULT_VARARGS_CC foo::*)(int&, int&&) volatile>::value);
    COMPILE_TIME_ASSERT(std::is_same<typename strip_variadic_args<va_c>::type, 
                                     void(BOOST_CLBL_TRTS_DEFAULT_VARARGS_CC foo::*)(int&, int&&) const>::value);
    COMPILE_TIME_ASSERT(std::is_same<typename strip_variadic_args<va_cl>::type, 
                                     void(BOOST_CLBL_TRTS_DEFAULT_VARARGS_CC foo::*)(int&, int&&) const>::value);
    COMPILE_TIME_ASSERT(std::is_same<typename strip_variadic_args<va_cr>::type, 
                                     void(BOOST_CLBL_TRTS_DEFAULT_VARARGS_CC foo::*)(int&, int&&) volatile>::value);

    return 0;
}

