using namespace eosio;

class [[eosio::contract]] MyToken : public contract {
public:
  using contract::contract;

  // Create a new token type with given issuer and max supply
  [[eosio::action]]
  void create(name issuer, asset maximum_supply) {
    require_auth(_self);

    symbol_code sym_code = maximum_supply.symbol.code();
    check(maximum_supply.symbol.is_valid(), "invalid symbol name");
    check(maximum_supply.amount > 0, "max-supply must be positive");

    stats_table statstable(_self, sym_code.raw());
    auto it = statstable.find(sym_code.raw());
    check(it == statstable.end(), "token with symbol already exists");

    statstable.emplace(_self, [&](auto& s) {
      s.supply = asset{0, maximum_supply.symbol};
      s.max_supply = maximum_supply;
      s.issuer = issuer;
    });
  }

  // Issue additional tokens to an account
  [[eosio::action]]
  void issue(name to, asset quantity, std::string memo) {
    symbol_code sym_code = quantity.symbol.code();
    check(quantity.symbol.is_valid(), "invalid symbol name");
    check(memo.length() <= 256u, "memo exceeds 256 bytes");

    stats_table statstable(_self, sym_code.raw());
    auto it = statstable.find(sym_code.raw());
    check(it != statstable.end(), "token with symbol does not exist");

    const auto& token = *it;
    require_auth(token.issuer);

    check(quantity.amount > 0, "must issue positive amount");
    check(quantity.symbol == token.supply.symbol, "symbol mismatch");
    check(quantity.amount <= token.max_supply.amount - token.supply.amount,
          "insufficient remaining supply");

    statstable.modify(token, same_payer, [&](auto& s) {
      s.supply.amount += quantity.amount;
    });

    adjust_balance(token.issuer, quantity, token.issuer);
    if (to != token.issuer) {
      send_inline_transfer(token.issuer, to, quantity, memo);
    }
  }

  // Transfer tokens between accounts
  [[eosio::action]]
  void transfer(name from, name to, asset quantity, std::string memo) {
    check(from != to, "cannot transfer to self");
    require_auth(from);
    check(is_account(to), "destination account does not exist");

    symbol_code sym_code = quantity.symbol.code();
    stats_table statstable(_self, sym_code.raw());
    const auto& token = statstable.get(sym_code.raw());

    require_recipient(from);
    require_recipient(to);

    check(quantity.amount > 0, "transfer amount must be positive");
    check(memo.length() <= 256u, "memo too long");

    deduct_balance(from, quantity);
    credit_balance(to, quantity, from);
  }

  // Print balance for a specific account (requires auth)
  [[eosio::action]]
  void balance(name account) {
    require_auth(account);
    accounts_table acnts(_self, account.value);
    const auto& entry = acnts.get(account.value, "no balance found");
    print("Balance: ", entry.balance);
  }

private:
  struct [[eosio::table]] account_record {
    asset balance;
    uint64_t primary_key() const { return balance.symbol.code().raw(); }
  };

  struct [[eosio::table]] token_stats {
    asset supply;
    asset max_supply;
    name issuer;
    uint64_t primary_key() const { return supply.symbol.code().raw(); }
  };

  typedef multi_index<"accounts"_n, account_record> accounts_table;
  typedef multi_index<"stat"_n, token_stats> stats_table;

  // Helper: reduce account balance (throws if insufficient funds)
  void deduct_balance(name owner, asset amount) {
    accounts_table from_acnts(_self, owner.value);
    auto iter = from_acnts.find(amount.symbol.code().raw());
    check(iter != from_acnts.end(), "balance object missing");

    const auto& record = *iter;
    check(record.balance.amount >= amount.amount, "insufficient balance");

    if (record.balance.amount == amount.amount) {
      from_acnts.erase(iter);
    } else {
      from_acnts.modify(iter, owner, [&](auto& r) {
        r.balance.amount -= amount.amount;
      });
    }
  }

  // Helper: increase account balance (creates if needed)
  void credit_balance(name owner, asset amount, name payer) {
    accounts_table to_acnts(_self, owner.value);
    auto iter = to_acnts.find(amount.symbol.code().raw());

    if (iter == to_acnts.end()) {
      to_acnts.emplace(payer, [&](auto& r) {
        r.balance = amount;
      });
    } else {
      to_acnts.modify(iter, same_payer, [&](auto& r) {
        r.balance.amount += amount.amount;
      });
    }
  }

  // Internal alias for adjust_balance (used in issue)
  void adjust_balance(name owner, asset amount, name ram_payer) {
    credit_balance(owner, amount, ram_payer);
  }

  // Inline action helper for transfers during issue
  void send_inline_transfer(name from, name to, asset qty, std::string note) {
    SEND_INLINE_ACTION(*this, transfer, {from, "active"_n}, {from, to, qty, note});
  }
};

