struct DeviceStorageDetails {
    uint16_t fileSystemIdentifier;
    uint16_t accessPermissions;
    uint64_t totalCapacityInMB;
    uint64_t availableSpaceInMB;
    uint32_t availableObjectCount;
};

// Function to parse storage information from buffer
DeviceStorageDetails decodeStorageDetails(const BinaryBuffer& inputBuffer) {
    DeviceStorageDetails details;

    details.fileSystemIdentifier = inputBuffer.extractUint16();
    details.accessPermissions = inputBuffer.extractUint16();

    // Convert bytes to megabytes by right-shifting 20 bits (dividing by 2^20)
    details.totalCapacityInMB = inputBuffer.extractUint64() >> 20;
    details.availableSpaceInMB = inputBuffer.extractUint64() >> 20;

    details.availableObjectCount = inputBuffer.extractUint32();

    return details;
}

