    std::cout << "Access Capability: " << deviceInfo.accessPermissions << std::endl;
    std::cout << "Max Capacity (MB): " << deviceInfo.totalCapacityInMB << std::endl;
    std::cout << "Free Space (MB): " << deviceInfo.availableSpaceInMB << std::endl;
