// Output non-epsilon words with adjusted timing and length
void generateOutput(const std::vector<int>& words, const std::vector<double>& times, const std::vector<double>& lengths, 
                    const std::string& key, double frame_shift, std::ostream& output_stream) {
    size_t index = 0;
    while (index < words.size()) {
        if (words[index] != 0) {  // Skip epsilon symbols (represent silence)
            double start_time = frame_shift * times[index];
            double duration = frame_shift * lengths[index];
            output_stream << key << " 1 " << start_time << ' ' << duration << ' ' << words[index] << '\n';
        }
        ++index;
    }
}

