    static size_t writeCallback(char* contents, size_t size, size_t nmemb, void* userp) {
        if (userp) {
            ((std::string*)userp)->append(contents, size * nmemb);
        }
        return size * nmemb;
    }

public:
    WebRequest() : curlObject(nullptr), responseBuffer("") {
        curl_global_init(CURL_GLOBAL_DEFAULT);
        curlObject = curl_easy_init();
    }

    ~WebRequest() {
        if (curlObject) {
            curl_easy_cleanup(curlObject);
        }
        curl_global_cleanup();
    }

    bool execute(const std::string& url) {
        if (!curlObject) return false;

        curl_easy_setopt(curlObject, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curlObject, CURLOPT_WRITEFUNCTION, writeCallback);
        curl_easy_setopt(curlObject, CURLOPT_WRITEDATA, &responseBuffer);

        CURLcode result = curl_easy_perform(curlObject);
        return (result == CURLE_OK);
    }

    void display() const {
        std::cout << responseBuffer << std::endl;
    }

    void extract(std::string& output) const {
        output = responseBuffer;
    }
};

#include "../include/cpp_lane_line_detection.h"

int main(int argc, char* argv[]) {
    int argIndex = 1;
    while (argIndex < argc) {
        // Load image from path provided as argument
        cv::Mat sourceFrame = cv::imread(argv[argIndex]);
        if (sourceFrame.empty()) {
            std::cerr << "Warning: Could not load image at " << argv[argIndex] << std::endl;
            ++argIndex;
            continue;
        }

        // Convert to grayscale and apply smoothing
        cv::Mat channelGray;
        cv::cvtColor(sourceFrame, channelGray, cv::COLOR_BGR2GRAY);

        cv::Mat smoothedChannel;
        cv::GaussianBlur(channelGray, smoothedChannel, cv::Size(5, 5), 0.0);

        // Edge detection via Canny
        cv::Mat edgeMap;
        cv::Canny(smoothedChannel, edgeMap, 50, 150);

        // Define polygonal region of interest
        cv::Mat roiMask = cv::Mat::zeros(edgeMap.size(), edgeMap.type());
        const int bottomY = edgeMap.rows - 1;
        cv::Point roiVertices[4] = {
            cv::Point(100, bottomY),
            cv::Point(450, 300),
            cv::Point(550, 300),
            cv::Point(edgeMap.cols - 100, bottomY)
        };
        cv::fillConvexPoly(roiMask, roiVertices, 4, cv::Scalar(255));

        // Apply mask to retain only edges within ROI
        cv::Mat maskedEdges;
        cv::bitwise_and(edgeMap, roiMask, maskedEdges);

        // Detect line segments using probabilistic Hough transform
        std::vector<cv::Vec4i> detectedSegments;
        cv::HoughLinesP(maskedEdges, detectedSegments,
                        1.0, static_cast<double>(CV_PI) / 180.0,
                        50, 50.0, 10.0);

        // Overlay detected lines onto original image
        for (size_t idx = 0; idx < detectedSegments.size(); ++idx) {
            const auto& segment = detectedSegments[idx];
            cv::Point pt1(segment[0], segment[1]);
            cv::Point pt2(segment[2], segment[3]);
            cv::line(sourceFrame, pt1, pt2, cv::Scalar(0, 0, 255), 3, cv::LINE_AA);
        }

        // Show result and wait for user input before next image
        cv::imshow("Lane Line Detection Output", sourceFrame);
        cv::waitKey(0);
        ++argIndex;
    }

    return 0;
}

