#include <Python.h>

// Helper function to validate callable objects
bool is_callable_object(PyObject* obj) {
    return PyCallable_Check(obj) != 0;
}

template <typename U>
class python_converter {
public:
    // Constructor stores the Python object reference
    python_converter(PyObject* input_obj)
        : py_obj(input_obj)
    {
        // Store reference for later use
    }

    // Convert Python callable result to C++ type
    U execute_conversion() {
        // Verify the object can be called
        if (!is_callable_object(py_obj)) {
            PyErr_SetString(PyExc_TypeError, "Expected callable parameter");
            throw error_already_set();
        }

        // Execute the callable without arguments
        PyObject* temp_result = PyObject_CallObject(py_obj, nullptr);
        if (temp_result == nullptr) {
            throw error_already_set();
        }

        // Attempt to extract the C++ value from result
        U extracted_value;
        if (!PyArg_ParseTuple(temp_result, "O", &extracted_value)) {
            PyErr_SetString(PyExc_TypeError, "Conversion from Python object failed");
            Py_DECREF(temp_result);
            throw error_already_set();
        }

        // Clean up reference
        Py_DECREF(temp_result);
        return extracted_value;
    }

private:
    PyObject* py_obj;
};

