#include <mcpputil/mcpputil/pointer_utils.hpp>
#include <unordered_set>
#include <iostream>

class MemoryTracker {
public:
    void* requestMemory(size_t bytes) {
        void* addr = mcpputil::pointer_utils::allocate(bytes);
        m_live_blocks.insert(addr);
        m_current_usage += bytes;
        return addr;
    }

    void releaseMemory(void* addr, size_t bytes) {
        auto iter = m_live_blocks.find(addr);
        if (iter != m_live_blocks.end()) {
            mcpputil::pointer_utils::deallocate(addr, bytes);
            m_live_blocks.erase(iter);
            m_current_usage -= bytes;
        }
    }

    ~MemoryTracker() {
        for (void* block : m_live_blocks) {
            std::cerr << "Unreleased memory block at: " << block << std::endl;
            // Simulate cleanup without size info
            mcpputil::pointer_utils::deallocate(block, /* size */ 0);
        }
    }

    size_t currentFootprint() const {
        return m_current_usage;
    }

private:
    std::unordered_set<void*> m_live_blocks;
    size_t m_current_usage = 0;
};

int main() {
    MemoryTracker tracker;

    // Acquire memory blocks
    void* blockA = tracker.requestMemory(100);
    void* blockB = tracker.requestMemory(200);

    // Release first block intentionally
    tracker.releaseMemory(blockA, 100);

    // Second block remains allocated to simulate leak
    std::cout << "Current memory footprint: " << tracker.currentFootprint() << " bytes" << std::endl;

    // Destructor will report remaining leaked memory
    return 0;
}

