#include <unordered_map>

// Thread-local storage for managing lock states per flag type
thread_local std::unordered_map<LockFlags, ThreadLockState> thread_lock_state_map;

// Global mutex to synchronize access to the thread-local map across threads
std::mutex thread_state_access_mutex;

ThreadLockState* AcquireThreadLockState(LockFlags flag) {
    // Synchronize access using RAII-style locking
    std::lock_guard<std::mutex> guard(thread_state_access_mutex);

    // Attempt to locate existing state for the given flag
    auto iter = thread_lock_state_map.find(flag);

    // If no entry exists, construct and insert a default ThreadLockState
    if (iter == thread_lock_state_map.end()) {
        thread_lock_state_map.emplace(flag, ThreadLockState{});
        iter = thread_lock_state_map.find(flag);
    }

    // Return address of the associated ThreadLockState
    return &(iter->second);
}

