// Expression class representing a constant numeric value
class ConstantValue {
public:
    ConstantValue(double val) : value(val) {}
    double evaluate() const { return value; }
private:
    double value;
};

// Expression class representing exponentiation operation
class Exponentiation {
public:
    Exponentiation(const ConstantValue* b, const ConstantValue* e) 
        : base(b), exponent(e) {}

    double evaluate() const { 
        return std::pow(base->evaluate(), exponent->evaluate()); 
    }

private:
    const ConstantValue* base;
    const ConstantValue* exponent;
};

void runExponentiationTests() {
    // First test: 2^5 = 32
    {
        ConstantValue baseVal(2);
        ConstantValue expVal(5);
        Exponentiation expr(&baseVal, &expVal);
        assert(expr.evaluate() == 32.0);
    }

    // Second test: 3^4 = 81
    {
        ConstantValue baseVal(3);
        ConstantValue expVal(4);
        Exponentiation expr(&baseVal, &expVal);
        assert(expr.evaluate() == 81.0);
    }

    // Third test: 5^2 = 25
    {
        ConstantValue baseVal(5);
        ConstantValue expVal(2);
        Exponentiation expr(&baseVal, &expVal);
        assert(expr.evaluate() == 25.0);
    }
}

int main() {
    runExponentiationTests();
    std::cout << "All tests passed successfully!" << std::endl;
    return 0;
}

