#include <iostream>
using namespace std;

// Determine if there's a valid path from top-left to bottom-right in the maze
bool canTraverse(int rows, int cols, char grid[10][10]) {
    bool reachable[10][10] = {false};  // Track which cells can be reached

    // Starting cell is reachable only if it's open ('0')
    reachable[0][0] = (grid[0][0] == '0');

    // Process each cell in the grid
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            // Only process if current cell is open
            if (grid[i][j] == '0') {
                // Check if we can reach this cell from above
                if (i > 0 && reachable[i - 1][j]) {
                    reachable[i][j] = true;
                }
                // Check if we can reach this cell from the left
                if (j > 0 && reachable[i][j - 1]) {
                    reachable[i][j] = true;
                }
            }
        }
    }

    // Return whether the destination (bottom-right) is reachable
    return reachable[rows - 1][cols - 1];
}

int main() {
    int m = 4, n = 4;
    char maze[10][10] = {
        "0000",
        "00X0",
        "0000",
        "0X00"
    };

    cout << (canTraverse(m, n, maze) ? "Path exists" : "No path exists") << endl;
    return 0;
}

