    // Extract number of sequences from header
    int totalSequences;
    inputFile.read(reinterpret_cast<char*>(&totalSequences), sizeof(totalSequences));

    // Read sequence names
    std::vector<std::string> sequenceLabels(totalSequences);
    int index = 0;
    while (index < totalSequences) {
        int nameSize;
        inputFile.read(reinterpret_cast<char*>(&nameSize), sizeof(nameSize));
        sequenceLabels[index].assign(nameSize, ' ');
        inputFile.read(&sequenceLabels[index][0], nameSize);
        ++index;
    }

    // Process each sequence: read encoded data and decode
    std::vector<std::string> finalSequences;
    for (const auto& label : sequenceLabels) {
        int seqLength;
        inputFile.read(reinterpret_cast<char*>(&seqLength), sizeof(seqLength));

        std::string rawEncodedData;
        rawEncodedData.resize(seqLength);
        inputFile.read(&rawEncodedData[0], seqLength);

        // Convert 2-bit encoding to nucleotide characters
        std::string nucleotideString;
        int byteIndex = 0;
        while (byteIndex < rawEncodedData.size()) {
            unsigned char byteValue = static_cast<unsigned char>(rawEncodedData[byteIndex]);
            std::bitset<8> fullByte(byteValue);

            // Extract two bits at a time (assuming big-endian bit order)
            for (int bitPos = 6; bitPos >= 0; bitPos -= 2) {
                int twoBitValue = (fullByte.to_ulong() >> bitPos) & 0x03;
                nucleotideString += "ACGT"[twoBitValue];
            }
            ++byteIndex;
        }

        // Trim to actual sequence length (since we processed full bytes)
        nucleotideString.resize(seqLength * 2);
        finalSequences.push_back(nucleotideString);
    }

    inputFile.close();
    return finalSequences;
}

