// Determine if a number is a power of two using bit manipulation
bool checkPowerOfTwo(int value) {
    // Handle non-positive values first
    if (value <= 0) {
        return false;
    }

    // A power of two in binary has exactly one '1' bit
    // Using the property: n & (n-1) clears the lowest set bit
    // So if only one bit is set, this operation results in zero
    return (value & (value - 1)) == 0;
}

int main() {
    int userInput;
    std::cout << "Enter a positive integer: ";
    std::cin >> userInput;

    if (checkPowerOfTwo(userInput)) {
        std::cout << "The given number is a power of two" << std::endl;
    } else {
        std::cout << "The given number is not a power of two" << std::endl;
    }

    return 0;
}

