#include <filesystem>

namespace fs = std::filesystem;

// Search for a 'resources' directory by traversing upward from the given path
fs::path DirectoryUtils::searchResourceDirectory(const fs::path& basePath) {
    fs::path searchPath = basePath;

    // Continue searching while there are parent directories to check
    while (!searchPath.empty()) {
        fs::path candidate = searchPath / "resources";

        // Check if the candidate path exists and is a directory
        if (fs::exists(candidate) && fs::is_directory(candidate)) {
            return candidate;
        }

        // Move up one level in the directory tree
        searchPath = searchPath.has_parent_path() ? searchPath.parent_path() : fs::path();
    }

    // Return empty path if no resources directory was found
    return fs::path();
}

