class URIQuery {
private:
    std::unordered_map<std::string, std::string> queryMap;
public:
    void AddParameter(const std::string& key, const std::string& value) {
        queryMap[key] = value;
    }

    std::string ToString() const {
        if (queryMap.empty()) {
            return "";
        }

        std::stringstream ss;
        ss << "?";

        auto iter = queryMap.begin();
        while (iter != queryMap.end()) {
            ss << iter->first << "=" << iter->second;

            // Check if there are more elements after current one
            auto nextIter = iter;
            ++nextIter;
            if (nextIter != queryMap.end()) {
                ss << "&";
            }

            ++iter;
        }

        return ss.str();
    }
};

int main() {
