#include <iostream>
#include <vector>

class DataDistribution {
private:
    const double& lowerBound;
    const double& upperBound;
    const int& numberOfBins;
    double binSize;
    std::vector<int> histogramData;

    int determineBin(const double& value) {
        return static_cast<int>((value - lowerBound) / binSize);
    }

public:
    DataDistribution(const double& low, const double& high, const int& bins)
        : lowerBound(low), upperBound(high), numberOfBins(bins), histogramData(bins, 0) {
        binSize = (upperBound - lowerBound) / numberOfBins;
    }

    void includeValue(const double& value) {
        int index = determineBin(value);
        if (index >= 0 && index < numberOfBins) {
            histogramData[index]++;
        }
    }

    int getCountAt(int position) {
        if (position >= 0 && position < numberOfBins) {
            return histogramData[position];
        }
        return 0;
    }
};

int main() {
    DataDistribution dist(0.0, 10.0, 5);
    dist.includeValue(2.5);
    dist.includeValue(7.8);
    dist.includeValue(11.0);

    std::cout << "Bin 2 count: " << dist.getCountAt(2) << std::endl;  // Output: Bin 2 count: 1
    std::cout << "Bin 4 count: " << dist.getCountAt(4) << std::endl;  // Output: Bin 4 count: 0

    return 0;
}

