int main() {
    int n, k;
    cin >> n;

    // Create a 2D array with 1-based indexing
    int matrix[n+1][n+1];

    // Read the matrix values
    for (int row = 1; row <= n; ++row) {
        for (int col = 1; col <= n; ++col) {
            cin >> matrix[row][col];
        }
    }

    // Extract specific elements into a 1D array
    int extractedValues[n*n + 1];
    int count = 0;

    // First segment: top-left quadrant diagonal-like pattern
    for (int i = 1; i <= n/2; ++i) {
        ++count;
        extractedValues[count] = matrix[i][n/2 - i + 1];
    }

    // Second segment: bottom-left quadrant diagonal-like pattern
    for (int i = 1; i <= n/2; ++i) {
        ++count;
        extractedValues[count] = matrix[n/2 + i][i];
    }

    // Third segment: bottom-right quadrant diagonal-like pattern
    for (int i = 1; i <= n/2; ++i) {
        ++count;
        extractedValues[count] = matrix[n - i + 1][n/2 + i];
    }

    // Fourth segment: top-right quadrant diagonal-like pattern
    for (int i = 1; i <= n/2; ++i) {
        ++count;
        extractedValues[count] = matrix[n/2 - i + 1][n - i + 1];
    }

    // Read rotation parameter
    cin >> k;

    // Output elements starting from position k+1 to end, then wrap around to k
    for (int idx = k + 1; idx <= count; ++idx) {
        cout << extractedValues[idx] << " ";
    }
    for (int idx = 1; idx <= k; ++idx) {
        cout << extractedValues[idx] << " ";
    }

    return 0;
}

