#include <cmath>

// Define the MSRIO class
class MSRIO {
public:
    virtual void write_msr(int cpu, uint64_t offset, uint64_t value, uint64_t mask) = 0;
};

// Define the MSR class with extended function enum
class MSR {
public:
    enum m_function {
        M_FUNCTION_SCALE,
        M_FUNCTION_DIRECT
    };
};

// Define the MSRFieldControl class with refactored logic
class MSRFieldControl {
public:
    MSRFieldControl(std::shared_ptr<MSRIO> msrio, int cpu, uint64_t offset,
                    int start_bit, int width_bits, MSR::m_function op, double factor)
        : m_msrio(msrio), m_cpu(cpu), m_offset(offset), m_start_bit(start_bit),
          m_width(width_bits), m_operation(op), m_factor(factor) {}

    void write(double input_value) {
        // Compute bit mask for the field width
        uint64_t field_mask = (m_width == 64) ? 0xFFFFFFFFFFFFFFFFULL 
                                              : ((1ULL << m_width) - 1);

        // Scale and convert input to integer representation
        uint64_t raw_value = static_cast<uint64_t>(std::round(input_value / m_factor));

        // Align the value to the correct bit position
        uint64_t shifted_value = raw_value << m_start_bit;
        uint64_t aligned_mask = field_mask << m_start_bit;

        // Delegate actual write operation
        m_msrio->write_msr(m_cpu, m_offset, shifted_value, aligned_mask);
    }

private:
    std::shared_ptr<MSRIO> m_msrio;
    int m_cpu;
    uint64_t m_offset;
    int m_start_bit;
    int m_width;
    MSR::m_function m_operation;
    double m_factor;
};

