class DiningPhilosophers {
public:
    DiningPhilosophers(int num) : forks(num) {}

    void wantsToEat(int philosopher, 
                    function<void()> pickLeftFork, 
                    function<void()> pickRightFork, 
                    function<void()> eat, 
                    function<void()> putLeftFork, 
                    function<void()> putRightFork) {

        int leftForkIndex = philosopher;
        int rightForkIndex = (philosopher + 1) % forks.size();

        // Odd-numbered philosophers pick up right fork first, even-numbered pick left first
        if (philosopher % 2 == 0) {
            forks[leftForkIndex].lock();
            pickLeftFork();
            forks[rightForkIndex].lock();
            pickRightFork();

            eat();

            putRightFork();
            forks[rightForkIndex].unlock();
            putLeftFork();
            forks[leftForkIndex].unlock();
        } else {
            forks[rightForkIndex].lock();
            pickRightFork();
            forks[leftForkIndex].lock();
            pickLeftFork();

            eat();

            putLeftFork();
            forks[leftForkIndex].unlock();
            putRightFork();
            forks[rightForkIndex].unlock();
        }
    }

private:
    vector<mutex> forks;
};

