namespace detail {
    // Overload for non-member callable objects (functions, lambdas, function objects)
    template <typename Callable, typename... Parameters>
    inline auto INVOKE(Callable&& func, Parameters&&... params)
      -> std::enable_if_t<
          !std::is_member_pointer_v<std::decay_t<Callable>>,
          decltype(std::forward<Callable>(func)(std::forward<Parameters>(params)...))
      > {
        return std::forward<Callable>(func)(std::forward<Parameters>(params)...);
    }
} // namespace detail

// Public interface to invoke a callable with arguments
template <typename FuncType, typename... ArgumentTypes>
std::result_of_t<FuncType&&(ArgumentTypes&&...)> 
my_invoke(FuncType&& func, ArgumentTypes&&... args) {
    return detail::INVOKE(std::forward<FuncType>(func), std::forward<ArgumentTypes>(args)...);
}

