#include <mutex>
#include <ctime>
#include <vector>

enum class Severity { TRACE, INFO, WARN, ERR, CRIT };

class LoggingSystem {
public:
    LoggingSystem() : minSeverity(Severity::INFO) {}

    void setMinimumSeverity(Severity level) {
        minSeverity = level;
    }

    void enableConsole() {
        targets.push_back(&std::cout);
    }

    void enableFile(const std::string& path) {
        std::ofstream* stream = new std::ofstream(path);
        targets.push_back(stream);
    }

    void write(Severity severity, const std::string& text) {
        if (severity >= minSeverity) {
            std::lock_guard<std::mutex> guard(mtx);
            for (auto target : targets) {
                *target << timestamp() << " [" << severityToString(severity) << "] " << text << "\n";
            }
        }
    }

    ~LoggingSystem() {
        for (auto target : targets) {
            if (target != &std::cout) {
                auto fileStream = static_cast<std::ofstream*>(target);
                fileStream->close();
                delete fileStream;
            }
        }
    }

private:
    Severity minSeverity;
    std::vector<std::ostream*> targets;
    std::mutex mtx;

    std::string timestamp() {
        std::time_t rawTime = std::time(nullptr);
        std::tm* timeInfo = std::localtime(&rawTime);
        char buffer[64];
        std::strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeInfo);
        return std::string(buffer);
    }

    std::string severityToString(Severity sev) {
        switch (sev) {
            case Severity::TRACE:  return "DEBUG";
            case Severity::INFO:   return "INFO";
            case Severity::WARN:   return "WARNING";
            case Severity::ERR:    return "ERROR";
            case Severity::CRIT:   return "FATAL";
            default:               return "UNKNOWN";
        }
    }
};

int main() {
    LoggingSystem logger;
    logger.enableConsole();
    logger.enableFile("log.txt");
    logger.setMinimumSeverity(Severity::TRACE);

    logger.write(Severity::INFO, "This is an informational message");
    logger.write(Severity::WARN, "This is a warning message");
    logger.write(Severity::ERR, "This is an error message");
    logger.write(Severity::TRACE, "This is a debug message");

    return 0;
}

