// Create a folded and reversed version of the input string
std::string reverseFoldString(const std::string& input, int n) {
    // Build the reversed string manually instead of using std::reverse
    std::string reversed;
    for (size_t i = input.length(); i > 0; --i) {
        reversed += input[i - 1];
    }

    // Fold the reversed string into chunks of size n
    std::string result;
    for (size_t i = 0; i < reversed.length(); ++i) {
        result += reversed[i];

        // Add comma after every n characters, but not after the last character
        if ((i + 1) % n == 0 && (i + 1) < reversed.length()) {
            result += ",";
        }
    }

    return result;
}

