#include <cstring>

// Custom hash table implementation with dynamic resizing and collision resolution
class HashMap {
private:
    struct Entry {
        void* key;
        void* value;
        Entry* next;  // For chaining in case of hash collisions
    };

    Entry** buckets;       // Array of bucket pointers (linked lists)
    size_t capacity;       // Current number of buckets
    size_t count;          // Number of stored entries
    double maxLoadFactor;  // Threshold for triggering resize

    // Simple hash function using pointer address and multiplication
    size_t computeIndex(void* keyPtr, size_t keyLen) {
        // Convert pointer to integer and apply multiplicative hashing
        size_t hash = reinterpret_cast<size_t>(keyPtr);
        hash *= 2654435761U;  // Knuth's multiplicative hash constant
        return (hash >> 16) % capacity;
    }

    // Add new entry at the front of the chain at given bucket index
    void addEntry(size_t idx, void* key, void* val) {
        Entry* newNode = new Entry;
        newNode->key = key;
        newNode->value = val;
        newNode->next = buckets[idx];
        buckets[idx] = newNode;
    }

    // Double the table size and reinsert all existing entries
    void expandBuckets() {
        size_t oldCap = capacity;
        capacity *= 2;

        Entry** oldBuckets = buckets;
        buckets = new Entry*[capacity];
        std::memset(buckets, 0, sizeof(Entry*) * capacity);

        // Rehash all entries into new buckets
        for (size_t i = 0; i < oldCap; ++i) {
            Entry* current = oldBuckets[i];
            while (current != nullptr) {
                Entry* nextNode = current->next;
                size_t newIndex = computeIndex(current->key, 0);
                current->next = buckets[newIndex];
                buckets[newIndex] = current;
                current = nextNode;
            }
            delete oldBuckets[i];  // Clean up old bucket nodes
        }
        delete[] oldBuckets;
    }

public:
    HashMap(size_t initialCapacity = 16, double loadFactor = 0.75) 
        : capacity(initialCapacity), count(0), maxLoadFactor(loadFactor) {
        buckets = new Entry*[capacity];
        std::memset(buckets, 0, sizeof(Entry*) * capacity);
    }

    ~HashMap() {
        // Properly deallocate all memory used by entries
        for (size_t i = 0; i < capacity; ++i) {
            Entry* curr = buckets[i];
            while (curr != nullptr) {
                Entry* temp = curr;
                curr = curr->next;
                delete temp;
            }
        }
        delete[] buckets;
    }

    // Insert a key-value pair into the map
    void put(void* key, void* value) {
        // Check if we need to grow the table
        if (static_cast<double>(count) / capacity > maxLoadFactor) {
            expandBuckets();
        }

        size_t idx = computeIndex(key, 0);

        // Check if key already exists
        Entry* probe = buckets[idx];
        while (probe != nullptr) {
            if (probe->key == key) {
                probe->value = value;  // Update existing value
                return;
            }
            probe = probe->next;
        }

        // Key not found - insert new entry
        addEntry(idx, key, value);
        ++count;
    }

    // Get value associated with key, or nullptr if not found
    void* get(void* key) {
        size_t idx = computeIndex(key, 0);
        Entry* cursor = buckets[idx];

        while (cursor != nullptr) {
            if (cursor->key == key) {
                return cursor->value;
            }
            cursor = cursor->next;
        }
        return nullptr;  // Key not present
    }

    // Remove entry by key and return whether removal succeeded
    bool erase(void* key) {
        size_t idx = computeIndex(key, 0);
        Entry* prev = nullptr;
        Entry* curr = buckets[idx];

        while (curr != nullptr) {
            if (curr->key == key) {
                if (prev == nullptr) {
                    buckets[idx] = curr->next;
                } else {
                    prev->next = curr->next;
                }
                delete curr;
                --count;
                return true;
            }
            prev = curr;
            curr = curr->next;
        }
        return false;  // Key not found
    }
};

int main() {
    // Demonstrate usage of the HashMap class
    HashMap map(8, 0.7);

    // Example operations
    int key1 = 10, val1 = 100;
    int key2 = 20, val2 = 200;

    map.put(&key1, &val1);
    map.put(&key2, &val2);

    void* result = map.get(&key1);
    if (result != nullptr) {
        std::cout << "Found value: " << *(static_cast<int*>(result)) << std::endl;
    }

    map.erase(&key1);
    result = map.get(&key1);
    std::cout << "After deletion, key1 exists: " << (result != nullptr ? "yes" : "no") << std::endl;

    return 0;
}

#include <iostream>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <atomic>

// Reimplementation of log flushing with modified control flow and variable names
void flushLogs() {
    std::unique_lock<std::recursive_mutex> guard(this->sync.mutex);

    // Skip if no logs to process
    if (this->sync.queue.empty()) {
        return;
    }

    // Capture current logs and clear the original queue
    auto bufferedLogs = this->sync.queue;
    this->sync.queue.clear();

    // Wait for any ongoing flush operation to complete
    auto isFlushComplete = [this] { 
        return !this->sync.inProgress.load(); 
    };
    this->sync.condition.wait(guard, isFlushComplete);

    // Mark that a new flush operation is starting
    this->sync.inProgress.store(true);
    guard.unlock(); // Unlock before performing I/O operations

    // Perform actual log output (simulated)
    for (const auto& entry : bufferedLogs) {
        std::cout << "Processing entry: " << entry << std::endl;
    }

    guard.lock(); // Reacquire lock for state update
    this->sync.inProgress.store(false); // Indicate flush completed
    this->sync.condition.notify_all(); // Wake up any waiting threads
}

#include <vector>

class CFill {
private:
    std::vector<std::vector<int>> matrix;
    int height;
    int width;

    void floodFillRecursive(int row, int col, int targetColor, int replacementColor) {
        // Boundary checks and color matching validation
        if (row < 0 || row >= height || col < 0 || col >= width || 
            matrix[row][col] != targetColor) {
            return;
        }

        // Apply new color
        matrix[row][col] = replacementColor;

        // Explore adjacent cells in four directions
        floodFillRecursive(row + 1, col, targetColor, replacementColor);
        floodFillRecursive(row - 1, col, targetColor, replacementColor);
        floodFillRecursive(row, col + 1, targetColor, replacementColor);
        floodFillRecursive(row, col - 1, targetColor, replacementColor);
    }

public:
    CFill() : height(10), width(10), 
              matrix(std::vector<std::vector<int>>(10, std::vector<int>(10, 0))) {
        // Initialize the grid with default dimensions and zero values
    }

    void performFloodFill(int startX, int startY, int newColorValue) {
        // Validate input coordinates
        if (startX < 0 || startX >= height || startY < 0 || startY >= width) {
            return;
        }

        int originalColor = matrix[startX][startY];

        // Avoid unnecessary processing if colors are identical
        if (originalColor == newColorValue) {
            return;
        }

        floodFillRecursive(startX, startY, originalColor, newColorValue);
    }
};

