// Enum to represent various statistics counters
enum class StatsType {
    error_msgs_sent__,
    unexpected_rx_msgs__,
    secure_tx_msgs__,
    total_stats_count__  // Total number of distinct statistics
};

class OutstationStats {
public:
    // Retrieve the current value of a specific statistic
    int fetchStat(StatsType stat) {
        switch (stat) {
            case StatsType::error_msgs_sent__:
                return errorsSent;
            case StatsType::unexpected_rx_msgs__:
                return unexpectedRx;
            case StatsType::secure_tx_msgs__:
                return secureTx;
            case StatsType::total_stats_count__:
                return static_cast<int>(StatsType::total_stats_count__);
        }
        return -1; // Should never reach here due to enum coverage
    }

    // Check if there's an APDU ready for processing
    bool checkAPDU() {
        return pendingAPDU;
    }

private:
    int errorsSent = 0;
    int unexpectedRx = 0;
    int secureTx = 0;
    bool pendingAPDU = false;
};

// Unit test function for OutstationStats
void validateOutstationStats() {
    OutstationStats stats;

    // Verify initial values of all statistics
    assert(stats.fetchStat(StatsType::error_msgs_sent__) == 0);
    assert(stats.fetchStat(StatsType::unexpected_rx_msgs__) == 0);
    assert(stats.fetchStat(StatsType::secure_tx_msgs__) == 0);
    assert(stats.fetchStat(StatsType::total_stats_count__) == 3);  // Confirm count matches expected

    // Verify no pending APDU initially
    assert(!stats.checkAPDU());
}

