#include <iostream>
#include <vector>
#include <algorithm>
#include <stack>

class StronglyConnectedComponents {
private:
    int vertexCount;
    std::vector<std::vector<int>> adjacencyList;
    std::vector<int> discoveryOrder;
    std::vector<int> minReachable;
    std::vector<bool> inStack;
    std::stack<int> nodeStack;
    int timestamp;
    std::vector<std::vector<int>> components;

    void explore(int currentNode) {
        nodeStack.push(currentNode);
        inStack[currentNode] = true;
        discoveryOrder[currentNode] = minReachable[currentNode] = timestamp++;

        for (int neighbor : adjacencyList[currentNode]) {
            if (discoveryOrder[neighbor] == -1) {
                explore(neighbor);
                minReachable[currentNode] = std::min(minReachable[currentNode], minReachable[neighbor]);
            } else if (inStack[neighbor]) {
                minReachable[currentNode] = std::min(minReachable[currentNode], discoveryOrder[neighbor]);
            }
        }

        if (discoveryOrder[currentNode] == minReachable[currentNode]) {
            std::vector<int> component;
            int poppedNode;
            do {
                poppedNode = nodeStack.top();
                nodeStack.pop();
                inStack[poppedNode] = false;
                component.push_back(poppedNode);
                minReachable[poppedNode] = discoveryOrder[currentNode];
            } while (poppedNode != currentNode);

            std::sort(component.begin(), component.end());
            components.push_back(component);
        }
    }

public:
    StronglyConnectedComponents(int n, const std::vector<std::vector<int>>& graph) 
        : vertexCount(n), 
          adjacencyList(graph),
          discoveryOrder(n, -1),
          minReachable(n),
          inStack(n, false),
          timestamp(0) {}

    std::vector<std::vector<int>> getComponents() {
        for (int i = 0; i < vertexCount; ++i) {
            if (discoveryOrder[i] == -1) {
                explore(i);
            }
        }

        std::sort(components.begin(), components.end());
        return components;
    }
};

