using U64 = unsigned long long;
using BitBoard = U64;

// Generate a 64-bit random value using multiple rand() calls with different shifts
BitBoard generateRandom64() {
    U64 part1 = static_cast<U64>(std::rand());
    U64 part2 = static_cast<U64>(std::rand()) << 15;
    U64 part3 = static_cast<U64>(std::rand()) << 30;
    U64 part4 = static_cast<U64>(std::rand()) << 45;
    U64 part5 = (static_cast<U64>(std::rand()) & 0xF) << 60;

    return part1 | part2 | part3 | part4 | part5;
}

// Generate a 64-bit random value with limited set bits by ANDing three random values
BitBoard generateSparseRandom64() {
    BitBoard a = generateRandom64();
    BitBoard b = generateRandom64();
    BitBoard c = generateRandom64();
    return a & b & c;
}

int main() {
    // Demonstrate the sparse random bitboard generator
    BitBoard sample = generateSparseRandom64();
    std::cout << "Sparse random bitboard: " << sample << std::endl;
