// Constants for control gains (defined as global constants)
const double k_linear = 1.0;
const double k_angular = 0.5;

void velocityCommandHandler(const geometry_msgs::Twist::ConstPtr& cmd) {
  // Extract linear and angular components from the incoming message
  double v_linear = cmd->linear.x;
  double v_angular = cmd->angular.z;

  // Compute combined control signal using weighted sum
  double output_signal = k_linear * v_linear + k_angular * v_angular;

  // Prepare and send control output
  static ros::Publisher pub_node = ros::NodeHandle().advertise<std_msgs::Float64>("/control_commands", 1);
  std_msgs::Float64 output_msg;
  output_msg.data = output_signal;
  pub_node.publish(output_msg);
}

int main(int argc, char** argv) {
  // Initialize ROS node with unique name
  ros::init(argc, argv, "motion_controller");
  ros::NodeHandle node;

  // Set up subscription to velocity command topic
  ros::Subscriber vel_sub = node.subscribe("/cmd_vel", 1, velocityCommandHandler);

  // Enter main event loop
  ros::spin();
  return 0;
}

