#include <iostream>
#include <string>
#include <vector>

// Represents a property of a class element
struct Property {
    std::string identifier;
    std::string dataType;
};

// Holds structural information about a class
struct ClassStructure {
    std::string className;
    bool nested;
    std::vector<Property> properties;
    std::vector<ClassStructure> nestedClasses;
};

// Manages collection and organization of class definitions
class TypeRegistry {
private:
    std::vector<ClassStructure> knownTypes;

public:
    // Add a top-level class definition
    void defineType(const std::string& typeName, bool isNested = false) {
        ClassStructure typeDef;
        typeDef.className = typeName;
        typeDef.nested = isNested;
        knownTypes.push_back(typeDef);
    }

    // Define a nested class inside an existing one
    void defineNestedType(const std::string& outerName, const std::string& innerName) {
        for (auto& type : knownTypes) {
            if (type.className == outerName) {
                ClassStructure nestedDef;
                nestedDef.className = innerName;
                nestedDef.nested = true;
                type.nestedClasses.push_back(nestedDef);
                return;
            }
        }
        std::cerr << "Warning: Outer type '" << outerName << "' not registered." << std::endl;
    }

    // Attach a property to a specific class
    void attachProperty(const std::string& typeName, const std::string& propName, const std::string& propType) {
        for (auto& type : knownTypes) {
            if (type.className == typeName) {
                Property newProp;
                newProp.identifier = propName;
                newProp.dataType = propType;
                type.properties.push_back(newProp);
                return;
            }
        }
        std::cerr << "Warning: Type '" << typeName << "' does not exist in registry." << std::endl;
    }

    // Additional utility methods could be added here
};

int main() {
    TypeRegistry registry;

    // Define the main type with full namespace path
    registry.defineType("domGlsl_surface_type::domGenerator::domName", true);

    // Define a nested structure within it
    registry.defineNestedType("domGlsl_surface_type::domGenerator::domName", "InnerClassName");

    // Attach a data member to the primary type
    registry.attachProperty("domGlsl_surface_type::domGenerator::domName", "_value", "xsNCName");

    return 0;
}

