// Matrix multiplication using MPI with row-based distribution
const int MATRIX_SIZE = 100; // Size of square matrices

int main(int argc, char *argv[]) {
    int process_rank, total_processes;
    MPI_Init(&argc, &argv);
    MPI_Comm_rank(MPI_COMM_WORLD, &process_rank);
    MPI_Comm_size(MPI_COMM_WORLD, &total_processes);

    // Validate command-line arguments
    if (argc != 2) {
        if (process_rank == 0) {
            std::cerr << "Usage: " << argv[0] << " <num_processes>" << std::endl;
        }
        MPI_Finalize();
        return 1;
    }

    int requested_processes = std::stoi(argv[1]);
    if (requested_processes < 1) {
        if (process_rank == 0) {
            std::cerr << "Number of processes should be at least 1." << std::endl;
        }
        MPI_Finalize();
        return 1;
    }

    // Initialize matrices on root process
    std::vector<std::vector<int>> matrix_A(MATRIX_SIZE, std::vector<int>(MATRIX_SIZE));
    std::vector<std::vector<int>> matrix_B(MATRIX_SIZE, std::vector<int>(MATRIX_SIZE));

    if (process_rank == 0) {
        // Read input matrices A and B from files
        // ... (file reading logic would go here)

        // Broadcast both matrices to all processes
        MPI_Bcast(&matrix_A[0][0], MATRIX_SIZE * MATRIX_SIZE, MPI_INT, 0, MPI_COMM_WORLD);
        MPI_Bcast(&matrix_B[0][0], MATRIX_SIZE * MATRIX_SIZE, MPI_INT, 0, MPI_COMM_WORLD);
    }

    // Calculate portion of result matrix for this process
    int rows_per_process = MATRIX_SIZE / requested_processes;
    std::vector<std::vector<int>> local_result(rows_per_process, std::vector<int>(MATRIX_SIZE, 0));

    // Perform matrix multiplication for assigned rows
    for (int row = process_rank * rows_per_process; 
         row < (process_rank + 1) * rows_per_process; 
         ++row) {
        for (int col = 0; col < MATRIX_SIZE; ++col) {
            int sum = 0;
            for (int k = 0; k < MATRIX_SIZE; ++k) {
                sum += matrix_A[row][k] * matrix_B[k][col];
            }
            local_result[row - process_rank * rows_per_process][col] = sum;
        }
    }

    // Collect results on root process
    std::vector<std::vector<int>> full_result(MATRIX_SIZE, std::vector<int>(MATRIX_SIZE));
    MPI_Gather(&local_result[0][0], rows_per_process * MATRIX_SIZE, MPI_INT,
               &full_result[0][0], rows_per_process * MATRIX_SIZE, MPI_INT, 0, MPI_COMM_WORLD);

    if (process_rank == 0) {
        // Write final matrix to output file
        std::ofstream output_file("result_matrix.txt");
        for (int i = 0; i < MATRIX_SIZE; ++i) {
            for (int j = 0; j < MATRIX_SIZE; ++j) {
                output_file << full_result[i][j] << " ";
            }
            output_file << "\n";
        }
        output_file.close();
    }

    MPI_Finalize();
    return 0;
}

