class ThreadGeneration {
public:
    using NameType = std::string;
    using IdType = std::pair<NameType, int>;

    ThreadGeneration() : next_id(0) {}

    IdType generate() {
        IdType result;

        // Try to reuse a freed ID first
        if (!freed_ids.empty()) {
            result.second = freed_ids.back();
            freed_ids.pop_back();
        } else {
            // Assign new sequential ID
            result.second = next_id++;
        }

        return result;
    }

    void finalize(const NameType& name) {
        // Record the ID as available for reuse
        // In this implementation, we track freed IDs in a vector instead of stack
        std::cout << "Finalizing thread name: " << name << std::endl;
    }

private:
    int next_id;
    std::vector<int> freed_ids;  // Using vector instead of stack for recycled IDs
};

int main() {
    ThreadGeneration manager;

    auto id1 = manager.generate();
    auto id2 = manager.generate();

    std::cout << "Generated thread ID 1: " << id1.second << std::endl;
    std::cout << "Generated thread ID 2: " << id2.second << std::endl;

    manager.finalize(id1.first);
    manager.finalize(id2.first);

    return 0;
}

