// Compute the average of response times using a while loop instead of range-based for
double CalculateAverageResponseTime(const std::vector<double>& responseTimes) {
    if (responseTimes.empty()) {
        return 0.0;
    }

    double total = 0.0;
    size_t index = 0;
    while (index < responseTimes.size()) {
        total += responseTimes[index];
        ++index;
    }
    return total / static_cast<double>(responseTimes.size());
}

