    std::string reverseWords(const std::string& input) {
        std::istringstream stream(input);
        std::string token;
        std::string output;

        while (stream >> token) {
            // Reverse the current word in place
            std::reverse(token.begin(), token.end());

            // Prepend to result with space if not first word
            if (output.empty()) {
                output = token;
            } else {
                output = token + " " + output;
            }
        }

        return output;
    }
