// Define terrain types using the same enum
enum TerrainType { GRASS, WATER, MOUNTAIN, DESERT };

// Modified map generation function with equivalent logic but different implementation
void generate_map(int cols, int rows, float fill_ratio, unsigned int seed_value, int total_types) {
    // Validate input parameters
    if (cols <= 0 || rows <= 0) {
        throw std::invalid_argument("Map dimensions must be positive integers.");
    }
    if (fill_ratio <= 0.0f || fill_ratio > 1.0f) {
        throw std::invalid_argument("Fill ratio must be in the range (0.0, 1.0].");
    }

    // Initialize random number generator with provided seed
    std::mt19937 rng(seed_value);
    std::uniform_real_distribution<float> dist(0.0f, 1.0f);

    // Create 2D grid initialized to GRASS
    std::vector<std::vector<TerrainType>> grid(rows, std::vector<TerrainType>(cols, GRASS));

    // Fill map based on density
    for (int row = 0; row < rows; ++row) {
        for (int col = 0; col < cols; ++col) {
            if (dist(rng) < fill_ratio) {
                // Use standard library random instead of rand()
                int type_index = std::rand() % total_types;
                grid[row][col] = static_cast<TerrainType>(type_index);
            }
        }
    }

    // Display the generated map
    for (int row = 0; row < rows; ++row) {
        for (int col = 0; col < cols; ++col) {
            std::cout << static_cast<int>(grid[row][col]) << " ";
        }
        std::cout << "\n";
    }
}

