// Template class for RGBA color representation
template <typename T>
struct RGBAColor {
    T r, g, b, a;
    RGBAColor(T red, T green, T blue, T alpha) 
        : r(red), g(green), b(blue), a(alpha) {}
};

// Type alias for unsigned integer-based RGBA color
using ColorU8 = RGBAColor<unsigned int>;

// Predefined colors using the new type
constexpr ColorU8 DARK{0, 0, 0, 255};   // Equivalent to BLACK
constexpr ColorU8 CRIMSON{255, 0, 0, 255}; // Equivalent to RED

// Function to linearly interpolate between two colors
ColorU8 mixColors(const ColorU8& first, const ColorU8& second, float progress) {
    // Compute weighted average for RGB components
    unsigned int mixed_r = static_cast<unsigned int>(first.r * (1.0f - progress) + second.r * progress);
    unsigned int mixed_g = static_cast<unsigned int>(first.g * (1.0f - progress) + second.g * progress);
    unsigned int mixed_b = static_cast<unsigned int>(first.b * (1.0f - progress) + second.b * progress);

    // Preserve alpha from the first color
    return ColorU8(mixed_r, mixed_g, mixed_b, first.a);
}

int main() {
    // Test blending with various interpolation values
    float steps[] = {0.2f, 0.5f, 0.8f};

    for (float t : steps) {
        ColorU8 result = mixColors(DARK, CRIMSON, t);
        std::cout << "Mixed color at t=" << t << ": (" 
                  << result.r << ", " << result.g << ", " 
                  << result.b << ", " << result.a << ")\n";
    }

    return 0;
}

