namespace intern {
    // Helper to compute sum using compile-time recursion with reversed index order
    template <typename T, std::size_t N, std::size_t I>
    struct Accumulator {
        static constexpr auto apply(const std::array<T, N>& a,
                                   const std::array<T, N>& b,
                                   auto op_transform,
                                   auto op_reduce) {
            return op_reduce(op_transform(a[I], b[I]),
                           Accumulator<T, N, I - 1>::apply(a, b, op_transform, op_reduce));
        }
    };

    // Base case: when index reaches 0
    template <typename T, std::size_t N>
    struct Accumulator<T, N, 0> {
        static constexpr auto apply(const std::array<T, N>& a,
                                   const std::array<T, N>& b,
                                   auto op_transform,
                                   auto op_reduce) {
            return op_reduce(op_transform(a[0], b[0]), T{});
        }
    };
}

// Main interface function for transform-reduce operation on arrays
template <typename T, std::size_t N, typename TransformOp, typename ReduceOp>
constexpr auto transform_reduce(const std::array<T, N>& first,
                               const std::array<T, N>& second,
                               TransformOp transform,
                               ReduceOp reduce) -> decltype(transform(first[0], second[0])) {
    static_assert(N > 0, "Array size must be at least 1");

    return intern::Accumulator<T, N, N - 1>::apply(first, second, transform, reduce);
}

