float LinuxParser::CpuUtilization(int pid) {
  // Get process-specific active jiffies and system uptime
  long processJiffies = LinuxParser::ActiveJiffies(pid);
  long systemUptime = LinuxParser::UpTime();

  // Convert jiffies to seconds using clock ticks per second
  const long clockTicksPerSecond = sysconf(_SC_CLK_TCK);
  double activeSeconds = static_cast<double>(processJiffies) / clockTicksPerSecond;

  // Compute how long the process has been running (in seconds)
  long processStartTime = LinuxParser::UpTime(pid);
  double processRuntime = static_cast<double>(systemUptime - (processStartTime / clockTicksPerSecond));

  // Avoid division by zero or invalid runtime
  if (processRuntime <= 0.0) {
    return 0.0f;
  }

  // Determine number of online CPUs for normalization
  int numCpus = sysconf(_SC_NPROCESSORS_ONLN);

  // Calculate CPU utilization as percentage: (active_time / runtime) / num_cpus * 100
  double cpuRatio = (activeSeconds / processRuntime) / numCpus;
  float utilization = static_cast<float>(cpuRatio * 100.0);

  return utilization;
}

