class TaskExecutor {
public:
    TaskExecutor() : completedCount(0) {}

    void addTask(const std::function<void()>& task) {
        std::unique_lock<std::mutex> lock(mtx);
        pendingTasks.push_back(task);
    }

    void runAll() {
        std::vector<std::thread> workerThreads;

        for (size_t idx = 0; idx < pendingTasks.size(); ++idx) {
            workerThreads.emplace_back([this, idx] {
                // Acquire lock to safely access the task and update counter
                std::unique_lock<std::mutex> lock(mtx);

                if (idx < pendingTasks.size()) {
                    pendingTasks[idx]();
                    ++completedCount;
                }

                // Notify waiting threads (if any)
                condVar.notify_one();
            });
        }

        // Wait for all threads to complete their work
        for (auto& thread : workerThreads) {
            thread.join();
        }
    }

    int getCompletedCount() const {
        return completedCount;
    }

private:
    std::vector<std::function<void()>> pendingTasks;
    mutable std::mutex mtx;
    std::condition_variable condVar;
    int completedCount;
};

int main() {
    TaskExecutor executor;

    // Add tasks to be executed
    executor.addTask([] { std::cout << "First task done" << std::endl; });
    executor.addTask([] { std::cout << "Second task done" << std::endl; });
    executor.addTask([] { std::cout << "Third task done" << std::endl; });

    // Execute all scheduled tasks concurrently
    executor.runAll();

    // Output the number of successfully completed tasks
    std::cout << "Number of completed tasks: " << executor.getCompletedCount() << std::endl;

    return 0;
}

