// Find the video mode with the highest resolution, refresh rate, and depth
std::tuple<int, int, int> getHighestResolutionMode(const std::vector<std::tuple<int, int, int>>& videoModes) {
    // Start with the first available mode as the initial candidate
    std::tuple<int, int, int> bestMode = videoModes[0];

    // Iterate through all modes to find the best one
    for (size_t idx = 1; idx < videoModes.size(); ++idx) {
        const auto& currentMode = videoModes[idx];

        // Extract values for comparison
        int currRes = std::get<0>(currentMode);
        int currRate = std::get<1>(currentMode);
        int currDepth = std::get<2>(currentMode);

        int bestRes = std::get<0>(bestMode);
        int bestRate = std::get<1>(bestMode);
        int bestDepth = std::get<2>(bestMode);

        // Compare: prefer higher resolution first, then refresh rate, then depth
        bool shouldUpdate = false;
        if (currRes > bestRes) {
            shouldUpdate = true;
        } else if (currRes == bestRes) {
            if (currRate > bestRate) {
                shouldUpdate = true;
            } else if (currRate == bestRate) {
                if (currDepth > bestDepth) {
                    shouldUpdate = true;
                }
            }
        }

        if (shouldUpdate) {
            bestMode = currentMode;
        }
    }

    return bestMode;
}

