// Interpolate between two points using linear interpolation logic
template <class Group, class Scalar>
Group interpolate(const Group& start, const Group& end, const Scalar& factor) {
    // Compute the relative transformation from start to end
    Group diff = start.inverse() * end;
    // Apply the interpolated transformation: start * (diff)^factor
    return start * Group::exp(diff.log() * factor);
}

