// Core logging mechanism
class SystemLogger {
private:
    Severity threshold;
    MessageHandler* handler;
public:
    SystemLogger(Severity minLevel, MessageHandler* dest) 
        : threshold(minLevel), handler(dest) {}

    void record(Severity level, const std::string& text) {
        if (level >= threshold) {
            std::time_t currentTime = std::time(nullptr);
            char buffer[64];
            std::strftime(buffer, sizeof(buffer), "%a %b %d %H:%M:%S %Y", std::localtime(&currentTime));
            std::string formattedTime(buffer);
            std::string fullMessage = "[" + formattedTime + "] " + text;
            handler->transmit(fullMessage);
        }
    }
};

