void TblDISTRICT_NEXT_O_ID::Key::print() {
    FILE* output = stdout;
    fprintf(output, "DISTRICT::Key { ");

    if (mVal == 0) {
        fprintf(output, "(NULL) ");
    } else {
        uint16_t offset = 0;

        // Extract and print TBLID (bits 0-15)
        uint16_t tblId = static_cast<uint16_t>(mVal & 0xFFFF);
        fprintf(output, "TBLID: %u, ", tblId);

        // Move to next field position
        offset += 16;

        // Extract and print D_W_ID (bits 16-31)
        uint16_t dWId = static_cast<uint16_t>((mVal >> offset) & 0xFFFF);
        fprintf(output, "D_W_ID: %u, ", dWId);

        // Move to next field position
        offset += 16;

        // Extract and print D_ID (bits 32-47)
        uint16_t dId = static_cast<uint16_t>((mVal >> offset) & 0xFFFF);
        fprintf(output, "D_ID: %u, ", dId);

        // Move to final field position
        offset += 16;

        // Extract and print T_ID (bits 48-63)
        uint16_t tId = static_cast<uint16_t>((mVal >> offset) & 0xFFFF);
        fprintf(output, "T_ID: %u", tId);
    }

    fprintf(output, " }\n");
