// Extracts nested elements from a given namespace string using regex pattern matching
std::vector<std::string> findNestedComponents(const std::string& nsPrefix) {
    std::vector<std::string> foundElements;

    // Construct regex to capture identifiers following the namespace prefix and "::"
    std::string pattern = "\\b" + nsPrefix + "::([a-zA-Z_][a-zA-Z0-9_]*)";
    std::regex elementRegex(pattern);

    // Code snippet containing namespace declarations with nested components
    std::string sourceCode = R"(
        namespace osquery {
            namespace detail {
                class Logger {
                    // Class implementation
                };
            }
            class Table {
                // Class implementation
            };
            namespace util {
                class Converter {
                    // Class implementation
                };
            }
        }
    )";

    // Perform regex search through the code snippet
    auto beginIter = sourceCode.cbegin();
    auto endIter = sourceCode.cend();
    std::smatch currentMatch;

    while (std::regex_search(beginIter, endIter, currentMatch, elementRegex)) {
        // Add the captured group (the nested element name) to the result vector
        foundElements.push_back(currentMatch[1].str());
        // Move iterator past the last match to continue searching
        beginIter = currentMatch.suffix().first;
    }

    return foundElements;
}

int main() {
    // Get the list of nested elements under the "osquery" namespace
    std::vector<std::string> extractedElements = findNestedComponents("osquery");

    // Print each extracted element on a separate line
    for (const auto& item : extractedElements) {
        std::cout << item << std::endl;
    }

    return 0;
}

