// Alternative implementation to compute the size of a range
template <typename Range>
typename qsboost::range_size<Range>::type computeRangeLength(const Range& rng) {
    using std::begin;
    using std::end;
    auto start_it = begin(rng);
    auto end_it = end(rng);
    typename qsboost::range_size<Range>::type count = 0;

    // Count elements by iterating manually instead of direct pointer arithmetic
    while (start_it != end_it) {
        ++count;
        ++start_it;
    }
    return count;
}

