// Class to manage DAS (Dynamic Adaptive System) charge levels
class DasController {
private:
    int max_charge_level_;
    int min_charge_level_;

public:
    // Constructor to set up the DAS thresholds
    DasController(int full_level, int low_level) 
        : max_charge_level_(full_level), min_charge_level_(low_level) {}

    // Set the DAS counter to its maximum capacity
    void chargeToMax(int& current_counter) const { 
        current_counter = max_charge_level_; 
    }

    // Adjust the DAS counter to the minimum operational level
    void adjustToMin(int& current_counter) const { 
        current_counter = min_charge_level_; 
    }

    // Completely discharge the DAS counter
    void dischargeFully(int& current_counter) const { 
        current_counter = 0; 
    }

    // Determine if the DAS counter has reached full capacity
    bool isAtFullCapacity(const int current_counter) const {
        return current_counter >= max_charge_level_;
    }

    // Determine if the DAS counter meets the minimum threshold
    bool meetsMinimumRequirement(const int current_counter) const {
        return current_counter >= min_charge_level_;
    }
};

int main() {
    // Create a controller instance with specified thresholds
    DasController das_controller(10, 3);
    int current_das_level = 0;

    // Charge to maximum and verify status
    das_controller.chargeToMax(current_das_level);
    std::cout << "DAS fully charged: " << das_controller.isAtFullCapacity(current_das_level) << std::endl;

    // Adjust to minimum level and verify status
    das_controller.adjustToMin(current_das_level);
    std::cout << "DAS softly charged: " << das_controller.meetsMinimumRequirement(current_das_level) << std::endl;

    // Fully discharge and verify status
    das_controller.dischargeFully(current_das_level);
    std::cout << "DAS fully charged: " << das_controller.isAtFullCapacity(current_das_level) << std::endl;

    return 0;
}

