#include <cmath>

// Minimum divisor to prevent division by zero in thickness calculation
const float MIN_DIVISOR_THRESHOLD = 0.0001f;

// Calculate sphere thickness at a given position using inverse matrix and squared thickness
float calculateSphereThickness(const float inverseMatrix[16], const float pointPos[3], float squaredThickness) {
    // Isolate translation components from the inverse matrix (last column)
    const float dx = inverseMatrix[12] + pointPos[0];
    const float dy = inverseMatrix[13] + pointPos[1];
    const float dz = inverseMatrix[14] + pointPos[2];

    // Compute squared distance with small offset to avoid division by zero
    const float distanceSquared = dx * dx + dy * dy + dz * dz + MIN_DIVISOR_THRESHOLD;

    // Return thickness scaled by inverse squared distance
    return squaredThickness / distanceSquared;
}

