enum class PinMode { INPUT, OUTPUT, PWM_MODE, SERVO_MODE };
enum class LogicLevel { HIGH_STATE, LOW_STATE };

class GpioController {
private:
    std::map<int, int> pinValues;
    std::function<void(int, int)> onPinChange;
public:
    void setPin(int pinNumber, int value, PinMode mode) {
        auto iter = this->pinValues.find(pinNumber);
        if (iter == this->pinValues.end()) return;

        switch (mode) {
            case PinMode::INPUT:
            case PinMode::OUTPUT:
                iter->second = (value != 0) ? static_cast<int>(LogicLevel::HIGH_STATE) : static_cast<int>(LogicLevel::LOW_STATE);
                break;
            case PinMode::PWM_MODE:
            case PinMode::SERVO_MODE:
                iter->second = value;
                break;
            default:
                return;
        }

        if (this->onPinChange) {
            this->onPinChange(pinNumber, iter->second);
        }
    }
};

int main() {
