// Validate if a string represents a valid Windows-style project path
bool isValidProjectPath(const std::string& path) {
    // Ensure the path is not empty
    if (path.empty()) {
        return false;
    }

    // Check for any whitespace characters in the path
    for (char c : path) {
        if (std::isspace(static_cast<unsigned char>(c))) {
            return false;
        }
    }

    // Verify drive letter format (e.g., C:)
    if (path.length() < 3 || !std::isalpha(static_cast<unsigned char>(path[0])) || path[1] != ':') {
        return false;
    }

    // Check that the third character is a valid separator
    if (path[2] != '\\' && path[2] != '/') {
        return false;
    }

    // Split the path into segments and validate each segment
    size_t start = 3;
    size_t pos = start;

    while (pos < path.length()) {
        // Find next separator
        while (pos < path.length() && path[pos] != '\\' && path[pos] != '/') {
            ++pos;
        }

        // Extract segment
        std::string segment = path.substr(start, pos - start);

        // Segment must not be empty
        if (segment.empty()) {
            return false;
        }

        // Each segment should contain only allowed characters: letters, digits, underscore, dot, hyphen
        for (char c : segment) {
            if (!std::isalnum(static_cast<unsigned char>(c)) && c != '_' && c != '.' && c != '-') {
                return false;
            }
        }

        // Move past the separator
        if (pos < path.length()) {
            ++pos;
            start = pos;
        }
    }

    // Must have at least two segments after the drive letter
    int segmentCount = 0;
    size_t tempStart = 3;
    size_t tempPos = tempStart;
    while (tempPos <= path.length()) {
        if (tempPos == path.length() || path[tempPos] == '\\' || path[tempPos] == '/') {
            if (tempPos > tempStart) {
                ++segmentCount;
            }
            tempStart = tempPos + 1;
        }
        ++tempPos;
    }

    return segmentCount >= 2;
}

int main() {
    // Test cases
    std::string path1 = "C:/Projects/MyProject";
    std::string path2 = "D:\\Documents\\Code\\Main.cpp";
    std::string path3 = "E:/Data Files/Report.docx";

    std::cout << std::boolalpha;
    std::cout << "Path 1 is valid: " << isValidProjectPath(path1) << std::endl;  // Output: true
    std::cout << "Path 2 is valid: " << isValidProjectPath(path2) << std::endl;  // Output: true
    std::cout << "Path 3 is valid: " << isValidProjectPath(path3) << std::endl;  // Output: false

    return 0;
}

