int main() {
    // Determine number of concurrent threads supported by the hardware
    unsigned int threadCount = std::thread::hardware_concurrency();

    // Initialize scene and image objects
    Scene scene;
    Image image;
    int imgWidth = image.getWidth();
    int imgHeight = image.getHeight();

    std::vector<std::thread> workerThreads;

    // Record start time using high-resolution clock
    auto startTime = std::chrono::high_resolution_clock::now();

    // Launch threads to process different vertical strips of the image
    for (unsigned int t = 0; t < threadCount; ++t) {
        int startY = (imgHeight * t) / threadCount;
        int endY = (imgHeight * (t + 1)) / threadCount;

        workerThreads.emplace_back(renderStrip, 
                                   std::ref(scene), 
                                   std::ref(image), 
                                   imgWidth, 
                                   imgHeight, 
                                   startY, 
                                   endY);
    }

    // Wait for all rendering threads to complete
    for (auto& worker : workerThreads) {
        worker.join();
    }

    // Calculate elapsed time
    auto endTime = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> elapsed = endTime - startTime;
    std::cout << "Rendering completed in " << elapsed.count() << " seconds." << std::endl;

    // Save result to file
    std::string outputFilename = "output_image.png";
