std::pair<std::string, std::string> processText(const std::vector<std::pair<int, std::string>>& commands) {
  std::string text1, text2;
  for (const auto& item : commands) {
    int action = item.first;
    const std::string& content = item.second;

    if (action == 1) {
      if (!text1.empty()) text1 += " ";
      text1 += content;
    } else if (action == 2) {
      if (!text2.empty()) text2 += " ";
      text2 += content;
    } else if (action == 3) {
      text1.clear();
    } else if (action == 4) {
      text2.clear();
    }
  }
  return std::make_pair(text1, text2);
}

