namespace {

// Validate that the given certificate is signed by the specified CA and is still valid
bool checkCertificateValidity(const net::x509_certificate& cert, const net::x509_certificate& issuerCert) {
    // Ensure the certificate hasn't expired yet
    if (cert.valid_expiry() <= net::x509_util::get_current_time()) {
        return false; // Certificate is no longer valid
    }

    // Prepare SSL info structure for signature verification
    net::ssl_info info;
    info.set_certificate(&cert);
    info.set_issuer_certificate(&issuerCert);

    // Perform signature verification using the trusted issuer
    return net::x509_util::check_signature_validity(&info);
}

