// Base class for screen objects
class Screen {
public:
    Screen(int identifier) : identifier(identifier) {}
    virtual void show() = 0;
    int getIdentifier() const { return identifier; }
protected:
    int identifier;
};

// Application manager that handles screens
class Application {
public:
    void registerScreen(Screen* screen) {
        registeredScreens[screen->getIdentifier()] = screen;
    }

    void deregisterScreen(int identifier) {
        auto iterator = registeredScreens.find(identifier);
        if (iterator != registeredScreens.end()) {
            delete iterator->second;
            registeredScreens.erase(iterator);
        }
    }

    void presentScreen(int identifier) {
        auto iterator = registeredScreens.find(identifier);
        if (iterator != registeredScreens.end()) {
            iterator->second->show();
        } else {
            std::cout << "Requested screen does not exist" << std::endl;
        }
    }

    ~Application() {
        for (auto& entry : registeredScreens) {
            delete entry.second;
        }
    }

private:
    std::unordered_map<int, Screen*> registeredScreens;
};

// Concrete implementation of a screen with text content
class TextScreen : public Screen {
public:
    TextScreen(int identifier, const std::string& message) 
        : Screen(identifier), message(message) {}

    void show() override {
        std::cout << "Display " << getIdentifier() << ": " << message << std::endl;
    }

private:
    std::string message;
};

