    Application app;

    // Register two example screens
    app.registerScreen(new TextScreen(101, "Hello, user!"));
    app.registerScreen(new TextScreen(102, "Configuration panel"));

    // Show both screens
    app.presentScreen(101);
    app.presentScreen(102);

    // Remove first screen and try to show it again
    app.deregisterScreen(101);
    app.presentScreen(101);

    return 0;
}

