// Using std::string instead of string alias for clarity
void DnsProvisionerVubercool::provisionHostname(const std::string &hostname, const cb_t& onDone)
{
    int attemptLimit = 3; // Maximum number of attempts including initial try
    int attemptCount = 0;

    // Lambda to handle provisioning with retry logic
    auto attemptProvision = [&](int remainingAttempts) {
        client_->Post("https://"s + config_.host + "/zone/" + hostname, 
            [this, hostname, onDone, remainingAttempts, attemptCount](Response& response) mutable {
                if (response.success) {
                    onDone(true); // Provisioning successful
                } else {
                    if (remainingAttempts > 0) {
                        // Schedule next retry
                        attemptProvision(remainingAttempts - 1);
                    } else {
                        LOG_ERROR << "Failed to provision hostname after " 
                                  << attemptCount + 1 << " attempts: " << hostname;
                        onDone(false); // Provisioning failed after all attempts
                    }
                }
            });
    };

    // Start with full retry count
    attemptProvision(attemptLimit - 1);
}

void DnsProvisionerVubercool::provisionWithRetries(const std::string &hostname, const cb_t& onDone, int maxRetries)
{
    int currentRetry = maxRetries;

    // Recursive lambda implementation
    std::function<void()> doProvision = [&]() {
        client_->Post("https://"s + config_.host + "/zone/" + hostname, 
            [this, hostname, onDone, currentRetry](Response& response) {
                if (response.success) {
                    onDone(true);
                } else {
                    if (currentRetry > 0) {
                        // Decrement and retry
                        currentRetry--;
                        doProvision();
                    } else {
                        LOG_ERROR << "DNS provisioning exhausted all retry attempts for: " << hostname;
                        onDone(false);
                    }
                }
            });
    };

    doProvision();
}

void DnsProvisionerVubercool::deleteHostname(const std::string &hostname, const cb_t& onDone)
{
    std::string url = "https://" + config_.host + "/zone/" + hostname;

    client_->Delete(url, [onDone](Response& response) {
        bool operationSuccess = response.success;
        onDone(operationSuccess);
    });
}

