class JavascriptSIMDUint8x16 {
public:
    static JavascriptSIMDUint8x16* New(const uint8_t* data, ScriptContext* ctx);
    const char16* GetFullBuiltinName(char16** buffer, const char16* funcName);
    JavascriptSIMDUint8x16* Copy(ScriptContext* ctx);

private:
    uint8_t value[16]; // assuming SIMD.Uint8x16 holds 16 bytes
    ScriptContext* context;

    JavascriptSIMDUint8x16(const uint8_t* src, void* recycler);
};

// Factory method: allocate new instance using recycler
JavascriptSIMDUint8x16* JavascriptSIMDUint8x16::New(const uint8_t* data, ScriptContext* ctx) {
    void* allocator = ctx->GetRecycler();
    return new (allocator) JavascriptSIMDUint8x16(data, allocator);
}

// Construct full builtin name by prepending prefix
const char16* JavascriptSIMDUint8x16::GetFullBuiltinName(char16** buffer, const char16* funcName) {
    if (!buffer || !*buffer) {
        return nullptr;
    }

    // Manually build the string instead of using swprintf_s
    const char16* prefix = _u("SIMD.Uint8x16.");
    int idx = 0;
    for (int i = 0; prefix[i] != u'\0'; ++i) {
        (*buffer)[idx++] = prefix[i];
    }
    for (int j = 0; funcName[j] != u'\0'; ++j) {
        (*buffer)[idx++] = funcName[j];
    }
    (*buffer)[idx] = u'\0';

    return *buffer;
}

// Create a duplicate of current instance
JavascriptSIMDUint8x16* JavascriptSIMDUint8x16::Copy(ScriptContext* ctx) {
    return JavascriptSIMDUint8x16::New(this->value, ctx);
}

