class Solution
{
public:
    std::vector<int> shortestToChar(std::string &s, char c)
    {
        int n = s.length();
        std::vector<int> distances(n, n);  // Initialize with maximum possible distance

        // First pass: left to right
        int lastPosition = -n;  // Start with an invalid position far before the string
        for (int index = 0; index < n; ++index)
        {
            if (s[index] == c)
                lastPosition = index;
            distances[index] = std::min(distances[index], std::abs(index - lastPosition));
        }

        // Second pass: right to left
        lastPosition = 2 * n;  // Start with an invalid position far after the string
        for (int index = n - 1; index >= 0; --index)
        {
            if (s[index] == c)
                lastPosition = index;
            distances[index] = std::min(distances[index], std::abs(index - lastPosition));
        }

        return distances;
    }
};

