// Update all active particles and remove expired ones
void ParticleEmitter::updateParticles(float deltaTime)
{
    // Process each particle by index
    for (size_t i = 0; i < particles.size(); )
    {
        // Update particle position using velocity and time step
        particles[i].x += particles[i].vx * deltaTime;
        particles[i].y += particles[i].vy * deltaTime;

        // Decrease remaining life time
        particles[i].lifetime -= deltaTime;

        // Check if particle has expired
        if (particles[i].lifetime <= 0.0f)
        {
            // Remove expired particle by swapping with last element and popping
            particles[i] = particles.back();
            particles.pop_back();
            // Don't increment i since we moved a new particle to position i
        }
        else
        {
            // Move to next particle only if current one wasn't removed
            ++i;
        }
    }
}

