void waterfill(const Grid& grid, int src_x, int src_y, Grid& water_grid) {
    // Initialize queue for breadth-first search
    std::queue<std::pair<int, int>> bfs_queue;
    bfs_queue.push(std::make_pair(src_x, src_y));

    // Mark starting position as filled
    water_grid[src_x][src_y] = Filled;

    // Define movement directions: up, down, left, right
    std::vector<std::pair<int, int>> move_dirs;
    move_dirs.push_back(std::make_pair(-1, 0)); // up
    move_dirs.push_back(std::make_pair(1, 0));  // down
    move_dirs.push_back(std::make_pair(0, -1)); // left
    move_dirs.push_back(std::make_pair(0, 1));  // right

    // Process all tiles in the queue
    while (!bfs_queue.empty()) {
        int current_x = bfs_queue.front().first;
        int current_y = bfs_queue.front().second;
        bfs_queue.pop();

        // Check each direction
        for (int i = 0; i < 4; ++i) {
            int neighbor_x = current_x + move_dirs[i].first;
            int neighbor_y = current_y + move_dirs[i].second;

            // Verify neighbor is within grid boundaries
            if (neighbor_x >= 0 && neighbor_x < static_cast<int>(grid.size()) &&
                neighbor_y >= 0 && neighbor_y < static_cast<int>(grid[0].size())) {

                // Only process if not already filled
                if (water_grid[neighbor_x][neighbor_y] != Filled) {
                    // Apply the specific waterfill condition
                    if (TileRoutines::waterfill_touch_right(grid[current_x][current_y], 
                                                           grid[neighbor_x][neighbor_y], 
                                                           tile)) {
                        // Mark as filled and add to queue for further processing
                        water_grid[neighbor_x][neighbor_y] = Filled;
                        bfs_queue.push(std::make_pair(neighbor_x, neighbor_y));
                    }
                }
            }
        }
    }
}

