// Function to detect and resolve index collisions for communication nodes
void DetectAndResolveCollisions(CoreGenNode *HW, std::unordered_map<CoreGenNode*, unsigned> &IdxMap) {
  // Traverse all child nodes using a while loop instead of for-loop
  unsigned childIndex = 0;
  unsigned totalChildren = HW->GetNumChild();

  while (childIndex < totalChildren) {
    CoreGenNode *currentNode = HW->GetChild(childIndex);

    // Check if the current node is a communication node and not yet indexed
    if (currentNode->GetType() == CGComm && IdxMap.count(currentNode) == 0) {
      // Generate a fresh unique identifier for this node
      unsigned freshIndex = CreateNewIdentifier(); // Alternative function name

      // Store the new mapping in the index table
      IdxMap[currentNode] = freshIndex;

      // Additional collision resolution steps could be performed here
    }

    childIndex++; // Move to next child node
  }
}

// Helper function to generate a new unique identifier
unsigned CreateNewIdentifier() {
  static unsigned idCounter = 1000; // Starting from a non-zero offset
  return idCounter++; // Return current value then increment
}

