#include <iostream>
#include <boost/safe_float.hpp>
#include <boost/safe_float/convenience.hpp>
#include <boost/safe_float/policy/check_addition_overflow.hpp>
#include <boost/safe_float/policy/check_addition_underflow.hpp>
#include <boost/safe_float/policy/check_addition_inexact.hpp>
#include <boost/safe_float/policy/check_addition_invalid_result.hpp>

template <typename FloatingPointType>
class FloatWrapper {
public:
    using SafeFloatType = boost::safe_float::safe_float<FloatingPointType>;

    FloatWrapper(FloatingPointType val) : safe_value_(val) {}

    // Method to perform addition with specified policies
    SafeFloatType performAddition(const SafeFloatType& other_policy, const SafeFloatType& operand) {
        return other_policy + operand;
    }

    // Display all error flags from a result
    void displayStatusFlags(const SafeFloatType& result) {
        auto err = result.error();
        std::cout << "Overflow: " << err.overflow() << std::endl;
        std::cout << "Underflow: " << err.underflow() << std::endl;
        std::cout << "Inexact: " << err.inexact() << std::endl;
        std::cout << "Invalid Result: " << err.invalid_result() << std::endl;
    }

private:
    SafeFloatType safe_value_;
};

int main() {
    // Create two safe float instances
    FloatWrapper<float> wrapper1(1.0f);
    FloatWrapper<float> wrapper2(2.0f);

    // Get underlying safe float values
    auto value1 = wrapper1.performAddition(wrapper1.safe_value_, 0.0f); // Extract by adding zero
    auto value2 = wrapper2.performAddition(wrapper2.safe_value_, 0.0f);

    // First operation: overflow and inexact checking policies
    auto result1 = value1 + value2;
    boost::safe_float::apply_policies(result1, 
                                      boost::safe_float::policy::check_addition_overflow{},
                                      boost::safe_float::policy::check_addition_inexact{});
    wrapper1.displayStatusFlags(result1);

    // Second operation: underflow and invalid result checking policies
    auto result2 = value1 + value2;
    boost::safe_float::apply_policies(result2,
                                      boost::safe_float::policy::check_addition_underflow{},
                                      boost::safe_float::policy::check_addition_invalid_result{});
    wrapper1.displayStatusFlags(result2);

    return 0;
}

