#include <iostream>
#include <cmath>

class ComplexNumber {
private:
    double realPart;
    double imaginaryPart;

public:
    // Default constructor
    ComplexNumber() : realPart(0.0), imaginaryPart(0.0) {}

    // Parameterized constructor
    ComplexNumber(double r, double i) : realPart(r), imaginaryPart(i) {}

    // Addition operator overloading
    ComplexNumber operator+(const ComplexNumber& rhs) const {
        return ComplexNumber(realPart + rhs.realPart, imaginaryPart + rhs.imaginaryPart);
    }

    // Subtraction operator overloading
    ComplexNumber operator-(const ComplexNumber& rhs) const {
        return ComplexNumber(realPart - rhs.realPart, imaginaryPart - rhs.imaginaryPart);
    }

    // Multiplication operator overloading
    ComplexNumber operator*(const ComplexNumber& rhs) const {
        return ComplexNumber(
            realPart * rhs.realPart - imaginaryPart * rhs.imaginaryPart,
            realPart * rhs.imaginaryPart + imaginaryPart * rhs.realPart
        );
    }

    // Division operator overloading
    ComplexNumber operator/(const ComplexNumber& rhs) const {
        double divisor = rhs.realPart * rhs.realPart + rhs.imaginaryPart * rhs.imaginaryPart;
        return ComplexNumber(
            (realPart * rhs.realPart + imaginaryPart * rhs.imaginaryPart) / divisor,
            (imaginaryPart * rhs.realPart - realPart * rhs.imaginaryPart) / divisor
        );
    }

    // Output stream insertion operator overloading
    friend std::ostream& operator<<(std::ostream& os, const ComplexNumber& num) {
        if (num.imaginaryPart >= 0) {
            os << num.realPart << " + " << num.imaginaryPart << "i";
        } else {
            os << num.realPart << " - " << std::abs(num.imaginaryPart) << "i";
        }
        return os;
    }

    // Method to compute the modulus of the complex number
    double modulus() const {
        return std::sqrt(realPart * realPart + imaginaryPart * imaginaryPart);
    }
};

int main() {
    ComplexNumber x;
    ComplexNumber y(8.0, 0.0);
    ComplexNumber z(0.0, -4.0);
    ComplexNumber w(29.99, 88.44);

    std::cout << "Complex number x: " << x << std::endl;
    std::cout << "Complex number y: " << y << std::endl;
    std::cout << "Complex number z: " << z << std::endl;
    std::cout << "Complex number w: " << w << std::endl;

    ComplexNumber resultSum = y + z;
    ComplexNumber resultDiff = y - z;
    ComplexNumber resultProd = y * z;
    ComplexNumber resultQuot = y / z;

    std::cout << "Sum of y and z: " << resultSum << std::endl;
    std::cout << "Difference of y and z: " << resultDiff << std::endl;
    std::cout << "Product of y and z: " << resultProd << std::endl;
    std::cout << "Quotient of y and z: " << resultQuot << std::endl;
    std::cout << "Modulus of y: " << y.modulus() << std::endl;

    return 0;
}

