namespace Debug {
    template<size_t CAPACITY>
    class StackAllocator {
    public:
        StackAllocator() : currentOffset_(0) {
            static_assert(CAPACITY > 0, "CAPACITY must be greater than 0");
            static_assert((CAPACITY & (CAPACITY - 1)) == 0, "CAPACITY must be a power of 2 for alignment");
            static_assert(CAPACITY <= UINT32_MAX, "CAPACITY must be within the range of uint32_t");
            static_assert(alignof(std::max_align_t) <= 4, "Alignment must be <= 4 for this example");
        }

        void* allocate(size_t sizeInBytes) {
            assert(currentOffset_ + sizeInBytes <= CAPACITY && "Out of memory");
            void* result = &storage_[currentOffset_];
            currentOffset_ += sizeInBytes;
            return result;
        }

        void deallocate(void* pointer, size_t sizeInBytes) {
            assert(sizeInBytes <= currentOffset_ && "Invalid deallocation size");
            assert(pointer == &storage_[currentOffset_ - sizeInBytes] && "Invalid deallocation pointer");
            currentOffset_ -= sizeInBytes;
        }

    private:
        alignas(std::max_align_t) uint8_t storage_[CAPACITY];
        size_t currentOffset_;
    };
}

int main() {
    Debug::StackAllocator<1024> allocator;

    // Allocate memory for an integer
    int* valuePtr = static_cast<int*>(allocator.allocate(sizeof(int)));
    *valuePtr = 42;

    // Deallocate the memory
    allocator.deallocate(valuePtr, sizeof(int));

    return 0;
}

