#include <map>

template <typename T>
struct codec_map {
    static bool decode(pb_istream_t *stream, const pb_field_t *field, void **arg) {
        auto *container = static_cast<std::map<typename T::KeyType, typename T::ValueType> *>(*arg);
        T entry;

        // Decode the protocol buffer message from the input stream
        if (!pb_decode(stream, field, &entry)) {
            return false;  // Indicate failure if decoding fails
        }

        // Insert the decoded key-value pair into the map
        container->emplace(entry.key, entry.value);
        return true;  // Indicate success after inserting the pair
    }
};

