struct GWBUF {
    char* data;
    size_t length;
};

// Function to create GWBUF object using different approach
GWBUF* make_gwbuf(const std::string& text) {
    // Allocate memory for GWBUF object
    GWBUF* buffer = new GWBUF;

    // Set length and allocate space for data (including null terminator)
    buffer->length = text.size();
    buffer->data = new char[buffer->length + 1];

    // Copy string content using manual character-by-character copy
    for (size_t i = 0; i <= buffer->length; ++i) {
        buffer->data[i] = text[i];
    }

    return buffer;
}

