// Process arithmetic operations for domain constraints
void process_operation(dom_t& dom, arith_operation_t op, varname_t x, varname_t y, varname_t z) {
    // Define constraint builder lambda for each operation type
    auto build_constraint = [&](const std::string& type) -> lincst_t {
        linexp_t expr;

        if (type == "add") {
            expr = linexp_t(var_t(y)) + linexp_t(var_t(z)) - var_t(x);
        } else if (type == "sub") {
            expr = linexp_t(var_t(y)) - linexp_t(var_t(z)) - var_t(x);
        } else if (type == "mul") {
            expr = linexp_t(var_t(y)) * linexp_t(var_t(z)) - var_t(x);
        } else {
            // Unsupported operation marker
            return lincst_t();
        }

        return lincst_t(expr, lincst_t::EQUALITY);
    };

    // Process based on operation type using early returns
    switch (op) {
        case ADDITION: {
            dom += build_constraint("add");
            return;
        }
        case SUBTRACTION: {
            dom += build_constraint("sub");
            return;
        }
        case MULTIPLICATION: {
            dom += build_constraint("mul");
            return;
        }
        case DIVISION: {
            // Division not supported in current linear expression framework
            // Implementation would require specialized handling
            return;
        }
        default: {
            // Non-arithmetic operations not handled in this implementation
            return;
        }
    }
}

