class TicketManager {
private:
    int availableTickets;
    HANDLE ticketSemaphore;
public:
    TicketManager(int initialCount) : availableTickets(initialCount) {
        ticketSemaphore = CreateSemaphore(NULL, initialCount, 0x7FFFFFFF, NULL);
    }

    void Restock(int amount) {
        availableTickets += amount;
        ReleaseSemaphore(ticketSemaphore, amount, NULL);
    }

    bool RequestTickets(int requestedAmount) {
        if (WaitForSingleObject(ticketSemaphore, 0) == WAIT_OBJECT_0) {
            if (availableTickets >= requestedAmount) {
                availableTickets -= requestedAmount;
                ReleaseSemaphore(ticketSemaphore, requestedAmount, NULL);
                return true;
            }
            ReleaseSemaphore(ticketSemaphore, 1, NULL);
        }
        return false;
    }
};

void SellerThread(TicketManager& manager, int quantity) {
    manager.Restock(quantity);
}

void BuyerThread(TicketManager& manager, int quantity) {
    if (manager.RequestTickets(quantity)) {
        std::cout << "Successfully bought: " << quantity << " tickets" << std::endl;
    } else {
        std::cout << "Insufficient tickets for request of " << quantity << std::endl;
    }
}

int main() {
    TicketManager manager(10);
    std::vector<std::thread> workerThreads;

    // Create seller and buyer threads in pairs
    for (int index = 0; index < 5; ++index) {
        workerThreads.emplace_back(SellerThread, std::ref(manager), 3);
        workerThreads.emplace_back(BuyerThread, std::ref(manager), 2);
    }

    // Wait for all threads to complete
    for (auto& thread : workerThreads) {
        thread.join();
    }

    // Check remaining tickets availability (using the boolean result)
    bool hasTickets = manager.RequestTickets(0);
    std::cout << "Ticket availability status: " << (hasTickets ? "Available" : "Not Available") << std::endl;

    return 0;
}

