class BufferHandler {
private:
    char* bufferAddress;
    size_t bufferSize;
public:
    BufferHandler(char* addr, size_t sz) : bufferAddress(addr), bufferSize(sz) {}

    void copyData(void* src, size_t startPos, size_t bytesToCopy) {
        // Check if the copy operation would exceed buffer boundaries
        if (startPos + bytesToCopy > bufferSize) {
            std::cerr << "Warning: Attempted copy exceeds available buffer space" << std::endl;
            return;
        }

        char* sourcePtr = static_cast<char*>(src);
        // Perform the memory copy operation
        std::memcpy(bufferAddress + startPos, sourcePtr, bytesToCopy);
    }
};

int main() {
    char storage[10];
    BufferHandler handler(storage, 10);
    char data[] = "Hello";

    // Copy 3 characters from 'data' starting at position 2 into 'storage' at offset 2
    handler.copyData(data, 2, 3);

    // Output the contents of the buffer
    for (int i = 0; i < 10; i++) {
        std::cout << storage[i];
    }

    return 0;
}

