// Expand bounding box minimum coordinates with tolerance for floating-point errors
int main() {
    // Simulating BoundingBox with pMin having x, y, z components
    struct Point3 {
        float x, y, z;
        Point3(float X = 0, float Y = 0, float Z = 0) : x(X), y(Y), z(Z) {}
    };

    struct BoundingBox {
        Point3 pMin;
        float Diagonal() const {
            return (pMax - pMin).Length();
        }
        Point3 pMax;
        float Length() const {
            return std::sqrt(x*x + y*y + z*z);
        }
    };

    // Initialize with sample values
    BoundingBox tb;
    tb.pMin = Point3(0.0f, 0.0f, 0.0f);
    tb.pMax = Point3(1.0f, 1.0f, 1.0f);

    // Compute adjustment factor based on diagonal length
    float diag = tb.Diagonal();
    float tolerance = 1e-4f * diag;

    // Apply tolerance to each coordinate of minimum point
    tb.pMin.x += tolerance;
    tb.pMin.y += tolerance;
    tb.pMin.z += tolerance;

    // Output result (simulating the adjusted bounding box)
    std::cout << "Adjusted pMin: (" 
              << tb.pMin.x << ", " 
              << tb.pMin.y << ", " 
              << tb.pMin.z << ")" << std::endl;

    return 0;
}

