class PerformanceTracker {
private:
    long long mAccumulatedDuration;
    unsigned long mSampleCount;
public:
    PerformanceTracker() : mAccumulatedDuration(0), mSampleCount(0) {}

    void RecordDuration(long long durationInMs) {
        mAccumulatedDuration += durationInMs;
        ++mSampleCount;
    }

    long long GetTotalDurationMS() const {
        return mAccumulatedDuration;
    }

    long long GetMeanDurationMS() const {
        return mSampleCount == 0 ? 0 : mAccumulatedDuration / static_cast<long long>(mSampleCount);
    }
};

