#include <algorithm>
#include <execution>

template <typename Policy, typename Iterator, typename T>
struct test_non_const_is_heap_until
{
    void operator()(Policy&& exec, Iterator iter)
    {
        // Use if constexpr instead of std::invoke_if for compile-time dispatch
        if constexpr (std::is_execution_policy_v<std::decay_t<Policy>>) {
            auto comp = get_comparator<T>();
            std::is_heap(std::forward<Policy>(exec), iter, non_const(comp));
        }
    }

private:
    // Helper function to create comparator
    template <typename U>
    static auto get_comparator() {
        return std::less<U>{};
    }

    // Make comparator non-const by value return
    template <typename Compare>
    static Compare non_const(Compare comp) {
        return comp;
    }
};

