// Test runner class that executes unit tests based on provided identifiers
class TestCaseExecutor {
public:
    // Constructor initializes the test function and its identifier
    TestCaseExecutor(void (*func)(void), const char* name) 
        : execute_test(func), test_identifier(name) {}

    // Execute a test case if the identifier matches or is empty (run all)
    int execute(const std::string& id, int& executed_count) {
        int failures = 0;

        // If no specific ID is given, run the test
        if (id.empty()) {
            execute_test();
            executed_count++;
        } 
        // If the ID matches the test's identifier, run the test
        else if (id == test_identifier) {
            execute_test();
            executed_count++;
