#include <QObject>
#include <QThread>
#include <QVector>
#include <complex>
#include <fftw3.h>
#include <vector>

class FFTProcessor : public QObject {
    Q_OBJECT
public:
    explicit FFTProcessor(int size) : m_size(size), m_thread(nullptr) {
        // Prepare internal buffers for FFTW
        m_realInput.resize(size);
        m_complexOutput.resize(size);

        // Create FFTW plan once during initialization
        m_plan = fftw_plan_dft_1d(
            size,
            reinterpret_cast<fftw_complex*>(m_realInput.data()),
            reinterpret_cast<fftw_complex*>(m_complexOutput.data()),
            FFTW_FORWARD,
            FFTW_ESTIMATE
        );
    }

    ~FFTProcessor() {
        if (m_plan) {
            fftw_destroy_plan(m_plan);
        }
        // Note: In real usage, ensure thread is stopped before destruction
    }

public slots:
    void handleNewData(const QVector<double>& rawData) {
        // Copy incoming data into internal buffer manually
        for (int idx = 0; idx < m_size && idx < rawData.size(); ++idx) {
            m_realInput[idx] = rawData[idx];
        }

        // Launch processing in dedicated thread
        m_thread = new QThread();
        this->moveToThread(m_thread);

        // Connect signals/slots for execution flow
        connect(m_thread, &QThread::started, this, &FFTProcessor::runTransform);
        connect(this, &FFTProcessor::processingDone, m_thread, &QThread::quit);
        connect(this, &FFTProcessor::processingDone, this, &FFTProcessor::cleanupAfterJob);
        connect(m_thread, &QThread::finished, m_thread, &QThread::deleteLater);
        m_thread->start();
    }

signals:
    void processingDone(const QVector<std::complex<double>>& transformedData);

private:
    int m_size;
    std::vector<double> m_realInput;
    std::vector<fftw_complex> m_complexOutput;
    fftw_plan m_plan;
    QThread* m_thread;

    void runTransform() {
        // Execute the actual FFT computation
        fftw_execute(m_plan);

        // Convert FFTW output to Qt-friendly format
        QVector<std::complex<double>> qtResult(m_size);
        for (int i = 0; i < m_size; ++i) {
            double re = m_complexOutput[i][0];
            double im = m_complexOutput[i][1];
            qtResult[i] = std::complex<double>(re, im);
        }

        // Emit result and signal completion
        emit processingDone(qtResult);
    }

    void cleanupAfterJob() {
        deleteLater(); // Safe deletion after thread finishes
    }
};

