template <typename T>
int64 UniqueAliOp(int64 out_idx) {
    // Verify type constraints using alternative approach
    static_assert(std::is_same_v<T, type>, "T must be of type 'type'");
    static_assert(std::is_same_v<decltype(out_idx), int64>, "out_idx must be of type 'int64'");

    // Alternative implementation: use conditional assignment instead of direct return
    int64 result = 0;
    if constexpr (std::is_same_v<T, type>) {
        result = out_idx;
    }

    return result;
}

