class BinarySearchTree {
private:
    struct TreeNode {
        int data;
        TreeNode* leftChild;
        TreeNode* rightChild;
        TreeNode(int val) : data(val), leftChild(nullptr), rightChild(nullptr) {}
    };
    TreeNode* headNode;

    // Recursive function to build tree from array representation
    TreeNode* buildTreeFromVector(const std::vector<int>& dataArray, int currentIndex) {
        if (currentIndex < dataArray.size()) {
            TreeNode* currentNode = new TreeNode(dataArray[currentIndex]);
            currentNode->leftChild = buildTreeFromVector(dataArray, 2 * currentIndex + 1);
            currentNode->rightChild = buildTreeFromVector(dataArray, 2 * currentIndex + 2);
            return currentNode;
        }
        return nullptr;
    }

public:
    // Initialize the tree with given values
    void initializeTree(const std::vector<int>& inputValues) {
        headNode = buildTreeFromVector(inputValues, 0);
    }

    // Conversion operator to extract root node's data as unsigned integer
    operator unsigned int() const {
        return static_cast<unsigned int>(headNode->data);
    }
};

int main() {
    BinarySearchTree bst;
    bst.initializeTree({1, 2, 3, 4, 5, 6, 7});
    unsigned int rootNodeData = bst; // Implicit conversion using overloaded operator
    std::cout << "Root node value: " << rootNodeData << std::endl;
    return 0;
}

