std::vector<std::pair<int, int>> manipulateVector(int M, int N) {
    std::vector<std::pair<int, int>> result;
    int counter = 2;  // Start from 2 since first increment happens before use

    // Generate M pairs using for loop instead of while
    for (int i = 0; i <= M; ++i) {
        result.push_back({counter, counter + 1});
        counter += 2;
    }

    // Add the special pair {1, next}
    result.push_back({1, counter});
    ++counter;

    // Check if exceeded N - return empty if so
    if (static_cast<int>(result.size()) > N) {
        return {};
    }

    // Pad with additional pairs to reach N elements
    while (static_cast<int>(result.size()) < N) {
        result.push_back({counter, counter + 1});
        counter += 2;
    }

    return result;
}

