namespace randest {
    template<typename OutputT>
    class data_provider {
    private:
        std::mt19937 generator;  // Mersenne Twister random number engine (renamed variable)
    public:
        data_provider(int seed_value) : generator(seed_value) {}

        std::vector<OutputT> produce(int quantity) {
            std::vector<OutputT> output;
            std::uniform_real_distribution<double> distribution(0.0, 1.0);  // Distribution for non-integer types

            int index = 0;
            while (index < quantity) {
                output.push_back(static_cast<OutputT>(distribution(generator)));
                ++index;
            }
            return output;
        }

        void reseed(int new_seed) {
            generator.seed(new_seed);
        }
    };
}

