#include <misaxx/ome/caches/misa_ome_tiff_cache.h>
#include <misaxx/ome/attachments/misa_ome_planes_location.h>
#include <misaxx/core/runtime/misa_parameter_registry.h>
#include <stdexcept>

// Compute the mean pixel intensity for a given image plane
double computeMeanIntensity(const misaxx::ome::misa_ome_tiff_cache &cache, int plane_idx) {
    // Extract the planes location metadata from the cache
    misaxx::ome::misa_ome_planes_location planes_info = cache.get_attachment<misaxx::ome::misa_ome_planes_location>();

    // Validate the provided plane index
    if (plane_idx < 0 || plane_idx >= static_cast<int>(planes_info.size())) {
        throw std::out_of_range("Plane index out of bounds");
    }

    // Access the pixel data for the requested plane
    const cv::Mat &image_plane = planes_info[plane_idx].get_plane();

    // Accumulate pixel intensities using row/column iteration
    double cumulative_intensity = 0.0;
    int row = 0;
    while (row < image_plane.rows) {
        int col = 0;
        while (col < image_plane.cols) {
            cumulative_intensity += image_plane.at<ushort>(row, col);
            ++col;
        }
        ++row;
    }

    // Derive the average by dividing total intensity by number of pixels
    double pixel_count = static_cast<double>(image_plane.rows * image_plane.cols);
    double mean_intensity = cumulative_intensity / pixel_count;
    return mean_intensity;
}

