        activeInstances++;
    }

    ~LiveCount() {
        activeInstances--;
    }
};

int LiveCount::activeInstances = 0;

int main() {
    std::map<int, LiveCount> container;

    // Create first object
    LiveCount obj1;
    assert(LiveCount::activeInstances == 1);

    // Insert temporary object into map (creates copy)
    container[42] = LiveCount();
    assert(LiveCount::activeInstances == 2);

    // Replace with another temporary (old one destroyed, new one added)
    container[42] = LiveCount();
    assert(LiveCount::activeInstances == 2);

    // Add two more objects in a scope block
    {
        LiveCount obj2;
        LiveCount obj3;
        assert(LiveCount::activeInstances == 4);
