#include <iostream>
#include <vector>
#include <climits>

class Graph {
private:
    struct Node {
        std::vector<std::pair<Node*, int>> edges;
    };

    std::vector<Node*> nodes;

public:
    void create_node() {
        nodes.push_back(new Node());
    }

    void connect(Node* source, Node* destination, int cost) {
        source->edges.emplace_back(destination, cost);
    }

    int minimum_cost(Node* start, Node* end) {
        // Implementation of Dijkstra's algorithm with minor structural changes
        size_t n = nodes.size();
        std::vector<int> distances(n, INT_MAX);
        size_t start_index = start - &nodes[0];
        size_t end_index = end - &nodes[0];

        distances[start_index] = 0;

        std::vector<bool> processed(n, false);

        for (size_t count = 0; count < n - 1; ++count) {
            int min_dist = INT_MAX;
            int u = -1;

            for (size_t i = 0; i < n; ++i) {
                if (!processed[i] && distances[i] < min_dist) {
                    min_dist = distances[i];
                    u = static_cast<int>(i);
                }
            }

            if (u == -1) break;

            processed[u] = true;

            for (const auto& edge : nodes[u]->edges) {
                Node* neighbor = edge.first;
                int weight = edge.second;
                size_t v = neighbor - &nodes[0];

                if (!processed[v] && 
                    distances[u] != INT_MAX && 
                    distances[u] + weight < distances[v]) {
                    distances[v] = distances[u] + weight;
                }
            }
        }

        return distances[end_index];
    }
};

int main() {
    Graph network;
    network.create_node(); // First node
    network.create_node(); // Second node

    // Connect first node to second with weight 5
    network.connect(network.nodes[0], network.nodes[1], 5);

    // Output the shortest path weight
    std::cout << "Minimum weight from first to second node: " 
              << network.minimum_cost(network.nodes[0], network.nodes[1]) << std::endl;

    return 0;
}

