namespace sycl = cl::sycl;

// Compute Black-Scholes option prices in parallel using SYCL and MKL RNG
void computeOptionPrices(const std::vector<double>& inputParams, int totalOptions, int paramsPerOption) {
    // Create SYCL queue targeting default device
    sycl::queue devQueue(sycl::default_selector{});

    // Allocate unified shared memory for parameters
    double* usmParams = sycl::malloc_shared<double>(totalOptions * paramsPerOption, devQueue);

    // Copy host data to device-accessible memory
    devQueue.memcpy(usmParams, inputParams.data(), 
                    static_cast<std::size_t>(totalOptions) * paramsPerOption * sizeof(double))
        .wait();

    // Validate memory type is USM shared
    auto memType = sycl::get_pointer_type(usmParams, devQueue.get_context());
