class CustomString {
private:
    char* data;

public:
    // Default constructor - initializes empty string
    CustomString() : data(nullptr) {
        data = new char[1];
        data[0] = '\0';
    }

    // Parameterized constructor - initializes with given C-string
    CustomString(const char* input) : data(nullptr) {
        size_t len = strlen(input);
        data = new char[len + 1];
        strcpy(data, input);
    }

    // Destructor - releases allocated memory
    ~CustomString() {
        delete[] data;
    }

    // Copy constructor for proper deep copy
    CustomString(const CustomString& other) : data(nullptr) {
        size_t len = strlen(other.data);
        data = new char[len + 1];
        strcpy(data, other.data);
    }

    // Assignment operator for proper deep copy
    CustomString& operator=(const CustomString& other) {
        if (this != &other) {
            delete[] data;
            size_t len = strlen(other.data);
            data = new char[len + 1];
            strcpy(data, other.data);
        }
        return *this;
    }

    // Method to get the length of the string
    size_t size() const {
        return strlen(data);
    }

    // Method to append another CustomString
    void concat(const CustomString& additional) {
        size_t current_len = strlen(data);
        size_t add_len = strlen(additional.data);

        char* buffer = new char[current_len + add_len + 1];
        strcpy(buffer, data);
        strcat(buffer, additional.data);

        delete[] data;
        data = buffer;
    }

    // Method to get the C-style string representation
    const char* c_str() const {
        return data;
    }
};

int main() {
    CustomString first;      // Default constructor
    CustomString second("Hello");   // Parameterized constructor
    CustomString third(" World");

    std::cout << "Initial string: '" << first.c_str() << "'" << std::endl;

    first.concat(second);     // Append "Hello"
    std::cout << "After appending 'Hello': '" << first.c_str() << "'" << std::endl;

    first.concat(third);      // Append " World"
    std::cout << "After appending ' World': '" << first.c_str() << "'" << std::endl;

    std::cout << "Length of the final string: " << first.size() << std::endl;
    return 0;
}

