        /**
         * @brief Applies square windowing to the input signal.
         * 
         * @param input The input signal.
         * @param windowSize The size of the square window.
         */
        void SquareWindowing(std::vector<double>& input, size_t windowSize) {
            // Ensure window size does not exceed the input signal length
            if (windowSize > input.size()) {
                windowSize = input.size();
            }

            // Apply square windowing: multiply by 1.0 within the window
            size_t index = 0;
            while (index < windowSize) {
                input[index] *= 1.0;  // Keep original value (square window effect)
                ++index;
            }
        }
