// Base class to prevent copying of derived classes
class NonCopyable {
protected:
    NonCopyable() = default;
    ~NonCopyable() = default;
private:
    NonCopyable(const NonCopyable&) = delete;
    NonCopyable& operator=(const NonCopyable&) = delete;
};

// Thread-safe critical section wrapper using std::mutex
class LockGuard {
public:
    void Acquire() {
        mtx.lock();
    }
    void Release() {
        mtx.unlock();
    }
private:
    std::mutex mtx;
};

// RAII-style lock manager for automatic locking/unlocking
class AutoLock : private NonCopyable {
public:
    explicit AutoLock(LockGuard& guard)
        : lg(guard) {
        lg.Acquire();
    }
    ~AutoLock() {
        lg.Release();
    }
private:
    LockGuard& lg;
};

// Generic thread-safe stack implementation
template <typename Item>
class ConcurrentStack {
public:
    void Push(const Item& item) {
        AutoLock guard(lock);
        storage.push(item);
    }

    bool Pop(Item& result) {
        AutoLock guard(lock);
        if (storage.empty()) {
            return false;
        }
        result = storage.top();
        storage.pop();
        return true;
    }

    bool Empty() const {
        AutoLock guard(lock);
        return storage.empty();
    }

private:
    std::stack<Item> storage;
    LockGuard lock;
};

#include <functional>

// Approximate the definite integral using the trapezoidal rule
double trapezoidalIntegral(std::function<double(double)> f, double a, double b, int N) {
    double stepSize = (b - a) / static_cast<double>(N);  // Width of each subinterval
    double accumulatedSum = 0.5 * (f(a) + f(b));  // Start with endpoints weighted by 0.5

    int currentIndex = 1;  // Start from the first interior point
    while (currentIndex < N) {
        double currentX = a + currentIndex * stepSize;  // Position within the interval
        accumulatedSum += f(currentX);  // Add interior point contribution
        currentIndex++;  // Move to next interior point
    }

    return stepSize * accumulatedSum;  // Multiply by step size for final result
}

