#include <iostream>

// Class to detect CPU capabilities via CPUID
class ProcessorFeatureChecker {
public:
    bool hasSSE2;
    bool hasAVX;
    bool hasAVX2;

    // Inline assembly wrapper for CPUID instruction
    void executeCpuid(int registers[4], int leaf) {
        __asm__ __volatile__(
            "cpuid"
            : "=a" (registers[0]), "=b" (registers[1]),
              "=c" (registers[2]), "=d" (registers[3])
            : "a" (leaf)
        );
    }

    // Analyze processor features and update status flags
    void analyzeCapabilities() {
        int regs[4];
        executeCpuid(regs, 0);
        int maxLeaf = regs[0];

        if (maxLeaf >= 1) {
            executeCpuid(regs, 1);
            // SSE2 available when bit 26 of EDX is set
            hasSSE2 = (regs[3] & (1 << 26)) != 0;
            // AVX available when bit 28 of ECX is set
            hasAVX = (regs[2] & (1 << 28)) != 0;
        }

        if (maxLeaf >= 7) {
            executeCpuid(regs, 7);
            // AVX2 available when bit 5 of EBX is set
            hasAVX2 = (regs[1] & (1 << 5)) != 0;
        }
    }
};

int main() {
    ProcessorFeatureChecker processorInfo;
    processorInfo.analyzeCapabilities();

    std::cout << "SSE2 support: " << (processorInfo.hasSSE2 ? "Yes" : "No") << std::endl;
    std::cout << "AVX support: " << (processorInfo.hasAVX ? "Yes" : "No") << std::endl;
    std::cout << "AVX2 support: " << (processorInfo.hasAVX2 ? "Yes" : "No") << std::endl;

    return 0;
}

