    }

    const std::vector<Edge<T>>& neighbors(size_t node) const {
        return adjList[node];
    }
};

// Update the priority queue with new shortest distance information
void updatePriority(const Edge<size_t>& edge, 
                   std::priority_queue<Edge<size_t>, 
                                      std::vector<Edge<size_t>>, 
                                      bool(*)(const Edge<size_t>&, const Edge<size_t>&)>& pq,
                   std::vector<size_t>& dist) {
    // This function would typically handle decrease-key operations
    // For simplicity, we're just pushing again (Dijkstra with duplicates allowed)
}

// Compute shortest path time using Dijkstra's algorithm
size_t computeTime(const WeightedGraph<size_t>& g, 
                  std::priority_queue<Edge<size_t>>& pq,
                  size_t startNode, 
                  size_t endNode) {
    std::vector<size_t> minTime(g.adjacencyList.size(), -1); // -1 means unvisited
    minTime[startNode] = 0;

    while (!pq.empty()) {
        auto current = pq.top();
        pq.pop();
        size_t u = current.target;

        if (u == endNode) {
            return minTime[u]; // Found shortest path to destination
        }

        for (const Edge<size_t>& e : g.neighbors(u)) {
            size_t alt = minTime[u] + e.cost;
            if (minTime[e.target] == static_cast<size_t>(-1) || alt < minTime[e.target]) {
                minTime[e.target] = alt;
                pq.push({e.target, alt});
            }
        }
    }

    return static_cast<size_t>(-1); // No path found
}

int main() {
    // Create a sample weighted directed graph
    WeightedGraph<size_t> network(5);
    network.connect(0, 1, 2);
    network.connect(0, 3, 5);
    network.connect(1, 2, 3);
    network.connect(3, 2, 1);
    network.connect(2, 4, 4);

    // Initialize priority queue for Dijkstra's algorithm
    std::priority_queue<Edge<size_t>> pq;
    pq.push({0, 0}); // Start from node 0 with distance 0

    size_t source = 0;
    size_t target = 4;

    size_t result = computeTime(network, pq, source, target);

    std::cout << "Minimum time to reach destination: " << result << std::endl;

    return 0;
}

#include <cmath>

class Point {
private:
    double xCoord, yCoord;
public:
    Point(double xVal, double yVal) : xCoord(xVal), yCoord(yVal) {}

    double distanceFrom(const Point& otherPoint) {
        double dx = otherPoint.xCoord - xCoord;
        double dy = otherPoint.yCoord - yCoord;
        return std::sqrt(dx * dx + dy * dy);
    }

    Point getMidpoint(const Point& otherPoint) {
        double midX = (xCoord + otherPoint.xCoord) / 2.0;
        double midY = (yCoord + otherPoint.yCoord) / 2.0;
        return Point(midX, midY);
    }

    bool isOnSameLine(const Point& pointA, const Point& pointB) {
        // Using cross product to check collinearity: (p2-p1) × (p3-p1) == 0
        double vector1X = pointA.xCoord - xCoord;
        double vector1Y = pointA.yCoord - yCoord;
        double vector2X = pointB.xCoord - xCoord;
        double vector2Y = pointB.yCoord - yCoord;
        return std::abs(vector1X * vector2Y - vector1Y * vector2X) < 1e-9;
    }
};

