    bgrChannels[1].convertTo(G_float, CV_32F);
    bgrChannels[2].convertTo(R_float, CV_32F);

    // Calculate intensity (I) as the average of RGB channels
    cv::Mat I_float = (R_float + G_float + B_float) * (1.0f / 3.0f);

    // Allocate memory for output matrices
    R = cvCreateMat(inputImage->height, inputImage->width, CV_32FC1);
    G = cvCreateMat(inputImage->height, inputImage->width, CV_32FC1);
    B = cvCreateMat(inputImage->height, inputImage->width, CV_32FC1);
    I = cvCreateMat(inputImage->height, inputImage->width, CV_32FC1);

    // Copy data from OpenCV Mat to CvMat using proper size calculation
    size_t totalBytes = inputMat.total() * sizeof(float);
    std::memcpy(R->data.fl, R_float.data, totalBytes);
    std::memcpy(G->data.fl, G_float.data, totalBytes);
    std::memcpy(B->data.fl, B_float.data, totalBytes);
    std::memcpy(I->data.fl, I_float.data, totalBytes);
}

