OFBool
DU_putShortDOElement(DcmItem *obj, DcmTagKey t, Uint16 us)
{
    OFCondition ec = EC_Normal;
    DcmElement *elem = nullptr;
    DcmTag tag(t);

    // Attempt to create a new DICOM element with the specified tag
    if (EC_Normal == (ec = newDicomElement(elem, tag))) {
        // If creation succeeded, set the element's value to the provided 16-bit unsigned integer
        if (EC_Normal == (ec = elem->putUint16(us))) {
            // If value setting succeeded, insert the element into the DICOM object
            if (EC_Normal == (ec = obj->insert(elem, OFTrue))) {
                return OFTrue;
            }
        }
    }

    // Return false if any operation failed
    return OFFalse;
}

