std::unique_ptr<IOBuf> encodeData(const std::vector<Header>& headers, const std::string& value, int headerTableSize);

// Modified version using while loop instead of for loop
std::vector<std::tuple<std::unique_ptr<IOBuf>, bool, TestStreamingCallback>> encodeFlightData(const std::vector<Header>& headers, const std::vector<std::string>& values, int headerTableSize) {
  std::vector<std::tuple<std::unique_ptr<IOBuf>, bool, TestStreamingCallback>> result;

  size_t index = 0;
  while (index < values.size()) {
    // Encode current flight data entry
    std::unique_ptr<IOBuf> buffer = encodeData(headers, values[index], headerTableSize);

    // Determine if encoding was successful
    bool isEncoded = (buffer != nullptr);

    // Create callback instance
    TestStreamingCallback handler;

    // Add the complete tuple to our result collection
    result.emplace_back(std::move(buffer), isEncoded, handler);

    // Move to next value
    ++index;
  }

  return result;
}

