// MazeGame class that inherits from SEngine to create a simple maze game
class MazeGame : public SEngine {
    std::vector<std::vector<char>> grid;  // Renamed from mazeGrid to grid
    int posX, posY;  // Renamed playerX and playerY to posX and posY

public:
    MazeGame() : grid(10, std::vector<char>(10, ' ')), posX(1), posY(1) {
        // Initialize the maze layout with obstacles and goal
        grid[3][3] = '#';  // Obstacle symbol changed from 'X' to '#'
        grid[8][8] = 'F';  // Goal symbol changed from 'G' to 'F' (for Finish)
    }

    void OnUserCreate() override {
        // Render initial state of the maze and player
        for (int row = 0; row < grid.size(); ++row) {
            for (int col = 0; col < grid[row].size(); ++col) {
                Draw(col, row, grid[row][col]);
            }
        }
        Draw(posX, posY, '@');  // Player symbol changed from 'P' to '@'
    }

    void OnUserUpdate(float dt) override {
        // Movement logic with boundary checks and obstacle collision
        if (GetKey(olc::Key::UP).bPressed && posY > 0 && grid[posY - 1][posX] != '#') {
            posY--;
        } else if (GetKey(olc::Key::DOWN).bPressed && posY < grid.size() - 1 && grid[posY + 1][posX] != '#') {
            posY++;
        } else if (GetKey(olc::Key::LEFT).bPressed && posX > 0 && grid[posY][posX - 1] != '#') {
            posX--;
        } else if (GetKey(olc::Key::RIGHT).bPressed && posX < grid[0].size() - 1 && grid[posY][posX + 1] != '#') {
            posX++;
        }

        // Check win condition
        if (grid[posY][posX] == 'F') {
            DrawString(20, 25, "Victory!", olc::GREEN);
            return;
        }

        // Check lose condition (collision with obstacle)
        if (grid[posY][posX] == '#') {
            DrawString(20, 25, "Crashed!", olc::RED);
            return;
        }

        // Redraw the entire screen each frame
        for (int r = 0; r < grid.size(); ++r) {
            for (int c = 0; c < grid[r].size(); ++c) {
                Draw(c, r, grid[r][c]);
            }
        }
        Draw(posX, posY, '@');
    }
};

int main() {
    MazeGame gameInstance;
    if (gameInstance.Construct(80, 50, 8, 8)) {
        gameInstance.Start();
    }
    return 0;
}

