#include <glslang/Public/ShaderLang.h>
#include <SPIRV/GlslangToSpv.h>
#include <SPIRV/SpvTools.h>
#include <SPIRV/disassemble.h>

bool compileGLSLToSPIRV(const std::string& sourceCode, std::vector<uint32_t>& outputSpirv) {
    glslang::InitializeProcess();

    glslang::TShader vertexShader(EShLangVertex);
    const char* shaderSourcePtr = sourceCode.c_str();
    vertexShader.setStrings(&shaderSourcePtr, 1);

    if (!vertexShader.parse(&glslang::DefaultTBuiltInResource, 100, false, EShMsgDefault)) {
        KG_LOGE(LM_RENDER, "[Compile GLSL to SPIR-V] Shader parsing failed\n%s", vertexShader.getInfoLog());
        glslang::FinalizeProcess();
        return false;
    }

    std::unique_ptr<glslang::TProgram> linker(new glslang::TProgram());
    linker->addShader(&vertexShader);

    if (!linker->link(EShMsgDefault)) {
        KG_LOGE(LM_RENDER, "[Compile GLSL to SPIR-V] Program linking failed\n%s", linker->getInfoLog());
        glslang::FinalizeProcess();
        return false;
    }

    spv::SpvBuildLogger messageLogger;
    glslang::GlslangToSpv(*linker->getIntermediate(EShLangVertex), outputSpirv, &messageLogger);

    std::string allMessages = messageLogger.getAllMessages();
    if (!allMessages.empty()) {
        KG_LOGW(LM_RENDER, "[Compile GLSL to SPIR-V] Warnings/Errors during SPIR-V generation:\n%s", allMessages.c_str());
    }

    glslang::FinalizeProcess();
    return true;
}

#include <type_traits>

namespace Rider {
    namespace Faiz {
        // Recursive disjunction implementation using type traits
        template <typename...>
        struct disjunction_impl : std::false_type {};

        template <typename First>
        struct disjunction_impl<First> : First {};

        template <typename First, typename... Rest>
        struct disjunction_impl<First, Rest...> 
            : std::conditional<First::value, First, disjunction_impl<Rest...>>::type {};

        // Alias template for convenience
        template <typename... Args>
        using disjunction = disjunction_impl<Args...>;

        // Compile-time assertion macro
        #define STATIC_REQUIRE(expr) static_assert(expr, "Static assertion failed")

        // Type aliases for clarity
        using true_type  = std::true_type;
        using false_type = std::false_type;

        // Test cases for the disjunction metafunction
        STATIC_REQUIRE(disjunction<true_type, false_type>::value);
        STATIC_REQUIRE(disjunction<false_type, true_type, false_type>::value);
        STATIC_REQUIRE(!disjunction<false_type, false_type, false_type>::value);
    }
}

