struct callable_signature<R(*)(P...)> {
    using type = R(*)(P...);
};

// Specialization for std::function objects
template <typename R, typename... P>
struct callable_signature<std::function<R(P...)>> {
    using type = R(*)(P...);
};

// General case: for lambdas and other callables with operator()
template <typename C>
struct callable_signature {
    // Extract the signature from the lambda's operator() member
    using type = typename callable_signature<
        decltype(&std::remove_reference_t<C>::operator())
    >::type;
};

// Utility function to transform a callable into a plain function pointer
template <typename Callable>
auto adapt_to_function(Callable&& c) 
    -> typename callable_signature<std::decay_t<Callable>>::type {
    return +c;  // Unary plus triggers conversion of stateless lambda to function pointer
}

// Demonstration program
int main() {
    // Create a simple lambda that adds two integers
    auto adder = [](int a, int b) { return a + b; };

    // Convert it to a function pointer
    auto fn_ptr = adapt_to_function(adder);

    // Use the resulting function pointer
    std::cout << fn_ptr(10, 20) << std::endl;  // Output: 30

    return 0;
}

