// Simulating a simplified version of the ProcessorManager class
class ProcessorManager {
private:
    std::unordered_map<int, std::function<void()>> processors;

public:
    void registerProcessor(int id, std::function<void()> func) {
        processors[id] = func;
    }

    void executeProcessor(int id) {
        auto it = processors.find(id);
        if (it != processors.end()) {
            it->second();
        } else {
            std::cout << "Error: Processor with ID " << id << " does not exist." << std::endl;
        }
    }

    bool unregisterProcessor(int id) {
        auto it = processors.find(id);
        if (it != processors.end()) {
            processors.erase(it);
            std::cout << "Processor with ID " << id << " unregistered successfully." << std::endl;
            return true;
        }
        return false;
    }
};

int main()
{
    ProcessorManager manager;
    // Registering processors using lambda functions
    manager.registerProcessor(1, []() { std::cout << "Executing Processor 1" << std::endl; });
    manager.registerProcessor(2, []() { std::cout << "Executing Processor 2" << std::endl; });

    // Execute registered processors
    manager.executeProcessor(1); // Output: Executing Processor 1
    manager.executeProcessor(2); // Output: Executing Processor 2

    // Unregister processor with ID 1
    manager.unregisterProcessor(1); // Output: Processor with ID 1 unregistered successfully.

    // Attempt to execute an already unregistered processor
    manager.executeProcessor(1); // Output: Error: Processor with ID 1 does not exist.

    return 0;
}

