// Process a module from the input stream
// Returns true if processing succeeded, false otherwise
bool ExtractAndHandleModule(const char*& currentPos, const char* finalLimit) {
    // Validate initial state
    if (currentPos == nullptr || finalLimit == nullptr || currentPos > finalLimit) {
        std::cerr << "Invalid input buffer pointers" << std::endl;
        return false;
    }

    // Check if we have at least one byte for size
    if (currentPos + 1 > finalLimit) {
        std::cerr << "Insufficient data to read module size" << std::endl;
        return false;
    }

    // Extract module length from first byte
    unsigned char moduleLength = static_cast<unsigned char>(*currentPos);

    // Verify we have enough data for the complete module
    if (currentPos + 1 + moduleLength > finalLimit) {
        std::cerr << "Invalid module size or incomplete module data" << std::endl;
        return false;
    }

    // Output module content (skip the size byte)
    std::cout << "Processing module: ";
    for (unsigned int idx = 0; idx < moduleLength; ++idx) {
        std::cout << *(currentPos + 1 + idx);
    }
    std::cout << std::endl;

    // Advance position past the size byte and module data
    currentPos += moduleLength + 1;
    return true;
}

int main() {
    const char* dataStream = "5Hello7World";
    const char* streamStart = dataStream;
    const char* streamEnd = dataStream + 12;  // Length of inputBuffer (including null terminator)

    // Process all modules until we reach the end
    while (streamStart < streamEnd) {
        if (!ExtractAndHandleModule(streamStart, streamEnd)) {
            std::cerr << "Error processing module" << std::endl;
            return 1;
        }
    }

    return 0;
}

