namespace {
struct CBC_HighLevelEncoder {
  static bool isNumeric(wchar_t ch) {
    return ch >= L'0' && ch <= L'9';
  }
};

std::optional<wchar_t> EncodeASCIIDigits(wchar_t firstDigit, wchar_t secondDigit) {
  if (!CBC_HighLevelEncoder::isNumeric(firstDigit) ||
      !CBC_HighLevelEncoder::isNumeric(secondDigit)) {
    return std::nullopt;  // Return empty optional if either digit is invalid
  }

  // Convert ASCII digits to numeric values and compute encoded character
  int value1 = firstDigit - L'0';
  int value2 = secondDigit - L'0';
  wchar_t resultChar = static_cast<wchar_t>(value1 * 10 + value2 + 130);
  return resultChar;
}
