class WordCounter {
private:
    std::map<std::string, int> wordCounts;

public:
    WordCounter(const std::string& filePath) {
        std::ifstream inputStream(filePath);
        if (inputStream.is_open()) {
            std::string token;
            while (inputStream >> token) {
                // Strip punctuation marks from the token
                auto newEnd = std::remove_if(token.begin(), token.end(), 
                                            [](unsigned char ch) { return std::ispunct(ch); });
                token.erase(newEnd, token.end());

                // Normalize to lowercase
                std::transform(token.begin(), token.end(), token.begin(),
                              [](unsigned char ch) { return std::tolower(ch); });

                if (!token.empty()) {
                    wordCounts[token]++;
                }
            }
            inputStream.close();
        } else {
            std::cerr << "Failed to open file: " << filePath << std::endl;
        }
    }

    int getCount(const std::string& searchTerm) const {
        std::string normalized = searchTerm;
        std::transform(normalized.begin(), normalized.end(), normalized.begin(),
                      [](unsigned char ch) { return std::tolower(ch); });

        auto it = wordCounts.find(normalized);
        return (it != wordCounts.end()) ? it->second : 0;
    }
};

int main() {
    WordCounter counter("input.txt");
    std::cout << "Occurrences of 'the': " << counter.getCount("the") << std::endl;
    std::cout << "Occurrences of 'fox': " << counter.getCount("fox") << std::endl;
    return 0;
}

