void HipServer::HandleReceive(const boost::system::error_code& error, std::size_t numBytes)
{
    // Check if no error occurred or if the error was due to oversized message
    if (error || error == boost::asio::error::message_size)
    {
        // Only proceed if there's no critical error (i.e., not a real failure)
        if (!error || error == boost::asio::error::message_size)
        {
            LOGGER_DEBUG("** PROCESSING INCOMING HIP MESSAGE **");
            try
            {
                // Store received data in a shared buffer
                m_context.m_buffer = std::make_shared<ByteBlock>
                    (m_buffer.begin(), m_buffer.begin() + static_cast<std::ptrdiff_t>(numBytes));

                LOGGER_DEBUG("Bytes received: ", *m_context.m_buffer);

                // Construct HIP packet from buffer
                m_context.m_packet = HipPacketPtr(new HipPacket(*m_context.m_buffer));

                // Extract network layer addresses
                std::string srcAddr = m_context.m_packet->GetSourceAddress();
                std::string dstAddr = m_context.m_packet->GetDestinationAddress();

                // Log key packet metadata
                LOGGER_DEBUG("Source IP: ", srcAddr);
                LOGGER_DEBUG("Destination IP: ", dstAddr);

                // Additional processing could be added here as needed
            }
            catch (const std::exception& ex)
            {
                LOGGER_ERROR("Failed to process incoming HIP packet: ", ex.what());
            }
        }
    }
}

