// Generate configuration strings by combining IPs, hostnames, and ports
std::vector<std::string> generateConfigurations(const std::vector<std::string>& ips, const std::vector<std::string>& hostnames, const std::vector<int>& ports) {
    std::vector<std::string> configurations;

    // Iterate through each combination using index-based loops
    for (size_t i = 0; i < ips.size(); ++i) {
        for (size_t h = 0; h < hostnames.size(); ++h) {
            for (size_t p = 0; p < ports.size(); ++p) {
                std::string config = "passport:" + ips[i] + ":" + hostnames[h] + ":" + base::IntToString(ports[p]) + ":";
                configurations.push_back(config);
            }
        }
    }

    return configurations;
}

