// Apply smoothing and geometric adjustments to the input image
void adjustImage(cv::Mat& img, float r_inner, float b_thick, float f_thick, int blur_ksize) {
    // Convert to grayscale for processing
    cv::Mat gray;
    cv::cvtColor(img, gray, cv::COLOR_BGR2GRAY);

    // Apply Gaussian smoothing with specified kernel size
    cv::Mat smoothed;
    int ksize = (blur_ksize % 2 == 0) ? blur_ksize + 1 : blur_ksize; // Ensure odd kernel size
    cv::GaussianBlur(gray, smoothed, cv::Size(ksize, ksize), 0);

    // Store result back into original matrix
    img = smoothed.clone();
}

int main(int argc, char* argv[]) {
    // Validate required command-line arguments
    if (argc < 10) {
        std::cerr << "Usage: program <image_path> <ground_w> <ground_h> ... <inner_radius> <base_thick> <front_thick> <smooth>" << std::endl;
        return -1;
    }

    // Extract parameters from command line
    std::string img_path = argv[1];
    int gw = std::atoi(argv[2]);
    int gh = std::atoi(argv[3]);
    // Parameters 4-5 unused in this version but present in signature
    float inner_r = std::atof(argv[6]);
    float base_t = std::atof(argv[7]);
    float front_t = std::atof(argv[8]);
    int smooth_val = std::atoi(argv[9]);

    // Load image
    cv::Mat src_img = cv::imread(img_path);
    if (src_img.empty()) {
        std::cerr << "Failed to load image: " << img_path << std::endl;
        return -1;
    }

    // Perform image adjustment
    adjustImage(src_img, inner_r, base_t, front_t, smooth_val);

