// Type alias for log identifiers
using LogIdentifier = int;

// Type alias for key-value log entries
using LogEntries = std::vector<std::pair<std::string, std::string>>;

// Abstract base class for logging functionality
class LogHandler {
public:
    virtual void record(LogIdentifier identifier, const LogEntries& entries) = 0;
};

// Concrete implementation of the logger
class SimpleLogger : public LogHandler {
private:
    std::unordered_map<LogIdentifier, LogEntries> storage;
public:
    void record(LogIdentifier identifier, const LogEntries& entries) override {
        storage[identifier] = entries;
    }

    // Access stored entries by log ID
    LogEntries retrieve(LogIdentifier identifier) const {
        auto it = storage.find(identifier);
        if (it != storage.end()) {
            return it->second;
        }
        return LogEntries{};
    }
};

int main() {
    // Instantiate the logger
    SimpleLogger logger;

    // Record some key-value data under log ID 1
    logger.record(1, {{"key1", "value1"}, {"key2", "value2"}});

    // Fetch and display the recorded entries
    LogEntries retrievedData = logger.retrieve(1);
    for (const auto& entry : retrievedData) {
        std::cout << entry.first << ": " << entry.second << '\n';
    }

    return 0;
}

