#include <set>

class Solution {
public:
    int smallestRepunitDivByK(int K) {
        // Early termination: numbers made of only 1s can never be divisible by 2 or 5
        if ((K & 1) == 0 || K % 5 == 0) {
            return -1;
        }

        // Using modular arithmetic to track remainders without storing all values
        int currentRemainder = 0;
        int digitCount = 0;

        // We only need to check up to K digits due to pigeonhole principle
        while (digitCount < K) {
            digitCount++;
            currentRemainder = (currentRemainder * 10 + 1) % K;

            if (currentRemainder == 0) {
                return digitCount;
            }
        }

        return -1;
    }
};

