// Custom timer-based callback handler class
class DeferredProcedureCall {
public:
    using Callback = void(*)(void*);

    DeferredProcedureCall(Callback callback, void* userData) 
        : callback_(callback), data_(userData), timerHandle_(0) {}

    void Schedule(unsigned int intervalMs) {
        timerHandle_ = SetTimer(nullptr, reinterpret_cast<UINT_PTR>(this), intervalMs, &DeferredProcedureCall::OnTimer);
    }

    void Stop() {
        if (timerHandle_ != 0) {
            KillTimer(nullptr, timerHandle_);
            timerHandle_ = 0;
        }
    }

    ~DeferredProcedureCall() {
        Stop();
    }

private:
    static VOID CALLBACK OnTimer(HWND, UINT, UINT_PTR timerId, DWORD) {
        DeferredProcedureCall* instance = reinterpret_cast<DeferredProcedureCall*>(timerId);
        if (instance && instance->callback_) {
            instance->callback_(instance->data_);
        }
    }

    Callback callback_;
    void* data_;
    UINT_PTR timerHandle_;
};

