// Storage for tracking client request statistics
std::unordered_map<std::string, std::pair<int, std::chrono::steady_clock::time_point>> clientRequestData;
std::mutex dataAccessMutex;

// Rate-limiting handler for the _v1_all endpoint
void _v1_all(const Rest::Request& request, Http::ResponseWriter response) {
    std::string clientAddress = request.address().host();

    // Thread-safe access to shared request data
    std::lock_guard<std::mutex> guard(dataAccessMutex);

    auto now = std::chrono::steady_clock::now();

    // Check if client exists and time window hasn't expired
    auto it = clientRequestData.find(clientAddress);
    bool isNewClient = (it == clientRequestData.end());
    bool windowExpired = !isNewClient && 
                        (now - it->second.second >= std::chrono::seconds(T));

    if (isNewClient || windowExpired) {
        // Initialize or reset counter for new window
        clientRequestData[clientAddress] = {1, now};
    } else {
        // Increment existing counter within same window
        ++(it->second.first);
    }

    // Check against rate limit threshold
    int currentCount = clientRequestData[clientAddress].first;
    if (currentCount > N) {
        response.headers().add<Http::Header::AccessControlAllowOrigin>("*");
        response.send(Pistache::Http::Code::Too_Many_Requests, "Rate limit exceeded");
    } else {
        // Continue normal request processing
        // ...
    }
}

