// Type III clone: Refactored logic using different control flow and variable names
void editFirstModbusRequestAndResponsePackets(PcapFileReaderDevice *reader, PcapFileWriterDevice *writer) {
    int requestFound = 0;
    int responseFound = 0;

    // Process each packet in sequence until end of file
    while (true) {
        RawPacket currentPacket;
        if (!reader->getNextPacket(currentPacket)) {
            break;  // No more packets available
        }

        // Convert raw data into structured Modbus format for analysis
        ModbusPacket parsedPacket = parseModbusPacket(currentPacket);

        // Handle first occurrence of request packet
        if (parsedPacket.type == ModbusPacketType::Request && requestFound == 0) {
            modifyModbusRequest(parsedPacket);
            requestFound = 1;
        }
        // Handle first occurrence of response packet
        else if (parsedPacket.type == ModbusPacketType::Response && responseFound == 0) {
            modifyModbusResponse(parsedPacket);
            responseFound = 1;
        }

        // Persist packet to output file regardless of modification status
        writer->writePacket(currentPacket);
    }

    // Validate that both required packet types were encountered
    if (requestFound == 0 || responseFound == 0) {
        EXIT_WITH_ERROR("No Modbus request or response packets found");
    }
}

