class UInt64Array {
private:
    std::vector<uint64_t> data;
public:
    // Constructor: initializes array with 64 elements, all set to the given value
    explicit UInt64Array(uint64_t val) : data(64, val) {}

    // Element-wise addition of two arrays
    UInt64Array sumWith(const UInt64Array& other) const {
        UInt64Array temp(0);
        for (size_t idx = 0; idx < 64; ++idx) {
            temp.data[idx] = data[idx] + other.data[idx];
        }
        return temp;
    }

    // Element-wise subtraction of two arrays
    UInt64Array diffFrom(const UInt64Array& other) const {
        UInt64Array temp(0);
        for (size_t idx = 0; idx < 64; ++idx) {
            temp.data[idx] = data[idx] - other.data[idx];
        }
        return temp;
    }

    // Element-wise multiplication of two arrays
    UInt64Array productWith(const UInt64Array& other) const {
        UInt64Array temp(0);
        for (size_t idx = 0; idx < 64; ++idx) {
            temp.data[idx] = data[idx] * other.data[idx];
        }
        return temp;
    }

    // Element-wise division of two arrays (with zero-check)
    UInt64Array quotientBy(const UInt64Array& other) const {
        UInt64Array temp(0);
        for (size_t idx = 0; idx < 64; ++idx) {
            if (other.data[idx] != 0) {
                temp.data[idx] = data[idx] / other.data[idx];
            } else {
                temp.data[idx] = std::numeric_limits<uint64_t>::max();
            }
        }
        return temp;
    }

    // Find smallest element in the array
    uint64_t smallest() const {
        return *std::min_element(data.begin(), data.end());
    }

    // Find largest element in the array
    uint64_t largest() const {
        return *std::max_element(data.begin(), data.end());
    }
};

int main() {
    UInt64Array arr1(5);
    UInt64Array arr2(3);

    UInt64Array resultSum = arr1.sumWith(arr2);
    UInt64Array resultDiff = arr1.diffFrom(arr2);
    UInt64Array resultProd = arr1.productWith(arr2);
    UInt64Array resultQuo = arr1.quotientBy(arr2);

    std::cout << "Smallest in sum: " << resultSum.smallest() << std::endl;
    std::cout << "Largest in sum: " << resultSum.largest() << std::endl;
    std::cout << "Smallest in diff: " << resultDiff.smallest() << std::endl;
    std::cout << "Largest in diff: " << resultDiff.largest() << std::endl;
    std::cout << "Smallest in product: " << resultProd.smallest() << std::endl;
    std::cout << "Largest in product: " << resultProd.largest() << std::endl;
    std::cout << "Smallest in quotient: " << resultQuo.smallest() << std::endl;
    std::cout << "Largest in quotient: " << resultQuo.largest() << std::endl;

    return 0;
}

#include <iostream>
#include <algorithm>

int64_t minCost(int64_t pricePerItem, int64_t pricePerPack, int64_t totalNeeded, int64_t itemsPerPack) {
    int64_t fullPacks = totalNeeded / itemsPerPack;
    int64_t remainingItems = totalNeeded % itemsPerPack;

    // Option 1: Buy packs for full packs, then buy remaining items individually
    int64_t option1 = remainingItems * pricePerItem + fullPacks * pricePerPack;

    // Option 2: Buy one more pack than needed (overbuy)
    int64_t option2 = (fullPacks + 1) * pricePerPack;

    return std::min(option1, option2);
}

int main() {
    std::cout << minCost(3, 5, 7, 2) << std::endl;  // Output: 26
    std::cout << minCost(2, 3, 5, 3) << std::endl;  // Output: 9
    return 0;
}

