struct Particle {
    int x, y;
    int dx, dy;

    void update() {
        x += dx;
        y += dy;
    }
};

int main(int argc, char** argv) {
    if (argc < 3) {
        std::cerr << "Usage: " << argv[0] << " <input_file> <num_steps>" << std::endl;
        return 1;
    }

    std::ifstream file(argv[1]);
    if (!file.is_open()) {
        std::cerr << "Error: Cannot open file '" << argv[1] << "'" << std::endl;
        return 1;
    }

    int steps = std::atoi(argv[2]);
    std::vector<Particle> particleList;
    std::string buffer;

    while (std::getline(file, buffer)) {
        if (buffer.find("particle") != std::string::npos) {
            Particle p;

            // Read position data
            std::getline(file, buffer);
            std::sscanf(buffer.c_str(), "  position: <%d, %d>", &p.x, &p.y);

            // Read velocity data
            std::getline(file, buffer);
            std::sscanf(buffer.c_str(), "  velocity: <%d, %d>", &p.dx, &p.dy);

            particleList.push_back(p);
        }
    }

    // Simulate movement for specified number of steps
    for (int step = 0; step < steps; ++step) {
        for (auto& p : particleList) {
            p.update();
        }
    }

    // Output final positions
    for (const auto& p : particleList) {
        std::cout << "Final position: (" << p.x << ", " << p.y << ")" << std::endl;
    }

    return 0;
}

