class FunctionRegistry {
private:
    std::unordered_map<std::string, std::function<void()>> registry;
public:
    void addFunction(const std::string& name, const std::function<void()>& func) {
        if (registry.count(name) > 0) {
            throw std::invalid_argument("Function named '" + name + "' already exists");
        }
        registry[name] = func;
    }

    template<typename... Args>
    void callFunction(const std::string& name, Args&&... args) {
        auto it = registry.find(name);
        if (it == registry.end()) {
            throw std::invalid_argument("Function named '" + name + "' not found");
        }
        it->second(std::forward<Args>(args)...);
    }
};

