#include <iostream>
#include <cmath>

// Abstract base class for geometric shapes
class GeometricFigure {
public:
    virtual double computeArea() = 0;
    virtual double computeBoundaryLength() = 0;
    virtual void showInformation() = 0;
};

// Circle implementation
class CircularRegion : public GeometricFigure {
private:
    double radialLength;
public:
    CircularRegion(double r) : radialLength(r) {}

    double computeArea() override {
        return M_PI * radialLength * radialLength;
    }

    double computeBoundaryLength() override {
        return 2 * M_PI * radialLength;
    }

    void showInformation() override {
        std::cout << "CircularRegion - Radius: " << radialLength 
                  << ", Area: " << computeArea() 
                  << ", Perimeter: " << computeBoundaryLength() << std::endl;
    }
};

// Rectangle implementation
class Quadrilateral : public GeometricFigure {
private:
    double extent, breadth;
public:
    Quadrilateral(double l, double w) : extent(l), breadth(w) {}

    double computeArea() override {
        return extent * breadth;
    }

    double computeBoundaryLength() override {
        return 2 * (extent + breadth);
    }

    void showInformation() override {
        std::cout << "Quadrilateral - Length: " << extent 
                  << ", Width: " << breadth 
                  << ", Area: " << computeArea() 
                  << ", Perimeter: " << computeBoundaryLength() << std::endl;
    }
};

// Triangle implementation using Heron's formula
class TriangularRegion : public GeometricFigure {
private:
    double edgeA, edgeB, edgeC;
public:
    TriangularRegion(double a, double b, double c) : edgeA(a), edgeB(b), edgeC(c) {}

    double computeArea() override {
        double semiPerimeter = (edgeA + edgeB + edgeC) / 2.0;
        return sqrt(semiPerimeter * (semiPerimeter - edgeA) * 
                    (semiPerimeter - edgeB) * (semiPerimeter - edgeC));
    }

    double computeBoundaryLength() override {
        return edgeA + edgeB + edgeC;
    }

    void showInformation() override {
        std::cout << "TriangularRegion - Side1: " << edgeA 
                  << ", Side2: " << edgeB 
                  << ", Side3: " << edgeC 
                  << ", Area: " << computeArea() 
                  << ", Perimeter: " << computeBoundaryLength() << std::endl;
    }
};

int main() {
    CircularRegion circle(5.0);
    Quadrilateral rectangle(4.0, 6.0);
    TriangularRegion triangle(3.0, 4.0, 5.0);

    circle.showInformation();
    rectangle.showInformation();
    triangle.showInformation();

    return 0;
}

