// Determine if the given string represents a valid single character literal
bool isValidCharLiteral(const std::string& text) {
    // A valid character literal must be exactly 3 characters long
    // and start and end with single quotes
    if (text.length() != 3 || text.front() != '\'' || text.back() != '\'') {
        return false;
    }

    // Extract the character between the quotes
    char innerChar = text[1];

    // Check if it's a printable ASCII character excluding the quote itself
    if (innerChar >= 32 && innerChar <= 126 && innerChar != '\'') {
        return true;
    }

    return false;
}

int main() {
    std::cout << std::boolalpha;
    std::cout << isValidCharLiteral("'x'") << std::endl;  // Output: true
    std::cout << isValidCharLiteral("'xy'") << std::endl; // Output: false
    return 0;
}

