// Validate input for L2 normalization operation
arm_compute::Status ClL2NormalizationWorkloadValidate(const arm_compute::TensorInfo& input)
{
    // Verify tensor properties required for L2 normalization
    if (!input.is_resizable())
    {
        return arm_compute::Status(arm_compute::ErrorCode::RUNTIME_ERROR, "Input tensor must be resizable");
    }

    // Ensure data layout is NHWC as required by this implementation
    if (input.data_layout() != arm_compute::DataLayout::NHWC)
    {
        return arm_compute::Status(arm_compute::ErrorCode::RUNTIME_ERROR, "Only NHWC data layout is supported");
    }

    // Confirm floating-point precision support
    auto dtype = input.data_type();
    if (dtype != arm_compute::DataType::F16 && dtype != arm_compute::DataType::F32)
    {
        return arm_compute::Status(arm_compute::ErrorCode::RUNTIME_ERROR, "Data type not supported: only FP16 and FP32 allowed");
    }

    // Validate spatial dimensions for 4D tensor with specific constraints
    const auto& shape = input.tensor_shape();
    if (shape.num_dimensions() != 4 || shape[2] != 1 || shape[3] != 1)
    {
        return arm_compute::Status(arm_compute::ErrorCode::RUNTIME_ERROR, "Expected 4D tensor with last two dimensions equal to 1");
    }

    // All validation checks passed successfully
    return arm_compute::Status::Success;
}

#include <iostream>

// Custom smart pointer implementation with reference counting
template <typename T>
class SmartPointer {
private:
    T* dataPtr;
    unsigned long* countPtr;

public:
    // Initialize with raw pointer
    explicit SmartPointer(T* p) : dataPtr(p), countPtr(new unsigned long(1)) {}

    // Copy constructor increments reference count
    SmartPointer(const SmartPointer& other) : dataPtr(other.dataPtr), countPtr(other.countPtr) {
        ++(*countPtr);
    }

    // Assignment operator handles self-assignment and decrements old reference count
    SmartPointer& operator=(const SmartPointer& other) {
        if (this != &other) {
            // Decrement current reference count and clean up if zero
            if (--(*countPtr) == 0) {
                delete dataPtr;
                delete countPtr;
            }
            // Copy from other
            dataPtr = other.dataPtr;
            countPtr = other.countPtr;
            ++(*countPtr);
        }
        return *this;
    }

    // Destructor decrements reference count and deletes resources when count reaches zero
    ~SmartPointer() {
        if (--(*countPtr) == 0) {
            delete dataPtr;
            delete countPtr;
        }
    }

    // Access the underlying pointer
    T* access() const {
        return dataPtr;
    }

    // Get current reference count
    unsigned long count() const {
        return *countPtr;
    }
};

int main() {
    // Create first smart pointer
    SmartPointer<int> sp1(new int(42));

    // Create second smart pointer by copying first
    SmartPointer<int> sp2 = sp1;

    // Output reference count after copying
    std::cout << "Reference count: " << sp1.count() << std::endl;

    // Create third smart pointer with different value
    SmartPointer<int> sp3(new int(100));

    // Assign third to second, which should decrement previous reference count
    sp2 = sp3;

    // Output final reference count
    std::cout << "Reference count: " << sp3.count() << std::endl;

    return 0;
}

