EToken Lexer::GetTokenType(std::string_view tokenText) const
{
    // Convert to std::string for comparison with m_ReservedTokens
    std::string tokenStr(tokenText);

    auto iter = std::find(m_ReservedTokens.begin(), m_ReservedTokens.end(), tokenStr);
    if (iter != m_ReservedTokens.end())
    {
        // Classify the token based on its content
        if (IsKeyword(tokenStr))
        {
            return EToken::Keyword;
        }
        else if (IsIdentifier(tokenStr))
        {
            return EToken::Identifier;
        }
        else if (IsOperator(tokenStr))
        {
            return EToken::Operator;
        }
        else if (IsLiteral(tokenStr))
        {
            return EToken::Literal;
        }
    }

    return EToken::Default; // Fallback for unrecognized tokens
}

// Helper methods to determine token types
bool Lexer::IsKeyword(const std::string& text) const
{
    static const std::vector<std::string> keywords = {
        "if", "else", "while", "for", "return", "int", "float", "bool", "char", "void"
    };
    return std::find(keywords.begin(), keywords.end(), text) != keywords.end();
}

bool Lexer::IsIdentifier(const std::string& text) const
{
    if (text.empty()) return false;

    // First character must be a letter or underscore
    if (!std::isalpha(text[0]) && text[0] != '_') return false;

    // Subsequent characters must be alphanumeric or underscore
    for (size_t i = 1; i < text.length(); ++i)
    {
        if (!std::isalnum(text[i]) && text[i] != '_') return false;
    }

    return true;
}

bool Lexer::IsOperator(const std::string& text) const
{
    static const std::vector<std::string> operators = {
        "+", "-", "*", "/", "=", "==", "!=", "<", ">", "<=", ">=", "&&", "||", "!", "&", "|", "^", "%", "<<", ">>"
    };
    return std::find(operators.begin(), operators.end(), text) != operators.end();
}

bool Lexer::IsLiteral(const std::string& text) const
{
    // Check for numeric literals (integer or floating-point)
    bool hasDigit = false;
    bool hasDecimal = false;

    for (size_t i = 0; i < text.length(); ++i)
    {
        if (std::isdigit(text[i]))
        {
            hasDigit = true;
        }
        else if (text[i] == '.' && !hasDecimal)
        {
            hasDecimal = true;
        }
        else
        {
            return false;
        }
    }

    return hasDigit;
}

