// Enum representing different data types
enum class DataType { None, Integer, Float, String, Boolean };

class TypeParser {
public:
    // Convert string to corresponding DataType enum value
    static DataType parseType(const std::string& typeName) {
        static const std::map<std::string, DataType> typeMapping = {
            {"None", DataType::None},
            {"Integer", DataType::Integer},
            {"Float", DataType::Float},
            {"String", DataType::String},
            {"Boolean", DataType::Boolean}
        };

        auto search = typeMapping.find(typeName);
        if (search != typeMapping.end()) {
            return search->second;
        }
        return DataType::None;
    }
};

