std::pair<void*, int> cast_graph::perform_cast(
    void* p, class_id source_type, class_id destination_type, class_id actual_type, void const* dynamic_object) const {
    // Check if the dynamic type matches the source type
    if (actual_type == source_type) {
        void* converted_ptr = dynamic_cast<void*>(p);
        // If conversion succeeds and target type matches dynamic type
        if (converted_ptr != nullptr && actual_type == destination_type) {
            return std::make_pair(converted_ptr, 1);  // Successful cast
        }
    }
    return std::make_pair(nullptr, 0);  // Cast operation failed
}

