// Neutral element for addition
template <typename T>
constexpr T neutral_element() {
    return T{};
}

template <typename T>
class fenwick_tree {
    std::vector<T> tree_data;

    // Combine two values using addition
    T combine_values(T left, T right) const {
        return left + right;
    }

public:
    // Constructor with size only
    explicit fenwick_tree(std::size_t size) 
        : tree_data(size + 2, neutral_element<T>()) {}

    // Constructor with initial value
    fenwick_tree(std::size_t size, T initial_value) 
        : tree_data(size + 2, neutral_element<T>()) {
        for (std::size_t i = 0; i < size; ++i) {
            increment(i, initial_value);
        }
    }

    // Add value to position idx
    void increment(int position, T value) {
        int index = position + 1;
        while (index < static_cast<int>(tree_data.size())) {
            tree_data[index] = combine_values(tree_data[index], value);
            index += (index & (-index));
        }
    }

    // Get prefix sum up to and including position idx
    T prefix_sum(int position) const {
        T result = neutral_element<T>();
        int index = position + 1;
        while (index > 0) {
            result = combine_values(result, tree_data[index]);
            index -= (index & (-index));
        }
        return result;
    }
};

