// Compute the average of scores after removing the lowest and highest values
int computeTrimmedAverage(std::vector<int> grades) {
    // If there are not enough scores to trim, return 0
    if (grades.size() <= 2) {
        return 0;
    }

    // Sort the grades in ascending order
    std::sort(grades.begin(), grades.end());

    // Manually accumulate the middle portion (excluding first and last)
    int total = 0;
    for (size_t i = 1; i < grades.size() - 1; ++i) {
        total += grades[i];
    }

    // Compute the count of remaining elements
    int count = static_cast<int>(grades.size()) - 2;

    // Calculate average with rounding to nearest integer
    double avgValue = static_cast<double>(total) / count;
    int result = static_cast<int>(std::round(avgValue));

    return result;
}

