// Helper function to get neighbors (assumed to be defined elsewhere)
std::vector<Node::Ptr> getNeighbors(const Node::Ptr& node);

std::vector<Node::Ptr> topologicalSort(const std::vector<Node::Ptr>& nodes) {
    std::vector<Node::Ptr> resultOrder;
    std::queue<Node::Ptr> pendingNodes;
    std::unordered_map<Node::Ptr, int> dependencyCount;

    // Initialize dependency counts for all nodes
    for (const auto& n : nodes) {
        dependencyCount[n] = 0;
    }

    // Compute how many dependencies each node has
    for (const auto& currentNode : nodes) {
        auto neighbors = getNeighbors(currentNode);
        for (const auto& dependentNode : neighbors) {
            dependencyCount[dependentNode]++;
        }
    }

    // Find all nodes with no dependencies
    for (const auto& nodePair : dependencyCount) {
        if (nodePair.second == 0) {
            pendingNodes.push(nodePair.first);
        }
    }

    // Process nodes in topological order
    while (!pendingNodes.empty()) {
        Node::Ptr current = pendingNodes.front();
        pendingNodes.pop();
        resultOrder.push_back(current);

        // Reduce dependency count for all dependents
        auto neighbors = getNeighbors(current);
        for (const auto& dependent : neighbors) {
            dependencyCount[dependent]--;
            if (dependencyCount[dependent] == 0) {
                pendingNodes.push(dependent);
            }
        }
    }

    return resultOrder;
}

