#include <iostream>

// Renders PSF font characters to the renderer with scaling
SDL_Texture* DrawPSF(const char* psfFilePath, SDL_Renderer* renderer, int scale) {
    // Load the PSF font data
    PSFFont psfFont = LoadPSF(psfFilePath);

    // Extract character dimensions from the font header
    int charWidth = psfFont.header->width;
    int charHeight = psfFont.header->height;

    // Create a temporary surface for rendering individual characters
    SDL_Surface* surface = SDL_CreateRGBSurface(0, charWidth, charHeight, 32, 0, 0, 0, 0);

    // Process each of the 256 possible characters
    for (int charIndex = 0; charIndex < 256; charIndex++) {
        // Retrieve the bitmap for the current character
        const uint8_t* charBitmap = psfFont.chars[charIndex];

        // Render pixel data for this character onto the surface
        for (int row = 0; row < charHeight; ++row) {
            for (int col = 0; col < charWidth; ++col) {
                // Extract bit corresponding to current pixel position
                uint8_t bitValue = (charBitmap[row] >> (7 - col)) & 1;

                // Set pixel color: white for set bits, black for unset
                uint32_t pixelColor = bitValue ? 0xFFFFFFFFu : 0x00000000u;

                // Write pixel to surface memory
                ((uint32_t*)surface->pixels)[row * charWidth + col] = pixelColor;
            }
        }

        // Generate texture from the updated surface
        SDL_Texture* charTexture = SDL_CreateTextureFromSurface(renderer, surface);

        // Define destination rectangle for scaled rendering
        SDL_Rect renderRect = {
            charIndex * charWidth * scale,
            0,
            charWidth * scale,
            charHeight * scale
        };

        // Copy texture to renderer at calculated position
        SDL_RenderCopy(renderer, charTexture, nullptr, &renderRect);

        // Release texture resources after rendering
        SDL_DestroyTexture(charTexture);
    }

    // Free the temporary surface after all characters are processed
    SDL_FreeSurface(surface);

    // Return null as no single texture is returned (original function had an issue)
    return nullptr;
}

