// Compute molecular mass based on elemental composition
double computeMolecularMass(std::istream& input) {
  // Dictionary mapping element symbols to their atomic masses
  std::map<std::string, double> elementMasses = {
    {"H", 1.008}, {"C", 12.011}, {"O", 15.999}, {"N", 14.007}
    // Extend with additional elements as required
  };

  double cumulativeMass = 0.0;
  char symbol;
  int quantity;

  // Parse the chemical formula from the stream
  while (input >> symbol >> quantity) {
    std::string element(symbol, 1);

    auto it = elementMasses.find(element);
    if (it != elementMasses.end()) {
      cumulativeMass += it->second * quantity;
    } else {
      std::cerr << "Error: Unknown element " << element << std::endl;
      return -1.0;  // Indicates an error due to unrecognized element
    }
  }

  return cumulativeMass;
}

