// Function to generate a random number from a normal distribution with mean 0 and standard deviation 1
double produceRandomDeviate(std::default_random_engine& rng) {
    std::normal_distribution<double> dist(0.0, 1.0);
    return dist(rng);
}

int main() {
    // Initialize simulation parameters
    double velocity = 0.0;   // Starting velocity
    double position = 0.0;   // Starting position
    double velNoiseStd = 0.1;   // Standard deviation for velocity noise
    double posNoiseStd = 0.2;   // Standard deviation for position noise
    int totalSteps = 100;       // Total number of simulation steps

    std::default_random_engine generator;  // Random number generator engine

    // Container for storing current state data
    std::map<std::string, double> record;

    int stepIndex = 0;      // Step counter for indexing
    double currentTime = 0.0;  // Simulation time variable

    // Perform the simulation loop
    for (int k = 0; k < totalSteps; ++k) {
        // Apply Euler-Maruyama updates with Gaussian noise
        velocity += velNoiseStd * produceRandomDeviate(generator);
        position += posNoiseStd * produceRandomDeviate(generator);

        // Populate the record map with current values
        record["Step"] = static_cast<double>(stepIndex++);
        record["Time"] = currentTime;
        record["Velocity"] = velocity;
        record["Position"] = position;
        record["PosNoiseStd"] = posNoiseStd;
        record["VelNoiseStd"] = velNoiseStd;

        // Output all recorded fields
        for (const auto& [key, value] : record) {
            std::cout << key << ": " << value << std::endl;
        }

        // Advance time and reset record for next iteration
        currentTime += 1.0;
        record.clear();
    }

    return 0;
}

