#include <cmath>

// Structure definitions (assumed based on usage)
struct Vector3 {
    float x, y, z;

    Vector3() : x(0), y(0), z(0) {}
    Vector3(float x, float y, float z) : x(x), y(y), z(z) {}
};

struct Ray {
    Vector3 origin;
    Vector3 dir;
};

const float EPSILON = 1e-6f;

// Helper function to compute dot product
float DotProduct(const Vector3& a, const Vector3& b) {
    return a.x * b.x + a.y * b.y + a.z * b.z;
}

// Helper function for vector subtraction
Vector3 Subtract(const Vector3& a, const Vector3& b) {
    return Vector3(a.x - b.x, a.y - b.y, a.z - b.z);
}

// Helper function for scalar multiplication of vector
Vector3 Multiply(const Vector3& v, float scalar) {
    return Vector3(v.x * scalar, v.y * scalar, v.z * scalar);
}

// Helper function for vector addition
Vector3 Add(const Vector3& a, const Vector3& b) {
    return Vector3(a.x + b.x, a.y + b.y, a.z + b.z);
}

// Calculate the intersection point between a ray and a plane
Vector3 FindRayPlaneIntersection(const Ray& ray, const Vector3& planePoint, const Vector3& planeNormal) {
    // Compute denominator: dot product of plane normal and ray direction
    float denom = DotProduct(planeNormal, ray.dir);

    // Check if ray is parallel or nearly parallel to the plane
    if (std::abs(denom) < EPSILON) {
        // No intersection possible in this case
        return Vector3(0.0f, 0.0f, 0.0f); // Using zero vector as special value
    }

    // Vector from ray origin to a point on the plane
    Vector3 originToPlane = Subtract(planePoint, ray.origin);

    // Compute parameter t for the intersection point
    float paramT = DotProduct(originToPlane, planeNormal) / denom;

    // Check if intersection occurs behind the ray origin
    if (paramT < 0.0f) {
        // Intersection point lies behind the ray origin
        return Vector3(0.0f, 0.0f, 0.0f); // Using zero vector as special value
    }

    // Compute actual intersection point using parametric equation of ray
    Vector3 intersection = Add(ray.origin, Multiply(ray.dir, paramT));
    return intersection;
}

