sge::parse::json::file_result sge::parse::json::parse_file(std::filesystem::path const &_path)
{
    std::ifstream input_stream(_path);

    if (!input_stream.good())
    {
        return sge::parse::json::file_result{
            std::nullopt,
            "Unable to access or open the specified file: " + _path.string()};
    }

    try
    {
        nlohmann::json document;
        input_stream >> document;

        // Verify that the stream is in a good state after parsing
        if (input_stream.fail() && !input_stream.eof())
        {
            return sge::parse::json::file_result{
                std::nullopt,
                "JSON parsing error encountered while reading file: " + _path.string()};
        }

        return sge::parse::json::file_result{document, std::nullopt};
    }
    catch (const nlohmann::json::exception &e)
    {
        return sge::parse::json::file_result{
            std::nullopt,
            "JSON structure invalid: " + std::string(e.what())};
    }
    catch (const std::exception &e)
    {
        return sge::parse::json::file_result{
            std::nullopt,
            "Unexpected error during file processing: " + std::string(e.what())};
    }
}

