#include <png.h>
#include <fstream>
#include <iostream>

void PNGImageReader::ReadImage(const std::string &filename, GrayscaleFloatImage &image) {
    // Open the PNG file for reading in binary mode
    std::ifstream input_stream(filename, std::ios::binary);
    if (!input_stream) {
        std::cerr << "Error: Unable to open file " << filename << std::endl;
        return;
    }

    // Initialize PNG read structure
    png_structp png_reader = png_create_read_struct(PNG_LIBPNG_VER_STRING, nullptr, nullptr, nullptr);
    if (!png_reader) {
        std::cerr << "Error: Failed to create PNG read struct" << std::endl;
        input_stream.close();
        return;
    }

    // Initialize PNG info structure
    png_infop png_info = png_create_info_struct(png_reader);
    if (!png_info) {
        std::cerr << "Error: Failed to create PNG info struct" << std::endl;
        png_destroy_read_struct(&png_reader, nullptr, nullptr);
        input_stream.close();
        return;
    }

    // Set up error recovery mechanism
    if (setjmp(png_jmpbuf(png_reader))) {
        std::cerr << "Error: An error occurred while reading the PNG file" << std::endl;
        png_destroy_read_struct(&png_reader, &png_info, nullptr);
        input_stream.close();
        return;
    }

    // Connect the file stream to libpng
    png_init_io(png_reader, input_stream);

    // Parse the PNG header information
    png_read_info(png_reader, png_info);
    int img_width  = png_get_image_width(png_reader, png_info);
    int img_height = png_get_image_height(png_reader, png_info);
    int depth      = png_get_bit_depth(png_reader, png_info);
    int color_mode = png_get_color_type(png_reader, png_info);

    // Validate image format: must be 8-bit grayscale
    if (color_mode != PNG_COLOR_TYPE_GRAY || depth != 8) {
        std::cerr << "Error: Unsupported PNG format. Only 8-bit grayscale images are supported." << std::endl;
        png_destroy_read_struct(&png_reader, &png_info, nullptr);
        input_stream.close();
        return;
    }

    // Prepare row pointers for image data
    png_bytep* row_pointers = new png_bytep[img_height];
    size_t row_bytes = png_get_rowbytes(png_reader, png_info);
    for (int row = 0; row < img_height; ++row) {
        row_pointers[row] = static_cast<png_bytep>(malloc(row_bytes));
    }

    // Read entire image into memory
    png_read_image(png_reader, row_pointers);

    // Convert pixel data to floating-point normalized values
    for (int y = 0; y < img_height; ++y) {
        for (int x = 0; x < img_width; ++x) {
            unsigned char pixel_val = row_pointers[y][x];
            float normalized = static_cast<float>(pixel_val) / 255.0f;
            image.SetPixelValue(x, y, normalized);
        }
    }

    // Release allocated resources
    for (int row = 0; row < img_height; ++row) {
        free(row_pointers[row]);
    }
    delete[] row_pointers;

    png_destroy_read_struct(&png_reader, &png_info, nullptr);
    input_stream.close();
}

#include <memory>

class CustomMemoryManager {
    std::unique_ptr<void, void(*)(void*)> managedResource;

    template<typename T>
    static void destroyObject(void* rawPtr) {
        if (rawPtr) {
            reinterpret_cast<T*>(rawPtr)->~T();
            ::operator delete(rawPtr);
        }
    }

public:
    template<typename T>
    T* obtain() {
        void* rawMem = ::operator new(sizeof(T));
        T* typedPtr = new (rawMem) T();
        managedResource.reset(typedPtr, destroyObject<T>);
        return typedPtr;
    }

    template<typename T>
    void release(T* objPtr) {
        if (objPtr && managedResource.get() == objPtr) {
            managedResource.reset();
        }
    }
};

