#include <memory>
#include <complex>

void nonlinear_step(std::shared_ptr<const DefaultExecutor> exec, int n,
                    double nonlinear_scale, double potential_scale,
                    double time_scale,
                    const gko::matrix::Dense<double>* potential,
                    gko::matrix::Dense<std::complex<double>>* ampl)
{
    using device_complex = device_type<std::complex<double>>;

    // Compute the combined scaling factor once
    double combined_factor = nonlinear_scale * potential_scale * time_scale;

    run_kernel(
        exec,
        GKO_KERNEL(auto i, auto j, auto n, auto combined_factor, auto potential, auto ampl) {
            // Calculate the updated amplitude value
            // Each element gets scaled by the product of all scale factors and the potential
            auto idx = i * n + j;  // Flattened index for 1D access
            ampl[idx] = combined_factor * potential[idx] * ampl[idx];
        });
}

#include <EGL/egl.h>

bool EGLContextX11::Create(const ContextParams& params, WindowHandle window, const EGLContextBase* shareContext)
{
    // Acquire EGL display connection
    EGLDisplay display = eglGetDisplay(EGL_DEFAULT_DISPLAY);
    if (display == nullptr) {
        // Error: Unable to obtain display
        return false;
    }

    // Set up EGL version information
    EGLint verMajor = 0, verMinor = 0;
    if (!eglInitialize(display, &verMajor, &verMinor)) {
        // Cleanup on failure
        eglTerminate(display);
        return false;
    }

    // Select appropriate EGL configuration
    EGLConfig chosenConfig = nullptr;
    EGLint configCount = 0;
    const EGLint requestedAttribs[] = {
        // Define desired attributes according to params
        // Examples: EGL_RED_SIZE, EGL_GREEN_SIZE, EGL_BLUE_SIZE, EGL_DEPTH_SIZE
        // ...
        EGL_NONE
    };
    if (!eglChooseConfig(display, requestedAttribs, &chosenConfig, 1, &configCount) || configCount == 0) {
        // Configuration selection failed
        eglTerminate(display);
        return false;
    }

    // Establish rendering context
    EGLContext newContext = eglCreateContext(display, chosenConfig, shareContext ? static_cast<EGLContext>(shareContext) : EGL_NO_CONTEXT, nullptr);
    if (newContext == EGL_NO_CONTEXT) {
        // Context creation unsuccessful
        eglTerminate(display);
        return false;
    }

    // Bind context to drawing surface
    if (!eglMakeCurrent(display, window, window, newContext)) {
        // Failed to make context current
        eglDestroyContext(display, newContext);
        eglTerminate(display);
        return false;
    }

    // All steps completed successfully
    return true;
}

