#include <cstddef>

// Helper function to extract comparison key from element
template<typename T>
static inline auto extractKey(const T& item) -> decltype(item.value) {
    return item.value;
}

// Lexicographical comparison using direct member access
static inline bool precedes(const _E& first, const _E& second) {
    return first.value < extractKey(second);
}

// Array comparison function with early termination
static inline int arrayCompare(const _E* arr1, const _E* arr2, size_t count) {
    for (size_t idx = 0; idx < count; ++idx) {
        if (precedes(arr1[idx], arr2[idx])) {
            return -1;
        }
        if (precedes(arr2[idx], arr1[idx])) {
            return 1;
        }
    }
    return 0;
}

#include <vector>
#include <Eigen/Dense>
#include <stdexcept>

// Compute the squared Euclidean distance between two vectors
double computeVectorDistanceSquared(const std::vector<double>& firstVec, const std::vector<double>& secondVec) {
    // Ensure both vectors have identical dimensions
    if (firstVec.size() != secondVec.size()) {
        throw std::invalid_argument("Vector dimensions must match");
    }

    // Wrap raw data into Eigen vector expressions for computation
    Eigen::Map<const Eigen::VectorXd> eigenFirst(firstVec.data(), firstVec.size());
    Eigen::Map<const Eigen::VectorXd> eigenSecond(secondVec.data(), secondVec.size());

    // Calculate squared distance via component-wise difference and norm
    double result = (eigenFirst - eigenSecond).array().pow(2).sum();
    return result;
}

#include <vector>
#include <folly/Range.h>
#include <folly/IOBuf.h>

// Derive cryptographic keys using HKDF expansion and extraction
std::pair<std::vector<uint8_t>, std::unique_ptr<folly::IOBuf>> deriveKeys(
    const std::vector<uint8_t>& sharedSecret,
    const std::vector<uint8_t>& psk,
    const SuiteId& suiteId,
    const KeyScheduleContext& keyScheduleContext,
    const Cipher& cipher) {

  // Perform HKDF-Extract with labeled salt and input key material
  std::vector<uint8_t> extractedSecret = hkdf->labeledExtract(
      folly::ByteRange(sharedSecret),
      folly::ByteRange(folly::StringPiece("secret")),
      folly::ByteRange(psk),
      suiteId.clone());

  // Expand the extracted secret to obtain the key material
  std::unique_ptr<folly::IOBuf> derivedKey = hkdf->labeledExpand(
      extractedSecret,
      folly::ByteRange(folly::StringPiece("key")),
      keyScheduleContext.clone(),
      cipher.keyLength());

  return std::make_pair(extractedSecret, std::move(derivedKey));
}

