#include <vector>
#include <algorithm>

// Compute the mean waiting time using non-preemptive scheduling logic
float computeMeanWaitingTime(const std::vector<std::pair<int, int>>& jobs) {
    int count = jobs.size();
    if (count == 0) return 0.0f;

    int cumulativeWait = 0;
    int timeline = 0;

    for (const auto& job : jobs) {
        int entryTime = job.first;
        int executionTime = job.second;

        // Determine how long this job waits before starting
        int idleDuration = (timeline > entryTime) ? (timeline - entryTime) : 0;
        cumulativeWait += idleDuration;

        // Advance timeline by the job's execution duration
        timeline += executionTime;

        // If the job arrived after the current timeline, adjust accordingly
        if (entryTime > timeline - executionTime) {
            timeline = entryTime + executionTime;
        }
    }

    // Derive the average waiting period across all jobs
    float result = static_cast<float>(cumulativeWait) / static_cast<float>(count);
    return result;
}

