      left[0] * right[1] - left[1] * right[0]);
}

#include <vector>
#include <algorithm>

class Solution {
public:
    int numRescueBoats(std::vector<int>& people, int limit) {
        // Sort the people array to apply greedy approach
        std::sort(people.begin(), people.end());

        int total_boats = 0;
        int lightest_index = 0;
        int heaviest_index = people.size() - 1;

        // Use two pointers: one at the lightest, one at the heaviest
        while (lightest_index <= heaviest_index) {
            // Always take the heaviest person on a boat
            total_boats++;

            // If the lightest and heaviest can share a boat, pair them
            if (people[lightest_index] + people[heaviest_index] <= limit) {
                lightest_index++;
            }

            // Move to the next heaviest person
            heaviest_index--;
        }

        return total_boats;
    }
};

