#include <vector>
#include <queue>
using namespace std;

class Solution {
public:
    vector<int> maxSlidingWindow(vector<int>& nums, int k) {
        vector<int> output;
        // Using a max-heap to store pairs of (value, index)
        priority_queue<pair<int, int>> heap;

        // Initialize the heap with the first window
        for (int idx = 0; idx < k; ++idx) {
            heap.push(make_pair(nums[idx], idx));
        }

        // Record maximum of the initial window
        output.push_back(heap.top().first);

        // Process remaining elements by sliding the window
        for (int right = k; right < nums.size(); ++right) {
            // Add new element entering the window
            heap.push(make_pair(nums[right], right));

            // Remove elements that are no longer in the current window
            while (!heap.empty() && heap.top().second <= right - k) {
                heap.pop();
            }

            // Append the current maximum value
            output.push_back(heap.top().first);
        }

        return output;
    }
};

