void exchange_positions(int pos1, int pos2) {
    if (pos1 == pos2) return;
    cout << "2 " << pos1 << " " << pos2 << endl;
    int response;
    cin >> response;
}

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, left1, left2;
    if (!(cin >> n >> left1 >> left2)) return 0;

    // 'chain_end' tracks how many initial positions form a consecutive value sequence
    int chain_end = 1;

    while (chain_end < n) {
        // Query total segments from current end to end of array
        int total_segments = get_segment_count(chain_end, n);
        // Query segments from next position to end of array
        int rest_segments = get_segment_count(chain_end + 1, n);

        if (total_segments <= rest_segments) {
            // There's a value adjacent to p[chain_end] in the remaining part
            int low = chain_end + 1;
            int high = n;

            // Binary search to locate the adjacent element
            while (low < high) {
                int mid = low + (high - low) / 2;
                int seg_left_part = get_segment_count(chain_end, mid);
                int seg_right_part = get_segment_count(chain_end + 1, mid);

                if (seg_left_part <= seg_right_part) {
                    high = mid;  // Adjacent element is in left half
                } else {
                    low = mid + 1;  // Adjacent element is in right half
                }
            }

            // Found the adjacent element at position 'low', move it next in chain
            exchange_positions(chain_end + 1, low);
            chain_end++;
        } else {
            // Current end has no adjacent neighbor in remaining part → it's an endpoint
            // Reverse the known chain so the other endpoint becomes the new end
            for (int i = 0; i < chain_end / 2; ++i) {
                exchange_positions(i + 1, chain_end - i);
            }
            // Loop continues with updated chain structure
        }
    }

    // Output final permutation (either ascending or descending)
    cout << "3";
    for (int idx = 1; idx <= n; ++idx) {
        cout << " " << idx;
    }
    cout << endl;

    return 0;
}

