TEST_CASE(test_issue_211_preset_gain_migration, "Config") {
    std::cout << "\nTest: Issue #211 Preset Gain Migration" << std::endl;
    const char* temp_ini = "migrate_legacy_preset.ini";
    std::string saved_path = Config::m_config_path;
    Config::m_config_path = temp_ini;

    // Step 1: Write legacy preset file (v0.7.66 format with 100Nm reference)
    {
        std::ofstream out_stream(temp_ini);
        out_stream << "[Preset:Legacy100Nm]\n";
        out_stream << "app_version=0.7.66\n";
        out_stream << "gain=1.0\n";
        out_stream << "max_torque_ref=100.0\n";
        out_stream.close();
    }

    // Step 2: Load presets and verify migration
    Config::LoadPresets();

    bool legacy_found = false;
    for (const auto& item : Config::presets) {
        if (item.name == "Legacy100Nm") {
            legacy_found = true;

            // After fix: wheelbase_max_nm should be 15.0f, gain scaled by 0.15
            float expected_gain = 0.15f;
            float tolerance = 0.001f;

            if (item.wheelbase_max_nm == 15.0f) {
                if (std::abs(item.gain - expected_gain) < tolerance) {
                    std::cout << "[PASS] Legacy preset gain migrated correctly: " << item.gain << std::endl;
                    g_tests_passed++;
                } else {
                    std::cout << "[FAIL] Legacy preset gain NOT migrated. Got: " << item.gain 
                              << " (Expected ~" << expected_gain << ")" << std::endl;
                    g_tests_failed++;
                }
            } else {
                std::cout << "[FAIL] Legacy preset wheelbase_max_nm NOT reset. Got: " << item.wheelbase_max_nm << std::endl;
                g_tests_failed++;
            }
            break;
        }
    }

    if (!legacy_found) {
        std::cout << "[FAIL] Legacy100Nm preset not found." << std::endl;
        g_tests_failed++;
    }

    // Cleanup
    Config::m_config_path = saved_path;
    std::remove(temp_ini);
}

