namespace Sass {

  // Helper to avoid repetition in simple return cases
  template<typename T>
  inline Value* identity_cast(T* ptr) {
    return static_cast<Value*>(ptr);
  }

  // Custom_Error is a valid value
  Value* To_Value::operator()(Custom_Error* e) {
    return identity_cast(e);
  }

  // Custom_Warning is a valid value
  Value* To_Value::operator()(Custom_Warning* w) {
    return identity_cast(w);
  }

  // Boolean is a valid value
  Value* To_Value::operator()(Boolean* b) {
    return identity_cast(b);
  }

  // Number is a valid value
  Value* To_Value::operator()(Number* n) {
    return identity_cast(n);
  }

  // Color types are valid values
  Value* To_Value::operator()(Color_RGBA* c) {
    return identity_cast(c);
  }

  Value* To_Value::operator()(Color_HSLA* c) {
    return identity_cast(c);
  }

  // String types are valid values
  Value* To_Value::operator()(String_Constant* s) {
    return identity_cast(s);
  }

  Value* To_Value::operator()(String_Quoted* s) {
    return identity_cast(s);
  }

  // List requires deep copy via recursion over elements
  Value* To_Value::operator()(List* l) {
    List_Obj new_list = SASS_MEMORY_NEW(List,
                                        l->pstate(),
                                        l->length(),
                                        l->separator(),
                                        l->is_arglist(),
                                        l->is_bracketed());

    size_t idx = 0;
    size_t total = l->length();
    while (idx < total) {
      Value* transformed = (*l)[idx]->perform(this);
      new_list->append(transformed);
      ++idx;
    }

    return new_list.detach();
  }

  // Map is a valid value
  Value* To_Value::operator()(Map* m) {
    return identity_cast(m);
  }

  // Null is a valid value
  Value* To_Value::operator()(Null* n) {
    return identity_cast(n);
  }

  // Function is a valid value
  Value* To_Value::operator()(Function* f) {
    return identity_cast(f);
  }

  // Argument returns its value if unnamed; otherwise null
  Value* To_Value::operator()(Argument* arg) {
    if (!arg->name().empty()) {
      return nullptr;
    }
    return arg->value()->perform(this);
  }

  // SelectorList converts to quoted string
  Value* To_Value::operator()(SelectorList* s) {
    std::string str_repr = s->to_string(ctx.c_options);
    return SASS_MEMORY_NEW(String_Quoted, s->pstate(), str_repr);
  }

  // Binary_Expression converts to quoted string
  Value* To_Value::operator()(Binary_Expression* expr) {
    std::string str_repr = expr->to_string(ctx.c_options);
    return SASS_MEMORY_NEW(String_Quoted, expr->pstate(), str_repr);
  }

}

