// Read lines from a file using getline, handling potential buffer overflow
void demoGetline() {
    std::ifstream inputFile("users.txt");
    if (!inputFile) return;

    const int BUFFER_CAPACITY = 128;
    char lineBuffer[BUFFER_CAPACITY];

    // Continuously read lines until end of file or error
    while (inputFile.getline(lineBuffer, BUFFER_CAPACITY)) {
        std::cout << "Read line: " << lineBuffer << std::endl;
    }

    // Check for failure due to extraction issues (e.g., line too long)
    if (inputFile.fail() && !inputFile.eof()) {
        std::cout << "ERROR: Found a line longer than the buffer." << std::endl;
        // Reset stream state flags to allow further operations
        inputFile.clear();
    }
}

#include "ncl.h"
/*----------------------------------------------------------------------------------------------------------------------
|	Constructs a NxsException by copying the provided message string and capturing parsing location details:
|	line number, column number, and file position at the time of the exception.
*/
NxsException::NxsException(
  const NxsString &message,	/* user-facing error description */
  file_pos position,		/* current position in the input file */
  long lineNum,				/* current line index in the file */
  long colNum)				/* current column index on the line */
	{
	pos   = position;
	line  = lineNum;
	col   = colNum;
	msg   = message;
	}
/*----------------------------------------------------------------------------------------------------------------------
|	Initializes a NxsException using an error message and contextual data extracted from a NxsToken object,
|	which holds information about the most recently processed token and its location.
*/
NxsException::NxsException(
  const NxsString &description,	/* descriptive error text */
  const NxsToken &token)		/* token instance containing last parsed element and metadata */
	{
	msg     = description; 
	pos     = token.GetFilePosition();
	line    = token.GetFileLine();
	col     = token.GetFileColumn();
  	}

