// Plugin that removes specific sections matching patterns like .text.f1* and .rela.text.f1*
class DLL_A_EXPORT DiscardSections : public SectionIteratorPlugin {
public:
  DiscardSections() : SectionIteratorPlugin("DISCARD") {}

  void Init(std::string /* Options */) override {}

  void processSection(eld::plugin::Section S) override {
    std::string secName = S.getName();
    if (S.matchPattern(".text.f1*") || S.matchPattern(".rela.text.f1*")) {
      m_Sections.push_back(S);
    }
  }

  Status Run(bool /* Trace */) override {
    for (auto &section : m_Sections) {
      std::cout << "Discarding section " << section.getName() << "\n";
      section.markAsDiscarded();
    }
    return Plugin::Status::SUCCESS;
  }

  void Destroy() override {}
  uint32_t GetLastError() override { return 0; }
  std::string GetLastErrorAsString() override { return "SUCCESS"; }
  std::string GetName() override { return "DISCARD"; }

private:
  std::vector<eld::plugin::Section> m_Sections;
};

// Alternative plugin using SectionMatcherPlugin base class with same functionality
class DLL_A_EXPORT DiscardViaMatcher : public SectionMatcherPlugin {
public:
  DiscardViaMatcher() : SectionMatcherPlugin("DiscardPluginSM") {}

  void Init(std::string /* Options */) override {}

  void processSection(eld::plugin::Section S) override {
    std::string secName = S.getName();
