private:
  std::vector<eld::plugin::Section> m_Sections;
};

// Global registry of plugins
std::unordered_map<std::string, Plugin *> PluginRegistry;

extern "C" {
bool DLL_A_EXPORT RegisterAll() {
  PluginRegistry["DISCARD"] = new DiscardSections{};
  PluginRegistry["DiscardPluginSM"] = new DiscardViaMatcher{};
  return true;
}

PluginBase *DLL_A_EXPORT getPlugin(const char *name) {
  return PluginRegistry[name];
}

void DLL_A_EXPORT Cleanup() {
  for (auto &entry : PluginRegistry) {
    if (entry.second) {
      delete entry.second;
    }
  }
  PluginRegistry.clear();
}
