// Random character generation setup
std::mt19937 rngEngine;
std::uniform_int_distribution<char> charDist(' ', '~');
auto generateRandomChar = std::bind(charDist, rngEngine);

// Generate a single random string of specified length
std::string createRandomString(size_t length) {
    std::string buffer;
    buffer.reserve(length);
    for (size_t index = 0; index < length; ++index) {
        buffer += generateRandomChar();
    }
    return buffer;
}

// Generate a fixed batch of 10 random strings of given length
std::vector<std::string> createRandomStringBatch(size_t length) {
    std::vector<std::string> batch;
    batch.reserve(10);
    for (int i = 0; i < 10; ++i) {
        batch.emplace_back(createRandomString(length));
    }
    return batch;
}

// Intern multiple randomly generated strings into the cache
std::vector<StringBox> internRandomStrings(StringCache& cache, size_t count, size_t length) {
    std::vector<StringBox> interned;
    interned.reserve(count);
    for (size_t i = 0; i < count; ++i) {
        interned.emplace_back(cache.makeString(createRandomString(length)));
    }
    return interned;
}

