// Reverses the order of checkpoints in-place
void InvertCheckpointsOrder(Checkpoints& checkpoints)
{
  std::vector<mercator::Point> coords = checkpoints.GetPoints();
  std::reverse(coords.begin(), coords.end());
  checkpoints = Checkpoints(coords);
}

