  // Forward direction
  auto result1 = integration::CalculateRoute(components, path, guidance);
  ValidateRouteAgainstExpectations(result1, targetDistM, targetTimeS, targetPoints);

  // Reverse direction
  InvertCheckpointsOrder(path);
  auto result2 = integration::CalculateRoute(components, path, guidance);
  ValidateRouteAgainstExpectations(result2, targetDistM, targetTimeS, targetPoints);
