  if (in.selectOnce || in.menuOnce)
  {
    // Prevent this frame's input from affecting subsequent screens.
    uiActionSwallowAll(in);
    controlsHelpDismiss();
    return;
  }

  // No additional interaction logic required for this help interface.
}

