namespace infengine
{
void RegisterRenderPipelineBindings(py::module_ &mod)
{
    // ---- CullingResults binding ----
    py::class_<CullingResults>(mod, "CullingResults")
        .def_property_readonly("visible_object_count",
                               [](const CullingResults &cr) { return cr.visibleObjectCount(); })
        .def_property_readonly("visible_light_count",
                               [](const CullingResults &cr) { return cr.visibleLightCount(); });

    // ---- ScriptableRenderContext binding ----
    py::class_<ScriptableRenderContext>(mod, "ScriptableRenderContext")
        .def_property_readonly("scene", &ScriptableRenderContext::GetScene, py::return_value_policy::reference,
                               "Retrieve the scene currently being rendered")
        .def("setup_camera_properties", &ScriptableRenderContext::SetupCameraProperties, py::arg("cam"),
             "Configure camera view-projection matrices for rendering")
        .def("cull", &ScriptableRenderContext::Cull, py::arg("cam"), "Perform frustum culling on scene objects")
        .def("apply_graph", &ScriptableRenderContext::ApplyGraph, py::arg("graph_desc"),
             "Integrate a user-defined render graph topology into the pipeline")
        .def("submit_culling", &ScriptableRenderContext::SubmitCulling, py::arg("results"),
             "Issue draw calls based on previously computed culling results")
        .def("execute_command_buffer", &ScriptableRenderContext::ExecuteCommandBuffer, py::arg("cmd_buf"),
             "Flush and execute a queued CommandBuffer")
        .def("get_camera_target", &ScriptableRenderContext::GetCameraTarget, py::arg("cam"),
             "Obtain the render target associated with the given camera")
        // Global shader parameters
        .def(
            "set_global_texture",
            [](ScriptableRenderContext &ctx, const std::string &param_name, RenderTargetHandle tex_handle) {
                ctx.SetGlobalTexture(param_name, tex_handle);
            },
            py::arg("name"), py::arg("handle"), "Assign a texture to a global shader property")
        .def("set_global_float", &ScriptableRenderContext::SetGlobalFloat, py::arg("name"), py::arg("val"),
             "Set a scalar float value for a shader uniform")
        .def("set_global_vector", &ScriptableRenderContext::SetGlobalVector, py::arg("name"), py::arg("vx"),
             py::arg("vy"), py::arg("vz"), py::arg("vw"), "Set a vec4 uniform in shaders");

    // ---- RenderPipelineCallback abstract base class ----
    py::class_<RenderPipelineCallback, PyRenderPipelineCallback, std::shared_ptr<RenderPipelineCallback>>(
        mod, "RenderPipelineCallback")
        .def(py::init<>())
        .def("render", &RenderPipelineCallback::Render, py::arg("context"), py::arg("cameras"),
             "Main entry point for per-frame rendering logic")
        .def("dispose", &RenderPipelineCallback::Dispose, "Cleanup callback invoked during pipeline teardown");
}
