// Validate boolean literal expressions
void validate_boolean_literals(SMTParser::ParserPtr& parser) {
    std::cout << "=== Validating Boolean Literals ===" << std::endl;

    // Check true constant
    auto trueNode = parser->mkExpr("true");
    assert(trueNode && trueNode->isTrue() && !trueNode->isFalse());
    std::cout << "Expression: true" << std::endl;
    std::cout << "  Output: " << parser->toString(trueNode) << std::endl;
    std::cout << "  True? : yes" << std::endl;
    std::cout << "  False?: no" << std::endl << std::endl;

    // Check false constant
    auto falseNode = parser->mkExpr("false");
    assert(falseNode && falseNode->isFalse() && !falseNode->isTrue());
    std::cout << "Expression: false" << std::endl;
    std::cout << "  Output: " << parser->toString(falseNode) << std::endl;
    std::cout << "  True? : no" << std::endl;
    std::cout << "  False?: yes" << std::endl << std::endl;
}

// Evaluate logical connectives with expected outcomes
void evaluate_logical_connectives(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, bool>> scenarios = {
        {"(not true)", false},
        {"(not false)", true},
        {"(and true true)", true},
        {"(and true false)", false},
        {"(and false false)", false},
        {"(or true true)", true},
        {"(or true false)", true},
        {"(or false false)", false},
        {"(=> true true)", true},
        {"(=> true false)", false},
        {"(=> false true)", true},
        {"(=> false false)", true},
        {"(xor true true)", false},
        {"(xor true false)", true},
        {"(xor false false)", false}
    };

    std::cout << "=== Evaluating Logical Connectives ===" << std::endl;
    for (const auto& scenario : scenarios) {
        std::cout << "Formula: " << scenario.first << std::endl;
        auto node = parser->mkExpr(scenario.first);
        assert(node);
        bool expectedTrue = scenario.second;
        bool actualTrue = node->isTrue();
        assert(actualTrue == expectedTrue || (!actualTrue && !expectedTrue));
        std::cout << "  Result: " << parser->toString(node) << std::endl;
        std::cout << std::endl;
    }
}

// Assess compound boolean formulas
void assess_compound_formulas(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, bool>> testCases = {
        {"(and (or true false) (not false))", true},
        {"(or (and true false) (not true))", false},
        {"(=> (or true false) (and true true))", true},
        {"(xor (not false) (and true false))", true},
        {"(and (=> true false) (or false true))", false},
        {"(not (and (or true false) (=> false true)))", false}
    };

    std::cout << "=== Assessing Compound Boolean Formulas ===" << std::endl;
    for (const auto& testCase : testCases) {
        std::cout << "Formula: " << testCase.first << std::endl;
        auto node = parser->mkExpr(testCase.first);
        assert(node);
        bool expectedTrue = testCase.second;
        bool actualTrue = node->isTrue();
        assert(actualTrue == expectedTrue || (!actualTrue && !expectedTrue));
        std::cout << "  Result: " << parser->toString(node) << std::endl;
        std::cout << std::endl;
    }
}

int main() {
    std::cout << "======= Boolean Logic Evaluation Suite =======" << std::endl;

    SMTParser::ParserPtr parser = SMTParser::newParser();

    validate_boolean_literals(parser);
    evaluate_logical_connectives(parser);
    assess_compound_formulas(parser);

    return 0;
}

#include <iostream>
#include <vector>
#include <numeric>
#include <random>
#include <algorithm>

// Ask the judge about a specific slice and return the result
int query(int value) {
    std::cout << "? " << value << std::endl;
    int response;
    std::cin >> response;
    if (response == -1) {
        std::exit(0); // Exit on judge error
    }
    return response;
}

// Output the final answer pair
void report(int first, int second) {
    std::cout << "! " << first << " " << second << std::endl;
}

// Recursive function to solve the pairing problem
void process(std::vector<int>& items) {
    if (items.empty()) {
        return;
    }

    // Base case: only two items left — they must be a pair
    if (items.size() == 2) {
        report(items[0], items[1]);
        return;
    }

    // Choose pivot as last element (shuffled input makes this safe)
    int pivot = items.back();
    items.pop_back();

    // Query with the pivot to initialize device state
    query(pivot);

    std::vector<int> same_group;
    same_group.push_back(pivot);
    std::vector<int> diff_group;

    int current_kinds = 1; // Only pivot is in the device initially

    // Partition remaining items based on whether adding them increases kind count
    for (int item : items) {
        int new_kinds = query(item);

        if (new_kinds == current_kinds) {
            // Same group: adding item didn't increase distinct kinds
            same_group.push_back(item);
        } else {
            // Different group: adding item introduced a new kind
            diff_group.push_back(item);
            current_kinds = new_kinds;
        }
    }

    // Clear device by toggling all elements of same_group back out
    for (int item : same_group) {
        query(item);
    }

    // Recursively solve both groups
    process(same_group);
    process(diff_group);
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;
    if (n == 0) {
        return 0;
    }

    // Prepare list of slices [1..2n]
    std::vector<int> items(2 * n);
    std::iota(items.begin(), items.end(), 1);

    // Shuffle to randomize pivot selection
    std::random_device rd;
    std::mt19937 rng(rd());
    std::shuffle(items.begin(), items.end(), rng);

    process(items);
    return 0;
}

#include <asio/ts/executor.hpp>
#include <asio/thread_pool.hpp>
#include <iostream>
#include <string>

using asio::bind_executor;
using asio::dispatch;
using asio::make_work_guard;
using asio::post;
using asio::thread_pool;

// Asynchronously reads one line from input stream using a different approach
template <typename CompletionToken>
void read_line_async(std::istream& input_stream, CompletionToken&& token)
{
  // Create a work guard to keep the executor alive during operation
  auto guard = make_work_guard(std::forward<CompletionToken>(token));

  // Schedule the actual I/O work on the default executor
  post([input_stream_ref = std::ref(input_stream), 
        guard = std::move(guard),
        token = std::forward<CompletionToken>(token)]() mutable
  {
    std::string buffer;
    std::getline(input_stream_ref.get(), buffer);

    // Dispatch the completion handler through the associated executor
    dispatch(guard.get_executor(),
        [buffer = std::move(buffer),
         token = std::forward<CompletionToken>(token)]() mutable
        {
          token(std::move(buffer));
        });
  });
}

int main()
{
  thread_pool worker_pool(2); // Explicitly specify pool size
  std::cout << "Enter a line: ";

  read_line_async(std::cin,
      bind_executor(worker_pool, [](std::string result)
        {
          std::cout << "Received: " << result << "\n";
        }));

  worker_pool.join();
}

