int APIENTRY wWinMain(_In_ HINSTANCE instance, _In_opt_ HINSTANCE prev,
                      _In_ wchar_t *command_line, _In_ int show_command) {
  // Attach to existing console or create a new one for debugging
  if (!::AttachConsole(ATTACH_PARENT_PROCESS)) {
    if (::IsDebuggerPresent()) {
      CreateAndAttachConsole();
    }
  }

  // Initialize COM for plugin and library compatibility
  ::CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED);

  // Setup Flutter project with command-line arguments
  flutter::DartProject project(L"data");
  std::vector<std::string> args = GetCommandLineArguments();
  project.set_dart_entrypoint_arguments(std::move(args));

  // Configure window properties
  flutter::FlutterWindow flutter_window(project);
  Win32Window::Point position(10, 10);
  Win32Window::Size dimensions(1280, 720);

  if (!flutter_window.Create(L"flutter_app", position, dimensions)) {
    return EXIT_FAILURE;
  }

  flutter_window.SetQuitOnClose(true);

  // Message loop for Windows application
  ::MSG message;
  while (::GetMessage(&message, nullptr, 0, 0)) {
    ::TranslateMessage(&message);
    ::DispatchMessage(&message);
  }

  ::CoUninitialize();
  return EXIT_SUCCESS;
}

