    config::vars().add("NodeId", config::nodeId());

    // Parse test arguments into a list of C-style strings
    std::vector<const char*> argPtrs;
    std::list<std::string> argStorage;
    std::istringstream stream(TestArgs.val());

    std::string token;
    while (stream >> token) {
        argStorage.push_back(token);
