Void ACPIFactoryInterface::Reboot() {
  // Perform hardware reset using keyboard controller and IDT invalidation
  asm volatile(
      "cli\n"
      "1:\n"
      "inb $0x64, %%al\n"
      "testb $0x02, %%al\n"
      "jnz 1b\n"
      "movb $0xD1, %%al\n"
      "outb %%al, $0x64\n"
      "2:\n"
      "inb $0x64, %%al\n"
      "testb $0x02, %%al\n"
      "jnz 2b\n"
      "movb $0xFE, %%al\n"
      "outb %%al, $0x60\n"
      "xor %%rax, %%rax\n"
      "lidt (%%rax)\n"
      "3:\n"
      "jmp 3b\n"
      :
      :
      : "al", "memory");
}
