#include <vector>
using namespace std;

// Generate all possible subsets (power set) of the given array
vector<vector<int>> subsets(vector<int>& nums) {
    vector<vector<int>> result;
    vector<int> current;

    // Backtracking function to generate subsets
    function<void(int)> backtrack = [&](int start) {
        // Add current subset to result
        result.push_back(current);

        // Try adding each remaining element
        for (int i = start; i < nums.size(); ++i) {
            current.push_back(nums[i]);           // Include nums[i]
            backtrack(i + 1);                     // Recurse with next index
            current.pop_back();                   // Backtrack: remove nums[i]
        }
    };

    backtrack(0);
    return result;
}

