// Global shutdown flag — atomic for thread safety
std::atomic<bool> termination_flag(false);

// Signal handler: sets termination flag upon receiving SIGINT/SIGTERM
void handleTerminationSignal(int sig) {
    spdlog::info("Received termination signal: {}", sig);
    termination_flag = true;
}

// Launch gRPC server and start metrics collection
void initiateService() {
    const std::string endpoint{"0.0.0.0:50051"};
    QubitEngineServiceImpl engine_service;
    grpc::ServerBuilder builder;

    builder.AddListeningPort(endpoint, grpc::InsecureServerCredentials());
    builder.RegisterService(&engine_service);

    // Optional reflection plugin — commented out as in original
    // grpc::reflection::InitProtoReflectionServerBuilderPlugin();

    auto server_ptr = builder.BuildAndStart();
    spdlog::set_level(spdlog::level::debug);
    spdlog::set_pattern("[%Y-%m-%d %H:%M:%S.%e] [%^%l%$] [thread %t] %v");

    spdlog::info("QubitEngine (C++) active on {}", endpoint);
    spdlog::info("QubitEngine v2 (Debug) - VisualizeCircuit mode enabled");

    // Start Prometheus metrics exporter
    QuantumMetrics::Instance().Activate();

    // Install signal handlers
    std::signal(SIGINT, handleTerminationSignal);
    std::signal(SIGTERM, handleTerminationSignal);

    // Polling loop until shutdown requested
    do {
        std::this_thread::sleep_for(std::chrono::milliseconds(500));
    } while (!termination_flag.load());

    spdlog::info("Initiating graceful shutdown...");
    server_ptr->Shutdown();
}

