int main(int argc, char* argv[]) {
#ifdef MPI_ENABLED
    MPI_Init(&argc, &argv);

    int my_rank = -1;
    int total_ranks = -1;

    MPI_Comm_rank(MPI_COMM_WORLD, &my_rank);
    MPI_Comm_size(MPI_COMM_WORLD, &total_ranks);

    if (my_rank == 0) {
        spdlog::info("MPI cluster initialized with {} ranks", total_ranks);
        initiateService();
    } else {
        // Worker node logic: Redis-based job polling + non-blocking MPI probing
        try {
            sw::redis::Redis redis_client("tcp://localhost:6379");
            spdlog::info("Worker rank {} connected to Redis.", my_rank);

            bool keep_polling = true;
            do {
                // Non-blocking check for incoming MPI messages
                int msg_available = 0;
                MPI_Status probe_status;
                MPI_Iprobe(MPI_ANY_SOURCE, MPI_ANY_TAG, MPI_COMM_WORLD,
                           &msg_available, &probe_status);

                // Try blocking pop from Redis queue with timeout
                auto maybe_job = redis_client.bzpopmax("queue:jobs", 1);
                if (maybe_job.has_value()) {
                    const auto& [queue_name, job_id] = *maybe_job;
                    spdlog::info("Worker {} dequeued job: {}", my_rank, job_id);
                    // TODO: dispatch job execution here cleanly
                }

                // Exit condition
                keep_polling = !termination_flag.load();
            } while (keep_polling);

        } catch (const sw::redis::Error& ex) {
            spdlog::error("Redis connection failed: {}", ex.what());
        }
    }

    MPI_Finalize();
#else
    // Standalone (non-MPI) mode: run single-node service
    initiateService();
#endif

    return 0;
}

#include <vector>
#include <cmath>

class Solution {
public:
    int firstMissingPositive(std::vector<int>& nums) {
        int size = nums.size();

        // Normalize non-positive and out-of-range values
        for (int i = 0; i < size; ++i) {
            if (nums[i] <= 0 || nums[i] > size + 1) {
                nums[i] = size + 1;
            }
        }

        // Mark presence of numbers by negating the value at corresponding index
        for (int i = 0; i < size; ++i) {
            int val = std::abs(nums[i]);
            if (val >= 1 && val <= size) {
                nums[val - 1] = -std::abs(nums[val - 1]);
            }
        }

        // Find the first positive index, which indicates missing number
        for (int i = 0; i < size; ++i) {
            if (nums[i] > 0) {
                return i + 1;
            }
        }

        return size + 1;
    }
};

