namespace tpa {

// Entry point for performing semi-sparse pointer analysis on a given program.
//
// This method executes two main stages:
//
// 1. Global Setup Phase:
//    - Leverages GlobalPointerAnalysis to inspect module-level entities.
//    - Builds up initial environment (env) and store (initStore) reflecting
//      global variables and their static initializers.
//
// 2. Iterative Data-Flow Computation:
//    - Constructs a shared GlobalState object containing immutable context.
//    - Instantiates the generic data-flow engine with custom components:
//        * TransferFunction: evaluates each program point,
//        * SemiSparsePropagator: defines traversal strategy over CFG,
//        * Memo: caches intermediate results for efficiency.
//    - Executes until reaching a fixpoint via runOnInitialState<Initializer>.
void SemiSparsePointerAnalysis::runOnProgram(const SemiSparseProgram &ssProg) {
  LOG_INFO("Initializing global state and analyzing static initializers...");

  Store initialStore;

  // Perform global pointer analysis to populate env and initialStore.
  auto [globalEnv, builtStore] =
      GlobalPointerAnalysis{ptrManager, memManager, ssProg.getTypeMap()}
          .runOnModule(ssProg.getModule());

  env = std::move(globalEnv);
  initialStore = std::move(builtStore);

  LOG_INFO("Global analysis finished; proceeding with intra-procedural propagation.");

  // Prepare the shared analysis context used across transfer functions.
  GlobalState analysisContext{ptrManager, memManager, ssProg, extTable, env};

  // Set up the data-flow solver using configured components.
  util::DataFlowAnalysis<GlobalState, Memo, TransferFunction, SemiSparsePropagator>
      solver{analysisContext, memo};

  // Kick off the iterative computation starting from the initialized store.
  solver.runOnInitialState<Initializer>(std::move(initialStore));

  LOG_INFO("Semi-sparse pointer analysis completed successfully.");
}

// Required by CRTP base class: retrieves points-to set for a given pointer.
PtsSet SemiSparsePointerAnalysis::getPtsSetImpl(const Pointer *p) const {
  return env.find(p);  // Equivalent to lookup, but using find-style naming
}

