using namespace std;

// Alternative implementation using a different approach to query words by prefix
void solve() {
    int N;
    if (!(cin >> N)) return;

    set<string> collected_words;

    // Process each letter from 'a' to 'z'
    for (char start_char = 'a'; start_char <= 'z'; ++start_char) {
        if (collected_words.size() >= N) break;

        string prefix(1, start_char);
        int found_for_prefix = 0;
        int current_query_size = 1;

        while (collected_words.size() < N) {
            // Determine how many more words we can possibly need for this prefix
            int other_words = collected_words.size() - found_for_prefix;
            int max_needed_for_this_prefix = N - other_words;

            // Adjust query size: either double or cap at theoretical maximum
            if (current_query_size <= found_for_prefix) {
                current_query_size *= 2;
                continue;
            }

            int effective_k = min(current_query_size, max_needed_for_this_prefix);

            // Skip if no progress would be made
            if (effective_k <= found_for_prefix) {
                current_query_size *= 2;
                continue;
            }

            cout << "query " << prefix << " " << effective_k << endl;
            int actual_count;
            cin >> actual_count;

            // Read the returned words
            for (int idx = 0; idx < actual_count; ++idx) {
                string word;
                cin >> word;
                collected_words.insert(word);
            }

            found_for_prefix = actual_count;

            // If fewer words than requested, no more words exist for this prefix
            if (actual_count < effective_k) {
                break;
            }

            // Early termination if all words collected
            if (collected_words.size() == N) break;

            current_query_size *= 2;
        }
    }

    cout << "answer";
    for (const string& word : collected_words) {
        cout << " " << word;
    }
    cout << endl;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int test_cases;
    if (cin >> test_cases) {
        for (int t = 0; t < test_cases; ++t) {
            solve();
        }
    }

    return 0;
}

#include <vector>
#include <cmath>

class Solution {
public:
    long long precomputed[18];

    // Initialize the precomputed array differently
    void initializeValues() {
        precomputed[0] = 1;
        for (int i = 1; i < 18; ++i) {
            long long term = 3LL * i * (1LL << (2 * (i - 1))) + 1;
            precomputed[i] = precomputed[i - 1] + term;
        }
    }

    // Alternative approach to calculate the sum up to x
    long long calculateSum(unsigned x) {
        if (x == 0) return 0;

        // Find the largest power of 4 <= x using logarithm instead of bit counting
        int power = 0;
        unsigned temp = x;
        while (temp > 1) {
            temp >>= 2;
            power++;
        }

        int remainder = x - (1 << (2 * power));
        return precomputed[power] + static_cast<long long>(remainder) * (power + 1);
    }

    long long minOperations(std::vector<std::vector<int>>& queries) {
        // Initialize the helper array
        initializeValues();

        long long totalOperations = 0;
        for (const auto& query : queries) {
            int leftBound = query[0] - 1;
            int rightBound = query[1];

            // Calculate the operation count using our alternative sum function
            long long rangeSum = calculateSum(rightBound) - calculateSum(leftBound);
            totalOperations += (rangeSum + 1) / 2;
        }

        return totalOperations;
    }
};

