DwarfFile::DwarfFile(AsmPrinter *AP, StringRef Prefix, BumpPtrAllocator &DA)
    : Asm(AP), Abbrevs(AbbrevAllocator), StrPool(DA, *Asm, Prefix) {}

void DwarfFile::addUnit(std::unique_ptr<DwarfCompileUnit> Unit) {
  CUs.emplace_back(std::move(Unit));
}

// Emit each debug unit into its respective section.
void DwarfFile::emitUnits(bool UseOffsets) {
  for (size_t Idx = 0; Idx < CUs.size(); ++Idx)
    emitUnit(CUs[Idx].get(), UseOffsets);
}

void DwarfFile::emitUnit(DwarfUnit *Unit, bool UseOffsets) {
  // Skip units that only contain debug directives (no actual DIEs)
  if (Unit->getCUNode()->isDebugDirectivesOnly())
    return;

  MCSection *Sect = Unit->getSection();
  if (!Sect)
    return;

  // Omit empty units (e.g., abandoned split CUs)
  if (Unit->getUnitDie().values().empty())
    return;

  Asm->OutStreamer->switchSection(Sect);
  Unit->emitHeader(UseOffsets);
  Asm->emitDwarfDIE(Unit->getUnitDie());
  if (MCSymbol *EndSym = Unit->getEndLabel())
    Asm->OutStreamer->emitLabel(EndSym);
}

// Compute sizes and offsets for all units and their DIEs.
void DwarfFile::computeSizeAndOffsets() {
  uint64_t CurrentOffset = 0;
  for (size_t Idx = 0; Idx < CUs.size(); ++Idx) {
    auto &CU = CUs[Idx];
    if (CU->getCUNode()->isDebugDirectivesOnly())
      continue;
    if (CU->getUnitDie().values().empty())
      continue;

    CU->setDebugSectionOffset(CurrentOffset);
    CurrentOffset += computeSizeAndOffsetsForUnit(CU.get());
  }

  if (CurrentOffset > UINT32_MAX && !Asm->isDwarf64()) {
    report_fatal_error("The generated debug information is too large "
                       "for the 32-bit DWARF format.");
  }
}

unsigned DwarfFile::computeSizeAndOffsetsForUnit(DwarfUnit *Unit) {
  unsigned Offset = Asm->getUnitLengthFieldByteSize() + // Length field size
                    Unit->getHeaderSize();              // Header size

  return computeSizeAndOffset(Unit->getUnitDie(), Offset);
}

// Compute size and offset for a single DIE.
unsigned DwarfFile::computeSizeAndOffset(DIE &Die, unsigned Offset) {
  return Die.computeOffsetsAndAbbrevs(Asm->getDwarfFormParams(), Abbrevs,
                                      Offset);
}

void DwarfFile::emitAbbrevs(MCSection *Section) {
  Abbrevs.Emit(Asm, Section);
}

void DwarfFile::emitStrings(MCSection *StrSec, MCSection *OffSec,
                            bool UseRelativeOffsets) {
  StrPool.emit(*Asm, StrSec, OffSec, UseRelativeOffsets);
}

void DwarfFile::addScopeVariable(LexicalScope *LScope, DbgVariable *Var) {
  auto &VarsInScope = ScopeVariables[LScope];
  const DILocalVariable *LocalVar = Var->getVariable();

  if (uint32_t ArgIndex = LocalVar->getArg()) {
    auto InsertResult = VarsInScope.Args.insert({ArgIndex, Var});
    assert(InsertResult.second && "Duplicate argument number in scope");
    (void)InsertResult;
  } else {
    VarsInScope.Locals.push_back(Var);
  }
}

void DwarfFile::addScopeLabel(LexicalScope *LScope, DbgLabel *Label) {
  ScopeLabels[LScope].push_back(Label);
}

std::pair<uint32_t, RangeSpanList *>
DwarfFile::addRange(const DwarfCompileUnit &CU, SmallVector<RangeSpan, 2> Ranges) {
  CURangeLists.emplace_back(
      RangeSpanList{Asm->createTempSymbol("debug_ranges"), &CU, std::move(Ranges)});
  return std::make_pair(CURangeLists.size() - 1, &CURangeLists.back());
}

