#include <string>
using namespace std;

// Reverse the given string by building it backwards
string reverseString(string &s) {
    string reversed = "";
    for (int i = s.length() - 1; i >= 0; --i) {
        reversed += s[i];
    }
    return reversed;
}

#include "urdf_parser/urdf_parser.h"
#include <fstream>
#include <iostream>

int main(int argc, char** argv) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <urdf_file>" << std::endl;
        return 1;
    }

    const char* filename = argv[1];
    while (true) {
        std::string content;
        std::ifstream file(filename);

        if (!file.is_open()) {
            std::cerr << "Failed to open file: " << filename << std::endl;
            return 1;
        }

        std::string line;
        while (std::getline(file, line)) {
            content += line + "\n";
        }
        file.close();

        urdf::parseURDF(content);
    }

    return 0;
}

#include <vector>
#include <stack>

class Solution {
public:
    std::vector<int> dailyTemperatures(std::vector<int>& temperatures) {
        std::stack<int> indexStack;
        int length = temperatures.size();
        std::vector<int> result(length, 0);

        // Start from the last day and move backwards
        indexStack.push(length - 1);

        for (int currentDay = length - 2; currentDay >= 0; --currentDay) {
            // Pop indices from stack while the temperature at those days is <= current day's temperature
            while (!indexStack.empty() && temperatures[indexStack.top()] <= temperatures[currentDay]) {
                indexStack.pop();
            }

            // If stack is empty, no warmer day exists in the future
            if (indexStack.empty()) {
                result[currentDay] = 0;
            } else {
                // The difference in days between the current day and the next warmer day
                result[currentDay] = indexStack.top() - currentDay;
            }

            // Push current day's index onto the stack
            indexStack.push(currentDay);
        }

        return result;
    }
};

