namespace MobileGL {

    // Helper to reset shared pointers in a controlled manner
    void CleanupResources() {
        MGLOG_I("MobileGL closing...");
        glslang::FinalizeProcess();

        // Reset contexts and managers in reverse initialization order
        MG_State::pEGLContext.reset();
        MG_State::pGLContext.reset();

        MG_Impl::GLImpl::TextureImpl::pProxyTextureManager.reset();
        MG_Impl::GLImpl::FramebufferImpl::pDefaultFramebufferInfo.reset();

        MG_Util::Debug::Close();
        // TODO: add and use Shutdown functions for other subsystems
    }

    // Main startup routine
    void Startup() {
        MG_Util::Debug::InitFile();
        MGLOG_I("Initializing MobileGL...");
        MG_ConfigLoader::Init();
        MGLOG_I("Configuration loaded");
        MG_State::Init();
        MGLOG_D("MG_State initialized");
        MG_Backend::Init();
        MGLOG_D("MG_Backend initialized");
        MG_Impl::Init();
        MGLOG_D("MG_Impl initialized");
        glslang::InitializeProcess();
        MGLOG_D("glslang initialized");
        MGLOG_I("MobileGL ready");
    }

    // Public shutdown entry point
    void Shutdown() {
        CleanupResources();
    }

    // Platform-specific lifecycle registration
#if defined(__linux__) || defined(__APPLE__)
    static void RegisterAutoLifecycle() {
        // No-op; handled via constructor/destructor attributes below
    }

    __attribute__((constructor)) static void AutoStartup() {
        Startup();
    }

    __attribute__((destructor)) static void AutoShutdown() {
        Shutdown();
    }
#endif

#ifdef _WIN32
    static BOOL WINAPI DllMainHook(HMODULE hModule, DWORD reason, LPVOID reserved) {
        switch (reason) {
            case DLL_PROCESS_ATTACH:
                Startup();
                break;
            case DLL_PROCESS_DETACH:
                Shutdown();
                break;
        }
        return TRUE;
    }

    static void RegisterAutoLifecycle() {
        // Ensure DllMainHook is registered by linker if needed
        // (No explicit call required here; Windows handles DllMain automatically)
    }
#endif

    // Explicitly invoke platform hooks once (if not auto-registered)
    static const bool lifecycleRegistered = []() {
        RegisterAutoLifecycle();
        return true;
    }();

} // namespace MobileGL

