using asio::post;
using asio::thread_pool;

// Modified active object pattern implementation
class bank_account
{
    int current_balance_ = 0;
    mutable thread_pool worker_pool_{1};
public:
    void add_funds(int value)
    {
        post(worker_pool_, [this, value]
            {
                current_balance_ += value;
            });
    }

    void remove_funds(int value)
    {
        post(worker_pool_, [this, value]
            {
                if (current_balance_ >= value)
                    current_balance_ -= value;
            });
    }

    void show_status() const
    {
        post(worker_pool_, [this]
            {
                std::cout << "account balance: " << current_balance_ << "\n";
            });
    }

    ~bank_account()
    {
        worker_pool_.join();
    }
};

int main()
{
    bank_account account;
    account.add_funds(20);
    account.remove_funds(10);
    account.show_status();
}

#include "Alias/TPA/Context/Context.h"
#include "Alias/TPA/Context/ProgramPoint.h"
using namespace llvm;

namespace context {

// Adds a new context frame based on a ProgramPoint, extracting its components.
const Context *Context::pushContext(const ProgramPoint &pp) {
  return pushContext(pp.getContext(), pp.getInstruction());
}

// Introduces a fresh context frame by extending the current one with an instruction.
// Parameters:
//   callerCtx - The calling context (previous stack frame).
//   callInst  - The instruction representing the call site.
// Returns: A pointer to the canonical (interned) Context instance for the new frame.
const Context *Context::pushContext(const Context *callerCtx,
                                    const Instruction *callInst) {
  // Construct a temporary context object for lookup/insertion
  Context tempCtx(callInst, callerCtx);

  // Attempt insertion into the global set of contexts
  auto [itr, inserted] = ctxSet.insert(tempCtx);

  // Return address of the interned context (either newly created or existing)
  return &(*itr);
}

// Removes the topmost context frame from the stack.
// Precondition: the given context is non-empty.
// Returns: the predecessor context (i.e., the caller's context).
const Context *Context::popContext(const Context *ctx) {
  assert(nullptr != ctx && ctx->sz > 0 && "Attempted to pop an empty or null context");
  return ctx->predContext;
}

// Provides access to the unique global context used for top-level analysis.
// This context represents the program entry point and global state.
const Context *Context::getGlobalContext() {
  Context globalCtx;
  auto [itr, _] = ctxSet.insert(globalCtx);
  return &(*itr);
}

// Exposes all contexts ever created during the analysis.
// Intended for diagnostics, testing, or post-processing.
std::vector<const Context *> Context::getAllContexts() {
  std::vector<const Context *> result;
  result.reserve(ctxSet.size());

  for (auto const &storedCtx : ctxSet) {
    result.push_back(&storedCtx);
  }

  return result;
}

} // namespace context

#include "BufferedOutputStream.h"
#include "util/console/ArrayWithLength.h"
#include "win/extraX64.h"

// Constructs a buffered output stream that wraps the given output stream,
// using a buffer of the specified size.
BufferedOutputStream::BufferedOutputStream(OutputStream* out, int size) {
    underlyingStream = out;
    buffer           = byteArray(size);
    bufferSize       = 0;
}

BufferedOutputStream::~BufferedOutputStream() {
    delete[] buffer.data;
}

// Ensures all buffered data is written to the underlying stream.
void BufferedOutputStream::flush() {
    if (bufferSize > 0) {
        underlyingStream->write(buffer, 0, bufferSize);
        bufferSize = 0;
    }
}

// Closes the stream after flushing remaining data.
void BufferedOutputStream::close() {
    flush();
    underlyingStream->close();
}

// Writes a sequence of bytes from a byte array into the buffer.
// If the write request exceeds buffer capacity, bypass buffering entirely.
void BufferedOutputStream::write(
    byteArray    sourceData,
    unsigned int startIndex,
    unsigned int byteCount
) {
    // If the amount to write is larger than or equal to the buffer size,
    // skip buffering and write directly to avoid unnecessary copying.
    if (byteCount >= buffer.length) {
        flush();
        underlyingStream->write(sourceData, startIndex, byteCount);
    } else {
        // Otherwise, copy byte-by-byte using the single-byte write method.
        for (unsigned int idx = 0; idx < byteCount; ++idx) {
            write(sourceData[startIndex + idx]);
        }
    }
}

// Convenience overload: writes an entire byte array.
void BufferedOutputStream::write(byteArray b) {
    write(b, 0, b.length);
}

// Writes a single byte to the internal buffer.
void BufferedOutputStream::write(unsigned int value) {
    buffer[bufferSize++] = static_cast<byte>(value);

    // When buffer is full, flush it automatically.
    if (bufferSize == buffer.length) {
        flush();
    }
}

