              << "(" << data.m_line << "): ";
    std::cout << Color::Red << failureString(data.m_at) << ": ";

    if (data.m_at & assertType::is_normal) {
        std::cout << Color::Cyan << assertString(data.m_at) 
                  << "( " << data.m_expr << " ) ";
        std::cout << Color::None << (data.m_threw ? "THREW exception: " : "is NOT correct!\n");

        if (data.m_threw) {
            std::cout << data.m_exception;
        } else {
            std::cout << "  values: " << assertString(data.m_at) 
                      << "( " << data.m_decomp << " )";
        }
    } else {
        std::cout << Color::None << "an exception-related assert has failed!";
    }

    std::cout << std::endl;
}

// Main program logic to demonstrate out-of-test-case assertions
void run_assertion_demo(int argc, char** argv) {
    // Skip execution unless explicitly invoked with the specific test flag
    if (std::find_if(argv, argv + argc, 
        [](const char* str) { 
            return std::strcmp(str, "-sf=*asserts_used_outside_of_tests.cpp") == 0; 
        }) == argv + argc) {
        return;
    }

    // Initialize doctest context
    doctest::Context context(argc, argv);

    // Register this context as default for out-of-test assertions
    context.setAsDefaultForAssertsOutOfTestCases();

