#include <iostream>
#include <vector>
using namespace std;

// Maximum size for the answer array
const int MAX_SIZE = 200005;
int result[MAX_SIZE];

// Recursive function to determine elements in range [start, end]
// Uses divide-and-conquer strategy based on frequency queries
void reconstruct(int start, int end) {
    if (start > end) return;

    // Ask query about current segment
    cout << "? " << start << " " << end << endl;

    int mode_value, frequency;
    cin >> mode_value >> frequency;

    // Handle error condition
    if (mode_value == -1) {
        exit(1);
    }

    // If all elements in the segment are the same
    if (frequency == end - start + 1) {
        for (int idx = start; idx <= end; ++idx) {
            result[idx] = mode_value;
        }
        return;
    }

    // Split the segment and process recursively
    int center = (start + end) / 2;
    reconstruct(start, center);
    reconstruct(center + 1, end);
}

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (cin >> n) {
        // Begin reconstruction of the entire array
        reconstruct(1, n);

        // Output final answer
        cout << "! ";
        for (int i = 1; i <= n; ++i) {
            cout << result[i];
            if (i != n) {
                cout << " ";
            }
        }
        cout << "\n";
    }

    return 0;
}

