#include <asio.hpp>
#include <boost/bind.hpp>
#include <istream>
#include <iostream>
#include <ostream>
#include "icmp_header.hpp"
#include "ipv4_header.hpp"

using asio::ip::icmp;
using steady_clock = asio::steady_timer::clock_type;
namespace chrono = asio::chrono;

class icmp_pinger
{
public:
  icmp_pinger(asio::io_context& ctx, const std::string& target_host)
    : resolver_(ctx),
      sock_(ctx, icmp::v4()),
      timer_(ctx),
      seq_num_(0),
      reply_count_(0)
  {
    auto endpoints = resolver_.resolve(icmp::v4(), target_host, "");
    target_ep_ = *endpoints.begin();

    initiate_request();
    prepare_for_reply();
  }

private:
  void initiate_request()
  {
    const std::string payload = "\"Hello!\" from Asio ping.";

    icmp_header req;
    req.type(icmp_header::echo_request);
    req.code(0);
    req.identifier(get_pid());
    req.sequence_number(++seq_num_);
    compute_checksum(req, payload.begin(), payload.end());

    asio::streambuf buffer;
    std::ostream os(&buffer);
    os << req << payload;

    send_time_ = steady_clock::now();
    sock_.send_to(buffer.data(), target_ep_);

    // Set timeout for reply
    reply_count_ = 0;
    timer_.expires_at(send_time_ + chrono::seconds(5));
    timer_.async_wait(boost::bind(&icmp_pinger::on_timeout, this));
  }

  void on_timeout()
  {
    if (reply_count_ == 0)
      std::cout << "Request timed out" << std::endl;

    // Enforce minimum delay between requests
    timer_.expires_at(send_time_ + chrono::seconds(1));
    timer_.async_wait(boost::bind(&icmp_pinger::initiate_request, this));
  }

  void prepare_for_reply()
  {
    reply_buffer_.consume(reply_buffer_.size());
    sock_.async_receive(reply_buffer_.prepare(65536),
        boost::bind(&icmp_pinger::handle_reply, this, _2));
  }

  void handle_reply(std::size_t bytes_received)
  {
    reply_buffer_.commit(bytes_received);

    std::istream is(&reply_buffer_);
    ipv4_header ip_hdr;
    icmp_header icmp_hdr;
    is >> ip_hdr >> icmp_hdr;

    if (!is) return;

    if (icmp_hdr.type() == icmp_header::echo_reply &&
        icmp_hdr.identifier() == get_pid() &&
        icmp_hdr.sequence_number() == seq_num_)
    {
      if (reply_count_++ == 0)
        timer_.cancel();

      auto now = steady_clock::now();
      auto duration = now - send_time_;
      std::size_t data_len = bytes_received - ip_hdr.header_length();

      std::cout << data_len << " bytes from " << ip_hdr.source_address()
                << ": icmp_seq=" << icmp_hdr.sequence_number()
                << ", ttl=" << static_cast<int>(ip_hdr.time_to_live())
                << ", time="
                << chrono::duration_cast<chrono::milliseconds>(duration).count()
                << " ms" << std::endl;
    }

    prepare_for_reply();
  }

  static unsigned short get_pid()
  {
#if defined(_WIN32) || defined(_WIN64)
    return static_cast<unsigned short>(::GetCurrentProcessId());
#else
    return static_cast<unsigned short>(::getpid());
#endif
  }

  icmp::resolver resolver_;
  icmp::endpoint target_ep_;
  icmp::socket sock_;
  steady_timer timer_;
  unsigned short seq_num_;
  chrono::steady_clock::time_point send_time_;
  asio::streambuf reply_buffer_;
  std::size_t reply_count_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: ping <hostname_or_ip>" << std::endl;
#if !defined(_WIN32) && !defined(_WIN64)
      std::cerr << "(This may require elevated privileges)" << std::endl;
#endif
      return 1;
    }

    asio::io_context context;
    icmp_pinger pinger(context, argv[1]);
    context.run();
  }
  catch (const std::exception& ex)
  {
    std::cerr << "Error: " << ex.what() << std::endl;
    return 1;
  }

  return 0;
}

