// Helper function to format legend string with unicode-like subscripts
std::string format_legend(double k, double x0) {
    std::ostringstream oss;

    // Format 'k' part
    if (k != 1.0) {
        oss << "k=" << k << ", ";
    } else {
        oss << "k=1, ";
    }

    // Format subscripted x0 using plain text approximation for unicode
    oss << "x₀=" << x0 << ": f(x) = 1 / [1 + exp(-";

    // Build the expression inside the exponential
    if (k != 1.0) {
        oss << k;
    }

    if (x0 != 0.0) {
        oss << "(";
        if (x0 > 0) {
            oss << "x - " << x0 << ")";
        } else {
            oss << "x + " << -x0 << ")";
        }
    } else {
        oss << "x";
    }

    oss << ")]";
    return oss.str();
}

int main() {
    // Simulate data generation and logistic function evaluation
    double start = -100.0;
    double end = 30.0;
    int num_points = 200;

    // Calculate step size
    double step = (end - start) / (num_points - 1);

    // Output header
    std::cout << "Logistic Functions Visualization Data\n";
    std::cout << "=====================================\n\n";

    // Define parameters for different logistic curves
    struct CurveParams {
        double k;
        double x0;
    };

    CurveParams curves[] = {
        {0.1, -10},
        {0.25, -5},
        {0.5, 0},
        {1.0, 5},
        {2.0, 10}
    };

    // Process each curve
    for (const auto& cp : curves) {
        std::cout << "Curve: " << format_legend(cp.k, cp.x0) << "\n";

        // Generate sample points and compute logistic values
        for (int i = 0; i < num_points; ++i) {
            double x = start + i * step;

            // Compute logistic function: 1 / (1 + exp(-k*(x-x0)))
            double exponent = -cp.k * (x - cp.x0);
            double value = 1.0 / (1.0 + std::exp(exponent));

            // Print a few representative points (every 40th point)
            if (i % 40 == 0 || i == num_points - 1) {
                std::printf("  x=%.2f -> f(x)=%.6f\n", x, value);
            }
        }
        std::cout << "\n";
    }

    std::cout << "Data generation complete.\n";
    return 0;
}

