// Helper function to query a range and return the result
int queryRange(int left, int right) {
    std::cout << "? " << left << " " << right << std::endl;
    int response;
    std::cin >> response;
    return response;
}

void processTestCase() {
    int arraySize;
    std::cin >> arraySize;

    // First phase: locate reference element (value n-1)
    int refPos = queryRange(1, arraySize);

    int searchLeft, searchRight;
    bool refOnLeftSide;

    if (refPos < arraySize && queryRange(refPos, arraySize) == refPos) {
        // The maximum value 'n' lies in [refPos+1, arraySize]
        searchLeft = refPos + 1;
        searchRight = arraySize;
        refOnLeftSide = true;
    } else {
        // The maximum value 'n' lies in [1, refPos-1]
        searchLeft = 1;
        searchRight = refPos - 1;
        refOnLeftSide = false;
    }

    // Second phase: binary search to find exact position of 'n'
    while (searchLeft < searchRight) {
        int mid = searchLeft + (searchRight - searchLeft) / 2;

        if (refOnLeftSide) {
            // Reference is on the left; check if 'n' is in [searchLeft, mid]
            if (queryRange(refPos, mid) == refPos) {
                searchRight = mid;
            } else {
                searchLeft = mid + 1;
            }
        } else {
            // Reference is on the right; check if 'n' is in [mid+1, searchRight]
            if (queryRange(mid + 1, refPos) == refPos) {
                searchLeft = mid + 1;
            } else {
                searchRight = mid;
            }
        }
    }

    std::cout << "! " << searchLeft << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int testCases;
    std::cin >> testCases;

    for (int t = 0; t < testCases; ++t) {
        processTestCase();
    }

    return 0;
}

