// Tile Accelerator (TA) emulation layer for PowerVR2 (Dreamcast)
// Manages command routing via function-pointer-based state machine
// Supports both Store Queue (single 32-byte write) and DMA (block) paths

namespace TASplitter {
    // Pointer to current TA command handler — acts as the state machine cursor
    TaListFP* activeTaHandler = nullptr;
}

using namespace TASplitter;

// Handle single 32-byte Store Queue write (e.g., from SQ register writes)
void libPvr_TaSQ(u32* buffer) {
    if (!activeTaHandler) {
        throw std::runtime_error("TA command handler not initialized");
    }

    Ta_Dma* entry = reinterpret_cast<Ta_Dma*>(buffer);
    activeTaHandler(entry, entry);  // Process one entry; start == end
}

// Process a contiguous block of TA entries via DMA
// 'length' specifies number of Ta_Dma units (i.e., 32-byte chunks), not bytes
void libPvr_TaDMA(u32* buffer, u32 length) {
    if (!activeTaHandler) {
        throw std::runtime_error("TA command handler not initialized");
    }
    if (length == 0) {
        return;  // No work to do
    }

    Ta_Dma* current = reinterpret_cast<Ta_Dma*>(buffer);
    Ta_Dma* lastEntry = current + length - 1;

    while (true) {
        current = activeTaHandler(current, lastEntry);
        if (current > lastEntry) break;
    }
}

