    }

    // Invoked on TA_LIST_INIT (new list start)
    // Resets global TA state and prepares for fresh command stream
    void TA_ListInit() {
        // activeTaHandler is assigned to ta_main inside FifoSplitter::ListInit()
    }

    // Triggered by SOFTRESET register write
    // Performs decoder-side cleanup without resetting physical hardware
    void TA_SoftReset() {
        // Decoder reset handled in FifoSplitter::SoftReset()
