using namespace lbug::binder;

namespace lbug {
namespace planner {

// Determine which factorization groups need flattening before sorting
f_group_pos_set LogicalOrderBy::getGroupsPosToFlatten() {
    auto const& childSchema = children[0]->getSchema();

    // If more than one factorization group exists in the input schema,
    // all ordering expressions must be flattened.
    if (childSchema->getNumGroups() > 1) {
        return FlattenAll::getGroupsPosToFlatten(expressionsToOrderBy, *childSchema);
    }

    // Otherwise, no flattening is needed — all relevant data resides in one group.
    return f_group_pos_set{};
}

// Rebuild the schema for factorized execution mode
void LogicalOrderBy::computeFactorizedSchema() {
    resetSchema(); // Equivalent to createEmptySchema()
    auto const& childSchema = children[0]->getSchema();
    std::vector<std::shared_ptr<Expression>> exprsInScope = childSchema->getExpressionsInScope();
    SinkOperatorUtil::recomputeSchema(*childSchema, exprsInScope, *schema);
}

// Build flat (tuple-at-a-time) schema: single group containing all expressions
void LogicalOrderBy::computeFlatSchema() {
    resetSchema();
    schema->createGroup();
    auto const& childExprs = children[0]->getSchema()->getExpressionsInScope();
    for (auto const& expr : childExprs) {
        schema->insertToGroupAndScope(expr, 0);
    }
}

// Generate human-readable representation of ORDER BY clause + LIMIT/SKIP
std::string LogicalOrderBy::getExpressionsForPrinting() const {
    std::string output = ExpressionUtil::toString(expressionsToOrderBy);

    if (hasSkipNum() && ExpressionUtil::canEvaluateAsLiteral(*skipNum)) {
        output += " SKIP ";
        output += std::to_string(ExpressionUtil::evaluateAsSkipLimit(*skipNum));
    }

    if (hasLimitNum() && ExpressionUtil::canEvaluateAsLiteral(*limitNum)) {
        output += " LIMIT ";
        output += std::to_string(ExpressionUtil::evaluateAsSkipLimit(*limitNum));
    }

    return output;
}

