#include <engLib/eng.h>
namespace engine::store::filter::filesys::base {
//-------------------------------------------------------------------------
/// @details
///		Determines whether the stored entry has been modified since last
///		inspection by comparing file system metadata. When changes are
///		detected, it updates internal state and notifies via markChanged.
///	@param[inout] object
///		The entry to inspect for modifications
///	@returns
///		Error code indicating success or failure of the operation
//-------------------------------------------------------------------------
template <log::Lvl LvlT>
Error IBaseSysInstance<LvlT>::checkChanged(Entry &object) noexcept {
    Error errCode;

    // Resolve the OS-specific path from the URL
    Text osPath;
    if (errCode = Url::osPath(object.url(), osPath)) return errCode;

    // Retrieve file system statistics
    auto statResult = ap::file::stat(osPath, true);
    if (!statResult) return statResult.ccode();

    auto statData = _mv(*statResult);

    // Assume no change initially
    object.changed(false);

    // Compare creation time
    if (object.createTime.get() != statData.createTime) {
        object.markChanged(LogLevel, "Creation timestamp mismatch");
        object.createTime(statData.createTime);
    }

    // Update access time without marking as changed (read-only sync)
    if (object.accessTime.get() != statData.accessTime) {
        object.accessTime(statData.accessTime);
    }

    // Compare modification time
    if (object.modifyTime.get() != statData.modifyTime) {
        object.markChanged(LogLevel, "Modification timestamp mismatch");
        object.modifyTime(statData.modifyTime);
    }

    // Compare file attributes/mode
    if (object.attrib() != statData.plat.st_mode) {
        object.markChanged(LogLevel, "File attributes have changed");
        object.attrib(statData.plat.st_mode);
    }

    // Compare logical file size
    if (object.size() != statData.size) {
        object.markChanged(LogLevel, "Logical file size differs");
        object.size(statData.size);
    }

    // Compare physical disk space usage
    if (object.storeSize() != statData.sizeOnDisk) {
        object.markChanged(LogLevel, "Disk space allocation differs");
        object.storeSize(statData.sizeOnDisk);
    }

    return {};
}
}  // namespace engine::store::filter::filesys::base

