#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <iterator>

int main() {
    // Fast I/O setup for competitive programming
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int m;
    std::cin >> m;

    // Track how many times each passage has been used during left->right transitions
    std::vector<int> left_to_right_counts(m, 0);
    // Track how many times each passage has been used during right->left transitions
    std::vector<int> right_to_left_counts(m, 0);

    while (true) {
        std::string current_stone;
        std::cin >> current_stone;

        if (current_stone == "treasure") {
            // Goal reached - exit loop and terminate
            break;
        }

        if (current_stone == "center") {
            // First visit to a new chamber: mark as "left" and use passage 0
            std::cout << "0 left 0\n";
        } 
        else if (current_stone == "left") {
            // Chamber is marked "left"; flip to "right"
            // Choose the passage with minimum usage in left->right transitions
            auto min_pos = std::min_element(left_to_right_counts.begin(), left_to_right_counts.end());
            int chosen_passage = static_cast<int>(std::distance(left_to_right_counts.begin(), min_pos));

            std::cout << "0 right " << chosen_passage << "\n";
            left_to_right_counts[chosen_passage]++;
        } 
        else if (current_stone == "right") {
            // Chamber is marked "right"; flip to "left"
            // Choose the passage with minimum usage in right->left transitions
            auto min_pos = std::min_element(right_to_left_counts.begin(), right_to_left_counts.end());
            int chosen_passage = static_cast<int>(std::distance(right_to_left_counts.begin(), min_pos));

            std::cout << "0 left " << chosen_passage << "\n";
            right_to_left_counts[chosen_passage]++;
        }
    }

    return 0;
}

