		{
			if (!library_manager_v4::get()->is_initialized())
				return;

			bool const modifiedByHook = is_modified_from_hook();
			auto event = GenerateEvent_JsCallback(
				EventId::kFbLibraryItemsChanged,
				std::make_shared<metadb_handle_list>(handles),
				modifiedByHook
			);
			EventDispatcher::Get().PutEventToAll(std::move(event));
		}

		void on_items_removed(metadb_handle_list_cref handles) noexcept final
		{
			if (!library_manager_v4::get()->is_initialized())
				return;

			auto event = GenerateEvent_JsCallback(
				EventId::kFbLibraryItemsRemoved,
				std::make_shared<metadb_handle_list>(handles)
			);
			EventDispatcher::Get().PutEventToAll(std::move(event));
