#define TILING_KEY_INT 23
#define TILING_KEY_A2_INT 123

extern "C" __global__ __aicore__ void dispatch_layout(
    GM_ADDR topkIdx,
    GM_ADDR numTokensPerRank,
    GM_ADDR numTokensPerExpert,
    GM_ADDR isTokenInRank,
    GM_ADDR notifySendData,
    GM_ADDR sendTokenIdxSmall,
    GM_ADDR workspace,
    GM_ADDR tiling)
{
    // Register and retrieve tiling data
    REGISTER_TILING_DEFAULT(DispatchLayoutTilingData);
    GET_TILING_DATA_WITH_STRUCT(DispatchLayoutTilingData, tilingData, tiling);

    TPipe pipe;

    // Extract key for branching
    const int32_t tilingKey = TILING_KEY_GET();

    switch (tilingKey) {
        case TILING_KEY_INT: {
            MoeDispatchLayout::DispatchLayout<int32_t> op;
            op.Init(topkIdx, numTokensPerRank, numTokensPerExpert, isTokenInRank,
                    notifySendData, sendTokenIdxSmall, workspace, &pipe, &tilingData);
            op.Process();
            break;
        }
        case TILING_KEY_A2_INT: {
            MoeDispatchLayoutA2::DispatchLayoutA2<int32_t> op;
            op.Init(topkIdx, numTokensPerRank, numTokensPerExpert, isTokenInRank,
                    notifySendData, sendTokenIdxSmall, workspace, &pipe, &tilingData);
            op.Process();
            break;
        }
        default:
            // Optional: handle unknown tiling key (no-op in original)
            break;
    }
}

#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    // Grid dimensions
    int rows = 20;
    int cols = 20;

    // Output the grid size
    cout << rows << " " << cols << endl;

    // Create a 2D grid initialized with walls ('0')
    vector<string> maze(rows, string(cols, '0'));

    // Build horizontal corridors on even-numbered rows (0, 2, ..., 18)
    for (int r = 0; r <= 18; r += 2) {
        for (int c = 0; c < cols; ++c) {
            maze[r][c] = '1';
        }
    }

    // Connect adjacent corridors using vertical links in odd rows (1, 3, ..., 17)
    // Alternate connection positions: right side for even pair index, left side for odd pair index
    for (int r = 0; r < 18; r += 2) {
        int pairIndex = r / 2;
        if (pairIndex % 2 == 0) {
            // Even-indexed corridor pair connects at the rightmost column
            maze[r + 1][cols - 1] = '1';
        } else {
            // Odd-indexed corridor pair connects at the leftmost column
            maze[r + 1][0] = '1';
        }
    }

    // Add terminal nodes ("teeth") to row 19 from the last corridor (row 18)
    // Place only at even column indices to avoid creating cycles
    for (int col = 0; col < cols; col += 2) {
        maze[rows - 1][col] = '1';
    }

    // Display the final maze configuration
    for (int i = 0; i < rows; ++i) {
        cout << maze[i] << endl;
    }

    return 0;
}

