	void ValidateOutputFormatString(FString& InOutFilenameFormatString, const bool bTestRenderPass, const bool bTestFrameNumber)
	{
		const FString FrameNumberTokens[] = { TEXT("{frame_number}"), TEXT("{frame_number_shot}"), TEXT("{frame_number_rel}"), TEXT("{frame_number_shot_rel}") };

		// Ensure unique naming when multiple render passes are involved
		if (bTestRenderPass)
		{
			if (!InOutFilenameFormatString.Contains(TEXT("{render_pass}"), ESearchCase::IgnoreCase))
			{
				UE_LOG(LogMovieRenderPipeline, Warning, TEXT("Multiple render passes exported but no {render_pass} format found. Automatically adding!"));

				// Locate the last occurrence of any frame number token
				int32 LastFrameTokenIndex = INDEX_NONE;
				for (const FString& Token : FrameNumberTokens)
				{
					int32 FoundIndex = InOutFilenameFormatString.Find(Token, ESearchCase::IgnoreCase, ESearchDir::FromEnd);
					if (FoundIndex != INDEX_NONE)
					{
						LastFrameTokenIndex = FoundIndex;
						break;
					}
				}

				if (LastFrameTokenIndex == INDEX_NONE)
				{
					// Append at end if no frame token found
					InOutFilenameFormatString += TEXT("{render_pass}");
				}
				else
				{
					// Insert before the frame token to preserve sequence recognition
					InOutFilenameFormatString.InsertAt(LastFrameTokenIndex, TEXT("{render_pass}."));
				}
			}
		}

		// Ensure frame number is present for image sequences
		if (bTestFrameNumber)
		{
			int32 FrameTokenIndex = INDEX_NONE;
			for (const FString& Token : FrameNumberTokens)
			{
				FrameTokenIndex = InOutFilenameFormatString.Find(Token, ESearchCase::IgnoreCase, ESearchDir::FromEnd);
				if (FrameTokenIndex != INDEX_NONE)
				{
					break;
				}
			}

			if (FrameTokenIndex == INDEX_NONE)
			{
				// Warn user that files may be overwritten without frame identifier
				UE_LOG(LogMovieRenderPipeline, Warning, TEXT("Frame number identifier not found. Files may be overwritten."));
			}
			else
			{
				// Insert duplicate marker before frame token
				InOutFilenameFormatString.InsertAt(FrameTokenIndex, TEXT("{file_dup}"));
			}
		}

		// Always ensure {file_dup} is present for safety
		if (!InOutFilenameFormatString.Contains(TEXT("{file_dup}"), ESearchCase::IgnoreCase))
		{
			InOutFilenameFormatString.Append(TEXT("{file_dup}"));
		}
	}

	void RemoveFrameNumberFormatStrings(FString& InOutFilenameFormatString, const bool bIncludeShots)
	{
		// Eliminate frame-number-related placeholders to prevent per-frame file generation
		InOutFilenameFormatString.ReplaceInline(TEXT("{frame_number}"), TEXT(""));
		InOutFilenameFormatString.ReplaceInline(TEXT("{frame_number_rel}"), TEXT(""));

		if (bIncludeShots)
		{
			InOutFilenameFormatString.ReplaceInline(TEXT("{frame_number_shot}"), TEXT(""));
			InOutFilenameFormatString.ReplaceInline(TEXT("{frame_number_shot_rel}"), TEXT(""));
		}
	}
}
