// Test case for profiling a single code block
TEST(ProfilerTest, single_block) {
  PERF_BLOCK("single_loop")
  int counter = 0;
  while (counter < 1000) {
    ++counter;
  }
  PERF_BLOCK_END
}

// Test case for profiling multiple independent code blocks
TEST(ProfilerTest, multi_block) {
  PERF_BLOCK("first_section")
  int idx = 0;
  do {
    ++idx;
  } while (idx < 500);
  PERF_BLOCK_END

  // Unprofiled section
  int temp = 0;
  for (int j = 0; j < 500; ++j) {
    temp += j;
  }

  PERF_BLOCK("second_section")
  int k = 0;
  while (k < 500) {
    ++k;
  }
  PERF_BLOCK_END
}

// Test case for profiling nested code blocks
TEST(ProfilerTest, nested_block) {
  PERF_BLOCK("outer_section")
  int outer = 0;
  while (outer < 500) {
    ++outer;

    PERF_BLOCK("inner_section")
    int inner = 0;
    while (inner < 500) {
      ++inner;
    }
    PERF_BLOCK_END
  }

  // Another unprofiled loop
  int m = 0;
  for (; m < 500; ++m) {
  }
  PERF_BLOCK_END
}

// Test case for profiling an entire function
TEST(ProfilerTest, function) {
  PERF_FUNCTION()
  int val = 0;
  for (int n = 0; n < 1000; ++n) {
