// Constructs a new byte array output stream with an initial buffer of 32 bytes
ByteArrayOutputStream::ByteArrayOutputStream() {
    count = 0;
    buf   = byteArray(32);
}

// Constructs a new byte array output stream with specified initial capacity
ByteArrayOutputStream::ByteArrayOutputStream(unsigned int capacity) {
    count = 0;
    buf   = byteArray(capacity);
}

// Destructor: releases allocated memory if buffer exists
ByteArrayOutputStream::~ByteArrayOutputStream() {
    if (buf.data != nullptr) {
        delete[] buf.data;
    }
}

// Writes a single byte to the stream; expands buffer if needed
void ByteArrayOutputStream::write(unsigned int value) {
    // Ensure sufficient space before writing
    if (count + 1 >= buf.length) {
        buf.resize(buf.length * 2);
    }
    buf[count] = static_cast<byte>(value);
    ++count;
}

// Writes entire byte array to the stream
void ByteArrayOutputStream::write(byteArray source) {
    write(source, 0, source.length);
}

// Writes a subsequence of bytes from source array to the stream
void ByteArrayOutputStream::write(
    byteArray    source,
    unsigned int start,
    unsigned int length
) {
    assert(source.length >= start + length);

    // Expand buffer if necessary to accommodate new data
    if (count + length >= buf.length) {
        unsigned int required = count + length + 1;
        unsigned int doubled  = buf.length * 2;
        buf.resize(required > doubled ? required : doubled);
    }

    // Copy data using platform-specific memory copy function
    XMemCpy(buf.data + count, source.data + start, length);
    count += length;
}

// No-op implementation: closing this stream has no effect
void ByteArrayOutputStream::close() {}

// Returns a new byte array containing only the valid portion of the internal buffer
byteArray ByteArrayOutputStream::toByteArray() const {
    byteArray result(count);
    std::memcpy(result.data, buf.data, count);
    return result;
}

