// Default constructor/destructor and special member functions (no change in semantics)
EntityIDRebaser::EntityIDRebaser() = default;
EntityIDRebaser::~EntityIDRebaser() = default;
EntityIDRebaser::EntityIDRebaser(const EntityIDRebaser&) = default;
EntityIDRebaser& EntityIDRebaser::operator=(const EntityIDRebaser&) = default;
EntityIDRebaser::EntityIDRebaser(EntityIDRebaser&&) noexcept = default;
EntityIDRebaser& EntityIDRebaser::operator=(EntityIDRebaser&&) noexcept = default;

// Adjusts a node identifier based on offset between branch point and current state
NodeID EntityIDRebaser::rebaseNodeID(NodeID inputId) const {
    bioassert(_branchTimeNextNodeID <= _newNextNodeID, "invalid _branchTimeNextNodeID");

    // Compute adjustment only if inputId is >= the node ID count at branch time
    NodeID delta = _newNextNodeID - _branchTimeNextNodeID;
    return (inputId >= _branchTimeNextNodeID) ? (inputId + delta) : inputId;
}

// Adjusts an edge identifier analogously to node IDs
EdgeID EntityIDRebaser::rebaseEdgeID(EdgeID inputId) const {
    bioassert(_branchTimeNextEdgeID <= _newNextEdgeID, "invalid _branchTimeNextEdgeID");

    EdgeID shift = _newNextEdgeID - _branchTimeNextEdgeID;
    return (inputId >= _branchTimeNextEdgeID) ? (inputId + shift) : inputId;
}

