#include <iostream>
#include <stack>
#include <string>

class Solution {
public:
    bool isValid(std::string str) {
        int length = str.length();

        // If length is odd, cannot be valid
        if (length % 2 != 0) {
            return false;
        }

        std::stack<char> bracketStack;

        for (int i = 0; i < length; ++i) {
            char currentChar = str[i];

            // Push opening brackets onto stack
            if (currentChar == '(' || currentChar == '[' || currentChar == '{') {
                bracketStack.push(currentChar);
            } 
            // Handle closing brackets
            else {
                // No matching opening bracket available
                if (bracketStack.empty()) {
                    return false;
                }

                char topBracket = bracketStack.top();

                // Check if current closing bracket matches the top opening bracket
                if ((topBracket == '(' && currentChar == ')') ||
                    (topBracket == '[' && currentChar == ']') ||
                    (topBracket == '{' && currentChar == '}')) {
                    bracketStack.pop();
                } else {
                    return false;
                }
            }
        }

        // All brackets matched if stack is empty
        return bracketStack.empty();
    }
};

#include <iostream>

// Demonstration of const-qualification behavior with different parameter types
struct B {};

// Function declarations with varying const-qualification
void g1(B obj);
void g2(const B obj);
void g3(B& ref);
void g4(const B& ref);
void g5(B* ptr);
void g6(const B* ptr);

// Implementation: g1 accepts non-const object by value
void g1(B obj) {
    g1(obj); // ok (recursion)
    g2(obj); // ok (copying into const is allowed)
    g3(obj); // ok (non-const reference can bind to temporary)
    g4(obj); // ok (const reference can bind to any object)
    g5(&obj); // ok (address of local non-const object)
    g6(&obj); // ok (address of non-const object can be passed to const pointer)
}

// Implementation: g2 accepts const object by value
void g2(const B obj) {
    g1(obj); // ok (copying const to non-const is allowed for value)
    g2(obj); // ok (recursion)
    g3(obj); // error: cannot bind non-const lvalue reference to const object
    g4(obj); // ok (const reference accepts const objects)
    g5(&obj); // error: cannot take address of const object for non-const pointer
    g6(&obj); // ok (const pointer can point to const object)
}

// Implementation: g3 accepts non-const reference
void g3(B& ref) {
    g1(ref); // ok (passing by value copies the object)
    g2(ref); // ok (copying into const is allowed)
    g3(ref); // ok (recursion)
    g4(ref); // ok (const reference can bind to non-const)
    g5(&ref); // ok (address of non-const object)
    g6(&ref); // ok (address of non-const object can be used as const pointer)
}

// Implementation: g4 accepts const reference
void g4(const B& ref) {
    g1(ref); // ok (copying from const object)
    g2(ref); // ok (copying into const is allowed)
    g3(ref); // error: cannot convert const reference to non-const reference
    g4(ref); // ok (recursion)
    g5(&ref); // error: cannot take address of const reference for non-const pointer
    g6(&ref); // ok (const pointer can point to const object)
}

// Implementation: g5 accepts non-const pointer
void g5(B* ptr) {
    g1(*ptr); // ok (dereferencing gives non-const object)
    g2(*ptr); // ok (copying into const is allowed)
    g3(*ptr); // ok (non-const object can bind to non-const reference)
    g4(*ptr); // ok (const reference can bind to any object)
    g5(ptr); // ok (recursion)
    g6(ptr); // ok (non-const pointer can be implicitly converted to const pointer)
}

// Implementation: g6 accepts const pointer
void g6(const B* ptr) {
    g1(*ptr); // ok (dereferencing const pointer yields const object, but copy is allowed)
    g2(*ptr); // ok (copying const object into const parameter)
    g3(*ptr); // error: cannot bind non-const reference to const object
    g4(*ptr); // ok (const reference can bind to const object)
    g5(ptr); // error: cannot convert const pointer to non-const pointer
    g6(ptr); // ok (recursion)
}

