#include <karm/macros>
export module Karm.Core:base.defer;
import :meta.nocopy;
import :base.base;

namespace Karm {

// RAII-style utility to execute a callable once the scope exits
export template <typename F>
struct ScopeGuard : Meta::Pinned {
    F _action;
    always_inline ScopeGuard(F action) : _action(action) {}
    always_inline ~ScopeGuard() {
        _action();
    }
};

export template <typename F>
ScopeGuard(F) -> ScopeGuard<F>;

// Variant that can be explicitly cancelled before execution
export template <typename F>
struct ConditionalGuard : Meta::NoCopy {
    F _action;
    bool _shouldExecute = true;

    always_inline ConditionalGuard(F action) : _action(action) {}
    always_inline ~ConditionalGuard() {
        if (_shouldExecute)
            _action();
    }

    always_inline void cancel() {
        _shouldExecute = false;
    }

    always_inline void enable() {
        _shouldExecute = true;
    }

    always_inline void triggerNow() {
        if (_shouldExecute)
            _action();
        cancel();
    }
};

export template <typename F>
ConditionalGuard(F) -> ConditionalGuard<F>;

} // namespace Karm

