#include <iostream>
#include <boost/array.hpp>
#include <asio.hpp>

int main(int argc, char* argv[]) {
    try {
        if (argc != 2) {
            std::cerr << "Usage: client <host>" << std::endl;
            return 1;
        }

        asio::io_context io_context;
        asio::ip::tcp::resolver resolver(io_context);
        auto endpoints = resolver.resolve(argv[1], "daytime");

        asio::ip::tcp::socket socket(io_context);
        socket.connect(*endpoints.begin());

        for (;;) {
            boost::array<char, 128> buffer;
            asio::error_code ec;
            size_t bytes_read = socket.read_some(asio::buffer(buffer), ec);

            if (ec == asio::error::eof) {
                break; // Connection closed gracefully by peer
            } else if (ec) {
                throw asio::system_error(ec); // Handle other errors
            }

            std::cout.write(buffer.data(), bytes_read);
        }
    } catch (const std::exception& ex) {
        std::cerr << ex.what() << std::endl;
    }

    return 0;
}

