#include <asio/ts/executor.hpp>
#include <asio/thread_pool.hpp>
#include <iostream>

using asio::post;
using asio::thread_pool;
using asio::use_future;

// Refactored bank account implementation using passive object pattern with async operations
class bank_account
{
    int balance_ = 0;
    mutable thread_pool pool_{1};

public:
    // Deposit funds asynchronously and wait for completion
    void deposit(int amount)
    {
        auto future = post(pool_, use_future([=] {
            balance_ += amount;
        }));
        future.get();
    }

    // Withdraw funds conditionally and wait for completion
    void withdraw(int amount)
    {
        auto future = post(pool_, use_future([=] {
            if (balance_ >= amount) {
                balance_ -= amount;
            }
        }));
        future.get();
    }

    // Query current balance synchronously
    int get_balance() const
    {
        auto future = post(pool_, use_future([=] {
            return balance_;
        }));
        return future.get();
    }
};

int main()
{
    bank_account account;
    account.deposit(20);
    account.withdraw(10);
    std::cout << "Current balance: " << account.get_balance() << "\n";
    return 0;
}

