#include <iostream>
#include <vector>
#include <algorithm>

void solve() {
    int n;
    std::cin >> n;

    // Find the first index k where query returns non-zero
    int k = -1;
    for (int i = 2; i <= n; ++i) {
        std::cout << "? 1 " << (i - 1) << std::endl;
        std::cout << i << std::endl;
        for (int j = 1; j < i; ++j) {
            std::cout << j;
            if (j < i - 1) std::cout << " ";
        }
        std::cout << std::endl;
        std::cout.flush();

        int response;
        std::cin >> response;
        if (response != 0) {
            k = i;
            break;
        }
    }

    // Binary search to find the specific position p in range [1, k-1]
    int p = 1;
    int left = 1, right = k - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        int count = mid - left + 1;

        std::cout << "? 1 " << count << std::endl;
        std::cout << k << std::endl;
        for (int idx = left; idx <= mid; ++idx) {
            std::cout << idx;
            if (idx < mid) std::cout << " ";
        }
        std::cout << std::endl;
        std::cout.flush();

        int result;
        std::cin >> result;
        if (result != 0) {
            p = mid;
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }

    // Collect demagnetized items
    std::vector<int> resultIndices;

    // Add all indices from 1 to k-1 except p
    for (int i = 1; i < k; ++i) {
        if (i != p) {
            resultIndices.push_back(i);
        }
    }

    // Check remaining indices from k+1 to n
    for (int i = k + 1; i <= n; ++i) {
        std::cout << "? 1 1" << std::endl;
        std::cout << p << std::endl;
        std::cout << i << std::endl;
        std::cout.flush();

        int check;
        std::cin >> check;
        if (check == 0) {
            resultIndices.push_back(i);
        }
    }

    // Output result
    std::cout << "! " << resultIndices.size();
    for (int idx : resultIndices) {
        std::cout << " " << idx;
    }
    std::cout << std::endl;
    std::cout.flush();
}

