TEST(SingleRawLoad, BasicAssertions) {
    // Construct absolute path for test image
    const std::string base_path = std::filesystem::current_path().string();
    const std::string img_path = base_path + std::string("/raw/dng_100.dng");

    // Initialize processor with RAII guard
    RawProcessorGuard guard;

    // Attempt file open
    int open_result = guard.processor.open_file(img_path.c_str());
    if (open_result != LIBRAW_SUCCESS) {
        FAIL() << "Failed to open RAW file: " << img_path 
               << ", error code: " << open_result;
    }

    // Unpack metadata and raw data
    int unpack_result = guard.processor.unpack();
    if (unpack_result != LIBRAW_SUCCESS) {
        FAIL() << "Failed to unpack RAW data, error code: " << unpack_result;
    }

    // Process image (demosaic, white balance, etc.)
    int process_result = guard.processor.dcraw_process();
    if (process_result != LIBRAW_SUCCESS) {
        FAIL() << "dcraw_process failed, error code: " << process_result;
    }

    // Generate in-memory RGB image
    libraw_processed_image_t* rgb_image = guard.processor.dcraw_make_mem_image();
    if (!rgb_image) {
        ADD_FAILURE() << "Memory image generation failed.";
        return;
    }

    // Optional: verify basic properties (not strictly necessary but adds robustness)
    EXPECT_GT(rgb_image->height, 0);
    EXPECT_GT(rgb_image->width, 0);
