#include <iostream>
#include <fstream>
#include <string>
#include <vector>

int main(int argc, char* argv[]) {
    std::string directoryPath = "";
    bool allFilesProcessedSuccessfully = true;

    std::cout << "Initiating diagnostic scan for .ans files in " << directoryPath << std::endl;

    int counter = 1;
    while (counter <= 10) {
        std::string filePath = directoryPath + std::to_string(counter) + ".ans";
        std::cout << "\n--- Processing file: " << filePath << " ---" << std::endl;

        std::ifstream inputStream(filePath);

        if (!inputStream.is_open()) {
            std::cerr << "  [ERROR] Unable to open the file. File might be missing." << std::endl;
            allFilesProcessedSuccessfully = false;
            ++counter;
            continue;
        }

        // Verify if file has any content
        if (inputStream.peek() == std::ifstream::traits_type::eof()) {
            std::cerr << "  [ERROR] File exists but contains no data." << std::endl;
            allFilesProcessedSuccessfully = false;
            inputStream.close();
            ++counter;
            continue;
        }

        std::vector<std::pair<int, int>> integerPairs;
        int rowValue, columnValue;

        while (inputStream >> rowValue >> columnValue) {
            integerPairs.emplace_back(rowValue, columnValue);
        }

        // Determine reason for loop termination
        if (inputStream.eof()) {
            // Expected case: reached end of file normally
            if (integerPairs.empty()) {
                std::cerr << "  [WARNING] File opened successfully but had no valid integer pairs." << std::endl;
            } else {
                std::cout << "  [SUCCESS] Parsed " << integerPairs.size() << " integer pairs without issues." << std::endl;
            }
        } else if (inputStream.fail()) {
            // Error case: parsing stopped due to invalid format
            std::cerr << "  [ERROR] Parsing failed. File may contain non-numeric or malformed content." << std::endl;
            allFilesProcessedSuccessfully = false;
        }

        inputStream.close();
        ++counter;
    }

    std::cout << "\n--- Final Report ---" << std::endl;
    if (allFilesProcessedSuccessfully) {
        std::cout << "All .ans files were processed successfully." << std::endl;
    } else {
        std::cout << "Some .ans files encountered errors during processing. Check the details above." << std::endl;
    }

    return 0;
}

