// Determine if the array is sorted in non-decreasing order
bool checkSorted(const vector<int>& data, int pos) {
    // Base case: reached the last element, so it's sorted
    if (pos >= data.size() - 1) {
        return true;
    }

    // Check if current element violates the sorted order
    if (data[pos] > data[pos + 1]) {
        return false;
    }

    // Continue checking the remaining elements
    return checkSorted(data, pos + 1);
}

