#include <cmath>

// Recursive function to solve Tower of Hanoi
// Parameters: disks count, source peg, target peg, auxiliary peg
void hanoi(int disks, int src, int dst, int aux) {
    if (disks <= 0) {
        return;
    }

    // Move top (disks-1) from source to auxiliary peg
    hanoi(disks - 1, src, aux, dst);

    // Move the largest disk from source to destination
    std::cout << src << " " << dst << "\n";

    // Move (disks-1) from auxiliary to destination peg
    hanoi(disks - 1, aux, dst, src);
}

int main() {
    // Optimize I/O operations
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int N;
    std::cin >> N;

    // Calculate total moves: 2^N - 1 using bit shift for efficiency
    long long total = (1LL << N) - 1;
    std::cout << total << "\n";

    // Only print individual moves if there are disks to move
    if (N > 0) {
        hanoi(N, 1, 3, 2);
    }

    return 0;
}

