using grpc::Server;
using grpc::ServerBuilder;
using grpc::ServerContext;
using grpc::Status;
using test_service_package::IntRequest;
using test_service_package::IntReply;
using test_service_package::Decompositor;

namespace {
  std::unique_ptr<Server> gMainServer;
  const auto gServerTimeout = std::chrono::seconds(10);
}

// Alternative decomposition service implementation
class DecompositionServiceImpl final : public Decompositor::Service {
public:
  Status Decompose(ServerContext* /*context*/,
                   const IntRequest* request,
                   IntReply* reply) override {
    int remaining = request->value();
    std::vector<int> parts;

    // Use LCG for lightweight pseudo-random generation (still valid C++11+)
    std::minstd_rand rng(std::random_device{}());
    std::uniform_int_distribution<int> dist(1, remaining);

    while (remaining > 0) {
      int candidate = dist(rng);
      if (candidate > remaining) {
        candidate = remaining; // fallback to ensure progress
      }
      parts.push_back(candidate);
      remaining -= candidate;
    }

    // Build output string manually
    std::ostringstream oss;
    for (size_t i = 0; i < parts.size(); ++i) {
      oss << parts[i];
      if (i + 1 < parts.size()) oss << " ";
    }
    oss << " = " << request->value();

    reply->set_message(oss.str());
    return Status::OK;
  }
};

void launch_grpc_server() {
  const std::string addr = "0.0.0.0:50051";
  DecompositionServiceImpl svc;
  ServerBuilder builder;

  builder.AddListeningPort(addr, grpc::InsecureServerCredentials());
  builder.RegisterService(&svc);

  gMainServer = builder.BuildAndStart();
  std::cout << "gRPC server active on " << addr << std::endl;

  gMainServer->Wait();
}

void shutdown_handler() {
  std::this_thread::sleep_for(gServerTimeout);
  std::cout << "Initiating server shutdown after " 
            << gServerTimeout.count() << " seconds" << std::endl;
  gMainServer->Shutdown();
}

int main(int argc, char** argv) {
  std::thread killer(shutdown_handler);
  launch_grpc_server();
  killer.join();
  return 0;
}

