#include <mplot/ReadCurves.h>
#include <mplot/tools.h>
#include <mplot/ColourMap.h>
#include <mplot/Visual.h>
#include <mplot/HexGridVisual.h>

int main()
{
    int exitCode = 0;
    unsigned int initialHexCount = 0;

    std::cout << "Start " << mplot::tools::timeNow() << std::endl;

    // Phase 1: Generate and save hexgrid
    {
        try {
            std::string workingDir = mplot::tools::getPwd();
            std::string svgPath = "../../tests/trial.svg";
            mplot::ReadCurves curveReader(svgPath);

            sm::hexgrid grid(0.01, 3, 0);
            grid.setBoundary(curveReader.getCorticalPath());

            std::cout << grid.extent() << std::endl;
            initialHexCount = grid.num();
            std::cout << "Number of hexes in grid:" << grid.num() << std::endl;
            std::cout << "Last vector index:" << grid.lastVectorIndex() << std::endl;

            grid.save("../trialhexgrid.h5");
        } catch (const std::exception& ex) {
            std::cerr << "Error during hexgrid generation: " << ex.what() << std::endl;
            std::cerr << "Current working directory: " << mplot::tools::getPwd() << std::endl;
            exitCode = -1;
            goto cleanup;
        }
    }

    std::cout << "Generated " << mplot::tools::timeNow() << std::endl;

    // Phase 2: Load and visualize hexgrid
    {
        sm::hexgrid loadedGrid("../trialhexgrid.h5");
        std::cout << "Read " << mplot::tools::timeNow() << std::endl;

        if (loadedGrid.num() != initialHexCount) {
            exitCode = -1;
            goto cleanup;
        }

        // Setup visualizer
        mplot::Visual viewer(1600, 1000, "hexgrid");
        viewer.lightingEffects();

        sm::vec<float, 3> positionOffset = { 0.0f, 0.0f, 0.0f };
        auto hexVis = std::make_unique<mplot::HexGridVisual<float>>(&loadedGrid, positionOffset);

        viewer.bindmodel(hexVis);

        // Prepare per-hex colour data
        std::vector<float> hexColours(loadedGrid.num(), 0.0f);

        static constexpr float COLOR_BOUNDARY_AND_INSIDE = 0.9f;
        static constexpr float COLOR_ONLY_BOUNDARY     = 0.8f;
        static constexpr float COLOR_DOMAIN            = 0.5f;
        static constexpr float COLOR_ONLY_INSIDE       = 0.15f;

        if (loadedGrid.d_flags.size() < loadedGrid.num()) {
            throw std::runtime_error("Flag array d_flags not initialized properly.");
        }

        // Helper lambda to assign colours based on flags
        auto assignHexColor = [&](unsigned int idx) -> void {
            bool isBoundary = (loadedGrid.d_flags[idx] & HEX_IS_BOUNDARY) != 0;
            bool isInside   = (loadedGrid.d_flags[idx] & HEX_INSIDE_BOUNDARY) != 0;

            if (isBoundary && isInside) {
                hexColours[idx] = COLOR_BOUNDARY_AND_INSIDE;
            } else if (isBoundary) {
                hexColours[idx] = COLOR_ONLY_BOUNDARY;
            } else if (isInside) {
                hexColours[idx] = COLOR_ONLY_INSIDE;
            } else {
                hexColours[idx] = COLOR_DOMAIN;
            }
        };

        // Apply colour assignment
        unsigned int i = 0;
        while (i < loadedGrid.num()) {
            assignHexColor(i);
            ++i;
        }

        hexVis->cm.setType(mplot::ColourMapType::Jet);
        hexVis->zScale.null_scaling(); // Flat Z, only colours vary
        hexVis->setScalarData(&hexColours);
        hexVis->hexVisMode = mplot::HexVisMode::HexInterp; // Or Triangles for smoother surface

        hexVis->finalize();
        viewer.addVisualModel(hexVis);

        // Render loop
        while (!viewer.readyToFinish()) {
            glfwWaitEventsTimeout(0.018);
            viewer.render();
        }
    }

cleanup:
    return exitCode;
}

