#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    // Optimize I/O operations for speed
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    // Use 1-based indexing for convenience
    vector<int> a(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
    }

    // We fix x = 3, which gives us reversal lengths of 2 and 4.
    // Reversal of length 2 swaps adjacent elements (step size 1).
    // Reversal of length 4 moves an element up to 3 positions.
    // This allows efficient movement with step sizes 1 and 3.
    cout << 3 << "\n";

    vector<pair<int, int>> operations;

    // Helper lambda: record operation and apply reversal
    auto apply_rev = [&](int left, int right) {
        operations.emplace_back(left, right);
        reverse(a.begin() + left, a.begin() + right + 1);
    };

    // Greedy sorting by placing correct values at boundaries
    int left = 1, right = n;

    while (left < right) {
        int pos_min = -1, pos_max = -1;

        // Locate current positions of values 'left' and 'right'
        for (int idx = 1; idx <= n; ++idx) {
            if (a[idx] == left) pos_min = idx;
            if (a[idx] == right) pos_max = idx;
        }

        // Compute distances to target positions
        int dist_to_left = pos_min - left;
        int dist_to_right = right - pos_max;

        if (dist_to_left <= dist_to_right) {
            // Move 'left' value to position 'left'
            int cur = pos_min;
            while (cur > left) {
                if (cur - 3 >= left) {
                    apply_rev(cur - 3, cur);
                    cur -= 3;
                } else {
                    apply_rev(cur - 1, cur);
                    cur -= 1;
                }
            }
            ++left;
        } else {
            // Move 'right' value to position 'right'
            int cur = pos_max;
            while (cur < right) {
                if (cur + 3 <= right) {
                    apply_rev(cur, cur + 3);
                    cur += 3;
                } else {
                    apply_rev(cur, cur + 1);
                    cur += 1;
                }
            }
            --right;
        }
    }

    cout << operations.size() << "\n";
    for (const auto& op : operations) {
        cout << op.first << " " << op.second << "\n";
    }

    return 0;
}

