WinCFGuard::WinCFGuard(AsmPrinter *A) : Asm(A) {}
WinCFGuard::~WinCFGuard() = default;

void WinCFGuard::endFunction(const MachineFunction *MF) {
  // Skip functions that have no longjmp targets.
  const auto &targets = MF->getLongjmpTargets();
  if (targets.empty())
    return;

  // Transfer longjmp targets from function scope to module-wide list.
  for (auto T : targets)
    LongjmpTargets.push_back(T);
}

/// Determines whether a function may be used as an indirect call target.
/// This includes cases where its address escapes in ways that could lead to
/// indirect calls — except for simple casts used only in direct calls with
/// mismatched prototypes.
static bool mightBeIndirectCallTarget(const Function *F) {
  SmallVector<const Value *, 4> worklist;
  worklist.push_back(F);

  while (!worklist.empty()) {
    const Value *current = worklist.pop_back_val();

    for (const Use &U : current->uses()) {
      const User *user = U.getUser();

      // Block addresses don't count as escape.
      if (isa<BlockAddress>(user))
        continue;

      // Check if this is a call instruction where the operand is not the callee.
      if (const CallBase *call = dyn_cast<CallBase>(user)) {
        if (!call->isCallee(&U))
          return true;
      }
      // Any other instruction implies escape.
      else if (isa<Instruction>(user)) {
        return true;
      }
      // Handle constants: only preserve pointer casts that strip back to F.
      else if (const Constant *cst = dyn_cast<Constant>(user)) {
        if (cst->stripPointerCasts() == F) {
          worklist.push_back(cst);
        } else {
          return true;
        }
      }
    }
  }

  return false;
}

MCSymbol *WinCFGuard::lookupImpSymbol(const MCSymbol *sym) {
  StringRef name = sym->getName();
  if (name.startswith("__imp_"))
    return nullptr;

  return Asm->OutContext.lookupSymbol(("__imp_" + name).str());
}

void WinCFGuard::endModule() {
  const Module *mod = Asm->MMI->getModule();
  std::vector<const MCSymbol *> gfidsSymbols;
  std::vector<const MCSymbol *> giatsSymbols;

  for (const Function &func : *mod) {
    if (mightBeIndirectCallTarget(&func)) {
      // If it's a dllimport function with an existing __imp_ symbol,
      // add the __imp_ symbol to .giats section.
      if (func.hasDLLImportStorageClass()) {
        MCSymbol *impSym = lookupImpSymbol(Asm->getSymbol(&func));
        if (impSym) {
          giatsSymbols.push_back(impSym);
        }
      }

      // Always add the original function symbol to .gfids section.
      gfidsSymbols.push_back(Asm->getSymbol(&func));
    }
  }

  // Nothing to emit if all lists are empty.
  if (gfidsSymbols.empty() && giatsSymbols.empty() && LongjmpTargets.empty())
    return;

  MCStreamer &OS = *Asm->OutStreamer;
  MCObjectFileInfo *objInfo = Asm->OutContext.getObjectFileInfo();

  // Emit .gfids section entries
  OS.switchSection(objInfo->getGFIDsSection());
  for (const MCSymbol *s : gfidsSymbols)
    OS.emitCOFFSymbolIndex(s);

  // Emit .giats section entries
  OS.switchSection(objInfo->getGIATsSection());
  for (const MCSymbol *s : giatsSymbols)
    OS.emitCOFFSymbolIndex(s);

  // Emit .gljmp section entries
  OS.switchSection(objInfo->getGLJMPSection());
  for (const MCSymbol *s : LongjmpTargets)
    OS.emitCOFFSymbolIndex(s);
}

