// Constructs an InputStreamReader that utilizes the default character encoding.
// Parameters:
// in - Input stream to wrap
InputStreamReader::InputStreamReader(InputStream *in) : stream( new DataInputStream( in ) )
{
}

// Releases resources and closes the underlying stream.
// After closing, operations like read(), ready(), mark(), reset(), or skip() will trigger an exception.
// Attempting to close an already-closed stream is safe and has no effect.
void InputStreamReader::close()
{
    stream->close();
}

// Reads one Unicode character from the stream.
// Returns:
// The character value (0-65535), or -1 when end-of-stream is reached.
int InputStreamReader::read()
{
    return stream->readUTFChar();
}

// Reads up to 'length' characters into the provided buffer starting at 'offset'.
// Parameters:
// cbuf - Target character array
// offset - Starting index in cbuf for writing characters
// length - Upper bound on number of characters to read
// Returns:
// Number of characters actually read, or -1 if no data available (end-of-stream)
int InputStreamReader::read(wchar_t cbuf[], unsigned int offset, unsigned int length)
{
    unsigned int count = 0;
    unsigned int pos = offset;

    while (pos < offset + length)
    {
        int rawChar = stream->readUTFChar();
        if (rawChar != -1)
        {
            cbuf[pos] = static_cast<wchar_t>(rawChar);
            count++;
            pos++;
        }
        else
        {
            break; // End of stream encountered
        }
    }

    return count;
}

