class TFileListTest : public TTestBase {
    UNIT_TEST_SUITE(TFileListTest);
    UNIT_TEST(TestSimple);
    UNIT_TEST(TestPrefix);
    UNIT_TEST_SUITE_END();
public:
    void TestSimple();
    void TestPrefix();
};

void TFileListTest::TestSimple() {
    // Create a temporary directory with a unique name
    TTempDir tempDirectory("nonexistingdir");

    // Ensure the subdirectory exists
    TString subDirPath = tempDirectory() + LOCSLASH_S "subdir";
    MakeDirIfNotExist(subDirPath.data());

    // Create a file inside the subdirectory
    TString filePath = subDirPath + LOCSLASH_S "file";
    TFile(filePath.data(), CreateAlways);

    // Populate the file list from the temp directory
    TFileList fileList;
    fileList.Fill(tempDirectory().data(), "", "", 1000);

    // Verify the first (and only) entry matches expected path
    TString actualFileName(fileList.Next());
    UNIT_ASSERT_EQUAL(actualFileName, "subdir" LOCSLASH_S "file");

    // Confirm no more files are left in the list
    UNIT_ASSERT_EQUAL(fileList.Next(), nullptr);
}

void TFileListTest::TestPrefix() {
    // Set up a fresh temporary directory
    TTempDir tempDirectory("nonexistingdir");

    // Create test files with specific naming patterns
    TFile((tempDirectory() + LOCSLASH_S "good_file1").data(), CreateAlways);
    TFile((tempDirectory() + LOCSLASH_S "good_file2").data(), CreateAlways);
    TFile((tempDirectory() + LOCSLASH_S "bad_file1").data(), CreateAlways);
    TFile((tempDirectory() + LOCSLASH_S "bad_file2").data(), CreateAlways);

    const bool ENABLE_SORTING = true;
    TFileList fileList;

    // First, test files matching "good_file" prefix
    {
        fileList.Fill(tempDirectory().data(), "good_file", ENABLE_SORTING);

        UNIT_ASSERT_EQUAL(TString(fileList.Next()), "good_file1");
        UNIT_ASSERT_EQUAL(TString(fileList.Next()), "good_file2");
        UNIT_ASSERT_EQUAL(fileList.Next(), nullptr);
    }

    // Then, test files matching "bad_file" prefix
    {
        fileList.Fill(tempDirectory().data(), "bad_file", ENABLE_SORTING);

        UNIT_ASSERT_EQUAL(TString(fileList.Next()), "bad_file1");
        UNIT_ASSERT_EQUAL(TString(fileList.Next()), "bad_file2");
        UNIT_ASSERT_EQUAL(fileList.Next(), nullptr);
    }
}

