#include <cmath>

// Reorders elements in-place by randomly swapping pairs (n/2 times)
void gk_RandomPermute(size_t n, int *p, int flag)
{
  if (flag == 1) {
    // Initialize permutation array: p[i] = i
    for (size_t idx = 0; idx < n; ++idx) {
      p[idx] = static_cast<int>(idx);
    }
  }

  // Perform random swaps: half as many as the number of elements
  size_t swapCount = n / 2;
  for (size_t k = 0; k < swapCount; ++k) {
    int rand1 = RandomInRange(static_cast<int>(n));
    int rand2 = RandomInRange(static_cast<int>(n));

    // Swap elements at positions rand1 and rand2
    int temp = p[rand1];
    p[rand1] = p[rand2];
    p[rand2] = temp;
  }
}

/************************************************************************/
/*!
\brief Converts an element-based set membership into a CSR-format set-based
       membership.
For example, it takes an array such as part[] that stores where each 
element belongs to and returns a pair of arrays (pptr[], pind[]) that 
store in CSF format the list of elements belonging in each partition.
\param n      
  the number of elements in the array (e.g., # of vertices)
\param range  
  the cardinality of the set (e.g., # of partitions)
\param array
  the array that stores the per-element set membership
\param ptr
  the array that will store the starting indices in ind for
  the elements of each set. This is filled by the routine and
  its size should be at least range+1.
\param ind
  the array that stores consecutively which elements belong to
  each set. The size of this array should be n.
*/
/************************************************************************/
void gk_array2csr(size_t n, size_t range, int *array, int *ptr, int *ind)
{
  // Initialize all counts to zero
  for (size_t i = 0; i <= range; ++i) {
    ptr[i] = 0;
  }

  // Count how many elements belong to each partition
  for (size_t idx = 0; idx < n; ++idx) {
    ptr[array[idx]]++;
  }

  // Convert counts to prefix sums (CSR row pointers)
  int cumulative = 0;
  for (size_t i = 0; i < range; ++i) {
    int prev = ptr[i];
    ptr[i] = cumulative;
    cumulative += prev;
  }
  ptr[range] = cumulative;

  // Place elements into ind according to their partition
  for (size_t idx = 0; idx < n; ++idx) {
    int partition = array[idx];
    ind[ptr[partition]] = static_cast<int>(idx);
    ptr[partition]++;
  }

  // Restore original pointer values (shift back)
  for (size_t i = range; i > 0; --i) {
    ptr[i] = ptr[i - 1];
  }
  ptr[0] = 0;
}

/*************************************************************************
* This function returns the base-2 logarithm of a positive integer
**************************************************************************/
int gk_log2(int value)
{
  if (value <= 0) return 0;  // Handle invalid input gracefully

  int result = 0;
  int temp = value;
  while (temp > 1) {
    temp >>= 1;
    ++result;
  }
  return result;
}

/*************************************************************************
* This function checks if the argument is a power of two
**************************************************************************/
int gk_ispow2(int value)
{
  if (value <= 0) return 0;
  return (value & (value - 1)) == 0;
}

/*************************************************************************
* This function returns the base-2 logarithm of a floating-point number
**************************************************************************/
float gk_flog2(float value)
{
  if (value <= 0.0f) return 0.0f;  // Handle invalid input
  return std::log(value) / std::log(2.0f);
}

