#include <vector>
#include <algorithm>

class Solution {
public:
    void rotate(std::vector<std::vector<int>>& matrix) {
        int size = matrix.size();

        // Transpose the matrix by swapping elements across the main diagonal
        for (int row = 0; row < size; ++row) {
            for (int col = row + 1; col < size; ++col) {
                std::swap(matrix[row][col], matrix[col][row]);
            }
        }

        // Reverse each row to complete the 90-degree clockwise rotation
        for (int row = 0; row < size; ++row) {
            int left = 0;
            int right = size - 1;
            while (left < right) {
                std::swap(matrix[row][left], matrix[row][right]);
                ++left;
                --right;
            }
        }
    }
};

#if defined(__SSE__) && !defined(USE_SCALAR_IMPLEMENTATION)
#include "svd3x3_sse.h"
#include <cmath>
#include <algorithm>

#define USE_SSE_IMPL
#undef USE_AVX_IMPL
#define COMPUTE_U_AS_MATRIX
#define COMPUTE_V_AS_MATRIX

#include "Singular_Value_Decomposition_Preamble.hpp"

#pragma runtime_checks("u", off)

template<typename Scalar>
IGL_INLINE void igl::svd3x3_sse(
    const Eigen::Matrix<Scalar, 3*4, 3>& input_matrix,
    Eigen::Matrix<Scalar, 3*4, 3>& left_vecs,
    Eigen::Matrix<Scalar, 3*4, 1>& singular_vals,
    Eigen::Matrix<Scalar, 3*4, 3>& right_vecs)
{
    // Scratch buffers for batched processing (4 matrices at once)
    float src_buf[9][4], u_buf[9][4], v_buf[9][4], s_buf[3][4];

    // Transpose and pack input into buffer layout expected by kernel
    int row = 0;
    while (row < 3) {
        int col = 0;
        while (col < 3) {
            int batch = 0;
            while (batch < 4) {
                src_buf[row + col * 3][batch] = input_matrix(row + 3 * batch, col);
                ++batch;
            }
            ++col;
        }
        ++row;
    }

#include "Singular_Value_Decomposition_Kernel_Declarations.hpp"

    // Load data into SIMD registers
    ENABLE_SSE_IMPL(a11 = _mm_loadu_ps(&src_buf[0][0]);)
    ENABLE_SSE_IMPL(a21 = _mm_loadu_ps(&src_buf[1][0]);)
    ENABLE_SSE_IMPL(a31 = _mm_loadu_ps(&src_buf[2][0]);)
    ENABLE_SSE_IMPL(a12 = _mm_loadu_ps(&src_buf[3][0]);)
    ENABLE_SSE_IMPL(a22 = _mm_loadu_ps(&src_buf[4][0]);)
    ENABLE_SSE_IMPL(a32 = _mm_loadu_ps(&src_buf[5][0]);)
    ENABLE_SSE_IMPL(a13 = _mm_loadu_ps(&src_buf[6][0]);)
    ENABLE_SSE_IMPL(a23 = _mm_loadu_ps(&src_buf[7][0]);)
    ENABLE_SSE_IMPL(a33 = _mm_loadu_ps(&src_buf[8][0]);)

#include "Singular_Value_Decomposition_Main_Kernel_Body.hpp"

    // Store results back from SIMD registers
    ENABLE_SSE_IMPL(_mm_storeu_ps(&u_buf[0][0], u11);)
    ENABLE_SSE_IMPL(_mm_storeu_ps(&u_buf[1][0], u21);)
    ENABLE_SSE_IMPL(_mm_storeu_ps(&u_buf[2][0], u31);)
    ENABLE_SSE_IMPL(_mm_storeu_ps(&u_buf[3][0], u12);)
    ENABLE_SSE_IMPL(_mm_storeu_ps(&u_buf[4][0], u22);)
    ENABLE_SSE_IMPL(_mm_storeu_ps(&u_buf[5][0], u32);)
    ENABLE_SSE_IMPL(_mm_storeu_ps(&u_buf[6][0], u13);)
    ENABLE_SSE_IMPL(_mm_storeu_ps(&u_buf[7][0], u23);)
    ENABLE_SSE_IMPL(_mm_storeu_ps(&u_buf[8][0], u33);)

    ENABLE_SSE_IMPL(_mm_storeu_ps(&v_buf[0][0], v11);)
    ENABLE_SSE_IMPL(_mm_storeu_ps(&v_buf[1][0], v21);)
    ENABLE_SSE_IMPL(_mm_storeu_ps(&v_buf[2][0], v31);)
    ENABLE_SSE_IMPL(_mm_storeu_ps(&v_buf[3][0], v12);)
    ENABLE_SSE_IMPL(_mm_storeu_ps(&v_buf[4][0], v22);)
    ENABLE_SSE_IMPL(_mm_storeu_ps(&v_buf[5][0], v32);)
    ENABLE_SSE_IMPL(_mm_storeu_ps(&v_buf[6][0], v13);)
    ENABLE_SSE_IMPL(_mm_storeu_ps(&v_buf[7][0], v23);)
    ENABLE_SSE_IMPL(_mm_storeu_ps(&v_buf[8][0], v33);)

    ENABLE_SSE_IMPL(_mm_storeu_ps(&s_buf[0][0], a11);)
    ENABLE_SSE_IMPL(_mm_storeu_ps(&s_buf[1][0], a22);)
    ENABLE_SSE_IMPL(_mm_storeu_ps(&s_buf[2][0], a33);)

    // Unpack results into output matrices
    int out_row = 0;
    while (out_row < 3) {
        int out_col = 0;
        while (out_col < 3) {
            int batch_idx = 0;
            while (batch_idx < 4) {
                left_vecs(out_row + 3 * batch_idx, out_col) = u_buf[out_row + out_col * 3][batch_idx];
                right_vecs(out_row + 3 * batch_idx, out_col) = v_buf[out_row + out_col * 3][batch_idx];
                ++batch_idx;
            }
            ++out_col;
        }
        ++out_row;
    }

    // Extract diagonal singular values
    int diag_idx = 0;
    while (diag_idx < 3) {
        int batch_idx = 0;
        while (batch_idx < 4) {
            singular_vals(diag_idx + 3 * batch_idx, 0) = s_buf[diag_idx][batch_idx];
            ++batch_idx;
        }
        ++diag_idx;
    }
}

