using asio::ip::tcp;

int main(int argc, char* argv[]) {
    try {
        if (argc != 3) {
            std::cerr << "Usage: http_client <server> <path>\n";
            std::cerr << "Example:\n";
            std::cerr << "  http_client www.boost.org /LICENSE_1_0.txt\n";
            return 1;
        }

        tcp::iostream connection;

        // Set timeout for the entire operation
        connection.expires_after(asio::chrono::seconds(60));

        // Connect to the server using the provided hostname and service name
        connection.connect(argv[1], "http");

        if (!connection) {
            std::cerr << "Connection failed: " << connection.error().message() << "\n";
            return 1;
        }

        // Construct and send HTTP GET request
        connection << "GET " << argv[2] << " HTTP/1.0\r\n"
                   << "Host: " << argv[1] << "\r\n"
                   << "Accept: */*\r\n"
                   << "Connection: close\r\n\r\n";

        // Read and validate HTTP version
        std::string version;
        connection >> version;

        unsigned int code;
        connection >> code;

        std::string message;
        std::getline(connection, message);

        // Verify response format
        if (!connection || version.substr(0, 5) != "HTTP/") {
            std::cerr << "Malformed HTTP response received\n";
            return 1;
        }

        // Check status code
        if (code != 200) {
            std::cerr << "HTTP error: " << code << " " << message << "\n";
            return 1;
        }

        // Print headers until blank line
        std::string line;
        while (std::getline(connection, line) && line != "\r") {
            std::cout << line << "\n";
        }
        std::cout << "\n";

        // Output remaining body content
        std::cout << connection.rdbuf();
    }
    catch (const std::exception& ex) {
        std::cerr << "Runtime error: " << ex.what() << "\n";
        return 1;
    }

    return 0;
}

