#include "ByteArrayOutputStream.h"

// Constructs a new byte array output stream with an initial buffer capacity of 32 bytes
ByteArrayOutputStream::ByteArrayOutputStream()
{
    count = 0;
    buf = byteArray(32);
}

// Constructs a new byte array output stream with the specified initial buffer size
// Parameters:
//   size - the desired initial capacity in bytes
ByteArrayOutputStream::ByteArrayOutputStream(unsigned int size)
{
    count = 0;
    buf = byteArray(size);
}

// Destructor: releases allocated memory if buffer exists
ByteArrayOutputStream::~ByteArrayOutputStream()
{
    if (buf.data != nullptr)
        delete[] buf.data;
}

// Writes a single byte to the stream
// Parameters:
//   b - the byte value to write
void ByteArrayOutputStream::write(unsigned int b)
{
    // Ensure sufficient buffer space by doubling capacity when needed
    if (count + 1 >= buf.length)
        buf.resize(buf.length * 2);

    buf[count] = static_cast<byte>(b);
    ++count;
}

// Writes all bytes from the provided byte array to the stream
// Equivalent to calling write(b, 0, b.length)
void ByteArrayOutputStream::write(byteArray b)
{
    write(b, 0, b.length);
}

// Writes a subsequence of bytes from the input array to the stream
// Parameters:
//   b       - source data array
//   offset  - starting position in the source array
//   length  - number of bytes to copy
void ByteArrayOutputStream::write(byteArray b, unsigned int offset, unsigned int length)
{
    assert(b.length >= offset + length);

    // Expand buffer if necessary to accommodate new data
    if (count + length >= buf.length)
        buf.resize(std::max(count + length + 1, buf.length * 2));

    // Copy data from source to internal buffer
    std::memcpy(&buf[count], &b[offset], length);

    count += length;
}

// Closes the stream — this operation is a no-op for this implementation
void ByteArrayOutputStream::close()
{
    // No action required; stream remains usable after closing
}

// Returns a copy of the current contents of the stream as a new byte array
// The returned array's size matches the current stream length
byteArray ByteArrayOutputStream::toByteArray() const
{
    byteArray result(count);
    std::memcpy(result.data, buf.data, count);
    return result;
}

