#include <cstdlib>
#include <iostream>
#include <boost/bind.hpp>
#include "asio.hpp"

using asio::ip::udp;

class echo_server
{
public:
  echo_server(asio::io_context& context, unsigned short port_number)
    : socket_(context, udp::endpoint(udp::v4(), port_number))
  {
    start_receiving();
  }

private:
  void start_receiving()
  {
    socket_.async_receive_from(
        asio::buffer(buffer_, buffer_size), remote_endpoint_,
        boost::bind(&echo_server::on_receive, this,
          asio::placeholders::error,
          asio::placeholders::bytes_transferred));
  }

  void on_receive(const asio::error_code& ec, size_t length)
  {
    if (!ec && length > 0)
    {
      send_response(length);
    }
    else
    {
      // Restart receiving on error or empty packet
      start_receiving();
    }
  }

  void send_response(size_t data_length)
  {
    socket_.async_send_to(
        asio::buffer(buffer_, data_length), remote_endpoint_,
        boost::bind(&echo_server::on_send, this,
          asio::placeholders::error,
          asio::placeholders::bytes_transferred));
  }

  void on_send(const asio::error_code& /*error*/, size_t /*sent_bytes*/)
  {
    start_receiving();
  }

private:
  udp::socket socket_;
  udp::endpoint remote_endpoint_;
  static const size_t buffer_size = 1024;
  char buffer_[buffer_size];
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: async_udp_echo_server <port>\n";
      return 1;
    }

    asio::io_context io_context;
    using namespace std; // For atoi.

    echo_server server_instance(io_context, static_cast<unsigned short>(atoi(argv[1])));
    io_context.run();
  }
  catch (const std::exception& exception_obj)
  {
    std::cerr << "Error: " << exception_obj.what() << "\n";
    return 1;
  }

  return 0;
}

