        auto res = lua_env.script(malformed_script, sol::script_pass_on_error);
        if (!res.valid()) {
            auto err_obj = static_cast<sol::error>(res);
            auto stat = res.status();
            std::cout << "Script failed with status '" << sol::to_string(stat) << "':\n\t"
                      << err_obj.what() << '\n';
        }
    }

    // Approach C: Manual chunk loading and evaluation
    {
        auto loaded = lua_env.load(malformed_script);
        if (!loaded.valid()) {
            auto err = static_cast<sol::error>(loaded);
            auto load_stat = loaded.status();
            std::cout << "Failed to load script: status '" << sol::to_string(load_stat) << "'\n\t"
                      << err.what() << '\n';
        } else {
            // This branch should not execute since syntax is invalid
            auto func = loaded.get<sol::protected_function>();
            auto run_result = func();
            if (!run_result.valid()) {
                auto runtime_err = static_cast<sol::error>(run_result);
                auto call_stat = run_result.status();
                std::cout << "Runtime error occurred: status '" << sol::to_string(call_stat) << "'\n\t"
                          << runtime_err.what() << '\n';
            }
        }
    }

    std::cout << std::endl;
    return 0;
}

