class FPlatformCryptoAdapter : public IEngineCrypto
{
public:
	FPlatformCryptoAdapter()
	{
		IModularFeatures::Get().RegisterModularFeature(IEngineCrypto::GetFeatureName(), this);
	}

	virtual ~FPlatformCryptoAdapter()
	{
		Teardown();
	}

	virtual void Teardown() override
	{
		if (CryptoContext.IsValid())
		{
			CryptoContext.Reset();
		}
	}

private:
	TUniquePtr<FEncryptionContext>& EnsureContext()
	{
		if (!CryptoContext.IsValid())
		{
			CryptoContext = IPlatformCrypto::Get().BuildContext();
		}
		return CryptoContext;
	}

	TUniquePtr<FEncryptionContext> CryptoContext;

public:
	/** IEngineCrypto implementation */
	virtual FRSAKeyHandle CreateRSAKey(const TArrayView<const uint8> InExponentPub, const TArrayView<const uint8> InExponentPriv, const TArrayView<const uint8> InModulus) override
	{
		return EnsureContext()->MakeRSAKey(InExponentPub, InExponentPriv, InModulus);
	}

	virtual void DestroyRSAKey(FRSAKeyHandle InKeyHandle) override
	{
		EnsureContext()->RemoveRSAKey(InKeyHandle);
	}

	virtual int32 GetKeyLength(FRSAKeyHandle InKeyHandle) override
	{
		return EnsureContext()->FetchRSAKeySize(InKeyHandle);
	}

	virtual int32 GetMaximumPayloadSize(FRSAKeyHandle InKeyHandle) override
	{
		return EnsureContext()->MaxInputSize_RSA(InKeyHandle);
	}

	virtual int32 EncryptWithPublic(const TArrayView<const uint8> InInput, TArray<uint8>& OutBuffer, FRSAKeyHandle InKeyHandle) override
	{
		return EnsureContext()->PerformPublicEncrypt_RSA(InInput, OutBuffer, InKeyHandle);
	}

	virtual int32 EncryptWithPrivate(const TArrayView<const uint8> InInput, TArray<uint8>& OutBuffer, FRSAKeyHandle InKeyHandle) override
	{
		return EnsureContext()->PerformPrivateEncrypt_RSA(InInput, OutBuffer, InKeyHandle);
	}

	virtual int32 DecryptWithPublic(const TArrayView<const uint8> InInput, TArray<uint8>& OutBuffer, FRSAKeyHandle InKeyHandle) override
	{
		return EnsureContext()->PerformPublicDecrypt_RSA(InInput, OutBuffer, InKeyHandle);
	}

	virtual int32 DecryptWithPrivate(const TArrayView<const uint8> InInput, TArray<uint8>& OutBuffer, FRSAKeyHandle InKeyHandle) override
	{
		return EnsureContext()->PerformPrivateDecrypt_RSA(InInput, OutBuffer, InKeyHandle);
	}
};

