#ifndef __Pyx_CppExn2PyErr
#include <new>
#include <typeinfo>
#include <stdexcept>
#include <ios>

// Converts C++ exceptions into corresponding Python errors
static void __Pyx_CppExn2PyErr() {
    // If a Python exception is already set, do nothing further
    if (PyErr_Occurred()) return;

    try {
        throw;  // Re-throw current exception
    }
    catch (const std::bad_alloc&) {
        PyErr_SetString(PyExc_MemoryError, "Memory allocation failed");
    }
    catch (const std::bad_cast&) {
        PyErr_SetString(PyExc_TypeError, "Bad cast encountered");
    }
    catch (const std::bad_typeid&) {
        PyErr_SetString(PyExc_TypeError, "Invalid typeid operation");
    }
    catch (const std::domain_error&) {
        PyErr_SetString(PyExc_ValueError, "Domain error in argument");
    }
    catch (const std::invalid_argument&) {
        PyErr_SetString(PyExc_ValueError, "Invalid argument supplied");
    }
    catch (const std::ios_base::failure&) {
        PyErr_SetString(PyExc_IOError, "I/O operation failed");
    }
    catch (const std::out_of_range&) {
        PyErr_SetString(PyExc_IndexError, "Index out of range");
    }
    catch (const std::overflow_error&) {
        PyErr_SetString(PyExc_OverflowError, "Numerical overflow occurred");
    }
    catch (const std::range_error&) {
        PyErr_SetString(PyExc_ArithmeticError, "Range error in computation");
    }
    catch (const std::underflow_error&) {
        PyErr_SetString(PyExc_ArithmeticError, "Numerical underflow detected");
    }
    catch (const std::exception& e) {
        PyErr_SetString(PyExc_RuntimeError, e.what());
    }
    catch (...) {
        PyErr_SetString(PyExc_RuntimeError, "Unknown or non-standard exception");
    }
}
#endif

/////////////// PythranConversion.proto ///////////////
template <typename T>
auto __Pyx_pythran_to_python(T &&val) -> decltype(
    to_python(
        pythonic::returnable<
            typename std::remove_cv<
                typename std::remove_reference<T>::type
            >::type
        >{std::forward<T>(val)}
    )
) {
    using wrapped_type = typename pythonic::returnable<
        typename std::remove_cv<
            typename std::remove_reference<T>::type
        >::type
    >;
    return to_python(wrapped_type{std::forward<T>(val)});
}

