#include <optional>

// Alias for underlying optional implementation
template <typename T>
using __Pyx_Optional_Impl = std::optional<T>;

// Wrapper offering consistent copy/move assignment semantics via emplace
template <typename T>
class __Pyx_Optional_Type : private __Pyx_Optional_Impl<T> {
public:
    using base_t = __Pyx_Optional_Impl<T>;
    using base_t::base_t;
    using base_t::has_value;
    using base_t::operator*;
    using base_t::operator->;

#if __cplusplus >= 201103L || (defined(_MSC_VER) && _MSC_VER >= 1600)
    __Pyx_Optional_Type& operator=(const __Pyx_Optional_Type& other) {
        if (other.has_value()) this->emplace(*other);
        else this->reset();
        return *this;
    }

    __Pyx_Optional_Type& operator=(__Pyx_Optional_Type&& other) {
        if (other.has_value()) this->emplace(std::move(*other));
        else this->reset();
        return *this;
    }

    template <typename U>
    __Pyx_Optional_Type& operator=(U&& val) {
        this->emplace(std::forward<U>(val));
        return *this;
    }
#else
    // Pre-C++11 fallback — relies on base assignment where supported
    using base_t::operator=;
#endif
};

