auto indexConfig = R"(
		{
			"config": {
				"index": {
					"compress": true,
					"maxWordCount": 250000000,
					"batchId": 1,
					"indexOutput": "datafile://data/output-words-%BatchId%.dat"
				}
			}
		}
	)"_json;
