TEST_CASE("store::index") {
    // Test writing a limited set of words
    SECTION("write a few words") {
        IFilterTest filter({engine::store::filter::indexer::Type}, indexConfig);
        Error ccode;
        // Establish connection to the endpoint
        REQUIRE_NO_ERROR(filter.connect());
        // Open a test object for indexing
        auto pipe = filter.openObject("test.txt"_tv, Entry::FLAGS::INDEX);
        REQUIRE_NO_ERROR(pipe);
        WordVector words{"word1"_tv, "word2"_tv, "word4"_tv};
        REQUIRE_NO_ERROR(pipe->writeWords(words));
        REQUIRE_NO_ERROR(filter.closeObject(*pipe));
    }
    // Test handling a large volume of distinct words
    SECTION("write lots of words") {
        IFilterTest filter({engine::store::filter::indexer::Type}, indexConfig);
        Error ccode;
        // Connect to the storage backend
        REQUIRE_NO_ERROR(filter.connect());
        // Acquire a write pipe and open target object
        auto pipe = filter.openObject("test.txt"_tv, Entry::FLAGS::INDEX);
        REQUIRE_NO_ERROR(pipe);
        // Generate and write one million unique terms
        _const int totalTerms = 1'000'000;
        _const int partitionCount = 10;
        _const int termsPerPartition = totalTerms / partitionCount;
        for (int partId = 0; partId < partitionCount; partId++) {
            WordVector batch;
            LOG(Test, "Processing partition {}", partId);
            // Populate batch with terms in structured groups
            for (int termIdx = 0; termIdx < termsPerPartition; termIdx++) {
                Text termText =
                    string::format("this.is.a.longer.phrase.{}",
                                   partId * termsPerPartition + termIdx);
                batch.push_back(_mv(termText));
            }
            REQUIRE_NO_ERROR(pipe->writeWords(batch));
        }
        // Finalize the indexed object
        REQUIRE_NO_ERROR(filter.closeObject(*pipe));
    }
}

