                                                 const char* func,
                                                 const char* condition,
                                                 const char* details) {
    std::string error_msg;
    absl::strings_internal::OStringStream stream{&error_msg};

    stream << "Assertion failed: " 
           << "File '" << file << "', Line " << line 
           << ", Function '" << func << "'\n"
           << "Expression: " << condition;

    if (details != nullptr && details[0] != '\0') {
        stream << "\nDetails: " << details;
    }

    stream << std::endl;

    crash(error_msg);
