class FWinDualShock : public IInputDevice
{
public:
	FWinDualShock(const TSharedRef<FGenericApplicationMessageHandler>& InMessageHandler)
		: MessageHandler(InMessageHandler)
	{
		// Initialize configuration flags for DS4 features
		bool bEnableTouch = false;
		bool bEnableTouchAsAxis = false;
		bool bEnableMouseEmulation = false;
		bool bEnableMotionTracking = false;

		if (GConfig)
		{
			// Load user preferences from config file
			GConfig->GetBool(TEXT("SonyController"), TEXT("bDSTouchEvents"), bEnableTouch, GEngineIni);
			GConfig->GetBool(TEXT("SonyController"), TEXT("bDSTouchAxisButtons"), bEnableTouchAsAxis, GEngineIni);
			GConfig->GetBool(TEXT("SonyController"), TEXT("bDSMouseEvents"), bEnableMouseEmulation, GEngineIni);
			GConfig->GetBool(TEXT("SonyController"), TEXT("bDSMotionEvents"), bEnableMotionTracking, GEngineIni);
		}

		// Apply configuration to controller system
		Controllers.SetEmitTouchEvents(bEnableTouch);
		Controllers.SetEmitTouchAxisEvents(bEnableTouchAsAxis);
		Controllers.SetEmitMouseEvents(bEnableMouseEmulation);
		Controllers.SetEmitMotionEvents(bEnableMotionTracking);
	}

	virtual ~FWinDualShock()
	{
		CleanupPlatformResources();
	}

	virtual void Tick(float DeltaTime) override
	{
		// No per-frame processing required
	}

	virtual bool IsGamepadAttached() const override
	{
		return Controllers.IsGamepadAttached();
	}

	virtual void SendControllerEvents() override
	{
		Controllers.SendControllerEvents(MessageHandler);
	}

	void SetChannelValue(int32 ControllerId, FForceFeedbackChannelType ChannelType, float Value)
	{
		Controllers.SetForceFeedbackChannelValue(ControllerId, ChannelType, Value);
	}

	void SetChannelValues(int32 ControllerId, const FForceFeedbackValues& Values)
	{
		Controllers.SetForceFeedbackChannelValues(ControllerId, Values);
	}

	virtual void SetMessageHandler(const TSharedRef<FGenericApplicationMessageHandler>& InMessageHandler) override
	{
		MessageHandler = InMessageHandler;
	}

	virtual bool Exec(UWorld* InWorld, const TCHAR* Cmd, FOutputDevice& Ar) override
	{
		return false;
	}

private:
	TSharedRef<FGenericApplicationMessageHandler> MessageHandler;
	FPlatformControllers Controllers;

	void CleanupPlatformResources()
	{
		WindowsCleanup();
	}
};

