	// Helper to normalize stat name: lowercase and replace 'x' in "mpx" with current char index digit
	static void NormalizeStatName(std::string& stat)
	{
		// Convert entire string to lowercase
		for (char& c : stat) {
			c = static_cast<char>(::tolower(static_cast<unsigned char>(c)));
		}

		// Check if starts with "mpx"
		if (stat.size() >= 3 && stat[0] == 'm' && stat[1] == 'p') {
			int charIdx = GetCharacterIndex();
			if (charIdx >= 0 && charIdx <= 9) {
				stat[2] = static_cast<char>('0' + charIdx);
			}
		}
	}

	// Retrieve current character index from stats system
	static int GetCharacterIndex()
	{
		int result = -1;
		STATS::STAT_GET_INT("MPPLY_LAST_MP_CHAR"_J, &result, -1);
		return result;
	}

	void SetInteger(const std::string& statName, int value)
	{
		std::string name = statName; // copy for normalization
		NormalizeStatName(name);
		STATS::STAT_SET_INT(Joaat(name), value, TRUE);
	}

	void SetBoolean(const std::string& statName, bool value)
	{
		std::string name = statName;
		NormalizeStatName(name);
		STATS::STAT_SET_BOOL(Joaat(name), value, TRUE);
