// Constructor initializes the internal message storage
MessageBus::MessageBus() {
    // messages container is default-constructed (empty map)
}

// Store or update a message at the specified address
void MessageBus::store(Message *msg) {
    uint64_t addr = msg->get_location();
    messages[addr] = msg;
}

// Retrieve a message by its address, if present
Message* MessageBus::fetch(uint64_t addr) {
    auto iter = messages.find(addr);
    if (iter != messages.end()) {
        return iter->second;
    }
    return nullptr; // Indicates no message exists at this address
}

