#ifndef __Pyx_CppExn2PyErr
#include <new>
#include <typeinfo>
#include <stdexcept>
#include <ios>

// Convert C++ exceptions into Python errors
static void __Pyx_ConvertCppExceptionToPython() {
    if (PyErr_Occurred()) {
        // A Python exception is already set; ignore the current C++ one
        return;
    }

    try {
        throw;  // Re-throw to catch in outer scope
    } catch (const std::bad_alloc&) {
        PyErr_SetString(PyExc_MemoryError, "Memory allocation failed");
    } catch (const std::bad_cast&) {
        PyErr_SetString(PyExc_TypeError, "Type conversion failed");
    } catch (const std::bad_typeid&) {
        PyErr_SetString(PyExc_TypeError, "Invalid type information");
    } catch (const std::domain_error&) {
        PyErr_SetString(PyExc_ValueError, "Domain error encountered");
    } catch (const std::invalid_argument&) {
        PyErr_SetString(PyExc_ValueError, "Invalid argument provided");
    } catch (const std::ios_base::failure&) {
        PyErr_SetString(PyExc_IOError, "I/O operation failed");
    } catch (const std::out_of_range&) {
        PyErr_SetString(PyExc_IndexError, "Index out of range");
    } catch (const std::overflow_error&) {
        PyErr_SetString(PyExc_OverflowError, "Numeric overflow occurred");
    } catch (const std::range_error&) {
        PyErr_SetString(PyExc_ArithmeticError, "Range error");
    } catch (const std::underflow_error&) {
        PyErr_SetString(PyExc_ArithmeticError, "Numeric underflow");
    } catch (const std::exception& e) {
        PyErr_SetString(PyExc_RuntimeError, e.what());
    } catch (...) {
        PyErr_SetString(PyExc_RuntimeError, "Unknown exception caught");
    }
}
#endif

/////////////// PythranConversion.proto ///////////////
template <typename T>
auto __Pyx_pythran_to_python(T &&val) 
    -> decltype(to_python(
        typename pythonic::returnable<
            typename std::remove_cv<
                typename std::remove_reference<T>::type
            >::type
        >::type{std::forward<T>(val)}))
{
    using value_type = typename std::remove_cv<
        typename std::remove_reference<T>::type
    >::type;

    using wrapped_type = typename pythonic::returnable<value_type>::type;
    return to_python(wrapped_type{std::forward<T>(val)});
}

