#include <optional>

// Alias for optional type support
template <typename T>
using __Pyx_OptionalStorage = std::optional<T>;

// Wrapper class that mimics std::optional but enforces emplace-based assignment
template <typename T>
class __Pyx_LocalOptional : private __Pyx_OptionalStorage<T> {
public:
    using base_t = __Pyx_OptionalStorage<T>;
    using base_t::base_t;
    using base_t::has_value;
    using base_t::operator*;
    using base_t::operator->;

#if __cplusplus >= 201103L || (defined(_MSC_VER) && _MSC_VER >= 1600)
    __Pyx_LocalOptional& operator=(const __Pyx_LocalOptional& other) {
        if (other.has_value()) this->emplace(*other);
        else this->reset();
        return *this;
    }

    __Pyx_LocalOptional& operator=(__Pyx_LocalOptional&& other) {
        if (other.has_value()) this->emplace(std::move(*other));
        else this->reset();
        return *this;
    }

    template <typename U>
    __Pyx_LocalOptional& operator=(U&& val) {
        this->emplace(std::forward<U>(val));
        return *this;
    }
#else
    // Pre-C++11 fallback (untested, minimal support)
    using base_t::operator=;
#endif
};

#include <engLib/eng.h>
namespace engine::task::actionTransform {
//-----------------------------------------------------------------
/// @details
///		Initialization logic for the transform task
//-----------------------------------------------------------------
Error Task::beginTask() noexcept {
    // First, obtain the target endpoint — configuration of source depends on it
    if (!(m_targetEndpoint = IServiceEndpoint::getTargetEndpoint(
              {.jobConfig = jobConfig(),
               .taskConfig = taskConfig(),
               .serviceConfig = taskConfig()["target"],
               .openMode = OPEN_MODE::TRANSFORM})))
        return m_targetEndpoint.ccode();

    // Determine how the source endpoint should be opened based on requested features
    OPEN_MODE srcOpenMode{};
    bool const wantsPolicies  = m_targetEndpoint->config.taskConfig.lookup<bool>("wantsPolicies");
    bool const wantsContext   = m_targetEndpoint->config.taskConfig.lookup<bool>("wantsContext");
    bool const wantsText      = m_targetEndpoint->config.taskConfig.lookup<bool>("wantsText");
    bool const wantsData      = m_targetEndpoint->config.taskConfig.lookup<bool>("wantsData");

    if (wantsPolicies || wantsContext || wantsText) {
        srcOpenMode = wantsData ? OPEN_MODE::SOURCE_INDEX : OPEN_MODE::INDEX;
    } else {
        srcOpenMode = OPEN_MODE::SOURCE;
    }

    // Acquire the source endpoint using computed mode
    if (!(m_sourceEndpoint = IServiceEndpoint::getSourceEndpoint(
              {.jobConfig = jobConfig(),
               .taskConfig = taskConfig(),
               .serviceConfig = taskConfig()["source"],
               .openMode = srcOpenMode})))
        return m_sourceEndpoint.ccode();

    // Proceed with base class initialization
    return Parent::beginTask();
}
//-----------------------------------------------------------------
///	@details
///		Processes a single input line and prepares an entry
/// @param[in] line
///		JSON-formatted input line
/// @param[in] parent
///		URL of the parent context
//-----------------------------------------------------------------
ErrorOr<Entry> Task::processLine(TextView line, const Url &parent) noexcept {
    // Use base processing for lines starting with 'A'
    auto entry = Parent::processLine("A"_tv, line, parent);
    if (entry.hasCcode()) return entry;

    // Ensure proper flags for transformation pipeline
    Entry::FLAGS currentFlags = entry.value().flags();
    entry.value().flags(currentFlags | Entry::FLAGS::INDEX |
                        Entry::FLAGS::CLASSIFY | Entry::FLAGS::OCR);
    return entry;
}
//-----------------------------------------------------------------
/// @details
///		Performs final transformation and output handling for an entry
/// @param[in] entry
///		The entry to finalize
//-----------------------------------------------------------------
Error Task::processItem(Entry &entry) noexcept {
    // Let base class handle core processing first
    if (auto ccode = Parent::processItem(entry)) return ccode;

    // Post-processing: classification data is not needed in transformed output
    entry.classifications.reset();

    // Handle outcome based on completion status
    if (entry.objectFailed()) {
        if (Ec::Skipped == entry.completionCode()) {
            // Skipped items are still considered completed
            MONITOR(addCompleted, 1, entry.size());
        } else {
            // Record failure and emit error record
            MONITOR(addFailed, 1, entry.size());
            if (auto ccode = Parent::writeError(entry, entry.completionCode()))
                return ccode;
        }
    } else {
        // Successful transformation
        MONITOR(addCompleted, 1, entry.size());
        if (auto ccode = Parent::writeResult('A', entry)) return ccode;
    }

    return {};
}
