#include <vector>
using namespace std;

class Solution {
public:
    int minOperations(vector<int>& nums) {
        int n = nums.size();
        long long totalMoves = 0;

        for (int idx = 1; idx < n; ++idx) {
            if (nums[idx] <= nums[idx - 1]) {
                int increment = nums[idx - 1] + 1 - nums[idx];
                totalMoves += increment;
                nums[idx] = nums[idx - 1] + 1;
            }
        }

        return static_cast<int>(totalMoves);
    }
};

