    // Helper to call UI update function at address 0x404aec for bank windows
    void update_bank_currency(Zeal::GameUI::BasicWnd* bank_window, int field_index, int amount) {
        auto func = reinterpret_cast<void(__thiscall*)(Zeal::GameUI::BasicWnd*, int, int)>(0x404aec);
        func(bank_window, field_index, amount);
    }

    // Helper to call UI update function at address 0x421876 for inventory windows
    void update_inventory_currency(Zeal::GameUI::BasicWnd* inv_window, int field_index, int amount) {
        auto func = reinterpret_cast<void(__thiscall*)(Zeal::GameUI::BasicWnd*, int, int)>(0x421876);
        func(inv_window, field_index, amount);
    }

    // Update all currency fields in bank window if non-zero
    void refresh_bank_currency(Zeal::GameUI::BasicWnd* bank_window, const Zeal::Game::CharInfo* char_info) {
        if (!bank_window || !char_info) return;

        if (char_info->BankGold > 0) {
            update_bank_currency(bank_window, 1, char_info->BankGold);
            update_bank_currency(bank_window, 2, -1);
        }

        if (char_info->BankSilver > 0) {
            update_bank_currency(bank_window, 2, char_info->BankSilver);
            update_bank_currency(bank_window, 3, -1);
        }

        if (char_info->BankCopper > 0) {
            update_bank_currency(bank_window, 3, char_info->BankCopper);
            // Reset other fields after copper update
            for (int idx : {0, 1, 2, 3}) {
                update_bank_currency(bank_window, idx, -1);
            }
        }
    }

    // Update all currency fields in inventory window if non-zero
    void refresh_inventory_currency(Zeal::GameUI::BasicWnd* inv_window, const Zeal::Game::CharInfo* char_info) {
        if (!inv_window || !char_info) return;

        if (char_info->Gold > 0) {
            update_inventory_currency(inv_window, 1, char_info->Gold);
            update_inventory_currency(inv_window, 2, -1);
        }

        if (char_info->Silver > 0) {
            update_inventory_currency(inv_window, 2, char_info->Silver);
            update_inventory_currency(inv_window, 3, -1);
        }

        if (char_info->Copper > 0) {
            update_inventory_currency(inv_window, 3, char_info->Copper);
            // Reset all fields after copper update
            for (int idx : {0, 1, 2, 3}) {
                update_inventory_currency(inv_window, idx, -1);
            }
        }
    }
}

void ui_bank::change() {
    auto* bank_window = Zeal::Game::Windows->Bank;
    if (!bank_window || !bank_window->IsVisible()) return;

    auto* char_info = Zeal::Game::get_char_info();
    if (!char_info) return;

    refresh_bank_currency(bank_window, char_info);

    auto* inv_window = Zeal::Game::Windows->Inventory;
    if (inv_window) {
        refresh_inventory_currency(inv_window, char_info);
    }
}

