#include <iostream>
#include <sol/sol.hpp>

// Alternative implementation using different variable names and control flow
void alternative_simple(sol::this_state ts, sol::this_environment te) {
    sol::state_view lua_vm = ts;

    if (te.has_value()) {
        sol::environment& current_env = *te;
        sol::environment created_env = lua_vm["freshenv"];
        bool environments_match = created_env == current_env;

        std::cout << "this_environment -- env matches freshenv : "
                  << environments_match << std::endl;
    }

    std::cout << "this_environment -- no environment context available"
              << std::endl;
}

// Enhanced version with refactored stack traversal logic
void alternative_complicated(sol::this_state ts) {
    lua_State* L = ts;
    lua_Debug frame_info;

    int search_level = 1;  // Skip current function frame
    int initial_stack_depth = lua_gettop(L);

    // Attempt to get stack information for the calling frame
    if (lua_getstack(L, search_level, &frame_info) != 1) {
        std::cerr << "error: cannot access stack frame at level " 
                  << search_level << std::endl;
        lua_settop(L, initial_stack_depth);
        return;
    }

    // Retrieve detailed information about the function at this level
    if (lua_getinfo(L, "fnluS", &frame_info) == 0) {
        std::cerr << "manually -- error: failed to retrieve function info" 
                  << std::endl;
        lua_settop(L, initial_stack_depth);
        return;
    }

    // Display debugging information about the stack frame
    std::cout << "manually -- [" << search_level << "] "
              << frame_info.short_src << ":" << frame_info.currentline
              << " -- " << (frame_info.name ? frame_info.name : "<unknown>")
              << "[" << frame_info.what << "]" << std::endl;

    // Extract function from top of stack
    sol::function func_obj(L, -1);

    // Get environment associated with the function
    sol::environment func_env(sol::env_key, func_obj);
    if (!func_env.valid()) {
        std::cout << "manually -- error: no environment found for function" 
                  << std::endl;
        lua_settop(L, initial_stack_depth);
        return;
    }

    // Compare with expected environment
    sol::state_view lua_vm(L);
    sol::environment expected_env = lua_vm["freshenv"];
    bool same_environment = expected_env == func_env;

    std::cout << "manually -- env matches freshenv : " << same_environment 
              << std::endl;

    // Restore original stack state
    lua_settop(L, initial_stack_depth);
}

int main() {
    std::cout << "=== environment introspection ===" << std::endl;

    sol::state lua_vm;
    sol::environment custom_env(lua_vm, sol::create, lua_vm.globals());

    lua_vm["freshenv"] = custom_env;
    lua_vm.set_function("test_func", alternative_simple);
    lua_vm.set_function("inspect_func", alternative_complicated);

    // Execute functions in the custom environment context
    lua_vm.script("test_func()", custom_env);
    lua_vm.script("inspect_func()", custom_env);

    std::cout << std::endl;
    return 0;
}

class Solution {
public:
    void sortColors(vector<int>& nums) {
        int count[3] = {0, 0, 0};

        // Count occurrences of each color
        for (int i = 0; i < nums.size(); ++i) {
            count[nums[i]]++;
        }

        // Reconstruct the array based on counts
        int index = 0;
        for (int color = 0; color <= 2; ++color) {
            while (count[color] > 0) {
                nums[index++] = color;
                count[color]--;
            }
        }
    }
};

#include "comms/torchcomms/nccl/TorchCommNCCLCCA.hpp"
#include <atomic>
#include <stdexcept>

namespace torch::comms {

// Global hook function registered externally
void cachingAllocatorHookFn(
    const c10::cuda::CUDACachingAllocator::TraceEntry& traceEntry) {
  CachingAllocatorHook::getInstance().handleMemoryEvent(traceEntry);
}

// Singleton access — thread-safe via atomic flag
CachingAllocatorHookImpl& CachingAllocatorHook::getInstance() {
  static std::atomic<bool> initialized{false};
  static CachingAllocatorHookImpl* singleton = nullptr;

  if (!initialized.load(std::memory_order_acquire)) {
    std::lock_guard<std::mutex> guard(init_mutex_);
    if (!initialized.load(std::memory_order_relaxed)) {
      singleton = new CachingAllocatorHookImpl();
      initialized.store(true, std::memory_order_release);
    }
  }
  return *singleton;
}

DefaultCachingAllocatorHookImpl::DefaultCachingAllocatorHookImpl() {
  // Ensure CUDA device context is initialized before proceeding
  at::globalContext().lazyInitDevice(c10::DeviceType::CUDA);

  // Capture initial memory state and register pre-existing segments
  captureAndRegisterInitialSegments();

  // Attach the allocator trace tracker callback
  c10::cuda::CUDACachingAllocator::attachAllocatorTraceTracker(
      &cachingAllocatorHookFn);
}

void DefaultCachingAllocatorHookImpl::captureAndRegisterInitialSegments() {
  auto snapshot = c10::cuda::CUDACachingAllocator::snapshot();
  for (const auto& seg : snapshot.segments) {
    void* memAddr = reinterpret_cast<void*>(seg.address);
    size_t segLen = seg.total_size;
    registerNewMemoryRegion(memAddr, segLen, seg.device);
  }
}

void CachingAllocatorHookImpl::registerMemPreHook() {
  // Alias for clarity: same as captureAndRegisterInitialSegments()
  captureAndRegisterInitialSegments();
}

void CachingAllocatorHookImpl::handleMemoryEvent(
    const c10::cuda::CUDACachingAllocator::TraceEntry& traceEntry) {
  std::lock_guard<std::mutex> lock(mutex_);

  bool isAlloc = (traceEntry.action_ ==
                  c10::cuda::CUDACachingAllocator::TraceEntry::Action::SEGMENT_ALLOC);
  bool isFree = (traceEntry.action_ ==
                 c10::cuda::CUDACachingAllocator::TraceEntry::Action::SEGMENT_FREE);

  if (isAlloc) {
    uintptr_t rawAddr = static_cast<uintptr_t>(traceEntry.addr_);
    void* memAddr = reinterpret_cast<void*>(rawAddr);
    size_t len = traceEntry.size_;
    int devIdx = traceEntry.device_;

    // Double-check registration
    if (registeredMemMap_.find(memAddr) != registeredMemMap_.end()) {
      throw std::runtime_error("Attempted to re-register already registered memory");
    }

    registeredMemMap_[memAddr] = MemInfo{len, devIdx};

    // Notify all relevant communicators
    for (auto& comm : registeredComms_) {
      if (comm->getDevice().index() == devIdx) {
        comm->register_address(TorchCommNCCL::AddressWithLen(memAddr, len));
      }
    }

  } else if (isFree) {
    uintptr_t rawAddr = static_cast<uintptr_t>(traceEntry.addr_);
    void* memAddr = reinterpret_cast<void*>(rawAddr);
    int devIdx = traceEntry.device_;

    auto it = registeredMemMap_.find(memAddr);
    if (it == registeredMemMap_.end()) {
      throw std::runtime_error("Attempting to free unregistered memory");
    }

    registeredMemMap_.erase(it);

    // Deregister from active communicators
    for (auto& comm : registeredComms_) {
      if (comm->getDevice().index() == devIdx) {
        comm->deregister_address(TorchCommNCCL::Address(memAddr));
      }
    }
  }
}

void CachingAllocatorHookImpl::registerNewMemoryRegion(void* addr, size_t len, int device) {
  if (registeredMemMap_.find(addr) != registeredMemMap_.end()) {
    throw std::runtime_error("Memory region already registered");
  }
  registeredMemMap_[addr] = MemInfo{len, device};
}

void CachingAllocatorHookImpl::registerComm(TorchCommNCCL* comm) {
  std::lock_guard<std::mutex> lock(mutex_);

  if (registeredComms_.find(comm) != registeredComms_.end()) {
    throw std::runtime_error("Communicator already registered");
  }

  // Pre-register all existing memory regions matching this device
  for (const auto& [addr, info] : registeredMemMap_) {
    if (info.device == comm->getDevice().index()) {
      comm->register_address(TorchCommNCCL::AddressWithLen(addr, info.len));
    }
  }

  registeredComms_.insert(comm);
}

void CachingAllocatorHookImpl::deregisterComm(TorchCommNCCL* comm) {
  std::lock_guard<std::mutex> lock(mutex_);

  auto it = registeredComms_.find(comm);
  if (it == registeredComms_.end()) {
    // Not an error; silently ignore
    return;
  }

  // Unregister all associated memory regions
  for (const auto& [addr, info] : registeredMemMap_) {
    if (info.device == comm->getDevice().index()) {
      comm->deregister_address(TorchCommNCCL::Address(addr));
    }
  }

  registeredComms_.erase(it);
}

void CachingAllocatorHookImpl::clear() {
  std::lock_guard<std::mutex> lock(mutex_);

  // Deregister all memory from all communicators
  for (auto& comm : registeredComms_) {
    for (const auto& [addr, info] : registeredMemMap_) {
      if (info.device == comm->getDevice().index()) {
        comm->deregister_address(TorchCommNCCL::Address(addr));
      }
    }
  }

  registeredMemMap_.clear();
  registeredComms_.clear();
}

bool CachingAllocatorHookImpl::isCommRegistered(TorchCommNCCL* comm) {
  std::lock_guard<std::mutex> lock(mutex_);
  return registeredComms_.find(comm) != registeredComms_.end();
}

