class Biome;

// Precomputed spike positions — derived from angular sampling at radius 40
// Original derivation: x = 40 * cos(angle), z = 40 * sin(angle)
// Angles spaced every π/8 radians starting from -π + π/8
TheEndBiomeDecorator::SPIKE TheEndBiomeDecorator::SpikeConfig[8] = {
    // Format: { minXChunk, minZChunk, centerX, centerZ, heightIndex }
    // Note: minXChunk/minZChunk represent the lowest chunk coordinates covering the spike
    {32,  -16, 40,  0,   2}, // spike #0: right side
    {16,  16,  28,  28,  2}, // spike #1: upper-right
    {-16, 32,  0,   40,  2}, // spike #2: top
    {-32, 16,  -28, 28,  3}, // spike #3: upper-left
    {-48, -16, -40, 0,   3}, // spike #4: left
    {-32, -32, -28, -28, 3}, // spike #5: lower-left
    {-16, -48, 0,   -40, 4}, // spike #6: bottom
    {16,  -32, 28,  -28, 4}  // spike #7: lower-right
};

TheEndBiomeDecorator::TheEndBiomeDecorator(Biome* biome)
    : BiomeDecorator(biome) {
    spikeGenerator     = std::make_unique<SpikeFeature>(Tile::whiteStone_Id);
    podiumGenerator    = std::make_unique<EndPodiumFeature>(Tile::whiteStone_Id);
}

void TheEndBiomeDecorator::decorate() {
    decorateOres();

    // Determine surface height at chunk center
    int surfaceY = level->getTopSolidBlock(xo + 8, zo + 8);
    if (surfaceY > level->GetHighestY()) {
        level->SetHighestY(surfaceY);
    }

    // Attempt to place spikes only if current chunk matches any spike's base chunk
    bool placedSpike = false;
    for (int idx = 0; idx < 8 && !placedSpike; ++idx) {
        if (xo == SpikeConfig[idx].baseChunkX && zo == SpikeConfig[idx].baseChunkZ) {
            spikeGenerator->placeWithIndex(
                level,
                random,
                SpikeConfig[idx].centerX,
                level->GetHighestY(),
                SpikeConfig[idx].centerZ,
                idx,
                SpikeConfig[idx].radius
            );
            placedSpike = true;
        }
    }

    // Spawn Ender Dragon only in central chunk (0,0)
    if (xo == 0 && zo == 0) {
        auto dragon = std::make_shared<EnderDragon>(level);
        float yaw = random->nextFloat() * 360.0f;
        dragon->moveTo(0, 128, 0, yaw, 0);
        level->addEntity(dragon);
    }

    // Place End Podium only in chunk (-16,-16), which ensures full coverage
    if (xo == -16 && zo == -16) {
        podiumGenerator->place(level, random, 0, Level::genDepth / 2, 0);
    }
}

#include <ros/ros.h>
#include <grid_map_ros/grid_map_ros.hpp>
#include <grid_map_cv/grid_map_cv.hpp>
#include <cv_bridge/cv_bridge.h>
#include <opencv2/highgui/highgui.hpp>

using namespace grid_map;
using namespace ros;

int main(int argc, char** argv) {
  // Initialize node and publisher.
  init(argc, argv, "opencv_demo");
  NodeHandle nh("~");
  Publisher pub = nh.advertise<grid_map_msgs::GridMap>("grid_map", 1, true);

  const bool transparentMode = false;

  // Create grid map with two layers: 'input_layer' and 'processed_layer'
  GridMap terrainMap({"input_layer", "processed_layer"});
  terrainMap.setFrameId("map");
  terrainMap.setGeometry(Length(1.2, 2.0), 0.01);

  ROS_INFO("Created map with dimensions %f x %f m (%i x %i cells).",
           terrainMap.getLength().x(), terrainMap.getLength().y(),
           terrainMap.getSize()(0), terrainMap.getSize()(1));

  // Fill polygon region in 'input_layer'
  if (!transparentMode) {
    terrainMap["input_layer"].setZero();
  }

  Polygon shape;
  shape.setFrameId(terrainMap.getFrameId());

  // Define vertices of a decagonal polygon centered at origin
  std::vector<std::pair<double, double>> coords = {
    { 0.480,  0.000}, { 0.164,  0.155}, { 0.116,  0.500},
    {-0.133,  0.250}, {-0.480,  0.399}, {-0.316,  0.000},
    {-0.480, -0.399}, {-0.133, -0.250}, { 0.116, -0.500},
    { 0.164, -0.155}, { 0.480,  0.000}
  };

  for (const auto& pt : coords) {
    shape.addVertex(Position(pt.first, pt.second));
  }

  // Assign constant value inside polygon
  for (PolygonIterator iter(terrainMap, shape); !iter.isPastEnd(); ++iter) {
    terrainMap.at("input_layer", *iter) = 0.3;
  }

  // Convert to OpenCV image
  cv::Mat inputImage;
  if (transparentMode) {
    GridMapCvConverter::toImage<unsigned short, 4>(
        terrainMap, "input_layer", CV_16UC4, 0.0, 0.3, inputImage);
  } else {
    GridMapCvConverter::toImage<unsigned short, 1>(
        terrainMap, "input_layer", CV_16UC1, 0.0, 0.3, inputImage);
  }

  // Create window for visualization
  cv::namedWindow("OpenCV Demo");

  // Main processing loop
  while (nh.ok()) {
    ros::Time now = ros::Time::now();
    terrainMap.setTimestamp(now.toNSec());

    cv::Mat outputImage;

    // Compute dynamic blur kernel size using a sawtooth-like function
    double timeSec = now.toSec();
    int rawVal = static_cast<int>(200.0 * std::fmod(timeSec + 1.0, 2.0) - 100.0);
    int absVal = std::abs(rawVal);
    int ksize = 200 - absVal;
    ksize = (ksize % 2 == 0) ? ksize + 1 : ksize; // Ensure odd size

    // Apply Gaussian blur
    cv::GaussianBlur(inputImage, outputImage, cv::Size(ksize, ksize), 0.0, 0.0);

    // Show result
    cv::imshow("OpenCV Demo", outputImage);
    cv::waitKey(40);

    // Update elevation layer from processed image
    if (transparentMode) {
      GridMapCvConverter::addLayerFromImage<unsigned short, 4>(
          outputImage, "processed_layer", terrainMap, 0.0, 0.3, 0.3);
    } else {
      GridMapCvConverter::addLayerFromImage<unsigned short, 1>(
          outputImage, "processed_layer", terrainMap, 0.0, 0.3);
    }

    // Publish updated grid map
    grid_map_msgs::GridMap msg;
    GridMapRosConverter::toMessage(terrainMap, msg);
    pub.publish(msg);

    ROS_INFO_STREAM("Published image and grid map with blur kernel size " << ksize << ".");
  }

  return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <cmath>
#include <limits>

// Use long double for better precision to avoid underflow with small weights.
using LD = long double;

// Computes log(sum(exp(x_i))) in a numerically stable manner
LD log_sum_exp(const std::vector<LD>& values) {
    if (values.empty()) {
        return -std::numeric_limits<LD>::infinity();
    }

    // Find maximum value to improve numerical stability
    LD max_val = values[0];
    for (size_t i = 1; i < values.size(); ++i) {
        if (values[i] > max_val) {
            max_val = values[i];
        }
    }

    LD sum = 0.0L;
    for (const LD& val : values) {
        sum += expl(val - max_val);
    }

    return max_val + logl(sum);
}

int main() {
    // Fast I/O setup
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n, m;
    std::cin >> n >> m;

    // Initialize log-weights: all experts start with weight 1 => log(1) = 0
    std::vector<LD> expert_logs(n, 0.0L);

    const LD learning_rate = 0.5L;
    const LD log_lr = logl(learning_rate);

    for (int round = 0; round < m; ++round) {
        std::string expert_predictions;
        std::cin >> expert_predictions;

        // Partition experts by their prediction
        std::vector<LD> zero_group;
        std::vector<LD> one_group;

        for (int i = 0; i < n; ++i) {
            if (expert_predictions[i] == '0') {
                zero_group.push_back(expert_logs[i]);
            } else {
                one_group.push_back(expert_logs[i]);
            }
        }

        // Compute total log-weight for each prediction group
        LD log_weight_zero = log_sum_exp(zero_group);
        LD log_weight_one = log_sum_exp(one_group);

        // Make prediction: prefer '0' on ties
        char my_guess;
        if (log_weight_zero >= log_weight_one) {
            my_guess = '0';
        } else {
            my_guess = '1';
        }

        std::cout << my_guess << '\n';

        // Read actual outcome
        char result;
        std::cin >> result;

        // Update weights: penalize incorrect experts by multiplying by eta (adding log(eta))
        for (int i = 0; i < n; ++i) {
            if (expert_predictions[i] != result) {
                expert_logs[i] += log_lr;
            }
        }
    }

    return 0;
}

