int main()
{
    // Initialize a JSON object with key-value pairs
    const json movie_characters =
    {
        { "the good"sv, "il buono" },
        { "the bad"sv, "il cattivo" },
        { "the ugly"sv, "il brutto" }
    };

    // Access and print the value associated with "the ugly"
    std::cout << movie_characters.at("the ugly"sv) << '\n';

    // Handle type error when calling at() on a non-object JSON value
    try
    {
        const json string_value = "I am a string";
        std::cout << string_value.at("the good"sv) << '\n';
    }
    catch (const json::type_error& err)
    {
        std::cout << err.what() << '\n';
