    // Handle out-of-range error when accessing a missing key
    try
    {
        std::cout << movie_characters.at("the fast"sv) << '\n';
    }
    catch (const json::out_of_range&)
    {
        std::cout << "key not found" << '\n';
    }

    return 0;
}

