namespace srouter::dns::sd {

namespace detail {

    template<std::size_t N>
    void send_dns_address(linux::DBUS& dbus, int32_t if_idx, int family, const std::array<uint8_t, N>& addr, uint16_t port) {
        dbus(
            "SetLinkDNSEx",
            "ia(iayqs)",
            if_idx,
            1,                             // one DNS entry
            family,                        // AF_INET or AF_INET6
            static_cast<int>(N),           // address length in bytes
            // Flatten array into initializer list
            [&addr]<std::size_t... Is>(std::index_sequence<Is...>) {
                return std::initializer_list<int>{static_cast<int>(addr[Is])...};
            }(std::make_index_sequence<N>{})
            ,
            port,
            nullptr  // no SNI support
        );
    }

    void configure_domains(linux::DBUS& dbus, int32_t if_idx, bool global) {
        if (global) {
            dbus("SetLinkDomains", "ia(sb)", if_idx, 1, ".", true);
        } else {
            // Local-only domains: .sesh, .loki, .snode
            dbus("SetLinkDomains", "ia(sb)", if_idx, 3,
                 "sesh", true,
                 "loki", true,
                 "snode", true);
        }
    }

} // namespace detail


void Platform::set_resolver(unsigned int if_ndx, quic::Address dns, bool global)
{
    linux::DBUS resolve_manager{"org.freedesktop.resolve1", "/org/freedesktop/resolve1", "org.freedesktop.resolve1.Manager"};

    // Disable default route and DoT for this interface first
    resolve_manager("SetLinkDefaultRoute", "ib", static_cast<int32_t>(if_ndx), false);
    resolve_manager("SetLinkDNSOverTLS", "is", static_cast<int32_t>(if_ndx), "off");

    // Handle IPv4 / IPv6 differently
    if (dns.is_ipv6()) {
        auto& ipv6_addr = dns.in6().sin6_addr.s6_addr;
        std::array<uint8_t, 16> addr{};
        std::copy_n(ipv6_addr, 16, addr.begin());
        detail::send_dns_address(resolve_manager, static_cast<int32_t>(if_ndx), AF_INET6, addr, dns.port());
    } else {
        auto& ipv4_addr = dns.in4().sin_addr.s_addr;
        std::array<uint8_t, 4> addr{};
        std::copy_n(reinterpret_cast<uint8_t*>(&ipv4_addr), 4, addr.begin());
        detail::send_dns_address(resolve_manager, static_cast<int32_t>(if_ndx), AF_INET, addr, dns.port());
    }

    // Configure routing domains
    detail::configure_domains(resolve_manager, static_cast<int32_t>(if_ndx), global);
}

