#include <cstdlib>

// Function to write user input to a file until user chooses to stop
void writeFileContents() {
    std::ofstream fileStream;
    char userInput[256];
    char continueChoice;

    fileStream.open("hello.txt");

    if (!fileStream.is_open()) {
        std::cerr << "Error: Cannot open file for writing." << std::endl;
        std::exit(EXIT_FAILURE);
    }

    do {
        std::cout << "Enter text to store: ";
        std::cin.getline(userInput, 256);
        fileStream << userInput << std::endl;

        std::cout << "Would you like to continue? (y/n): ";
        std::cin >> continueChoice;
        std::cin.ignore(); // Clear the newline from buffer

    } while (continueChoice == 'y' || continueChoice == 'Y');

    fileStream.close();
}

// Function to read and display file contents
void readFileContents() {
    std::ifstream inputStream;
    char character;

    std::cout << "The contents of the file are:" << std::endl;

    inputStream.open("hello.txt");

    if (!inputStream.is_open()) {
        std::cerr << "Error: Cannot open file for reading." << std::endl;
        std::exit(EXIT_FAILURE);
    }

    while (inputStream.get(character)) {
        std::cout << character;
    }

    inputStream.close();
}

int main() {
    writeFileContents();
    readFileContents();

    return 0;
}

#include "dap/io.h"
#include "dap/network.h"
#include "dap/protocol.h"
#include "dap/session.h"
#include <condition_variable>
#include <mutex>

int main(int, char*[]) {
    const int serverPort = 19021;

    // Function to handle new client connections
    auto onNewConnection =
        [&](const std::shared_ptr<dap::ReaderWriter>& connSocket) {
            auto debugSession = dap::Session::create();

            // Configure session behavior: close connection on malformed data
            debugSession->setOnInvalidData(dap::kClose);
            debugSession->bind(connSocket);

            // Handle Initialize request from client
            debugSession->registerHandler([&](const dap::InitializeRequest&) {
                dap::InitializeResponse reply;
                printf("Server received initialize request from client\n");
                return reply;
            });

            // State tracking for disconnection
            bool disconnectRequested = false;
            std::condition_variable signal;
            std::mutex mtx;  // protects 'disconnectRequested'

            // Handle Disconnect request from client
            debugSession->registerHandler([&](const dap::DisconnectRequest&) {
                std::lock_guard<std::mutex> guard(mtx);
                disconnectRequested = true;
                signal.notify_one();
                return dap::DisconnectResponse{};
            });

            // Wait for disconnection or timeout (5 seconds)
            std::unique_lock<std::mutex> lock(mtx);
            signal.wait_for(lock, std::chrono::seconds(5), 
                [&] { return disconnectRequested; });

            printf("Server closing connection\n");
        };

    // Error handling callback
    auto handleError = [&](const char* errorMessage) {
        printf("Server error: %s\n", errorMessage);
    };

    // Create and configure the server
    auto serverInstance = dap::net::Server::create();
    serverInstance->start(serverPort, onNewConnection, handleError);

    // Establish client-side connection
    auto clientSocket = dap::net::connect("localhost", serverPort);
    if (!clientSocket) {
        printf("Couldn't connect to server\n");
        return 1;
    }

    // Set up client session
    auto clientSession = dap::Session::create();
    clientSession->bind(clientSocket);

    // Send initialization request
    auto initFuture = clientSession->send(dap::InitializeRequest{});
    printf("Client sent initialize request to server\n");
    printf("Waiting for response from server...\n");

    // Process server's response
    auto initResponse = initFuture.get();
    printf("Response received from server\n");
    printf("Disconnecting...\n");

    // Terminate connection gracefully
    clientSession->send(dap::DisconnectRequest{});
    return 0;
}

