//----------------------------------------------------------------------------------
// Initializes the save message scene: sets up UI elements, starts DLC installation if needed,
// and schedules automatic navigation after 8 seconds.
//----------------------------------------------------------------------------------
HRESULT CScene_SaveMessage::OnInit(XUIMessageInit* pInitData, BOOL& bHandled)
{
    InitializeChildControls();

    CXuiSceneBase::ShowBackground(DEFAULT_XUI_MENU_USER, TRUE);
    CXuiSceneBase::ShowLogo(DEFAULT_XUI_MENU_USER, TRUE);

    m_button.SetText(app.GetString(IDS_CONFIRM_OK));
    m_SaveMessage.SetText(app.GetString(IDS_SAVE_ICON_MESSAGE));
    ui.SetTooltips(DEFAULT_XUI_MENU_USER, IDS_TOOLTIPS_SELECT);

    // Attempt to install DLC for any connected or signed-in user, if not already done
    bool dlcInstallNeeded = !app.DLCInstallProcessCompleted() && !app.DLCInstallPending();
    if (dlcInstallNeeded)
    {
        for (unsigned int userIndex = 0; userIndex < XUSER_MAX_COUNT; ++userIndex)
        {
            if (InputManager.IsPadConnected(userIndex) || ProfileManager.IsSignedIn(userIndex))
            {
                app.StartInstallDLCProcess(userIndex);
                break;
            }
        }
    }

    // Schedule auto-advance after 8 seconds
    XuiSetTimer(m_hObj, 0, 8000);
    m_bIgnoreInput = false;

    return S_OK;
}

