#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
using namespace std;

// Problem constraint: n * m <= 100000
// By ensuring rows <= columns, we bound rows <= sqrt(100000) ≈ 316
// Using a safe upper bound for arrays
const int MAX_ROWS = 350;

// Track which pairs of rows have been used together in any column
bool pair_used[MAX_ROWS][MAX_ROWS];
// Track how many other rows each row has been paired with (constraint count)
int pair_count[MAX_ROWS];

struct Coordinate {
    int row_idx;
    int col_idx;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int input_n, input_m;
    if (!(cin >> input_n >> input_m)) return 0;

    // Normalize so that rows <= columns for greedy efficiency
    bool dimensions_swapped = false;
    int rows = input_n;
    int cols = input_m;
    if (rows > cols) {
        swap(rows, cols);
        dimensions_swapped = true;
    }

    // Initialize random generator with fixed seed for deterministic behavior
    mt19937_64 rng(12345);

    // Prepare list of row indices
    vector<int> row_list(rows);
    iota(row_list.begin(), row_list.end(), 0);

    vector<Coordinate> output_points;

    // Process each column
    for (int current_col = 0; current_col < cols; ++current_col) {
        // Randomize row order to avoid bias
        shuffle(row_list.begin(), row_list.end(), rng);

        // Sort by constraint count (fewer constraints first)
        stable_sort(row_list.begin(), row_list.end(),
            [&](int r1, int r2) {
                return pair_count[r1] < pair_count[r2];
            });

        vector<int> selected_rows;
        // Greedy selection: pick rows that don't conflict with already-selected ones
        for (int r : row_list) {
            bool can_add = true;
            for (int prev_r : selected_rows) {
                if (pair_used[r][prev_r]) {
                    can_add = false;
                    break;
                }
            }
            if (can_add) {
                selected_rows.push_back(r);
            }
        }

        // Record points and update constraints
        for (size_t i = 0; i < selected_rows.size(); ++i) {
            int r1 = selected_rows[i];
            output_points.push_back({r1 + 1, current_col + 1});

            for (size_t j = i + 1; j < selected_rows.size(); ++j) {
                int r2 = selected_rows[j];
                pair_used[r1][r2] = true;
                pair_used[r2][r1] = true;
                pair_count[r1]++;
                pair_count[r2]++;
            }
        }
    }

    // Output results
    cout << output_points.size() << '\n';
    for (const auto& pt : output_points) {
        if (dimensions_swapped) {
            cout << pt.col_idx << ' ' << pt.row_idx << '\n';
        } else {
            cout << pt.row_idx << ' ' << pt.col_idx << '\n';
        }
    }

    return 0;
}

#include "test/jemalloc_test.h"

/*
 * GCC "-Walloc-size-larger-than" warning detects when one of the memory
 * allocation functions is called with a size larger than the maximum size that
 * they support. Here we want to explicitly test that the allocation functions
 * do indeed fail properly when this is the case, which triggers the warning.
 * Therefore we disable the warning for these tests.
 */
JEMALLOC_DIAGNOSTIC_PUSH
JEMALLOC_DIAGNOSTIC_IGNORE_ALLOC_SIZE_LARGER_THAN

TEST_BEGIN(test_overflow) {
    unsigned nlextents;
    size_t mib[4];
    size_t sz, miblen, max_size_class;
    void *p;

    // Get number of large extent classes
    sz = sizeof(unsigned);
    expect_d_eq(mallctl("arenas.nlextents", (void *)&nlextents, &sz, NULL, 0),
        0, "Unexpected mallctl() error");

    // Get MIB for arenas.lextent.0.size
    miblen = sizeof(mib) / sizeof(size_t);
    expect_d_eq(mallctlnametomib("arenas.lextent.0.size", mib, &miblen), 0,
        "Unexpected mallctlnametomib() error");

    // Set index to last extent class
    mib[2] = nlextents - 1;
    sz = sizeof(size_t);

    // Retrieve maximum size class
    expect_d_eq(mallctlbymib(mib, miblen, (void *)&max_size_class, &sz,
        NULL, 0), 0, "Unexpected mallctlbymib() error");

    // Test malloc with oversized requests
    expect_ptr_null(malloc(max_size_class + 1),
        "Expected OOM due to over-sized allocation request");
    expect_ptr_null(malloc(SIZE_T_MAX),
        "Expected OOM due to over-sized allocation request");

    // Test calloc with oversized requests
    expect_ptr_null(calloc(1, max_size_class + 1),
        "Expected OOM due to over-sized allocation request");
    expect_ptr_null(calloc(1, SIZE_T_MAX),
        "Expected OOM due to over-sized allocation request");

    // Allocate small block and test realloc to oversized sizes
    p = malloc(1);
    expect_ptr_not_null(p, "Unexpected malloc() OOM");
    expect_ptr_null(realloc(p, max_size_class + 1),
        "Expected OOM due to over-sized allocation request");
    expect_ptr_null(realloc(p, SIZE_T_MAX),
        "Expected OOM due to over-sized allocation request");

    free(p);
}
TEST_END

/* Re-enable the "-Walloc-size-larger-than=" warning */
JEMALLOC_DIAGNOSTIC_POP

int main(void) {
    return test(
        test_overflow);
}

#include "flock.h"
#include "file_lock.h"
#include "guard.h"
#include "tempfile.h"
#include <library/cpp/testing/unittest/registar.h>

Y_UNIT_TEST_SUITE(TFileLockTest) {
    Y_UNIT_TEST(TestFlock) {
        TTempFileHandle tmp("./file");
        UNIT_ASSERT_EQUAL(Flock(tmp.GetHandle(), LOCK_EX), 0);
        UNIT_ASSERT_EQUAL(Flock(tmp.GetHandle(), LOCK_UN), 0);
    }

    Y_UNIT_TEST(TestFileLocker) {
        TTempFileHandle tmp("./file.locker");
        TFileLock exclusiveLock1("./file.locker");
        TFileLock exclusiveLock2("./file.locker");
        TFileLock sharedLock1("./file.locker", EFileLockType::Shared);
        TFileLock sharedLock2("./file.locker", EFileLockType::Shared);
        TFileLock sharedLock3("./file.locker", EFileLockType::Shared);

        // First test: acquire and release exclusive lock via guard
        {
            TGuard<TFileLock> guard(exclusiveLock1);
        }

        // Second test: try to acquire already released exclusive lock
        {
            TTryGuard<TFileLock> tryGuard(exclusiveLock1);
            UNIT_ASSERT(tryGuard.WasAcquired());
        }

        // Third test: exclusive lock blocks another exclusive lock
        {
            TGuard<TFileLock> guard1(exclusiveLock1);
            TTryGuard<TFileLock> guard2(exclusiveLock2);
            UNIT_ASSERT(!guard2.WasAcquired());
        }

        // Fourth test: multiple shared locks can coexist
        {
            TGuard<TFileLock> guard1(sharedLock1);
            TTryGuard<TFileLock> guard2(sharedLock2);
            TTryGuard<TFileLock> guard3(sharedLock3);
            UNIT_ASSERT(guard2.WasAcquired());
            UNIT_ASSERT(guard3.WasAcquired());
        }

        // Fifth test: exclusive lock blocks all shared locks
        {
            TGuard<TFileLock> guard1(exclusiveLock1);
            TTryGuard<TFileLock> guard2(sharedLock1);
            TTryGuard<TFileLock> guard3(sharedLock2);
            UNIT_ASSERT(!guard2.WasAcquired());
            UNIT_ASSERT(!guard3.WasAcquired());
        }

        // Sixth test: shared lock allows other shared locks but blocks exclusive
        {
            TGuard<TFileLock> guard1(sharedLock1);
            TTryGuard<TFileLock> guard2(exclusiveLock1);
            TTryGuard<TFileLock> guard3(sharedLock2);
            UNIT_ASSERT(!guard2.WasAcquired());
            UNIT_ASSERT(guard3.WasAcquired());
        }
