int main() {
    // Initialize a vector with integers 1 through 5
    vector<int> v = {1, 2, 3, 4, 5};

    // Display original vector
    cout << "Original vector: ";
    for (int element : v) {
        cout << element << " ";
    }
    cout << endl;

    // Manually reverse the vector by swapping elements from both ends
    int left = 0;
    int right = v.size() - 1;
    while (left < right) {
        int temp = v[left];
        v[left] = v[right];
        v[right] = temp;
        left++;
        right--;
    }

    // Display reversed vector
    cout << "Reversed vector: ";
    for (int element : v) {
        cout << element << " ";
    }
    cout << endl;

    // Create another vector and reverse only its first 3 elements
    vector<int> v1 = {1, 2, 3, 4, 5};

    // Reverse first 3 elements manually
    int start = 0;
    int end = 2; // since we want to reverse indices 0, 1, 2 (first 3 elements)
    while (start < end) {
        int temp = v1[start];
        v1[start] = v1[end];
        v1[end] = temp;
        start++;
        end--;
    }

    // Display partially reversed vector
    cout << "Partially reversed vector: ";
    for (int element : v1) {
        cout << element << " ";
    }
    cout << endl;

    return 0;
}

