void verify_read_buffering_property()
{
  // Check unbuffered socket types
  ASIO_CHECK(!asio::is_read_buffered<
      asio::ip::tcp::socket>::value);

  // Check buffered read stream types
  ASIO_CHECK(!!asio::is_read_buffered<
      asio::buffered_read_stream<
        asio::ip::tcp::socket> >::value);

  // Check write-only buffered streams
  ASIO_CHECK(!asio::is_read_buffered<
      asio::buffered_write_stream<
        asio::ip::tcp::socket> >::value);

  // Check full buffered stream (read+write)
  ASIO_CHECK(!!asio::is_read_buffered<
      asio::buffered_stream<asio::ip::tcp::socket> >::value);

  // Repeat tests with custom mock stream
  ASIO_CHECK(!asio::is_read_buffered<mock_stream>::value);
  ASIO_CHECK(!!asio::is_read_buffered<
      asio::buffered_read_stream<mock_stream> >::value);
  ASIO_CHECK(!asio::is_read_buffered<
      asio::buffered_write_stream<mock_stream> >::value);
  ASIO_CHECK(!!asio::is_read_buffered<
      asio::buffered_stream<mock_stream> >::value);
}

ASIO_TEST_SUITE
(
  "is_read_buffered",
  ASIO_TEST_CASE(verify_read_buffering_property)
)

