    int first = v[0];
    int second = v[1];
    if (first > second) {
        cout << first << endl;
        cout << second << endl;
    } else {
        cout << second << endl;
        cout << first << endl;
    }

    // Swap the first two elements using a temporary variable
    int temp = v[0];
    v[0] = v[1];
    v[1] = temp;

    cout << "After swapping: ";
    for (int i = 0; i < v.size(); ++i) {
        cout << v[i] << " ";
    }
    cout << endl;

    // Find maximum and minimum elements in the vector
    int maxVal = v[0];
    int minVal = v[0];
    for (int i = 1; i < v.size(); ++i) {
        if (v[i] > maxVal) maxVal = v[i];
        if (v[i] < minVal) minVal = v[i];
    }
    cout << maxVal << endl;
    cout << minVal << endl;

    // Check if 6 exists in the vector by linear search
    bool found = false;
    for (int x : v) {
        if (x == 6) {
            found = true;
            break;
        }
    }
    cout << (found ? 1 : 0) << endl;

    // Count set bits using manual bit counting
    int n = 5;
    long int n2 = 5;
    long long n1 = 5;

    // Function to count set bits manually
    int countBits(int num) {
        int count = 0;
        while (num > 0) {
            count += num & 1;
            num >>= 1;
        }
        return count;
    }

    cout << countBits(n) << endl;
    cout << countBits(static_cast<int>(n2)) << endl;
    cout << countBits(static_cast<int>(n1)) << endl;

    return 0;
}

