// Simulating sol::var and sol::ref behavior using standard C++ constructs
template<typename T>
struct var_wrapper {
    T value;
    var_wrapper(T v) : value(v) {}
};

template<typename T>
struct ref_wrapper {
    T& reference;
    ref_wrapper(T& r) : reference(r) {}
};

struct test {
    static int muh_variable;
};
int test::muh_variable = 25;

int main() {
    std::cout << "=== static_variables ===" << std::endl;

    // Simulate sol::state with a simple map-like structure
    struct LuaState {
        struct Member {
            var_wrapper<int> direct;
            var_wrapper<int> global;     // Copy of the value
            ref_wrapper<int> ref_global; // Reference to the original variable

            Member(int d, int g, int& rg) 
                : direct(d), global(g), ref_global(rg) {}
        };

        Member test_obj{2, test::muh_variable, test::muh_variable};

        Member& get_class(const std::string&) { return test_obj; }
    };

    LuaState lua;

    // Accessing values similar to lua["test"]["direct"]
    int direct_value = lua.get_class("test").direct.value;
    // direct_value == 2
    if (direct_value != 2) {
        std::cerr << "Assertion failed: direct_value != 2" << std::endl;
        return 1;
    }
    std::cout << "direct_value: " << direct_value << std::endl;

    int global = lua.get_class("test").global.value;
    int global2 = lua.get_class("test").ref_global.reference;
    // global == 25
    // global2 == 25
    if (global != 25 || global2 != 25) {
        std::cerr << "Assertion failed: initial values incorrect" << std::endl;
        return 1;
    }

    std::cout << "First round of values --" << std::endl;
    std::cout << global << std::endl;
    std::cout << global2 << std::endl;

    // Modify the original variable
    test::muh_variable = 542;

    // Re-read values
    global = lua.get_class("test").global.value;   // Still holds old copy
    global2 = lua.get_class("test").ref_global.reference; // Sees updated value

    // global == 25 (unchanged because it's a copy)
    // global2 == 542 (reflects current value via reference)
    if (global != 25 || global2 != 542) {
        std::cerr << "Assertion failed: modified values incorrect" << std::endl;
        return 1;
    }

    std::cout << "Second round of values --" << std::endl;
    std::cout << "global : " << global << std::endl;
    std::cout << "global2: " << global2 << std::endl;
    std::cout << std::endl;

    return 0;
}

