FdServerTransport::FdServerTransport() : is_active(false) {
}

FdServerTransport::~FdServerTransport() {
    CloseConnection();
}

bool FdServerTransport::OpenConnection() {
    std::lock_guard<std::mutex> guard(io_mutex);
    if (is_active) {
        return true;
    }
    is_active = true;
    return true;
}

void FdServerTransport::CloseConnection() {
    std::lock_guard<std::mutex> guard(io_mutex);
    is_active = false;
}

bool FdServerTransport::IsActive() const {
    return is_active;
}

void FdServerTransport::Transmit(const MCPMessage &msg) {
    if (!IsActive()) {
        MCP_LOG_ERROR("stdio", "Transmit invoked without active connection");
        throw IOException("No active connection");
    }

    std::lock_guard<std::mutex> guard(io_mutex);
    try {
        std::string payload = msg.ToJSON();
        MCP_LOG_DEBUG("stdio", "Outgoing message preview: %s", payload.substr(0, 100).c_str());

        // Output to stdout and force immediate flush
        std::cout << payload << std::endl;
        std::cout.flush();

        MCP_LOG_DEBUG("stdio", "Message successfully transmitted and flushed");
    } catch (const std::exception &err) {
        MCP_LOG_ERROR("stdio", "Transmission failure: %s", err.what());
        throw IOException(std::string("Transmission failed: ") + err.what());
    }
}

MCPMessage FdServerTransport::Fetch() {
    if (!IsActive()) {
        MCP_LOG_ERROR("stdio", "Fetch invoked without active connection");
        throw IOException("No active connection");
    }

    std::lock_guard<std::mutex> guard(io_mutex);
    try {
        MCP_LOG_DEBUG("stdio", "Awaiting input from stdin...");

        std::string buffer;
        if (!std::getline(std::cin, buffer)) {
            MCP_LOG_DEBUG("stdio", "Input stream terminated (EOF or error)");
            throw IOException("Input stream ended unexpectedly");
        }

        MCP_LOG_DEBUG("stdio", "Received line (%zu bytes): %s", buffer.size(), buffer.substr(0, 100).c_str());

        if (buffer.empty()) {
            MCP_LOG_WARN("stdio", "Empty line received");
            throw IOException("Empty message received");
        }

        return MCPMessage::FromJSON(buffer);
    } catch (const IOException &) {
        throw;
    } catch (const std::exception &err) {
        MCP_LOG_ERROR("stdio", "Message reception or parsing error: %s", err.what());
        throw IOException(std::string("Failed to receive message: ") + err.what());
    }
}

