#include <iostream>
#include <vector>
#include <map>
#include <cstdlib>
using namespace std;

// Maximum size of the array as per problem constraints
const int MAX_SIZE = 200005;
// Array to store the final result
int resultArray[MAX_SIZE];
// Map to remember the leftmost occurrence of each distinct value
map<int, int> firstOccurrence;

/**
 * Recursive function to determine values in the range [left, right]
 * Uses divide-and-conquer with pruning based on sorted array properties and known positions.
 */
void processRange(int left, int right) {
    // Skip already filled positions from the left
    while (left <= right && resultArray[left] != 0) {
        left++;
    }
    // Skip already filled positions from the right
    while (right >= left && resultArray[right] != 0) {
        right--;
    }

    // Base case: no valid range left to process
    if (left > right) return;

    // Perform interactive query for current range
    cout << "? " << left << " " << right << endl;
    int value, frequency;
    cin >> value >> frequency;

    if (value == -1) exit(0); // Error handling for invalid response

    // If all elements in the range are the same
    if (frequency == right - left + 1) {
        for (int idx = left; idx <= right; ++idx) {
            resultArray[idx] = value;
        }
        firstOccurrence[value] = left;
        return;
    }

    // Anchor optimization: use previously recorded position of 'value'
    if (firstOccurrence.find(value) != firstOccurrence.end()) {
        int knownPos = firstOccurrence[value];

        if (knownPos < left) {
            // Value appears before current range, so must start at 'left'
            for (int i = 0; i < frequency; ++i) {
                resultArray[left + i] = value;
            }
            firstOccurrence[value] = left;
            processRange(left + frequency, right);
            return;
        } else if (knownPos > right) {
            // Value appears after current range, so must end at 'right'
            for (int i = 0; i < frequency; ++i) {
                resultArray[right - i] = value;
            }
            firstOccurrence[value] = right;
            processRange(left, right - frequency);
            return;
        }
    }

    // No optimization possible: split the range and recurse
    int center = (left + right) / 2;
    processRange(left, center);
    processRange(center + 1, right);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    // Initialize array to zero (unfilled)
    for (int i = 0; i < MAX_SIZE; ++i) resultArray[i] = 0;

    // Process the entire array
    processRange(1, n);

    // Output the reconstructed array
    cout << "! ";
    for (int i = 1; i <= n; ++i) {
        cout << resultArray[i];
        if (i < n) cout << " ";
    }
    cout << endl;

    return 0;
}

