// Entry point function called by the Gorgon engine instead of standard main()
int Main(const std::vector<std::string> &args) {
    // Initialize the engine with a unique application identifier
    Gorgon::Initialize("Shooter");

    // Create a scene manager responsible for managing active scenes
    // Configure window in fullscreen mode with specified title
    Gorgon::SceneManager sceneManager(Gorgon::Window::Fullscreen, "Shooter");

    // Set up the UI system with a custom scaling factor (4 instead of default 7.5)
    // This ensures consistent UI element sizing across various display resolutions
    Gorgon::UI::Initialize(4);

    // Register available game scenes: main menu and gameplay
    sceneManager.NewScene<MainMenu>(MAIN_MENU);
    sceneManager.NewScene<Game>(GAME_SCENE);

    // Activate the initial scene (main menu) before starting the game loop
    sceneManager.SwitchScene(MAIN_MENU);

    // Begin the main game loop; this call blocks until the user exits
    // Internally handles frame updates and rendering at ~60 FPS
    sceneManager.Run();

    return 0;
}

#include <algorithm>
#include <yams/search/search_filters.h>

namespace yams::search {

bool SearchFilters::matches(const SearchResultItem& item) const {
    // Check each filter category; early exit if any filter fails
    // Date-based filtering logic
    for (const auto& df : dateFilters_) {
        std::chrono::system_clock::time_point checkDate;
        switch (df.field) {
            case DateRangeFilter::DateField::LastModified:
                checkDate = item.lastModified;
                break;
            case DateRangeFilter::DateField::Created:
                // Fallback to lastModified if created date is unavailable
                checkDate = item.lastModified;
                break;
            case DateRangeFilter::DateField::Indexed:
                checkDate = item.indexedAt;
                break;
        }
        if (!df.check(checkDate)) {
            return false;
        }
    }

    // Size-based filtering
    for (const auto& sf : sizeFilters_) {
        if (!sf.check(item.fileSize)) {
            return false;
        }
    }

    // Content type filtering
    for (const auto& ct : contentTypeFilters_) {
        if (!ct.check(item.contentType)) {
            return false;
        }
    }

    // Language filtering
    for (const auto& lang : languageFilters_) {
        if (!lang.check(item.detectedLanguage, item.languageConfidence)) {
            return false;
        }
    }

    // Path-based filtering
    for (const auto& pf : pathFilters_) {
        if (!pf.check(item.path)) {
            return false;
        }
    }

    // Metadata filtering
    for (const auto& mf : metadataFilters_) {
        if (!mf.check(item.metadata)) {
            return false;
        }
    }

    // Relevance score filtering
    for (const auto& rf : relevanceFilters_) {
        if (!rf.check(item.relevanceScore)) {
            return false;
        }
    }

    // Custom user-defined filters
    for (const auto& cf : customFilters_) {
        if (!cf(item)) {
            return false;
        }
    }

    return true;
}

std::vector<SearchResultItem>
SearchFilters::apply(const std::vector<SearchResultItem>& results) const {
    if (!hasAnyFilters()) {
        return results; // No filters defined — return original list unchanged
    }

    std::vector<SearchResultItem> output;
    output.reserve(results.size());

    for (const auto& res : results) {
        if (matches(res)) {
            output.push_back(res);
        }
    }

    return output;
}

} // namespace yams::search

