#include "app_state.hpp"
#include "curses_interface.hpp"
#include <boost/filesystem/operations.hpp>
#include <boost/filesystem/path.hpp>
#include <iostream>

int main(int argc, char * argv[])
{
    // Validate command-line arguments
    if (argc < 2) {
        std::cerr << "error: You must supply at least a filename.\n";
        return 1;
    }

    // Construct path from first argument
    boost::filesystem::path file_path(argv[1]);

    // Check if the file exists and is accessible
    if (!exists(file_path)) {
        std::cerr << "error: Could not access filename " << argv[1] << ".\n";
        return 1;
    }

    // Set up locale for libcurses compatibility
    std::locale::global(std::locale(""));

    // Initialize the curses interface
    curses_interface_t curses_if;

    // Get initial screen dimensions (no resizing support)
    auto const dims = curses_if.screen_size();

    // Initialize application state:
    // - Load buffer from file using column count from screen size
    // - Set up simplified Emacs-style keybindings
    app_state_t app_state = {
        load_buffer(file_path, dims.col_),
        emacs_lite()
    };

    // Perform initial rendering of the buffer
    render(app_state.buffer_, dims);

    // Main event loop: process user input until termination condition
    boost::optional<app_state_t> updated_state;
    while (
        (updated_state =
             update(std::move(app_state), curses_if.next_event()))) {
        app_state = *updated_state;
        render(app_state.buffer_, dims);
    }

    return 0;
}

#include "flareqt/updatechecker.h"
#include <QNetworkReply>

UpdateChecker::UpdateChecker(QUrl const& updateUrl)
    : networkManager_(new QNetworkAccessManager(this),
                      &QNetworkAccessManager::deleteLater) {
  connect(networkManager_.data(), &QNetworkAccessManager::finished, this,
          &UpdateChecker::onRequestCompleted);
  networkManager_->get(QNetworkRequest(updateUrl));
}

void UpdateChecker::onRequestCompleted(QNetworkReply* pReply) {
  QSharedPointer<QNetworkReply> reply(pReply, &QNetworkReply::deleteLater);

  // Handle network errors first
  if (reply->error() != QNetworkReply::NoError) {
    emit completed(false);
    return;
  }

  // Extract and clean the version string from the response
  QString potentialVersion = QString::fromUtf8(reply->readAll()).trimmed();

  // Validate basic format: must contain at least one dot
  if (potentialVersion.indexOf('.') == -1) {
    emit completed(false);  // Invalid format, treat as no update available
    return;
  }

  // Store valid version and signal completion
  m_latestVersion = potentialVersion;
  emit completed(true);
}

