namespace at {
namespace AtenTypeXPU {

// Helper: Determine whether tensor metadata dtype matches context-stored dtype
inline bool needs_dtype_reconstruction(const at::Tensor& t) {
    return !check_equality_for_meta_dtype_and_ctx_dtype(t);
}

at::Tensor DPCPPTensorConvertor::to_plain(const at::Tensor& src) {
    // Early exit if not an opaque tensor
    if (!is_opaque_tensor(src)) {
        return src;
    }

    at::Tensor working_tensor = src;

    // Check if reconstruction is needed due to dtype mismatch between meta and context
    const bool requires_recon = needs_dtype_reconstruction(src);

    if (requires_recon) {
        // Reconstruct tensor with correct dtype inferred from context
        auto reconstructed_opts = src.options().dtype(opaqueTypeToScalarType(src));
        working_tensor = at::empty_like(src, reconstructed_opts);
        unsafe_get_and_set_data_ptr(src, working_tensor);
    }

    // Prepare destination tensor with same shape/layout as working_tensor
    at::Tensor dst = at::empty_like(working_tensor);

    // Extract context and metadata for layout info
    auto* ctx_ptr = static_cast<DPCPPTensorContext*>(
        working_tensor.unsafeGetTensorImpl()->storage().data_ptr().get_context());
    DPCPPTensorContext ctx_copy = *ctx_ptr;
    auto layout_info = ctx_copy.aten_meta();

    // Share storage and set strides on dst to match desired layout
    at::Tensor dst_laid_out = share_storage_and_set_strided_as(
        dst, layout_info.sizes_, layout_info.strides_, c10::nullopt);

    // Perform reorder operation using native oneDNN API
    kernels::xpu::oneDNN::reorder(working_tensor, dst_laid_out);

    if (requires_recon) {
        // Restore original tensor's meta on dst by reconstructing again
        dst = at::empty_like(src);

        // Transfer ownership of context from laid-out dst back to final dst
        unsafe_release_and_set_data_ptr(dst_laid_out, dst);

        // Explicitly release context from temporary working_tensor
        working_tensor.unsafeGetTensorImpl()
            ->storage()
            .unsafeGetStorageImpl()
            ->mutable_data_ptr()
            .release_context();
    }

    return dst;
}

at::Tensor DPCPPTensorConvertor::to_plain_(at::Tensor& input) {
    if (!is_opaque_tensor(input)) {
        return input;
    }

    // Convert to plain format
    at::Tensor plain_tensor = to_plain(input);

    // Move context from result to original tensor
    auto new_ctx = DPCPPTensorContext::get_tensor_ctx(plain_tensor);
    DPCPPTensorContext::set_tensor_ctx(input, std::move(new_ctx));

    return input;
}

} // namespace AtenTypeXPU
} // namespace at

