    // Helper to collect all players except self
    static std::vector<Player> CollectValidRemotePlayers()
    {
        std::vector<Player> result;
        const auto& allPlayers = Players::GetPlayers();
        result.reserve(allPlayers.size());

        for (auto iter = allPlayers.begin(); iter != allPlayers.end(); ++iter)
        {
            const Player& player = iter->second;
            if (!player.IsValid())
                continue;

            const Player& localPlayer = Self::GetPlayer();
            if (localPlayer.IsValid() && player.GetId() == localPlayer.GetId())
                continue;

            result.push_back(player);
        }

        return result;
    }

