#include <pthread.h>
#include "libcgo.h"

void x_cgo_getstackbound(uintptr bounds[2]) {
    pthread_attr_t attr;
    void *stack_addr = nullptr;
    size_t stack_size = 0;

    // Initialize the attribute structure
    pthread_attr_init(&attr);

#if defined(__GLIBC__) || defined(__BIONIC__) || (defined(__sun) && !defined(__illumos__))
    // Use GNU extension or Solaris-specific function to get thread attributes
    pthread_getattr_np(pthread_self(), &attr);  // GNU extension
    pthread_attr_getstack(&attr, &stack_addr, &stack_size);
#elif defined(__illumos__)
    // Illumos-specific alternative
    pthread_attr_get_np(pthread_self(), &attr);
    pthread_attr_getstack(&attr, &stack_addr, &stack_size);
#else
    // Fallback: no reliable way to obtain stack bounds; set to zero
    stack_addr = nullptr;
    stack_size = 0;
#endif

    // Clean up attribute object
    pthread_attr_destroy(&attr);

    // Synchronize with TSAN for Go runtime stack management
    _cgo_tsan_acquire();
    bounds[0] = reinterpret_cast<uintptr>(stack_addr);
    bounds[1] = bounds[0] + stack_size;
    _cgo_tsan_release();
}

