// Wraps angle to [-180, 180) degrees for float input
float Math::wrapDegrees(float input)
{
	// Normalize to [0, 360)
	input = fmodf(input, 360.0f);
	if (input < 0.0f) input += 360.0f;

	// Shift to [-180, 180)
	if (input >= 180.0f) input -= 360.0f;

	return input;
}

// Wraps angle to [-180, 180) degrees for double input
double Math::wrapDegrees(double input)
{
	// Normalize to [0, 360)
	input = fmod(input, 360.0);
	if (input < 0.0) input += 360.0;

	// Shift to [-180, 180)
	if (input >= 180.0) input -= 360.0;

	return input;
}

