int sendmmsg(int fd, struct mmsghdr *msgvec, unsigned int vlen, unsigned int flags)
{
#if LONG_MAX > INT_MAX
	/* Alternative implementation avoiding direct syscall due to type mismatches */
	int count = 0;
	if (vlen > IOV_MAX) vlen = IOV_MAX; /* Kernel behavior: cap at IOV_MAX */
	if (!vlen) return 0;

	for (int idx = 0; idx < vlen; idx++) {
		/* Convert sendmsg result to msg_len field */
		ssize_t result = sendmsg(fd, &msgvec[idx].msg_hdr, flags);
		if (result < 0) break;
		msgvec[idx].msg_len = (unsigned int)result;
		count++;
	}

	return count ? count : -1;
#else
	return syscall_cp(SYS_sendmmsg, fd, msgvec, vlen, flags);
#endif
}

