    std::string path2 = FLAGS_store_path + folder2;

    try {
        // Process first folder
        if (std::filesystem::exists(path1)) {
            std::cout << "Detected folder: " << folder1 
                      << ", proceeding with removal..." << std::endl;

            std::uintmax_t bytes_removed = std::filesystem::remove_all(path1);
