// Calculate the sum from 1 to 5 using a while loop instead of for loop
int main() {
    int total = 0;
    int counter = 1;
    while (counter <= 5) {
        total += counter;
        ++counter;
    }
    std::cout << total << std::endl;
    return 0;
}

