#include "jemalloc/internal/jemalloc_preamble.h"
#include "jemalloc/internal/jemalloc_internal_includes.h"
#include "jemalloc/internal/prof_stats.h"

bool opt_prof_stats = false;
malloc_mutex_t prof_stats_mtx;

// Storage for current (live) and cumulative statistics
static prof_stats_t current_stats[PROF_SC_NSIZES];
static prof_stats_t cumulative_stats[PROF_SC_NSIZES];

// Acquire lock for statistics access
static void 
acquire_stats_lock(tsd_t *tsd, szind_t size_index) {
    assert(opt_prof && opt_prof_stats);
    assert(size_index < SC_NSIZES);
    malloc_mutex_lock(tsd_tsdn(tsd), &prof_stats_mtx);
}

// Release lock after statistics operation
static void 
release_stats_lock(tsd_t *tsd) {
    malloc_mutex_unlock(tsd_tsdn(tsd), &prof_stats_mtx);
}

// Update statistics when allocation occurs
void 
prof_stats_inc(tsd_t *tsd, szind_t size_index, size_t requested_size) {
    cassert(config_prof);
    acquire_stats_lock(tsd, size_index);

    // Increment both live and cumulative counters
    current_stats[size_index].req_sum += requested_size;
    current_stats[size_index].count++;
    cumulative_stats[size_index].req_sum += requested_size;
    cumulative_stats[size_index].count++;

    release_stats_lock(tsd);
}

// Update statistics when deallocation occurs
void 
prof_stats_dec(tsd_t *tsd, szind_t size_index, size_t requested_size) {
    cassert(config_prof);
    acquire_stats_lock(tsd, size_index);

    // Decrement only live counter (cumulative remains)
    current_stats[size_index].req_sum -= requested_size;
    current_stats[size_index].count--;

    release_stats_lock(tsd);
}

// Retrieve current (live) statistics
void 
prof_stats_get_live(tsd_t *tsd, szind_t size_index, prof_stats_t *output_stats) {
    cassert(config_prof);
    acquire_stats_lock(tsd, size_index);

    // Copy live statistics to output buffer
    memcpy(output_stats, &current_stats[size_index], sizeof(prof_stats_t));

    release_stats_lock(tsd);
}

// Retrieve cumulative statistics
void 
prof_stats_get_accum(tsd_t *tsd, szind_t size_index, prof_stats_t *output_stats) {
    cassert(config_prof);
    acquire_stats_lock(tsd, size_index);

    // Copy cumulative statistics to output buffer
    memcpy(output_stats, &cumulative_stats[size_index], sizeof(prof_stats_t));

    release_stats_lock(tsd);
}

