#include "BufferProcessor.hpp"
#include "Buffer.hpp"
#include "MayaFlux/Journal/Archivist.hpp"

namespace MayaFlux::Buffers {

void BufferProcessor::process(const std::shared_ptr<Buffer>& buffer)
{
    if (!buffer->attempt_acquire_for_processing()) {
        MF_RT_ERROR(Journal::Component::Buffers, Journal::Context::BufferProcessing,
            "Buffer is currently in use by another processor; skipping this operation");
        return;
    }

    m_processing_in_progress.fetch_add(1, std::memory_order_acquire);

    try {
        execute_buffer_processing(buffer);
    } catch (...) {
        buffer->finish_processing();
        m_processing_in_progress.fetch_sub(1, std::memory_order_release);
        throw;
    }

    buffer->finish_processing();
    m_processing_in_progress.fetch_sub(1, std::memory_order_release);
}

void BufferProcessor::process_non_owning(const std::shared_ptr<Buffer>& buffer)
{
    m_processing_in_progress.fetch_add(1, std::memory_order_acquire);

    try {
        execute_buffer_processing(buffer);
    } catch (...) {
        m_processing_in_progress.fetch_sub(1, std::memory_order_release);
        throw;
    }

    m_processing_in_progress.fetch_sub(1, std::memory_order_release);
}

}

#include <algorithm>
#include <climits>

class Solution {
public:
    int binaryGap(unsigned n) {
        if (n == 0 || (n & (n - 1)) == 0) return 0; // 0 or power of 2 has no gap

        int max_gap = 0;
        int prev_position = -1;

        for (int bit_pos = 0; bit_pos < 32; ++bit_pos) {
            if ((n >> bit_pos) & 1) {  // check if bit at position bit_pos is set
                if (prev_position != -1) {
                    max_gap = std::max(max_gap, bit_pos - prev_position);
                }
                prev_position = bit_pos;
            }
        }

        return max_gap;
    }
};

