#include <boost/capy/test/thread_name.hpp>
#include "test_helpers.hpp"

namespace boost {
namespace capy {

// Thread name test suite implementation with platform-specific behavior
struct thread_name_test_impl
{
    void
    verify_thread_naming()
    {
#if defined(BOOST_CAPY_TEST_CAN_GET_THREAD_NAME)
        // Basic naming test
        set_current_thread_name("primary-worker");
        BOOST_TEST(check_thread_name("primary-worker"));

        // Pool-style naming
        set_current_thread_name("capy-service-1");
        BOOST_TEST(check_thread_name("capy-service-1"));

        // Long name handling across platforms
        const char* long_name = 
            "excessively-long-thread-name-that-goes-beyond-platform-limits";
        set_current_thread_name(long_name);

#if defined(__linux__) || defined(__FreeBSD__) || defined(__NetBSD__)
        // POSIX systems typically limit to 15 characters
        BOOST_TEST(check_thread_name("excessively-long-"));
#elif defined(__APPLE__)
        // macOS allows up to 63 characters
        BOOST_TEST(check_thread_name(
            "excessively-long-thread-name-that-goes-beyond-platform-limits"));
#elif defined(_WIN32)
        // Windows supports longer names
        BOOST_TEST(check_thread_name(
            "excessively-long-thread-name-that-goes-beyond-platform-limits"));
#endif

        // macOS-specific 63-character boundary check
        const char* macos_boundary_name =
            "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789ABCDEF";
        set_current_thread_name(macos_boundary_name);

#if defined(__APPLE__)
        // Should be truncated at 63 chars
        BOOST_TEST(check_thread_name(
            "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789ABC"));
#endif

#if defined(_WIN32)
        // Windows UTF-8 compatibility verification
        set_current_thread_name("io-handler-2");
        BOOST_TEST(check_thread_name("io-handler-2"));
#endif
#endif // BOOST_CAPY_TEST_CAN_GET_THREAD_NAME

        // Edge case: empty string (should not cause crash)
        set_current_thread_name("");
    }

    void
    execute_tests()
    {
        verify_thread_naming();
    }
};

// Register the test suite with Boost.Test framework
TEST_SUITE(
    thread_name_test_impl,
    "boost.capy.thread_name");
} // capy
} // boost

