#include <hip/hip_runtime.h>
#include <cstddef>
#include <cstdlib>
#include <iostream>

#define HIP_ERROR_CHECK(op)                                      \
    do {                                                         \
        hipError_t err = (op);                                   \
        if (err != hipSuccess) {                                 \
            std::cerr << "HIP runtime error: " << err             \
                      << " (" << hipGetErrorString(err) << ")"    \
                      << " in " << __FILE__ << " at line "        \
                      << __LINE__ << std::endl;                   \
            std::exit(EXIT_FAILURE);                             \
        }                                                        \
    } while(0)

int main() {
    hipMemPool_t poolHandle;
    int devId = 0; // Select GPU device 0

    // Set the active device
    HIP_ERROR_CHECK(hipSetDevice(devId));

    // Retrieve the default memory pool associated with the device
    HIP_ERROR_CHECK(hipDeviceGetDefaultMemPool(&poolHandle, devId));

    // Request a 1 MiB buffer from global heap
    const std::size_t bytesRequested = 1024 * 1024;
    void* devicePtr = nullptr;
    HIP_ERROR_CHECK(hipMalloc(&devicePtr, bytesRequested));

    // Release the buffer back to the system
    HIP_ERROR_CHECK(hipFree(devicePtr));

    // Reduce the pool's committed memory footprint to 512 KiB
    const std::size_t targetSize = 512 * 1024;
    HIP_ERROR_CHECK(hipMemPoolTrimTo(poolHandle, targetSize));

    std::cout << "Memory pool successfully trimmed to "
              << targetSize << " bytes." << std::endl;

    return EXIT_SUCCESS;
}

