#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>

int n;
std::vector<std::vector<int>> inv_parity;

// Helper function to safely access inversion parity for range [l, r]
int get_inversion(int l, int r) {
    if (l >= r) return 0;
    return inv_parity[l][r];
}

// Compute whether element at position i is greater than element at position j
// using XOR-based inclusion-exclusion on inversion counts
int compare_positions(int i, int j) {
    // Inversion parity for [i,j] minus inversions that don't involve both endpoints
    int result = get_inversion(i, j);
    result ^= get_inversion(i + 1, j);
    result ^= get_inversion(i, j - 1);
    result ^= get_inversion(i + 1, j - 1);
    return result;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::cin >> n;

    // Handle trivial case
    if (n == 1) {
        std::cout << "1 1\n";
        return 0;
    }

    // Initialize data structure for inversion parities
    inv_parity.resize(n + 2, std::vector<int>(n + 2, 0));

    // Query all subarrays to get inversion parities
    for (int left = 1; left <= n; ++left) {
        for (int right = left + 1; right <= n; ++right) {
            std::cout << "0 " << left << " " << right << "\n";
            std::cin >> inv_parity[left][right];
        }
    }

    // Create array of positions
    std::vector<int> pos(n);
    std::iota(pos.begin(), pos.end(), 1);

    // Sort positions based on the actual values in the permutation
    std::stable_sort(pos.begin(), pos.end(), [&](int a, int b) {
        if (a == b) return false;

        // Determine if value at position a is less than value at position b
        if (a < b) {
            // If there's no inversion between a and b (value_a < value_b)
            return compare_positions(a, b) == 0;
        } else {
            // When a > b, check if value_a < value_b by checking inversion at (b,a)
            return compare_positions(b, a) == 1;
        }
    });

    // Build the permutation: pos[i] is the position where value i+1 appears
    std::vector<int> perm(n + 1);
    for (int idx = 0; idx < n; ++idx) {
        perm[pos[idx]] = idx + 1;
    }

    // Output the reconstructed permutation
    std::cout << "1 ";
    for (int i = 1; i <= n; ++i) {
        std::cout << perm[i];
        if (i < n) std::cout << " ";
    }
    std::cout << "\n";

    return 0;
}

