int main() {
    std::cout << "=== tables ===" << std::endl;

    sol::state lua;

    // Initialize Lua tables: one as an array, another with nested structure
    lua.script(R"(table1 = {"hello", "world"})");
    lua.script(R"(
        table2 = {
            ["nestedTable"] = {
                ["key1"] = "valueA",
                ["key2"] = "valueB",
            },
            ["name"] = "example_table"
        }
    )");

    // Retrieve top-level table and nested sub-table
    sol::table t2 = lua["table2"];
    sol::table nested = t2["nestedTable"];

    // Access values using different syntaxes
    std::string val1 = nested["key1"];
    std::string val2 = lua["table2"]["nestedTable"]["key2"];

    std::cout << "nested table: key1 : "
              << val1
              << ", key2: " << val2 << '\n';

    // Extract name from table2 using two approaches
    std::string tableName1 = t2.get<std::string>("name");
    std::string tableName2 = t2["name"];

    std::cout << "name of t2: " << tableName1 << '\n';
    std::cout << "name of t2 (alt): " << tableName2 << '\n';

    // Alternative longer syntax for table1 access
    sol::table arr = lua.get<sol::table>("table1");
    std::cout << arr.get<std::string>(1) << " "
              << arr.get<std::string>(2) << '\n';

    // Direct chained access for nested values
    std::cout << "nested table (chained): key1 : "
              << lua.get<sol::table>("table2")
                     .get<sol::table>("nestedTable")
                     .get<std::string>("key1")
              << ", key2: "
              << lua["table2"]["nestedTable"]["key2"]
              << '\n';

    std::cout << std::endl;
    return 0;
}

