#include "ByteArrayInputStream.h"
#include <cstddef>
#include "util/console/ArrayWithLength.h"
#include "win/extraX64.h"

// Constructor: initializes stream with a buffer, offset, and length
ByteArrayInputStream::ByteArrayInputStream(
    byteArray    inputBuffer,
    unsigned int startOffset,
    unsigned int maxLength
)
: pos(startOffset),
  count(std::min(startOffset + maxLength, inputBuffer.length)),
  mark(startOffset) {
    buf = inputBuffer;
}

// Constructor: creates stream using entire buffer (offset=0, count=length)
ByteArrayInputStream::ByteArrayInputStream(byteArray inputBuffer)
: pos(0),
  count(inputBuffer.length),
  mark(0) {
    buf = inputBuffer;
}

// Reads one byte from the stream; returns -1 if no data remains
int ByteArrayInputStream::read() {
    if (pos >= count) return -1;
    return buf[pos++];
}

// Reads bytes into provided buffer b (equivalent to read(b, 0, b.length))
int ByteArrayInputStream::read(byteArray destBuffer) { 
    return read(destBuffer, 0, destBuffer.length); 
}

// Reads up to 'length' bytes into destBuffer starting at 'offset'
int ByteArrayInputStream::read(
    byteArray    destBuffer,
    unsigned int destOffset,
    unsigned int maxBytes
) {
    if (pos == count) return -1;

    // Determine how many bytes can actually be read
    int bytesRead = std::min(static_cast<int>(maxBytes), count - pos);

    // Copy data from internal buffer to destination
    XMemCpy(&destBuffer[destOffset], &buf[pos], bytesRead);

    // Advance position and return actual bytes read
    pos += bytesRead;
    return bytesRead;
}

// No-op: closing this stream has no effect
void ByteArrayInputStream::close() { }

// Skips up to 'n' bytes forward in the stream
std::int64_t ByteArrayInputStream::skip(std::int64_t n) {
    std::int64_t proposedPos = pos + n;

    // Clamp to valid range [pos, count]
    if (proposedPos > count) proposedPos = count;

    std::int64_t skipped = proposedPos - pos;
    pos = static_cast<unsigned int>(proposedPos);

    return skipped;
}

// Destructor: releases allocated memory if present
ByteArrayInputStream::~ByteArrayInputStream() {
    if (buf.data != nullptr) {
        delete[] buf.data;
        buf.data = nullptr;
    }
}

