// Custom interop check: adapted to use sol2's stack utilities more explicitly
template <typename T>
inline bool is_tolua_player(sol::state_view& lua, int index) {
	std::string typeName = sol::detail::short_demangle<T>();
	tolua_Error err {};
	return tolua_isusertype(lua.lua_state(), index, typeName.c_str(), 0, &err) == 1;
}

// Register functions callable from Lua using raw sol2 bindings
void setup_lua_bindings(sol::state_view& lua) {
	lua.set_function("f", [](sol::this_state s) -> int {
		lua_State* L = s;
		int nargs = lua_gettop(L);

		if (nargs < 1 || nargs > 2) {
			luaL_error(L, "Function 'f' expects 1 or 2 arguments");
			return 0;
		}

		// Check if first arg is a Player*
		if (!is_tolua_player<Player>(lua, 1)) {
			luaL_error(L, "First argument must be a Player instance");
			return 0;
		}

		Player* p = static_cast<Player*>(tolua_tousertype(L, 1, nullptr));
		if (!p) {
			luaL_error(L, "Invalid Player pointer");
			return 0;
		}

		if (nargs == 1) {
			std::cout << "calling 1-argument version with "
			             "tolua-created Player { health:"
			          << p->getHealth() << " }" << std::endl;
			SOL_ASSERT(p->getHealth() == 4);
		} else {
			int secondArg = lua_tointeger(L, 2);
			std::cout << "calling 2-argument version with "
			             "tolua-created Player { health: "
			          << p->getHealth()
			          << " } and integer argument of "
			          << secondArg << std::endl;
			SOL_ASSERT(p->getHealth() == 4);
			SOL_ASSERT(secondArg == 5);
		}
		return 0;
	});
}

// Verify object state using sol2
void validate_object(sol::state_view& lua) {
	sol::optional<Player&> maybePlayer = lua["obj"];
	if (!maybePlayer) {
		SOL_ASSERT(false && "Expected 'obj' to exist in Lua");
	}
	Player& player = *maybePlayer;
	SOL_ASSERT(player.getHealth() == 4);
}

int main(int, char*[]) {
	std::cout << "=== interop example (tolua) ===" << std::endl;
	std::cout << "(code lifted from a sol2 user's use case: "
	             "https://github.com/ThePhD/sol2/issues/"
	             "511#issuecomment-331729884)"
	          << std::endl;

	lua_State* luaVM = luaL_newstate();
	luaL_openlibs(luaVM);   // Initialize standard libraries
	tolua_open(luaVM);      // Initialize tolua core
	tolua_Player_open(luaVM); // Expose Player class to Lua

	sol::state_view lua(luaVM);
	setup_lua_bindings(lua);

	const char* script = R"(
obj = Player:new()
obj:setHealth(4)
f(obj) -- invoke 1-arg overload
f(obj, 5) -- invoke 2-arg overload
)";

	if (luaL_dostring(luaVM, script)) {
		lua_error(luaVM);
	}

	validate_object(lua);

	lua_close(luaVM);
	return 0;
}

