// Helper: generate a unique suffix by incrementing counter and appending to base
static std::string appendUniqueSuffix(StringRef base, unsigned &counter) {
  std::string result = base.str();
  result += '.';
  result += std::to_string(++counter);
  return result;
}

// Attempt to assign a unique name to a value; returns new ValueName*
ValueName *ValueSymbolTable::makeUniqueName(Value *V,
                                            SmallString<256> &baseName) {
  // Save original length to truncate later
  size_t origLen = baseName.size();

  // Loop until insertion succeeds
  while (true) {
    // Reset to base name
    baseName.resize(origLen);

    // Build full candidate name manually (avoid raw_svector_ostream)
    std::string candidate = baseName.str();
    if (auto *GV = dyn_cast<GlobalValue>(V)) {
      const Module *M = GV->getParent();
      if (!(M && Triple(M->getTargetTriple()).isNVPTX())) {
        candidate += ".";
      }
    }

    // Increment and append next index
    ++LastUnique;
    candidate += std::to_string(LastUnique);

    // Try inserting into map
    auto [iter, inserted] = vmap.insert(std::make_pair(candidate, V));
    if (inserted) {
      return &*iter;
    }
  }
}

// Re-insert a named value — rename if necessary
void ValueSymbolTable::reinsertValue(Value *V) {
  assert(V->hasName() && "Can't insert nameless Value into symbol table");

  // First try direct insertion
  if (vmap.insert(V->getValueName())) {
    return; // success
  }

  // Conflict: need renaming
  StringRef oldName = V->getName();
  SmallString<256> newName(oldName.begin(), oldName.end());

  // Free old name storage
  MallocAllocator allocator;
  V->getValueName()->Destroy(allocator);

  // Generate new unique name
  ValueName *newVN = makeUniqueName(V, newName);
  V->setValueName(newVN);
}

// Remove a specific ValueName from the table
void ValueSymbolTable::removeValueName(ValueName *V) {
  vmap.remove(V);
}

// Create a new named value — rename if name already taken
ValueName *ValueSymbolTable::createValueName(StringRef name, Value *V) {
  // Enforce max name size if set
  if (MaxNameSize > -1 && name.size() > static_cast<unsigned>(MaxNameSize)) {
    name = name.substr(0, std::max(1u, static_cast<unsigned>(MaxNameSize)));
  }

  // Common case: insert directly
  auto [iter, inserted] = vmap.insert(std::make_pair(name, V));
  if (inserted) {
    return &*iter;
  }

  // Collision: build unique variant
  SmallString<256> trialName(name.begin(), name.end());
  return makeUniqueName(V, trialName);
}

