#include <array>
#include <iostream>
#include <string>
#include "asio.hpp"

constexpr short mcast_port = 30001;

class udp_multicast_listener
{
public:
  udp_multicast_listener(asio::io_context& ctx,
      const asio::ip::address& bind_addr,
      const asio::ip::address& group_addr)
    : sock_(ctx)
  {
    // Configure socket for reuse and binding
    asio::ip::udp::endpoint ep(bind_addr, mcast_port);
    sock_.open(ep.protocol());
    sock_.set_option(asio::ip::udp::socket::reuse_address(true));
    sock_.bind(ep);

    // Subscribe to the multicast group
    sock_.set_option(asio::ip::multicast::join_group(group_addr));

    start_receiving();
  }

private:
  void start_receiving()
  {
    sock_.async_receive_from(
        asio::buffer(buffer_), remote_,
        [this](std::error_code err, std::size_t bytes_transferred)
        {
          if (!err)
          {
            std::cout.write(buffer_.data(), bytes_transferred);
            std::cout << '\n';
            start_receiving();
          }
        });
  }

  asio::ip::udp::socket sock_;
  asio::ip::udp::endpoint remote_;
  std::array<char, 1024> buffer_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 3)
    {
      std::cerr << "Usage: receiver <listen_address> <multicast_address>\n";
      std::cerr << "  For IPv4, try:\n";
      std::cerr << "    receiver 0.0.0.0 239.255.0.1\n";
      std::cerr << "  For IPv6, try:\n";
      std::cerr << "    receiver 0::0 ff31::8000:1234\n";
      return 1;
    }

    asio::io_context context;
    udp_multicast_listener listener(context,
        asio::ip::make_address(argv[1]),
        asio::ip::make_address(argv[2]));

    context.run();
  }
  catch (const std::exception& ex)
  {
    std::cerr << "Error: " << ex.what() << "\n";
  }

  return 0;
}

#include <vector>
#include <climits>
#include <algorithm>

class Solution {
public:
    int minimumCost(std::vector<int>& nums) {
        int n = nums.size();
        int result = INT_MAX;

        // Iterate through all valid pairs (i, j) where 1 <= i < j < n
        for (int firstIndex = 1; firstIndex < n - 1; ++firstIndex) {
            for (int secondIndex = firstIndex + 1; secondIndex < n; ++secondIndex) {
                int currentTotal = nums[0] + nums[firstIndex] + nums[secondIndex];
                result = std::min(result, currentTotal);
            }
        }

