    // Process a single test case: find two pens with ink using tournament-style elimination
    void processTest() {
        int n;
        std::cin >> n;

        // Start with all pen indices as potential ink-containing pens
        std::vector<int> pool(n);
        std::iota(pool.begin(), pool.end(), 0);

        // Continue eliminating until only two pens remain
        while (pool.size() > 2) {
            std::vector<int> survivors;

            // Handle odd number of participants by giving last one automatic advancement
            if (pool.size() % 2 == 1) {
                survivors.push_back(pool.back());
                pool.pop_back();
            }

            // Compare pairs and keep the one that has ink
            for (size_t i = 0; i < pool.size(); i += 2) {
                int first = pool[i];
                int second = pool[i + 1];

                // Check first pen
                std::cout << "0 " << first << std::endl;
                int result_first;
                std::cin >> result_first;

                // Check second pen
                std::cout << "0 " << second << std::endl;
                int result_second;
                std::cin >> result_second;

                // If first pen has ink, it advances; otherwise second pen advances
                if (result_first == 1) {
                    survivors.push_back(first);
                } else {
                    survivors.push_back(second);
                }
            }

            // Update pool to contain only survivors
            pool = survivors;
        }

        // Report the final two candidate pens
        std::cout << "1 " << pool[0] << " " << pool[1] << std::endl;
    }

    int main() {
        // Optimize I/O performance
        std::ios_base::sync_with_stdio(false);
        std::cin.tie(nullptr);

        int testCases;
        std::cin >> testCases;

        for (int tc = 0; tc < testCases; ++tc) {
            processTest();
        }

        return 0;
    }

