#include <iostream>
#include <vector>
#include <queue>
#include <limits>
#include <list>

// Using standard namespace for convenience
using namespace std;

// Graph class implementing Dijkstra's shortest path algorithm
class ShortestPathGraph {
public:
    int vertexCount; // Total number of vertices in the graph
    list<pair<int, int>>* adjacencyList; // Adjacency list representation

    // Constructor to initialize graph with given number of vertices
    ShortestPathGraph(int V) : vertexCount(V) {
        adjacencyList = new list<pair<int, int>>[V];
    }

    // Add an undirected edge between two vertices with specified weight
    void insertEdge(int from, int to, int cost) {
        adjacencyList[from].emplace_back(to, cost);
        adjacencyList[to].emplace_back(from, cost); // Undirected graph
    }

    // Compute shortest paths from source vertex using Dijkstra's algorithm
    void computeShortestPaths(int startNode) {
        // Priority queue (min-heap) storing {distance, vertex}
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> minHeap;

        // Distance array initialized to maximum possible value
        vector<int> distances(vertexCount, numeric_limits<int>::max());

        // Initialize source distance to zero and add to priority queue
        minHeap.emplace(0, startNode);
        distances[startNode] = 0;

        // Process vertices until priority queue is empty
        while (!minHeap.empty()) {
            int currentVertex = minHeap.top().second;
            minHeap.pop();

            // Explore all adjacent vertices
            for (const auto& edge : adjacencyList[currentVertex]) {
                int nextVertex = edge.first;
                int edgeWeight = edge.second;

                // Relaxation step: update distance if shorter path found
                if (distances[currentVertex] + edgeWeight < distances[nextVertex]) {
                    distances[nextVertex] = distances[currentVertex] + edgeWeight;
                    minHeap.emplace(distances[nextVertex], nextVertex);
                }
            }
        }

        // Output results in tabular format
        cout << "Vertex\tDistance from Source" << endl;
        for (int i = 0; i < vertexCount; ++i) {
            cout << i << "\t" << distances[i] << endl;
        }
    }

    // Display the adjacency list representation of the graph
    void displayGraph() {
        for (int i = 0; i < vertexCount; ++i) {
            cout << "Vertex " << i << ":";
            for (const auto& connection : adjacencyList[i]) {
                cout << " -> (" << connection.first << ", " << connection.second << ")";
            }
            cout << endl;
        }
    }
};

// Main function demonstrating usage of the ShortestPathGraph class
int main() {
    // Create a graph with 5 vertices
    ShortestPathGraph network(5);

    // Add edges with weights
    network.insertEdge(0, 1, 10);
    network.insertEdge(0, 2, 5);
    network.insertEdge(1, 2, 2);
    network.insertEdge(1, 3, 1);
    network.insertEdge(2, 1, 3);
    network.insertEdge(2, 3, 9);
    network.insertEdge(2, 4, 2);
    network.insertEdge(3, 4, 4);

    // Run Dijkstra's algorithm from vertex 0
    cout << "Shortest Path Analysis starting from vertex 0:" << endl;
    network.computeShortestPaths(0);

    return 0;
}

/*
Dijkstra's Algorithm efficiently computes shortest paths from a source vertex 
to all other vertices in graphs with non-negative edge weights.

Implementation Details:
- Uses a min-priority queue for optimal performance
- Employs adjacency list representation for memory efficiency
- Implements standard relaxation technique for updating distances

Time Complexity: O((V + E) log V), where V is vertices and E is edges
Space Complexity: O(V) for storing distances and priority queue
*/

