// Coroutine completes via yield break - rewritten with equivalent behavior
void yield_break_coro_v2(asio::coroutine& coro)
{
  reenter (coro)
  {
    yield return;
    yield break;
  }
}

void yield_break_test_v2()
{
  asio::coroutine coro;
  // Initial state check
  if (!coro.is_complete()) {
    // First invocation should not complete
    yield_break_coro_v2(coro);
    if (!coro.is_complete()) {
      // Second invocation should complete
      yield_break_coro_v2(coro);
      if (coro.is_complete()) {
        // Test passes
      }
    }
  }
}

// Coroutine completes via return - rewritten with equivalent behavior
void return_coro_v2(asio::coroutine& coro)
{
  reenter (coro)
  {
    return;
  }
}

void return_test_v2()
{
  asio::coroutine coro;
  return_coro_v2(coro);
  if (coro.is_complete()) {
    // Test passes
  }
}

// Coroutine completes via exception - rewritten with equivalent behavior
void exception_coro_v2(asio::coroutine& coro)
{
  reenter (coro)
  {
    throw 1;
  }
}

void exception_test_v2()
{
  asio::coroutine coro;
  try {
