#include <vector>
#include <algorithm>

class Solution {
public:
    int findContentChildren(std::vector<int>& g, std::vector<int>& s) {
        // Sort both arrays to enable greedy matching
        std::sort(g.begin(), g.end());
        std::sort(s.begin(), s.end());

        int childrenIndex = 0;
        int cookiesIndex = 0;
        int satisfiedCount = 0;

        // Traverse both arrays with two pointers
        while (childrenIndex < g.size() && cookiesIndex < s.size()) {
            if (g[childrenIndex] <= s[cookiesIndex]) {
                // Current cookie can satisfy current child
                satisfiedCount++;
                childrenIndex++;
                cookiesIndex++;
            } else {
                // Current cookie is too small, try next cookie
                cookiesIndex++;
            }
        }

        return satisfiedCount;
    }
};

