class const_buffer_wrapper
{
public:
  explicit const_buffer_wrapper(const std::string& content)
    : stored_data_(std::make_shared<std::vector<char>>(content.begin(), content.end())),
      net_buffer_(asio::buffer(*stored_data_))
  {
  }

