  asio::const_buffer net_buffer_;
};

// Handles individual client connections
class connection_handler
  : public std::enable_shared_from_this<connection_handler>
{
public:
  explicit connection_handler(tcp::socket conn_socket)
    : socket_(std::move(conn_socket))
  {
  }

  void initiate()
  {
    send_time_data();
  }

private:
  void send_time_data()
  {
    time_t current_time = std::time(nullptr);
    std::string time_string(std::ctime(&current_time));

    auto self = shared_from_this();
    const_buffer_wrapper buffer(time_string);

    asio::async_write(socket_, buffer,
        [this, self](const asio::error_code& error, std::size_t bytes_transferred)
        {
          // Connection handling logic could be extended here
        });
  }

  tcp::socket socket_;
};

// Main server class managing incoming connections
class time_server
{
public:
  time_server(asio::io_context& context, unsigned short listening_port)
    : acceptor_(context, tcp::endpoint(tcp::v4(), listening_port))
  {
    start_accepting_connections();
  }

private:
  void start_accepting_connections()
  {
    acceptor_.async_accept(
        [this](const asio::error_code& error, tcp::socket client_socket)
        {
          if (!error)
          {
            std::make_shared<connection_handler>(std::move(client_socket))->initiate();
          }

          // Continue accepting new connections
          start_accepting_connections();
        });
  }

  tcp::acceptor acceptor_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: time_server <port>\n";
      return 1;
    }

    asio::io_context io_context;
    time_server server(io_context, static_cast<unsigned short>(std::atoi(argv[1])));

    io_context.run();
  }
  catch (const std::exception& exception)
  {
    std::cerr << "Server error: " << exception.what() << "\n";
    return 1;
  }

  return 0;
}

#include "llvm/Analysis/ScalarEvolutionNormalization.h"
#include "llvm/Analysis/LoopInfo.h"
#include "llvm/Analysis/ScalarEvolution.h"
#include "llvm/Analysis/ScalarEvolutionExpressions.h"

using namespace llvm;

// Operation modes for post-increment normalization/denormalization
enum RewriteMode {
  // Shift expression backward in loop index (i.e., normalize)
  NormalizeMode,
  // Shift expression forward in loop index (i.e., denormalize)
  DenormalizeMode
};

namespace {

class PostIncRewriter
    : public SCEVRewriteVisitor<PostIncRewriter> {
  const RewriteMode Mode;
  // NB! Pred is a function_ref. Lifetime must be carefully managed.
  const NormalizePredTy Predicate;

public:
  PostIncRewriter(RewriteMode M, NormalizePredTy P, ScalarEvolution &S)
      : SCEVRewriteVisitor<PostIncRewriter>(S), Mode(M), Predicate(P) {}

  const SCEV *visitAddRecExpr(const SCEVAddRecExpr *Expr);
};

} // end anonymous namespace

const SCEV *
PostIncRewriter::visitAddRecExpr(const SCEVAddRecExpr *AR) {
  SmallVector<const SCEV *, 8> NewOps;
  std::transform(AR->operands().begin(), AR->operands().end(),
                 std::back_inserter(NewOps),
                 [this](const SCEV *Op) { return this->visit(Op); });

  if (!Predicate(AR))
    return SE.getAddRecExpr(NewOps, AR->getLoop(), SCEV::FlagAnyWrap);

  // Normalization: decrement w.r.t. loop; Denormalization: increment w.r.t. loop
  if (Mode == DenormalizeMode) {
    // Perform partial increment: accumulate from right to left
    int idx = NewOps.size() - 2;
    while (idx >= 0) {
      NewOps[idx] = SE.getAddExpr(NewOps[idx], NewOps[idx + 1]);
      --idx;
    }
  } else {
    assert(Mode == NormalizeMode && "Only two rewrite modes exist!");
    // Perform partial decrement: subtract next operand from current, moving leftward
    int pos = static_cast<int>(NewOps.size()) - 2;
    while (pos >= 0) {
      NewOps[pos] = SE.getMinusSCEV(NewOps[pos], NewOps[pos + 1]);
      --pos;
    }
  }

  return SE.getAddRecExpr(NewOps, AR->getLoop(), SCEV::FlagAnyWrap);
}

const SCEV *llvm::normalizeForPostIncUse(const SCEV *Expr,
                                         const PostIncLoopSet &TargetLoops,
                                         ScalarEvolution &SE,
                                         bool VerifyInvertibility) {
  if (TargetLoops.empty())
    return Expr;

  auto LoopMatches = [&](const SCEVAddRecExpr *AR) {
    return TargetLoops.contains(AR->getLoop());
  };

  const SCEV *Normalized =
      PostIncRewriter(NormalizeMode, LoopMatches, SE).visit(Expr);

  const SCEV *Denormalized = denormalizeForPostIncUse(Normalized, TargetLoops, SE);

  if (VerifyInvertibility && Denormalized != Expr)
    return nullptr;

  return Normalized;
}

const SCEV *llvm::normalizeForPostIncUseIf(const SCEV *Expr,
                                           NormalizePredTy Pred,
                                           ScalarEvolution &SE) {
  return PostIncRewriter(NormalizeMode, Pred, SE).visit(Expr);
}

const SCEV *llvm::denormalizeForPostIncUse(const SCEV *Expr,
                                           const PostIncLoopSet &TargetLoops,
                                           ScalarEvolution &SE) {
  if (TargetLoops.empty())
    return Expr;

  auto LoopMatches = [&](const SCEVAddRecExpr *AR) {
    return TargetLoops.contains(AR->getLoop());
  };

  return PostIncRewriter(DenormalizeMode, LoopMatches, SE).visit(Expr);
}

