using namespace ptn;

// Recursive JSON parser with depth-based indentation and type-specific handling
void parse_json(const json &j, int level = 0) {
    match(j)
        .when(
            bind()[is_type(json::value_t::null)] >>
            print_null(level))
        .when(
            bind()[is_type(json::value_t::boolean)] >>
            print_bool(level))
        .when(
            bind()[is_type(json::value_t::number_integer)] >>
            print_number<int>("int", level))
        .when(
            bind()[is_type(json::value_t::number_unsigned)] >>
            print_number<unsigned>("uint", level))
        .when(
            bind()[is_type(json::value_t::number_float)] >>
            print_number<double>("float", level))
        .when(
            bind()[is_type(json::value_t::string)] >>
            print_string(level))
        .when(
            bind()[is_empty_array] >>
            [=](const json &) {
                indent(level);
                std::cout << "array []\n";
            })
        .when(
            bind()[is_type(json::value_t::array)] >>
            [=](const json &arr) {
                indent(level);
                std::cout << "array (" << arr.size() << ")\n";
                int idx = 0;
                while (idx < static_cast<int>(arr.size())) {
                    parse_json(arr[idx], level + 1);
                    ++idx;
                }
            })
        .when(
            bind()[has_field("name")] >>
            [=](const json &obj) {
                indent(level);
                std::cout << "object <named>\n";
                for (auto &&[key, val] : obj.items()) {
                    indent(level + 1);
                    std::cout << key << ":\n";
                    parse_json(val, level + 2);
                }
            })
        .otherwise([=] {
            indent(level);
            std::cout << "<unknown>\n";
        });
}

#include <asio.hpp>
#include <boost/bind.hpp>
#include <iostream>
#include "logger.hpp"

using asio::ip::tcp;

// Buffer for incoming data
char input_buffer[1024];

// Handler for asynchronous read operations
void on_read_complete(const asio::error_code& error,
    std::size_t bytes_read, tcp::socket* sock)
{
  if (!error)
  {
    // Output the received data to standard output
    std::cout.write(input_buffer, bytes_read);

    // Continue reading asynchronously
    sock->async_read_some(asio::buffer(input_buffer),
        boost::bind(on_read_complete, asio::placeholders::error,
          asio::placeholders::bytes_transferred, sock));
  }
  else
  {
    // Log the read error using the logger
    services::logger log_instance(sock->get_executor().context(), "on_read_complete");
    std::string err_msg = "Read operation failed: ";
    err_msg += error.message();
    log_instance.log(err_msg);
  }
}

// Handler for connection establishment
void on_connection_established(const asio::error_code& error, tcp::socket* sock)
{
  services::logger log_instance(sock->get_executor().context(), "on_connection_established");

  if (!error)
  {
    log_instance.log("Successfully connected to server");

    // Begin reading data after successful connection
    sock->async_read_some(asio::buffer(input_buffer),
        boost::bind(on_read_complete, asio::placeholders::error,
          asio::placeholders::bytes_transferred, sock));
  }
  else
  {
    std::string err_msg = "Connection attempt failed: ";
    err_msg += error.message();
    log_instance.log(err_msg);
  }
}

int main(int argc, char* argv[])
{
  try
  {
    // Validate command-line arguments
    if (argc != 2)
    {
      std::cerr << "Usage: daytime_client <hostname>" << std::endl;
      return 1;
    }

    asio::io_context io_ctx;

    // Initialize global logger and configure file output
    services::logger base_logger(io_ctx, "");
    base_logger.use_file("log.txt");

    // Resolve hostname to endpoint list
    tcp::resolver resolver(io_ctx);
    auto endpoints = resolver.resolve(argv[1], "daytime");

    // Create socket and initiate async connect
    tcp::socket client_socket(io_ctx);
    asio::async_connect(client_socket, endpoints,
        boost::bind(on_connection_established,
          asio::placeholders::error, &client_socket));

    // Execute the I/O context until all operations complete
    io_ctx.run();
  }
  catch (const std::exception& ex)
  {
    std::cerr << "Exception occurred: " << ex.what() << std::endl;
    return 1;
  }

  return 0;
}

