#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    std::vector<std::vector<std::string>> groupAnagrams(std::vector<std::string>& strs) {
        // Map to store groups of anagrams using sorted string as key
        std::unordered_map<std::string, std::vector<std::string>> anagramMap;

        // Process each string in the input
        for (const auto& currentStr : strs) {
            // Create a sorted version of the string to use as a key
            std::string sortedStr = currentStr;
            std::sort(sortedStr.begin(), sortedStr.end());

            // Add the original string to its anagram group
            anagramMap[sortedStr].push_back(currentStr);
        }

        // Collect all anagram groups into the result
        std::vector<std::vector<std::string>> groupedResult;
        for (const auto& entry : anagramMap) {
            groupedResult.push_back(entry.second);
        }

        return groupedResult;
    }
};

