namespace yams::tools {

// Forward declarations for command types
class GCCommand;
class StatsCommand;
class VerifyCommand;

// Factory function declarations
std::unique_ptr<Command> createGCCommand();
std::unique_ptr<Command> createStatsCommand();
std::unique_ptr<Command> createVerifyCommand();

class YamsTools {
public:
    YamsTools() : cliApp_("yams-tools", "YAMS Storage Maintenance Utilities") {
        configureApp();
        installCommands();
    }

    int run(int argc, char** argv) {
        try {
            cliApp_.parse(argc, argv);

            // Find and execute the selected subcommand
            for (const auto& [label, handler] : commandMap_) {
                if (cliApp_.got_subcommand(label)) {
                    return handler->perform();
                }
            }

            // No subcommand given — display help
            std::cout << cliApp_.help() << std::endl;
            return 0;
        } catch (const CLI::ParseError& err) {
            return cliApp_.exit(err);
        } catch (const std::exception& ex) {
            std::cerr << "Fatal error: " << ex.what() << std::endl;
            return 1;
        }
    }

private:
    void configureApp() {
        cliApp_.set_version_flag("-V,--version", "1.0.0");
        cliApp_.require_subcommand(0, 1);
        cliApp_.add_flag("--debug", verbose_, "Activate verbose logging mode");
    }

    void installCommands() {
        installSingleCommand(createGCCommand());
        installSingleCommand(createStatsCommand());
        installSingleCommand(createVerifyCommand());
    }

    void installSingleCommand(std::unique_ptr<Command> cmd) {
        if (!cmd) return;

        const std::string& key = cmd->getName();
        cmd->configureOptions(cliApp_);
        commandMap_[key] = std::move(cmd);
    }

    CLI::App cliApp_;
    std::map<std::string, std::unique_ptr<Command>> commandMap_;
    bool verbose_ = false;
};

} // namespace yams::tools

// Global interrupt flag and handler
std::atomic<bool> g_signalReceived{false};

void handleSignal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        g_signalReceived = true;
        std::cerr << "\nOperation interrupted. Initiating shutdown..." << std::endl;
    }
}

int main(int argc, char** argv) {
    // Install signal handlers
    std::signal(SIGINT, handleSignal);
    std::signal(SIGTERM, handleSignal);

    // Configure log format
    spdlog::set_pattern("[%Y-%m-%d %H:%M:%S.%e] [%l] %v");

    // Launch the tool
    yams::tools::YamsTools program;
    return program.run(argc, argv);
}

