#include <asio.hpp>
#include <ctime>
#include <chrono>
#include <iostream>

// Custom clock based on std::time(), mimicking steady behavior where possible
struct epoch_based_wall_clock
{
  using tick_duration = std::chrono::steady_clock::duration;
  using rep = tick_duration::rep;
  using period = tick_duration::period;
  using time_point = std::chrono::time_point<epoch_based_wall_clock>;

  static constexpr bool is_steady = false;

  static time_point now() noexcept
  {
    auto seconds_since_epoch = std::time(nullptr);
    return time_point{tick_duration{seconds_since_epoch * period::den / period::num}};
  }
};

// Custom wait traits for handling coarse-grained clocks (1-second resolution)
struct adaptive_polling_traits
{
  // Helper: compute remaining duration until target time point
  static epoch_based_wall_clock::duration remaining(
      const epoch_based_wall_clock::time_point& target)
  {
    return target - epoch_based_wall_clock::now();
  }

  // Strategy: reduce polling frequency when far from timeout; increase near deadline
  static epoch_based_wall_clock::duration to_wait_duration(
      const epoch_based_wall_clock::duration& rel_time)
  {
    if (rel_time > std::chrono::seconds(2))
      return rel_time - std::chrono::seconds(1);  // Wait most of the interval before final check
    else if (rel_time > std::chrono::seconds(0))
      return std::chrono::milliseconds(50);       // Poll every 50ms when close
    else
      return epoch_based_wall_clock::duration::zero(); // Immediate wake-up needed
  }

  static epoch_based_wall_clock::duration to_wait_duration(
      const epoch_based_wall_clock::time_point& abs_time)
  {
    return to_wait_duration(remaining(abs_time));
  }
};

// Alias for convenience
using wall_timer = asio::basic_waitable_timer<
    epoch_based_wall_clock, adaptive_polling_traits>;

int main()
{
  try
  {
    asio::io_context ctx;

    // Synchronous wait demonstration
    wall_timer sync_timer{ctx};
    sync_timer.expires_after(std::chrono::seconds(5));
    std::cout << "Synchronous wait initiated...\n";
    sync_timer.wait();
    std::cout << "Synchronous wait completed.\n";

    // Asynchronous wait demonstration
    wall_timer async_timer{ctx};
    async_timer.expires_after(std::chrono::seconds(5));
    std::cout << "Asynchronous wait started...\n";

    bool completed = false;
    async_timer.async_wait(
        [&](const std::error_code& ec)
        {
          if (!ec)
          {
            std::cout << "Asynchronous timeout triggered.\n";
            completed = true;
          }
        });

    // Run event loop until completion
    ctx.run();

    std::cout << "Asynchronous wait finished.\n";
  }
  catch (const std::exception& err)
  {
    std::cerr << "Caught exception: " << err.what() << '\n';
    return 1;
  }

  return 0;
}

