// Constructor: Level-only initialization
ThrownEnderpearl::ThrownEnderpearl(Level *level) : Throwable(level)
{
	// 4J Stu - This function call had to be moved here from the Entity ctor to ensure that
	// the derived version of the function is called
	this->defineSynchedData();
}

// Constructor: With LivingEntity owner
ThrownEnderpearl::ThrownEnderpearl(Level *level, shared_ptr<LivingEntity> mob) : Throwable(level, mob)
{
	// 4J Stu - This function call had to be moved here from the Entity ctor to ensure that
	// the derived version of the function is called
	this->defineSynchedData();
}

// Constructor: With explicit coordinates
ThrownEnderpearl::ThrownEnderpearl(Level *level, double x, double y, double z) : Throwable(level, x, y, z)
{
	// 4J Stu - This function call had to be moved here from the Entity ctor to ensure that
	// the derived version of the function is called
	this->defineSynchedData();
}

void ThrownEnderpearl::onHit(HitResult *res)
{
	// Handle entity hit
	if (res->entity != nullptr)
	{
		DamageSource *damageSource = DamageSource::thrown(shared_from_this(), getOwner());
		res->entity->hurt(damageSource, 0);
		delete damageSource;
	}

	// Spawn particles for visual effect
	for (int idx = 0; idx < 32; ++idx)
	{
		level->addParticle(eParticleType_ender, 
		                   x, 
		                   y + random->nextDouble() * 2.0, 
		                   z, 
		                   random->nextGaussian(), 
		                   0.0, 
		                   random->nextGaussian());
	}

	// Server-side logic only
	if (!level->isClientSide)
	{
		// Fix for #67486 - TCR #001: BAS Game Stability: Customer Encountered: TU8: Code: Gameplay: The title crashes on Host's console when Client Player leaves the game before the Ender Pearl thrown by him touches the ground.
		// If the owner has been removed, then ignore
		// 4J-JEV: Cheap type check first.
		LivingEntity* owner = getOwner();
		if (owner != nullptr && owner->instanceof(eTYPE_SERVERPLAYER))
		{
			shared_ptr<ServerPlayer> serverPlayer = dynamic_pointer_cast<ServerPlayer>(owner);
			if (!serverPlayer->removed)
			{
				PlayerConnection* conn = serverPlayer->connection.get();
				if (conn != nullptr && !serverPlayer->connection->done && serverPlayer->level == this->level)
				{
					if (owner->isRiding())
					{
						owner->ride(nullptr);
					}
					owner->teleportTo(x, y, z);
					owner->fallDistance = 0.0f;
					owner->hurt(DamageSource::fall, 5);
				}
			}
		}
		remove();
	}
}

#include <small_gicp/util/downsampling.hpp>
#include <small_gicp/points/point_cloud.hpp>
#include <small_gicp/benchmark/benchmark.hpp>
#include <small_gicp/benchmark/benchmark_odom.hpp>
#include <fstream>

int main(int argc, char** argv) {
  using namespace small_gicp;

  // Check command-line arguments and show help if insufficient
  if (argc < 3) {
    std::cout << "Usage: odometry_benchmark <dataset_path> <output_path> [options]" << std::endl;
    std::cout << "Options:" << std::endl;
    std::cout << "  --visualize" << std::endl;
    std::cout << "  --num_threads <value> (default: 4)" << std::endl;
    std::cout << "  --num_neighbors <value> (default: 20)" << std::endl;
    std::cout << "  --downsampling_resolution <value> (default: 0.25)" << std::endl;
    std::cout << "  --voxel_resolution <value> (default: 2.0)" << std::endl;

    const auto odom_names = odometry_names();
    std::string engine_list;
    for (size_t idx = 0; idx < odom_names.size(); ++idx) {
      if (!engine_list.empty()) engine_list += "|";
      engine_list += odom_names[idx];
    }
    std::cout << "  --engine <" << engine_list << "> (default: small_gicp)" << std::endl;
    return 0;
  }

  // Parse required positional arguments
  const std::string dataset_dir = argv[1];
  const std::string result_file = argv[2];

  // Initialize estimation parameters with defaults
  OdometryEstimationParams config;
  config.num_threads = 4;
  config.num_neighbors = 20;
  config.downsampling_resolution = 0.25;
  config.voxel_resolution = 2.0;
  config.visualize = false;

  std::string reg_engine = "small_gicp";

  // Process optional arguments
  for (int idx = 0; idx < argc; ++idx) {
    const std::string token = argv[idx];
    if (token == "--visualize") {
      config.visualize = true;
    } else if (token == "--num_threads" && idx + 1 < argc) {
      config.num_threads = std::stoi(argv[++idx]);
    } else if (token == "--num_neighbors" && idx + 1 < argc) {
      config.num_neighbors = std::stoi(argv[++idx]);
    } else if (token == "--downsampling_resolution" && idx + 1 < argc) {
      config.downsampling_resolution = std::stod(argv[++idx]);
    } else if (token == "--voxel_resolution" && idx + 1 < argc) {
      config.voxel_resolution = std::stod(argv[++idx]);
    } else if (token == "--engine" && idx + 1 < argc) {
      reg_engine = argv[++idx];
    } else if (token.size() > 2 && token.substr(0, 2) == "--") {
      std::cerr << "Error: unrecognized option '" << token << "'" << std::endl;
      return 1;
    }
  }

  // Print configuration summary
  std::cout << "SIMD instruction set in use: " << Eigen::SimdInstructionSetsInUse() << std::endl;
  std::cout << "Dataset path: " << dataset_dir << std::endl;
  std::cout << "Output file: " << result_file << std::endl;
  std::cout << "Registration engine: " << reg_engine << std::endl;
  std::cout << "Threads: " << config.num_threads << std::endl;
  std::cout << "Neighbors: " << config.num_neighbors << std::endl;
  std::cout << "Downsampling resolution: " << config.downsampling_resolution << std::endl;
  std::cout << "Voxel resolution: " << config.voxel_resolution << std::endl;
  std::cout << "Visualization enabled: " << config.visualize << std::endl;

  // Create registration object
  std::shared_ptr<OdometryEstimation> estimator = create_odometry(reg_engine, config);
  if (!estimator) {
    std::cerr << "Failed to create odometry estimator for engine: " << reg_engine << std::endl;
    return 1;
  }

  // Load KITTI dataset
  KittiDataset dataset(dataset_dir);
  std::cout << "Loaded " << dataset.points.size() << " frames" << std::endl;
  std::cout << fmt::format("Total points: {} [points]", summarize(dataset.points, [](const auto& pts) { return pts.size(); })) << std::endl;

  // Convert raw data to PointCloud format
  auto point_clouds = dataset.convert<PointCloud>(true);

  // Perform odometry estimation
  std::vector<Eigen::Isometry3d> trajectory = estimator->estimate(point_clouds);
  std::cout << "Odometry estimation completed." << std::endl;

  // Output performance report
  estimator->report();

  // Save trajectory to output file
  std::ofstream out_stream(result_file);
  for (const auto& pose : trajectory) {
    for (int row = 0; row < 3; ++row) {
      for (int col = 0; col < 4; ++col) {
        if (row != 0 || col != 0) {
          out_stream << " ";
        }
        out_stream << fmt::format("{:.6f}", pose(row, col));
      }
    }
    out_stream << std::endl;
  }

  return 0;
}

#include <iostream>
#include <vector>
#include <madvoro/Voronoi3D.hpp>

int main(int argc, char *argv[]) {
    // Define bounding box corners
    MadVoro::Vector3D lowerLeft(-10.0, -10.0, -10.0);
    MadVoro::Vector3D upperRight(10.0, 10.0, 10.0);

    // Initialize Voronoi diagram with the bounding box
    MadVoro::Voronoi3D voronoi(lowerLeft, upperRight);

    // Input point set (sites)
    std::vector<MadVoro::Vector3D> sites = {
        { -0.115, 4.484, 0.688 },
        { -6.121, 6.335, -9.093 },
        { -5.529, -7.464, 2.459 },
        { -3.448, -7.794, -6.939 },
        { -3.231, 8.213, -7.829 },
        { 5.204, 9.943, 6.175 },
        { -7.018, 7.155, -0.226 },
        { 0.567, 2.263, -0.962 },
        { 9.998, -3.030, 7.772 },
        { 3.811, 6.672, -8.231 },
        { 4.252, -8.460, -2.693 },
        { 5.184, 0.449, -1.665 },
        { -3.333, 3.909, 5.544 },
        { 3.495, -0.703, 5.494 },
        { -4.844, 4.808, -4.166 },
        { 3.016, -0.006, -1.534 },
        { -3.990, -1.579, 0.691 },
        { 6.928, 1.059, 6.088 },
        { 9.439, -6.873, 5.741 },
        { 6.238, -6.793, -4.822 }
    };

    // Retrieve and display bounding box info
    auto bounds = voronoi.GetBoxCoordinates();
    std::cout << "Lower-left corner: " << bounds.first 
              << ", Upper-right corner: " << bounds.second << std::endl;

    // Construct Voronoi diagram
    voronoi.Build(sites);

    // Output basic statistics
    std::cout << "Total number of sites (cells): " << voronoi.GetPointNo() << std::endl;

    // Analyze cell for a specific site (index 3)
    size_t targetSiteIdx = 3;
    const MadVoro::face_vec& faceIndices = voronoi.GetCellFaces(targetSiteIdx);

    std::cout << "Site #" << targetSiteIdx << " at " << voronoi.GetMeshPoint(targetSiteIdx) 
              << " has " << faceIndices.size() << " faces" << std::endl;
    std::cout << "Hence, it has " << faceIndices.size() << " neighboring cells" << std::endl;

    // Get all face vertex coordinates
    std::vector<MadVoro::Vector3D> allFaceVertices = voronoi.GetFacePoints();

    std::cout << "\nDetailed face information:" << std::endl;
    for (size_t fIdx : faceIndices) {
        // Compute center of mass for this face
        MadVoro::Vector3D cm = voronoi.FaceCM(fIdx);

        // Get neighbor pair across this face
        std::pair<size_t, size_t> adjacents = voronoi.GetFaceNeighbors(fIdx);
        size_t otherSite = (adjacents.first == targetSiteIdx) ? adjacents.second : adjacents.first;

        std::cout << "Face " << fIdx << ": adjacent to site " << otherSite 
                  << " (" << voronoi.GetMeshPoint(otherSite) << ")" << std::endl;

        // List vertices of this face
        std::cout << "  Vertices: ";
        for (size_t vIdx : voronoi.GetPointsInFace(fIdx)) {
            std::cout << allFaceVertices[vIdx] << ", ";
        }
        std::cout << "\b\b" << std::endl;
    }

    return 0;
}

