#include <iostream>
#include <fstream>
#include "program.hpp"

int main() {
    char input_file_name[MAX_FILE_NAME];

    // Prompt user for the input file name
    std::cout << "Enter file name: ";
    std::cin.getline(input_file_name, MAX_FILE_NAME);

    std::ifstream input_stream(input_file_name);
    if (!input_stream.is_open()) {
        std::cerr << "Error: Cannot open input file.\n";
        return 1;
    }

    std::ofstream output_stream("Result.txt");
    if (!output_stream.is_open()) {
        std::cerr << "Error: Cannot create output file 'Result.txt'.\n";
        input_stream.close();
        return 1;
    }

    // Process each program in the input file
    while (input_stream) {
        program_context ctx;
        int status = read_program(ctx, input_stream);

        if (status == 1) {  // parsing succeeded
            output_stream << ctx.program_name << '\n';
            for (int idx = 0; idx < ALPHABET_SIZE; ++idx) {
                if (ctx.defined[idx]) {
                    output_stream 
                        << static_cast<char>('a' + idx)
                        << '='
                        << ctx.values[idx] << '\n';
                }
            }
        } else if (status == 0) {  // parsing failed
            output_stream << ctx.program_name << ' ' << FAIL_MESSAGE << '\n';
        }

        clear_context(ctx);
    }

    input_stream.close();
    output_stream.close();
    return 0;
}

