#include <iostream>
#include <set>

int main() {
    std::set<int> numbers; // collection of unique integers
    numbers.insert(1);     // add 1 to the set
    numbers.insert(2);     // add 2 to the set
    numbers.insert(3);     // add 3 to the set
    numbers.insert(4);     // add 4 to the set
    numbers.insert(6);     // add 6 to the set

    // Attempting to insert duplicates (1 and 2) - these will be ignored
    numbers.insert(1);
    numbers.insert(2);

    // Print all elements in ascending order
    for (auto element : numbers) {
        std::cout << element << " ";
    }
    std::cout << std::endl;

    // Display set properties
    std::cout << numbers.size() << std::endl;       // number of unique elements (5)
    std::cout << numbers.max_size() << std::endl;   // maximum possible size (system-dependent)
    std::cout << numbers.empty() << std::endl;      // check if empty (0 = not empty)
    std::cout << numbers.count(1) << std::endl;     // check existence of 1 (1 = exists)

    // Find lower and upper bounds
    auto lb4 = numbers.lower_bound(4);              // first >= 4
    if (lb4 != numbers.end()) {
        std::cout << *lb4 << std::endl;             // prints 4
    } else {
        std::cout << 0 << std::endl;
    }

    auto lb5 = numbers.lower_bound(5);              // first >= 5
    if (lb5 != numbers.end()) {
        std::cout << *lb5 << std::endl;             // prints 6
    } else {
        std::cout << 0 << std::endl;
    }

    auto lb7 = numbers.lower_bound(7);              // first >= 7
    if (lb7 != numbers.end()) {
        std::cout << *lb7 << std::endl;
    } else {
        std::cout << 0 << std::endl;                // no element >= 7, print 0
    }

    auto ub4 = numbers.upper_bound(4);              // first > 4
    if (ub4 != numbers.end()) {
        std::cout << *ub4 << std::endl;             // prints 6
    } else {
        std::cout << 0 << std::endl;
    }

    auto ub5 = numbers.upper_bound(5);              // first > 5
    if (ub5 != numbers.end()) {
        std::cout << *ub5 << std::endl;             // prints 6
    } else {
        std::cout << 0 << std::endl;
    }

    return 0;
}

