// Renamed and slightly restructured date/time structures
struct CalendarDate {
    unsigned short d;   // day (renamed for variety)
    unsigned short m;   // month
    unsigned short y;   // year
};

struct ClockTime {
    unsigned short h{0};     // hour (default initialized to 0)
    unsigned short min{};    // minute (value-initialization to 0)
    unsigned short sec{15};  // second (explicitly set to 15)
};

constexpr std::size_t MaxNameLen = 50;

struct StaffMember {
    int empId{0};
    char fullName[MaxNameLen]{};
    double annualPay{10000.0};
    CalendarDate startDate{}; // embedded struct with default initialization
};

// Function declarations (renamed for semantic clarity)
void displayDate(const CalendarDate& dt);
void showTime(const ClockTime& tm);

int main() {
    // Declare instances
    CalendarDate personalBday;
    ClockTime arbitraryTime;

    // Assign values manually
    personalBday.d = 17;
    personalBday.m = 7;
    personalBday.y = 1956;

    std::cout << "I was born on ";
    displayDate(personalBday);

    std::cout << "Random time: ";
    showTime(arbitraryTime);

    // Aggregate initialization using positional syntax
    CalendarDate currentDay{24, 2, 2026};
    std::cout << "Today is ";
    displayDate(currentDay);

    // Full member initialization
    ClockTime altTime{12, 30, 45};
    std::cout << "Random time 2: ";
    showTime(altTime);

    // Partial initialization (remaining members use defaults)
    ClockTime partialTime{12, 30};
    std::cout << "Random time 3: ";
    showTime(partialTime);

    // Const-correct usage
    const CalendarDate startOfYear{1, 1, 2026};
    // startOfYear.d = 2; // Would cause compile error

    // Struct with embedded struct initialization
    StaffMember worker{1, "John Doe", 2000.0, {1, 1, 2020}};

    // Passing temporary objects directly
    displayDate(CalendarDate{23, 3, 2027});
    displayDate({23, 3, 2027}); // Type deduction allowed in C++17+

    return 0;
}

void displayDate(const CalendarDate& dt) {
    std::cout << dt.d << '/' << dt.m << '/' << dt.y << '\n';
}

void showTime(const ClockTime& tm) {
    std::cout << tm.h << ':' << tm.min << ':' << tm.sec;
}

