// Constructor: renamed variables & refactored loop to use do-while for equivalent iteration
UIScene_DebugOptionsMenu::UIScene_DebugOptionsMenu(
    int      iPad,
    void*    initData,
    UILayer* parentLayer
)
: UIScene(iPad, parentLayer) {
    initialiseMovie();

    unsigned int currentDebugMask = app.GetGameSettingsDebugMask(iPad);
    IggyValuePath* root = IggyPlayerRootPath(getMovie());

    int index = 0;
    m_iTotalCheckboxElements = 0;

    // Use do-while instead of for-loop, with early exit condition
    do {
        if (index >= eDebugSetting_Max || index >= 21) break;

        std::wstring label(m_DebugCheckboxTextA[index]);
        bool isChecked = (currentDebugMask & (1u << index)) != 0;

        m_checkboxes[m_iTotalCheckboxElements].init(label, m_iTotalCheckboxElements, isChecked);
        ++m_iTotalCheckboxElements;
        ++index;
    } while (true);
}

std::wstring UIScene_DebugOptionsMenu::getMoviePath() {
    return L"DebugOptionsMenu";
}

void UIScene_DebugOptionsMenu::handleInput(
    int   iPad,
    int   key,
    bool  repeat,
    bool  pressed,
    bool  released,
    bool& handled
) {
    switch (key) {
    case ACTION_MENU_CANCEL:
        if (pressed) {
            unsigned int newDebugMask = 0U;
            int bitPosition = 0;

            // Iterate over active checkboxes and reconstruct bitmask
            for (int i = 0; i < m_iTotalCheckboxElements; ++i) {
                if (m_checkboxes[i].IsChecked()) {
                    newDebugMask |= (1u << bitPosition);
                }
                ++bitPosition;
            }

            unsigned int oldDebugMask = app.GetGameSettingsDebugMask(iPad);

            if (newDebugMask != oldDebugMask) {
                app.SetGameSettingsDebugMask(iPad, newDebugMask);

                if (app.DebugSettingsOn()) {
                    app.ActionDebugMask(iPad);
                } else {
                    app.ActionDebugMask(iPad, true); // Force disable
                }

                app.CheckGameSettingsChanged(true, iPad);
            }

            navigateBack();
        }
        break;

    case ACTION_MENU_OK:
    case ACTION_MENU_UP:
    case ACTION_MENU_DOWN:
    case ACTION_MENU_PAGEUP:
    case ACTION_MENU_PAGEDOWN:
        sendInputToMovie(key, repeat, pressed, released);
        break;
    }
}

