namespace NLastGetopt {
    TFormattedOutput::IndentGuard::IndentGuard(TFormattedOutput* output)
        : Output(output)
    {
        ++(Output->IndentLevel_);
        ++(Output->IndentLevel_);
    }
    TFormattedOutput::IndentGuard::~IndentGuard() {
        --(Output->IndentLevel_);
        --(Output->IndentLevel_);
    }
    TFormattedOutput::IndentGuard TFormattedOutput::Indent() {
        return IndentGuard(this);
    }
    TStringBuilder& TFormattedOutput::Line() {
        Lines_.emplace_back();
        auto& back = Lines_.back();
        back.first = IndentLevel_;
        back.second = TStringBuilder();
        return back.second;
    }
    void TFormattedOutput::Print(IOutputStream& out) {
        size_t count = Lines_.size();
        for (size_t i = 0; i < count; ++i) {
            auto& item = Lines_[i];
            int indent_spaces = item.first;
            TStringBuilder& line_builder = item.second;

            if (indent_spaces > 0 && !line_builder.empty()) {
                TString indent_str;
                for (int j = 0; j < indent_spaces; ++j) {
                    indent_str += ' ';
                }
                out.Write(indent_str.c_str(), indent_str.size());
            }

            out << line_builder;

            const char* line_cstr = line_builder.c_str();
            size_t len = line_builder.size();
            if (len == 0 || line_cstr[len - 1] != '\n') {
                out << Endl;
            }
        }
    }
}

