#define _GNU_SOURCE
#define ROCPROFSYS_PUBLIC_API     __attribute__((visibility("default")))
#define ROCPROFSYS_HIDDEN_API     __attribute__((visibility("hidden")))
#define ROCPROFSYS_INTERNAL_API   __attribute__((visibility("internal")))

#include <dlfcn.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

// Type aliases for function pointers
typedef int (*main_entry_t)(int, char**, char**);
typedef void (*init_routine_t)(void);
typedef int (*libc_start_main_ptr_t)(int (*)(int, char**, char**), int, char**, void (*)(void),
                                     void (*)(void), void (*)(void), void*);

// Internal declarations
static int rocprofsys_libc_start_main_impl(int (*)(int, char**, char**), int, char**, void (*)(void),
                                           void (*)(void), void (*)(void), void*) ROCPROFSYS_INTERNAL_API;

int __libc_start_main(int (*)(int, char**, char**), int, char**, void (*)(void),
                      void (*)(void), void (*)(void), void*) ROCPROFSYS_PUBLIC_API;

// External symbols
extern int rocprofsys_preload_library(void);
extern void rocprofsys_finalize(void);
extern void rocprofsys_push_trace(const char*);
extern void rocprofsys_pop_trace(const char*);
extern void rocprofsys_init_tooling(void);
extern void rocprofsys_init(const char*, bool, const char*);
extern char* basename(const char*);
extern void rocprofsys_set_main(main_entry_t) ROCPROFSYS_INTERNAL_API;
extern void rocprofsys_set_main_init(init_routine_t) ROCPROFSYS_INTERNAL_API;
extern void rocprofsys_main_init(void) ROCPROFSYS_INTERNAL_API;
extern int rocprofsys_main(int, char**, char**) ROCPROFSYS_INTERNAL_API;

// Implementation helper: avoids direct recursion in wrapper
static int rocprofsys_libc_start_main_impl(
    int (*user_main)(int, char**, char**),
    int argc,
    char** argv,
    void (*init_fn)(void),
    void (*fini_fn)(void),
    void (*rtld_fini_fn)(void),
    void* stack_end)
{
    // Preload check
    int preload_status = rocprofsys_preload_library();

    // Reentrancy guard
    static bool entered = false;
    if (entered) {
        return -1;
    }
    entered = true;

    // Capture current address to avoid self-call
    void* current_addr = __builtin_return_address(0);

    // Register user's main and init functions
    rocprofsys_set_main(user_main);
    rocprofsys_set_main_init(init_fn);

    // Resolve real __libc_start_main
    libc_start_main_ptr_t real_libc_start_main = (libc_start_main_ptr_t)dlsym(RTLD_NEXT, "__libc_start_main");

    // Disable further preloads
    setenv("ROCPROFSYS_PRELOAD", "0", 1);

    if (real_libc_start_main && real_libc_start_main != current_addr) {
        if (preload_status == 0) {
            // Direct delegation if no preload needed
            return real_libc_start_main(user_main, argc, argv, init_fn, fini_fn, rtld_fini_fn, stack_end);
        } else {
            // Wrap with rocprofsys_main
            return real_libc_start_main(rocprofsys_main, argc, argv, init_fn, fini_fn, rtld_fini_fn, stack_end);
        }
    } else {
        fprintf(stderr, "Error! rocprof-sys could not locate __libc_start_main!\n");
        return -1;
    }
}

// Public entry point — delegates to internal implementation
int __libc_start_main(
    int (*user_main)(int, char**, char**),
    int argc,
    char** argv,
    void (*init_fn)(void),
    void (*fini_fn)(void),
    void (*rtld_fini_fn)(void),
    void* stack_end)
{
    return rocprofsys_libc_start_main_impl(user_main, argc, argv, init_fn, fini_fn, rtld_fini_fn, stack_end);
}

