#include "connection.hpp"
#include <vector>
#include <boost/bind.hpp>
#include "request_handler.hpp"

namespace http {
namespace server2 {

connection::connection(asio::io_context& context, request_handler& handler)
  : socket_(context),
    request_handler_(handler)
{
}

asio::ip::tcp::socket& connection::socket()
{
  return socket_;
}

void connection::start()
{
  socket_.async_read_some(asio::buffer(buffer_),
      boost::bind(&connection::on_data_received, shared_from_this(),
        asio::placeholders::error,
        asio::placeholders::bytes_transferred));
}

void connection::on_data_received(const asio::error_code& ec,
    std::size_t length)
{
  if (!ec)
  {
    boost::tribool parsing_result;
    boost::tie(parsing_result, boost::tuples::ignore) = request_parser_.parse(
        request_, buffer_.data(), buffer_.data() + length);

    if (parsing_result)
    {
      request_handler_.handle_request(request_, reply_);
      asio::async_write(socket_, reply_.to_buffers(),
          boost::bind(&connection::on_write_complete, shared_from_this(),
            asio::placeholders::error));
    }
    else if (!parsing_result)
    {
      reply_ = reply::stock_reply(reply::bad_request);
      asio::async_write(socket_, reply_.to_buffers(),
          boost::bind(&connection::on_write_complete, shared_from_this(),
            asio::placeholders::error));
    }
    else
    {
      // Parsing incomplete - continue reading
      socket_.async_read_some(asio::buffer(buffer_),
          boost::bind(&connection::on_data_received, shared_from_this(),
            asio::placeholders::error,
            asio::placeholders::bytes_transferred));
    }
  }
  // Error handling: when an error occurs, no new async operations are started.
  // The connection object will be automatically destroyed once all shared_ptr references vanish.
  // The destructor handles closing the socket.
}

void connection::on_write_complete(const asio::error_code& ec)
{
  if (!ec)
  {
    // Gracefully close the connection
    asio::error_code temp_ec;
    socket_.shutdown(asio::ip::tcp::socket::shutdown_both, temp_ec);
  }
  // No further async operations initiated. Connection cleanup happens automatically.
  // Destructor ensures socket closure.
}

