#include "ReduceGlobalVarInitializers.h"
#include "llvm/IR/Constants.h"
#include "llvm/IR/GlobalValue.h"
using namespace llvm;

/// Clears initializers for global variables outside target regions
static void extractGVsFromModule(Oracle &O, ReducerWorkItem &WorkItem) {
  Module &M = WorkItem.getModule();

  // Iterate through all global variables in the module
  for (auto GI = M.global_begin(), GE = M.global_end(); GI != GE; ++GI) {
    GlobalValue *GV = &*GI;

    // Check if this GV has an initializer and should be excluded
    if (GV->hasInitializer() && !O.shouldKeep()) {
      // Remove the initializer
      GV->setInitializer(nullptr);

      // Change linkage to external
      GV->setLinkage(GlobalValue::ExternalLinkage);

      // Clear any comdat association
      GV->setComdat(nullptr);
    }
  }
}

void llvm::reduceGlobalsInitializersDeltaPass(TestRunner &Test) {
  runDeltaPass(Test, extractGVsFromModule, "Reducing GV Initializers");
}

#include <iostream>
#include <vector>
#include <cstdint>
#include <nlohmann/json.hpp>

using json = nlohmann::json;
using namespace nlohmann::literals;

// Helper function to display UBJSON bytes in human-readable form
void show_ubjson_byte(std::uint8_t b)
{
    if (b >= 32 && b <= 126)
    {
        std::cout << static_cast<char>(b);
    }
    else
    {
        std::cout << static_cast<int>(b);
    }
}

int main()
{
    // Build a JSON object from raw string literal
    json obj = R"({"compact": true, "schema": false})"_json;

    // Convert to UBJSON format (binary representation)
    std::vector<std::uint8_t> ubjson_bytes = json::to_ubjson(obj);

    // Output each byte in diagnostic format
    for (std::uint8_t byte : ubjson_bytes)
    {
        show_ubjson_byte(byte);
    }
    std::cout << '\n';

    // Create a numeric array
    json numbers = {1, 2, 3, 4, 5, 6, 7, 8};

    // Generate three variants of UBJSON encoding:
    // 1. Standard encoding
    std::vector<std::uint8_t> standard_ubjson = json::to_ubjson(numbers);

    // 2. Size-optimized encoding
    std::vector<std::uint8_t> size_optimized = json::to_ubjson(numbers, true);

    // 3. Size + type optimized encoding
    std::vector<std::uint8_t> full_optimized = json::to_ubjson(numbers, true, true);

    // Print each variant on separate lines
    for (std::uint8_t b : standard_ubjson)
    {
        show_ubjson_byte(b);
    }
    std::cout << '\n';

    for (std::uint8_t b : size_optimized)
    {
        show_ubjson_byte(b);
    }
    std::cout << '\n';

    for (std::uint8_t b : full_optimized)
    {
        show_ubjson_byte(b);
    }
    std::cout << '\n';

    return 0;
}

