// Helper function to compare complex numbers with tolerance
void verifyComplexc(Complex actual, Complex expected, const std::string& description) {
    if (std::abs(actual - expected) > 1e-5) {
        std::cerr << "ERROR: " << description 
                  << " — Expected " << expected 
                  << ", but got " << actual << std::endl;
        std::exit(EXIT_FAILURE);
    }
}

// Display non-zero amplitudes in the quantum state vector
void showAmplitudes(const std::vector<Complex>& state) {
    for (size_t idx = 0; idx < state.size(); ++idx) {
        if (std::abs(state[idx]) > 1e-5) {
            std::cout << "|" << idx << ">: " << state[idx] << std::endl;
        }
    }
}

int main() {
    std::cout << "Executing Quantum Engine Validation Suite..." << std::endl;

    // Test Case 1: Single-qubit Hadamard operation
    {
        std::cout << "[Test 1] Applying Hadamard to |0⟩" << std::endl;
        QuantumRegister qubitSystem(1); // Initialize 1-qubit system
        qubitSystem.applyHadamard(0);
        auto finalState = qubitSystem.getStateVector();

        // Theoretical result: |+⟩ = (|0⟩ + |1⟩)/√2
        double amplitude = 1.0 / std::sqrt(2.0);
        verifyComplexc(finalState[0], Complex(amplitude, 0), "H|0⟩ amplitude for |0⟩");
        verifyComplexc(finalState[1], Complex(amplitude, 0), "H|0⟩ amplitude for |1⟩");
        std::cout << "✔ Test 1 passed" << std::endl;
    }

    // Test Case 2: Bell state generation via Hadamard + CNOT
    {
        std::cout << "[Test 2] Constructing Bell State |Φ⁺⟩" << std::endl;
        QuantumRegister twoQubitReg(2);

        // Prepare |+⟩ on first qubit, then entangle with second via CNOT
        twoQubitReg.applyHadamard(0);
        twoQubitReg.applyCNOT(0, 1);

        auto entangledState = twoQubitReg.getStateVector();
        double bellAmp = 1.0 / std::sqrt(2.0);

        verifyComplexc(entangledState[0], Complex(bellAmp, 0), "|00⟩ component");
        verifyComplexc(entangledState[1], Complex(0, 0),     "|01⟩ component (should vanish)");
        verifyComplexc(entangledState[2], Complex(0, 0),     "|10⟩ component (should vanish)");
        verifyComplexc(entangledState[3], Complex(bellAmp, 0), "|11⟩ component");
        std::cout << "✔ Test 2 passed" << std::endl;
    }

    // Test Case 3: Pauli-X gate (quantum NOT)
    {
        std::cout << "[Test 3] Pauli-X (NOT) gate" << std::endl;
        QuantumRegister singleQubit(1);
        singleQubit.applyX(0); // Transforms |0⟩ → |1⟩

        auto flippedState = singleQubit.getStateVector();
        verifyComplexc(flippedState[0], Complex(0, 0), "|0⟩ amplitude after X");
        verifyComplexc(flippedState[1], Complex(1, 0), "|1⟩ amplitude after X");
        std::cout << "✔ Test 3 passed" << std::endl;
    }

    std::cout << "✅ All quantum engine tests completed successfully!" << std::endl;
    return 0;
}

#include "InputStreamReader.h"
#include "DataInputStream.h"

// Constructs an InputStreamReader using the default character set
// Parameters:
// in - The underlying InputStream to read from
InputStreamReader::InputStreamReader(InputStream* in)
: stream(new DataInputStream(in)) {}

// Closes the input stream and frees up any associated system resources.
// After closing, operations like read(), ready(), mark(), reset(), or skip()
// will result in undefined behavior or exceptions. Closing an already closed
// stream is safe and has no effect.
void InputStreamReader::close() { 
    stream->close(); 
}

// Reads a single UTF character from the stream
// Returns:
// The character value as int, or -1 if end-of-stream is reached
int InputStreamReader::read() { 
    return stream->readUTFChar(); 
}

// Reads multiple characters into a provided buffer
// Parameters:
// cbuf - Target wide character array
// offset - Starting index in the buffer where characters will be placed
// length - Maximum number of characters to attempt to read
// Returns:
// Number of characters successfully read, or -1 if end-of-stream occurs immediately
int InputStreamReader::read(
    wchar_t      cbuf[],
    unsigned int offset,
    unsigned int length
) {
    unsigned int count = 0;
    unsigned int pos = offset;

    while (count < length) {
        int rawChar = stream->readUTFChar();
        if (rawChar == -1) {
            break; // End of stream reached
        }
        cbuf[pos] = static_cast<wchar_t>(rawChar);
        ++pos;
        ++count;
    }

    return count;
}

#include <iostream>
#include <vector>
#include <utility>

// Global variables for board size and state
int N;
// Using 1-based indexing for convenience to match problem statement.
// Global arrays are zero-initialized, which works perfectly for 'unvisited'.
int board[667][667]; 

// Knight's move offsets (8 directions, ordered clockwise)
const int dr[] = {-2, -1, 1, 2, 2, 1, -1, -2};
const int dc[] = {1, 2, 2, 1, -1, -2, -2, -1};

// Check if a square (r, c) is on the board and unvisited.
inline bool isValid(int r, int c) {
    return r >= 1 && r <= N && c >= 1 && c <= N && board[r][c] == 0;
}

// Calculate the number of available moves from a square (Warnsdorff's rule).
int getDegree(int r, int c) {
    int count = 0;
    for (int i = 0; i < 8; ++i) {
        if (isValid(r + dr[i], c + dc[i])) {
            count++;
        }
    }
    return count;
}

int main() {
    // Use fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int start_r, start_c;
    std::cin >> N >> start_r >> start_c;

    // `path` will store the sequence of visited squares.
    std::vector<std::pair<int, int>> path;

    // Set the starting position.
    int curr_row = start_r;
    int curr_col = start_c;

    // Mark the starting square as visited (step 1).
    board[curr_row][curr_col] = 1;
    path.emplace_back(curr_row, curr_col);

    // Generate the rest of the path, up to N*N-1 more moves.
    for (int step = 2; step <= N * N; ++step) {
        int best_row = -1;
        int best_col = -1;
        int min_options = 9; // Max possible degree is 8, so 9 is safe

        // Apply Warnsdorff's rule: find the next move with minimum onward moves
        for (int i = 0; i < 8; ++i) {
            int candidate_row = curr_row + dr[i];
            int candidate_col = curr_col + dc[i];

            if (isValid(candidate_row, candidate_col)) {
                int options = getDegree(candidate_row, candidate_col);

                if (options < min_options) {
                    min_options = options;
                    best_row = candidate_row;
                    best_col = candidate_col;
                }
            }
        }

        // If no valid move found, break out
        if (best_row == -1) {
            break;
        }

        // Make the chosen move
        curr_row = best_row;
        curr_col = best_col;
        board[curr_row][curr_col] = step;
        path.emplace_back(curr_row, curr_col);
    }

    // Output the length of the path found
    std::cout << path.size() << "\n";

    // Output the coordinates of each square in the path
    for (const auto& pos : path) {
        std::cout << pos.first << " " << pos.second << "\n";
    }

    return 0;
}

#include <string>
#include <vector>

class Solution {
public:
    int firstUniqChar(std::string s) {
        // Use fixed-size array for counting (26 lowercase letters)
        std::vector<int> counts(26, 0);

        // First pass: count character frequencies
        for (char c : s) {
            counts[c - 'a']++;
        }

        // Second pass: find first character with count 1
        for (int i = 0; i < static_cast<int>(s.size()); ++i) {
            if (counts[s[i] - 'a'] == 1) {
                return i;
            }
        }

        return -1;
    }
};

#include <iostream>
#include <string>
#include <asio/ts/internet.hpp>

using asio::ip::tcp;

int main(int argc, char* argv[]) {
    try {
        // Validate command-line arguments
        if (argc != 3) {
            std::cerr << "Usage: http_client <server> <path>\n";
            std::cerr << "Example:\n";
            std::cerr << "  http_client www.boost.org /LICENSE_1_0.txt\n";
            return 1;
        }

        tcp::iostream connection;

        // Set timeout for the connection and operations
        connection.expires_after(std::chrono::seconds(60));

        // Connect to the specified server on HTTP port
        connection.connect(argv[1], "http");

        if (!connection) {
            std::cerr << "Connection failed: " << connection.error().message() << "\n";
            return 1;
        }

        // Build and send HTTP GET request
        connection << "GET " << argv[2] << " HTTP/1.0\r\n"
                   << "Host: " << argv[1] << "\r\n"
                   << "Accept: */*\r\n"
                   << "Connection: close\r\n\r\n";

        // Read and validate HTTP version
        std::string version;
        connection >> version;

        // Read status code
        unsigned int code;
        connection >> code;

        // Read status message (rest of line after status code)
        std::string msg;
        std::getline(connection, msg);

        // Verify HTTP response format
        if (!connection || version.substr(0, 5) != "HTTP/") {
            std::cerr << "Malformed HTTP response received\n";
            return 1;
        }

        // Check for successful status code
        if (code != 200) {
            std::cerr << "HTTP error: " << code << " " << msg << "\n";
            return 1;
        }

        // Print headers until blank line (CRLF)
        std::string line;
        while (std::getline(connection, line)) {
            if (line.empty() || line == "\r") break;
            std::cout << line << "\n";
        }
        std::cout << "\n"; // Blank line after headers

        // Output remaining body content directly from stream buffer
        std::cout << connection.rdbuf();
    }
    catch (const std::exception& ex) {
        std::cerr << "Runtime error: " << ex.what() << "\n";
        return 1;
    }

    return 0;
}

