Y_UNIT_TEST_SUITE(TTestTLS) {
    struct X {
        inline X()
            : V(0)
        {
        }

        inline void Increment() {
            ++TlsRef(V);
        }

        inline int GetValue() const {
            return TlsRef(V);
        }

        Y_THREAD(int)
        V;
    };

    Y_UNIT_TEST(TestHugeSetup) {
        // Create an array of 100000 X objects
        TArrayHolder<X> objects(new X[100000]);

        // Thread worker class
        struct Worker: public ISimpleThread {
            inline Worker(X* data)
                : Data(data)
            {
            }

            void* ThreadProc() noexcept override {
                // Each thread increments all elements 100000 times
                for (size_t idx = 0; idx < 100000; ++idx) {
                    Data[idx].Increment();
                }
                return nullptr;
            }

            X* Data;
        };

        // Create and start two threads
        Worker worker1(objects.Get());
        Worker worker2(objects.Get());

        worker1.Start();
        worker2.Start();

        // Wait for both threads to complete
        worker1.Join();
        worker2.Join();

        // Verify that each element has value 0 (since TLS is per-thread, increments don't affect other threads' values)
        for (size_t idx = 0; idx < 100000; ++idx) {
            UNIT_ASSERT_VALUES_EQUAL(objects.Get()[idx].GetValue(), 0);
        }
    }
} // Y_UNIT_TEST_SUITE(TTestTLS)

