void FActorPaletteModule::StartupModule()
{
    // Initialize styling and register commands
    FActorPaletteStyle::Initialize();
    FActorPaletteStyle::ReloadTextures();
    FActorPaletteCommands::Register();

    PluginCommands = MakeShareable(new FUICommandList);

    const FSlateIcon PaletteIcon(FActorPaletteStyle::GetStyleSetName(), "ActorPalette.TabIcon");
    const IWorkspaceMenuStructure& MenuStructure = WorkspaceMenu::GetMenuStructure();

    TSharedRef<FWorkspaceItem> ToolsGroup = MenuStructure.GetToolsCategory()->AddGroup(
        LOCTEXT("WorkspaceMenu_ActorPaletteCategory", "Actor Palette"),
        LOCTEXT("ActorPaletteMenuTooltipText", "Open an Actor Palette tab."),
        PaletteIcon,
        true);

    // Register tab spawners dynamically
    for (int32 Idx = 0; Idx < UE_ARRAY_COUNT(ActorPaletteTabs); ++Idx)
    {
        const FName TabId = FName(*FString::Printf(TEXT("ActorPaletteTab%d"), Idx + 1));
        ActorPaletteTabs[Idx].TabID = TabId;

        FGlobalTabmanager::Get()->RegisterNomadTabSpawner(
            TabId,
            FOnSpawnTab::CreateRaw(this, &FActorPaletteModule::SpawnPaletteTab, Idx))
            .SetDisplayName(ActorPaletteInternal::MakeTabLabel(Idx))
            .SetTooltipText(LOCTEXT("ActorPaletteMenuTooltipText", "Open an Actor Palette tab."))
            .SetGroup(ToolsGroup)
            .SetIcon(PaletteIcon);
    }
}

void FActorPaletteModule::ShutdownModule()
{
    FActorPaletteStyle::Shutdown();
    FActorPaletteCommands::Unregister();

    for (int32 Idx = 0; Idx < UE_ARRAY_COUNT(ActorPaletteTabs); ++Idx)
    {
        FGlobalTabmanager::Get()->UnregisterNomadTabSpawner(ActorPaletteTabs[Idx].TabID);
    }
}

TSharedRef<SDockTab> FActorPaletteModule::SpawnPaletteTab(const FSpawnTabArgs& Args, int32 TabIndex)
{
    TSharedRef<SActorPalette> NewPaletteWidget = SNew(SActorPalette, TabIndex);

    check(!ActorPaletteTabs[TabIndex].OpenInstance.IsValid());
    ActorPaletteTabs[TabIndex].OpenInstance = NewPaletteWidget;

    TAttribute<FText> LabelBinding = TAttribute<FText>::Create(
        TAttribute<FText>::FGetter::CreateRaw(this, &FActorPaletteModule::GetDynamicTabTitle, TabIndex));

    TSharedRef<SDockTab> ResultTab = SNew(SDockTab)
        .TabRole(ETabRole::NomadTab)
        .Label(LabelBinding)
        [
            NewPaletteWidget
        ];

    return ResultTab;
}

