#include <QtWidgets/QApplication>
#include <sm/vvec>
#include <mplot/qt/viswidget.h>
#include <mplot/GraphVisual.h>

// Entry point for an mplot-based visualization application
int main(int argc, char** argv) {
    QApplication appInstance(argc, argv);

    // Instantiate the OpenGL-capable visualization widget (index 0)
    mplot::qt::viswidget<0> plotWidget;

    // Ensure initialization occurs before adding models
    plotWidget.show();

    // Prepare a GraphVisual instance with appropriate template parameters
    auto graphObj = std::make_unique<mplot::GraphVisual<double, mplot::qt::gl_version>>(
        sm::vec<float>({0.0f, 0.0f, 0.0f})
    );

    // Register the model with the widget’s visual manager
    plotWidget.v.bindmodel(graphObj);

    // Enable full 3D rendering (disable planar projection)
    graphObj->twodimensional(false);

    // Generate x-values: from -0.5 to 0.8 in 14 evenly spaced steps
    sm::vvec<double> abscissae;
    abscissae.linspace(-0.5, 0.8, 14);

    // Compute y = x^3 using vectorized operations
    auto ordinates = abscissae.pow(3);

    // Feed data into the graph object
    graphObj->setdata(abscissae, ordinates);

    // Finalize internal vertex setup for OpenGL rendering
    graphObj->finalize();

    // Transfer ownership of the graph model to the scene
    plotWidget.v.addVisualModel(std::move(graphObj));

    // Start the Qt event loop
    return appInstance.exec();
}

#include "utl/JsonEncode.h"
#include <cstring>

void JSONStrEncode(const char *cc, String &str) {
    size_t len = std::strlen(cc);
    for (size_t idx = 0; idx < len; ++idx) {
        unsigned char ch = static_cast<unsigned char>(cc[idx]);

        switch (ch) {
            case '"':
                str += "\\\"";
                break;
            case '\\':
                str += "\\\\";
                break;
            case '/':
                str += "\\/";
                break;
            case '\b':
                str += "\\b";
                break;
            case '\r':
                str += "\\r";
                break;
            case '\n':
                str += "\\n";
                break;
            case '\t':
                str += "\\t";
                break;
            default:
                if (ch < ' ') {
                    str += "\\u00";
                    const char hexDigits[] = "0123456789ABCDEF";
                    str += hexDigits[ch >> 4];
                    str += hexDigits[ch & 0x0F];
                } else {
                    str += static_cast<char>(ch);
                }
                break;
        }
    }
}

