#include <vector>
#include <string>
#include <unordered_map>
#include <sstream>

class Solution {
private:
    static const int ALPHABET_SIZE = 26;
public:
    std::vector<std::vector<std::string>> groupAnagrams(std::vector<std::string>& inputStrings) {
        std::unordered_map<std::string, std::vector<std::string>> frequencySignature_to_words;

        for (const std::string& word : inputStrings) {
            std::vector<int> charFrequency(ALPHABET_SIZE, 0);

            // Count character occurrences
            for (char c : word) {
                charFrequency[c - 'a']++;
            }

            // Create unique signature from frequency array
            std::string signature = "";
            for (int freq : charFrequency) {
                signature += std::to_string(freq) + "_";
            }

            // Group words by their signature
            frequencySignature_to_words[signature].push_back(word);
        }

        // Collect all groups into result
        std::vector<std::vector<std::string>> result;
        for (const auto& entry : frequencySignature_to_words) {
            result.push_back(entry.second);
        }

        return result;
    }
};

