	void GUI::UpdateMouseVisibility()
	{
		auto& imguiIO = ImGui::GetIO();
		const bool shouldShowCursor = IsOpen() || IsOnboarding();

		imguiIO.MouseDrawCursor = shouldShowCursor;
		if (shouldShowCursor)
			imguiIO.ConfigFlags &= ~ImGuiConfigFlags_NoMouse;
		else
			imguiIO.ConfigFlags |= ImGuiConfigFlags_NoMouse;
	}

	bool GUI::HandleWindowMessage(HWND hwnd, UINT msg, WPARAM wparam, LPARAM lparam)
	{
		if (msg == WM_KEYUP)
		{
			const bool isInsertPressed = (wparam == VK_INSERT);
			const bool isCtrlBackslashPressed = (wparam == VK_OEM_5) && ((GetKeyState(VK_CONTROL) & 0x8000) != 0);

			if (isInsertPressed || isCtrlBackslashPressed)
			{
				static POINT savedCursorPos{};
				if (m_IsOpen)
				{
					GetCursorPos(&savedCursorPos);
				}
				else if (savedCursorPos.x != 0 || savedCursorPos.y != 0)
				{
					SetCursorPos(savedCursorPos.x, savedCursorPos.y);
				}

				if (!IsOnboarding())
					Toggle();

				UpdateMouseVisibility();
				return true;
			}
		}
		return false;
	}

	void GUI::SetOnboarding(bool state)
	{
		m_Onboarding = state;
		UpdateMouseVisibility();
	}

