using namespace gte;

LogToFile::LogToFile(std::string const& filename, int flags)
    : Logger::Listener(flags),
      mFilename(filename)
{
    // Attempt to open the file and immediately close it to truncate if successful
    std::ofstream testStream(filename);
    if (testStream.is_open())
    {
        testStream.close();
        // File was successfully opened and closed; contents cleared by opening in default mode
    }
    else
    {
        // If opening failed, invalidate the filename so future writes are skipped
        mFilename.clear();
    }
}

void LogToFile::Report(std::string const& message)
{
    if (!mFilename.empty())
    {
        // Open file in append mode
        std::ofstream output(mFilename, std::ios_base::app | std::ios_base::out);
        if (output.is_open())
        {
            output << message;
            output.close();
        }
        else
        {
            // On failure, clear the filename to prevent repeated failed attempts
            mFilename.clear();
        }
    }
}

