#include <vector>
#include <algorithm>
#include <climits>

class Solution {
public:
    bool canReach(int leftPos, int rightPos, int startPos, int maxSteps) {
        // If target segment is entirely to the left of startPos
        if (rightPos <= startPos) {
            return (startPos - leftPos) <= maxSteps;
        }
        // If target segment is entirely to the right of startPos
        else if (leftPos >= startPos) {
            return (rightPos - startPos) <= maxSteps;
        }
        // If startPos is within the segment [leftPos, rightPos]
        else {
            // Two possible paths: go left first then right, or go right first then left
            int distToLeft = startPos - leftPos;
            int distToRight = rightPos - startPos;

            // Path 1: Go to left end first, then to right end
            int path1 = distToLeft * 2 + distToRight;
            // Path 2: Go to right end first, then to left end
            int path2 = distToRight * 2 + distToLeft;

            return (path1 <= maxSteps) || (path2 <= maxSteps);
        }
    }

    int maxTotalFruits(std::vector<std::vector<int>>& fruits, int startPos, int k) {
        int n = fruits.size();
        int result = 0;
        int currentSum = 0;
        int leftIndex = 0;

        for (int rightIndex = 0; rightIndex < n; ++rightIndex) {
            currentSum += fruits[rightIndex][1];

            // Shrink window from left while current range is invalid
            while (leftIndex <= rightIndex && 
                   !canReach(fruits[leftIndex][0], fruits[rightIndex][0], startPos, k)) {
                currentSum -= fruits[leftIndex][1];
                leftIndex++;
            }

            result = std::max(result, currentSum);
        }

        return result;
    }
};

