#include "wifi_power.h"
#include <WiFi.h>
#include <Preferences.h>
#include "wifi_store.h"

// Apply Wi-Fi power state: disable or enable connection based on input flag
void applyWifiPower(bool enabled)
{
  if (!enabled) {
    // Disable Wi-Fi auto-reconnect and disconnect from current network
    WiFi.setAutoReconnect(false);
    WiFi.disconnect(true, true);
    WiFi.mode(WIFI_OFF);
    return;
  }

  // Enable Wi-Fi station mode and prepare for reconnection
  WiFi.mode(WIFI_STA);
  WiFi.setAutoReconnect(true);

  String storedSsid, storedPass;
  if (wifiStoreLoad(storedSsid, storedPass)) {
    // Use loaded credentials to initiate connection
    WiFi.begin(storedSsid.c_str(), storedPass.c_str());
  } else {
    // No valid credentials found; prevent automatic reconnection attempts
    WiFi.setAutoReconnect(false);
    WiFi.disconnect(true, true);
  }
}

// Reset Wi-Fi settings by clearing saved credentials and disconnecting
void wifiResetSettings()
{
  // Clear saved SSID and password in non-volatile storage
  Preferences prefs;
  prefs.begin("rh_wifi", false);
  prefs.putString("ssid", "");
  prefs.putString("pass", "");
  prefs.end();

  // Force disconnection and wait briefly for stability
  WiFi.disconnect(true, true);
  delay(50);
}

#include "ps2recomp/elf_analyzer.h"
#include <iostream>
#include <string>

void showHelp()
{
    std::cout << "PS2 ELF Analyzer\n";
    std::cout << "Utility for inspecting PS2 ELF binaries and producing TOML configs for PS2Recomp\n\n";
    std::cout << "Command line: ps2_analyzer <source_elf> <dest_toml>\n";
    std::cout << "  source_elf   Path to the PlayStation 2 ELF binary to examine\n";
    std::cout << "  dest_toml    Path where the generated TOML configuration will be saved\n";
}

int main(int argc, char *argv[])
{
    if (argc != 3)
    {
        showHelp();
        return 1;
    }

    std::string inputBinary = argv[1];
    std::string outputConfig = argv[2];

    std::cout << "PS2 ELF Analyzer\n";
    std::cout << "----------------\n";
    std::cout << "Source ELF: " << inputBinary << "\n";
    std::cout << "Target TOML: " << outputConfig << "\n\n";

    try
    {
        ps2recomp::ElfAnalyzer analyzer(inputBinary);

        if (!analyzer.process())
        {
            std::cerr << "Error: Unable to process the ELF file\n";
            return 1;
        }

        if (!analyzer.writeToml(outputConfig))
        {
            std::cerr << "Error: Could not write the TOML configuration file\n";
            return 1;
        }

        std::cout << "\nProcessing finished successfully\n";
        std::cout << "Configuration saved to: " << outputConfig << "\n";
        std::cout << "\nNext step: run PS2Recomp with the generated config:\n";
        std::cout << "  ps2recomp " << outputConfig << "\n";

        return 0;
    }
    catch (const std::exception &err)
    {
        std::cerr << "Exception occurred: " << err.what() << "\n";
        return 1;
    }
}

#include <engLib/eng.h>

namespace engine::store::pythonBase {

//-----------------------------------------------------------------
/// @details
///		Make static, finalized configs
///	@param[out]	key
///		Receives the unique configuration key for this endpoint
//-----------------------------------------------------------------
Error IPythonEndpointBase::getConfigSubKey(Text &key) noexcept {
    // Early exit if no method exists
    if (!py::hasattr(m_pyEndpoint, "getConfigSubKey")) {
        return Parent::getConfigSubKey(key);
    }

    const auto python = localfcn()->Error {
        try {
            auto subkeyObj = m_pyEndpoint.attr("getConfigSubKey")();
            if (subkeyObj.is_none()) {
                return Parent::getConfigSubKey(key);
            }
            key = py::cast<std::string>(subkeyObj);
        } catch (...) {
            // Swallow exceptions; let callPython handle propagation if needed
        }
        return {};
    };

    return callPython(python);
}

//-----------------------------------------------------------------
/// @details
///		Validate the the service configuration. This should pretty
///		much not fail, but rather errors and warnings should be
///		place in the errors result. If it does return an error, the
///		configure task will put that error in errors automatically
///		and return a successful outcome for the task
///	@param[in]	syntaxOnly
///		Perform a syntax check only
//-----------------------------------------------------------------
Error IPythonEndpointBase::validateConfig(bool syntaxOnly) noexcept {
    // First, delegate to parent validation
    Error parentResult = Parent::validateConfig(syntaxOnly);
    if (parentResult) return parentResult;

    const auto python = localfcn()->Error {
        if (py::hasattr(m_pyEndpoint, "validateConfig")) {
            m_pyEndpoint.attr("validateConfig")(syntaxOnly);
        }
        return {};
    };

    return callPython(python);
}

//-----------------------------------------------------------------
/// @details
///		Congigure the list of the pipe stack filters
///	@param[out]	filters
///		The list of the filters required by endpoint
//-----------------------------------------------------------------
Error IPythonEndpointBase::getPipeFilters(IPipeFilters &filters) noexcept {
    // Try Python implementation first
    const auto python = localfcn()->Error {
        if (!py::hasattr(m_pyEndpoint, "getPipeFilters")) {
            return {};
        }

        pybind11::object rawResult = m_pyEndpoint.attr("getPipeFilters")();
        if (!py::isinstance<py::list>(rawResult)) {
            return {};  // Ignore non-list results silently
        }

        py::list pyFilters = rawResult.cast<py::list>();
        for (auto &elem : pyFilters) {
            if (py::isinstance<py::str>(elem)) {
                filters.emplace_back(Text{py::cast<std::string>(elem)});
            } else if (py::isinstance<py::dict>(elem)) {
                json::Value filterJson =
                    engine::python::pyjson::dictToJson(elem);
                filters.emplace_back(std::move(filterJson));
            } else {
                throw APERR(Ec::InvalidParam,
                            "getPipeFilters item must be str or dict");
            }
        }
        return {};
    };

    Error err = callPython(python);
    if (!err && !filters.empty()) {
        return err;
    }

    // Fallback to parent if Python didn't contribute
    return Parent::getPipeFilters(filters);
}

