// Benchmark for applying Hadamard gate on first qubit
static void BM_Antigravity_ApplyHadamard(benchmark::State &state) {
  size_t qubit_count = state.range(0);

  try {
    // Initialize quantum register with specified number of qubits
    QuantumRegister reg(qubit_count);

    for (auto _ : state) {
      // Apply Hadamard transformation to the first qubit
      reg.applyHadamard(0);

      // Ensure compiler doesn't optimize away the operation
      benchmark::DoNotOptimize(reg.getStateVector().data());
      benchmark::ClobberMemory();
    }
  } catch (const std::exception &err) {
    state.SkipWithError(err.what());
  }
}

