#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>
#include <iostream>

// Renamed struct to avoid direct copy; semantically identical
struct pair_data {
    int value;
    bool flag;
};

// Custom checker: verifies that two consecutive stack slots match int and bool
template <typename ErrorHandler>
bool sol_lua_check(sol::types<pair_data>, lua_State* L,
     int pos, ErrorHandler&& err_handler,
     sol::stack::record& tracker) {
    // Normalize negative indices to absolute positions
    int abs_pos = lua_absindex(L, pos);

    // Validate first slot is int, second is bool
    bool ok_int   = sol::stack::check<int>(L, abs_pos, err_handler);
    bool ok_bool  = sol::stack::check<bool>(L, abs_pos + 1, err_handler);

    // Mark usage of two stack entries
    tracker.use(2);
    return ok_int && ok_bool;
}

// Extractor: retrieves values from Lua stack into pair_data
pair_data sol_lua_get(sol::types<pair_data>, lua_State* L,
     int pos, sol::stack::record& tracker) {
    int abs_pos = lua_absindex(L, pos);

    // Fetch in order: int then bool
    int val = sol::stack::get<int>(L, abs_pos);
    bool flg = sol::stack::get<bool>(L, abs_pos + 1);

    tracker.use(2);
    return pair_data{val, flg};
}

// Pusher: pushes pair_data onto Lua stack as two values
int sol_lua_push(lua_State* L, const pair_data& data) {
    int pushed = sol::stack::push(L, data.value);   // +1
    pushed += sol::stack::push(L, data.flag);       // +1 more
    return pushed;                                  // total = 2
}

int main() {
    std::cout << "=== customization ===" << std::endl;
    std::cout << std::boolalpha;

    sol::state vm;
    vm.open_libraries(sol::lib::base);

    // Define a Lua function that echoes its arguments
    vm.script(R"(
        function echo(x, y)
            print(x, y)
            return x, y
        end
    )");

    // Retrieve the Lua function
    sol::function echo_fn = vm["echo"];

    // Call it with our custom type
    pair_data input{24, false};
    pair_data result = echo_fn(input);

    // Verify correctness
    SOL_ASSERT(result.value == 24);
    SOL_ASSERT(result.flag == false);

    std::cout << "result.value: " << result.value << std::endl;
    std::cout << "result.flag: " << result.flag << std::endl;
    std::cout << std::endl;

    return 0;
}

#include <shmem.h>
#include <stdio.h>

int main(void) {
    // Initialize the SHMEM runtime environment
    shmem_init();

    // Determine current PE identity and total count
    int my_id = shmem_my_pe();     // Current processing element index
    int total_pe = shmem_n_pes();  // Total number of processing elements

    // Print initial greeting from each PE
    printf("Greetings from PE %d among %d PEs\n", my_id, total_pe);

    // -------------------------------------------------------------------------
    // Demonstrate point-to-point symmetric memory communication
    // -------------------------------------------------------------------------

    // Allocate a shared integer in symmetric heap accessible by all PEs
    int* shared_data = (int*) shmem_malloc(sizeof(int));

    // Each PE writes its own ID into the shared location
    *shared_data = my_id;

    // Ensure all PEs have completed their write before proceeding
    shmem_barrier_all();

    // Compute which PE we will read from (next PE in ring topology)
    int target_pe = (my_id + 1) % total_pe;
    int fetched_value;

    // Perform blocking get operation to retrieve data from remote PE
    shmem_int_get(&fetched_value, shared_data, 1, target_pe);

    // Report what was received and from whom
    printf("PE %d obtained value %d from PE %d\n", my_id, fetched_value, target_pe);

    // Ensure all remote memory operations are globally visible
    shmem_quiet();

    // -------------------------------------------------------------------------
    // Resource cleanup
    // -------------------------------------------------------------------------
    shmem_free(shared_data);

    // Terminate SHMEM environment cleanly
    shmem_finalize();

    return 0;
}

