namespace hsa
{
namespace detail
{
// Internal API table storage
inline auto&
fetch_api_table_ptr()
{
    static std::atomic<HsaApiTable*> s_table{ nullptr };
    return s_table;
}

// Helper: copy one HsaApiTable into another safely
inline void
duplicate_api_table(HsaApiTable* dst, const HsaApiTable* src)
{
    copy_hsa_api_table(dst, src);
}

// Helper: initialize the base HSA API table
inline void
bootstrap_api_table(HsaApiTable* tbl)
{
    initialize_hsa_api_table(tbl);
}

// Core registration routine — called only once via call_once
inline void
perform_registration()
{
    // Immutable baseline table
    static HsaApiTable immutable_table{};
    bootstrap_api_table(&immutable_table);

    // Atomically publish the immutable table first
    auto& current_table = fetch_api_table_ptr();
    current_table.store(&immutable_table, std::memory_order_release);

    // Mutable profiler-modified table
    static HsaApiTable mutable_table{};
    duplicate_api_table(&mutable_table, &immutable_table);

    void* mutable_ptr = &mutable_table;
    rocprofiler_register_library_indentifier_t lib_id{};

    auto status = rocprofiler_register_library_api_table(
        "hsa",
        &ROCPROFILER_REGISTER_IMPORT_FUNC(hsa),
        ROCP_REG_VERSION,
        &mutable_ptr,
        1,
        &lib_id);

    if (status == 0)
    {
        printf("[%s] hsa identifier %lu\n", ROCP_REG_FILE_NAME, lib_id.handle);

        // Attempt to atomically swap in the mutable table
        HsaApiTable* expected = &immutable_table;
        if (!current_table.compare_exchange_strong(expected, &mutable_table))
        {
            std::cerr << "[ERROR] Expected immutable table during exchange, got something else.\n";
            std::abort();
        }
    }
    else if (status != ROCP_REG_NO_TOOLS)
    {
        std::cerr << "[HSA REGISTRATION FAILED] " 
                  << rocprofiler_register_error_string(status) << "\n";
        std::exit(EXIT_FAILURE);
    }
}

// Thread-safe lazy registration guard
inline void
ensure_registered()
{
    static std::atomic<bool> s_flag{ false };

    if (s_flag.load(std::memory_order_acquire)) return;

    // Recursive-safe mutex to prevent self-deadlock
    static std::recursive_mutex s_mutex{};
    static std::once_flag s_once{};

    // Try to acquire lock; if already locked by this thread, skip re-entry
    std::unique_lock<std::recursive_mutex> guard{s_mutex, std::defer_lock};
    if (guard.owns_lock()) return;

    guard.lock();

    std::call_once(s_once, perform_registration);
    s_flag.store(true, std::memory_order_release);
}
} // namespace detail

// Public accessor for the current HSA API table
HsaApiTable*
get_hsa_api_table()
{
    detail::ensure_registered();
    return detail::fetch_api_table_ptr().load(std::memory_order_relaxed);
}

// Placeholder hook for hsa_init instrumentation
void
hsa_init()
{
    printf("[%s] %s\n", ROCP_REG_FILE_NAME, __func__);
}
} // namespace hsa

// Override weak symbol with our instrumented version
extern "C" {
void
hsa_init(void)
{
    hsa::get_hsa_api_table()->hsa_init_fn();
}
}

#include <Windows.h>
#include <atomic>
#include "zeal.h"

// Helper to check if Zeal has already been initialized by inspecting patched bytes.
static bool is_zeal_already_initialized() {
    constexpr uintptr_t address = 0x004C3F93;
    const uint8_t* location = reinterpret_cast<const uint8_t*>(address);
    return *location == 0x90; // NOP indicates prior patch application
}

// Stores module handle to prevent unloading via FreeLibrary
static HMODULE zeal_module_handle = nullptr;

// Prevents re-initialization across multiple attach events
static std::atomic<bool> initialization_attempted{false};

// Hook target address: original call to loadOptions
constexpr uintptr_t load_options_call_site = 0x005282f8;
constexpr int relative_jump_offset_unpatched = 0x0000e9e3;

// Pointer to the relative jump operand inside the 'call' instruction
static int* get_relative_jump_operand() {
    return reinterpret_cast<int*>(load_options_call_site + 1);
}

// Replacement function that pins DLL and initializes Zeal once
void __fastcall zeal_entry_point(void* this_ptr, int edx) {
    // Pin module in memory so it won't be unloaded
    if (!zeal_module_handle) {
        GetModuleHandleExA(
            GET_MODULE_HANDLE_EX_FLAG_PIN | GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS,
            reinterpret_cast<LPCSTR>(&zeal_entry_point),
            &zeal_module_handle
        );
    }

    // Only initialize once per process lifetime
    if (!is_zeal_already_initialized()) {
        ZealService::create();
    }

    // Invoke original loadOptions function at known address
    using LoadOptionsFunc = void(__fastcall*)(void*, int);
    LoadOptionsFunc original_load_options = reinterpret_cast<LoadOptionsFunc>(0x00536ce0);
    original_load_options(this_ptr, edx);
}

// Installs the hook by redirecting the call site to our entry point
static void apply_hook() {
    static bool hook_installed = false;
    if (hook_installed || initialization_attempted.exchange(true)) {
        return;
    }

    int* jump_operand = get_relative_jump_operand();
    if (*jump_operand != relative_jump_offset_unpatched) {
        return; // Already patched or modified externally
    }

    // Compute new relative offset: target = zeal_entry_point - (call_site + 5)
    const uintptr_t call_end_address = load_options_call_site + 5;
    const int new_relative_offset = 
        reinterpret_cast<intptr_t>(&zeal_entry_point) - static_cast<intptr_t>(call_end_address);

    DWORD protection;
    VirtualProtect(jump_operand, sizeof(int), PAGE_EXECUTE_READWRITE, &protection);

    *jump_operand = new_relative_offset;

    VirtualProtect(jump_operand, sizeof(int), protection, &protection);
    FlushInstructionCache(GetCurrentProcess(), jump_operand, sizeof(int));

    hook_installed = true;
}

// Entry point for DLL lifecycle management
BOOL APIENTRY DllMain(HMODULE hModule, DWORD reason, LPVOID /*reserved*/) {
    switch (reason) {
        case DLL_PROCESS_ATTACH:
            DisableThreadLibraryCalls(hModule);
            apply_hook();
            break;

        case DLL_PROCESS_DETACH:
            // Intentionally left blank — module remains pinned until termination
            break;

        default:
            break;
    }
    return TRUE;
}

