void ThrownEnderpearl::onHit(HitResult *hitResult)
{
	// Handle entity hit
	if (nullptr != hitResult->entity)
	{
		DamageSource *damage = DamageSource::thrown(shared_from_this(), owner);
		hitResult->entity->hurt(damage, 0);
		delete damage;
	}

	// Spawn particles
	int particleCount = 32;
	for (int idx = 0; idx < particleCount; ++idx)
	{
		double offsetX = random->nextGaussian();
		double offsetZ = random->nextGaussian();
		double offsetY = random->nextDouble() * 2.0;
		level->addParticle(eParticleType_ender, x, y + offsetY, z, offsetX, 0.0, offsetZ);
	}

	// Server-side behavior only
	if (!level->isClientSide)
	{
		// Fix for #67486 - TCR #001: BAS Game Stability: Customer Encountered: TU8: Code: Gameplay: The title crashes on Host's console when Client Player leaves the game before the Ender Pearl thrown by him touches the ground.
		shared_ptr<ServerPlayer> playerPtr = dynamic_pointer_cast<ServerPlayer>(owner);
		if (playerPtr && !playerPtr->removed)
		{
			PlayerConnection *conn = playerPtr->connection.get();
			if (conn && !conn->done && playerPtr->level == level)
			{
				owner->teleportTo(x, y, z);
				owner->fallDistance = 0.0f;
				owner->hurt(DamageSource::fall, 5);
			}
		}
		remove();
	}
}

#include <asio/post.hpp>
#include <asio/thread_pool.hpp>
#include <iostream>

using asio::post;
using asio::thread_pool;

// Modified active object pattern implementation
class bank_account
{
    int current_balance_ = 0;
    mutable thread_pool worker_pool_{1};

public:
    void credit(int value)
    {
        post(worker_pool_, [this, value]
            {
                current_balance_ += value;
            });
    }

    void debit(int value)
    {
        post(worker_pool_, [this, value]
            {
                if (current_balance_ >= value)
                    current_balance_ -= value;
            });
    }

    void display_status() const
    {
        post(worker_pool_, [this]
            {
                std::cout << "account balance: " << current_balance_ << "\n";
            });
    }

    ~bank_account()
    {
        worker_pool_.join();
    }
};

int main()
{
    bank_account account;
    account.credit(20);
    account.debit(10);
    account.display_status();
}

#include "isdiag.h"
template <typename Scalar>
IGL_INLINE bool igl::isdiag(const Eigen::SparseMatrix<Scalar> & A)
{
  // Check each non-zero entry to ensure it lies on the diagonal
  for(int outer = 0; outer < A.outerSize(); ++outer)
  {
    for(typename Eigen::SparseMatrix<Scalar>::InnerIterator it(A, outer); it; ++it)
    {
      // If a non-zero element is found off the main diagonal, matrix is not diagonal
      if(it.row() != it.col() && it.value() != Scalar(0))
      {
        return false;
      }
    }
  }
  return true;
}
