#include <iostream>
#include <vector>
using namespace std;

// LeetCode 136: Single Number - Alternative Implementation
// Given a non-empty array of integers nums, every element appears twice except for one. Find that single one.
// You must implement a solution with a linear runtime complexity and use only constant extra space.
class Solution {
public:
    int singleNumber(vector<int>& nums) {
        int result = 0;
        int index = 0;
        int size = nums.size();

        while (index < size) {
            result ^= nums[index];
            index++;
        }

        return result;
    }
};

// Logic Explanation:
// We can use the XOR bitwise operation to solve this problem efficiently.
// The XOR operation has the following properties:
// 1. a ^ a = 0 (any number XORed with itself is 0)
// 2. a ^ 0 = a (any number XORed with 0 is the number itself)
// 3. XOR is commutative and associative, meaning the order of operations does not matter.
// By XORing all the numbers in the array together, the numbers that appear twice will cancel each other out
// (resulting in 0), and we will be left with the single number that appears only once.
// Time Complexity: O(n) where n is the number of elements in the array.
// Space Complexity: O(1) since we are using only a constant amount of extra space.

#include <iostream>
#include <string>
#include <vector>
#include <cctype>

// Convert character to index: 'A'-'Z' -> 0-25, '0'-'9' -> 26-35
inline int char_to_index(char c) {
    if (std::isupper(c)) {
        return c - 'A';
    }
    // Based on problem constraints, assume c is a digit
    return c - '0' + 26;
}

// Greedy matching function: builds subsequence by scanning target string
// using precomputed positions of characters from source string
std::string build_subsequence(const std::string& source, const std::vector<std::vector<int>>& char_positions) {
    std::string result;
    if (source.empty()) {
        return result;
    }

    result.reserve(source.size());
    int last_matched_pos = -1;
    std::vector<int> position_pointers(36, 0);

    for (char ch : source) {
        int idx = char_to_index(ch);
        const std::vector<int>& positions = char_positions[idx];
        int& ptr = position_pointers[idx];

        // Skip positions that are before or at the last matched position
        while (ptr < static_cast<int>(positions.size()) && positions[ptr] <= last_matched_pos) {
            ++ptr;
        }

        // If we found a valid position, include this character in result
        if (ptr < static_cast<int>(positions.size())) {
            result.push_back(ch);
            last_matched_pos = positions[ptr];
            ++ptr;
        }
    }

    return result;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::string str_a, str_b;
    std::cin >> str_a >> str_b;

    // Precompute character positions for both strings
    std::vector<std::vector<int>> pos_map_a(36);
    std::vector<std::vector<int>> pos_map_b(36);

    for (size_t i = 0; i < str_a.length(); ++i) {
        pos_map_a[char_to_index(str_a[i])].push_back(static_cast<int>(i));
    }
    for (size_t i = 0; i < str_b.length(); ++i) {
        pos_map_b[char_to_index(str_b[i])].push_back(static_cast<int>(i));
    }

    // Try both directions: match str_a in str_b and vice versa
    std::string candidate_1 = build_subsequence(str_a, pos_map_b);
    std::string candidate_2 = build_subsequence(str_b, pos_map_a);

    // Output the longer common subsequence
    if (candidate_1.length() >= candidate_2.length()) {
        std::cout << candidate_1 << '\n';
    } else {
        std::cout << candidate_2 << '\n';
    }

    return 0;
}

