namespace py = pybind11;

/**
 * @brief Compute eigenvalues and eigenvectors for a real symmetric matrix using LAPACK's syev.
 *
 * @param input_matrix Input dense square matrix (NumPy array).
 * @return A tuple with the computed eigenvalues and corresponding eigenvectors.
 */
py::tuple compute_eigen_decomposition(const py::array_t<double>& input_matrix) {
  // Ensure the input is a 2D array
  if (input_matrix.ndim() != 2) {
    throw std::invalid_argument("Input must be a 2-dimensional array.");
  }

  auto dims = input_matrix.shape();
  if (dims[0] != dims[1]) {
    throw std::invalid_argument("Matrix must be square.");
  }

  int size = dims[0];

  // Convert NumPy array to Eigen matrix
  Eigen::MatrixXd A = Eigen::Map<const Eigen::MatrixXd>(input_matrix.data(), size, size);
  Eigen::VectorXd eigen_vals(size);

  // Call LAPACK's syev routine to compute eigenvalues and eigenvectors
  int result = lapack::syev(lapack::Job::Vec, lapack::Uplo::Lower, size, 
                            A.data(), size, eigen_vals.data());

  if (result != 0) {
    throw std::runtime_error("LAPACK syev computation failed.");
  }

  return py::make_tuple(eigen_vals, A);
}

/**
 * @brief Register the eigenvalue solver in the Python module.
 */
void register_eigen_solver(py::module& module) {
  module.def("eigen_solver", &compute_eigen_decomposition,
             R"(
                Solve eigenvalue problem for a real symmetric matrix via LAPACK's syev.

                Parameters
                ----------
                input_matrix : numpy.ndarray
                    Real symmetric dense matrix.

                Returns
                -------
                tuple
                    - ``eigenvalues``: 1-D numpy.ndarray of shape (n,), sorted in ascending order
                    - ``eigenvectors``: 2-D numpy.ndarray of shape (n, n), where column i is the eigenvector for eigenvalue i

                Raises
                ------
                ValueError
                    If the input is not a square matrix.
                RuntimeError
                    If the underlying LAPACK routine fails.
            )",
             py::arg("input_matrix"));
}

#include <vector>
#include <algorithm>

class Solution {
public:
    int maximumWealth(std::vector<std::vector<int>>& accounts) {
        int totalRows = accounts.size();
        if (totalRows == 0) return 0;

        int maxWealth = 0;
        for (int row = 0; row < totalRows; ++row) {
            int currentSum = 0;
            for (int col = 0; col < accounts[row].size(); ++col) {
                currentSum += accounts[row][col];
            }
            maxWealth = std::max(maxWealth, currentSum);
        }
        return maxWealth;
    }
};

#include <asio.hpp>
#include <iostream>

// Bank account implementation using active object pattern with thread pool
class bank_account
{
    int balance_ = 0;
    mutable asio::thread_pool pool_{1};

public:
    void deposit(int amount)
    {
        auto result = asio::post(pool_,
            [this, amount]
            {
                balance_ += amount;
            });
        result.get();
    }

    bool withdraw(int amount)
    {
        auto result = asio::post(pool_,
            [this, amount]
            {
                if (balance_ >= amount)
                {
                    balance_ -= amount;
                    return true;
                }
                return false;
            });
        return result.get();
    }

    int get_balance() const
    {
        auto result = asio::post(pool_,
            [this]
            {
                return balance_;
            });
        return result.get();
    }
};

int main()
{
    bank_account account;
    account.deposit(20);
    account.withdraw(10);
    std::cout << "Current balance: " << account.get_balance() << "\n";
    return 0;
}

