int main() {
    // Initialize visualization window
    mplot::Visual viewer(1400, 1300, "Demo: Grid Image Resampling");
    viewer.setSceneTrans(sm::vec<float, 3>({-2.60691f, 1.39885f, -11.1f}));

    const unsigned int downscaleFactor = 2U;
    sm::vec<float, 2> baseSpacing = {0.02f, 0.02f};
    sm::vec<float, 2> coarserSpacing = baseSpacing * downscaleFactor;

    // Original fine grid
    sm::grid originalGrid{256U, 64U, baseSpacing};
    std::cout << "Original grid extents: (xmin,xmax,ymin,ymax): " << originalGrid.extents() << '\n';

    // Coarser grid for resampling
    sm::grid coarseGrid{256U / downscaleFactor, 64U / downscaleFactor, coarserSpacing};
    std::cout << "Coarse grid extents: (xmin,xmax,ymin,ymax): " << coarseGrid.extents() << '\n';

    // Load image
    const std::string imagePath = "../examples/bike256_64.png";
    sm::vvec<float> pixelData;
    sm::vec<unsigned int, 2> imageDims = mplot::loadpng(imagePath, pixelData);
    std::cout << "Loaded image dimensions: " << imageDims << '\n';

    if (imageDims[0] != 256) {
        std::cerr << "Error: Expected image width 256, got " << imageDims[0] << '\n';
        return -1;
    }

    // Helper lambda to resample image onto a given grid
    auto resampleImageOntoGrid = [](const sm::grid& targetGrid,
                                    const sm::vvec<float>& srcPixels,
                                    unsigned int srcWidth,
                                    const sm::vec<float, 2>& scale = {1.0f, 1.0f},
                                    const sm::vec<float, 2>& offset = {0.0f, 0.0f}) {
        return targetGrid.resample_image(srcPixels, srcWidth, scale, offset);
    };

    // Resample onto coarse grid
    sm::vvec<float> resampledOnCoarse = resampleImageOntoGrid(coarseGrid, pixelData, imageDims[0]);

    // Prepare hexagonal grid for alternative resampling
    sm::vec<float, 2> hexSpacing = coarseGrid.get_dx();
    sm::hexgrid hexGrid{hexSpacing[0], static_cast<float>(coarseGrid.width()) * 2.0f, 0.0f};
    hexGrid.setRectangularBoundary(coarseGrid.width(), coarseGrid.height());

    // Hex resampling requires scaling to match rectangular domain size
    sm::vec<float, 2> hexScale{static_cast<float>(coarseGrid.width()), static_cast<float>(coarseGrid.width())};
    sm::vvec<float> resampledOnHex = hexGrid.resampleImage(pixelData, imageDims[0], hexScale, {0.0f, 0.0f});

    // === Visualization Setup ===

    // Original image on fine grid
    auto originalVisual = std::make_unique<mplot::GridVisual<float>>(&originalGrid, {0, 0, 0});
    viewer.bindmodel(originalVisual);
    originalVisual->gridVisMode = mplot::GridVisMode::RectInterp;
    originalVisual->setScalarData(&pixelData);
    originalVisual->cm.setType(mplot::ColourMapType::GreyscaleInv);
    originalVisual->zScale.null_scaling();
    originalVisual->addLabel("Original", {0, -0.2, 0}, mplot::TextFeatures(0.1f));
    originalVisual->finalize();
    viewer.addVisualModel(originalVisual);

    // Resampled image on coarse grid
    auto coarseVisual = std::make_unique<mplot::GridVisual<float>>(
        &coarseGrid, sm::vec<float>{0.0f, -2.0f, 0.0f});
    viewer.bindmodel(coarseVisual);
    coarseVisual->gridVisMode = mplot::GridVisMode::RectInterp;
    coarseVisual->setScalarData(&resampledOnCoarse);
    coarseVisual->cm.setType(mplot::ColourMapType::GreyscaleInv);
    coarseVisual->zScale.null_scaling();
    coarseVisual->addLabel("Resampled to coarser grid", {0, -0.2, 0}, mplot::TextFeatures(0.1f));
    coarseVisual->finalize();
    viewer.addVisualModel(coarseVisual);

    // Resampled image on hex grid
    auto hexVisual = std::make_unique<mplot::HexGridVisual<float>>(
        &hexGrid, sm::vec<float>{
            static_cast<float>(coarseGrid.width()) / 2.0f,
            static_cast<float>(coarseGrid.height()) / 2.0f - 4.0f,
            0.0f
        });
    viewer.bindmodel(hexVisual);
    hexVisual->setScalarData(&resampledOnHex);
    hexVisual->cm.setType(mplot::ColourMapType::GreyscaleInv);
    hexVisual->zScale.null_scaling();
    hexVisual->addLabel(
        "Resampled to hexgrid",
        {-static_cast<float>(coarseGrid.width()) / 2.0f,
         -0.2f - static_cast<float>(coarseGrid.height()) / 2.0f,
         0},
        mplot::TextFeatures(0.1f)
    );
    hexVisual->finalize();
    viewer.addVisualModel(hexVisual);

    // Keep window open
    viewer.keepOpen();
    return 0;
}

