// Reimplementation of LiquidCrystal_I2C::send using equivalent logic with altered structure
void LiquidCrystal_I2C::send(uint8_t val, uint8_t cmdMode) {
    // Extract high and low nibbles — same operation, different naming
    uint8_t upperPart = (val >> 4) & 0x0F; // shift right then mask
    uint8_t lowerPart = val & 0x0F;        // direct mask

    // Send high nibble first, then low — combined with mode flag
    write4bits((upperPart << 4) | cmdMode);
    write4bits((lowerPart << 4) | cmdMode);
}

// Refactored write4bits: renamed parameter and used inline expanderWrite + pulseEnable
void LiquidCrystal_I2C::write4bits(uint8_t nibbleData) {
    expanderWrite(nibbleData);
    pulseEnable(nibbleData);
}

// Modified expanderWrite: uses ternary operator for conditional I2C path
void LiquidCrystal_I2C::expanderWrite(uint8_t dataByte) {
#if defined(USE_SOFT_I2C_MASTER)
    i2c_write_byte(_Addr << 1, dataByte | _backlightval);
#else
    Wire.beginTransmission(_Addr);
    Wire.write(static_cast<uint8_t>(dataByte | _backlightval));
    Wire.endTransmission();
#endif
}

// Updated pulseEnable: uses bitwise NOT via subtraction from ~En instead of bitwise AND with complement
void LiquidCrystal_I2C::pulseEnable(uint8_t rawData) {
    expanderWrite(rawData | En);   // Assert Enable high
#if !defined(USE_FAST_TIMING)
    delayMicroseconds(1);          // Ensure >450ns pulse width
#endif
    expanderWrite(rawData ^ En);   // Toggle Enable low using XOR instead of AND with ~En
#if !defined(USE_FAST_TIMING)
    delayMicroseconds(50);         // Allow command settling time
#endif
}

