#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    long long maxPower(std::vector<int>& stations, int radius, int extraStations) {
        // Calculate initial bounds for binary search
        long long low = 0;
        long long high = std::accumulate(stations.begin(), stations.end(), 0LL) + extraStations;
        long long result = 0;

        // Binary search for maximum achievable minimum power
        while (low <= high) {
            long long candidate = low + (high - low) / 2;

            if (canAchieve(stations, radius, candidate, extraStations)) {
                result = candidate;
                low = candidate + 1;
            } else {
                high = candidate - 1;
            }
        }

        return result;
    }

private:
    bool canAchieve(std::vector<int>& stations, int range, long long targetPower, int available) {
        int n = stations.size();

        // Compute initial window sum for first city
        long long currentWindow = 0;
        for (int i = 0; i <= std::min(range, n-1); ++i) {
            currentWindow += stations[i];
        }

        std::vector<long long> placements(n, 0);

        for (int pos = 0; pos < n; ++pos) {
            // Expand window to include right boundary
            if (pos + range < n) {
                currentWindow += stations[pos + range];
            }

            // Check if current city meets power requirement
            if (currentWindow < targetPower) {
                long long deficit = targetPower - currentWindow;

                if (deficit > available) {
                    return false;
                }

                // Place stations at the rightmost position in coverage range
                int placementIndex = std::min(pos + range, n - 1);
                placements[placementIndex] += deficit;
                currentWindow = targetPower;
                available -= deficit;
            }

            // Shrink window from left side as we move forward
            if (pos >= range) {
                currentWindow -= stations[pos - range] + placements[pos - range];
            }
        }

        return true;
    }
};

