// Atomic pointer to hold the current HIP API table
std::atomic<HipApiTable*>& get_api_table_ptr() {
    static std::atomic<HipApiTable*> s_table{nullptr};
    return s_table;
}

void do_registration() {
    // Immutable baseline table
    static HipApiTable s_const_table{};
    initialize_hip_api_table(&s_const_table);

    // Atomically install the const table as initial value
    auto* expected = nullptr;
    if (!get_api_table_ptr().compare_exchange_strong(expected, &s_const_table)) {
        // Should not happen in normal flow; indicates misuse
        std::cerr << "do_registration failed to set initial API table.\n";
        abort();
    }

    // Mutable copy for profiler instrumentation
    static HipApiTable s_profiler_table{};
    copy_hip_api_table(&s_profiler_table, &s_const_table);

    void* profiler_table_ptr = &s_profiler_table;
    rocprofiler_register_library_indentifier_t lib_id{};

    auto result = rocprofiler_register_library_api_table(
        "hip",
        &ROCPROFILER_REGISTER_IMPORT_FUNC(hip),
        ROCP_REG_VERSION,
        &profiler_table_ptr,
        1,
        &lib_id);

    if (result == 0) {
        // Ensure only one successful registration path
        HipApiTable* current = &s_const_table;
        if (!get_api_table_ptr().compare_exchange_strong(current, &s_profiler_table)) {
            std::cerr << "do_registration: unexpected table replacement during registration.\n";
            abort();
        }
    }
}

void ensure_registered() {
    static std::atomic<bool> s_is_done{false};
    if (!s_is_done.load(std::memory_order_acquire)) {
        using recursive_mutex_type = std::recursive_mutex;
        using lock_guard_type      = std::unique_lock<recursive_mutex_type>;

        static std::once_flag s_init_once{};
        static recursive_mutex_type s_mutex{};

        // Defer locking to detect recursion before acquiring
        lock_guard_type guard{s_mutex, std::defer_lock};

        // If this thread already owns the lock (i.e., re-entrant call), skip full registration
        if (guard.owns_lock()) {
            return;
        }

        guard.lock();  // Now safely acquire lock for non-reentrant case

        std::call_once(s_init_once, do_registration);
        s_is_done.store(true, std::memory_order_release);
    }
}

}  // namespace

HipApiTable* get_hip_api_table() {
    ensure_registered();
    return get_api_table_ptr().load(std::memory_order_relaxed);
}

