TEST_CASE("InitCommand: Models are from sentence-transformers", "[cli][init][models]") {
    for (const auto& spec : MODEL_LIST) {
        INFO("Checking model: " << spec.identifier);
        REQUIRE(spec.download_url.find("sentence-transformers") != std::string::npos);
    }
}

