// Helper function to print existence and value of a key in an environment
void inspect_key(const sol::environment& target_env,
                 const sol::state_view& lua_state,
                 std::string_view key_name) {
    // Check presence in target environment
    bool in_target = target_env[key_name].has_value();
    // Check presence in global environment
    bool in_global = lua_state[key_name].has_value();

    // Report global status
    if (in_global) {
        std::cout << "\t'" << key_name << "' is "
                  << lua_state[key_name].get<int>() 
                  << " in the global environment\n";
    } else {
        std::cout << "\t'" << key_name 
                  << "' does not exist in the global environment\n";
    }

    // Report target environment status
    if (in_target) {
        std::cout << "\t'" << key_name << "' is "
                  << target_env[key_name].get<int>()
                  << " in target environment\n";
    } else {
        std::cout << "\t'" << key_name 
                  << "' does not exist in target environment\n";
    }
}

int main(int, char*[]) {
    std::cout << "=== environments ===\n";

    sol::state lua_vm;

    // Set up global variable for fallback testing
    lua_vm["b"] = 2142;

    // Create isolated environment without fallback
    sol::environment isolated_env = sol::environment::create(lua_vm);
    lua_vm.script("a = 24", isolated_env);

    std::cout << "-- target: isolated_env\n";
    inspect_key(isolated_env, lua_vm, "a");
    inspect_key(isolated_env, lua_vm, "b");

    std::cout << "\n";

    // Create environment with fallback to globals
    sol::environment env_with_fallback = 
        sol::environment::create(lua_vm, lua_vm.globals());
    lua_vm.script("a = 56", env_with_fallback);

    std::cout << "-- target: env_with_fallback (fallback is "
                 "global table)\n";
    inspect_key(env_with_fallback, lua_vm, "a");
    inspect_key(env_with_fallback, lua_vm, "b");

    return 0;
}

#include <assert.h>
#include <math.h>
#include <mpi.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Generates an array of random floating-point values in range [0, 1]
float*
generate_random_values(int count)
{
    float* values = (float*) malloc(sizeof(float) * count);
    assert(values != NULL);

    for (int idx = 0; idx < count; ++idx) {
        values[idx] = static_cast<float>(rand()) / static_cast<float>(RAND_MAX);
    }

    return values;
}

int
main(int argc, char** argv)
{
    if (argc != 2) {
        fprintf(stderr, "Usage: stddev num_elements_per_process\n");
        exit(EXIT_FAILURE);
    }

    int elements_per_rank = atoi(argv[1]);

    MPI_Init(nullptr, nullptr);

    int my_rank;
    MPI_Comm_rank(MPI_COMM_WORLD, &my_rank);

    int total_ranks;
    MPI_Comm_size(MPI_COMM_WORLD, &total_ranks);

    // Initialize different random seeds per process
    srand(static_cast<unsigned>(time(NULL)) ^ (my_rank + 1));

    float* data = generate_random_values(elements_per_rank);

    // Compute local sum
    float local_total = 0.0f;
    for (int pos = 0; pos < elements_per_rank; ++pos) {
        local_total += data[pos];
    }

    // Aggregate all local sums to get global sum
    float global_total;
    MPI_Allreduce(&local_total, &global_total, 1, MPI_FLOAT, MPI_SUM, MPI_COMM_WORLD);

    // Calculate overall mean
    float avg = global_total / static_cast<float>(elements_per_rank * total_ranks);

    // Compute local sum of squared deviations from the mean
    float local_variance_sum = 0.0f;
    for (int idx = 0; idx < elements_per_rank; ++idx) {
        float diff = data[idx] - avg;
        local_variance_sum += diff * diff;
    }

    // Reduce to root process
    float global_variance_sum;
    MPI_Reduce(&local_variance_sum, &global_variance_sum, 1, MPI_FLOAT, MPI_SUM, 0, MPI_COMM_WORLD);

    // Output results on root process
    if (my_rank == 0) {
        float variance = global_variance_sum / static_cast<float>(elements_per_rank * total_ranks);
        float std_dev = sqrt(variance);
        printf("Mean - %f, Standard deviation = %f\n", avg, std_dev);
    }

    // Cleanup resources
    free(data);
    MPI_Barrier(MPI_COMM_WORLD);
    MPI_Finalize();

    return 0;
}

