#include "pugixml.hpp"
#include <string.h>
#include <iostream>

int main() {
    pugi::xml_document doc;
    if (!doc.load_string("<node id='123'>text</node><!-- comment -->", 
                         pugi::parse_default | pugi::parse_comments)) {
        return -1;
    }

    // Retrieve the node element
    pugi::xml_node element = doc.child("node");

    // Rename the node and display results
    std::cout << element.set_name("renamedNode") << ", ";
    std::cout << "updated node name: " << element.name() << std::endl;

    // Access and modify the comment node (last child)
    pugi::xml_node commentNode = doc.last_child();
    std::cout << commentNode.set_value("modified comment") << ", ";
    std::cout << "new comment content: " << commentNode.value() << std::endl;

    // Attempt invalid operations: setting value on element, name on comment
    std::cout << element.set_value("ignored") << ", " 
              << commentNode.set_name("invalid") << std::endl;

    // Attribute manipulation section
    pugi::xml_attribute attribute = element.attribute("id");

    // Modify attribute name and value
    std::cout << attribute.set_name("identifier") << ", " 
              << attribute.set_value("789");
    std::cout << ", updated attribute: " << attribute.name() << "=" << attribute.value() << std::endl;

    // Assign numeric and boolean values to attribute
    attribute.set_value(3.14159);
    std::cout << "numeric attribute value: " << attribute.value() << std::endl;

    // Use assignment operator for concise updates
    attribute = false;
    std::cout << "final boolean attribute value: " << attribute.value() << std::endl;

    return 0;
}

