    SAVE_INSTANTIATE(tag_component, ser20::oarchive_binary_t);

    // Serialization: Load operation
    LOAD(tag_component)
    {
        // Deserialize using named value pairs
        auto&& [n, t] = std::tie(obj.name, obj.tag);
        try_load(ar, ser20::make_nvp("name", n));
        try_load(ar, ser20::make_nvp("tag", t));
    }

    // Instantiate load for both archive types
    LOAD_INSTANTIATE(tag_component, ser20::iarchive_associative_t);
    LOAD_INSTANTIATE(tag_component, ser20::iarchive_binary_t);
} // namespace unravel

