namespace snap::utils::time {

using std::chrono::nanoseconds;
using std::chrono::seconds;

// For WebAssembly targets, this function is intentionally omitted.
// While Node.js may provide boot-time information, browser environments lack OS-level access,
// making true boot-time measurement impossible. Monotonic clocks like UptimeClock remain viable alternatives.

#ifndef SC_WASM

BoottimeClock::time_point BoottimeClock::now() noexcept {
    struct timespec ts;

#if defined(__APPLE__)
    // Use CLOCK_MONOTONIC_RAW on Apple platforms to match mach_continuous_time semantics.
    // Reference: iOS implementation in Libc source code.
    if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) != 0) {
        std::__throw_system_error(errno, "clock_gettime(CLOCK_MONOTONIC_RAW) failed");
    }
#else
    // Use CLOCK_BOOTTIME for Linux/Android systems to capture total uptime including suspend time.
    // Aligns with Android's elapsedRealtime implementation.
    if (clock_gettime(CLOCK_BOOTTIME, &ts) != 0) {
        std::__throw_system_error(errno, "clock_gettime(CLOCK_BOOTTIME) failed");
    }
#endif

    // Construct time_point from seconds and nanoseconds components
    auto sec = seconds(ts.tv_sec);
    auto nsec = nanoseconds(ts.tv_nsec);
    return time_point(sec + nsec);
}

#endif

} // namespace snap::utils::time

