// Helper function to perform a swap operation via interactive communication
void interact_swap(int idx1, int idx2) {
    if (idx1 == idx2) return;
    std::cout << "2 " << idx1 << " " << idx2 << std::endl;
    int temp;
    std::cin >> temp;
}

// Helper function to query the number of adjacent value segments in range [l, r]
int interact_query(int left, int right) {
    std::cout << "1 " << left << " " << right << std::endl;
    int result;
    std::cin >> result;
    return result;
}

// Output the final permutation answer
void output_result(const std::vector<int>& result_perm) {
    std::cout << "3";
    for (size_t k = 1; k < result_perm.size(); ++k) {
        std::cout << " " << result_perm[k];
    }
    std::cout << std::endl;
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n, len1, len2;
    std::cin >> n >> len1 >> len2;

    // Track where each original element currently resides: pos[value] = current_position
    std::vector<int> pos(n + 1);
    std::iota(pos.begin(), pos.end(), 0);

    // Build a chain by iteratively extending it with adjacent-value neighbors
    for (int chain_end = 1; chain_end < n; ++chain_end) {
        bool found_neighbor = false;

        // Try each remaining candidate position
        for (int candidate_pos = chain_end + 1; candidate_pos <= n && !found_neighbor; ++candidate_pos) {
            // Temporarily bring candidate to position chain_end+1
            interact_swap(chain_end + 1, candidate_pos);
            std::swap(pos[chain_end + 1], pos[candidate_pos]);

            // Check if positions chain_end and chain_end+1 now contain adjacent values
            if (interact_query(chain_end, chain_end + 1) == 3) {
                found_neighbor = true;
                // Keep this neighbor at position chain_end+1
            } else {
                // Restore previous state for next iteration
                interact_swap(chain_end + 1, candidate_pos);
                std::swap(pos[chain_end + 1], pos[candidate_pos]);
            }
        }
    }

    // Reconstruct the actual permutation values based on final positions
    std::vector<int> final_values(n + 1);
    for (int position = 1; position <= n; ++position) {
        final_values[pos[position]] = position;
    }

    // Output the determined permutation
    output_result(final_values);
    return 0;
}

#include "llvm/Transforms/Utils/UnifyFunctionExitNodes.h"
#include "llvm/IR/BasicBlock.h"
#include "llvm/IR/Function.h"
#include "llvm/IR/Instructions.h"
#include "llvm/IR/Type.h"
#include "llvm/Transforms/Utils.h"

using namespace llvm;

namespace {

// Merge all unreachable terminators into a single block
bool consolidateUnreachableTargets(Function &func) {
  SmallVector<BasicBlock *, 8> unreachableCandidates;
  for (auto &block : func) {
    if (isa<UnreachableInst>(block.getTerminator()))
      unreachableCandidates.push_back(&block);
  }

  if (unreachableCandidates.size() <= 1)
    return false;

  // Create a new unified unreachable block
  BasicBlock *unifiedBlock = BasicBlock::Create(
      func.getContext(), "MergedUnreachable", &func);
  new UnreachableInst(func.getContext(), unifiedBlock);

  // Replace each original unreachable terminator with a branch to the unified block
  for (BasicBlock *bb : unreachableCandidates) {
    Instruction *term = &bb->back();
    term->dropAllReferences();
    term->eraseFromParent();
    BranchInst::Create(unifiedBlock, bb);
  }

  return true;
}

// Merge all return instructions into one block, handling return values via PHI nodes
bool consolidateReturnPoints(Function &func) {
  SmallVector<BasicBlock *, 8> returnBlocks;
  for (BasicBlock &blk : func) {
    if (isa<ReturnInst>(blk.getTerminator()))
      returnBlocks.push_back(&blk);
  }

  if (returnBlocks.size() <= 1)
    return false;

  // Create a new unified return block
  BasicBlock *mergeRetBlock = BasicBlock::Create(
      func.getContext(), "MergedReturn", &func);

  PHINode *phiNode = nullptr;
  Type *retType = func.getReturnType();

  if (retType->isVoidTy()) {
    ReturnInst::Create(func.getContext(), nullptr, mergeRetBlock);
  } else {
    phiNode = PHINode::Create(retType, returnBlocks.size(), "MergedRetVal");
    phiNode->insertInto(mergeRetBlock, mergeRetBlock->end());
    ReturnInst::Create(func.getContext(), phiNode, mergeRetBlock);
  }

  // Update each original return block: replace return with branch, feed value into PHI if needed
  for (BasicBlock *bb : returnBlocks) {
    Instruction *retTerm = &bb->back();
    Value *returnedVal = retTerm->getNumOperands() > 0 ? retTerm->getOperand(0) : nullptr;

    if (phiNode && returnedVal)
      phiNode->addIncoming(returnedVal, bb);

    retTerm->eraseFromParent();
    BranchInst::Create(mergeRetBlock, bb);
  }

  return true;
}

} // namespace

PreservedAnalyses UnifyFunctionExitNodesPass::run(Function &F,
                                                  FunctionAnalysisManager &) {
  bool modified = false;
  modified |= consolidateUnreachableTargets(F);
  modified |= consolidateReturnPoints(F);
  return modified ? PreservedAnalyses() : PreservedAnalyses::all();
}

