    // Helper function to compute greatest common divisor using Euclidean algorithm
    static unsigned computeGCD(unsigned a, unsigned b) {
        while (b != 0) {
            unsigned temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    // Count the number of Pythagorean triples with hypotenuse <= n
    static int countTriples(int n) {
        int count = 0;

        // Iterate through all possible hypotenuse values
        for (int c = 5; c <= n; c++) {
            // Check all possible leg pairs (a, b) where a < b < c
            for (int a = 1; a * a <= c * c / 2; a++) {
                int b_squared = c * c - a * a;
                int b = static_cast<int>(std::sqrt(b_squared));

                // Verify it's a perfect square and forms a valid triple
                if (b * b == b_squared && b > a && b < c) {
                    // Count both (a,b,c) and (b,a,c) as distinct
                    count += 2;
                }
            }
        }

        return count;
    }
};

#include <asio.hpp>
#include <boost/bind.hpp>
#include <fstream>
#include <iostream>
#include <string>

using asio::dispatch;
using asio::post;
using asio::spawn;
using asio::strand;
using asio::thread_pool;
using asio::yield_context;

// Helper function to print a matched line with filename prefix
void output_result(const std::string& filename, const std::string& content)
{
  std::cout << filename << ':' << content << std::endl;
}

// Coroutine that searches for a pattern in a file and reports matches via strand
void scan_file(const std::string& pattern, const std::string& filepath,
    strand<thread_pool::executor_type> out_strand, yield_context yield)
{
  std::ifstream ifs(filepath);
  if (!ifs.is_open()) return;

  std::string buffer;
  std::size_t counter = 0;

  while (std::getline(ifs, buffer))
  {
    // Check if the current line contains the search term
    if (buffer.find(pattern) != std::string::npos)
    {
      dispatch(out_strand, boost::bind(&output_result, filepath, buffer));
    }

    // Yield periodically to allow other coroutines to run
    if (++counter % 10 == 0)
    {
      post(yield);
    }
  }
}

int main(int argc, char* argv[])
{
  try
  {
    if (argc < 2)
    {
      std::cerr << "Usage: parallel_grep <pattern> <file1> [file2] ...\n";
      return 1;
    }

    // Create a thread pool for concurrent execution
    thread_pool executor_pool;

    // Strand ensures serialized output to avoid interleaving
    auto output_guard = strand{executor_pool.get_executor()};

    // Extract search pattern from first argument
    std::string keyword = argv[1];

    // Launch one coroutine per input file
    for (int idx = 2; idx < argc; ++idx)
    {
      std::string target_file = argv[idx];
      spawn(executor_pool,
          boost::bind(&scan_file, keyword, target_file, output_guard, _1));
    }

    // Wait until all work is done
    executor_pool.join();
  }
  catch (const std::exception& ex)
  {
    std::cerr << "Error: " << ex.what() << '\n';
  }

  return 0;
}

#include <iostream>
#include <functional>
#include <string>

// Standalone function for printing
void display_value(int val) {
    std::cout << "free_function: " << val << '\n';
}

// Callable struct with overloaded operator()
struct CallableHandler {
    void operator()(int val) const {
        std::cout << "Functor: " << val << '\n';
    }
};

// Class encapsulating data and behavior
struct Item {
    void instance_method(int val) {
        std::cout << "Widget::member_function: " << val << '\n';
    }

    void readonly_method(int val) const {
        std::cout << "Widget::const_member_function: " << val << '\n';
    }

    int stored_value = 42;
};

void demonstrate_invoke_usage() {
    std::cout << "=== std::invoke Fundamentals ===\n";

    CallableHandler handler;
    Item obj;

    // Call free function via invoke
    std::invoke(display_value, 42);

    // Call functor object
    std::invoke(handler, 21);

    // Lambda invocation
    std::invoke([](int x) { std::cout << "Lambda: " << x << '\n'; }, 10);

    // Member function on lvalue reference
    std::invoke(&Item::instance_method, obj, 5);

    // Member function on pointer to object
    std::invoke(&Item::instance_method, &obj, 15);

    // Const member function call
    std::invoke(&Item::readonly_method, obj, 25);

    // Accessing member variable through invoke
    int retrieved = std::invoke(&Item::stored_value, obj);
    std::cout << "Item::stored_value = " << retrieved << '\n';
}

void contrast_call_methods() {
    std::cout << "\n=== Direct Calls vs std::invoke ===\n";

    Item item;

    std::cout << "Direct approach:\n";
    item.instance_method(1);
    (item.*&Item::instance_method)(2);
    (&item->*&Item::instance_method)(3);

    std::cout << "\nUniform invoke syntax:\n";
    std::invoke(&Item::instance_method, item, 1);
    std::invoke(&Item::instance_method, &item, 2);
}

void integrate_with_std_function() {
    std::cout << "\n=== Using std::invoke with std::function ===\n";

    std::function<void(int)> wrapper = [](int n) {
        std::cout << "std::function: " << n << '\n';
    };

    std::invoke(wrapper, 100);
}

void handle_reference_wrappers() {
    std::cout << "\n=== std::invoke with std::reference_wrapper ===\n";

    Item target;
    auto wrapped = std::ref(target);

    std::invoke(&Item::instance_method, wrapped, 7);
}

int main() {
    demonstrate_invoke_usage();
    contrast_call_methods();
    integrate_with_std_function();
    handle_reference_wrappers();

    std::cout << "\n=== Advantages Summary ===\n";
    std::cout << "- Unified calling interface across callable entities\n";
    std::cout << "- Eliminates need for .* / ->* operators\n";
    std::cout << "- Compatible with std::reference_wrapper\n";
    std::cout << "- Supports generic templates accepting any callable\n";

    return 0;
}

