using grpc::Channel;
using grpc::ClientContext;
using grpc::Status;
using test_service_package::IntRequest;
using test_service_package::IntReply;
using test_service_package::Decompositor;

class DecompositorProxy {
 public:
  explicit DecompositorProxy(std::shared_ptr<Channel> channel)
      : stub_(Decompositor::NewStub(channel)) {}

  // Initiates a decomposition request to the remote service
  std::string RequestDecomposition(const int& input_value) {
    IntRequest request;
    request.set_value(input_value);

    IntReply response;
    ClientContext context;

    Status result = stub_->Decompose(&context, request, &response);

    if (result.ok()) {
      return response.message();
    } else {
      std::cerr << "Error code: " << result.error_code() 
                << ", message: " << result.error_message() << std::endl;
      return "RPC invocation failed";
    }
  }

 private:
  std::unique_ptr<Decompositor::Stub> stub_;
};

int main(int argc, char** argv) {
  // Establish connection with the gRPC server using insecure credentials
  auto channel = grpc::CreateChannel(
      "localhost:50051", grpc::InsecureChannelCredentials());

  DecompositorProxy client(channel);

  int number_to_decompose = 42;
  std::string server_response = client.RequestDecomposition(number_to_decompose);

  std::cout << "Response from Decompositor service: " << server_response << std::endl;

  return 0;
}

