#include "IntBuffer.h"

// Allocates a new int buffer.
// The new buffer's position will be zero, its limit will be its capacity, and its mark will be undefined.
// It will have a backing array, and its array offset will be zero.
//
// Parameters:
//   capacity - The new buffer's capacity, in ints
IntBuffer::IntBuffer(unsigned int capacity) : Buffer(capacity)
{
	pos = 0;
	lim = static_cast<int>(capacity);
	hasBackingArray = false;
	buffer = new int[capacity];
	std::fill_n(buffer, capacity, 0); // Safe C++ alternative to memset
}

// Constructs an IntBuffer using an externally-provided backing array.
// The new buffer shares ownership of the given array; it does not own it.
//
// Parameters:
//   capacity    - The buffer's logical capacity (number of elements)
//   backingArray - Pointer to pre-allocated integer array
IntBuffer::IntBuffer(unsigned int capacity, int* backingArray) : Buffer(capacity)
{
	pos = 0;
	lim = static_cast<int>(capacity);
	hasBackingArray = true;
	buffer = backingArray;
}

IntBuffer::~IntBuffer()
{
	if (!hasBackingArray && buffer != nullptr) {
		delete[] buffer;
		buffer = nullptr;
	}
}

int* IntBuffer::getBuffer()
{
	return buffer;
}

// Flips this buffer: sets the limit to the current position, then resets position to zero.
// If the mark is defined, it is discarded.
//
// Returns:
//   This buffer (for chaining)
IntBuffer* IntBuffer::flip()
{
	lim = pos;
	pos = 0;
	return this;
}

// Absolute get method: reads the int at the specified index.
//
// Parameters:
//   index - Index from which to read; must be less than current limit
// Returns:
//   The value stored at the given index
int IntBuffer::get(unsigned int index)
{
	assert(index < static_cast<unsigned int>(lim));
	return buffer[index];
}

// Relative bulk put method (optional operation).
// Copies integers from the source array into this buffer.
//
// Precondition: 
//   offset + length must be within bounds of inputArray->data
//
// Postcondition:
//   Position is incremented by 'length'
//
// Parameters:
//   inputArray - Source array containing data to copy
//   offset     - Starting index in inputArray to copy from
//   length     - Number of elements to copy
// Returns:
//   This buffer (for chaining)
IntBuffer* IntBuffer::put(intArray* inputArray, unsigned int offset, unsigned int length)
{
	assert(offset + length <= inputArray->length); // Adjusted for correctness: <= instead of <

	for (unsigned int i = 0; i < length; ++i) {
		buffer[pos + i] = inputArray->data[offset + i];
	}
	pos += static_cast<int>(length);
	return this;
}

// Bulk put method that copies entire inputArray into this buffer.
//
// Precondition:
//   inputArray.length must fit in remaining space of this buffer
//
// Parameters:
//   inputArray - Array whose contents are to be copied
// Returns:
//   This buffer (for chaining)
IntBuffer* IntBuffer::put(intArray inputArray)
{
	if (inputArray.length > remaining()) {
		assert(false); // TODO 4J Stu - Some kind of exception?
		return this;
	}

	for (unsigned int i = 0; i < inputArray.length; ++i) {
		buffer[pos + i] = inputArray.data[i];
	}
	pos += static_cast<int>(inputArray.length);
	return this;
}

// Writes a single integer into this buffer at the current position,
// then advances the position by one.
//
// Parameters:
//   i - Integer value to store
// Returns:
//   This buffer (for chaining)
IntBuffer* IntBuffer::put(int i)
{
	assert(pos < lim);
	buffer[pos++] = i;
	return this;
}

