namespace ap::plat {

void init() noexcept {
    // Initialize COM subsystem
    plat::ComInit::init();

    // Configure console for VT-100 escape sequence support
    HANDLE consoleHandle = ::GetStdHandle(STD_OUTPUT_HANDLE);
    DWORD consoleMode;
    ::GetConsoleMode(consoleHandle, &consoleMode);

    // Attempt to enable virtual terminal processing; fall back if it fails
    if (!::SetConsoleMode(consoleHandle, consoleMode | ENABLE_VIRTUAL_TERMINAL_PROCESSING))
        log::options().disableAllColors = true;

    // Set output code page to UTF-8 for proper Unicode rendering
    ::SetConsoleOutputCP(65001);

    // Request backup privileges for the current process
    ASSERTD_MSG(!addRights(),
                "Failed to acquire backup privileges for the process");

    // Register console control handler for graceful shutdown
    ::SetConsoleCtrlHandler(plat::consoleEventHandler, TRUE);

    // Override default COM error handling to use logging instead of exceptions
    ::_set_com_error_handler([](HRESULT hr, IErrorInfo *) noexcept {
        if (log::isLevelEnabled<false>(Lvl::Error))
            APERR(hr, "Global COM error");
    });

    // Initialize Winsock library for network operations
    WSADATA wsaData = {};
    if (int socketInitResult = ::WSAStartup(MAKEWORD(2, 2), &wsaData))
        ASSERTD_MSG(false, "Failed to initialize socket manager", socketInitResult);
}

void deinit() noexcept {
    // Clean up Winsock resources
    ::WSACleanup();
}

