#include "planner/operator/logical_plan_util.h"
#include "binder/expression/property_expression.h"
#include "planner/operator/extend/logical_extend.h"
#include "planner/operator/logical_hash_join.h"
#include "planner/operator/logical_intersect.h"
#include "planner/operator/scan/logical_scan_node_table.h"

using namespace lbug::binder;

namespace lbug {
namespace planner {

std::string LogicalPlanUtil::encodeJoin(LogicalPlan& plan) {
    return encode(plan.getFinalOperator().get());
}

std::string LogicalPlanUtil::encode(LogicalOperator* op) {
    std::string buffer;
    traverseAndEncode(op, buffer);
    return buffer;
}

void LogicalPlanUtil::traverseAndEncode(LogicalOperator* node, std::string& out) {
    switch (node->getType()) {
    case LogicalOperatorType::CROSS_PRODUCT: {
        appendCrossProduct(out);
        for (size_t idx = 0; idx < node->getNumChildren(); ++idx) {
            out += "[";
            traverseAndEncode(node->getChild(idx).get(), out);
            out += "]";
        }
    } break;

    case LogicalOperatorType::INTERSECT: {
        appendIntersect(node, out);
        for (size_t idx = 0; idx < node->getNumChildren(); ++idx) {
            out += "[";
            traverseAndEncode(node->getChild(idx).get(), out);
            out += "]";
        }
    } break;

    case LogicalOperatorType::HASH_JOIN: {
        appendHashJoin(node, out);
        out += "[";
        traverseAndEncode(node->getChild(0).get(), out);
        out += "][";
        traverseAndEncode(node->getChild(1).get(), out);
        out += "]";
    } break;

    case LogicalOperatorType::EXTEND: {
        appendExtend(node, out);
        traverseAndEncode(node->getChild(0).get(), out);
    } break;

    case LogicalOperatorType::SCAN_NODE_TABLE: {
        appendScanNodeTable(node, out);
    } break;

    case LogicalOperatorType::FILTER: {
        appendFilter(out);
        traverseAndEncode(node->getChild(0).get(), out);
    } break;

    default:
        // Fallback: recursively process all children if type not explicitly handled
        for (size_t i = 0; i < node->getNumChildren(); ++i) {
            traverseAndEncode(node->getChild(i).get(), out);
        }
    }
}

void LogicalPlanUtil::appendCrossProduct(std::string& output) {
    output += "CP()";
}

void LogicalPlanUtil::appendIntersect(LogicalOperator* op, std::string& output) {
    auto& intersectOp = op->constCast<LogicalIntersect>();
    output += "I(" + intersectOp.getSharedNodeVariable()->toString() + ")";
}

void LogicalPlanUtil::appendHashJoin(LogicalOperator* op, std::string& output) {
    auto& joinOp = op->constCast<LogicalHashJoin>();
    output += "HJ(" + joinOp.getJoinKeyStrings() + ")";
}

void LogicalPlanUtil::appendExtend(LogicalOperator* op, std::string& output) {
    auto& extendOp = op->constCast<LogicalExtend>();
    output += "E(" + extendOp.getTargetNode()->toString() + ")";
}

void LogicalPlanUtil::appendScanNodeTable(LogicalOperator* op, std::string& output) {
    auto& scanOp = op->constCast<LogicalScanNodeTable>();
    if (scanOp.getMethod() == LogicalScanNodeTableType::PRIMARY_KEY_SCAN) {
        output += "IdxScan";
    } else {
        output += "SeqScan";
    }
    output += "(" + scanOp.getIdVar()->constCast<PropertyExpression>().getName() + ")";
}

void LogicalPlanUtil::appendFilter(std::string& out) {
    out += "Filter()";
}

