#include "quadrants/ir/ir.h"
#include "quadrants/ir/statements.h"
#include "quadrants/ir/transforms.h"
#include "quadrants/ir/visitors.h"
#include "quadrants/system/profiler.h"

namespace quadrants::lang {

// A visitor that substitutes every occurrence of 'target' with 'replacement'
// across IR nodes, excluding frontend loop constructs (e.g., FrontendForStmt)
class OperandSubstitutor : public IRVisitor {
 public:
  Stmt* target;
  Stmt* replacement;

  OperandSubstitutor(Stmt* t, Stmt* r)
      : target(t), replacement(r) {
    allow_undefined_visitor = true;
    invoke_default_visitor = true;
  }

 private:
  // Helper to safely replace operands only if they match exactly
  void try_replace_operand(Stmt* stmt) {
    if (stmt != nullptr) {
      stmt->replace_operand_with(target, replacement);
    }
  }

  void visit(Stmt* stmt) override {
    try_replace_operand(stmt);
  }

  void visit(WhileStmt* w_stmt) override {
    try_replace_operand(w_stmt);
    w_stmt->body->accept(this);
  }

  void visit(IfStmt* i_stmt) override {
    try_replace_operand(i_stmt);
    if (i_stmt->true_statements) {
      i_stmt->true_statements->accept(this);
    }
    if (i_stmt->false_statements) {
      i_stmt->false_statements->accept(this);
    }
  }

  void visit(Block* blk) override {
    for (auto& s : blk->statements) {
      s->accept(this);
    }
  }

  void visit(RangeForStmt* r_stmt) override {
    try_replace_operand(r_stmt);
    r_stmt->body->accept(this);
  }

  void visit(StructForStmt* s_stmt) override {
    s_stmt->body->accept(this);
  }

  void visit(MeshForStmt* m_stmt) override {
    m_stmt->body->accept(this);
  }

  void visit(OffloadedStmt* o_stmt) override {
    o_stmt->all_blocks_accept(this);
  }

  // Entry point: perform substitution starting from root or parent chain
  static void apply(IRNode* root, Stmt* old_stmt, Stmt* new_stmt) {
    OperandSubstitutor subs(old_stmt, new_stmt);

    if (root != nullptr) {
      root->accept(&subs);
      return;
    }

    QD_ASSERT(old_stmt->parent != nullptr);

    // First, substitute within the immediate parent block
    old_stmt->parent->accept(&subs);

    // Then walk upward through enclosing blocks
    Block* curr = old_stmt->parent->parent_block();
    while (curr != nullptr) {
      for (auto& stmt : curr->statements) {
        stmt->replace_operand_with(old_stmt, new_stmt);
      }
      curr = curr->parent_block();
    }
  }
};

namespace irpass {

void replace_all_usages_with(IRNode* root, Stmt* old_stmt, Stmt* new_stmt) {
  QD_AUTO_PROF;
  OperandSubstitutor::apply(root, old_stmt, new_stmt);
}

}  // namespace irpass
}  // namespace quadrants::lang

