// Entry point for the mini-game pause overlay UI
void uiMgPauseEnter()
{
  // Activate pause mode and set initial selection to "Continue"
  mgPauseSetPaused(true);
  mgPauseSetChoice(0);
  requestFullUIRedraw();
}

// Process input while in the mini-game pause screen
void uiMgPauseHandle(InputState& input)
{
  // Temporarily block menu activation (e.g., ESC) to prevent Settings popup during pause
  uiSuppressMenuForMs(150);

  // If we're unexpectedly not paused:
  // - Resume back to MINI_GAME only if a valid mini-game is active.
  // - Avoid bouncing through MINI_GAME unnecessarily to prevent "NO MINI GAME" flicker.
  if (!mgPauseIsPaused())
  {
    if (g_app.inMiniGame && currentMiniGame != MiniGame::NONE)
    {
      uiActionEnterStateClean(UIState::MINI_GAME, g_app.currentTab, false, input, 150);
      requestFullUIRedraw();
    }
    return;
  }

  const uint8_t prevSelection = mgPauseChoice();

  // Let the pause menu system process input and update internal state
  const uint8_t actionResult = mgPauseHandle(input);

  // Redraw only the UI layer if selection changed (not full redraw needed)
  if (mgPauseChoice() != prevSelection)
  {
    requestUIRedraw();
  }

  // Handle explicit "Exit" selection — already handled internally by mgPauseHandle(),
  // so no further transition logic required here.
  if (actionResult == MGPAUSE_EXIT)
  {
    requestFullUIRedraw();
    return;
  }

  // Otherwise, remain in MG_PAUSE until unpaused or exited.
  // When "Continue" is selected, mgPauseIsPaused() will flip to false,
  // causing the next tick to fall into the early-exit path above and resume MINI_GAME.
}

