    return outcome;
}

// Helper function to request the current distance to the target
int get_distance() {
    std::cout << "query" << std::endl;
    int distance;
    std::cin >> distance;
    return distance;
}

int main() {
    // Optimize I/O for competitive programming scenarios
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int starting_depth;
    std::cin >> starting_depth;
    int remaining_distance = starting_depth;

    // If already at the destination, terminate immediately
    if (remaining_distance == 0) {
        return 0;
    }

    int upward_color = -1;

    // --- Initial exploration phase ---
    // With no prior knowledge, test colors 0 and 1 to find an upward path
    for (int attempt_color = 0; attempt_color < 2; ++attempt_color) {
        if (execute_move(attempt_color) == 1) {
            return 0; // Reached goal during move
        }

        int new_dist = get_distance();
        if (new_dist < remaining_distance) {
            upward_color = attempt_color;
            break;
        }

        // Return to original position if this direction didn't help
        execute_move(attempt_color);
    }

    // If neither 0 nor 1 worked, then 2 must be the upward direction
    if (upward_color == -1) {
        upward_color = 2;
        if (execute_move(upward_color) == 1) {
            return 0;
        }
    }

    remaining_distance--;
    int last_used_color = upward_color;

    // --- Main navigation loop ---
    // Now we know the incoming direction, so only need to test the other two
    while (remaining_distance > 0) {
        // Calculate alternative directions using modular arithmetic
        int alt1 = (last_used_color + 1) % 3;
        int alt2 = (last_used_color + 2) % 3;

        // Try first alternative
        if (execute_move(alt1) == 1) {
            return 0;
        }

        int updated_dist = get_distance();
        if (updated_dist < remaining_distance) {
            upward_color = alt1;
        } else {
            // First alternative was downward, so backtrack
            execute_move(alt1);

            // Second alternative must be upward
            upward_color = alt2;
            if (execute_move(upward_color) == 1) {
                return 0;
            }
        }

        remaining_distance--;
        last_used_color = upward_color;
    }

    return 0;
}

