    selection_action_t::selection_action_t(editing_manager* mgr,
                                           const std::vector<entt::meta_any>& prev_sel,
                                           const std::vector<entt::meta_any>& curr_sel, bool selecting)
        : manager(mgr), old_selection(prev_sel), new_selection(curr_sel), is_select(selecting)
    {
        action_name = selecting ? "Select" : "Unselect";
        can_undo = true;
    }

    void selection_action_t::execute()
    {
        if (!manager)
            return;

        // Apply the current (target) selection state via internal handler
        manager->apply_selection_impl(new_selection);
    }

    void selection_action_t::revert()
    {
        if (!manager)
            return;

        // Revert to the prior selection state via internal handler
        manager->apply_selection_impl(old_selection);
    }

    auto selection_action_t::can_be_merged(const editing_action_t& former) const -> bool
    {
        const auto& other_sel_action = static_cast<const selection_action_t&>(former);

        // Merge only if both actions have the same operation type (both select or both unselect)
        if (other_sel_action.is_select != is_select)
            return false;

        // Handle trivial cases: both empty selections → mergeable
        if (old_selection.empty() && other_sel_action.new_selection.empty())
            return true;

        // Size mismatch implies non-mergeability
        if (old_selection.size() != other_sel_action.new_selection.size())
            return false;

        // Verify set equality (order-insensitive) between old_selection and former's new_selection
        for (const auto& item : old_selection)
        {
            bool match_found = false;
            for (const auto& prior_item : other_sel_action.new_selection)
            {
                if (item == prior_item)
                {
                    match_found = true;
                    break;
                }
            }
            if (!match_found)
                return false;
        }

        return true;
    }

    void selection_action_t::combine_with(const editing_action_t& former)
    {
        const auto& other_sel_action = static_cast<const selection_action_t&>(former);

        // Preserve the earliest selection state from former action
        old_selection = other_sel_action.old_selection;
        // Retain the latest selection state in new_selection (unchanged)
    }

    auto selection_action_t::is_operational() const -> bool
    {
        return manager != nullptr;
    }
