// Helper function to query the range [l, r] and return the result
int query_range(int left, int right) {
    std::cout << "? " << left << " " << right << std::endl;
    int response;
    std::cin >> response;
    return response;
}

// Function to output the final answer
void report_answer(int position) {
    std::cout << "! " << position << std::endl;
}

// Core logic for solving one test case
void process_case() {
    int array_size;
    std::cin >> array_size;

    // First, locate the index of the second largest element (value n-1)
    int second_max_pos = query_range(1, array_size);

    bool max_element_left = false;

    // Check if the maximum element (n) is to the left of second_max_pos
    if (second_max_pos > 1) {
        int candidate_pos = query_range(1, second_max_pos);
        if (candidate_pos == second_max_pos) {
            // If the second max in [1, second_max_pos] is still at second_max_pos,
            // then the maximum must be somewhere before it
            max_element_left = true;
        }
    }

    if (max_element_left) {
        // Search for maximum in [1, second_max_pos - 1]
        int low = 1;
        int high = second_max_pos - 1;

        while (low < high) {
            int mid = low + (high - low) / 2;
            int res = query_range(mid + 1, second_max_pos);

            if (res == second_max_pos) {
                // The maximum lies in the right subarray
                low = mid + 1;
            } else {
                // The maximum lies in the left subarray
                high = mid;
            }
        }
        report_answer(low);
    } else {
        // Search for maximum in [second_max_pos + 1, array_size]
        int low = second_max_pos + 1;
        int high = array_size;

        while (low < high) {
            int mid = low + (high - low + 1) / 2;
            int res = query_range(second_max_pos, mid - 1);

            if (res == second_max_pos) {
                // The maximum lies in the left subarray
                high = mid - 1;
            } else {
                // The maximum lies in the right subarray
                low = mid;
            }
        }
        report_answer(low);
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    while (test_cases-- > 0) {
        process_case();
    }

    return 0;
}

