using namespace std;

class Solution {
public:
    bool isOneBitCharacter(vector<int>& bits) {
        int size = bits.size();
        int index = 0;

        // Traverse until the second-to-last element
        while (index < size - 1) {
            if (bits[index] == 1) {
                // If current bit is 1, skip next bit (2-bit character)
                index += 2;
            } else {
                // If current bit is 0, it's a 1-bit character
                index++;
            }
        }

        // Check if we ended exactly at the last position
        return index == size - 1;
    }
};

