namespace rslcpp::dynamic_composition
{

std::vector<rclcpp::Node::SharedPtr> ComponentLoader::load_and_create_nodes(
  const std::vector<ComponentDescription>& components,
  rclcpp::NodeOptions const& options)
{
  std::vector<rclcpp::Node::SharedPtr> nodes;
  nodes.reserve(components.size());

  std::transform(components.begin(), components.end(),
                 std::back_inserter(nodes),
                 [this, &options](ComponentDescription const& comp) {
                   return load_component(comp, options);
                 });

  return nodes;
}

std::shared_ptr<rclcpp::Node> ComponentLoader::load_component(
  ComponentDescription const& component,
  rclcpp::NodeOptions const& options)
{
  std::cout << ">> Loading Component | " << component.component_name << std::endl;

  const auto lib_path = utils::get_shared_library_path(component);

  // Use find_if to check if loader exists; insert if not
  auto it = std::find_if(loaders.begin(), loaders.end(),
                         [&lib_path](auto const& pair) { return pair.first == lib_path; });
  if (it == loaders.end()) {
    loaders.emplace(lib_path, std::make_unique<class_loader::ClassLoader>(lib_path));
  }

  const std::string factory_class =
    "rclcpp_components::NodeFactoryTemplate<" + component.component_name + ">";

  auto& loader_instance = *loaders[lib_path];
  auto node_factory = loader_instance.createInstance<rclcpp_components::NodeFactory>(factory_class);

  // Override node options with component-specific arguments
  rclcpp::NodeOptions modified_opts = options;
  if (!component.component_arguments.empty()) {
    modified_opts.arguments(component.component_arguments);
  }

  auto wrapper = node_factory->create_node_instance(modified_opts);
  auto node_ptr = std::static_pointer_cast<rclcpp::Node>(wrapper.get_node_instance());
  node_wrappers.push_back(std::move(wrapper));

  return node_ptr;
}

std::vector<ComponentDescription> parse_components_from_command_line_arguments(
  int& argc, char**& argv)
{
  std::vector<ComponentDescription> parsed_components;

  // Skip leading non-component arguments until we hit "--ros-args" or end
  int skip_count = 0;
  for (; skip_count < argc && std::string(argv[skip_count]) != "--ros-args"; ++skip_count) {
    if (std::string(argv[skip_count]) == "--component") {
      break;
    }
  }

  // If no "--component" found, return empty list
  if (skip_count >= argc || std::string(argv[skip_count]) != "--component") {
    return parsed_components;
  }

  // Process each --component block
  int idx = skip_count;
  while (idx < argc && std::string(argv[idx]) != "--ros-args") {
    if (std::string(argv[idx]) != "--component") {
      throw std::runtime_error("DynamicComposition | Unexpected argument before '--component'");
    }

    // Expect at least two args after --component: package and class name
    if (idx + 2 >= argc) {
      throw std::runtime_error(
        "DynamicComposition | '--component' specified without package and class arguments.");
    }

    const std::string pkg_name = argv[idx + 1];
    const std::string cls_name = argv[idx + 2];

    // Parse optional ROS args section
    std::vector<std::string> comp_args;
    int next_idx = idx + 3;

    if (next_idx < argc && std::string(argv[next_idx]) == "--component-ros-args") {
      comp_args.push_back("--ros-args");
      ++next_idx;
    } else if (next_idx < argc) {
      throw std::runtime_error(
        "DynamicComposition | If you want to add arguments per component, use "
        "'--component-ros-args' after the component name");
    }

    // Collect remaining component args
    while (next_idx < argc && std::string(argv[next_idx]) != "--ros-args" &&
           std::string(argv[next_idx]) != "--component") {
      comp_args.push_back(argv[next_idx]);
      ++next_idx;
    }

    parsed_components.emplace_back(pkg_name, cls_name, comp_args);
    idx = next_idx;
  }

  // Adjust argc/argv to reflect unparsed portion
  argc -= idx;
  argv += idx;

  if (argc <= 0) {
    argc = 0;
    argv = nullptr;
  }

  return parsed_components;
}

}  // namespace rslcpp::dynamic_composition

