MatchForwardOrderSafe::token MatchForwardOrderSafe::choose(const bool b) {
  // Return token A if condition is true, otherwise token B
  return b ? token::A : token::B;
}

unsigned int
MatchForwardOrderSafe::encode(const MatchForwardOrderSafe::token x) {
  // Lambda function to handle encoding via switch-case
  auto encode_impl = [&]() -> unsigned int {
    switch (x) {
      case token::A:
        // Encode A as 1 (0 + 1)
        return 1;
      case token::B:
        // Encode B as 0
        return 0;
      default:
        // Defensive programming: should not reach here
        throw std::runtime_error("Invalid token value in encode()");
    }
  };

  return encode_impl();
}

