#include <iostream>
#include <vector>
#include <string>
#include <set>
#include <algorithm>

// Alternative implementation using different approach to word discovery
void processTestCase() {
    int totalNeeded;
    std::cin >> totalNeeded;

    std::set<std::string> discoveredWords;

    // Process each character from 'a' to 'z'
    for (char currentChar = 'a'; currentChar <= 'z'; ++currentChar) {
        if (discoveredWords.size() >= static_cast<size_t>(totalNeeded)) {
            break;
        }

        std::string basePrefix(1, currentChar);
        int requestSize = 1;

        // Continue until we have enough words or exhaust this prefix
        while (true) {
            if (discoveredWords.size() >= static_cast<size_t>(totalNeeded)) {
                break;
            }

            std::cout << "query " << basePrefix << " " << requestSize << std::endl;

            int actualCount;
            std::cin >> actualCount;

            // Collect the returned words
            for (int idx = 0; idx < actualCount; ++idx) {
                std::string nextWord;
                std::cin >> nextWord;
                discoveredWords.insert(nextWord);
            }

            // If we got fewer words than requested, no more exist for this prefix
            if (actualCount < requestSize) {
                break;
            }

            // If we've reached the total needed, stop processing
            if (requestSize == totalNeeded) {
                break;
            }

            // Increase our request size for next iteration
            requestSize *= 2;
            if (requestSize > totalNeeded) {
                requestSize = totalNeeded;
            }
        }
    }

    // Output the collected words
    std::cout << "answer";
    for (const std::string& word : discoveredWords) {
        std::cout << " " << word;
    }
    std::cout << std::endl;
}

int main() {
    // Optimize I/O operations
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int testCaseCount;
    std::cin >> testCaseCount;

    while (testCaseCount-- > 0) {
        processTestCase();
    }

    return 0;
}

