// Helper function to benchmark map swapping performance
template <typename MapType>
void measure_swap_performance(std::string_view map_name) {
    MapType first_map;
    MapType second_map;

    // Initialize random number generator with fixed seed for reproducibility
    ankerl::nanobench::Rng rng(456);

    // Setup phase: populate both maps with entries
    for (size_t iteration = 0; iteration < 10000; ++iteration) {
        first_map[rng()] = 0;
        second_map[rng()] = 0;
    }

    // Run benchmark using nanobench
    ankerl::nanobench::Bench benchmark;
    benchmark.run(fmt::format("swap {}", map_name), [&] {
        std::swap(first_map, second_map);
    });

    // Prevent compiler optimizations from eliminating the maps
    ankerl::nanobench::doNotOptimizeAway(&first_map);
    ankerl::nanobench::doNotOptimizeAway(&second_map);
}

} // anonymous namespace

