namespace xllm {

// Test basic rate limiting functionality with a single concurrent request limit
TEST(RequestLimiterTest, BasicFunctionality) {
  // Configure the system to allow at most one simultaneous request
  FLAGS_max_concurrent_requests = 1;
  RateLimiter limiter;

  // Initially, no active requests exist, so no throttling should occur
  EXPECT_FALSE(limiter.is_limited());

  // Simulate an incoming request being processed (increment internal counter)
  limiter.increase_one_request();

  // Now that one request is active and the limit is 1, further requests should be throttled
  EXPECT_TRUE(limiter.is_limited());

  // Simulate completion of the current request (decrement internal counter)
  limiter.decrease_one_request();

  // With zero active requests again, no throttling should apply
  EXPECT_FALSE(limiter.is_limited());
}

