static void printExtensionInfo(const char* ext_name, GLboolean status1, GLboolean status2, GLboolean status3)
{
    size_t len = strlen(ext_name);
    fprintf(output_file, "\n%s:", ext_name);

    for (size_t j = 0; j < 62 - len; ++j)
        fprintf(output_file, " ");

    fprintf(output_file, "%s ", (status1 ? "OK" : "MISSING"));

    if (status1 != status2)
        fprintf(output_file, "[%s] ", (status2 ? "OK" : "MISSING"));

    if (status1 != status3)
        fprintf(output_file, "[%s]\n", (status3 ? "OK" : "MISSING"));
    else
        fprintf(output_file, "\n");

    for (size_t k = 0; k < len + 1; ++k)
        fprintf(output_file, "-");
    fprintf(output_file, "\n");

    fflush(output_file);
}

static void logFunctionStatus(const char* func_name, GLint is_missing)
{
    size_t name_len = strlen(func_name);
    fprintf(output_file, "  %s:", func_name);

    for (size_t pad = 0; pad < 60 - name_len; ++pad)
        fprintf(output_file, " ");

    fprintf(output_file, "%s\n", (is_missing ? "MISSING" : "OK"));
    fflush(output_file);
}

