class PathUndoRedoerTest : public PlainTestSuite {
  Q_OBJECT
 public:
 private slots:
  void test_undo_only() {
    PathUndoRedoer pUR;

    // Initial state checks
    QVERIFY(!pUR.undoPathAvailable());
    QCOMPARE(pUR.undoStack.size(), 0);

    // Push first item
    pUR("1");
    QCOMPARE(pUR.undoPathAvailable(), false); // Still no undo available yet
    QCOMPARE(pUR.undoStack.size(), 1);
    QCOMPARE(pUR.undoStack.top(), "1");

    // Push second item
    pUR("2");
    QCOMPARE(pUR.undoPathAvailable(), true);
    QCOMPARE(pUR.undoStack.size(), 2);
    QCOMPARE(pUR.undoStack.top(), "2");

    // Check redo state before any redo operation
    QVERIFY(!pUR.redoPathAvailable());
    QVERIFY(pUR.redoStack.isEmpty());

    // Attempt redo when none available - should return empty string
    QCOMPARE(pUR.onRedoPath(), QString(""));
    QCOMPARE(pUR.undoPathAvailable(), true);
    QCOMPARE(pUR.undoStack.size(), 2);
    QCOMPARE(pUR.undoStack.top(), "2");
    QVERIFY(!pUR.redoPathAvailable());
    QVERIFY(pUR.redoStack.isEmpty());

    // Perform undo
    QCOMPARE(pUR.onUndoPath(), "1");
    QVERIFY(!pUR.undoPathAvailable());
    QCOMPARE(pUR.undoStack.size(), 1);
    QCOMPARE(pUR.undoStack.top(), "1");
    QCOMPARE(pUR.redoPathAvailable(), true);
    QCOMPARE(pUR.redoStack.size(), 1);
    QCOMPARE(pUR.redoStack.top(), "2");

    // Perform redo
    pUR.onRedoPath();
    QCOMPARE(pUR.undoPathAvailable(), true);
    QCOMPARE(pUR.undoStack.size(), 2);
    QCOMPARE(pUR.undoStack.top(), "2");
    QVERIFY(!pUR.redoPathAvailable());
    QVERIFY(pUR.redoStack.isEmpty());

    // Add more items
    pUR("3");
    QCOMPARE(pUR.undoPathAvailable(), true);
    QCOMPARE(pUR.undoStack.size(), 3);
    QCOMPARE(pUR.undoStack.top(), "3");
    QVERIFY(!pUR.redoPathAvailable());
    QVERIFY(pUR.redoStack.isEmpty());

    pUR("4");
    QCOMPARE(pUR.undoPathAvailable(), true);
    QCOMPARE(pUR.undoStack.size(), 4);
    QCOMPARE(pUR.undoStack.top(), "4");
    QVERIFY(!pUR.redoPathAvailable());
    QVERIFY(pUR.redoStack.isEmpty());

    // Multiple undos
    QCOMPARE(pUR.onUndoPath(), "3");
    QCOMPARE(pUR.undoPathAvailable(), true);
    QCOMPARE(pUR.undoStack.size(), 3);
    QCOMPARE(pUR.undoStack.top(), "3");
    QCOMPARE(pUR.redoPathAvailable(), true);
    QCOMPARE(pUR.redoStack.size(), 1);
    QCOMPARE(pUR.redoStack.top(), "4");

    QCOMPARE(pUR.onUndoPath(), "2");
    QCOMPARE(pUR.undoPathAvailable(), true);
    QCOMPARE(pUR.undoStack.size(), 2);
    QCOMPARE(pUR.undoStack.top(), "2");
    QCOMPARE(pUR.redoPathAvailable(), true);
    QCOMPARE(pUR.redoStack.size(), 2);
    QCOMPARE(pUR.redoStack.top(), "3");

    QCOMPARE(pUR.onUndoPath(), "1");
    QVERIFY(!pUR.undoPathAvailable());
    QCOMPARE(pUR.undoStack.size(), 1);
    QCOMPARE(pUR.undoStack.top(), "1");
    QCOMPARE(pUR.redoPathAvailable(), true);
    QCOMPARE(pUR.redoStack.size(), 3);
    QCOMPARE(pUR.redoStack.top(), "2");

    // Final undo attempt when none available
    QCOMPARE(pUR.onUndoPath(), QString(""));
    QVERIFY(!pUR.undoPathAvailable());
    QCOMPARE(pUR.undoStack.size(), 1);
