// Constructs an InputStreamReader using the default character encoding.
// Parameters:
//   in - Pointer to an InputStream object
InputStreamReader::InputStreamReader(InputStream *in) : stream( new DataInputStream( in ) )
{
}

// Releases resources and closes the underlying input stream.
// After closing, any further operations (read, ready, mark, reset, skip) will result in an exception.
// Attempting to close an already closed stream is safe and has no effect.
void InputStreamReader::close()
{
    stream->close();
}

// Reads a single UTF character from the stream.
// Returns:
//   The character value as int, or -1 if end-of-stream is reached
int InputStreamReader::read()
{
    return stream->readUTFChar();
}

// Reads multiple characters into a provided buffer.
// Parameters:
//   cbuf     - Target wide character array
//   offset   - Starting index in the buffer for writing
//   length   - Maximum number of characters to read
// Returns:
//   Number of characters successfully read, or -1 on EOF
int InputStreamReader::read(wchar_t cbuf[], unsigned int offset, unsigned int length)
{
    unsigned int count = 0;
    unsigned int index = offset;

    while (count < length && index < offset + length)
    {
        int rawValue = stream->readUTFChar();
        if (rawValue != -1)
        {
            cbuf[index] = static_cast<wchar_t>(rawValue);
            count++;
        }
        else
        {
            break; // End of stream reached
        }
        index++;
    }

    return (count > 0 || length == 0) ? static_cast<int>(count) : -1;
}

