// Helper: write text content to disk (plain text mode)
void persist_text(const std::string& path, const std::string& data)
{
    std::ofstream out(path);
    if(out.is_open() && out.good())
    {
        out << data;
    }
}

// Helper: read text content from disk
std::string retrieve_text(const std::string& path)
{
    std::ifstream in(path);
    return in.is_open() ? fs::read_stream_str(in) : std::string{};
}

// Save ui_tree as plain text file
void save_to_file(const std::string& absolute_path, const ui_tree::sptr& target)
{
    if(target && !absolute_path.empty())
    {
        persist_text(absolute_path, target->content);
    }
}

// Save ui_tree using binary serialization via ser20
void save_to_file_bin(const std::string& absolute_path, const ui_tree::sptr& target)
{
    if(!target || absolute_path.empty()) return;

    std::ofstream out(absolute_path, std::ios::binary);
    if(!out.is_open() || !out.good()) return;

    ser20::oarchive_binary_t ar(out);
    try_save(ar, ser20::make_nvp("ui_tree", *target));
}

// Load ui_tree from plain text file
void load_from_file(const std::string& absolute_path, ui_tree::sptr& target)
{
    if(!target || absolute_path.empty()) return;

    target->content = retrieve_text(absolute_path);
}

// Load ui_tree from binary serialized file
void load_from_file_bin(const std::string& absolute_path, ui_tree::sptr& target)
{
    if(!target || absolute_path.empty()) return;

    std::ifstream in(absolute_path, std::ios::binary);
    if(!in.is_open() || !in.good()) return;

    ser20::iarchive_binary_t ar(in);
    try_load(ar, ser20::make_nvp("ui_tree", *target));
}
