int main() {
    // Initialize two identical vectors with the same elements
    vector<int> vecA = {5, 2, 8, 1, 4};
    vector<int> vecB = {5, 2, 8, 1, 4};

    // Sort vecA in ascending order
    sort(vecA.begin(), vecA.end());

    cout << "Sorted vector in ascending order: ";
    for (int element : vecA) {
        cout << element << " ";
    }
    cout << endl;

    // Sort vecB in descending order using greater comparator
    sort(vecB.begin(), vecB.end(), greater<int>());

    cout << "Sorted vector in descending order: ";
    for (int element : vecB) {
        cout << element << " ";
    }
    cout << endl;

    // Initialize an array with the same elements
    int numbers[5] = {5, 2, 8, 1, 4};

    // Sort the array in ascending order
    sort(numbers, numbers + 5);

    cout << "Sorted array in ascending order: ";
    for (int i = 0; i < 5; ++i) {
        cout << numbers[i] << " ";
    }
    cout << endl;

    // Sort the array in descending order
    sort(numbers, numbers + 5, greater<int>());

    cout << "Sorted array in descending order: ";
    for (int i = 0; i < 5; ++i) {
        cout << numbers[i] << " ";
    }
    cout << endl;

    return 0;
}

