namespace {

// Centralized registry initializer singleton
struct RegistryInitializer {
    static RegistryInitializer& get() {
        static RegistryInitializer instance;
        return instance;
    }

    mlir::DialectRegistry& getRegistry() { return registry; }

private:
    RegistryInitializer() {
        mlir::registerAllDialects(registry);
        mlir::registerAllPasses();
        ::sdfg::codegen::register_default_dispatchers();
        ::sdfg::serializer::register_default_serializers();
    }

    mlir::DialectRegistry registry;
};

// Wrapper class for managing an MLIR module and its transformations
class SDFGTranslator {
public:
    explicit SDFGTranslator(const std::string& source) {
        auto& regInit = RegistryInitializer::get();
        ctx = new mlir::MLIRContext(regInit.getRegistry());
        ctx->loadAllAvailableDialects();

        auto mod = mlir::parseSourceString<mlir::ModuleOp>(source, ctx);
        if (!mod) {
            delete ctx;
            throw std::runtime_error("Failed to parse MLIR module");
        }
        module = mod.release();
    }

    ~SDFGTranslator() {
        if (module) module->erase();
        delete ctx;
    }

    // Returns textual representation of the module
    std::string describe() {
        std::string buffer;
        llvm::raw_string_ostream stream(buffer);
        module->print(stream);
        return buffer;
    }

    // Applies Linalg specialization passes
    void applyTransformations() {
        mlir::PassManager manager(ctx);
        manager.addPass(mlir::createLinalgSpecializeGenericOpsPass());
        if (mlir::failed(manager.run(*module))) {
            throw std::runtime_error("Transformation pipeline failed");
        }
    }

    // Converts the module to SDFG JSON format
    std::string exportSDFG() {
        std::string output;
        llvm::raw_string_ostream stream(output);
        if (mlir::failed(mlir::sdfg::translateToSDFG(module, stream))) {
            throw std::runtime_error("SDFG translation failed");
        }
        return output;
    }

    mlir::Operation* nativeHandle() const { return module; }

private:
    mlir::MLIRContext* ctx = nullptr;
    mlir::ModuleOp module = nullptr;
};

} // namespace

PYBIND11_MODULE(_sdfg_mlir, module) {
    module.doc() = "Python bindings for MLIR-to-SDFG compilation pipeline";

    py::class_<SDFGTranslator>(module, "MLIRModule")
        .def(py::init<const std::string&>(), py::arg("mlir_text"),
             "Constructs an MLIR module from textual IR input")
        .def("to_string", &SDFGTranslator::describe,
             "Returns the current MLIR module as a human-readable string")
        .def("convert", &SDFGTranslator::applyTransformations,
             "Applies optimization passes including Linalg specialization")
        .def("translate", &SDFGTranslator::exportSDFG,
             "Exports the transformed module into serialized SDFG format");
}

#include <asio.hpp>
#include <iostream>
#include <memory>
#include <string>

using asio::ip::tcp;

class connection_handler : public std::enable_shared_from_this<connection_handler>
{
public:
  explicit connection_handler(tcp::socket socket)
    : socket_(std::move(socket)),
      timeout_timer_(socket_.get_io_context()),
      work_strand_(socket_.get_io_context())
  {
  }

  void start()
  {
    auto self(shared_from_this());

    // First coroutine: handles data transfer with timeout
    asio::spawn(work_strand_,
        [this, self](asio::yield_context yield)
        {
          try
          {
            char buffer[1024];
            for (;;)
            {
              // Reset timer to 10 seconds
              timeout_timer_.expires_after(std::chrono::seconds(10));

              // Read data from socket
              std::size_t bytes_read = socket_.async_read_some(asio::buffer(buffer), yield);

              // Echo back the received data
              asio::async_write(socket_, asio::buffer(buffer, bytes_read), yield);
            }
          }
          catch (const std::exception&)
          {
            shutdown();
          }
        });

    // Second coroutine: monitors timeout and closes connection if expired
    asio::spawn(work_strand_,
        [this, self](asio::yield_context yield)
        {
          while (socket_.is_open())
          {
            asio::error_code ec;
            timeout_timer_.async_wait(yield[ec]);

            // Check if timer has expired (no activity within 10 seconds)
            if (timeout_timer_.expiry() <= asio::steady_timer::clock_type::now())
            {
              socket_.close();
            }
          }
        });
  }

private:
  void shutdown()
  {
    asio::error_code ignored_ec;
    socket_.close(ignored_ec);
    timeout_timer_.cancel(ignored_ec);
  }

private:
  tcp::socket socket_;
  asio::steady_timer timeout_timer_;
  asio::io_context::strand work_strand_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: echo_server <port>\n";
      return 1;
    }

    asio::io_context io_context;

    asio::spawn(io_context,
        [&](asio::yield_context yield)
        {
          tcp::acceptor acceptor(io_context,
            tcp::endpoint(tcp::v4(), std::atoi(argv[1])));

          for (;;)
          {
            asio::error_code ec;
            tcp::socket client_socket(io_context);
            acceptor.async_accept(client_socket, yield[ec]);

            if (!ec)
            {
              std::make_shared<connection_handler>(std::move(client_socket))->start();
            }
          }
        });

    io_context.run();
  }
  catch (const std::exception& e)
  {
    std::cerr << "Error: " << e.what() << "\n";
  }

  return 0;
}

#include <vector>
#include <set>

class Solution {
    std::multiset<long long> leftSet, rightSet;
public:
    long long minimumCost(std::vector<int>& nums, int k, int dist) {
        int n = nums.size();
        k--; // We need k-1 additional elements besides nums[0]

        // Initialize with first window [0, dist+1]
        long long currentSum = nums[0];
        for (int i = 1; i <= dist + 1 && i < n; i++) {
            currentSum += nums[i];
            leftSet.insert(nums[i]);
        }

        // Balance: move excess elements from leftSet to rightSet
        while (static_cast<int>(leftSet.size()) > k) {
            auto it = std::prev(leftSet.end());
            long long val = *it;
            currentSum -= val;
            rightSet.insert(val);
            leftSet.erase(it);
        }

        long long result = currentSum;

        // Slide the window from position dist+2 onwards
        for (int windowEnd = dist + 2; windowEnd < n; windowEnd++) {
            int removedIndex = windowEnd - dist - 1;

            // Remove the element going out of the window
            auto leftIt = leftSet.find(nums[removedIndex]);
            if (leftIt != leftSet.end()) {
                currentSum -= nums[removedIndex];
                leftSet.erase(leftIt);
            } else {
                auto rightIt = rightSet.find(nums[removedIndex]);
                if (rightIt != rightSet.end()) {
                    rightSet.erase(rightIt);
                }
            }

            // Add the new element coming into the window
            int newValue = nums[windowEnd];
            if (!leftSet.empty() && newValue < *leftSet.rbegin()) {
                currentSum += newValue;
                leftSet.insert(newValue);
            } else {
                rightSet.insert(newValue);
            }

            // Rebalance to maintain exactly k elements in leftSet
            while (static_cast<int>(leftSet.size()) < k && !rightSet.empty()) {
                long long val = *rightSet.begin();
                currentSum += val;
                leftSet.insert(val);
                rightSet.erase(rightSet.begin());
            }

            while (static_cast<int>(leftSet.size()) > k) {
                auto it = std::prev(leftSet.end());
                long long val = *it;
                currentSum -= val;
                rightSet.insert(val);
                leftSet.erase(it);
            }

            result = std::min(result, currentSum);
        }

        return result;
    }
};

