// Helper function to print a vector of strings in quoted format
void print_string_vector(const std::vector<std::string>& vec, const std::string& indent = "\t") {
    for (const auto& item : vec) {
        std::cout << "'" << item << "' ";
    }
}

// Refactored version using sol::nested with renamed variables and inline assertions
void demo_renamed(
     sol::nested<std::map<std::string, std::vector<std::string>>>
          data_container) {
    std::cout << "demo, sol::nested<...> (renamed)" << std::endl;

    const auto& map_ref = data_container.value();
    if (map_ref.size() != 2) {
        throw std::runtime_error("Expected exactly 2 key-value pairs");
    }

    for (const auto& [key, value_vec] : map_ref) {
        if (value_vec.size() != 3) {
            throw std::runtime_error("Each vector must contain exactly 3 elements");
        }
        std::cout << "\t" << key << " = ";
        print_string_vector(value_vec);
        std::cout << std::endl;
    }
    std::cout << std::endl;
}

// Equivalent explicit version using sol::as_table_t with modified structure
void demo_explicit_renamed(
     sol::as_table_t<std::map<std::string,
          sol::as_table_t<std::vector<std::string>>>>
          wrapped_data) {
    std::cout << "demo, explicit sol::as_table_t<...> (renamed)"
              << std::endl;

    const auto& outer_map = wrapped_data.value();
    if (outer_map.size() != 2) {
        throw std::runtime_error("Outer map must have 2 entries");
    }

    for (const auto& [outer_key, inner_wrapper] : outer_map) {
        const auto& inner_vec = inner_wrapper.value();
        if (inner_vec.size() != 3) {
            throw std::runtime_error("Inner vector must have 3 elements");
        }
        std::cout << "\t" << outer_key << " = ";
        print_string_vector(inner_vec);
        std::cout << std::endl;
    }
    std::cout << std::endl;
}

