// LeetCode 210: Course Schedule II - Modified Implementation
// This solution uses Kahn's algorithm for topological sorting instead of DFS
class Solution {
public:
    vector<int> findOrder(int numCourses, vector<vector<int>>& prerequisites) {
        // Build adjacency list and calculate in-degrees
        vector<vector<int>> adj(numCourses);
        vector<int> inDegree(numCourses, 0);

        // Process prerequisites: for [a, b], b -> a (b is prerequisite for a)
        for (const auto& pre : prerequisites) {
            int course = pre[0];
            int prereq = pre[1];
            adj[prereq].push_back(course);
            inDegree[course]++;
        }

        // Initialize queue with all courses having no prerequisites (in-degree 0)
        queue<int> q;
        for (int i = 0; i < numCourses; i++) {
            if (inDegree[i] == 0) {
                q.push(i);
            }
        }

        vector<int> result;
        // Process courses using BFS (Kahn's algorithm)
        while (!q.empty()) {
            int curr = q.front();
            q.pop();
            result.push_back(curr);

            // Reduce in-degree of dependent courses
            for (int neighbor : adj[curr]) {
                inDegree[neighbor]--;
                if (inDegree[neighbor] == 0) {
                    q.push(neighbor);
                }
            }
        }

        // If we couldn't process all courses, there's a cycle
        if (result.size() != numCourses) {
            return {}; // Return empty list if impossible
        }

        return result;
    }
};

