#include <iostream>
#include <vector>
#include <string>

int main() {
    // Design a winding path on a 20x20 grid to simulate a constrained random walk
    // The path is constructed to maximize the chance of non-synchronization 
    // by limiting connectivity and creating a long but narrow corridor.

    const int rows = 20;
    const int cols = 20;

    std::cout << rows << " " << cols << "\n";

    std::vector<std::string> layout(rows, std::string(cols, '0'));

    // Build a serpentine (zigzag) corridor:
    // - Even-indexed rows (0, 2, ...) are fully open horizontally
    // - Odd-indexed rows have exactly one opening to link adjacent rows,
    //   alternating between left and right ends to create a snake-like path

    for (int r = 0; r < rows; ++r) {
        if (r % 2 == 0) {
            // Fill entire even row with open cells
            for (int c = 0; c < cols; ++c) {
                layout[r][c] = '1';
            }
        } else {
            // For odd rows, place a single passage at alternating ends
            int col_pos = (r / 2) % 2 == 0 ? (cols - 1) : 0;
            layout[r][col_pos] = '1';
        }
    }

    // Output the resulting grid
    for (const auto& line : layout) {
        std::cout << line << "\n";
    }

    return 0;
}

