// Validate string handling across various lengths including edge cases
void evaluate_string_lengths(SMTParser::ParserPtr& parser) {
    std::vector<std::string> test_cases;
    test_cases.push_back(""); // Empty input
    test_cases.push_back("true");
    test_cases.push_back("false");
    test_cases.push_back("a_very_long_identifier_name_to_test_buffer_handling");
    test_cases.push_back("(and (or true false) (not true))");

    // Construct a long string programmatically
    std::string long_str;
    for (int i = 0; i < 1000; ++i) {
        long_str += 'a';
    }
    test_cases.push_back(long_str);

    for (size_t idx = 0; idx < test_cases.size(); ++idx) {
        const std::string& current = test_cases[idx];
        std::cout << "Examining string length: " << current.length() << std::endl;

        std::shared_ptr<SMTParser::DAGNode> node = parser->mkConstStr(current);
        assert(node != nullptr && !node->isErr());

        std::cout << "  Output: " << parser->toString(node) << std::endl;
    }
}

// Examine expressions involving special characters and syntax
void inspect_special_syntax(SMTParser::ParserPtr& parser) {
    std::vector<std::string> samples;
    samples.push_back("\"quoted string\"");
    // "|symbol with spaces|" -> would cause error if uncommented
    // ";comment" -> would cause error if uncommented
    samples.push_back("(and (or true false) (not true))");

    for (size_t i = 0; i < samples.size(); ++i) {
        const std::string& expr = samples[i];
        std::cout << "Processing expression: " << expr << std::endl;

        std::shared_ptr<SMTParser::DAGNode> parsed = parser->mkExpr(expr);
        assert(parsed != nullptr && !parsed->isErr());

        std::cout << "  Parsed form: " << parser->toString(parsed) << std::endl;
    }
}

int main() {
    std::cout << "======= String Handling Safety Test =======" << std::endl;

    SMTParser::ParserPtr sm_parser = SMTParser::newParser();

    std::cout << "\n--- Evaluating String Lengths ---" << std::endl;
    evaluate_string_lengths(sm_parser);

    std::cout << "\n--- Inspecting Special Syntax ---" << std::endl;
    inspect_special_syntax(sm_parser);

    return 0;
}

