#include <vector>
#include <algorithm>
#include <climits>

class Solution {
public:
    int minOperations(std::vector<int>& nums) {
        int total = nums.size();
        int ones = 0;

        // Count existing ones
        for (int x : nums) {
            if (x == 1) ones++;
        }

        // If there are ones, just convert the rest
        if (ones > 0) {
            return total - ones;
        }

        int min_ops = INT_MAX;

        // Find the smallest window with GCD = 1
        for (int start = 0; start < total; start++) {
            int current_gcd = nums[start];
            for (int end = start + 1; end < total; end++) {
                // Calculate GCD iteratively
                int a = current_gcd;
                int b = nums[end];
                while (b != 0) {
                    int temp = b;
                    b = a % b;
                    a = temp;
                }
                current_gcd = a;

                // If we found GCD 1, calculate operations needed
                if (current_gcd == 1) {
                    int operations_to_create_one = end - start;
                    int operations_to_convert_rest = total - 1;
                    min_ops = std::min(min_ops, operations_to_create_one + operations_to_convert_rest);
                    break;
                }
            }
        }

        return (min_ops == INT_MAX) ? -1 : min_ops;
    }
};

