// Retrieve device pointer for a given field (snode) within the program
DevicePtr get_device_ptr(quadrants::lang::Program *program, SNode *snode) {
  /*
  GGUI assumes that input fields originate from ti.field() or ti.Vector with
  explicit shape, implying they are built using ti.root.dense.place().
  Specifically: snode's parent is dense, and that parent's parent is root.
  This structure enables computing the field's offset relative to the root buffer.
  Note: This holds except possibly for set_image(), where image data bypasses VBO.
  */

  // Navigate up the SNode hierarchy: snode -> dense_parent -> root
  SNode *dense_parent = snode->parent;
  SNode *root_node = dense_parent->parent;

  // Extract tree identifier and root buffer device pointer
  int tree_identifier = root_node->get_snode_tree_id();
  DevicePtr base_root_ptr = program->get_snode_tree_device_ptr(tree_identifier);

  // Compute field-specific offset within the root buffer and return final pointer
  size_t field_offset = program->get_field_in_tree_offset(tree_identifier, snode);
  return base_root_ptr.get_ptr(field_offset);
}
