class Solution {
public:
    int missingNumber(vector<int>& nums) {
        int n = nums.size();
        sort(nums.begin(), nums.end());

        int current = 0;
        for (int i = 0; i < n; ++i) {
            if (nums[i] != current) {
                return current;
            }
            current++;
        }

        return n;
    }
};

#include <iostream>
#include <vector>
#include <algorithm>

// Global variables to track the current state
std::vector<int> arr;      // Current permutation (0-indexed)
std::vector<int> indexMap; // indexMap[v] = 1-based position of value v
std::vector<std::pair<int, int>> operations; // Store all reversal operations

// Apply a reversal operation on positions [l, r] (1-based)
void performReversal(int left, int right) {
    if (left > right) std::swap(left, right);

    operations.push_back({left, right});

    // Convert to 0-based indices for the actual reversal
    int start = left - 1;
    int end = right;
    std::reverse(arr.begin() + start, arr.begin() + end);

    // Update the position map for all affected elements
    for (int pos = left; pos <= right; ++pos) {
        indexMap[arr[pos - 1]] = pos;
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    // Initialize data structures
    arr.resize(n);
    indexMap.resize(n + 1);

    // Read input and initialize position map
    for (int i = 0; i < n; ++i) {
        std::cin >> arr[i];
        indexMap[arr[i]] = i + 1;
    }

    // Choose x = 3 as in the original solution
    int x = 3;

    // Sort by placing each element from n down to 1 into its correct position
    for (int target = n; target >= 1; --target) {
        int currentPos = indexMap[target];

        // Move the target element towards its correct position (position 'target')
        while (currentPos < target) {
            // Determine how far we can move using reversals of length 2 or 4
            if (currentPos + 3 <= target) {
                // Use reversal of length 4: positions [currentPos, currentPos+3]
                performReversal(currentPos, currentPos + 3);
            } else {
                // Use reversal of length 2: positions [currentPos, currentPos+1]
                performReversal(currentPos, currentPos + 1);
            }

            // Refresh current position after reversal
            currentPos = indexMap[target];
        }
    }

    // Output results
    std::cout << x << "\n";
    std::cout << operations.size() << "\n";
    for (const auto& op : operations) {
        std::cout << op.first << " " << op.second << "\n";
    }

    return 0;
}

