#include <ctpl.h>
#include <iostream>
#include <string>
#include <thread>
#include <chrono>

// Renamed functions and slightly adjusted logic for Type III clone
void greet(int worker_id) { 
    std::cout << "hello from " << worker_id << ", function\n"; 
}

void greet_with_value(int worker_id, int value) {
    std::cout << "hello from " << worker_id << ", function with parameter " << value
              << '\n';
}

struct CustomClass {
    CustomClass(int initial_value) : val(initial_value) {
        std::cout << "CustomClass ctor " << this->val << '\n';
    }

    CustomClass(CustomClass &&other) : val(other.val) {
        std::cout << "CustomClass move ctor\n";
    }

    CustomClass(const CustomClass &other) : val(other.val) {
        std::cout << "CustomClass copy ctor\n";
    }

    ~CustomClass() { 
        std::cout << "CustomClass dtor\n"; 
    }

    int val;
};

void process_string(int worker_id, const std::string &text) {
    std::cout << "process_string function " << worker_id << ' ' << text << '\n';
}

void delayed_task(int worker_id, CustomClass &obj) {
    std::this_thread::sleep_for(std::chrono::milliseconds(2000));
    std::cout << "hello from " << worker_id << ", function with parameter CustomClass " << obj.val
              << '\n';
}

int main(int argc, char **argv) {
    ctpl::thread_pool pool(2 /* two threads in the pool */);

    // Launch tasks using different callable types
    std::future<void> future1 = pool.push(std::ref(greet));  
    pool.push(greet);                                   
    pool.push(greet_with_value, 7);                                 

    // Local scope for functor definition
    {
        struct LocalFunctor {
            LocalFunctor(const std::string &msg) : message(msg) { 
                std::cout << "LocalFunctor ctor\n"; 
            }

            LocalFunctor(LocalFunctor &&other) : message(std::move(other.message)) {
                std::cout << "LocalFunctor move ctor\n";
            }

            LocalFunctor(const LocalFunctor &other) : message(other.message) { 
                std::cout << "LocalFunctor copy ctor\n"; 
            };

            ~LocalFunctor() { 
                std::cout << "LocalFunctor dtor\n"; 
            }

            void operator()(int id) const {
                std::cout << "hello from " << id << ' ' << this->message << '\n';
            }

        private:
            std::string message;
        } functor(", functor");

        pool.push(std::ref(functor));  
        std::this_thread::sleep_for(std::chrono::milliseconds(2000));
        pool.push(const_cast<const LocalFunctor &>(functor));  
        pool.push(std::move(functor));                   
        pool.push(functor);                              
        pool.push(LocalFunctor(", functor"));                
    }

    {
        CustomClass instance(100);
        pool.push(delayed_task, std::ref(instance));   
        pool.push(delayed_task, instance);             
        pool.push(delayed_task, std::move(instance));  
    }

    pool.push(delayed_task, CustomClass(200));  
    std::string lambda_capture = ", lambda";

    // Lambda expressions with same semantics but renamed variables
    pool.push([lambda_capture](int id) {  
        std::this_thread::sleep_for(std::chrono::milliseconds(2000));
        std::cout << "hello from " << id << ' ' << lambda_capture << '\n';
    });

    pool.push([lambda_capture](int id) {  
        std::this_thread::sleep_for(std::chrono::milliseconds(2000));
        std::cout << "hello from " << id << ' ' << lambda_capture << '\n';
    });

    pool.push(process_string, "worked");

    auto task = pool.pop();
    if (task) {
        std::cout << "poped function from the pool ";
        task(0);
    }

    // Adjust thread pool size
    pool.resize(1);

    std::string result_str = "result";
    auto future_result = pool.push([result_str](int) { return result_str; });

    std::cout << "returned " << future_result.get() << '\n';

    auto failing_task = pool.push([](int) { throw std::exception(); });

    try {
        failing_task.get();
    } catch (std::exception &ex) {
        std::cout << "caught exception\n";
    }

    // Access a specific thread reference
    auto &worker_thread = pool.get_thread(0);
    return 0;
}

