#include <iostream>
#include <vector>
#include <cstdlib>
using namespace std;

// Global array to store the final sequence (size sufficient for max N = 200,000)
int result[200005];

/**
 * Recursive helper function that reconstructs the array using divide-and-conquer.
 * For a given interval [low, high], it queries the mode and its frequency.
 * If all elements in the interval are identical, fills them directly.
 * Otherwise, splits the interval and recurses on both halves.
 */
void reconstruct(int low, int high) {
    if (low > high) return;

    // Query the current segment: "? low high"
    cout << "? " << low << " " << high << endl;
    fflush(stdout); // Ensure output is flushed for interactive problems

    long long modeVal;
    int freq;

    // Safely read input; exit on failure or invalid response
    if (!(cin >> modeVal >> freq)) {
        exit(0);
    }
    if (modeVal == -1 || freq == -1) {
        exit(0);
    }

    int mode = static_cast<int>(modeVal);
    int len = high - low + 1;

    // Base case: entire segment has same value
    if (freq == len) {
        for (int i = low; i <= high; ++i) {
            result[i] = mode;
        }
        return;
    }

    // Recursive case: split into two halves
    int mid = (low + high) / 2;
    reconstruct(low, mid);
    reconstruct(mid + 1, high);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (cin >> n) {
        reconstruct(1, n);

        // Output the reconstructed array
        cout << "! ";
        for (int i = 1; i <= n; ++i) {
            cout << result[i];
            if (i < n) cout << " ";
        }
        cout << endl;
    }

    return 0;
}

