#include "ConstrainedMeshSmoothers.h"
#include "MatrixSolver.h"
#include "ConstrainedPoissonSolver.h"

bool FBiHarmonicMeshSmoother::ComputeSmoothedMeshPositions(TArray<FVector3d>& OutPositions)
{
    UpdateSolverConstraints();

    // Construct right-hand side vector for the biharmonic system
    FSOAPositions RHSVector(InternalVertexCount);

    if (InternalVertexCount != VertexCount) // boundary vertices present
    {
        for (int32 coord = 0; coord < 3; ++coord)
        {
            RHSVector.Array(coord) = BoundaryOperator * BoundaryPositions.Array(coord);
        }
    }
    else
    {
        RHSVector.ZeroInitialize();
    }

    // Solve constrained optimization problem
    FSOAPositions ResultVector(InternalVertexCount);
    const bool bSolveOK = ConstrainedSolver->Solve(RHSVector, ResultVector);

    // Apply post-fix constraint corrections if any
    ApplyPostFixAdjustments(ResultVector);

    // Prepare output buffer with correct capacity
    const int32 TotalVertices = VtxLinearization.ToId().Num();
    OutPositions.Reset(TotalVertices);
    OutPositions.SetNumUninitialized(TotalVertices);

    // Populate internal vertex positions from solution
    TransferInternalCoords(ResultVector, OutPositions);

    // Fill in boundary vertex positions
    TransferBoundaryCoords(OutPositions);

    return bSolveOK;
}

bool FCGBiHarmonicMeshSmoother::ComputeSmoothedMeshPositions(TArray<FVector3d>& OutPositions)
{
    UpdateSolverConstraints();

    // Build source term for CG-based smoothing
    FSOAPositions RHSVector(InternalVertexCount);

    if (InternalVertexCount != VertexCount) // non-trivial boundary handling
    {
        for (int32 axis = 0; axis < 3; ++axis)
        {
            RHSVector.Array(axis) = BoundaryOperator * BoundaryPositions.Array(axis);
        }
    }
    else
    {
        RHSVector.FillZero();
    }

    // Perform constrained solve
    FSOAPositions SolutionVec(InternalVertexCount);
    const bool bSuccess = ConstrainedSolver->Solve(RHSVector, SolutionVec);

    // Enforce final post-fix constraints
    ApplyPostFixAdjustments(SolutionVec);

    // Resize output array appropriately
    const int32 MaxIndex = VtxLinearization.ToId().Num();
    OutPositions.Empty(MaxIndex);
    OutPositions.AddDefaulted(MaxIndex);

    // Copy computed interior values into result structure
    TransferInternalCoords(SolutionVec, OutPositions);

    // Ensure boundary values are copied over
    TransferBoundaryCoords(OutPositions);

    return bSuccess;
}

