TEST(UIThreadSafetyTest, ConcurrentPrinting) {
  std::vector<std::thread> worker_threads;
  const int thread_count = 10;
  const int iterations_per_thread = 50;

  // Launch multiple threads that concurrently call UI print functions
  for (int t_idx = 0; t_idx < thread_count; ++t_idx) {
