        PrintToolCallMessage(tool_name, arg_json, "  ", 0);
        PrintToolResultMessage(tool_name, result_msg, "completed", "  ");
      }
    });
  }

  // Wait for all threads to complete execution
  for (auto& thread : worker_threads) {
