#include <assert.h>
#include <mpi.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Generate an array of random floating-point values in [0, 1]
float*
generate_random_values(int count)
{
    float* values = (float*) malloc(sizeof(float) * count);
    assert(values != NULL);
    for (int idx = 0; idx < count; ++idx)
    {
        values[idx] = static_cast<float>(rand()) / static_cast<float>(RAND_MAX);
    }
    return values;
}

// Compute the arithmetic mean of a given array
float
calculate_mean(const float* data, int length)
{
    double total = 0.0;
    for (int i = 0; i < length; ++i)
    {
        total += data[i];
    }
    return static_cast<float>(total / length);
}

int
main(int argc, char** argv)
{
    if (argc != 2)
    {
        fprintf(stderr, "Usage: %s elements_per_process\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    int elements_per_rank = atoi(argv[1]);
    srand(static_cast<unsigned>(time(NULL)));

    MPI_Init(nullptr, nullptr);

    int rank, size;
    MPI_Comm_rank(MPI_COMM_WORLD, &rank);
    MPI_Comm_size(MPI_COMM_WORLD, &size);

    // Root process generates the full dataset
    float* global_data = nullptr;
    if (rank == 0)
    {
        global_data = generate_random_values(elements_per_rank * size);
    }

    // Allocate local buffer for scattered data
    float* local_data = (float*) malloc(sizeof(float) * elements_per_rank);
    assert(local_data != nullptr);

    // Distribute data across processes
    MPI_Scatter(global_data, elements_per_rank, MPI_FLOAT,
                local_data, elements_per_rank, MPI_FLOAT, 0, MPI_COMM_WORLD);

    // Compute local average
    float local_avg = calculate_mean(local_data, elements_per_rank);

    // Collect all local averages at root
    float* partial_avgs = nullptr;
    if (rank == 0)
    {
        partial_avgs = (float*) malloc(sizeof(float) * size);
        assert(partial_avgs != nullptr);
    }

    MPI_Gather(&local_avg, 1, MPI_FLOAT,
               partial_avgs, 1, MPI_FLOAT, 0, MPI_COMM_WORLD);

    // Final average calculation at root
    if (rank == 0)
    {
        float overall_avg = calculate_mean(partial_avgs, size);
        printf("Average from partial results: %f\n", overall_avg);

        float reference_avg = calculate_mean(global_data, elements_per_rank * size);
        printf("Average from full dataset:    %f\n", reference_avg);

        free(global_data);
        free(partial_avgs);
    }

    free(local_data);
    MPI_Barrier(MPI_COMM_WORLD);
    MPI_Finalize();

    return 0;
}

