int main() {
    int distanceToExit;
    cin >> distanceToExit;

    while (distanceToExit > 0) {
        bool foundBetterPath = false;

        for (int color = 0; color < 3 && !foundBetterPath; ++color) {
            // Attempt movement in current color direction
            cout << "move " << color << endl;

            int movementResult;
            cin >> movementResult;

            if (movementResult == 1) {
                return 0; // Exit reached
            }

            // Check new distance after movement
            cout << "query" << endl;
            int updatedDistance;
            cin >> updatedDistance;

            // Determine if we made progress toward exit
            if (updatedDistance == distanceToExit - 1) {
                distanceToExit = updatedDistance;
                foundBetterPath = true;
            } else {
                // We moved away from exit, return to original position
                cout << "move " << color << endl;
                int returnResult;
                cin >> returnResult;

                if (returnResult == 1) {
                    return 0; // Exit reached on return path
                }
            }
        }
    }

    return 0;
}

