// Leetcode 1352: Product of Last K Numbers (Type III Clone)
class ProductOfNumbers {
private:
    vector<int> prefixProducts;  // Stores cumulative products, starting with 1 as base

public:
    ProductOfNumbers() {
        prefixProducts.push_back(1);  // Initialize with multiplicative identity
    }

    void add(int value) {
        if (value == 0) {
            // Reset the prefix products when encountering zero
            prefixProducts.clear();
            prefixProducts.push_back(1);
        } else {
            // Append new product = previous product * current value
            prefixProducts.push_back(prefixProducts.back() * value);
        }
    }

    int getProduct(int k) {
        // If k exceeds available products (excluding initial 1), there must have been a zero in last k elements
        if (k >= prefixProducts.size()) {
            return 0;
        }
        // Compute product using division of prefix products
        return prefixProducts.back() / prefixProducts[prefixProducts.size() - k - 1];
    }
};

// Time Complexity:
// - add: O(1)
// - getProduct: O(1)
// Space Complexity: O(n) where n is number of elements added
// Note: Uses prefix product technique for efficient computation; handles zeros by resetting the sequence

