class TextConverterApp : public BApplication
{
public:
	TextConverterApp(int argc, char** argv)
		:
		BApplication("application/x-vnd.demo-textconverter"),
		fArgc(argc),
		fArgv(argv)
	{
	}

	void ReadyToRun() override
	{
		if (fArgc < 2) {
			std::cerr << "Usage: " << fArgv[0] << " <input_file>" << std::endl;
			PostMessage(B_QUIT_REQUESTED);
			return;
		}

		const char* inputPath = fArgv[1];

		// Attempt to open the source file
		BFile inputFile(inputPath, B_READ_ONLY);
		if (inputFile.InitCheck() != B_OK) {
			std::cerr << "Error: Unable to access file '" << inputPath << "'" << std::endl;
			PostMessage(B_QUIT_REQUESTED);
			return;
		}

		// Prepare output file with a fixed name
		BFile outputFile("converted_output.txt",
			B_CREATE_FILE | B_ERASE_FILE | B_WRITE_ONLY);

		// Retrieve default translator roster
		BTranslatorRoster* roster = BTranslatorRoster::Default();
		if (!roster) {
			std::cerr << "Critical error: Could not initialize translator system" << std::endl;
			PostMessage(B_QUIT_REQUESTED);
			return;
		}

		// Perform translation from RTF to plain text
		status_t result = roster->Translate(&inputFile, nullptr, nullptr, &outputFile, 'TEXT');
		if (result != B_OK) {
			std::cerr << "Conversion failed: " << strerror(result) << std::endl;
		} else {
			std::cout << "Success: File converted and saved as 'converted_output.txt'" << std::endl;
		}

		// Terminate application gracefully
		PostMessage(B_QUIT_REQUESTED);
	}

private:
	int fArgc;
	char** fArgv;
};

int main(int argc, char** argv)
{
	TextConverterApp app(argc, argv);
	app.Run();
	return 0;
}

