// Helper function to extract hint entries from hints.ini and store them in pot_elements
bool extract_hint_entries(const boost::filesystem::path& ini_path, 
                          std::vector<std::pair<std::string, std::string>>& pot_elements) {
    namespace pt = boost::property_tree;
    pt::ptree root;

    try {
        boost::nowide::ifstream input_file(ini_path.string());
        if (!input_file.is_open()) {
            std::cerr << "Failed to open INI file: " << ini_path.string() << std::endl;
            return false;
        }
        pt::read_ini(input_file, root);
    } catch (const pt::ini_parser::ini_parser_error& e) {
        std::cerr << "INI parsing error: " << e.what() << std::endl;
        return false;
    }

    for (const auto& section : root) {
        const std::string& section_name = section.first;

        // Only process sections starting with "hint:"
        if (section_name.find("hint:") == 0) {
            for (const auto& key_value : section.second) {
                if (key_value.first == "text" && !key_value.second.data().empty()) {
                    pot_elements.emplace_back(section_name, key_value.second.data());
                    break; // Take only the first 'text' entry per section
                }
            }
        }
    }
    return true;
}

// Append extracted entries to a .pot file in gettext format
bool append_to_pot_file(const boost::filesystem::path& pot_path, 
                        const std::vector<std::pair<std::string, std::string>>& entries) {
    boost::nowide::ofstream output_file(pot_path.string(), std::ios_base::app);
    if (!output_file.is_open()) {
        std::cerr << "Failed to open POT file for writing: " << pot_path.string() << std::endl;
        return false;
    }

    for (const auto& item : entries) {
        output_file << "\n#: resources/data/hints.ini: [" << item.first << "]\n"
                   << "msgid \"" << item.second << "\"\n"
                   << "msgstr \"\"\n";
    }

    output_file.close();
    return true;
}

int main(int argc, char* argv[]) {
    // Validate command-line arguments
    if (argc != 3) {
        std::cerr << "HINTS_TO_POT FAILED: WRONG NUMBER OF ARGUMENTS" << std::endl;
        return -1;
    }

    // Resolve canonical paths for input and output files
    boost::filesystem::path base_dir_ini = boost::filesystem::canonical(argv[1]).parent_path();
    boost::filesystem::path base_dir_pot = boost::filesystem::canonical(argv[2]).parent_path();

    boost::filesystem::path hints_ini_path = base_dir_ini / "resources" / "data" / "hints.ini";
    boost::filesystem::path pot_output_path = base_dir_pot / "localization" / "preFlight.pot";

    // Check existence of input INI file
    if (!boost::filesystem::exists(hints_ini_path)) {
        std::cerr << "HINTS_TO_POT FAILED: INI FILE DOES NOT EXIST" << std::endl;
        std::cerr << "Expected path: " << hints_ini_path.string() << std::endl;
        return -1;
    }

    // Collect hint entries
    std::vector<std::pair<std::string, std::string>> extracted_data;
    if (!extract_hint_entries(hints_ini_path, extracted_data)) {
        std::cerr << "HINTS_TO_POT FAILED TO EXTRACT HINT ENTRIES" << std::endl;
        return -1;
    }

    // Write to POT file
    if (!append_to_pot_file(pot_output_path, extracted_data)) {
        std::cerr << "HINTS_TO_POT FAILED TO WRITE POT FILE" << std::endl;
        return -1;
    }

    std::cout << "HINTS_TO_POT SUCCESS" << std::endl;
    return 0;
}

