#include <iostream>
#include "sophus/geometry.hpp"

int main() {
  // Compute combined rotation using three axis-aligned rotations
  const double pi = Sophus::Constants<double>::pi();

  // Define individual rotations around coordinate axes
  Sophus::SO3d Rx = Sophus::SO3d::rotX(pi / 4.0);
  Sophus::SO3d Ry = Sophus::SO3d::rotY(pi / 6.0);
  Sophus::SO3d Rz = Sophus::SO3d::rotZ(-pi / 3.0);

  // Display rotation matrices
  std::cout << "Rotation matrices:" << std::endl;
  std::cout << "Rx:\n" << Rx.matrix() << std::endl;
  std::cout << "Ry:\n" << Ry.matrix() << std::endl;
  std::cout << "Rz:\n" << Rz.matrix() << std::endl;
  std::cout << "Combined rotation Rx*Ry*Rz:\n"
            << (Rx * Ry * Rz).matrix() << std::endl;
  std::cout << std::endl;

  // Apply rotations to a test vector
  Eigen::Vector3d point;
  point << 0.0, 0.0, 1.0;

  std::cout << "Vector transformation under rotation:" << std::endl;
  std::cout << "Original vector:\n" << point << std::endl;
  std::cout << "Ry applied:\n" << Ry * point << std::endl;
  std::cout << "Rx(Ry(vector)):\n" << Rx * (Ry * point) << std::endl;
  std::cout << "(Rx*Ry) applied:\n" << (Rx * Ry) * point << std::endl;
  std::cout << std::endl;

  // Show internal representation as unit quaternion
  std::cout << "Matrix representation of Rx:\n" << Rx.matrix() << std::endl;
  std::cout << "Quaternion representation of Rx:\n"
            << Rx.unit_quaternion().coeffs() << std::endl;
  // Note: Eigen uses (i, j, k, r) ordering for quaternion coefficients
  std::cout << std::endl;

  return 0;
}

