      file << message << '\n';
      file.flush();
    }
  }

  void Logger::write(const Level level, const std::string& message)
  {
    std::string timestamp = time::get("(%d-%B-%Y %I:%M:%S)");
    std::string prefix = LEVEL_STRINGS[level];
    std::string formatted = prefix + " " + timestamp + " " + message;
    write_raw(formatted);
  }

