class CommentFileFinder : public BApplication
{
public:
    CommentFileFinder()
        : BApplication("application/x-vnd.kitlab-listcommentfiles")
    {
        ExecuteSearch();
        PostMessage(B_QUIT_REQUESTED);
    }

private:
    void ExecuteSearch()
    {
        // --- Locate the user's home directory ---
        BPath userHome;
        if (find_directory(B_USER_DIRECTORY, &userHome) != B_OK) {
            fprintf(stderr, "Error: Could not locate user home directory.\n");
            return;
        }

        BDirectory dir(userHome.Path());
        BVolume vol;
        if (dir.GetVolume(&vol) != B_OK) {
            fprintf(stderr, "Error: Unable to retrieve volume for home directory.\n");
            return;
        }

        // --- Output search context ---
        printf("Scanning location: %s\n", userHome.Path());
        printf("Target: Files with 'Comment' metadata and MIME type text/plain\n\n");

        const char* targetMimeType = "text/plain";

        // --- Build the query criteria ---
        BQuery searchQuery;
        searchQuery.SetVolume(&vol);

        // Condition 1: MIME type must be text/plain
        searchQuery.PushAttr("BEOS:TYPE");
        searchQuery.PushString(targetMimeType);
        searchQuery.PushOp(B_EQ);

        // Condition 2: 'Comment' attribute exists and is non-empty
        searchQuery.PushAttr("Comment");
        searchQuery.PushString("*");
        searchQuery.PushOp(B_EQ);

        // Combine both conditions with logical AND
        searchQuery.PushOp(B_AND);

        // --- Execute the query ---
        if (searchQuery.Fetch() != B_OK) {
            fprintf(stderr, "Error: Query execution failed.\n");
            return;
        }

        // --- Process results ---
        entry_ref reference;
        int foundCount = 0;

        while (searchQuery.GetNextRef(&reference) == B_OK) {
            BEntry item(&reference);
            BPath fullPath(&item);

            // Ensure the file resides under the user's home directory
            size_t homeLen = strlen(userHome.Path());
            if (strncmp(fullPath.Path(), userHome.Path(), homeLen) == 0) {
                printf("Match: %s\n", fullPath.Path());
                foundCount++;
            }
        }

        // --- Report outcome ---
        if (foundCount == 0)
            printf("No matching files were found.\n");
    }
};

int main()
{
    CommentFileFinder finder;
    finder.Run();
    return 0;
}

