void UAbilityTask_NetworkSyncPoint::Activate()
{
	FScopedPredictionWindow ScopedPrediction(AbilitySystemComponent, IsPredictingClient());

	if (!AbilitySystemComponent.IsValid())
	{
		return;
	}

	bool bShouldListenForEvent = false;
	EAbilityGenericReplicatedEvent EventToSubscribe = EAbilityGenericReplicatedEvent::MAX;

	if (IsPredictingClient())
	{
		// Determine if we need to wait for server signal
		if (SyncType != EAbilityTaskNetSyncType::OnlyServerWait)
		{
			EventToSubscribe = EAbilityGenericReplicatedEvent::GenericSignalFromServer;
			bShouldListenForEvent = true;
