		// Determine if we need to notify server about client signal
		if (SyncType != EAbilityTaskNetSyncType::OnlyClientWait)
		{
			AbilitySystemComponent->ServerSetReplicatedEvent(
				EAbilityGenericReplicatedEvent::GenericSignalFromClient,
				GetAbilitySpecHandle(),
				GetActivationPredictionKey(),
				AbilitySystemComponent->ScopedPredictionKey
			);
		}
	}
	else if (IsForRemoteClient())
	{
		// Determine if we need to wait for client signal
		if (SyncType != EAbilityTaskNetSyncType::OnlyClientWait)
		{
			EventToSubscribe = EAbilityGenericReplicatedEvent::GenericSignalFromClient;
			bShouldListenForEvent = true;
		}

		// Determine if we need to notify client about server signal
		if (SyncType != EAbilityTaskNetSyncType::OnlyServerWait)
		{
			AbilitySystemComponent->ClientSetReplicatedEvent(
				EAbilityGenericReplicatedEvent::GenericSignalFromServer,
				GetAbilitySpecHandle(),
				GetActivationPredictionKey()
			);
		}
	}

	// Register delegate only if we're waiting for a replicated event
	if (bShouldListenForEvent && EventToSubscribe != EAbilityGenericReplicatedEvent::MAX)
	{
		CallOrAddReplicatedDelegate(EventToSubscribe, FSimpleMulticastDelegate::FDelegate::CreateUObject(this, &UAbilityTask_NetworkSyncPoint::OnSignalCallback));
	}
	else
	{
		// No replication needed - sync completes immediately
		SyncFinished();
	}
}

void UAbilityTask_NetworkSyncPoint::SyncFinished()
{
	if (IsValid(this) && !HasAnyFlags(RF_PendingKill))
	{
		if (ShouldBroadcastAbilityTaskDelegates())
		{
			OnSync.Broadcast();
		}
		EndTask();
	}
}

