// Factory function to allocate and initialize MCInstrInfo for NVPTX
static MCInstrInfo *buildNVPTXMCInstrInfo() {
  MCInstrInfo *info = new MCInstrInfo();
  InitNVPTXMCInstrInfo(info);
  return info;
}

// Factory function to allocate and initialize MCRegisterInfo for NVPTX
static MCRegisterInfo *buildNVPTXMCRegisterInfo(const Triple &targetTriple) {
  MCRegisterInfo *regInfo = new MCRegisterInfo();
  // PTX architecture lacks a dedicated return address register
  InitNVPTXMCRegisterInfo(regInfo, /*RAReg=*/0);
  return regInfo;
}

// Factory function to construct MCSubtargetInfo for NVPTX
static MCSubtargetInfo *
buildNVPTXMCSubtargetInfo(const Triple &targetTriple,
                          StringRef cpuName,
                          StringRef featureString) {
  return createNVPTXMCSubtargetInfoImpl(targetTriple, cpuName, /*TuneCPU=*/cpuName, featureString);
}

// Factory function to produce an MCInstPrinter instance for NVPTX assembly output
static MCInstPrinter *buildNVPTXMCInstPrinter(const Triple &triple,
                                              unsigned syntaxVariant,
                                              const MCAsmInfo &asmInfo,
                                              const MCInstrInfo &instrInfo,
                                              const MCRegisterInfo &regInfo) {
  if (syntaxVariant == 0)
    return new NVPTXInstPrinter(asmInfo, instrInfo, regInfo);
  return nullptr;
}

// Create an MCTargetStreamer that emits actual assembly directives
static MCTargetStreamer *createAsmTargetStreamer(MCStreamer &streamer,
                                                 formatted_raw_ostream &,
                                                 MCInstPrinter *,
                                                 bool) {
  return new NVPTXAsmTargetStreamer(streamer);
}

// Create a no-op MCTargetStreamer used when no assembly output is needed
static MCTargetStreamer *createEmptyTargetStreamer(MCStreamer &streamer) {
  return new NVPTXTargetStreamer(streamer);
}

// Force static initialization of NVPTX target components
extern "C" LLVM_EXTERNAL_VISIBILITY void LLVMInitializeNVPTXTargetMC() {
  Target *targets[] = { &getTheNVPTXTarget32(), &getTheNVPTXTarget64() };
  for (size_t idx = 0; idx < sizeof(targets)/sizeof(targets[0]); ++idx) {
    Target *t = targets[idx];

    // Register the assembly information class
    RegisterMCAsmInfo<NVPTXMCAsmInfo> asmInfoReg(*t);

    // Register instruction info factory
    TargetRegistry::RegisterMCInstrInfo(*t, buildNVPTXMCInstrInfo);

    // Register register info factory
    TargetRegistry::RegisterMCRegInfo(*t, buildNVPTXMCRegisterInfo);

    // Register subtarget info factory
    TargetRegistry::RegisterMCSubtargetInfo(*t, buildNVPTXMCSubtargetInfo);

    // Register instruction printer factory
    TargetRegistry::RegisterMCInstPrinter(*t, buildNVPTXMCInstPrinter);

    // Register assembler streamer factory
    TargetRegistry::RegisterAsmTargetStreamer(*t, createAsmTargetStreamer);

    // Register null streamer factory
    TargetRegistry::RegisterNullTargetStreamer(*t, createEmptyTargetStreamer);
  }
}

