std::atomic<bool> running(true);

// Function to detect Enter key press and signal termination
void handleUserExit() {
    while (running) {
        if (std::cin.get() == '\n') {
            running = false;
        }
    }
}

int main() {
    std::thread input_thread(handleUserExit);

    while (running) {
        Table sys_table;

        // Initialize random number generator
        std::random_device seed;
        std::mt19937 rng(seed());
        std::uniform_real_distribution<float> dist(0.0f, 100.0f);

        // Build table header
        sys_table.add_row(Row_t{"PID", "CPU%", "MEM%", "OWNER", "PRI"});

        // Generate dynamic rows with random values
        sys_table.add_row(Row_t{"4297", 
                                 std::to_string(static_cast<int>(std::round(dist(rng)))),
                                 std::to_string(static_cast<int>(std::round(dist(rng)))),
                                 "ubuntu", "20"});
        sys_table.add_row(Row_t{"12671", 
                                  std::to_string(static_cast<int>(std::round(dist(rng)))),
                                  std::to_string(static_cast<int>(std::round(dist(rng)))),
                                  "root", "0"});
        sys_table.add_row(Row_t{"810", 
                                  std::to_string(static_cast<int>(std::round(dist(rng)))),
                                  std::to_string(static_cast<int>(std::round(dist(rng)))),
                                  "root", "-20"});

        // Apply formatting
        sys_table.column(2).format().font_align(FontAlign::center);
        sys_table.column(3).format().font_align(FontAlign::right);
        sys_table.column(4).format().font_align(FontAlign::right);

        // Style header row
        for (size_t col_idx = 0; col_idx < 5; ++col_idx) {
            sys_table[0][col_idx]
                .format()
                .font_color(Color::yellow)
                .font_align(FontAlign::center)
                .font_style({FontStyle::bold});
        }

        std::cout << sys_table << std::endl;
        std::cout << "Press ENTER to terminate..." << std::endl;

        std::this_thread::sleep_for(std::chrono::seconds(1));

        // Move cursor up 10 lines to overwrite previous output
        std::cout << "\033[A\033[A\033[A\033[A\033[A"
                  << "\033[A\033[A\033[A\033[A\033[A";
    }

    // Restore cursor position after exit
    std::cout << "\033[B\033[B\033[B\033[B\033[B"
              << "\033[B\033[B\033[B\033[B\033[B";

    input_thread.join();
    return 0;
}

#include <vector>
#include <unordered_map>
#include <queue>

class Solution {
public:
    std::vector<int> findXSum(std::vector<int>& nums, int k, int x) 
    {
        int n = nums.size();
        std::vector<int> result;
        std::unordered_map<int, int> countMap;

        // Build frequency map for the first window of size k
        for (int idx = 0; idx < k; ++idx) {
            countMap[nums[idx]]++;
        }

        // Compute initial x-sum and add to result
        result.push_back(computeTopXProductSum(countMap, x));

        // Process remaining windows using sliding window technique
        for (int start = 1; start <= n - k; ++start) {
            // Remove leftmost element of previous window
            int outVal = nums[start - 1];
            countMap[outVal]--;
            if (countMap[outVal] == 0) {
                countMap.erase(outVal);
            }

            // Add rightmost element of current window
            int inVal = nums[start + k - 1];
            countMap[inVal]++;

            // Compute x-sum for current window and append to result
            result.push_back(computeTopXProductSum(countMap, x));
        }

        return result;
    }

private:
    int computeTopXProductSum(const std::unordered_map<int, int>& freqMap, int topCount) {
        // Use max heap to retrieve elements with highest frequencies
        std::priority_queue<std::pair<int, int>> maxHeap; // {frequency, value}

        for (const auto& item : freqMap) {
            maxHeap.emplace(item.second, item.first);
        }

        int total = 0;
        int processed = 0;

        while (!maxHeap.empty() && processed < topCount) {
            auto [freq, val] = maxHeap.top();
            maxHeap.pop();
            total += freq * val;
            ++processed;
        }

        return total;
    }
};

