#include "src/QuantumRegister.hpp"
#include <cassert>
#include <cmath>
#include <iostream>
#include <mpi.h>
#include <vector>

using qubit_engine::QuantumRegister;

// Helper function to compare complex numbers with tolerance
bool approximately_equal(std::complex<double> x, std::complex<double> y,
                         double epsilon = 1e-5) {
  return std::norm(x - y) < epsilon * epsilon;
}

int main(int argc, char **argv) {
  MPI_Init(&argc, &argv);

  int my_rank;
  MPI_Comm_rank(MPI_COMM_WORLD, &my_rank);

  int total_ranks;
  MPI_Comm_size(MPI_COMM_WORLD, &total_ranks);

  // Verify correct number of processes
  if (total_ranks != 2) {
    if (my_rank == 0) {
      std::cerr << "Error: This test requires exactly 2 MPI ranks."
                << std::endl;
    }
    MPI_Finalize();
    return 1;
  }

  const size_t num_qubits = 4;
  QuantumRegister register_state(num_qubits);

  // Initialize in |0000⟩ state
  // Rank 0 holds indices [0..7], Rank 1 holds [8..15]
  // Initially only index 0 (global) has amplitude 1.0

  // Step 1: Apply Hadamard gate on qubit 3 (most significant)
  if (my_rank == 0) {
    std::cout << "Applying H on qubit 3..." << std::endl;
  }
  register_state.applyHadamard(3);

  auto local_amplitudes = register_state.getStateVector();
  const double one_over_root_two = 1.0 / std::sqrt(2.0);

  if (my_rank == 0) {
    assert(approximately_equal(local_amplitudes[0], {one_over_root_two, 0.0}));
  } else {
    // In global indexing, local index 0 corresponds to global index 8 (|1000⟩)
    assert(approximately_equal(local_amplitudes[0], {one_over_root_two, 0.0}));
  }

  // Step 2: Apply CNOT with control=3, target=0
  if (my_rank == 0) {
    std::cout << "Applying CNOT(3, 0)..." << std::endl;
  }
  register_state.applyCNOT(3, 0);

  local_amplitudes = register_state.getStateVector();

  if (my_rank == 0) {
    // |0000⟩ remains unchanged under CNOT when control is 0
    if (approximately_equal(local_amplitudes[0], {one_over_root_two, 0.0})) {
      std::cout << "[Rank 0] |0000⟩ component verified." << std::endl;
    } else {
      std::cerr << "[Rank 0] FAILED: Expected |0000⟩ amplitude mismatch." << std::endl;
      MPI_Finalize();
      return 1;
    }
  } else {
    // After CNOT: |1000⟩ → |1001⟩
    // Local index 0 = global 8 (|1000⟩), local index 1 = global 9 (|1001⟩)
    if (approximately_equal(local_amplitudes[0], {0.0, 0.0}) &&
        approximately_equal(local_amplitudes[1], {one_over_root_two, 0.0})) {
      std::cout << "[Rank 1] |1001⟩ component verified." << std::endl;
    } else {
      std::cerr << "[Rank 1] FAILED: Amplitude distribution after CNOT incorrect." << std::endl;
      MPI_Finalize();
      return 1;
    }
  }

  MPI_Finalize();
  return 0;
}

