namespace g2o {

#ifdef _WINDOWS
#if defined(_MSC_VER) || defined(_MSC_EXTENSIONS)
  #define EPOCH_DIFFERENCE_MICROSECS  11644473600000000Ui64
#else
  #define EPOCH_DIFFERENCE_MICROSECS  11644473600000000ULL
#endif

struct timezone_offset {
  int minutes_west_of_greenwich;
  int dst_correction_type;
};

int get_current_time(struct timeval* time_val, struct timezone_offset* tz_info)
{
  FILETIME current_file_time;
  unsigned long long timestamp = 0;
  static bool timezone_initialized = false;

  if (time_val != nullptr) {
    GetSystemTimeAsFileTime(&current_file_time);

    timestamp |= static_cast<unsigned long long>(current_file_time.dwHighDateTime) << 32;
    timestamp |= static_cast<unsigned long long>(current_file_time.dwLowDateTime);

    // Convert from 100-nanosecond intervals to microseconds
    timestamp /= 10;

    // Adjust for Unix epoch offset
    timestamp -= EPOCH_DIFFERENCE_MICROSECS;

    time_val->tv_sec = static_cast<long>(timestamp / 1000000ULL);
    time_val->tv_usec = static_cast<long>(timestamp % 1000000ULL);
  }

  if (tz_info != nullptr) {
    if (!timezone_initialized) {
      _tzset();
      timezone_initialized = true;
    }

    long seconds_offset;
    int daylight_flag;
    _get_timezone(&seconds_offset);
    _get_daylight(&daylight_flag);

    tz_info->minutes_west_of_greenwich = static_cast<int>(seconds_offset / 60);
    tz_info->dst_correction_type = daylight_flag;
  }

  return 0;
}
#endif

ScopeTime::ScopeTime(const char* title) : _title(title), _startTime(get_monotonic_time()) {}

ScopeTime::~ScopeTime() {
  double elapsed = get_monotonic_time() - _startTime;
  std::cerr << _title << " took " << (elapsed * 1000.0) << "ms.\n";
}

double get_monotonic_time()
{
#if (defined(_POSIX_TIMERS) && (_POSIX_TIMERS+0 >= 0) && defined(_POSIX_MONOTONIC_CLOCK))
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return static_cast<double>(ts.tv_sec) + static_cast<double>(ts.tv_nsec) * 1e-9;
#else
  return get_wall_clock_time();
#endif
}

