// Logger constructor: builds formatted message string
Logger::Logger(char const* srcFile, char const* funcName, int lineNumber,
    std::string const& text)
{
    std::ostringstream oss;
    oss << "File: " << srcFile << "\n"
        << "Func: " << funcName << "\n";

