    oss << text << "\n\n";
    mMessage = oss.str();
}

// Dispatch assertion messages to registered listeners
void Logger::Assertion()
{
    msMutex.lock();
    for (auto&& lstnr : msListeners)
    {
        if ((lstnr->GetFlags() & Listener::LISTEN_FOR_ASSERTION) != 0)
        {
            lstnr->Assertion(mMessage);
        }
    }
    msMutex.unlock();
}

// Dispatch error messages to registered listeners
void Logger::Error()
{
    msMutex.lock();
    for (auto&& lstnr : msListeners)
    {
        if ((lstnr->GetFlags() & Listener::LISTEN_FOR_ERROR) != 0)
        {
            lstnr->Error(mMessage);
        }
    }
    msMutex.unlock();
}

// Dispatch warning messages to registered listeners
void Logger::Warning()
{
    msMutex.lock();
    for (auto&& lstnr : msListeners)
    {
        if ((lstnr->GetFlags() & Listener::LISTEN_FOR_WARNING) != 0)
        {
            lstnr->Warning(mMessage);
        }
    }
    msMutex.unlock();
}

// Dispatch informational messages to registered listeners
void Logger::Information()
{
    msMutex.lock();
    for (auto&& lstnr : msListeners)
    {
        if ((lstnr->GetFlags() & Listener::LISTEN_FOR_INFORMATION) != 0)
        {
            lstnr->Information(mMessage);
        }
    }
    msMutex.unlock();
}

// Add a listener to the global list
void Logger::Subscribe(Listener* lstnr)
{
    msMutex.lock();
    msListeners.insert(lstnr);
    msMutex.unlock();
}

// Remove a listener from the global list
void Logger::Unsubscribe(Listener* lstnr)
{
    msMutex.lock();
    msListeners.erase(lstnr);
    msMutex.unlock();
}

