#include <iostream>
#include <vector>
#include <string>

void send_automaton(int state_count, const std::vector<int>& zero_transitions, const std::vector<int>& one_transitions) {
    std::cout << 1 << "\n";
    std::cout << state_count << "\n";

    for (int idx = 0; idx < state_count; ++idx) {
        std::cout << zero_transitions[idx];
        if (idx < state_count - 1) std::cout << " ";
    }
    std::cout << "\n";

    for (int idx = 0; idx < state_count; ++idx) {
        std::cout << one_transitions[idx];
        if (idx < state_count - 1) std::cout << " ";
    }
    std::cout << "\n";
    std::cout.flush();
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int length;
    std::cin >> length;

    std::string result_string(length, '0');

    // Determine each character sequentially
    for (int position = 0; position < length; ++position) {
        // Create automaton with position+2 states
        int num_states = position + 2;

        std::vector<int> next_on_zero(num_states);
        std::vector<int> next_on_one(num_states);

        // Build chain: state i -> state i+1 for first 'position' transitions
        for (int state = 0; state < position; ++state) {
            next_on_zero[state] = state + 1;
            next_on_one[state] = state + 1;
        }

        // Decision point: state 'position' branches based on input bit
        next_on_zero[position] = position;      // stay in decision state for '0'
        next_on_one[position] = position + 1;   // move to accept state for '1'

        // Sink states remain fixed once reached
        if (position + 1 < num_states) {
            next_on_zero[position + 1] = position + 1;
            next_on_one[position + 1] = position + 1;
        }

        // Query the automaton behavior
        send_automaton(num_states, next_on_zero, next_on_one);

        int response;
        std::cin >> response;

        // Interpret response to set the character
        result_string[position] = (response == position) ? '0' : '1';
    }

    // Output final result
    std::cout << 0 << "\n" << result_string << "\n";
    std::cout.flush();

    return 0;
}

