#include "network/Protocol.hpp"
#include "network/ProtocolCommands.hpp"
#include "common/Log.hpp"

Protocol::Protocol()
{
}

Error Protocol::init()
{
    // Reset all pending command entries
    for (uint8_t idx = 0; idx < PROTOCOL_MAX_PENDING_COMMANDS; ++idx) {
        pending_commands[idx].id = 0;
        pending_commands[idx].callback = nullptr;
    }
    return Error::None;
}

Error Protocol::deinit()
{
    return Error::None;
}

Error Protocol::handleRequest(const Request& req, HandleResponseCallback callback)
{
    if (!callback)
    {
        Log::Add(Log::Level::Error, TAG, "Invalid callback provided for request ID %d", req.id);
        return Error::InvalidParameters;
    }

    // Locate an available slot in the pending commands array
    uint8_t slot_index = PROTOCOL_MAX_PENDING_COMMANDS;
    for (uint8_t i = 0; i < PROTOCOL_MAX_PENDING_COMMANDS; ++i) {
        if (pending_commands[i].callback == nullptr) {
            slot_index = i;
            break;
        }
    }

    if (slot_index == PROTOCOL_MAX_PENDING_COMMANDS)
    {
        Log::Add(Log::Level::Error, TAG, "No free slot available for pending command ID %d", req.id);
        return Error::NoMemory;
    }

    // Assign the request to the found slot
    pending_commands[slot_index].id = req.id;
    pending_commands[slot_index].callback = callback;

    // Search for a matching handler among registered handlers
    CommandHandler* handler_ptr = nullptr;
    for (auto& h : handlers)
    {
        if (h.cmd == req.cmd)
        {
            handler_ptr = &h;
            break;
        }
    }

    if (handler_ptr == nullptr)
    {
        Log::Add(Log::Level::Error, TAG, "No handler found for command 0x%02X", req.cmd);
        return Error::NotFound;
    }

    // Validate payload length against expected size
    if (handler_ptr->len != req.len)
    {
        Log::Add(Log::Level::Error, TAG, "Invalid payload length for command 0x%02X: expected %d, got %d", req.cmd, handler_ptr->len, req.len);
        return Error::InvalidParameters;
    }

    // Execute the handler with a wrapper callback that forwards responses to resolveCommand
    handler_ptr->callback(req, [this](const Response& res) {
        this->resolveCommand(res);
    });

    return Error::None;
}

Error Protocol::resolveCommand(const Response& res)
{
    // Locate the pending command by matching ID
    for (uint8_t i = 0; i < PROTOCOL_MAX_PENDING_COMMANDS; ++i) {
        if (pending_commands[i].id == res.id) {
            // Invoke the stored callback if present
            if (pending_commands[i].callback) {
                pending_commands[i].callback(res);
            } else {
                Log::Add(Log::Level::Error, TAG, "No callback found for pending command ID %d", res.id);
                return Error::InvalidState;
            }

            // Clear the slot after handling
            pending_commands[i].id = 0;
            pending_commands[i].callback = nullptr;
            return Error::None;
        }
    }

    // No matching pending command was found
    return Error::NotFound;
}

#include <iostream>
#include <vector>
#include <string>
#include <set>
#include <algorithm>

void process_case() {
    int total_words;
    std::cin >> total_words;

    if (total_words == 0) {
        std::cout << "answer" << std::endl;
        std::cout.flush();
        return;
    }

    std::vector<std::string> starting_chars;
    std::set<std::string> discovered;

    // Check each letter from 'a' to 'z'
    for (char letter = 'a'; letter <= 'z'; ++letter) {
        std::string test_prefix(1, letter);
        std::cout << "query " << test_prefix << " " << 1 << std::endl;
        std::cout.flush();

        int count;
        std::cin >> count;

        if (count > 0) {
            starting_chars.push_back(test_prefix);
            std::string word;
            std::cin >> word;
            discovered.insert(word);
        }
    }

    // Sort prefixes in reverse order (z to a)
    std::sort(starting_chars.begin(), starting_chars.end(), 
              [](const std::string& a, const std::string& b) { return a > b; });

    int remaining = total_words;

    // Process each prefix
    for (size_t idx = 0; idx < starting_chars.size(); ++idx) {
        const std::string& current_prefix = starting_chars[idx];

        // Count how many already-discovered words match this prefix
        int matched_count = 0;
        for (const auto& existing_word : discovered) {
            if (existing_word.find(current_prefix) == 0) {
                matched_count++;
            }
        }

        // Calculate how many more words we expect for this prefix
        int expected_new = remaining - (discovered.size() - matched_count);

        // Adjust for last prefix case
        if (idx == starting_chars.size() - 1) {
            expected_new = total_words - discovered.size() + matched_count;
        }

        if (expected_new <= 0) continue;

        std::cout << "query " << current_prefix << " " << expected_new << std::endl;
        std::cout.flush();

        int actual_count;
        std::cin >> actual_count;

        for (int i = 0; i < actual_count; ++i) {
            std::string new_word;
            std::cin >> new_word;
            discovered.insert(new_word);
        }
    }

    std::cout << "answer";
    for (const auto& word : discovered) {
        std::cout << " " << word;
    }
    std::cout << std::endl;
    std::cout.flush();
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    while (test_cases-- > 0) {
        process_case();
    }

    return 0;
}

