using asio::local::stream_protocol;

// Session class handles communication with a connected client
class session
  : public std::enable_shared_from_this<session>
{
public:
  explicit session(stream_protocol::socket sock)
    : socket_(std::move(sock))
  {
  }

  void initiate()
  {
    begin_read();
  }

private:
  void begin_read()
  {
    auto self(shared_from_this());
    socket_.async_read_some(asio::buffer(buffer_),
        [this, self](std::error_code error_code, std::size_t bytes_transferred)
        {
          if (!error_code)
            start_write(bytes_transferred);
        });
  }

  void start_write(std::size_t size)
  {
    auto self(shared_from_this());
    asio::async_write(socket_,
        asio::buffer(buffer_, size),
        [this, self](std::error_code error_code, std::size_t /*bytes_written*/)
        {
          if (!error_code)
            begin_read();
        });
  }

  // Socket for client communication
  stream_protocol::socket socket_;
  // Data buffer for incoming/outgoing messages
  std::array<char, 1024> buffer_;
};

// Server class manages incoming connections
class server
{
public:
  server(asio::io_context& context, const std::string& path)
    : acceptor_(context, stream_protocol::endpoint(path))
  {
    await_connection();
  }

private:
  void await_connection()
  {
    acceptor_.async_accept(
        [this](std::error_code error_code, stream_protocol::socket client_socket)
        {
          if (!error_code)
          {
            std::make_shared<session>(std::move(client_socket))->initiate();
          }
          await_connection();
        });
  }

  stream_protocol::acceptor acceptor_;
};

int main(int argument_count, char* arguments[])
{
  try
  {
    if (argument_count != 2)
    {
      std::cerr << "Usage: stream_server <socket_file>\n";
      std::cerr << "*** WARNING: existing file will be deleted ***\n";
      return 1;
    }

    asio::io_context service;
    std::remove(arguments[1]);
    server instance(service, arguments[1]);
    service.run();
  }
  catch (const std::exception& exception)
  {
    std::cerr << "Error: " << exception.what() << "\n";
  }

  return 0;
}
