#include <iostream>
#include <unordered_map>
#include <nlohmann/json.hpp>

using json = nlohmann::json;

int main() {
    // Initialize a JSON object containing various data types
    json data_object = {
        {"flag", true},
        {
            "numeric_data", {
                {"whole_number", 42},
                {"decimal_value", 17.23f}
            }
        },
        {"text", "Hello, world!"},
        {"sequence", {1, 2, 3, 4, 5}},
        {"empty_value", nullptr}
    };

    // Declare variables for type conversion
    bool boolean_result;
    int integer_result_1;
    short short_result;
    float float_result;
    int integer_result_2;
    std::string string_result;
    std::vector<short> vector_result;
    std::unordered_map<std::string, json> map_result;

    // Perform explicit value extraction using get_to()
    data_object["flag"].get_to(boolean_result);
    data_object["numeric_data"]["whole_number"].get_to(integer_result_1);
    data_object["numeric_data"]["whole_number"].get_to(short_result);
    data_object["numeric_data"]["decimal_value"].get_to(float_result);
    data_object["numeric_data"]["decimal_value"].get_to(integer_result_2);
    data_object["text"].get_to(string_result);
    data_object["sequence"].get_to(vector_result);
    data_object.get_to(map_result);

    // Output the extracted values
    std::cout << boolean_result << '\n';
    std::cout << integer_result_1 << ' ' << short_result << '\n';
    std::cout << float_result << ' ' << integer_result_2 << '\n';
    std::cout << string_result << '\n';

    for (const auto& item : vector_result) {
        std::cout << item << ' ';
    }
    std::cout << "\n\n";

    for (const auto& [key, value] : map_result) {
        std::cout << key << ": " << value << '\n';
    }

    return 0;
}

#include <sol/sol.hpp>
