// Wrapper function to execute Lua script using sol2
int execute_lua_print(lua_State* raw_lua_state) {
    sol::state_view lua_view(raw_lua_state);
    lua_view.script("print('bark bark bark!')");
    return 0;
}

int main(int, char*[]) {
    std::cout << "=== initializing sol::state_view with raw Lua state ==="
              << std::endl;

    // Create new Lua state and load libraries
    lua_State* L = luaL_newstate();
    luaL_openlibs(L);

    // Register our C++ function as a Lua callable
    lua_pushcclosure(L, &execute_lua_print, 0);
    lua_setglobal(L, "use_sol2");

    // Execute the Lua call to our registered function
    if (luaL_dostring(L, "use_sol2()")) {
        lua_error(L);
        return -1;
    }

    std::cout << std::endl;
    return 0;
}

#include <ocs2_switched_model_interface/constraint/EndEffectorVelocityConstraint.h>
#include <iostream>

int main(int argc, char** argv) {
  // Define type alias for the end-effector velocity constraint
  using EeVelConstraint = switched_model::EndEffectorVelocityConstraint<3, 2>;

  // Configure constraint with default settings
  switched_model::EndEffectorVelocityConstraintSettings cfg;
  EeVelConstraint eeVelConstraint(cfg);

  // Prepare evaluation point: (time, state, input)
  EeVelConstraint::scalar_t t = 0.0;
  EeVelConstraint::state_vector_t x;
  EeVelConstraint::input_vector_t u;

  x.setConstant(1.0);   // Initialize state vector with ones
  u.setConstant(1.0);   // Initialize input vector with ones

  // Set desired end-effector velocity to 1.5 in all components
  cfg.desiredEndEffectorVelocity.setConstant(1.5);

  // Evaluate constraint value and its first-order approximation
  auto value = eeVelConstraint.getValue(t, x, u);
  auto approx = eeVelConstraint.getLinearApproximation(t, x, u);

  // Output constraint residuals
  std::cout << "Constraint values:" << std::endl;
  for (const auto& val : value) {
    std::cout << val << std::endl;
  }

  // Output partial derivatives w.r.t. state
  std::cout << "State Jacobian rows:" << std::endl;
  for (const auto& dcdx_row : approx.derivativeState) {
    std::cout << dcdx_row.transpose() << std::endl;
  }

  // Output partial derivatives w.r.t. input
  std::cout << "Input Jacobian rows:" << std::endl;
  for (const auto& dcdu_row : approx.derivativeInput) {
    std::cout << dcdu_row.transpose() << std::endl;
  }

  return 0;
}

