namespace quadrants::lang {

// This optimization removes immutable local variables by propagating their values.
// After the GatherImmutableLocalVars pass, each immutable local var has exactly one store.
// We replace all subsequent loads with the stored value and remove the redundant allocations,
// stores, and loads.
class ImmutableVarEliminator : public BasicStmtVisitor {
 private:
  using BasicStmtVisitor::visit;

  // Set of statements representing immutable local variables
  std::unordered_set<Stmt *> immutable_vars_;

  // Maps each immutable variable to its constant value (from the single store)
  std::unordered_map<Stmt *, Stmt *> var_to_value_map_;

  ImmediateIRModifier ir_modifier_;
  DelayedIRModifier cleanup_modifier_;

 public:
  ImmutableVarEliminator(
      const std::unordered_set<Stmt *> &immutable_vars,
      IRNode *root)
      : immutable_vars_(immutable_vars), 
        ir_modifier_(root) {
  }

  void visit(AllocaStmt *stmt) override {
    if (immutable_vars_.count(stmt)) {
      cleanup_modifier_.remove(stmt);
    }
  }

  void visit(LocalLoadStmt *stmt) override {
    auto it = immutable_vars_.find(stmt->src);
    if (it != immutable_vars_.end()) {
      Stmt *replacement = var_to_value_map_[stmt->src];
      ir_modifier_.substitute(stmt, replacement);
      cleanup_modifier_.remove(stmt);
    }
  }

  void visit(LocalStoreStmt *stmt) override {
    if (immutable_vars_.count(stmt->dest)) {
      QD_ASSERT(var_to_value_map_.find(stmt->dest) == var_to_value_map_.end());
      var_to_value_map_[stmt->dest] = stmt->val;
      cleanup_modifier_.remove(stmt);
    }
  }

  static void apply(IRNode *root) {
    ImmutableVarEliminator optimizer(
        irpass::analysis::collect_immutable_local_vars(root), root);
    root->accept(&optimizer);
    optimizer.cleanup_modifier_.update_ir();
  }
};

namespace irpass {

void eliminate_immutable_local_vars(IRNode *root) {
  QD_AUTO_PROF;
  ImmutableVarEliminator::apply(root);
}

}  // namespace irpass
}  // namespace quadrants::lang

#include <doctest/extensions/doctest_mpi.h>

// Helper function that returns different values based on MPI rank
int compute_value_for_rank(int rank) {
  if (rank == 0) {
    return 10;
  }
  else if (rank == 1) {
    return 11;
  }
  return 0;
}

MPI_TEST_CASE("Parallel test on 2 processes", 2) {
  // Accessible variables: test_comm, test_rank, test_nb_procs
  int result = compute_value_for_rank(test_rank);
  MPI_CHECK(0, result == 10);   // Verify rank 0 has value 10
  MPI_CHECK(1, result == 11);   // Verify rank 1 has value 11
}

MPI_TEST_CASE("Parallel test on 3 processes (expected to fail)", 3) {
  int local_result = compute_value_for_rank(test_rank);
  MPI_CHECK(0, local_result == 10);  // Rank 0 check passes
  MPI_CHECK(1, local_result == 11);  // Rank 1 check passes
  MPI_CHECK(2, local_result == -1);  // Rank 2 check fails (returns 0 instead of -1)
}

